INSERT INTO `ai_resource` VALUES (1,'2026-10-26 11:21:50','2026-10-26 11:21:50','academic-anthropologist','agentspec','文化体系、仪式、亲属关系、信仰系统和民族志方法专家——构建有生活气息而非凭空捏造的、文化上连贯自洽的社会','enable','public','[\"academic\"]',NULL,'github.com/jnMetaCode/agency-agents-zh','{\"onlineCnt\":1,\"labels\":{\"latest\":\"0.0.1\"}}',1,'PUBLIC','nacos',0),(2,'2026-10-26 11:21:50','2026-10-26 11:21:50','academic-narratologist','agentspec','叙事理论、故事结构、人物弧线和文学分析专家——基于从普罗普到坎贝尔再到现代叙事学的成熟框架提供建议','enable','public','[\"academic\"]',NULL,'github.com/jnMetaCode/agency-agents-zh','{\"onlineCnt\":1,\"labels\":{\"latest\":\"0.0.1\"}}',1,'PUBLIC','nacos',0),(3,'2026-10-26 11:21:50','2026-10-26 11:21:50','academic-historian','agentspec','历史分析、分期、物质文化和史学方法专家——验证历史一致性，以扎根于一手和二手资料的真实时代细节丰富设定','enable','public','[\"academic\"]',NULL,'github.com/jnMetaCode/agency-agents-zh','{\"onlineCnt\":1,\"labels\":{\"latest\":\"0.0.1\"}}',1,'PUBLIC','nacos',0),(4,'2026-10-26 11:21:50','2026-10-26 11:21:50','academic-geographer','agentspec','自然地理与人文地理、气候系统、制图学和空间分析专家——构建地理上连贯自洽的世界，使地形、气候、资源和聚落模式在科学上合理','enable','public','[\"academic\"]',NULL,'github.com/jnMetaCode/agency-agents-zh','{\"onlineCnt\":1,\"labels\":{\"latest\":\"0.0.1\"}}',1,'PUBLIC','nacos',0),(5,'2026-10-26 11:21:50','2026-10-26 11:21:50','nacos-skill-registry','skill','Helps users discover and install AI skills from a team\'s Nacos server when they ask questions like \"how do I do X\", \"I want to X\", \"help me with X\", \"find a skill for X\", \"is there a skill that can...\", or express interest in extending capabilities. This skill should be used when the user is looking for functionality that might exist as an installable skill in Nacos. Also supports uploading and publishing skills for team sharing.','enable','public',NULL,NULL,'github.com/alibaba/nacos','{\"onlineCnt\":1,\"labels\":{\"latest\":\"0.0.1\"}}',1,'PUBLIC','-',0),(6,'2026-10-26 11:21:50','2026-10-26 11:21:50','brand-guidelines','skill','Applies Anthropic\'s official brand colors and typography 