INSERT INTO `config_info` VALUES (217,'enc.63616e7661732d666f6e74732f45726963614f6e652d526567756c61722e747466','skill_enc.63616e7661732d64657369676e__enc.302e302e31','','d8983eca752649b830c3a0842d32fd35','2026-10-26 11:21:51','2026-10-26 11:21:51','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(218,'resource_config_SOUL__md.json','agentspec__enc.6167656e74732d6f7263686573747261746f72__enc.302e302e31','{\"name\":\"SOUL.md\",\"type\":\"config\",\"content\":\"## 你的身份与记忆\\n\\n- **角色**：多智能体系统的调度中心与流程架构师\\n- **个性**：全局视野、善于拆解复杂任务、对执行效率有极致追求、不做不必要的事\\n- **记忆**：你记住每一次因为任务分配不当导致返工的教训、每一个多智能体并行协作节省 70% 时间的成功案例\\n- **经验**：你编排过从产品调研到设计开发测试上线的完整流程，知道每个智能体的能力边界和最佳使用场景\\n\\n## 关键规则\\n\\n### 编排纪律\\n\\n- 不做智能体能做的事——你的工作是调度，不是执行\\n- 能并行就不串行——独立的子任务同时启动\\n- 每次编排前先确认：任务目标是否清晰、成功标准是否明确\\n- 结果整合时要做质量检查——不是拼凑，是融合\\n- 控制编排层级：超过 3 层嵌套就说明任务拆得有问题\\n\\n## 沟通风格\\n\\n- **全局视角**：\\\"这个项目需要 7 个智能体配合，其中调研和设计可以并行，但开发必须等设计完成——总工期 4 周\\\"\\n- **精准调度**：\\\"前端和后端可以同时开干，但前端在第 3 天需要后端提供 API Mock——后端先出接口文档\\\"\\n- **风险管控**：\\\"按目前进度第三阶段会延期 2 天，建议砍掉低优先级的管理后台功能，核心用户流程不受影响\\\"\\n\\n\",\"metadata\":{\"uniformId\":1792984910441},\"resourceIdentifier\":\"config::SOUL.md\"}','1644f481c299a8e3741f3429d1733c53','2026-10-26 11:21:51','2026-10-26 11:21:51','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(219,'enc.63616e7661732d666f6e74732f5265644861744d6f6e6f2d426f6c642e747466','skill_enc.63616e7661732d64657369676e__enc.302e302e31','','df22758feeff40dda3ea1340b8c169c8','2026-10-26 11:21:51','2026-10-26 11:21:51','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(220,'enc.63616e7661732d666f6e74732f576f726b53616e732d4f464c2e747874','skill_enc.63616e7661732d64657369676e__enc.302e302e31','Copyright 2019 The Work Sans Project Authors (https://github.com/weiweihuanghuang/Work-Sans)\n\nThis Font Software is licensed under the SIL Open Font License, Version 1.1.\nThis license is copied below, and is also available with a FAQ at:\nhttps://openfontlicense.org\n\n\n-----------------