mmentsEx xmlns:wpc=\"http://schemas.microsoft.com/office/word/2010/wordprocessingCanvas\" xmlns:cx=\"http://schemas.microsoft.com/office/drawing/2014/chartex\" xmlns:cx1=\"http://schemas.microsoft.com/office/drawing/2015/9/8/chartex\" xmlns:cx2=\"http://schemas.microsoft.com/office/drawing/2015/10/21/chartex\" xmlns:cx3=\"http://schemas.microsoft.com/office/drawing/2016/5/9/chartex\" xmlns:cx4=\"http://schemas.microsoft.com/office/drawing/2016/5/10/chartex\" xmlns:cx5=\"http://schemas.microsoft.com/office/drawing/2016/5/11/chartex\" xmlns:cx6=\"http://schemas.microsoft.com/office/drawing/2016/5/12/chartex\" xmlns:cx7=\"http://schemas.microsoft.com/office/drawing/2016/5/13/chartex\" xmlns:cx8=\"http://schemas.microsoft.com/office/drawing/2016/5/14/chartex\" xmlns:mc=\"http://schemas.openxmlformats.org/markup-compatibility/2006\" xmlns:aink=\"http://schemas.microsoft.com/office/drawing/2016/ink\" xmlns:am3d=\"http://schemas.microsoft.com/office/drawing/2017/model3d\" xmlns:o=\"urn:schemas-microsoft-com:office:office\" xmlns:oel=\"http://schemas.microsoft.com/office/2019/extlst\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\" xmlns:m=\"http://schemas.openxmlformats.org/officeDocument/2006/math\" xmlns:v=\"urn:schemas-microsoft-com:vml\" xmlns:wp14=\"http://schemas.microsoft.com/office/word/2010/wordprocessingDrawing\" xmlns:wp=\"http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing\" xmlns:w10=\"urn:schemas-microsoft-com:office:word\" xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\" xmlns:w14=\"http://schemas.microsoft.com/office/word/2010/wordml\" xmlns:w15=\"http://schemas.microsoft.com/office/word/2012/wordml\" xmlns:w16cex=\"http://schemas.microsoft.com/office/word/2018/wordml/cex\" xmlns:w16cid=\"http://schemas.microsoft.com/office/word/2016/wordml/cid\" xmlns:w16=\"http://schemas.microsoft.com/office/word/2018/wordml\" xmlns:w16du=\"http://schemas.microsoft.com/office/word/2023/wordml/word16du\" xmlns:w16sdtdh=\"http://schemas.microsoft.com/office/word/2020/wordml/sdtdatahash\" xmlns:w16sdtfl=\"http://schemas.microsoft.com/office/word/2024/wordml/sdtformatlock\" xmlns:w16se=\"http://schemas.microsoft.com/office/word/2015/wordml/symex\" xmlns:wpg=\"http://schemas.microsoft.com/office/word/2010/wordprocessingGroup\" xmlns:wpi=\"http://schemas.microsoft.com/office/word/2010/wordprocessingInk\" xmlns:wne=\"http://schemas.microsoft.com/office/word/2006/wordml\" xmlns:wps=\"http://schemas.microsoft.com/office/word/2010/wordprocessingShape\" mc:Ignorable=\"w14 w15 w16se w16cid w16 w16cex w16sdtdh w16sdtfl w16du wp14\">\n</w15:commentsEx>\n','39bd651f7662a0092852156135a7d0ae','2026-10-26 11:21:55','2026-10-26 11:21:55','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'xml',NULL,''),(557,'resource_config_SOUL__md.json','agentspec__enc.64657369676e2d75782d72657365617263686572__enc.302e302e31','{\"name\":\"SOUL.md\",\"type\":\"config\",\"content\":\"## 你的身份与记忆\\n\\n- **角色**：用户研究员与可用性测试专家\\n- **个性**：好奇心强、善于倾听、对\\\"我觉得用户会喜欢\\\"这种话过敏、数据和故事两手抓\\n- **记忆**：你记住每一次用户访谈中的意外发现、每一个可用性测试暴露的致命问题、每一次数据推翻团队假设的时刻\\n- **经验**：你做过面对面访谈、远程测试、问卷调查、日记研究，知道每种方法的适用场景和局限性\\n\\n## 关键规则\\n\\n### 研究伦理\\n\\n- 用户隐私至上：知情同意、数据脱敏、匿名化\\n- 不诱导：问题措辞中立，不暗示\\\"正确答案\\\"\\n- 样本多样性：不只测自己圈子里的人\\n- 结论要诚实：数据不支持的就不说，不为了迎合领导编故事\\n- 研究发现必须附上方法论说明，让读者自行判断可信度\\n\\n## 沟通风格\\n\\n- **用证据说话**：\\\"不是我觉得这个设计有问题——8 个测试用户里有 6 个卡在了这一步，平均耗时是预期的 3 倍\\\"\\n- **翻译用户声音**：\\\"用户嘴上说\'界面挺好的\'，但实际操作时犹豫了 15 秒才找到下一步按钮\\\"\\n- **可执行建议**：\\\"与其全部重设计，建议先把这个按钮从灰色改成蓝色试一周，看点击率变化\\\"\\n\\n\",\"metadata\":{\"uniformId\":1792984914457},\"resourceIdentifier\":\"config::SOUL.md\"}','e07127134c241c7c71243fec7db80f7f','2026-10-26 11:21:55','2026-10-26 11:21:55','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(558,'manifest.json','agentspec__enc.64657369676e2d76697375616c2d73746f727974656c6c6572__enc.302e302e31','{\"name\":\"design-visual-storyteller\",\"description\":\"视觉传达专家，擅长把复杂信息转化成有吸引力的视觉故事，通过多媒体内容和品牌叙事打动受众。\",\"content\":\"{\\n  \\\"version\\\": \\\"1.0\\\",\\n  \\\"source\\\": {\\n    \\\"repository\\\": \\\"https://github.com/jnMetaCode/agency-agents-zh\\\",\\n    \\\"commit\\\": \\\"23c2746913fe46260450517fa5afb58afc61fed7\\\",\\n    \\\"original_path\\\": \\\"design/design-visual-storyteller.md\\\",\\n    \\\"openclaw_mode\\\": true\\n  },\\n  \\\"description\\\": \\\"视觉传达专家，擅长把复杂信息转化成有吸引力的视觉故事，通过多媒体内容和品牌叙事打动受众。\\\",\\n  \\\"tags\\\": [\\n    \\\"design\\\"\\n  ],\\n  \\\"worker\\\": {\\n    \\\"suggested_name\\\": \\\"design-visual-storyteller\\\",\\n    \\\"base_image\\\": \\\"hiclaw/worker-agent:latest\\\",\\n    \\\"apt_packages\\\": [],\\n    \\\"pip_packages\\\": [],\\n    \\\"npm_packages\\\": []\\n  },\\n  \\\"proxy\\\": {\\n    \\\"suggested\\\": false,\\n    \\\"reason\\\": \\\"\\\"\\n  }\\n}\\n\",\"uniformId\":1792984914794,\"resources\":[{\"name\":\"jobs.json\",\"type\":\"crons\"},{\"name\":\"IDENTITY.md\",\"type\":\"config\"},{\"name\":\"tool-analysis.json\",\"type\":\"tool-analysis\"},{\"name\":\"AGENTS.md\",\"type\":\"config\"},{\"name\":\"SOUL.md\",\"type\":\"config\"},{\"name\":\"MEMORY.md\",\"type\":\"config\"}]}','bf5a838dc83de47c3eac954349ccd4c2','2026-10-26 11:21:55','2026-10-26 11:21:55','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(559,'enc.736372697074732f74656d706c617465732f636f6d6d656e7473457874656e6465642e786d6c','skill_enc.646f6378__enc.302e302e31','<?xml version=\"1.0\" ?>\n<w15:commentsEx xmlns:wpc=\"http://schemas.microsoft.com/office/word/2010/wordprocessingCanvas\" xmlns:cx=\"http://schemas.microsoft.com/office/drawing/2014/chartex\" xmlns:cx1=\"http://schemas.microsoft.com/office/drawing/2015/9/8/chartex\" xmlns:cx2=\"http://schemas.microsoft.com/office/drawing/2015/10/21/chartex\" xmlns:cx3=\"http://schemas.microsoft.com/office/drawing/2016/5/9/chartex\" xmlns:cx4=\"http://schemas.microsoft.com/office/drawing/2016/5/10/chartex\" xmlns:cx5=\"http://schemas.microsoft.com/office/drawing/2016/5/11/chartex\" xmlns:cx6=\"http://schemas.microsoft.com/office/drawing/2016/5/12/chartex\" xmlns:cx7=\"http://schemas.microsoft.com/office/drawing/2016/5/13/chartex\" xmlns:cx8=\"http://schemas.microsoft.com/office/drawing/2016/5/14/chartex\" xmlns:mc=\"http://schemas.openxmlformats.org/markup-compatibility/2006\" xmlns:aink=\"http://schemas.microsoft.com/office/drawing/2016/ink\" xmlns:am3d=\"http://schemas.microsoft.com/office/drawing/2017/model3d\" xmlns:o=\"urn:schemas-microsoft-com:office:office\" xmlns:oel=\"http://schemas.microsoft.com/office/2019/extlst\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\" xmlns:m=\"http://schemas.openxmlformats.org/officeDocument/2006/math\" xmlns:v=\"urn:schemas-microsoft-com:vml\" xmlns:wp14=\"http://schemas.microsoft.com/office/word/2010/wordprocessingDrawing\" xmlns:wp=\"http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing\" xmlns:w10=\"urn:schemas-microsoft-com:office:word\" xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\" xmlns:w14=\"http://schemas.microsoft.com/office/word/2010/wordml\" xmlns:w15=\"http://schemas.microsoft.com/office/word/2012/wordml\" xmlns:w16cex=\"http://schemas.microsoft.com/office/word/2018/wordml/cex\" xmlns:w16cid=\"http://schemas.microsoft.com/office/word/2016/wordml/cid\" xmlns:w16=\"http://schemas.microsoft.com/office/word/2018/wordml\" xmlns:w16du=\"http://schemas.microsoft.com/office/word/2023/wordml/word16du\" xmlns:w16sdtdh=\"http://schemas.microsoft.com/office/word/2020/wordml/sdtdatahash\" xmlns:w16sdtfl=\"http://schemas.microsoft.com/office/word/2024/wordml/sdtformatlock\" xmlns:w16se=\"http://schemas.microsoft.com/office/word/2015/wordml/symex\" xmlns:wpg=\"http://schemas.microsoft.com/office/word/2010/wordprocessingGroup\" xmlns:wpi=\"http://schemas.microsoft.com/office/word/2010/wordprocessingInk\" xmlns:wne=\"http://schemas.microsoft.com/office/word/2006/wordml\" xmlns:wps=\"http://schemas.microsoft.com/office/word/2010/wordprocessingShape\" mc:Ignorable=\"w14 w15 w16se w16cid w16 w16cex w16sdtdh w16sdtfl w16du wp14\">\n</w15:commentsEx>\n','39bd651f7662a0092852156135a7d0ae','2026-10-26 11:21:55','2026-10-26 11:21:55','nacos',NULL,'','public',NULL,NULL,NULL,'xml',NULL,''),(560,'resource_config_IDENTITY__md.json','agentspec__enc.64657369676e2d76697375616c2d73746f727974656c6c6572__enc.302e302e31','{\"name\":\"IDENTITY.md\",\"type\":\"config\",\"content\":\"# 视觉叙事师\\n视觉传达专家，擅长把复杂信息转化成有吸引力的视觉故事，通过多媒体内容和品牌叙事打动受众。\\n\",\"metadata\":{\"uniformId\":1792984914794},\"resourceIdentifier\":\"config::IDENTITY.md\"}','f95d3174061a469f5021c89a48fcf3ea','2026-10-26 11:21:55','2026-10-26 11:21:55','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(561,'resource_config_MEMORY__md.json','agentspec__enc.64657369676e2d75782d72657365617263686572__enc.302e302e31','{\"name\":\"MEMORY.md\",\"type\":\"config\",\"content\":\"# 长期记忆\\n\\n由运行时写入；本模板未预置业务记忆。\\n\",\"metadata\":{\"uniformId\":1792984914457},\"resourceIdentifier\":\"config::MEMORY.md\"}','27efa00036e65fb2f0e1a03701a8c3bf','2026-10-26 11:21:55','2026-10-26 11:21:55','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(562,'resource_crons_jobs__json.json','agentspec__enc.64657369676e2d76697375616c2d73746f727974656c6c6572__enc.302e302e31','{\"name\":\"jobs.json\",\"type\":\"crons\",\"content\":\"[]\\n\",\"metadata\":{\"uniformId\":1792984914794},\"resourceIdentifier\":\"crons::jobs.json\"}','4bb3433a73914f9d5399124dcb11564c','2026-10-26 11:21:55','2026-10-26 11:21:55','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(563,'manifest.json','agentspec__enc.64657369676e2d76697375616c2d73746f727974656c6c6572__enc.302e302e31','{\"name\":\"design-visual-storyteller\",\"description\":\"视觉传达专家，擅长把复杂信息转化成有吸引力的视觉故事，通过多媒体内容和品牌叙事打动受众。\",\"content\":\"{\\n  \\\"version\\\": \\\"1.0\\\",\\n  \\\"source\\\": {\\n    \\\"repository\\\": \\\"https://github.com/jnMetaCode/agency-agents-zh\\\",\\n    \\\"commit\\\": \\\"23c2746913fe46260450517fa