3746f72__enc.302e302e31','{\"name\":\"MEMORY.md\",\"type\":\"config\",\"content\":\"# 长期记忆\\n\\n由运行时写入；本模板未预置业务记忆。\\n\",\"metadata\":{\"uniformId\":1792984915115},\"resourceIdentifier\":\"config::MEMORY.md\"}','ad622095efbcaff438f82f1a3f8be8ba','2026-10-26 11:21:56','2026-10-26 11:21:56','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(621,'enc.736372697074732f6f66666963652f736368656d61732f6d6963726f736f66742f776d6c2d323031302e787364','skill_enc.646f6378__enc.302e302e31','','48d648797b801f851d23d8a5ac1190f2','2026-10-26 11:21:56','2026-10-26 11:21:56','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(622,'manifest.json','agentspec__enc.656e67696e656572696e672d61692d646174612d72656d6564696174696f6e2d656e67696e656572__enc.302e302e31','{\"name\":\"engineering-ai-data-remediation-engineer\",\"description\":\"\\\"自愈数据管道专家——使用气隙隔离的本地 SLM 和语义聚类，自动检测、分类和修复大规模数据异常。专注于修复层：拦截坏数据、通过 Ollama 生成确定性修复逻辑，并保证零数据丢失。不是通用数据工程师——而是当你的数据出了问题且管道不能停的时候，出手的外科手术级专家。\\\"\",\"content\":\"{\\n  \\\"version\\\": \\\"1.0\\\",\\n  \\\"source\\\": {\\n    \\\"repository\\\": \\\"https://github.com/jnMetaCode/agency-agents-zh\\\",\\n    \\\"commit\\\": \\\"23c2746913fe46260450517fa5afb58afc61fed7\\\",\\n    \\\"original_path\\\": \\\"engineering/engineering-ai-data-remediation-engineer.md\\\",\\n    \\\"openclaw_mode\\\": true\\n  },\\n  \\\"description\\\": \\\"\\\\\\\"自愈数据管道专家——使用气隙隔离的本地 SLM 和语义聚类，自动检测、分类和修复大规模数据异常。专注于修复层：拦截坏数据、通过 Ollama 生成确定性修复逻辑，并保证零数据丢失。不是通用数据工程师——而是当你的数据出了问题且管道不能停的时候，出手的外科手术级专家。\\\\\\\"\\\",\\n  \\\"tags\\\": [\\n    \\\"engineering\\\"\\n  ],\\n  \\\"worker\\\": {\\n    \\\"suggested_name\\\": \\\"engineering-ai-data-remediation-engineer\\\",\\n    \\\"base_image\\\": \\\"hiclaw/worker-agent:latest\\\",\\n    \\\"apt_packages\\\": [],\\n    \\\"pip_packages\\\": [],\\n    \\\"npm_packages\\\": []\\n  },\\n  \\\"proxy\\\": {\\n    \\\"suggested\\\": false,\\n    \\\"reason\\\": \\\"\\\"\\n  }\\n}\\n\",\"uniformId\":1792984915354,\"resources\":[{\"name