/schemas.microsoft.com/office/drawing/2015/9/8/chartex\" xmlns:cx2=\"http://schemas.microsoft.com/office/drawing/2015/10/21/chartex\" xmlns:cx3=\"http://schemas.microsoft.com/office/drawing/2016/5/9/chartex\" xmlns:cx4=\"http://schemas.microsoft.com/office/drawing/2016/5/10/chartex\" xmlns:cx5=\"http://schemas.microsoft.com/office/drawing/2016/5/11/chartex\" xmlns:cx6=\"http://schemas.microsoft.com/office/drawing/2016/5/12/chartex\" xmlns:cx7=\"http://schemas.microsoft.com/office/drawing/2016/5/13/chartex\" xmlns:cx8=\"http://schemas.microsoft.com/office/drawing/2016/5/14/chartex\" xmlns:mc=\"http://schemas.openxmlformats.org/markup-compatibility/2006\" xmlns:aink=\"http://schemas.microsoft.com/office/drawing/2016/ink\" xmlns:am3d=\"http://schemas.microsoft.com/office/drawing/2017/model3d\" xmlns:o=\"urn:schemas-microsoft-com:office:office\" xmlns:oel=\"http://schemas.microsoft.com/office/2019/extlst\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\" xmlns:m=\"http://schemas.openxmlformats.org/officeDocument/2006/math\" xmlns:v=\"urn:schemas-microsoft-com:vml\" xmlns:wp14=\"http://schemas.microsoft.com/office/word/2010/wordprocessingDrawing\" xmlns:wp=\"http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing\" xmlns:w10=\"urn:schemas-microsoft-com:office:word\" xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\" xmlns:w14=\"http://schemas.microsoft.com/office/word/2010/wordml\" xmlns:w15=\"http://schemas.microsoft.com/office/word/2012/wordml\" xmlns:w16cex=\"http://schemas.microsoft.com/office/word/2018/wordml/cex\" xmlns:w16cid=\"http://schemas.microsoft.com/office/word/2016/wordml/cid\" xmlns:w16=\"http://schemas.microsoft.com/office/word/2018/wordml\" xmlns:w16du=\"http://schemas.microsoft.com/office/word/2023/wordml/word16du\" xmlns:w16sdtdh=\"http://schemas.microsoft.com/office/word/2020/wordml/sdtdatahash\" xmlns:w16sdtfl=\"http://schemas.microsoft.com/office/word/2024/wordml/sdtformatlock\" xmlns:w16se=\"http://schemas.microsoft.com/office/word/2015/wordml/symex\" xmlns:wpg=\"http://schemas.microsoft.com/office/word/2010/wordprocessingGroup\" xmlns:wpi=\"http://schemas.microsoft.com/office/word/2010/wordprocessingInk\" xmlns:wne=\"http://schemas.microsoft.com/office/word/2006/wordml\" xmlns:wps=\"http://schemas.microsoft.com/office/word/2010/wordprocessingShape\" xmlns:cr=\"http://schemas.microsoft.com/office/comments/2020/reactions\" mc:Ignorable=\"w14 w15 w16se w16cid w16 w16cex w16sdtdh w16sdtfl cr w16du wp14\">\n</w16cex:commentsExtensible>\n','e5fe57c24b0b6896e7df8ed92984e923','2026-10-26 11:21:56','2026-10-26 11:21:56','nacos',NULL,'','public',NULL,NULL,NULL,'xml',NULL,''),(658,'enc.736372697074732f6f66666963652f736368656d61732f49534f2d49454332393530302d345f323031362f7368617265642d646f63756d656e7450726f70657274696573457874656e6465642e787364','skill_enc.646f6378__enc.302e302e31','','bf137503133653b6cac5d82209e65908','2026-10-26 11:21:56','2026-10-26 11:21:56','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(659,'resource_config_AGENTS__md.json','agentspec__enc.656e67696e656572696e672d61692d656e67696e656572__enc.302e302e31','{\"name\":\"AGENTS.md\",\"type\":\"config\",\"content\":\"\\n# AI 工程师\\n\\n你是**AI 工程师**，一位在模型开发和工程化落地之间架桥的实战派。你清楚地知道，一个模型在 Jupyter Notebook 里跑通和真正上线服务之间隔着十万八千里，而你的工作就是把这段路走通。\\n\\n## 核心使命\\n\\n### 模型开发与训练\\n\\n- 数据管线搭建：清洗、特征工程、数据版本管理（DVC）\\n- 模型选型：不追最新论文，选最适合业务场景的方案\\n- 训练工程化：分布式训练、混合精度、梯度累积、checkpoint 管理\\n- 实验管理：MLflow/Weights & Biases 跟踪每次实验的超参和指标\\n- **原则**：没有 baseline 的实验不做，没有离线评估的模型不上线\\n\\n### 模型部署与服务化\\n\\n- 模型优化：量化（INT8/FP16）、剪枝、知识蒸馏、ONNX 转换\\n- Serving 架构：TorchServe/Triton/vLLM 选型与调优\\n- A/B 测试和灰度发布：线上效果验证\\n- 监控告警：数据漂移检测、模型性能指标追踪\\n\\n### LLM 应用工程\\n\\n- Prompt Engineering：系统化的 prompt 设计和版本管理\\n- RAG 架构：向量数据库选型、检索策略、chunk 方案优化\\n- Agent 系统：工具调用、记忆管理、多步推理链路\\n- 成本控制：token 用量监控、模型路由、缓存策略\\n\\n## 技术交付物\\n\\n### RAG 服务示例\\n\\n```python\\nfrom dataclasses import dataclass\\nfrom typing import List\\nimport numpy as np\\n\\n\\n@dataclass\\nclass RetrievalConfig:\\n    top_k: int = 5\\n    similarity_threshold: float = 0.75\\n    chunk_size: int = 512\\n    chunk_overlap: int = 64\\n\\n\\nclass RAGService:\\n    \\\"\\\"\\\"检索增强生成服务\\\"\\\"\\\"\\n\\n    def __init__(self, config: RetrievalConfig, vector_store, llm_client):\\n        self.config = config\\n        self.vector_store = vector_store\\n        self.llm = llm_client\\n\\n    def query(self, question: str, filters: dict = None) -> dict:\\n        # 1. 检索相关文档\\n        docs = self.vector_store.search(\\n            query=question,\\n            top_k=self.config.top_k,\\n            filters=filters,\\n        )\\n\\n        # 2. 过滤低相关度结果\\n        relevant = [\\n            d for d in docs\\n            if d.score >= self.config.similarity_threshold\\n        ]\\n\\n        if not relevant:\\n            return {\\\"answer\\\": \\\"未找到相关信息\\\", \\\"sources\\\": []}\\n\\n        # 3. 构建 prompt\\n        context = \\\"\\\\n\\\\n\\\".join(d.content for d in relevant)\\n        prompt = self._build_prompt(question, context)\\n\\n        # 4. 生成回答\\n        response = self.llm.generate(\\n            prompt=prompt,\\n            max_tokens=1024,\\n            temperature=0.1,\\n        )\\n\\n        return {\\n            \\\"answer\\\": response.text,\\n            \\\"sources\\\": [d.metadata for d in relevant],\\n            \\\"tokens_used\\\": response.usage.total_tokens,\\n        }\\n\\n    def _build_prompt(self, question: str, context: str) -> str:\\n        return (\\n            f\\\"基于以下参考资料回答问题。如果资料中没有答案，\\\"\\n            f\\\"请明确说明。\\\\n\\\\n\\\"\\n            f\\\"参考资料：\\\\n{context}\\\\n\\\\n\\\"\\n            f\\\"问题：{question}\\\\n\\\\n\\\"\\n            f\\\"回答：\\\"\\n        )\\n```\\n\\n## 工作流程\\n\\n### 第一步：问题定义与数据审计\\n\\n- 明确业务目标和评估指标——\\\"准确率提升 5%\\\"不够，要定义在什么数据集、什么场景下\\n- 数据质量审计：分布、缺失值、标注一致性\\n- 确定 baseline：规则方案或已有模型的效果\\n\\n### 第二步：实验迭代\\n\\n- 搭建可复现的实验管线\\n- 快速迭代：先跑通 pipeline，再优化单点\\n- 离线评估要全面：precision/recall/F1 之外，关注分布外样本和边界情况\\n\\n### 第三步：工程化与部署\\n\\n- 模型打包：Docker 镜像 + 模型权重版本化\\n- 性能优化：推理延迟和吞吐量满足 SLA\\n- 搭建监控：请求量、延迟、错误率、模型指标\\n\\n### 第四步：线上验证与迭代\\n\\n- Shadow mode 验证线上效果\\n- A/B 测试确认业务指标提升\\n- 建立数据回流机制，持续优化模型\\n\\n## 成功指标\\n\\n- 模型从实验到上线周期 < 2 周\\n- 线上推理 P99 延迟 < 100ms（非 LLM 场景）\\n- 模型效果线上线下一致性偏差 < 5%\\n- 训练实验 100% 可复现\\n- GPU 资源利用率 > 70%\\n\",\"metadata\":{\"uniformId\":1792984915746},\"resourceIdentifier\":\"config::AGENTS.md\"}','1d2a04f291df4470bf6f42045c6b03ba','2026-10-26 11:21:56','2026-10-26 11:21:56','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(660,'resource_config_AGENTS__md.json','agentspec__enc.656e67696e656572696e672d61692d656e67696e656572__enc.302e302e31','{\"name\":\"AGENTS.md\",\"type\":\"config\",\"content\":\"\\n# AI 工程师\\n\\n你是**AI 工程师**，一位在模型开发和工程化落地之间架桥的实战派。你清楚地知道，一个模型在 Jupyter Notebook 里跑通和真正上线服务之间隔着十万八千里，而你的工作就是把这段路走通。\\n\\n## 核心使命\\n\\n### 模型开发与训练\\n\\n- 数据管线搭建：清洗、特征工程、数据版本管理（DVC）\\n- 模型选型：不追最新论文，选最适合业务场景的方案\\n- 训练工程化：分布式训练、混合精度、梯度累积、checkpoint 管理\\n- 实验管理：MLflow/Weights & Biases 跟踪每次实验的超参和指标\\n- **原则**：没有 baseline 的实验不做，没有离线评估的模型不上线\\n\\n### 模型部署与服务化\\n\\n- 模型优化：量化（INT8/FP16）、剪枝、知识蒸馏、ONNX 转换\\n- Serving 架构：TorchServe/Triton/vLLM 选型与调优\\n- A/B 测试和灰度发布：线上效果验证\\n- 监控告警：数据漂移检测、模型性能指标追踪\\n\\n### LLM 应用工程\\n\\n- Prompt Engineering：系统化的 prompt 设计和版本管理\\n- RAG 架构：向量数据库选型、检索策略、chunk 方案优化\\n- Agent 系统：工具调用、记忆管理、多步推理链路\\n- 成本控制：token 用量监控、模型路由、缓存策略\\n\\n## 技术交付物\\n\\n### RAG 服务示例\\n\\n```python\\nfrom dataclasses import dataclass\\nfrom typing import List\\nimport numpy as np\\n\\n\\n@dataclass\\nclass RetrievalConfig:\\n    top_k: int = 5\\n    similarity_threshold: float = 0.75\\n    chunk_size: int = 512\\n    chunk_overlap: int = 64\\n\\n\\nclass RAGService:\\n    \\\"\\\"\\\"检索增强生成服务\\\"\\\"\\\"\\n\\n    def __init__(self, config: RetrievalConfig, vector_store, llm_client):\\n        self.config = config\\n        self.vector_store = vector_store\\n        self.llm = llm_client\\n\\n    def query(self, question: str, filters: dict = None) -> dict:\\n        # 1. 检索相关文档\\n        docs = self.vector_store.search(\\n            query=question,\\n            top_k=self.config.top_k,\\n            filters=filters,\\n        )\\n\\n        # 2. 过滤低相关度结果\\n        relevant = [\\n            d for d in docs\\n            if d.score >= self.config.similarity_threshold\\n        ]\\n\\n        if not relevant:\\n            return {\\\"answer\\\": \\\"未找到相关信息\\\", \\\"sources\\\": []}\\n\\n        # 3. 构建 prompt\\n        context = \\\"\\\\n\\\\n\\\".join(d.content for d in relevant)\\n        prompt = self._build_prompt(question, context)\\n\\n        # 4. 生成回答\\n        response = self.llm.generate(\\n            prompt=prompt,\\n            max_tokens=1024,\\n            temperature=0.1,\\n        )\\n\\n        return {\\n            \\\"answer\\\": response.text,\\n            \\\"sources\\\": [d.metadata for d in relevant],\\n            \\\"tokens_used\\\": response.usage.total_tokens,\\n        }\\n\\n    def _build_prompt(self, question: str, context: str) -> str:\\n        return (\\n            f\\\"基于以下参考资料回答问题。如果资料中没有答案，\\\"\\n            f\\\"请明确说明。\\\\n\\\\n\\\"\\n            f\\\"参考资料：\\\\n{context}\\\\n\\\\n\\\"\\n            f\\\"问题：{question}\\\\n\\\\n\\\"\\n            f\\\"回答：\\\"\\n        )\\n```\\n\\n## 工作流程\\n\\n### 第一步：问题定义与数据审计\\n\\n- 明确业务目标和评估指标——\\\"准确率提升 5%\\\"不够，要定义在什么数据集、什么场景下\\n- 数据质量审计：分布、缺失值、标注一致性\\n- 确定 baseline：规则方案或已有模型的效果\\n\\n### 第二步：实验迭代\\n\\n- 搭建可复现的实验管线\\n- 快速迭代：先跑通 pipeline，再优化单点\\n- 离线评估要全面：precision/recall/F1 之外，关注分布外样本和边界情况\\n\\n### 第三步：工程化与部署\\n\\n- 模型打包：Docker 镜像 + 模型权重版本化\\n- 性能优化：推理延迟和吞吐量满足 SLA\\n- 搭建监控：请求量、延迟、错误率、模型指标\\n\\n### 第四步：线上验证与迭代\\n\\n- Shadow mode 验证线上效果\\n- A/B 测试确认业务指标提升\\n- 建立数据回流机制，持续优化模型\\n\\n## 成功指标\\n\\n- 模型从实验到上线周期 < 2 周\\n- 线上推理 P99 延迟 < 100ms（非 LLM 场景）\\n- 模型效果线上线下一致性偏差 < 5%\\n- 训练实验 100% 可复现\\n- GPU 资源利用率 > 70%\\n\",\"metadata\":{\"uniformId\":1792984915746},\"resourceIdentifier\":\"config::AGENTS.md\"}','1d2a04f291df4470bf6f42045c6b03ba','2026-10-26 11:21:56','2026-10-26 11:21:56','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(661,'enc.736372697074732f6f66666963652f736368656d61732f49534f2d49454332393530302d345f323031362f7368617265642d636f6d6d6f6e53696d706c6554797065732e787364','skill_enc.646f6378__enc.302e302e31','','8467bfda5ef339eb1df6652185d65ec9','2026-10-26 11:21:56','2026-10-26 11:21:56','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(662,'enc.736372697074732f6f66666963652f736368656d61732f49534f2d49454332393530302d345f323031362f7368617265642d636f6d6d6f6e53696d706c6554797065732e787364','skill_enc.646f6378__enc.302e302e31','','8467bfda5ef339eb1df6652185d65ec9','2026-10-26 11:21:56','2026-10-26 11:21:56','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(663,'enc.736372697074732f6163636570745f6368616e6765732e7079','skill_enc.646f6378__enc.302e302e31','\"\"\"Accept all tracked changes in a DOCX file using LibreOffice.\n\nRequires LibreOffice (soffice) to be installed.\n\"\"\"\n\nimport argparse\nimport logging\nimport shutil\nimport subprocess\nfrom pathlib import Path\n\nfrom office.soffice import get_soffice_env\n\nlogger = logging.getLogger(__name__)\n\nLIBREOFFICE_PROFILE = \"/tmp/libreoffice_docx_profile\"\nMACRO_DIR = f\"{LIBREOFFICE_PROFILE}/user/basic/Standard\"\n\nACCEPT_CHANGES_MACRO = \"\"\"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!DOCTYPE script:module PUBLIC \"-//OpenOffice.org//DTD OfficeDocument 1.0//EN\" \"module.dtd\">\n<script:module xmlns:script=\"http://openoffice.org/2000/script\" script:name=\"Module1\" script:language=\"StarBasic\">\n    Sub AcceptAllTrackedChanges()\n        Dim document As Object\n        Dim dispatcher As Object\n\n        document = ThisComponent.CurrentController.Frame\n        dispatcher = createUnoService(\"com.sun.star.frame.DispatchHelper\")\n\n        dispatcher.executeDispatch(document, \".uno:AcceptAllTrackedChanges\", \"\", 0, Array())\n        ThisComponent.store()\n        ThisComponent.close(True)\n    End Sub\n</script:module>\"\"\"\n\n\ndef accept_changes(\n    input_file: str,\n    output_file: str,\n) -> tuple[None, str]:\n    input_path = Path(input_file)\n    output_path = Path(output_file)\n\n    if not input_path.exists():\n        return None, f\"Error: Input file not found: {input_file}\"\n\n    if not input_path.suffix.lower() == \".docx\":\n        return None, f\"Error: Input file is not a DOCX file: {input_file}\"\n\n    try:\n        output_path.parent.mkdir(parents=True, exist_ok=True)\n        shutil.copy2(input_path, output_path)\n    except Exception as e:\n        return None, f\"Error: Failed to copy input file to output location: {e}\"\n\n    if not _setup_libreoffice_macro():\n        return None, \"Error: Failed to setup LibreOffice macro\"\n\n    cmd = [\n        \"soffice\",\n        \"--headless\",\n        f\"-env:UserInstallation=file://{LIBREOFFICE_PROFILE}\",\n        \"--norestore\",\n        \"vnd.sun.star.script:Standard.Module1.AcceptAllTrackedChanges?language=Basic&location=application\",\n        str(output_path.absolute()),\n    ]\n\n    try:\n        result = subprocess.run(\n            cmd,\n            capture_output=True,\n            text=True,\n            timeout=30,\n            check=False,\n            env=get_soffice_env(),\n        )\n    except subprocess.TimeoutExpired:\n        return (\n            None,\n            f\"Successfully accepted all tracked changes: {input_file} -> {output_file}\",\n        )\n\n    if result.returncode != 0:\n        return None, f\"Error: LibreOffice failed: {result.stderr}\"\n\n    return (\n        None,\n        f\"Successfully accepted all tracked changes: {input_file} -> {output_file}\",\n    )\n\n\ndef _setup_libreoffice_macro() -> bool:\n    macro_dir = Path(MACRO_DIR)\n    macro_file = macro_dir / \"Module1.xba\"\n\n    if macro_file.exists() and \"AcceptAllTrackedChanges\" in macro_file.read_text():\n        return True\n\n    if not macro_dir.exists():\n        subprocess.run(\n            [\n                \"soffice\",\n                \"--headless\",\n                f\"-env:UserInstallation=file://{LIBREOFFICE_PROFILE}\",\n                \"--terminate_after_init\",\n            ],\n            capture_output=True,\n            timeout=10,\n            check=False,\n            env=get_soffice_env(),\n        )\n        macro_dir.mkdir(parents=True, exist_ok=True)\n\n    try:\n        macro_file.write_text(ACCEPT_CHANGES_MACRO)\n        return True\n    except Exception as e:\n        logger.warning(f\"Failed to setup LibreOffice macro: {e}\")\n        return False\n\n\nif __name__ == \"__main__\":\n    parser = argparse.ArgumentParser(\n        description=\"Accept all tracked changes in a DOCX file\"\n    )\n    parser.add_argument(\"input_file\", help=\"Input DOCX file with tracked changes\")\n    parser.add_argument(\n        \"output_file\", help=\"Output DOCX file (clean, no tracked changes)\"\n    )\n    args = parser.parse_args()\n\n    _, message = accept_changes(args.input_file, args.output_file)\n    print(message)\n\n    if \"Error\" in message:\n        raise SystemExit(1)\n','ddbb446842e4c03d128aa950c2d9cde4','2026-10-26 11:21:56','2026-10-26 11:21:56','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(664,'enc.736372697074732f6f66666963652f736368656d61732f65636d612f666f7574682d65646974696f6e2f6f70632d72656c6174696f6e73686970732e787364','skill_enc.646f6378__enc.302e302e31','','83c1e2da90194b600688463398a125fd','2026-10-26 11:21:56','2026-10-26 11:21:56','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(665,'enc.736372697074732f6163636570745f6368616e6765732e7079','skill_enc.646f6378__enc.302e302e31','\"\"\"Accept all tracked changes in a DOCX file using LibreOffice.\n\nRequires LibreOffice (soffice) to be installed.\n\"\"\"\n\nimport argparse\nimport logging\nimport shutil\nimport subprocess\nfrom pathlib import Path\n\nfrom office.soffice import get_soffice_env\n\nlogger = logging.getLogger(__name__)\n\nLIBREOFFICE_PROFILE = \"/tmp/libreoffice_docx_profile\"\nMACRO_DIR = f\"{LIBREOFFICE_PROFILE}/user/basic/Standard\"\n\nACCEPT_CHANGES_MACRO = \"\"\"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<!DOCTYPE script:module PUBLIC \"-//OpenOffice.org//DTD OfficeDocument 1.0//EN\" \"module.dtd\">\n<script:module xmlns:script=\"http://openoffice.org/2000/script\" script:name=\"Module1\" script:language=\"StarBasic\">\n    Sub AcceptAllTrackedChanges()\n        Dim document As Object\n        Dim dispatcher As Object\n\n        document = ThisComponent.CurrentController.Frame\n        dispatcher = createUnoService(\"com.sun.star.frame.DispatchHelper\")\n\n        dispatcher.executeDispatch(document, \".uno:AcceptAllTrackedChanges\", \"\", 0, Array())\n        ThisComponent.store()\n        ThisComponent.close(True)\n    End Sub\n</script:module>\"\"\"\n\n\ndef accept_changes(\n    input_file: str,\n    output_file: str,\n) -> tuple[None, str]:\n    input_path = Path(input_file)\n    output_path = Path(output_file)\n\n    if not input_path.exists():\n        return None, f\"Error: Input file not found: {input_file}\"\n\n    if not input_path.suffix.lower() == \".docx\":\n        return None, f\"Error: Input file is not a DOCX file: {input_file}\"\n\n    try:\n        output_path.parent.mkdir(parents=True, exist_ok=True)\n        shutil.copy2(input_path, output_path)\n    except Exception as e:\n        return None, f\"Error: Failed to copy input file to output location: {e}\"\n\n    if not _setup_libreoffice_macro():\n        return None, \"Error: Failed to setup LibreOffice macro\"\n\n    cmd = [\n        \"soffice\",\n        \"--headless\",\n        f\"-env:UserInstallation=file://{LIBREOFFICE_PROFILE}\",\n        \"--norestore\",\n        \"vnd.sun.star.script:Standard.Module1.AcceptAllTrackedChanges?language=Basic&location=application\",\n        str(output_path.absolute()),\n    ]\n\n    try:\n        result = subprocess.run(\n            cmd,\n            capture_output=True,\n            text=True,\n            timeout=30,\n            check=False,\n            env=get_soffice_env(),\n        )\n    except subprocess.TimeoutExpired:\n        return (\n            None,\n            f\"Successfully accepted all tracked changes: {input_file} -> {output_file}\",\n        )\n\n    if result.returncode != 0:\n        return None, f\"Error: LibreOffice failed: {result.stderr}\"\n\n    return (\n        None,\n        f\"Successfully accepted all tracked changes: {input_file} -> {output_file}\",\n    )\n\n\ndef _setup_libreoffice_macro() -> bool:\n    macro_dir = Path(MACRO_DIR)\n    macro_file = macro_dir / \"Module1.xba\"\n\n    if macro_file.exists() and \"AcceptAllTrackedChanges\" in macro_file.read_text():\n        return True\n\n    if not macro_dir.exists():\n        subprocess.run(\n            [\n                \"soffice\",\n                \"--headless\",\n                f\"-env:UserInstallation=file://{LIBREOFFICE_PROFILE}\",\n                \"--terminate_after_init\",\n            ],\n            capture_output=True,\n            timeout=10,\n            check=False,\n            env=get_soffice_env(),\n        )\n        macro_dir.mkdir(parents=True, exist_ok=True)\n\n    try:\n        macro_file.write_text(ACCEPT_CHANGES_MACRO)\n        return True\n    except Exception as e:\n        logger.warning(f\"Failed to setup LibreOffice macro: {e}\")\n        return False\n\n\nif __name__ == \"__main__\":\n    parser = argparse.ArgumentParser(\n        description=\"Accept all tracked changes in a DOCX file\"\n    )\n    parser.add_argument(\"input_file\", help=\"Input DOCX file with tracked changes\")\n    parser.add_argument(\n        \"output_file\", help=\"Output DOCX file (clean, no tracked changes)\"\n    )\n    args = parser.parse_args()\n\n    _, message = accept_changes(args.input_file, args.output_file)\n    print(message)\n\n    if \"Error\" in message:\n        raise SystemExit(1)\n','ddbb446842e4c03d128aa950c2d9cde4','2026-10-26 11:21:56','2026-10-26 11:21:56','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(666,'enc.736372697074732f6f66666963652f76616c696461746f72732f626173652e7079','skill_enc.646f6378__enc.302e302e31','\"\"\"\nBase validator with common validation logic for document files.\n\"\"\"\n\nimport re\nfrom pathlib import Path\n\nimport defusedxml.minidom\nimport lxml.etree\n\n\nclass BaseSchemaValidator:\n\n    IGNORED_VALIDATION_ERRORS = [\n        \"hyphenationZone\",\n        \"purl.org/dc/terms\",\n    ]\n\n    UNIQUE_ID_REQUIREMENTS = {\n        \"comment\": (\"id\", \"file\"),  \n        \"commentrangestart\": (\"id\", \"file\"),  \n        \"commentrangeend\": (\"id\", \"file\"),  \n        \"bookmarkstart\": (\"id\", \"file\"),  \n        \"bookmarkend\": (\"id\", \"file\"),  \n        \"sldid\": (\"id\", \"file\"),  \n        \"sldmasterid\": (\"id\", \"global\"),  \n        \"sldlayoutid\": (\"id\", \"global\"),  \n        \"cm\": (\"authorid\", \"file\"),  \n        \"sheet\": (\"sheetid\", \"file\"),  \n        \"definedname\": (\"id\", \"file\"),  \n        \"cxnsp\": (\"id\", \"file\"),  \n        \"sp\": (\"id\", \"file\"),  \n        \"pic\": (\"id\", \"file\"),  \n        \"grpsp\": (\"id\", \"file\"),  \n    }\n\n    EXCLUDED_ID_CONTAINERS = {\n        \"sectionlst\",  \n    }\n\n    ELEMENT_RELATIONSHIP_TYPES = {}\n\n    SCHEMA_MAPPINGS = {\n        \"word\": \"ISO-IEC29500-4_2016/wml.xsd\",  \n        \"ppt\": \"ISO-IEC29500-4_2016/pml.xsd\",  \n        \"xl\": \"ISO-IEC29500-4_2016/sml.xsd\",  \n        \"[Content_Types].xml\": \"ecma/fouth-edition/opc-contentTypes.xsd\",\n        \"app.xml\": \"ISO-IEC29500-4_2016/shared-documentPropertiesExtended.xsd\",\n        \"core.xml\": \"ecma/fouth-edition/opc-coreProperties.xsd\",\n        \"custom.xml\": \"ISO-IEC29500-4_2016/shared-documentPropertiesCustom.xsd\",\n        \".rels\": \"ecma/fouth-edition/opc-relationships.xsd\",\n        \"people.xml\": \"microsoft/wml-2012.xsd\",\n        \"commentsIds.xml\": \"microsoft/wml-cid-2016.xsd\",\n        \"commentsExtensible.xml\": \"microsoft/wml-cex-2018.xsd\",\n        \"commentsExtended.xml\": \"microsoft/wml-2012.xsd\",\n        \"chart\": \"ISO-IEC29500-4_2016/dml-chart.xsd\",\n        \"theme\": \"ISO-IEC29500-4_2016/dml-main.xsd\",\n        \"drawing\": \"ISO-IEC29500-4_2016/dml-main.xsd\",\n    }\n\n    MC_NAMESPACE = \"http://schemas.openxmlformats.org/markup-compatibility/2006\"\n    XML_NAMESPACE = \"http://www.w3.org/XML/1998/namespace\"\n\n    PACKAGE_RELATIONSHIPS_NAMESPACE = (\n        \"http://schemas.openxmlformats.org/package/2006/relationships\"\n    )\n    OFFICE_RELATIONSHIPS_NAMESPACE = (\n        \"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"\n    )\n    CONTENT_TYPES_NAMESPACE = (\n        \"http://schemas.openxmlformats.org/package/2006/content-types\"\n    )\n\n    MAIN_CONTENT_FOLDERS = {\"word\", \"ppt\", \"xl\"}\n\n    OOXML_NAMESPACES = {\n        \"http://schemas.openxmlformats.org/officeDocument/2006/math\",\n        \"http://schemas.openxmlformats.org/officeDocument/2006/relationships\",\n        \"http://schemas.openxmlformats.org/schemaLibrary/2006/main\",\n        \"http://schemas.openxmlformats.org/drawingml/2006/main\",\n        \"http://schemas.openxmlformats.org/drawingml/2006/chart\",\n        \"http://schemas.openxmlformats.org/drawingml/2006/chartDrawing\",\n        \"http://schemas.openxmlformats.org/drawingml/2006/diagram\",\n        \"http://schemas.openxmlformats.org/drawingml/2006/picture\",\n        \"http://schemas.openxmlformats.org/drawingml/2006/spreadsheetDrawing\",\n        \"http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing\",\n        \"http://schemas.openxmlformats.org/wordprocessingml/2006/main\",\n        \"http://schemas.openxmlformats.org/presentationml/2006/main\",\n        \"http://schemas.openxmlformats.org/spreadsheetml/2006/main\",\n        \"http://schemas.openxmlformats.org/officeDocument/2006/sharedTypes\",\n        \"http://www.w3.org/XML/1998/namespace\",\n    }\n\n    def __init__(self, unpacked_dir, original_file=None, verbose=False):\n        self.unpacked_dir = Path(unpacked_dir).resolve()\n        self.original_file = Path(original_file) if original_file else None\n        self.verbose = verbose\n\n        self.schemas_dir = Path(__file__).parent.parent / \"schemas\"\n\n        patterns = [\"*.xml\", \"*.rels\"]\n        self.xml_files = [\n            f for pattern in patterns for f in self.unpacked_dir.rglob(pattern)\n        ]\n\n        if not self.xml_files:\n            print(f\"Warning: No XML files found in {self.unpacked_dir}\")\n\n    def validate(self):\n        raise NotImplementedError(\"Subclasses must implement the validate method\")\n\n    def repair(self) -> int:\n        return self.repair_whitespace_preservation()\n\n    def repair_whitespace_preservation(self) -> int:\n        repairs = 0\n\n        for xml_file in self.xml_files:\n            try:\n                content = xml_file.read_text(encoding=\"utf-8\")\n                dom = defusedxml.minidom.parseString(content)\n                modified = False\n\n                for elem in dom.getElementsByTagName(\"*\"):\n                    if elem.tagName.endswith(\":t\") and elem.firstChild:\n                        text = elem.firstChild.nodeValue\n                        if text and (text.startswith((\' \', \'\\t\')) or text.endswith((\' \', \'\\t\'))):\n                            if elem.getAttribute(\"xml:space\") != \"preserve\":\n                                elem.setAttribute(\"xml:space\", \"preserve\")\n                                text_preview = repr(text[:30]) + \"...\" if len(text) > 30 else repr(text)\n                                print(f\"  Repaired: {xml_file.name}: Added xml:space=\'preserve\' to {elem.tagName}: {text_preview}\")\n                                repairs += 1\n                                modified = True\n\n                if modified:\n                    xml_file.write_bytes(dom.toxml(encoding=\"UTF-8\"))\n\n            except Exception:\n                pass\n\n        return repairs\n\n    def validate_xml(self):\n        errors = []\n\n        for xml_file in self.xml_files:\n            try:\n                lxml.etree.parse(str(xml_file))\n            except lxml.etree.XMLSyntaxError as e:\n                errors.append(\n                    f\"  {xml_file.relative_to(self.unpacked_dir)}: \"\n                    f\"Line {e.lineno}: {e.msg}\"\n                )\n            except Exception as e:\n                errors.append(\n                    f\"  {xml_file.relative_to(self.unpacked_dir)}: \"\n                    f\"Unexpected error: {str(e)}\"\n                )\n\n        if errors:\n            print(f\"FAILED - Found {len(errors)} XML violations:\")\n            for error in errors:\n                print(error)\n            return False\n        else:\n            if self.verbose:\n                print(\"PASSED - All XML files are well-formed\")\n            return True\n\n    def validate_namespaces(self):\n        errors = []\n\n        for xml_file in self.xml_files:\n            try:\n                root = lxml.etree.parse(str(xml_file)).getroot()\n                declared = set(root.nsmap.keys()) - {None}  \n\n                for attr_val in [\n                    v for k, v in root.attrib.items() if k.endswith(\"Ignorable\")\n                ]:\n                    undeclared = set(attr_val.split()) - declared\n                    errors.extend(\n                        f\"  {xml_file.relative_to(self.unpacked_dir)}: \"\n                        f\"Namespace \'{ns}\' in Ignorable but not declared\"\n                        for ns in undeclared\n                    )\n            except lxml.etree.XMLSyntaxError:\n                continue\n\n        if errors:\n            print(f\"FAILED - {len(errors)} namespace issues:\")\n            for error in errors:\n                print(error)\n            return False\n        if self.verbose:\n            print(\"PASSED - All namespace prefixes properly declared\")\n        return True\n\n    def validate_unique_ids(self):\n        errors = []\n        global_ids = {}  \n\n        for xml_file in self.xml_files:\n            try:\n                root = lxml.etree.parse(str(xml_file)).getroot()\n                file_ids = {}  \n\n                mc_elements = root.xpath(\n                    \".//mc:AlternateContent\", namespaces={\"mc\": self.MC_NAMESPACE}\n                )\n                for elem in mc_elements:\n                    elem.getparent().remove(elem)\n\n                for elem in root.iter():\n                    tag = (\n                        elem.tag.split(\"}\")[-1].lower()\n                        if \"}\" in elem.tag\n                        else elem.tag.lower()\n                    )\n\n                    if tag in self.UNIQUE_ID_REQUIREMENTS:\n                        in_excluded_container = any(\n                            ancestor.tag.split(\"}\")[-1].lower() in self.EXCLUDED_ID_CONTAINERS\n                            for ancestor in elem.iterancestors()\n                        )\n                        if in_excluded_container:\n                            continue\n\n                        attr_name, scope = self.UNIQUE_ID_REQUIREMENTS[tag]\n\n                        id_value = None\n                        for attr, value in elem.attrib.items():\n                            attr_local = (\n                                attr.split(\"}\")[-1].lower()\n                                if \"}\" in attr\n                                else attr.lower()\n                            )\n                            if attr_local == attr_name:\n                                id_value = value\n                                break\n\n                        if id_value is not None:\n                            if scope == \"global\":\n                                if id_value in global_ids:\n                                    prev_file, prev_line, prev_tag = global_ids[\n                                        id_value\n                                    ]\n                                    errors.append(\n                                        f\"  {xml_file.relative_to(self.unpacked_dir)}: \"\n                                        f\"Line {elem.sourceline}: Global ID \'{id_value}\' in <{tag}> \"\n                                        f\"already used in {prev_file} at line {prev_line} in <{prev_tag}>\"\n                                    )\n                                else:\n                                    global_ids[id_value] = (\n                                        xml_file.relative_to(self.unpacked_dir),\n                                        elem.sourceline,\n                                        tag,\n                                    )\n                            elif scope == \"file\":\n                                key = (tag, attr_name)\n                                if key not in file_ids:\n                                    file_ids[key] = {}\n\n                                if id_value in file_ids[key]:\n                                    prev_line = file_ids[key][id_value]\n                                    errors.append(\n                                        f\"  {xml_file.relative_to(self.unpacked_dir)}: \"\n                                        f\"Line {elem.sourceline}: Duplicate {attr_name}=\'{id_value}\' in <{tag}> \"\n                                        f\"(first occurrence at line {prev_line})\"\n                                    )\n                                else:\n                                    file_ids[key][id_value] = elem.sourceline\n\n            except (lxml.etree.XMLSyntaxError, Exception) as e:\n                errors.append(\n                    f\"  {xml_file.relative_to(self.unpacked_dir)}: Error: {e}\"\n                )\n\n        if errors:\n            print(f\"FAILED - Found {len(errors)} ID uniqueness violations:\")\n            for error in errors:\n                print(error)\n            return False\n        else:\n            if self.verbose:\n                print(\"PASSED - All required IDs are unique\")\n            return True\n\n    def validate_file_references(self):\n        errors = []\n\n        rels_files = list(self.unpacked_dir.rglob(\"*.rels\"))\n\n        if not rels_files:\n            if self.verbose:\n                print(\"PASSED - No .rels files found\")\n            return True\n\n        all_files = []\n        for file_path in self.unpacked_dir.rglob(\"*\"):\n            if (\n                file_path.is_file()\n                and file_path.name != \"[Content_Types].xml\"\n                and not file_path.name.endswith(\".rels\")\n            ):  \n                all_files.append(file_path.resolve())\n\n        all_referenced_files = set()\n\n        if self.verbose:\n            print(\n                f\"Found {len(rels_files)} .rels files and {len(all_files)} target files\"\n            )\n\n        for rels_file in rels_files:\n            try:\n                rels_root = lxml.etree.parse(str(rels_file)).getroot()\n\n                rels_dir = rels_file.parent\n\n                referenced_files = set()\n                broken_refs = []\n\n                for rel in rels_root.findall(\n                    \".//ns:Relationship\",\n                    namespaces={\"ns\": self.PACKAGE_RELATIONSHIPS_NAMESPACE},\n                ):\n                    target = rel.get(\"Target\")\n                    if target and not target.startswith(\n                        (\"http\", \"mailto:\")\n                    ):  \n                        if target.startswith(\"/\"):\n                            target_path = self.unpacked_dir / target.lstrip(\"/\")\n                        elif rels_file.name == \".rels\":\n                            target_path = self.unpacked_dir / target\n                        else:\n                            base_dir = rels_dir.parent\n                            target_path = base_dir / target\n\n                        try:\n                            target_path = target_path.resolve()\n                            if target_path.exists() and target_path.is_file():\n                                referenced_files.add(target_path)\n                                all_referenced_files.add(target_path)\n                            else:\n                                broken_refs.append((target, rel.sourceline))\n                        except (OSError, ValueError):\n                            broken_refs.append((target, rel.sourceline))\n\n                if broken_refs:\n                    rel_path = rels_file.relative_to(self.unpacked_dir)\n                    for broken_ref, line_num in broken_refs:\n                        errors.append(\n                            f\"  {rel_path}: Line {line_num}: Broken reference to {broken_ref}\"\n                        )\n\n            except Exception as e:\n                rel_path = rels_file.relative_to(self.unpacked_dir)\n                errors.append(f\"  Error parsing {rel_path}: {e}\")\n\n        unreferenced_files = set(all_files) - all_referenced_files\n\n        if unreferenced_files:\n            for unref_file in sorted(unreferenced_files):\n                unref_rel_path = unref_file.relative_to(self.unpacked_dir)\n                errors.append(f\"  Unreferenced file: {unref_rel_path}\")\n\n        if errors:\n            print(f\"FAILED - Found {len(errors)} relationship validation errors:\")\n            for error in errors:\n                print(error)\n            print(\n                \"CRITICAL: These errors will cause the document to appear corrupt. \"\n                + \"Broken references MUST be fixed, \"\n                + \"and unreferenced files MUST be referenced or removed.\"\n            )\n            return False\n        else:\n            if self.verbose:\n                print(\n                    \"PASSED - All references are valid and all files are properly referenced\"\n                )\n            return True\n\n    def validate_all_relationship_ids(self):\n        import lxml.etree\n\n        errors = []\n\n        for xml_file in self.xml_files:\n            if xml_file.suffix == \".rels\":\n                continue\n\n            rels_dir = xml_file.parent / \"_rels\"\n            rels_file = rels_dir / f\"{xml_file.name}.rels\"\n\n            if not rels_file.exists():\n                continue\n\n            try:\n                rels_root = lxml.etree.parse(str(rels_file)).getroot()\n                rid_to_type = {}\n\n                for rel in rels_root.findall(\n                    f\".//{{{self.PACKAGE_RELATIONSHIPS_NAMESPACE}}}Relationship\"\n                ):\n                    rid = rel.get(\"Id\")\n                    rel_type = rel.get(\"Type\", \"\")\n                    if rid:\n                        if rid in rid_to_type:\n                            rels_rel_path = rels_file.relative_to(self.unpacked_dir)\n                            errors.append(\n                                f\"  {rels_rel_path}: Line {rel.sourceline}: \"\n                                f\"Duplicate relationship ID \'{rid}\' (IDs must be unique)\"\n                            )\n                        type_name = (\n                            rel_type.split(\"/\")[-1] if \"/\" in rel_type else rel_type\n                        )\n                        rid_to_type[rid] = type_name\n\n                xml_root = lxml.etree.parse(str(xml_file)).getroot()\n\n                r_ns = self.OFFICE_RELATIONSHIPS_NAMESPACE\n                rid_attrs_to_check = [\"id\", \"embed\", \"link\"]\n                for elem in xml_root.iter():\n                    for attr_name in rid_attrs_to_check:\n                        rid_attr = elem.get(f\"{{{r_ns}}}{attr_name}\")\n                        if not rid_attr:\n                            continue\n                        xml_rel_path = xml_file.relative_to(self.unpacked_dir)\n                        elem_name = (\n                            elem.tag.split(\"}\")[-1] if \"}\" in elem.tag else elem.tag\n                        )\n\n                        if rid_attr not in rid_to_type:\n                            errors.append(\n                                f\"  {xml_rel_path}: Line {elem.sourceline}: \"\n                                f\"<{elem_name}> r:{attr_name} references non-existent relationship \'{rid_attr}\' \"\n                                f\"(valid IDs: {\', \'.join(sorted(rid_to_type.keys())[:5])}{\'...\' if len(rid_to_type) > 5 else \'\'})\"\n                            )\n                        elif attr_name == \"id\" and self.ELEMENT_RELATIONSHIP_TYPES:\n                            expected_type = self._get_expected_relationship_type(\n                                elem_name\n                            )\n                            if expected_type:\n                                actual_type = rid_to_type[rid_attr]\n                                if expected_type not in actual_type.lower():\n                                    errors.append(\n                                        f\"  {xml_rel_path}: Line {elem.sourceline}: \"\n                                        f\"<{elem_name}> references \'{rid_attr}\' which points to \'{actual_type}\' \"\n                                        f\"but should point to a \'{expected_type}\' relationship\"\n                                    )\n\n            except Exception as e:\n                xml_rel_path = xml_file.relative_to(self.unpacked_dir)\n                errors.append(f\"  Error processing {xml_rel_path}: {e}\")\n\n        if errors:\n            print(f\"FAILED - Found {len(errors)} relationship ID reference errors:\")\n            for error in errors:\n                print(error)\n            print(\"\\nThese ID mismatches will cause the document to appear corrupt!\")\n            return False\n        else:\n            if self.verbose:\n                print(\"PASSED - All relationship ID references are valid\")\n            return True\n\n    def _get_expected_relationship_type(self, element_name):\n        elem_lower = element_name.lower()\n\n        if elem_lower in self.ELEMENT_RELATIONSHIP_TYPES:\n            return self.ELEMENT_RELATIONSHIP_TYPES[elem_lower]\n\n        if elem_lower.endswith(\"id\") and len(elem_lower) > 2:\n            prefix = elem_lower[:-2]  \n            if prefix.endswith(\"master\"):\n                return prefix.lower()\n            elif prefix.endswith(\"layout\"):\n                return prefix.lower()\n            else:\n                if prefix == \"sld\":\n                    return \"slide\"\n                return prefix.lower()\n\n        if elem_lower.endswith(\"reference\") and len(elem_lower) > 9:\n            prefix = elem_lower[:-9]  \n            return prefix.lower()\n\n        return None\n\n    def validate_content_types(self):\n        errors = []\n\n        content_types_file = self.unpacked_dir / \"[Content_Types].xml\"\n        if not content_types_file.exists():\n            print(\"FAILED - [Content_Types].xml file not found\")\n            return False\n\n        try:\n            root = lxml.etree.parse(str(content_types_file)).getroot()\n            declared_parts = set()\n            declared_extensions = set()\n\n            for override in root.findall(\n                f\".//{{{self.CONTENT_TYPES_NAMESPACE}}}Override\"\n            ):\n                part_name = override.get(\"PartName\")\n                if part_name is not None:\n                    declared_parts.add(part_name.lstrip(\"/\"))\n\n            for default in root.findall(\n                f\".//{{{self.CONTENT_TYPES_NAMESPACE}}}Default\"\n            ):\n                extension = default.get(\"Extension\")\n                if extension is not None:\n                    declared_extensions.add(extension.lower())\n\n            declarable_roots = {\n                \"sld\",\n                \"sldLayout\",\n                \"sldMaster\",\n                \"presentation\",  \n                \"document\",  \n                \"workbook\",\n                \"worksheet\",  \n                \"theme\",  \n            }\n\n            media_extensions = {\n                \"png\": \"image/png\",\n                \"jpg\": \"image/jpeg\",\n                \"jpeg\": \"image/jpeg\",\n                \"gif\": \"image/gif\",\n                \"bmp\": \"image/bmp\",\n                \"tiff\": \"image/tiff\",\n                \"wmf\": \"image/x-wmf\",\n                \"emf\": \"image/x-emf\",\n            }\n\n            all_files = list(self.unpacked_dir.rglob(\"*\"))\n            all_files = [f for f in all_files if f.is_file()]\n\n            for xml_file in self.xml_files:\n                path_str = str(xml_file.relative_to(self.unpacked_dir)).replace(\n                    \"\\\\\", \"/\"\n                )\n\n                if any(\n                    skip in path_str\n                    for skip in [\".rels\", \"[Content_Types]\", \"docProps/\", \"_rels/\"]\n                ):\n                    continue\n\n                try:\n                    root_tag = lxml.etree.parse(str(xml_file)).getroot().tag\n                    root_name = root_tag.split(\"}\")[-1] if \"}\" in root_tag else root_tag\n\n                    if root_name in declarable_roots and path_str not in declared_parts:\n                        errors.append(\n                            f\"  {path_str}: File with <{root_name}> root not declared in [Content_Types].xml\"\n                        )\n\n                except Exception:\n                    continue  \n\n            for file_path in all_files:\n                if file_path.suffix.lower() in {\".xml\", \".rels\"}:\n                    continue\n                if file_path.name == \"[Content_Types].xml\":\n                    continue\n                if \"_rels\" in file_path.parts or \"docProps\" in file_path.parts:\n                    continue\n\n                extension = file_path.suffix.lstrip(\".\").lower()\n                if extension and extension not in declared_extensions:\n                    if extension in media_extensions:\n                        relative_path = file_path.relative_to(self.unpacked_dir)\n                        errors.append(\n                            f\'  {relative_path}: File with extension \\\'{extension}\\\' not declared in [Content_Types].xml - should add: <Default Extension=\"{extension}\" ContentType=\"{media_extensions[extension]}\"/>\'\n                        )\n\n        except Exception as e:\n            errors.append(f\"  Error parsing [Content_Types].xml: {e}\")\n\n        if errors:\n            print(f\"FAILED - Found {len(errors)} content type declaration errors:\")\n            for error in errors:\n                print(error)\n            return False\n        else:\n            if self.verbose:\n                print(\n                    \"PASSED - All content files are properly declared in [Content_Types].xml\"\n                )\n            return True\n\n    def validate_file_against_xsd(self, xml_file, verbose=False):\n        xml_file = Path(xml_file).resolve()\n        unpacked_dir = self.unpacked_dir.resolve()\n\n        is_valid, current_errors = self._validate_single_file_xsd(\n            xml_file, unpacked_dir\n        )\n\n        if is_valid is None:\n            return None, set()  \n        elif is_valid:\n            return True, set()  \n\n        original_errors = self._get_original_file_errors(xml_file)\n\n        assert current_errors is not None\n        new_errors = current_errors - original_errors\n\n        new_errors = {\n            e for e in new_errors\n            if not any(pattern in e for pattern in self.IGNORED_VALIDATION_ERRORS)\n        }\n\n        if new_errors:\n            if verbose:\n                relative_path = xml_file.relative_to(unpacked_dir)\n                print(f\"FAILED - {relative_path}: {len(new_errors)} new error(s)\")\n                for error in list(new_errors)[:3]:\n                    truncated = error[:250] + \"...\" if len(error) > 250 else error\n                    print(f\"  - {truncated}\")\n            return False, new_errors\n        else:\n            if verbose:\n                print(\n                    f\"PASSED - No new errors (original had {len(current_errors)} errors)\"\n                )\n            return True, set()\n\n    def validate_against_xsd(self):\n        new_errors = []\n        original_error_count = 0\n        valid_count = 0\n        skipped_count = 0\n\n        for xml_file in self.xml_files:\n            relative_path = str(xml_file.relative_to(self.unpacked_dir))\n            is_valid, new_file_errors = self.validate_file_against_xsd(\n                xml_file, verbose=False\n            )\n\n            if is_valid is None:\n                skipped_count += 1\n                continue\n            elif is_valid and not new_file_errors:\n                valid_count += 1\n                continue\n            elif is_valid:\n                original_error_count += 1\n                valid_count += 1\n                continue\n\n            new_errors.append(f\"  {relative_path}: {len(new_file_errors)} new error(s)\")\n            for error in list(new_file_errors)[:3]:  \n                new_errors.append(\n                    f\"    - {error[:250]}...\" if len(error) > 250 else f\"    - {error}\"\n                )\n\n        if self.verbose:\n            print(f\"Validated {len(self.xml_files)} files:\")\n            print(f\"  - Valid: {valid_count}\")\n            print(f\"  - Skipped (no schema): {skipped_count}\")\n            if original_error_count:\n                print(f\"  - With original errors (ignored): {original_error_count}\")\n            print(\n                f\"  - With NEW errors: {len(new_errors) > 0 and len([e for e in new_errors if not e.startswith(\'    \')]) or 0}\"\n            )\n\n        if new_errors:\n            print(\"\\nFAILED - Found NEW validation errors:\")\n            for error in new_errors:\n                print(error)\n            return False\n        else:\n            if self.verbose:\n                print(\"\\nPASSED - No new XSD validation errors introduced\")\n            return True\n\n    def _get_schema_path(self, xml_file):\n        if xml_file.name in self.SCHEMA_MAPPINGS:\n            return self.schemas_dir / self.SCHEMA_MAPPINGS[xml_file.name]\n\n        if xml_file.suffix == \".rels\":\n            return self.schemas_dir / self.SCHEMA_MAPPINGS[\".rels\"]\n\n        if \"charts/\" in str(xml_file) and xml_file.name.startswith(\"chart\"):\n            return self.schemas_dir / self.SCHEMA_MAPPINGS[\"chart\"]\n\n        if \"theme/\" in str(xml_file) and xml_file.name.startswith(\"theme\"):\n            return self.schemas_dir / self.SCHEMA_MAPPINGS[\"theme\"]\n\n        if xml_file.parent.name in self.MAIN_CONTENT_FOLDERS:\n            return self.schemas_dir / self.SCHEMA_MAPPINGS[xml_file.parent.name]\n\n        return None\n\n    def _clean_ignorable_namespaces(self, xml_doc):\n        xml_string = lxml.etree.tostring(xml_doc, encoding=\"unicode\")\n        xml_copy = lxml.etree.fromstring(xml_string)\n\n        for elem in xml_copy.iter():\n            attrs_to_remove = []\n\n            for attr in elem.attrib:\n                if \"{\" in attr:\n                    ns = attr.split(\"}\")[0][1:]\n                    if ns not in self.OOXML_NAMESPACES:\n                        attrs_to_remove.append(attr)\n\n            for attr in attrs_to_remove:\n                del elem.attrib[attr]\n\n        self._remove_ignorable_elements(xml_copy)\n\n        return lxml.etree.ElementTree(xml_copy)\n\n    def _remove_ignorable_elements(self, root):\n        elements_to_remove = []\n\n        for elem in list(root):\n            if not hasattr(elem, \"tag\") or callable(elem.tag):\n                continue\n\n            tag_str = str(elem.tag)\n            if tag_str.startswith(\"{\"):\n                ns = tag_str.split(\"}\")[0][1:]\n                if ns not in self.OOXML_NAMESPACES:\n                    elements_to_remove.append(elem)\n                    continue\n\n            self._remove_ignorable_elements(elem)\n\n        for elem in elements_to_remove:\n            root.remove(elem)\n\n    def _preprocess_for_mc_ignorable(self, xml_doc):\n        root = xml_doc.getroot()\n\n        if f\"{{{self.MC_NAMESPACE}}}Ignorable\" in root.attrib:\n            del root.attrib[f\"{{{self.MC_NAMESPACE}}}Ignorable\"]\n\n        return xml_doc\n\n    def _validate_single_file_xsd(self, xml_file, base_path):\n        schema_path = self._get_schema_path(xml_file)\n        if not schema_path:\n            return None, None  \n\n        try:\n            with open(schema_path, \"rb\") as xsd_file:\n                parser = lxml.etree.XMLParser()\n                xsd_doc = lxml.etree.parse(\n                    xsd_file, parser=parser, base_url=str(schema_path)\n                )\n                schema = lxml.etree.XMLSchema(xsd_doc)\n\n            with open(xml_file, \"r\") as f:\n                xml_doc = lxml.etree.parse(f)\n\n            xml_doc, _ = self._remove_template_tags_from_text_nodes(xml_doc)\n            xml_doc = self._preprocess_for_mc_ignorable(xml_doc)\n\n            relative_path = xml_file.relative_to(base_path)\n            if (\n                relative_path.parts\n                and relative_path.parts[0] in self.MAIN_CONTENT_FOLDERS\n            ):\n                xml_doc = self._clean_ignorable_namespaces(xml_doc)\n\n            if schema.validate(xml_doc):\n                return True, set()\n            else:\n                errors = set()\n                for error in schema.error_log:\n                    errors.add(error.message)\n                return False, errors\n\n        except Exception as e:\n            return False, {str(e)}\n\n    def _get_original_file_errors(self, xml_file):\n        if self.original_file is None:\n            return set()\n\n        import tempfile\n        import zipfile\n\n        xml_file = Path(xml_file).resolve()\n        unpacked_dir = self.unpacked_dir.resolve()\n        relative_path = xml_file.relative_to(unpacked_dir)\n\n        with tempfile.TemporaryDirectory() as temp_dir:\n            temp_path = Path(temp_dir)\n\n            with zipfile.ZipFile(self.original_file, \"r\") as zip_ref:\n                zip_ref.extractall(temp_path)\n\n            original_xml_file = temp_path / relative_path\n\n            if not original_xml_file.exists():\n                return set()\n\n            is_valid, errors = self._validate_single_file_xsd(\n                original_xml_file, temp_path\n            )\n            return errors if errors else set()\n\n    def _remove_template_tags_from_text_nodes(self, xml_doc):\n        warnings = []\n        template_pattern = re.compile(r\"\\{\\{[^}]*\\}\\}\")\n\n        xml_string = lxml.etree.tostring(xml_doc, encoding=\"unicode\")\n        xml_copy = lxml.etree.fromstring(xml_string)\n\n        def process_text_content(text, content_type):\n            if not text:\n                return text\n            matches = list(template_pattern.finditer(text))\n            if matches:\n                for match in matches:\n                    warnings.append(\n                        f\"Found template tag in {content_type}: {match.group()}\"\n                    )\n                return template_pattern.sub(\"\", text)\n            return text\n\n        for elem in xml_copy.iter():\n            if not hasattr(elem, \"tag\") or callable(elem.tag):\n                continue\n            tag_str = str(elem.tag)\n            if tag_str.endswith(\"}t\") or tag_str == \"t\":\n                continue\n\n            elem.text = process_text_content(elem.text, \"text content\")\n            elem.tail = process_text_content(elem.tail, \"tail content\")\n\n        return lxml.etree.ElementTree(xml_copy), warnings\n\n\nif __name__ == \"__main__\":\n    raise RuntimeError(\"This module should not be run directly.\")\n','fd8b4f0bf6c070363709936542cecc3b','2026-10-26 11:21:56','2026-10-26 11:21:56','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(667,'enc.736372697074732f6f66666963652f736368656d61732f65636d612f666f7574682d65646974696f6e2f6f70632d72656c6174696f6e73686970732e787364','skill_enc.646f6378__enc.302e302e31','','83c1e2da90194b600688463398a125fd','2026-10-26 11:21:56','2026-10-26 11:21:56','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(668,'resource_config_SOUL__md.json','agentspec__enc.656e67696e656572696e672d61692d656e67696e656572__enc.302e302e31','{\"name\":\"SOUL.md\",\"type\":\"config\",\"content\":\"## 你的身份与记忆\\n\\n- **角色**：机器学习工程师与 AI 系统架构师\\n- **个性**：务实、数据驱动、对\\\"炼丹玄学\\\"保持警惕、追求可复现性\\n- **记忆**：你记住每一次模型上线后 P0 故障的根因、每一个训练跑飞的 debug 过程、每一种 serving 架构的吞吐上限\\n- **经验**：你经历过 GPU 集群半夜挂掉导致训练白跑、模型精度在线上诡异下降、推理延迟超标被业务方追着催的场景\\n\\n## 关键规则\\n\\n### 工程纪律\\n\\n- 训练代码必须可复现——随机种子、环境依赖、数据版本全部锁定\\n- 模型上线前必须过 shadow mode，对比线上 baseline\\n- 推理服务必须有降级策略：模型挂了，兜底逻辑要顶上\\n- 不在生产环境用 `model.eval()` 没调的模型\\n- GPU 资源按需申请，训练完及时释放，别当矿主\\n\\n## 沟通风格\\n\\n- **数据说话**：\\\"这个模型在测试集上 F1 是 0.92，但线上真实数据的分布偏移导致实际只有 0.78，需要重新采样训练集\\\"\\n- **务实选型**：\\\"这个场景用 BERT-base 就够了，GPT-4 的效果只好 2 个点但成本高 50 倍\\\"\\n- **风险预警**：\\\"训练数据里有 30% 是去年的，分布已经漂了，上线前必须更新\\\"\\n\\n\",\"metadata\":{\"uniformId\":1792984915746},\"resourceIdentifier\":\"config::SOUL.md\"}','1e9b21993678f09e2b3ec678fbed9d90','2026-10-26 11:21:56','2026-10-26 11:21:56','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(669,'enc.736372697074732f6f66666963652f76616c696461746f72732f626173652e7079','skill_enc.646f6378__enc.302e302e31','\"\"\"\nBase validator with common validation logic for document files.\n\"\"\"\n\nimport re\nfrom pathlib import Path\n\nimport defusedxml.minidom\nimport lxml.etree\n\n\nclass BaseSchemaValidator:\n\n    IGNORED_VALIDATION_ERRORS = [\n        \"hyphenationZone\",\n        \"purl.org/dc/terms\",\n    ]\n\n    UNIQUE_ID_REQUIREMENTS = {\n        \"comment\": (\"id\", \"file\"),  \n        \"commentrangestart\": (\"id\", \"file\"),  \n        \"commentrangeend\": (\"id\", \"file\"),  \n        \"bookmarkstart\": (\"id\", \"file\"),  \n        \"bookmarkend\": (\"id\", \"file\"),  \n        \"sldid\": (\"id\", \"file\"),  \n        \"sldmasterid\": (\"id\", \"global\"),  \n        \"sldlayoutid\": (\"id\", \"global\"),  \n        \"cm\": (\"authorid\", \"file\"),  \n        \"sheet\": (\"sheetid\", \"file\"),  \n        \"definedname\": (\"id\", \"file\"),  \n        \"cxnsp\": (\"id\", \"file\"),  \n        \"sp\": (\"id\", \"file\"),  \n        \"pic\": (\"id\", \"file\"),  \n        \"grpsp\": (\"id\", \"file\"),  \n    }\n\n    EXCLUDED_ID_CONTAINERS = {\n        \"sectionlst\",  \n    }\n\n    ELEMENT_RELATIONSHIP_TYPES = {}\n\n    SCHEMA_MAPPINGS = {\n        \"word\": \"ISO-IEC29500-4_2016/wml.xsd\",  \n        \"ppt\": \"ISO-IEC29500-4_2016/pml.xsd\",  \n        \"xl\": \"ISO-IEC29500-4_2016/sml.xsd\",  \n        \"[Content_Types].xml\": \"ecma/fouth-edition/opc-contentTypes.xsd\",\n        \"app.xml\": \"ISO-IEC29500-4_2016/shared-documentPropertiesExtended.xsd\",\n        \"core.xml\": \"ecma/fouth-edition/opc-coreProperties.xsd\",\n        \"custom.xml\": \"ISO-IEC29500-4_2016/shared-documentPropertiesCustom.xsd\",\n        \".rels\": \"ecma/fouth-edition/opc-relationships.xsd\",\n        \"people.xml\": \"microsoft/wml-2012.xsd\",\n        \"commentsIds.xml\": \"microsoft/wml-cid-2016.xsd\",\n        \"commentsExtensible.xml\": \"microsoft/wml-cex-2018.xsd\",\n        \"commentsExtended.xml\": \"microsoft/wml-2012.xsd\",\n        \"chart\": \"ISO-IEC29500-4_2016/dml-chart.xsd\",\n        \"theme\": \"ISO-IEC29500-4_2016/dml-main.xsd\",\n        \"drawing\": \"ISO-IEC29500-4_2016/dml-main.xsd\",\n    }\n\n    MC_NAMESPACE = \"http://schemas.openxmlformats.org/markup-compatibility/2006\"\n    XML_NAMESPACE = \"http://www.w3.org/XML/1998/namespace\"\n\n    PACKAGE_RELATIONSHIPS_NAMESPACE = (\n        \"http://schemas.openxmlformats.org/package/2006/relationships\"\n    )\n    OFFICE_RELATIONSHIPS_NAMESPACE = (\n        \"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"\n    )\n    CONTENT_TYPES_NAMESPACE = (\n        \"http://schemas.openxmlformats.org/package/2006/content-types\"\n    )\n\n    MAIN_CONTENT_FOLDERS = {\"word\", \"ppt\", \"xl\"}\n\n    OOXML_NAMESPACES = {\n        \"http://schemas.openxmlformats.org/officeDocument/2006/math\",\n        \"http://schemas.openxmlformats.org/officeDocument/2006/relationships\",\n        \"http://schemas.openxmlformats.org/schemaLibrary/2006/main\",\n        \"http://schemas.openxmlformats.org/drawingml/2006/main\",\n        \"http://schemas.openxmlformats.org/drawingml/2006/chart\",\n        \"http://schemas.openxmlformats.org/drawingml/2006/chartDrawing\",\n        \"http://schemas.openxmlformats.org/drawingml/2006/diagram\",\n        \"http://schemas.openxmlformats.org/drawingml/2006/picture\",\n        \"http://schemas.openxmlformats.org/drawingml/2006/spreadsheetDrawing\",\n        \"http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing\",\n        \"http://schemas.openxmlformats.org/wordprocessingml/2006/main\",\n        \"http://schemas.openxmlformats.org/presentationml/2006/main\",\n        \"http://schemas.openxmlformats.org/spreadsheetml/2006/main\",\n        \"http://schemas.openxmlformats.org/officeDocument/2006/sharedTypes\",\n        \"http://www.w3.org/XML/1998/namespace\",\n    }\n\n    def __init__(self, unpacked_dir, original_file=None, verbose=False):\n        self.unpacked_dir = Path(unpacked_dir).resolve()\n        self.original_file = Path(original_file) if original_file else None\n        self.verbose = verbose\n\n        self.schemas_dir = Path(__file__).parent.parent / \"schemas\"\n\n        patterns = [\"*.xml\", \"*.rels\"]\n        self.xml_files = [\n            f for pattern in patterns for f in self.unpacked_dir.rglob(pattern)\n        ]\n\n        if not self.xml_files:\n            print(f\"Warning: No XML files found in {self.unpacked_dir}\")\n\n    def validate(self):\n        raise NotImplementedError(\"Subclasses must implement the validate method\")\n\n    def repair(self) -> int:\n        return self.repair_whitespace_preservation()\n\n    def repair_whitespace_preservation(self) -> int:\n        repairs = 0\n\n        for xml_file in self.xml_files:\n            try:\n                content = xml_file.read_text(encoding=\"utf-8\")\n                dom = defusedxml.minidom.parseString(content)\n                modified = False\n\n                for elem in dom.getElementsByTagName(\"*\"):\n                    if elem.tagName.endswith(\":t\") and elem.firstChild:\n                        text = elem.firstChild.nodeValue\n                        if text and (text.startswith((\' \', \'\\t\')) or text.endswith((\' \', \'\\t\'))):\n                            if elem.getAttribute(\"xml:space\") != \"preserve\":\n                                elem.setAttribute(\"xml:space\", \"preserve\")\n                                text_preview = repr(text[:30]) + \"...\" if len(text) > 30 else repr(text)\n                                print(f\"  Repaired: {xml_file.name}: Added xml:space=\'preserve\' to {elem.tagName}: {text_preview}\")\n                                repairs += 1\n                                modified = True\n\n                if modified:\n                    xml_file.write_bytes(dom.toxml(encoding=\"UTF-8\"))\n\n            except Exception:\n                pass\n\n        return repairs\n\n    def validate_xml(self):\n        errors = []\n\n        for xml_file in self.xml_files:\n            try:\n                lxml.etree.parse(str(xml_file))\n            except lxml.etree.XMLSyntaxError as e:\n                errors.append(\n                    f\"  {xml_file.relative_to(self.unpacked_dir)}: \"\n                    f\"Line {e.lineno}: {e.msg}\"\n                )\n            except Exception as e:\n                errors.append(\n                    f\"  {xml_file.relative_to(self.unpacked_dir)}: \"\n                    f\"Unexpected error: {str(e)}\"\n                )\n\n        if errors:\n            print(f\"FAILED - Found {len(errors)} XML violations:\")\n            for error in errors:\n                print(error)\n            return False\n        else:\n            if self.verbose:\n                print(\"PASSED - All XML files are well-formed\")\n            return True\n\n    def validate_namespaces(self):\n        errors = []\n\n        for xml_file in self.xml_files:\n            try:\n                root = lxml.etree.parse(str(xml_file)).getroot()\n                declared = set(root.nsmap.keys()) - {None}  \n\n                for attr_val in [\n                    v for k, v in root.attrib.items() if k.endswith(\"Ignorable\")\n                ]:\n                    undeclared = set(attr_val.split()) - declared\n                    errors.extend(\n                        f\"  {xml_file.relative_to(self.unpacked_dir)}: \"\n                        f\"Namespace \'{ns}\' in Ignorable but not declared\"\n                        for ns in undeclared\n                    )\n            except lxml.etree.XMLSyntaxError:\n                continue\n\n        if errors:\n            print(f\"FAILED - {len(errors)} namespace issues:\")\n            for error in errors:\n                print(error)\n            return False\n        if self.verbose:\n            print(\"PASSED - All namespace prefixes properly declared\")\n        return True\n\n    def validate_unique_ids(self):\n        errors = []\n        global_ids = {}  \n\n        for xml_file in self.xml_files:\n            try:\n                root = lxml.etree.parse(str(xml_file)).getroot()\n                file_ids = {}  \n\n                mc_elements = root.xpath(\n                    \".//mc:AlternateContent\", namespaces={\"mc\": self.MC_NAMESPACE}\n                )\n                for elem in mc_elements:\n                    elem.getparent().remove(elem)\n\n                for elem in root.iter():\n                    tag = (\n                        elem.tag.split(\"}\")[-1].lower()\n                        if \"}\" in elem.tag\n                        else elem.tag.lower()\n                    )\n\n                    if tag in self.UNIQUE_ID_REQUIREMENTS:\n                        in_excluded_container = any(\n                            ancestor.tag.split(\"}\")[-1].lower() in self.EXCLUDED_ID_CONTAINERS\n                            for ancestor in elem.iterancestors()\n                        )\n                        if in_excluded_container:\n                            continue\n\n                        attr_name, scope = self.UNIQUE_ID_REQUIREMENTS[tag]\n\n                        id_value = None\n                        for attr, value in elem.attrib.items():\n                            attr_local = (\n                                attr.split(\"}\")[-1].lower()\n                                if \"}\" in attr\n                                else attr.lower()\n                            )\n                            if attr_local == attr_name:\n                                id_value = value\n                                break\n\n                        if id_value is not None:\n                            if scope == \"global\":\n                                if id_value in global_ids:\n                                    prev_file, prev_line, prev_tag = global_ids[\n                                        id_value\n                                    ]\n                                    errors.append(\n                                        f\"  {xml_file.relative_to(self.unpacked_dir)}: \"\n                                        f\"Line {elem.sourceline}: Global ID \'{id_value}\' in <{tag}> \"\n                                        f\"already used in {prev_file} at line {prev_line} in <{prev_tag}>\"\n                                    )\n                                else:\n                                    global_ids[id_value] = (\n                                        xml_file.relative_to(self.unpacked_dir),\n                                        elem.sourceline,\n                                        tag,\n                                    )\n                            elif scope == \"file\":\n                                key = (tag, attr_name)\n                                if key not in file_ids:\n                                    file_ids[key] = {}\n\n                                if id_value in file_ids[key]:\n                                    prev_line = file_ids[key][id_value]\n                                    errors.append(\n                                        f\"  {xml_file.relative_to(self.unpacked_dir)}: \"\n                                        f\"Line {elem.sourceline}: Duplicate {attr_name}=\'{id_value}\' in <{tag}> \"\n                                        f\"(first occurrence at line {prev_line})\"\n                                    )\n                                else:\n                                    file_ids[key][id_value] = elem.sourceline\n\n            except (lxml.etree.XMLSyntaxError, Exception) as e:\n                errors.append(\n                    f\"  {xml_file.relative_to(self.unpacked_dir)}: Error: {e}\"\n                )\n\n        if errors:\n            print(f\"FAILED - Found {len(errors)} ID uniqueness violations:\")\n            for error in errors:\n                print(error)\n            return False\n        else:\n            if self.verbose:\n                print(\"PASSED - All required IDs are unique\")\n            return True\n\n    def validate_file_references(self):\n        errors = []\n\n        rels_files = list(self.unpacked_dir.rglob(\"*.rels\"))\n\n        if not rels_files:\n            if self.verbose:\n                print(\"PASSED - No .rels files found\")\n            return True\n\n        all_files = []\n        for file_path in self.unpacked_dir.rglob(\"*\"):\n            if (\n                file_path.is_file()\n                and file_path.name != \"[Content_Types].xml\"\n                and not file_path.name.endswith(\".rels\")\n            ):  \n                all_files.append(file_path.resolve())\n\n        all_referenced_files = set()\n\n        if self.verbose:\n            print(\n                f\"Found {len(rels_files)} .rels files and {len(all_files)} target files\"\n            )\n\n        for rels_file in rels_files:\n            try:\n                rels_root = lxml.etree.parse(str(rels_file)).getroot()\n\n                rels_dir = rels_file.parent\n\n                referenced_files = set()\n                broken_refs = []\n\n                for rel in rels_root.findall(\n                    \".//ns:Relationship\",\n                    namespaces={\"ns\": self.PACKAGE_RELATIONSHIPS_NAMESPACE},\n                ):\n                    target = rel.get(\"Target\")\n                    if target and not target.startswith(\n                        (\"http\", \"mailto:\")\n                    ):  \n                        if target.startswith(\"/\"):\n                            target_path = self.unpacked_dir / target.lstrip(\"/\")\n                        elif rels_file.name == \".rels\":\n                            target_path = self.unpacked_dir / target\n                        else:\n                            base_dir = rels_dir.parent\n                            target_path = base_dir / target\n\n                        try:\n                            target_path = target_path.resolve()\n                            if target_path.exists() and target_path.is_file():\n                                referenced_files.add(target_path)\n                                all_referenced_files.add(target_path)\n                            else:\n                                broken_refs.append((target, rel.sourceline))\n                        except (OSError, ValueError):\n                            broken_refs.append((target, rel.sourceline))\n\n                if broken_refs:\n                    rel_path = rels_file.relative_to(self.unpacked_dir)\n                    for broken_ref, line_num in broken_refs:\n                        errors.append(\n                            f\"  {rel_path}: Line {line_num}: Broken reference to {broken_ref}\"\n                        )\n\n            except Exception as e:\n                rel_path = rels_file.relative_to(self.unpacked_dir)\n                errors.append(f\"  Error parsing {rel_path}: {e}\")\n\n        unreferenced_files = set(all_files) - all_referenced_files\n\n        if unreferenced_files:\n            for unref_file in sorted(unreferenced_files):\n                unref_rel_path = unref_file.relative_to(self.unpacked_dir)\n                errors.append(f\"  Unreferenced file: {unref_rel_path}\")\n\n        if errors:\n            print(f\"FAILED - Found {len(errors)} relationship validation errors:\")\n            for error in errors:\n                print(error)\n            print(\n                \"CRITICAL: These errors will cause the document to appear corrupt. \"\n                + \"Broken references MUST be fixed, \"\n                + \"and unreferenced files MUST be referenced or removed.\"\n            )\n            return False\n        else:\n            if self.verbose:\n                print(\n                    \"PASSED - All references are valid and all files are properly referenced\"\n                )\n            return True\n\n    def validate_all_relationship_ids(self):\n        import lxml.etree\n\n        errors = []\n\n        for xml_file in self.xml_files:\n            if xml_file.suffix == \".rels\":\n                continue\n\n            rels_dir = xml_file.parent / \"_rels\"\n            rels_file = rels_dir / f\"{xml_file.name}.rels\"\n\n            if not rels_file.exists():\n                continue\n\n            try:\n                rels_root = lxml.etree.parse(str(rels_file)).getroot()\n                rid_to_type = {}\n\n                for rel in rels_root.findall(\n                    f\".//{{{self.PACKAGE_RELATIONSHIPS_NAMESPACE}}}Relationship\"\n                ):\n                    rid = rel.get(\"Id\")\n                    rel_type = rel.get(\"Type\", \"\")\n                    if rid:\n                        if rid in rid_to_type:\n                            rels_rel_path = rels_file.relative_to(self.unpacked_dir)\n                            errors.append(\n                                f\"  {rels_rel_path}: Line {rel.sourceline}: \"\n                                f\"Duplicate relationship ID \'{rid}\' (IDs must be unique)\"\n                            )\n                        type_name = (\n                            rel_type.split(\"/\")[-1] if \"/\" in rel_type else rel_type\n                        )\n                        rid_to_type[rid] = type_name\n\n                xml_root = lxml.etree.parse(str(xml_file)).getroot()\n\n                r_ns = self.OFFICE_RELATIONSHIPS_NAMESPACE\n                rid_attrs_to_check = [\"id\", \"embed\", \"link\"]\n                for elem in xml_root.iter():\n                    for attr_name in rid_attrs_to_check:\n                        rid_attr = elem.get(f\"{{{r_ns}}}{attr_name}\")\n                        if not rid_attr:\n                            continue\n                        xml_rel_path = xml_file.relative_to(self.unpacked_dir)\n                        elem_name = (\n                            elem.tag.split(\"}\")[-1] if \"}\" in elem.tag else elem.tag\n                        )\n\n                        if rid_attr not in rid_to_type:\n                            errors.append(\n                                f\"  {xml_rel_path}: Line {elem.sourceline}: \"\n                                f\"<{elem_name}> r:{attr_name} references non-existent relationship \'{rid_attr}\' \"\n                                f\"(valid IDs: {\', \'.join(sorted(rid_to_type.keys())[:5])}{\'...\' if len(rid_to_type) > 5 else \'\'})\"\n                            )\n                        elif attr_name == \"id\" and self.ELEMENT_RELATIONSHIP_TYPES:\n                            expected_type = self._get_expected_relationship_type(\n                                elem_name\n                            )\n                            if expected_type:\n                                actual_type = rid_to_type[rid_attr]\n                                if expected_type not in actual_type.lower():\n                                    errors.append(\n                                        f\"  {xml_rel_path}: Line {elem.sourceline}: \"\n                                        f\"<{elem_name}> references \'{rid_attr}\' which points to \'{actual_type}\' \"\n                                        f\"but should point to a \'{expected_type}\' relationship\"\n                                    )\n\n            except Exception as e:\n                xml_rel_path = xml_file.relative_to(self.unpacked_dir)\n                errors.append(f\"  Error processing {xml_rel_path}: {e}\")\n\n        if errors:\n            print(f\"FAILED - Found {len(errors)} relationship ID reference errors:\")\n            for error in errors:\n                print(error)\n            print(\"\\nThese ID mismatches will cause the document to appear corrupt!\")\n            return False\n        else:\n            if self.verbose:\n                print(\"PASSED - All relationship ID references are valid\")\n            return True\n\n    def _get_expected_relationship_type(self, element_name):\n        elem_lower = element_name.lower()\n\n        if elem_lower in self.ELEMENT_RELATIONSHIP_TYPES:\n            return self.ELEMENT_RELATIONSHIP_TYPES[elem_lower]\n\n        if elem_lower.endswith(\"id\") and len(elem_lower) > 2:\n            prefix = elem_lower[:-2]  \n            if prefix.endswith(\"master\"):\n                return prefix.lower()\n            elif prefix.endswith(\"layout\"):\n                return prefix.lower()\n            else:\n                if prefix == \"sld\":\n                    return \"slide\"\n                return prefix.lower()\n\n        if elem_lower.endswith(\"reference\") and len(elem_lower) > 9:\n            prefix = elem_lower[:-9]  \n            return prefix.lower()\n\n        return None\n\n    def validate_content_types(self):\n        errors = []\n\n        content_types_file = self.unpacked_dir / \"[Content_Types].xml\"\n        if not content_types_file.exists():\n            print(\"FAILED - [Content_Types].xml file not found\")\n            return False\n\n        try:\n            root = lxml.etree.parse(str(content_types_file)).getroot()\n            declared_parts = set()\n            declared_extensions = set()\n\n            for override in root.findall(\n                f\".//{{{self.CONTENT_TYPES_NAMESPACE}}}Override\"\n            ):\n                part_name = override.get(\"PartName\")\n                if part_name is not None:\n                    declared_parts.add(part_name.lstrip(\"/\"))\n\n            for default in root.findall(\n                f\".//{{{self.CONTENT_TYPES_NAMESPACE}}}Default\"\n            ):\n                extension = default.get(\"Extension\")\n                if extension is not None:\n                    declared_extensions.add(extension.lower())\n\n            declarable_roots = {\n                \"sld\",\n                \"sldLayout\",\n                \"sldMaster\",\n                \"presentation\",  \n                \"document\",  \n                \"workbook\",\n                \"worksheet\",  \n                \"theme\",  \n            }\n\n            media_extensions = {\n                \"png\": \"image/png\",\n                \"jpg\": \"image/jpeg\",\n                \"jpeg\": \"image/jpeg\",\n                \"gif\": \"image/gif\",\n                \"bmp\": \"image/bmp\",\n                \"tiff\": \"image/tiff\",\n                \"wmf\": \"image/x-wmf\",\n                \"emf\": \"image/x-emf\",\n            }\n\n            all_files = list(self.unpacked_dir.rglob(\"*\"))\n            all_files = [f for f in all_files if f.is_file()]\n\n            for xml_file in self.xml_files:\n                path_str = str(xml_file.relative_to(self.unpacked_dir)).replace(\n                    \"\\\\\", \"/\"\n                )\n\n                if any(\n                    skip in path_str\n                    for skip in [\".rels\", \"[Content_Types]\", \"docProps/\", \"_rels/\"]\n                ):\n                    continue\n\n                try:\n                    root_tag = lxml.etree.parse(str(xml_file)).getroot().tag\n                    root_name = root_tag.split(\"}\")[-1] if \"}\" in root_tag else root_tag\n\n                    if root_name in declarable_roots and path_str not in declared_parts:\n                        errors.append(\n                            f\"  {path_str}: File with <{root_name}> root not declared in [Content_Types].xml\"\n                        )\n\n                except Exception:\n                    continue  \n\n            for file_path in all_files:\n                if file_path.suffix.lower() in {\".xml\", \".rels\"}:\n                    continue\n                if file_path.name == \"[Content_Types].xml\":\n                    continue\n                if \"_rels\" in file_path.parts or \"docProps\" in file_path.parts:\n                    continue\n\n                extension = file_path.suffix.lstrip(\".\").lower()\n                if extension and extension not in declared_extensions:\n                    if extension in media_extensions:\n                        relative_path = file_path.relative_to(self.unpacked_dir)\n                        errors.append(\n                            f\'  {relative_path}: File with extension \\\'{extension}\\\' not declared in [Content_Types].xml - should add: <Default Extension=\"{extension}\" ContentType=\"{media_extensions[extension]}\"/>\'\n                        )\n\n        except Exception as e:\n            errors.append(f\"  Error parsing [Content_Types].xml: {e}\")\n\n        if errors:\n            print(f\"FAILED - Found {len(errors)} content type declaration errors:\")\n            for error in errors:\n                print(error)\n            return False\n        else:\n            if self.verbose:\n                print(\n                    \"PASSED - All content files are properly declared in [Content_Types].xml\"\n                )\n            return True\n\n    def validate_file_against_xsd(self, xml_file, verbose=False):\n        xml_file = Path(xml_file).resolve()\n        unpacked_dir = self.unpacked_dir.resolve()\n\n        is_valid, current_errors = self._validate_single_file_xsd(\n            xml_file, unpacked_dir\n        )\n\n        if is_valid is None:\n            return None, set()  \n        elif is_valid:\n            return True, set()  \n\n        original_errors = self._get_original_file_errors(xml_file)\n\n        assert current_errors is not None\n        new_errors = current_errors - original_errors\n\n        new_errors = {\n            e for e in new_errors\n            if not any(pattern in e for pattern in self.IGNORED_VALIDATION_ERRORS)\n        }\n\n        if new_errors:\n            if verbose:\n                relative_path = xml_file.relative_to(unpacked_dir)\n                print(f\"FAILED - {relative_path}: {len(new_errors)} new error(s)\")\n                for error in list(new_errors)[:3]:\n                    truncated = error[:250] + \"...\" if len(error) > 250 else error\n                    print(f\"  - {truncated}\")\n            return False, new_errors\n        else:\n            if verbose:\n                print(\n                    f\"PASSED - No new errors (original had {len(current_errors)} errors)\"\n                )\n            return True, set()\n\n    def validate_against_xsd(self):\n        new_errors = []\n        original_error_count = 0\n        valid_count = 0\n        skipped_count = 0\n\n        for xml_file in self.xml_files:\n            relative_path = str(xml_file.relative_to(self.unpacked_dir))\n            is_valid, new_file_errors = self.validate_file_against_xsd(\n                xml_file, verbose=False\n            )\n\n            if is_valid is None:\n                skipped_count += 1\n                continue\n            elif is_valid and not new_file_errors:\n                valid_count += 1\n                continue\n            elif is_valid:\n                original_error_count += 1\n                valid_count += 1\n                continue\n\n            new_errors.append(f\"  {relative_path}: {len(new_file_errors)} new error(s)\")\n            for error in list(new_file_errors)[:3]:  \n                new_errors.append(\n                    f\"    - {error[:250]}...\" if len(error) > 250 else f\"    - {error}\"\n                )\n\n        if self.verbose:\n            print(f\"Validated {len(self.xml_files)} files:\")\n            print(f\"  - Valid: {valid_count}\")\n            print(f\"  - Skipped (no schema): {skipped_count}\")\n            if original_error_count:\n                print(f\"  - With original errors (ignored): {original_error_count}\")\n            print(\n                f\"  - With NEW errors: {len(new_errors) > 0 and len([e for e in new_errors if not e.startswith(\'    \')]) or 0}\"\n            )\n\n        if new_errors:\n            print(\"\\nFAILED - Found NEW validation errors:\")\n            for error in new_errors:\n                print(error)\n            return False\n        else:\n            if self.verbose:\n                print(\"\\nPASSED - No new XSD validation errors introduced\")\n            return True\n\n    def _get_schema_path(self, xml_file):\n        if xml_file.name in self.SCHEMA_MAPPINGS:\n            return self.schemas_dir / self.SCHEMA_MAPPINGS[xml_file.name]\n\n        if xml_file.suffix == \".rels\":\n            return self.schemas_dir / self.SCHEMA_MAPPINGS[\".rels\"]\n\n        if \"charts/\" in str(xml_file) and xml_file.name.startswith(\"chart\"):\n            return self.schemas_dir / self.SCHEMA_MAPPINGS[\"chart\"]\n\n        if \"theme/\" in str(xml_file) and xml_file.name.startswith(\"theme\"):\n            return self.schemas_dir / self.SCHEMA_MAPPINGS[\"theme\"]\n\n        if xml_file.parent.name in self.MAIN_CONTENT_FOLDERS:\n            return self.schemas_dir / self.SCHEMA_MAPPINGS[xml_file.parent.name]\n\n        return None\n\n    def _clean_ignorable_namespaces(self, xml_doc):\n        xml_string = lxml.etree.tostring(xml_doc, encoding=\"unicode\")\n        xml_copy = lxml.etree.fromstring(xml_string)\n\n        for elem in xml_copy.iter():\n            attrs_to_remove = []\n\n            for attr in elem.attrib:\n                if \"{\" in attr:\n                    ns = attr.split(\"}\")[0][1:]\n                    if ns not in self.OOXML_NAMESPACES:\n                        attrs_to_remove.append(attr)\n\n            for attr in attrs_to_remove:\n                del elem.attrib[attr]\n\n        self._remove_ignorable_elements(xml_copy)\n\n        return lxml.etree.ElementTree(xml_copy)\n\n    def _remove_ignorable_elements(self, root):\n        elements_to_remove = []\n\n        for elem in list(root):\n            if not hasattr(elem, \"tag\") or callable(elem.tag):\n                continue\n\n            tag_str = str(elem.tag)\n            if tag_str.startswith(\"{\"):\n                ns = tag_str.split(\"}\")[0][1:]\n                if ns not in self.OOXML_NAMESPACES:\n                    elements_to_remove.append(elem)\n                    continue\n\n            self._remove_ignorable_elements(elem)\n\n        for elem in elements_to_remove:\n            root.remove(elem)\n\n    def _preprocess_for_mc_ignorable(self, xml_doc):\n        root = xml_doc.getroot()\n\n        if f\"{{{self.MC_NAMESPACE}}}Ignorable\" in root.attrib:\n            del root.attrib[f\"{{{self.MC_NAMESPACE}}}Ignorable\"]\n\n        return xml_doc\n\n    def _validate_single_file_xsd(self, xml_file, base_path):\n        schema_path = self._get_schema_path(xml_file)\n        if not schema_path:\n            return None, None  \n\n        try:\n            with open(schema_path, \"rb\") as xsd_file:\n                parser = lxml.etree.XMLParser()\n                xsd_doc = lxml.etree.parse(\n                    xsd_file, parser=parser, base_url=str(schema_path)\n                )\n                schema = lxml.etree.XMLSchema(xsd_doc)\n\n            with open(xml_file, \"r\") as f:\n                xml_doc = lxml.etree.parse(f)\n\n            xml_doc, _ = self._remove_template_tags_from_text_nodes(xml_doc)\n            xml_doc = self._preprocess_for_mc_ignorable(xml_doc)\n\n            relative_path = xml_file.relative_to(base_path)\n            if (\n                relative_path.parts\n                and relative_path.parts[0] in self.MAIN_CONTENT_FOLDERS\n            ):\n                xml_doc = self._clean_ignorable_namespaces(xml_doc)\n\n            if schema.validate(xml_doc):\n                return True, set()\n            else:\n                errors = set()\n                for error in schema.error_log:\n                    errors.add(error.message)\n                return False, errors\n\n        except Exception as e:\n            return False, {str(e)}\n\n    def _get_original_file_errors(self, xml_file):\n        if self.original_file is None:\n            return set()\n\n        import tempfile\n        import zipfile\n\n        xml_file = Path(xml_file).resolve()\n        unpacked_dir = self.unpacked_dir.resolve()\n        relative_path = xml_file.relative_to(unpacked_dir)\n\n        with tempfile.TemporaryDirectory() as temp_dir:\n            temp_path = Path(temp_dir)\n\n            with zipfile.ZipFile(self.original_file, \"r\") as zip_ref:\n                zip_ref.extractall(temp_path)\n\n            original_xml_file = temp_path / relative_path\n\n            if not original_xml_file.exists():\n                return set()\n\n            is_valid, errors = self._validate_single_file_xsd(\n                original_xml_file, temp_path\n            )\n            return errors if errors else set()\n\n    def _remove_template_tags_from_text_nodes(self, xml_doc):\n        warnings = []\n        template_pattern = re.compile(r\"\\{\\{[^}]*\\}\\}\")\n\n        xml_string = lxml.etree.tostring(xml_doc, encoding=\"unicode\")\n        xml_copy = lxml.etree.fromstring(xml_string)\n\n        def process_text_content(text, content_type):\n            if not text:\n                return text\n            matches = list(template_pattern.finditer(text))\n            if matches:\n                for match in matches:\n                    warnings.append(\n                        f\"Found template tag in {content_type}: {match.group()}\"\n                    )\n                return template_pattern.sub(\"\", text)\n            return text\n\n        for elem in xml_copy.iter():\n            if not hasattr(elem, \"tag\") or callable(elem.tag):\n                continue\n            tag_str = str(elem.tag)\n            if tag_str.endswith(\"}t\") or tag_str == \"t\":\n                continue\n\n            elem.text = process_text_content(elem.text, \"text content\")\n            elem.tail = process_text_content(elem.tail, \"tail content\")\n\n        return lxml.etree.ElementTree(xml_copy), warnings\n\n\nif __name__ == \"__main__\":\n    raise RuntimeError(\"This module should not be run directly.\")\n','fd8b4f0bf6c070363709936542cecc3b','2026-10-26 11:21:56','2026-10-26 11:21:56','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(670,'resource_config_MEMORY__md.json','agentspec__enc.656e67696e656572696e672d61692d656e67696e656572__enc.302e302e31','{\"name\":\"MEMORY.md\",\"type\":\"config\",\"content\":\"# 长期记忆\\n\\n由运行时写入；本模板未预置业务记忆。\\n\",\"metadata\":{\"uniformId\":1792984915746},\"resourceIdentifier\":\"config::MEMORY.md\"}','58268f5e8b0a240f06aa47fab6d02aab','2026-10-26 11:21:56','2026-10-26 11:21:56','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(671,'resource_config_SOUL__md.json','agentspec__enc.656e67696e656572696e672d61692d656e67696e656572__enc.302e302e31','{\"name\":\"SOUL.md\",\"type\":\"config\",\"content\":\"## 你的身份与记忆\\n\\n- **角色**：机器学习工程师与 AI 系统架构师\\n- **个性**：务实、数据驱动、对\\\"炼丹玄学\\\"保持警惕、追求可复现性\\n- **记忆**：你记住每一次模型上线后 P0 故障的根因、每一个训练跑飞的 debug 过程、每一种 serving 架构的吞吐上限\\n- **经验**：你经历过 GPU 集群半夜挂掉导致训练白跑、模型精度在线上诡异下降、推理延迟超标被业务方追着催的场景\\n\\n## 关键规则\\n\\n### 工程纪律\\n\\n- 训练代码必须可复现——随机种子、环境依赖、数据版本全部锁定\\n- 模型上线前必须过 shadow mode，对比线上 baseline\\n- 推理服务必须有降级策略：模型挂了，兜底逻辑要顶上\\n- 不在生产环境用 `model.eval()` 没调的模型\\n- GPU 资源按需申请，训练完及时释放，别当矿主\\n\\n## 沟通风格\\n\\n- **数据说话**：\\\"这个模型在测试集上 F1 是 0.92，但线上真实数据的分布偏移导致实际只有 0.78，需要重新采样训练集\\\"\\n- **务实选型**：\\\"这个场景用 BERT-base 就够了，GPT-4 的效果只好 2 个点但成本高 50 倍\\\"\\n- **风险预警**：\\\"训练数据里有 30% 是去年的，分布已经漂了，上线前必须更新\\\"\\n\\n\",\"metadata\":{\"uniformId\":1792984915746},\"resourceIdentifier\":\"config::SOUL.md\"}','1e9b21993678f09e2b3ec678fbed9d90','2026-10-26 11:21:56','2026-10-26 11:21:56','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(672,'resource_config_MEMORY__md.json','agentspec__enc.656e67696e656572696e672d61692d656e67696e656572__enc.302e302e31','{\"name\":\"MEMORY.md\",\"type\":\"config\",\"content\":\"# 长期记忆\\n\\n由运行时写入；本模板未预置业务记忆。\\n\",\"metadata\":{\"uniformId\":1792984915746},\"resourceIdentifier\":\"config::MEMORY.md\"}','58268f5e8b0a240f06aa47fab6d02aab','2026-10-26 11:21:56','2026-10-26 11:21:56','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(673,'enc.736372697074732f6f66666963652f736368656d61732f6d6963726f736f66742f776d6c2d323031382e787364','skill_enc.646f6378__enc.302e302e31','','ba27663e14790ebbc5dd39ce48caf670','2026-10-26 11:21:56','2026-10-26 11:21:56','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(674,'enc.736372697074732f6f66666963652f736368656d61732f49534f2d49454332393530302d345f323031362f646d6c2d706963747572652e787364','skill_enc.646f6378__enc.302e302e31','','b4dd1b964ecce7e2a425b022068a556d','2026-10-26 11:21:56','2026-10-26 11:21:56','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(675,'enc.736372697074732f6f66666963652f736368656d61732f6d6963726f736f66742f776d6c2d323031382e787364','skill_enc.646f6378__enc.302e302e31','','ba27663e14790ebbc5dd39ce48caf670','2026-10-26 11:21:56','2026-10-26 11:21:56','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(676,'enc.736372697074732f6f66666963652f736368656d61732f49534f2d49454332393530302d345f323031362f766d6c2d6d61696e2e787364','skill_enc.646f6378__enc.302e302e31','','26a8d3552ba20d6ae290eaca673361ce','2026-10-26 11:21:56','2026-10-26 11:21:56','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(677,'enc.736372697074732f6f66666963652f736368656d61732f49534f2d49454332393530302d345f323031362f646d6c2d706963747572652e787364','skill_enc.646f6378__enc.302e302e31','','b4dd1b964ecce7e2a425b022068a556d','2026-10-26 11:21:56','2026-10-26 11:21:56','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(678,'manifest.json','agentspec__enc.656e67696e656572696e672d6175746f6e6f6d6f75732d6f7074696d697a6174696f6e2d617263686974656374__enc.302e302e31','{\"name\":\"engineering-autonomous-optimization-architect\",\"description\":\"智能系统治理专家，持续对 API 进行影子测试以优化性能，同时严格执行财务和