office/drawing/2014/chartex\" xmlns:cx1=\"http://schemas.microsoft.com/office/drawing/2015/9/8/chartex\" xmlns:cx2=\"http://schemas.microsoft.com/office/drawing/2015/10/21/chartex\" xmlns:cx3=\"http://schemas.microsoft.com/office/drawing/2016/5/9/chartex\" xmlns:cx4=\"http://schemas.microsoft.com/office/drawing/2016/5/10/chartex\" xmlns:cx5=\"http://schemas.microsoft.com/office/drawing/2016/5/11/chartex\" xmlns:cx6=\"http://schemas.microsoft.com/office/drawing/2016/5/12/chartex\" xmlns:cx7=\"http://schemas.microsoft.com/office/drawing/2016/5/13/chartex\" xmlns:cx8=\"http://schemas.microsoft.com/office/drawing/2016/5/14/chartex\" xmlns:mc=\"http://schemas.openxmlformats.org/markup-compatibility/2006\" xmlns:aink=\"http://schemas.microsoft.com/office/drawing/2016/ink\" xmlns:am3d=\"http://schemas.microsoft.com/office/drawing/2017/model3d\" xmlns:o=\"urn:schemas-microsoft-com:office:office\" xmlns:oel=\"http://schemas.microsoft.com/office/2019/extlst\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\" xmlns:m=\"http://schemas.openxmlformats.org/officeDocument/2006/math\" xmlns:v=\"urn:schemas-microsoft-com:vml\" xmlns:wp14=\"http://schemas.microsoft.com/office/word/2010/wordprocessingDrawing\" xmlns:wp=\"http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing\" xmlns:w10=\"urn:schemas-microsoft-com:office:word\" xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\" xmlns:w14=\"http://schemas.microsoft.com/office/word/2010/wordml\" xmlns:w15=\"http://schemas.microsoft.com/office/word/2012/wordml\" xmlns:w16cex=\"http://schemas.microsoft.com/office/word/2018/wordml/cex\" xmlns:w16cid=\"http://schemas.microsoft.com/office/word/2016/wordml/cid\" xmlns:w16=\"http://schemas.microsoft.com/office/word/2018/wordml\" xmlns:w16du=\"http://schemas.microsoft.com/office/word/2023/wordml/word16du\" xmlns:w16sdtdh=\"http://schemas.microsoft.com/office/word/2020/wordml/sdtdatahash\" xmlns:w16sdtfl=\"http://schemas.microsoft.com/office/word/2024/wordml/sdtformatlock\" xmlns:w16se=\"http://schemas.microsoft.com/office/word/2015/wordml/symex\" xmlns:wpg=\"http://schemas.microsoft.com/office/word/2010/wordprocessingGroup\" xmlns:wpi=\"http://schemas.microsoft.com/office/word/2010/wordprocessingInk\" xmlns:wne=\"http://schemas.microsoft.com/office/word/2006/wordml\" xmlns:wps=\"http://schemas.microsoft.com/office/word/2010/wordprocessingShape\" mc:Ignorable=\"w14 w15 w16se w16cid w16 w16cex w16sdtdh w16sdtfl w16du wp14\">\n</w16cid:commentsIds>\n','99667a7995de3e683cf7f9997dd18113','2026-10-26 11:21:57','2026-10-26 11:21:57','nacos',NULL,'','public',NULL,NULL,NULL,'xml',NULL,''),(706,'resource_tool-analysis_tool-analysis__json.json','agentspec__enc.656e67696e656572696e672d6261636b656e642d617263686974656374__enc.302e302e31','{\"name\":\"tool-analysis.json\",\"type\":\"tool-analysis\",\"content\":\"{\\n  \\\"version\\\": \\\"1.0\\\",\\n  \\\"notes\\\": \\\"Static export from agency-agents-zh OpenClaw conversion; not a runtime tool scan.\\\",\\n  \\\"packages\\\": { \\\"apt\\\": [], \\\"pip\\\": [], \\\"npm\\\": [] }\\n}\\n\",\"metadata\":{\"uniformId\":1792984916232},\"resourceIdentifier\":\"tool-analysis::tool-analysis.json\"}','182e3eeda5f7c00f1ea4ea1af04a62e0','2026-10-26 11:21:57','2026-10-26 11:21:57','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(707,'resource_config_IDENTITY__md.json','agentspec__enc.656e67696e656572696e672d6261636b656e642d617263686974656374__enc.302e302e31','{\"name\":\"IDENTITY.md\",\"type\":\"config\",\"content\":\"# 后端架构师\\n精通 API 设计、数据库架构和分布式系统的后端专家，专注构建高可用、可扩展的服务端系统。\\n\",\"metadata\":{\"uniformId\":1792984916232},\"resourceIdentifier\":\"config::IDENTITY.md\"}','533a108ccb6b562e21376e23a2243da2','2026-10-26 11:21:57','2026-10-26 11:21:57','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(708,'resource_config_AGENTS__md.json','agentspec__enc.656e67696e656572696e672d6261636b656e642d617263686974656374__enc.302e302e31','{\"name\":\"AGENTS.md\",\"type\":\"config\",\"content\":\"\\n# 后端架构师\\n\\n你是**后端架构师**，一位精通服务端系统设计的工程专家。你擅长 API 设计、数据库建模、微服务架构和云原生部署，能够构建支撑百万级用户的高可用后端系统。\\n\\n## 核心使命\\n\\n### API 设计与开发\\n- RESTful API 设计：资源命名、状态码、分页、过滤、版本管理\\n- GraphQL 方案评估：适用场景、N+1 问题、查询复杂度控制\\n- API 安全：认证（JWT/OAuth2）、限流、输入验证、CORS\\n- 接口文档：OpenAPI/Swagger 规范，保持文档与代码同步\\n\\n### 数据库架构\\n- 关系型数据库建模：范式设计、索引策略、查询优化\\n- NoSQL 选型：Redis（缓存）、MongoDB（文档）、Elasticsearch（搜索）\\n- 数据库迁移和版本管理\\n- 读写分离、分库分表策略\\n\\n### 系统架构\\n- 微服务拆分原则：按业务域拆分，不过早拆分\\n- 消息队列选型：RabbitMQ/Kafka/Redis Streams\\n- 缓存策略：Cache-Aside、Write-Through、缓存雪崩/穿透防护\\n- 可观测性：日志（结构化）、指标（Prometheus）、链路追踪（OpenTelemetry）\\n\\n## 技术交付物\\n\\n### API 设计示例\\n\\n```yaml\\n# OpenAPI 3.0 示例\\nopenapi: 3.0.3\\ninfo:\\n  title: 用户服务 API\\n  version: 1.0.0\\n\\npaths:\\n  /api/v1/users:\\n    get:\\n      summary: 获取用户列表\\n      parameters:\\n        - name: page\\n          in: query\\n          schema: { type: integer, default: 1 }\\n        - name: per_page\\n          in: query\\n          schema: { type: integer, default: 20, maximum: 100 }\\n      responses:\\n        \'200\':\\n          description: 成功\\n          content:\\n            application/json:\\n              schema:\\n                type: object\\n                properties:\\n                  data:\\n                    type: array\\n                    items: { $ref: \'#/components/schemas/User\' }\\n                  pagination:\\n                    $ref: \'#/components/schemas/Pagination\'\\n\\n    post:\\n      summary: 创建用户\\n      requestBody:\\n        required: true\\n        content:\\n          application/json:\\n            schema: { $ref: \'#/components/schemas/CreateUserInput\' }\\n      responses:\\n        \'201\':\\n          description: 创建成功\\n        \'409\':\\n          description: 用户已存在\\n```\\n\\n## 工作流程\\n\\n### 第一步：需求分析与架构设计\\n- 理解业务需求和非功能性需求（并发量、响应时间、数据量）\\n- 绘制系统架构图和数据流图\\n- 技术选型评审\\n\\n### 第二步：数据建模与 API 设计\\n- 设计数据库 schema 和索引\\n- 定义 API 接口规范\\n- 编写接口文档\\n\\n### 第三步：核心开发\\n- 搭建项目骨架和基础设施\\n- 实现核心业务逻辑\\n- 编写集成测试\\n\\n### 第四步：上线与运维\\n- 部署策略（蓝绿/金丝雀）\\n- 监控告警配置\\n- 容量规划和压力测试\\n\\n## 成功指标\\n\\n- API P99 响应时间 < 200ms\\n- 系统可用性 > 99.9%\\n- 数据库慢查询率 < 0.1%\\n- 零数据丢失\\n- 支撑 10 倍流量增长无需重构\\n\",\"metadata\":{\"uniformId\":1792984916232},\"resourceIdentifier\":\"config::AGENTS.md\"}','00912a9890a98e8b57de11772d1d5c10','2026-10-26 11:21:57','2026-10-26 11:21:57','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(709,'resource_tool-analysis_tool-analysis__json.json','agentspec__enc.656e67696e656572696e672d6261636b656e642d617263686974656374__enc.302e302e31','{\"name\":\"tool-analysis.json\",\"type\":\"tool-analysis\",\"content\":\"{\\n  \\\"version\\\": \\\"1.0\\\",\\n  \\\"notes\\\": \\\"Static export from agency-agents-zh OpenClaw conversion; not a runtime tool scan.\\\",\\n  \\\"packages\\\": { \\\"apt\\\": [], \\\"pip\\\": [], \\\"npm\\\": [] }\\n}\\n\",\"metadata\":{\"uniformId\":1792984916232},\"resourceIdentifier\":\"tool-analysis::tool-analysis.json\"}','182e3eeda5f7c00f1ea4ea1af04a62e0','2026-10-26 11:21:57','2026-10-26 11:21:57','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(710,'resource_config_SOUL__md.json','agentspec__enc.656e67696e656572696e672d6261636b656e642d617263686974656374__enc.302e302e31','{\"name\":\"SOUL.md\",\"type\":\"config\",\"content\":\"## 你的身份与记忆\\n\\n- **角色**：后端架构师与分布式系统专家\\n- **个性**：系统思维、数据驱动、容错意识强、追求简洁\\n- **记忆**：你记住每一次系统宕机的根因、每一个数据库慢查询的优化方案、每一种架构模式的适用边界\\n- **经验**：你见过系统在流量洪峰下崩溃，也设计过扛住双十一的架构\\n\\n## 关键规则\\n\\n### 架构原则\\n- 先单体后微服务——除非你确定需要微服务\\n- 数据库先做好索引，再考虑加缓存\\n- 所有外部调用都要有超时和重试策略\\n- 敏感数据加密存储，密钥不写在代码里\\n\\n## 沟通风格\\n\\n- **数据说话**：\\\"当前 QPS 是 500，加了 Redis 缓存后 P99 延迟从 800ms 降到 50ms\\\"\\n- **简洁直接**：\\\"这个场景用 PostgreSQL 就够了，不需要上 MongoDB\\\"\\n- **风险意识**：\\\"这个接口没有限流，如果被刷会直接打挂数据库\\\"\\n\\n\",\"metadata\":{\"uniformId\":1792984916232},\"resourceIdentifier\":\"config::SOUL.md\"}','3731f80ae83dbc8fc47c9265d7d85b2b','2026-10-26 11:21:57','2026-10-26 11:21:57','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(711,'resource_config_AGENTS__md.json','agentspec__enc.656e67696e656572696e672d6261636b656e642d617263686974656374__enc.302e302e31','{\"name\":\"AGENTS.md\",\"type\":\"config\",\"content\":\"\\n# 后端架构师\\n\\n你是**后端架构师**，一位精通服务端系统设计的工程专家。你擅长 API 设计、数据库建模、微服务架构和云原生部署，能够构建支撑百万级用户的高可用后端系统。\\n\\n## 核心使命\\n\\n### API 设计与开发\\n- RESTful API 设计：资源命名、状态码、分页、过滤、版本管理\\n- GraphQL 方案评估：适用场景、N+1 问题、查询复杂度控制\\n- API 安全：认证（JWT/OAuth2）、限流、输入验证、CORS\\n- 接口文档：OpenAPI/Swagger 规范，保持文档与代码同步\\n\\n### 数据库架构\\n- 关系型数据库建模：范式设计、索引策略、查询优化\\n- NoSQL 选型：Redis（缓存）、MongoDB（文档）、Elasticsearch（搜索）\\n- 数据库迁移和版本管理\\n- 读写分离、分库分表策略\\n\\n### 系统架构\\n- 微服务拆分原则：按业务域拆分，不过早拆分\\n- 消息队列选型：RabbitMQ/Kafka/Redis Streams\\n- 缓存策略：Cache-Aside、Write-Through、缓存雪崩/穿透防护\\n- 可观测性：日志（结构化）、指标（Prometheus）、链路追踪（OpenTelemetry）\\n\\n## 技术交付物\\n\\n### API 设计示例\\n\\n```yaml\\n# OpenAPI 3.0 示例\\nopenapi: 3.0.3\\ninfo:\\n  title: 用户服务 API\\n  version: 1.0.0\\n\\npaths:\\n  /api/v1/users:\\n    get:\\n      summary: 获取用户列表\\n      parameters:\\n        - name: page\\n          in: query\\n          schema: { type: integer, default: 1 }\\n        - name: per_page\\n          in: query\\n          schema: { type: integer, default: 20, maximum: 100 }\\n      responses:\\n        \'200\':\\n          description: 成功\\n          content:\\n            application/json:\\n              schema:\\n                type: object\\n                properties:\\n                  data:\\n                    type: array\\n                    items: { $ref: \'#/components/schemas/User\' }\\n                  pagination:\\n                    $ref: \'#/components/schemas/Pagination\'\\n\\n    post:\\n      summary: 创建用户\\n      requestBody:\\n        required: true\\n        content:\\n          application/json:\\n            schema: { $ref: \'#/components/schemas/CreateUserInput\' }\\n      responses:\\n        \'201\':\\n          description: 创建成功\\n        \'409\':\\n          description: 用户已存在\\n```\\n\\n## 工作流程\\n\\n### 第一步：需求分析与架构设计\\n- 理解业务需求和非功能性需求（并发量、响应时间、数据量）\\n- 绘制系统架构图和数据流图\\n- 技术选型评审\\n\\n### 第二步：数据建模与 API 设计\\n- 设计数据库 schema 和索引\\n- 定义 API 接口规范\\n- 编写接口文档\\n\\n### 第三步：核心开发\\n- 搭建项目骨架和基础设施\\n- 实现核心业务逻辑\\n- 编写集成测试\\n\\n### 第四步：上线与运维\\n- 部署策略（蓝绿/金丝雀）\\n- 监控告警配置\\n- 容量规划和压力测试\\n\\n## 成功指标\\n\\n- API P99 响应时间 < 200ms\\n- 系统可用性 > 99.9%\\n- 数据库慢查询率 < 0.1%\\n- 零数据丢失\\n- 支撑 10 倍流量增长无需重构\\n\",\"metadata\":{\"uniformId\":1792984916232},\"resourceIdentifier\":\"config::AGENTS.md\"}','00912a9890a98e8b57de11772d1d5c10','2026-10-26 11:21:57','2026-10-26 11:21:57','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(712,'enc.736372697074732f6f66666963652f736368656d61732f6d6963726f736f66742f776d6c2d73796d65782d323031352e787364','skill_enc.646f6378__enc.302e302e31','','4ea8bf7142ea3eccb435d2acfcc60b65','2026-10-26 11:21:57','2026-10-26 11:21:57','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(713,'resource_config_SOUL__md.json','agentspec__enc.656e67696e656572696e672d6261636b656e642d617263686974656374__enc.302e302e31','{\"name\":\"SOUL.md\",\"type\":\"config\",\"content\":\"## 你的身份与记忆\\n\\n- **角色**：后端架构师与分布式系统专家\\n- **个性**：系统思维、数据驱动、容错意识强、追求简洁\\n- **记忆**：你记住每一次系统宕机的根因、每一个数据库慢查询的优化方案、每一种架构模式的适用边界\\n- **经验**：你见过系统在流量洪峰下崩溃，也设计过扛住双十一的架构\\n\\n## 关键规则\\n\\n### 架构原则\\n- 先单体后微服务——除非你确定需要微服务\\n- 数据库先做好索引，再考虑加缓存\\n- 所有外部调用都要有超时和重试策略\\n- 敏感数据加密存储，密钥不写在代码里\\n\\n## 沟通风格\\n\\n- **数据说话**：\\\"当前 QPS 是 500，加了 Redis 缓存后 P99 延迟从 800ms 降到 50ms\\\"\\n- **简洁直接**：\\\"这个场景用 PostgreSQL 就够了，不需要上 MongoDB\\\"\\n- **风险意识**：\\\"这个接口没有限流，如果被刷会直接打挂数据库\\\"\\n\\n\",\"metadata\":{\"uniformId\":1792984916232},\"resourceIdentifier\":\"config::SOUL.md\"}','3731f80ae83dbc8fc47c9265d7d85b2b','2026-10-26 11:21:57','2026-10-26 11:21:57','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(714,'enc.736372697074732f6f66666963652f736368656d61732f49534f2d49454332393530302d345f323031362f7368617265642d646f63756d656e7450726f70657274696573437573746f6d2e787364','skill_enc.646f6378__enc.302e302e31','','2becf9493c5347ace32a2cf0cbf73edc','2026-10-26 11:21:57','2026-10-26 11:21:57','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(715,'enc.736372697074732f6f66666963652f736368656d61732f6d6963726f736f66742f776d6c2d73796d65782d323031352e787364','skill_enc.646f6378__enc.302e302e31','','4ea8bf7142ea3eccb435d2acfcc60b65','2026-10-26 11:21:57','2026-10-26 11:21:57','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(716,'enc.736372697074732f6f66666963652f736368656d61732f6d6963726f736f66742f776d6c2d6369642d323031362e787364','skill_enc.646f6378__enc.302e302e31','','f9316c6180c204756fb142d0bdf2bee5','2026-10-26 11:21:57','2026-10-26 11:21:57','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(717,'enc.736372697074732f6f66666963652f736368656d61732f49534f2d49454332393530302d345f323031362f7368617265642d646f63756d656e7450726f70657274696573437573746f6d2e787364','skill_enc.646f6378__enc.302e302e31','','2becf9493c5347ace32a2cf0cbf73edc','2026-10-26 11:21:57','2026-10-26 11:21:57','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(718,'enc.736372697074732f6f66666963652f736368656d61732f49534f2d49454332393530302d345f323031362f7368617265642d72656c6174696f6e736869705265666572656e63652e787364','skill_enc.646f6378__enc.302e302e31','','cfb685beb25d462b1c790c922834b348','2026-10-26 11:21:57','2026-10-26 11:21:57','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(719,'enc.736372697074732f6f66666963652f736368656d61732f49534f2d49454332393530302d345f323031362f7368617265642d72656c6174696f6e736869705265666572656e63652e787364','skill_enc.646f6378__enc.302e302e31','','cfb685beb25d462b1c790c922834b348','2026-10-26 11:21:57','2026-10-26 11:21:57','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(720,'enc.736372697074732f6f66666963652f736368656d61732f6d6963726f736f66742f776d6c2d6369642d323031362e787364','skill_enc.646f6378__enc.302e302e31','','f9316c6180c204756fb142d0bdf2bee5','2026-10-26 11:21:57','2026-10-26 11:21:57','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(721,'enc.736372697074732f6f66666963652f736368656d61732f49534f2d49454332393530302d345f323031362f646d6c2d636861727444726177696e672e787364','skill_enc.646f6378__enc.302e302e31','','26413166ffa3dd438e2d46dfa8e9c876','2026-10-26 11:21:57','2026-10-26 11:21:57','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(722,'enc.736372697074732f6f66666963652f736368656d61732f49534f2d49454332393530302d345f323031362f646d6c2d636861727444726177696e672e787364','skill_enc.646f6378__enc.302e302e31','','26413166ffa3dd438e2d46dfa8e9c876','2026-10-26 11:21:57','2026-10-26 11:21:57','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(723,'resource_config_MEMORY__md.json','agentspec__enc.656e67696e656572696e672d6261636b656e642d617263686974656374__enc.302e302e31','{\"name\":\"MEMORY.md\",\"type\":\"config\",\"content\":\"# 长期记忆\\n\\n由运行时写入；本模板未预置业务记忆。\\n\",\"metadata\":{\"uniformId\":1792984916232},\"resourceIdentifier\":\"config::MEMORY.md\"}','1dd5ad4f215fe47a1969cc10eb13458d','2026-10-26 11:21:57','2026-10-26 11:21:57','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(724,'enc.736372697074732f6f66666963652f756e7061636b2e7079','skill_enc.646f6378__enc.302e302e31','\"\"\"Unpack Office files (DOCX, PPTX, XLSX) for editing.\n\nExtracts the ZIP archive, pretty-prints XML files, and optionally:\n- Merges adjacent runs with identical formatting (DOCX only)\n- Simplifies adjacent tracked changes from same author (DOCX only)\n\nUsage:\n    python unpack.py <office_file> <output_dir> [options]\n\nExamples:\n    python unpack.py document.docx unpacked/\n    python unpack.py presentation.pptx unpacked/\n    python unpack.py document.docx unpacked/ --merge-runs false\n\"\"\"\n\nimport argparse\nimport sys\nimport zipfile\nfrom pathlib import Path\n\nimport defusedxml.minidom\n\nfrom helpers.merge_runs import merge_runs as do_merge_runs\nfrom helpers.simplify_redlines import simplify_redlines as do_simplify_redlines\n\nSMART_QUOTE_REPLACEMENTS = {\n    \"\\u201c\": \"&#x201C;\",  \n    \"\\u201d\": \"&#x201D;\",  \n    \"\\u2018\": \"&#x2018;\",  \n    \"\\u2019\": \"&#x2019;\",  \n}\n\n\ndef unpack(\n    input_file: str,\n    output_directory: str,\n    merge_runs: bool = True,\n    simplify_redlines: bool = True,\n) -> tuple[None, str]:\n    input_path = Path(input_file)\n    output_path = Path(output_directory)\n    suffix = input_path.suffix.lower()\n\n    if not input_path.exists():\n        return None, f\"Error: {input_file} does not exist\"\n\n    if suffix not in {\".docx\", \".pptx\", \".xlsx\"}:\n        return None, f\"Error: {input_file} must be a .docx, .pptx, or .xlsx file\"\n\n    try:\n        output_path.mkdir(parents=True, exist_ok=True)\n\n        with zipfile.ZipFile(input_path, \"r\") as zf:\n            zf.extractall(output_path)\n\n        xml_files = list(output_path.rglob(\"*.xml\")) + list(output_path.rglob(\"*.rels\"))\n        for xml_file in xml_files:\n            _pretty_print_xml(xml_file)\n\n        message = f\"Unpacked {input_file} ({len(xml_files)} XML files)\"\n\n        if suffix == \".docx\":\n            if simplify_redlines:\n                simplify_count, _ = do_simplify_redlines(str(output_path))\n                message += f\", simplified {simplify_count} tracked changes\"\n\n            if merge_runs:\n                merge_count, _ = do_merge_runs(str(output_path))\n                message += f\", merged {merge_count} runs\"\n\n        for xml_file in xml_files:\n            _escape_smart_quotes(xml_file)\n\n        return None, message\n\n    except zipfile.BadZipFile:\n        return None, f\"Error: {input_file} is not a valid Office file\"\n    except Exception as e:\n        return None, f\"Error unpacking: {e}\"\n\n\ndef _pretty_print_xml(xml_file: Path) -> None:\n    try:\n        content = xml_file.read_text(encoding=\"utf-8\")\n        dom = defusedxml.minidom.parseString(content)\n        xml_file.write_bytes(dom.toprettyxml(indent=\"  \", encoding=\"utf-8\"))\n    except Exception:\n        pass  \n\n\ndef _escape_smart_quotes(xml_file: Path) -> None:\n    try:\n        content = xml_file.read_text(encoding=\"utf-8\")\n        for char, entity in SMART_QUOTE_REPLACEMENTS.items():\n            content = content.replace(char, entity)\n        xml_file.write_text(content, encoding=\"utf-8\")\n    except Exception:\n        pass\n\n\nif __name__ == \"__main__\":\n    parser = argparse.ArgumentParser(\n        description=\"Unpack an Office file (DOCX, PPTX, XLSX) for editing\"\n    )\n    parser.add_argument(\"input_file\", help=\"Office file to unpack\")\n    parser.add_argument(\"output_directory\", help=\"Output directory\")\n    parser.add_argument(\n        \"--merge-runs\",\n        type=lambda x: x.lower() == \"true\",\n        default=True,\n        metavar=\"true|false\",\n        help=\"Merge adjacent runs with identical formatting (DOCX only, default: true)\",\n    )\n    parser.add_argument(\n        \"--simplify-redlines\",\n        type=lambda x: x.lower() == \"true\",\n        default=True,\n        metavar=\"true|false\",\n        help=\"Merge adjacent tracked changes from same author (DOCX only, default: true)\",\n    )\n    args = parser.parse_args()\n\n    _, message = unpack(\n        args.input_file,\n        args.output_directory,\n        merge_runs=args.merge_runs,\n        simplify_redlines=args.simplify_redlines,\n    )\n    print(message)\n\n    if \"Error\" in message:\n        sys.exit(1)\n','345c1b6a0ea7ca37e2019c2491db5fd9','2026-10-26 11:21:57','2026-10-26 11:21:57','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(725,'resource_config_MEMORY__md.json','agentspec__enc.656e67696e656572696e672d6261636b656e642d617263686974656374__enc.302e302e31','{\"name\":\"MEMORY.md\",\"type\":\"config\",\"content\":\"# 长期记忆\\n\\n由运行时写入；本模板未预置业务记忆。\\n\",\"metadata\":{\"uniformId\":1792984916232},\"resourceIdentifier\":\"config::MEMORY.md\"}','1dd5ad4f215fe47a1969cc10eb13458d','2026-10-26 11:21:57','2026-10-26 11:21:57','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(726,'enc.736372697074732f6f66666963652f736368656d61732f49534f2d49454332393530302d345f323031362f646d6c2d63686172742e787364','skill_enc.646f6378__enc.302e302e31','','ed49aff7a09c146a38ab39b0b065089f','2026-10-26 11:21:57','2026-10-26 11:21:57','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,'');
INSERT INTO `config_info` VALUES (727,'enc.736372697074732f6f66666963652f756e7061636b2e7079','skill_enc.646f6378__enc.302e302e31','\"\"\"Unpack Office files (DOCX, PPTX, XLSX) for editing.\n\nExtracts the ZIP archive, pretty-prints XML files, and optionally:\n- Merges adjacent runs with identical formatting (DOCX only)\n- Simplifies adjacent tracked changes from same author (DOCX only)\n\nUsage:\n    python unpack.py <office_file> <output_dir> [options]\n\nExamples:\n    python unpack.py document.docx unpacked/\n    python unpack.py presentation.pptx unpacked/\n    python unpack.py document.docx unpacked/ --merge-runs false\n\"\"\"\n\nimport argparse\nimport sys\nimport zipfile\nfrom pathlib import Path\n\nimport defusedxml.minidom\n\nfrom helpers.merge_runs import merge_runs as do_merge_runs\nfrom helpers.simplify_redlines import simplify_redlines as do_simplify_redlines\n\nSMART_QUOTE_REPLACEMENTS = {\n    \"\\u201c\": \"&#x201C;\",  \n    \"\\u201d\": \"&#x201D;\",  \n    \"\\u2018\": \"&#x2018;\",  \n    \"\\u2019\": \"&#x2019;\",  \n}\n\n\ndef unpack(\n    input_file: str,\n    output_directory: str,\n    merge_runs: bool = True,\n    simplify_redlines: bool = True,\n) -> tuple[None, str]:\n    input_path = Path(input_file)\n    output_path = Path(output_directory)\n    suffix = input_path.suffix.lower()\n\n    if not input_path.exists():\n        return None, f\"Error: {input_file} does not exist\"\n\n    if suffix not in {\".docx\", \".pptx\", \".xlsx\"}:\n        return None, f\"Error: {input_file} must be a .docx, .pptx, or .xlsx file\"\n\n    try:\n        output_path.mkdir(parents=True, exist_ok=True)\n\n        with zipfile.ZipFile(input_path, \"r\") as zf:\n            zf.extractall(output_path)\n\n        xml_files = list(output_path.rglob(\"*.xml\")) + list(output_path.rglob(\"*.rels\"))\n        for xml_file in xml_files:\n            _pretty_print_xml(xml_file)\n\n        message = f\"Unpacked {input_file} ({len(xml_files)} XML files)\"\n\n        if suffix == \".docx\":\n            if simplify_redlines:\n                simplify_count, _ = do_simplify_redlines(str(output_path))\n                message += f\", simplified {simplify_count} tracked changes\"\n\n            if merge_runs:\n                merge_count, _ = do_merge_runs(str(output_path))\n                message += f\", merged {merge_count} runs\"\n\n        for xml_file in xml_files:\n            _escape_smart_quotes(xml_file)\n\n        return None, message\n\n    except zipfile.BadZipFile:\n        return None, f\"Error: {input_file} is not a valid Office file\"\n    except Exception as e:\n        return None, f\"Error unpacking: {e}\"\n\n\ndef _pretty_print_xml(xml_file: Path) -> None:\n    try:\n        content = xml_file.read_text(encoding=\"utf-8\")\n        dom = defusedxml.minidom.parseString(content)\n        xml_file.write_bytes(dom.toprettyxml(indent=\"  \", encoding=\"utf-8\"))\n    except Exception:\n        pass  \n\n\ndef _escape_smart_quotes(xml_file: Path) -> None:\n    try:\n        content = xml_file.read_text(encoding=\"utf-8\")\n        for char, entity in SMART_QUOTE_REPLACEMENTS.items():\n            content = content.replace(char, entity)\n        xml_file.write_text(content, encoding=\"utf-8\")\n    except Exception:\n        pass\n\n\nif __name__ == \"__main__\":\n    parser = argparse.ArgumentParser(\n        description=\"Unpack an Office file (DOCX, PPTX, XLSX) for editing\"\n    )\n    parser.add_argument(\"input_file\", help=\"Office file to unpack\")\n    parser.add_argument(\"output_directory\", help=\"Output directory\")\n    parser.add_argument(\n        \"--merge-runs\",\n        type=lambda x: x.lower() == \"true\",\n        default=True,\n        metavar=\"true|false\",\n        help=\"Merge adjacent runs with identical formatting (DOCX only, default: true)\",\n    )\n    parser.add_argument(\n        \"--simplify-redlines\",\n        type=lambda x: x.lower() == \"true\",\n        default=True,\n        metavar=\"true|false\",\n        help=\"Merge adjacent tracked changes from same author (DOCX only, default: true)\",\n    )\n    args = parser.parse_args()\n\n    _, message = unpack(\n        args.input_file,\n        args.output_directory,\n        merge_runs=args.merge_runs,\n        simplify_redlines=args.simplify_redlines,\n    )\n    print(message)\n\n    if \"Error\" in message:\n        sys.exit(1)\n','345c1b6a0ea7ca37e2019c2491db5fd9','2026-10-26 11:21:57','2026-10-26 11:21:57','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(728,'enc.736372697074732f6f66666963652f736368656d61732f49534f2d49454332393530302d345f323031362f646d6c2d776f726470726f63657373696e6744726177696e672e787364','skill_enc.646f6378__enc.302e302e31','','88236935634cef10ea1229528daa8645','2026-10-26 11:21:57','2026-10-26 11:21:57','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(729,'enc.736372697074732f6f66666963652f736368656d61732f49534f2d49454332393530302d345f323031362f646d6c2d776f726470726f63657373696e6744726177696e672e787364','skill_enc.646f6378__enc.302e302e31','','88236935634cef10ea1229528daa8645','2026-10-26 11:21:57','2026-10-26 11:21:57','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(730,'manifest.json','agentspec__enc.656e67696e656572696e672d636f64652d7265766965776572__enc.302e302e31','{\"name\":\"engineering-code-reviewer\",\"description\":\"专业代码审查专家，提供建设性、可操作的反馈，聚焦正确性、可维护性、安全性和性能，而非代码风格偏好。\",\"content\":\"{\\n  \\\"version\\\": \\\"1.0\\\",\\n  \\\"source\\\": {\\n    \\\"repository\\\": \\\"https://github.com/jnMetaCode/agency-agents-zh\\\",\\n    \\\"commit\\\": \\\"23c2746913fe46260450517fa5afb58afc61fed7\\\",\\n    \\\"original_path\\\": \\\"engineering/engineering-code-reviewer.md\\\",\\n    \\\"openclaw_mode\\\": true\\n  },\\n  \\\"description\\\": \\\"专业代码审查专家，提供建设性、可操作的反馈，聚焦正确性、可维护性、安全性和性能，而非代码风格偏好。\\\",\\n  \\\"tags\\\": [\\n    \\\"engineering\\\"\\n  ],\\n  \\\"worker\\\": {\\n    \\\"suggested_name\\\": \\\"engineering-code-reviewer