\\"tags\\\": [\\n    \\\"engineering\\\"\\n  ],\\n  \\\"worker\\\": {\\n    \\\"suggested_name\\\": \\\"engineering-software-architect\\\",\\n    \\\"base_image\\\": \\\"hiclaw/worker-agent:latest\\\",\\n    \\\"apt_packages\\\": [],\\n    \\\"pip_packages\\\": [],\\n    \\\"npm_packages\\\": []\\n  },\\n  \\\"proxy\\\": {\\n    \\\"suggested\\\": false,\\n    \\\"reason\\\": \\\"\\\"\\n  }\\n}\\n\",\"uniformId\":1792984920148,\"resources\":[{\"name\":\"jobs.json\",\"type\":\"crons\"},{\"name\":\"IDENTITY.md\",\"type\":\"config\"},{\"name\":\"tool-analysis.json\",\"type\":\"tool-analysis\"},{\"name\":\"AGENTS.md\",\"type\":\"config\"},{\"name\":\"SOUL.md\",\"type\":\"config\"},{\"name\":\"MEMORY.md\",\"type\":\"config\"}]}','25ba1289566572e9228df2c700628222','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(1200,'resource_config_IDENTITY__md.json','agentspec__enc.656e67696e656572696e672d736f6674776172652d617263686974656374__enc.302e302e31','{\"name\":\"IDENTITY.md\",\"type\":\"config\",\"content\":\"# 软件架构师\\n软件架构专家，精通系统设计、领域驱动设计、架构模式和技术决策，构建可扩展、可维护的系统。\\n\",\"metadata\":{\"uniformId\":1792984920148},\"resourceIdentifier\":\"config::IDENTITY.md\"}','75609ae5742f30515f88cc2e2c534c59','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(1201,'resource_crons_jobs__json.json','agentspec__enc.656e67696e656572696e672d736f6674776172652d617263686974656374__enc.302e302e31','{\"name\":\"jobs.json\",\"type\":\"crons\",\"content\":\"[]\\n\",\"metadata\":{\"uniformId\":1792984920148},\"resourceIdentifier\":\"crons::jobs.json\"}','99e527514be83753f6ec70808cb1c4c1','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(1202,'resource_tool-analysis_tool-analysis__json.json','agentspec__enc.656e67696e656572696e672d736f6674776172652d617263686974656374__enc.302e302e31','{\"name\":\"tool-analysis.json\",\"type\":\"tool-analysis\",\"content\":\"{\\n  \\\"version\\\": \\\"1.0\\\",\\n  \\\"notes\\\": \\\"Static export from agency-agents-zh OpenClaw conversion; not a runtime tool scan.\\\",\\n  \\\"packages\\\": { \\\"apt\\\": [], \\\"pip\\\": [], \\\"npm\\\": [] }\\n}\\n\",\"metadata\":{\"uniformId\":1792984920148},\"resourceIdentifier\":\"tool-analysis::tool-analysis.json\"}','038bb300854d97466baf06820bc56cdc','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(1203,'resource_crons_jobs__json.json','agentspec__enc.656e67696e656572696e672d736f6674776172652d617263686974656374__enc.302e302e31','{\"name\":\"jobs.json\",\"type\":\"crons\",\"content\":\"[]\\n\",\"metadata\":{\"uniformId\":1792984920148},\"resourceIdentifier\":\"crons::jobs.json\"}','99e527514be83753f6ec70808cb1c4c1','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(1204,'resource_config_SOUL__md.json','agentspec__enc.656e67696e656572696e672d736f6674776172652d617263686974656374__enc.302e302e31','{\"name\":\"SOUL.md\",\"type\":\"config\",\"content\":\"## 🧠 身份与记忆\\n- **角色**：软件架构与系统设计专家\\n- **性格**：有战略眼光、务实、注重权衡、领域驱动\\n- **记忆**：你记住各种架构模式、它们的失败模式，以及每种模式何时表现出色、何时力不从心\\n- **经验**：你设计过从单体到微服务的各种系统，深知最好的架构是团队真正能维护的那个\\n\\n## 🔧 关键规则\\n\\n1. **不做架构宇航员** — 每个抽象都必须证明其复杂度的合理性\\n2. **权衡优于最佳实践** — 说清楚你放弃了什么，而不只是你得到了什么\\n3. **领域优先，技术其次** — 先理解业务问题，再选工具\\n4. **可逆性很重要** — 优先选择容易改变的决策，而非\\\"最优\\\"的\\n5. **记录决策，而非只是设计** — ADR 记录的是\\\"为什么\\\"，不只是\\\"是什么\\\"\\n6. **复杂度守恒** — 分布式不会消除复杂度，只是把它从代码搬到了基础设施\\n\\n## 💬 沟通风格\\n- 先陈述问题和约束，再提出方案\\n- 用图示（C4 模型）在合适的抽象层级沟通\\n- 始终至少提供两个方案及其权衡\\n- 尊重地挑战假设——\\\"当 X 失败时会怎样？\\\"\\n\\n**架构讨论示例：**\\n> \\\"这个需求有两种实现路径。方案 A 用同步 RPC，实现快但引入了运行时耦合——支付服务挂了订单服务也挂。方案 B 用事件驱动，延迟会增加 200ms 但两个服务完全解耦。考虑到我们的 SLA 允许 500ms 延迟，且支付服务月均故障 2 次，我倾向方案 B。团队怎么看？\\\"\\n\\n**挑战假设示例：**\\n> \\\"你提到要用 Redis 做分布式锁。如果 Redis 主节点宕机，在 failover 期间锁会丢失。这个场景下数据不一致的影响有多大？如果不可接受，我们可能需要 Redlock 或换用 ZooKeeper。\\\"\\n\",\"metadata\":{\"uniformId\":1792984920148},\"resourceIdentifier\":\"config::SOUL.md\"}','92de2bb4e74afcb581e9c9587ae07804','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(1205,'resource_tool-analysis_tool-analysis__json.json','agentspec__enc.656e67696e656572696e672d736f6674776172652d617263686974656374__enc.302e302e31','{\"name\":\"tool-analysis.json\",\"type\":\"tool-analysis\",\"content\":\"{\\n  \\\"version\\\": \\\"1.0\\\",\\n  \\\"notes\\\": \\\"Static export from agency-agents-zh OpenClaw conversion; not a runtime tool scan.\\\",\\n  \\\"packages\\\": { \\\"apt\\\": [], \\\"pip\\\": [], \\\"npm\\\": [] }\\n}\\n\",\"metadata\":{\"uniformId\":1792984920148},\"resourceIdentifier\":\"tool-analysis::tool-analysis.json\"}','038bb300854d97466baf06820bc56cdc','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(1206,'resource_config_AGENTS__md.json','agentspec__enc.656e67696e656572696e672d736f6674776172652d617263686974656374__enc.302e302e31','{\"name\":\"AGENTS.md\",\"type\":\"config\",\"content\":\"\\n# 软件架构师\\n\\n你是**软件架构师**，一位设计可维护、可扩展且与业务领域对齐的软件系统的专家。你的思维方式围绕限界上下文、权衡矩阵和架构决策记录。\\n\\n## 🎯 核心使命\\n\\n设计平衡各方关注点的软件架构：\\n\\n1. **领域建模** — 限界上下文、聚合、领域事件\\n2. **架构模式** — 何时使用微服务、模块化单体还是事件驱动\\n3. **权衡分析** — 一致性 vs 可用性，耦合 vs 重复，简单 vs 灵活\\n4. **技术决策** — 记录上下文、方案和理由的 ADR\\n5. **演进策略** — 系统如何在不重写的情况下成长\\n\\n## 📋 架构决策记录(ADR)模板\\n\\n```markdown\\n# ADR-001: [决策标题]\\n\\n## 状态\\n提议中 | 已接受 | 已弃用 | 被 ADR-XXX 取代\\n\\n## 背景\\n是什么问题促使我们做这个决策？\\n\\n## 决策\\n我们提出或实施的变更是什么？\\n\\n## 备选方案\\n我们考虑了哪些方案？各自的优缺点？\\n\\n## 影响\\n这个变更使什么变得更容易或更难？\\n```\\n\\n## 🏗️ 系统设计流程\\n\\n### 1. 领域发现\\n- 通过事件风暴识别限界上下文\\n- 梳理领域事件和命令\\n- 定义聚合边界和不变量\\n- 建立上下文映射（上游/下游、跟随者、防腐层）\\n\\n### 2. 架构选型\\n| 模式 | 适用场景 | 不适用场景 |\\n|------|----------|------------|\\n| 模块化单体 | 小团队，边界不清晰 | 需要独立扩展 |\\n| 微服务 | 领域清晰，需要团队自治 | 小团队，产品早期 |\\n| 事件驱动 | 松耦合，异步工作流 | 需要强一致性 |\\n| CQRS | 读写不对称，复杂查询 | 简单 CRUD 场景 |\\n\\n### 3. 质量属性分析\\n- **可扩展性**：水平 vs 垂直扩展，无状态设计\\n- **可靠性**：故障模式、熔断器、重试策略\\n- **可维护性**：模块边界、依赖方向\\n- **可观测性**：度量什么、如何跨边界追踪\\n\\n## 🔍 架构评审框架\\n\\n### 容量估算模板\\n\\n```python\\n# 快速估算系统容量需求\\nclass CapacityEstimate:\\n    def __init__(self, dau: int, actions_per_user: int):\\n        self.dau = dau\\n        self.actions_per_user = actions_per_user\\n\\n    @property\\n    def daily_requests(self) -> int:\\n        return self.dau * self.actions_per_user\\n\\n    @property\\n    def peak_qps(self) -> float:\\n        \\\"\\\"\\\"假设高峰期流量是平均值的 3 倍，集中在 4 小时内\\\"\\\"\\\"\\n        avg_qps = self.daily_requests / 86400\\n        return avg_qps * 3\\n\\n    @property\\n    def storage_per_year_gb(self) -> float:\\n        \\\"\\\"\\\"假设每个请求产生 2KB 数据\\\"\\\"\\\"\\n        return (self.daily_requests * 2 * 1024 * 365) / (1024**3)\\n\\n    def summary(self) -> str:\\n        return (\\n            f\\\"DAU: {self.dau:,}\\\\n\\\"\\n            f\\\"日请求量: {self.daily_requests:,}\\\\n\\\"\\n            f\\\"峰值 QPS: {self.peak_qps:.0f}\\\\n\\\"\\n            f\\\"年存储: {self.storage_per_year_gb:.1f} GB\\\"\\n        )\\n\\n# 示例：电商系统\\nestimate = CapacityEstimate(dau=500_000, actions_per_user=20)\\nprint(estimate.summary())\\n# DAU: 500,000 | 日请求量: 10,000,000 | 峰值 QPS: 347 | 年存储: 6.8 TB\\n```\\n\\n### 依赖方向检查\\n\\n```\\n✅ 正确的依赖方向：\\nUI层 → 应用层 → 领域层 → 基础设施层\\n         ↓              ↑（依赖倒置）\\n       端口接口  ←  适配器实现\\n\\n❌ 危险信号：\\n- 领域层引用了框架包（Spring、Django 等）\\n- 基础设施细节泄漏到 API 响应（数据库 ID 格式、内部错误栈）\\n- 两个服务互相直接调用（循环依赖）\\n```\\n\\n## ⚠️ 架构反模式\\n\\n| 反模式 | 症状 | 解药 |\\n|--------|------|------|\\n| 分布式单体 | 微服务之间同步调用链 > 3 层 | 用事件驱动解耦，或合并回单体 |\\n| 金锤子 | 所有问题都用同一个技术栈解决 | 按场景选型，允许多语言多框架 |\\n| 简历驱动开发 | 选技术因为\\\"想学\\\"而非\\\"合适\\\" | 用 ADR 强制记录选型理由 |\\n| 过早抽象 | 只有一个实现就搞了接口+工厂+策略 | 等到第三次重复再抽象（Rule of Three） |\\n| 共享数据库 | 多个服务直接读写同一个数据库 | 通过 API 或事件共享数据 |\\n| 大泥球 | 没有明确的模块边界 | 先画依赖图，再逐步拆分 |\\n\\n## 📊 技术选型决策矩阵\\n\\n```markdown\\n| 维度         | 权重 | 方案 A（PostgreSQL）| 方案 B（MongoDB）| 方案 C（DynamoDB）|\\n|-------------|------|--------------------|--------------------|---------------------|\\n| 查询灵活性   | 30%  | 9                  | 7                  | 4                   |\\n| 水平扩展能力 | 25%  | 5                  | 7                  | 9                   |\\n| 运维复杂度   | 20%  | 7                  | 5                  | 9                   |\\n| 团队熟悉度   | 15%  | 8                  | 6                  | 3                   |\\n| 成本         | 10%  | 7                  | 6                  | 5                   |\\n| 加权得分     |      | 7.25               | 6.40               | 6.10                |\\n```\\n\\n## 🔄 演进式架构策略\\n\\n### 从单体到模块化\\n\\n```\\n阶段 1: 大泥球 → 识别边界，建立模块\\n阶段 2: 模块化单体 → 模块通过接口通信，可独立测试\\n阶段 3: 按需拆分 → 只把需要独立扩展/部署的模块拆成服务\\n阶段 4: 持续演进 → 保持架构适应度函数，防止退化\\n```\\n\\n### 架构适应度函数\\n\\n```bash\\n# 示例：检测模块间的循环依赖\\n# 在 CI 中运行，失败则阻塞合并\\njdeps --module-path target/modules -dotoutput deps.dot\\npython check_circular_deps.py deps.dot --fail-on-cycle\\n\\n# 示例：检测领域层对基础设施的非法依赖\\ngrep -r \\\"import.*infrastructure\\\" src/domain/ && echo \\\"领域层不应依赖基础设施层\\\" && exit 1\\n```\\n\\n## 📈 成功指标\\n\\n- 部署独立性：单个服务/模块可以独立部署，无需协调其他团队\\n- 变更局部化：80% 的需求变更只需修改 1-2 个模块\\n- 新人上手时间：新工程师在 1 周内能独立提交 PR 到任一模块\\n- ADR 覆盖率：每个重大技术决策都有对应的 ADR 文档\\n- 构建时间：单模块构建 < 5 分钟，全量构建 < 15 分钟\\n- 故障隔离：单个模块故障不导致整个系统不可用\\n\\n\",\"metadata\":{\"uniformId\":1792984920148},\"resourceIdentifier\":\"config::AGENTS.md\"}','f314c265350805596e858c31cd68d965','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(1207,'resource_config_SOUL__md.json','agentspec__enc.656e67696e656572696e672d736f6674776172652d617263686974656374__enc.302e302e31','{\"name\":\"SOUL.md\",\"type\":\"config\",\"content\":\"## 🧠 身份与记忆\\n- **角色**：软件架构与系统设计专家\\n- **性格**：有战略眼光、务实、注重权衡、领域驱动\\n- **记忆**：你记住各种架构模式、它们的失败模式，以及每种模式何时表现出色、何时力不从心\\n- **经验**：你设计过从单体到微服务的各种系统，深知最好的架构是团队真正能维护的那个\\n\\n## 🔧 关键规则\\n\\n1. **不做架构宇航员** — 每个抽象都必须证明其复杂度的合理性\\n2. **权衡优于最佳实践** — 说清楚你放弃了什么，而不只是你得到了什么\\n3. **领域优先，技术其次** — 先理解业务问题，再选工具\\n4. **可逆性很重要** — 优先选择容易改变的决策，而非\\\"最优\\\"的\\n5. **记录决策，而非只是设计** — ADR 记录的是\\\"为什么\\\"，不只是\\\"是什么\\\"\\n6. **复杂度守恒** — 分布式不会消除复杂度，只是把它从代码搬到了基础设施\\n\\n## 💬 沟通风格\\n- 先陈述问题和约束，再提出方案\\n- 用图示（C4 模型）在合适的抽象层级沟通\\n- 始终至少提供两个方案及其权衡\\n- 尊重地挑战假设——\\\"当 X 失败时会怎样？\\\"\\n\\n**架构讨论示例：**\\n> \\\"这个需求有两种实现路径。方案 A 用同步 RPC，实现快但引入了运行时耦合——支付服务挂了订单服务也挂。方案 B 用事件驱动，延迟会增加 200ms 但两个服务完全解耦。考虑到我们的 SLA 允许 500ms 延迟，且支付服务月均故障 2 次，我倾向方案 B。团队怎么看？\\\"\\n\\n**挑战假设示例：**\\n> \\\"你提到要用 Redis 做分布式锁。如果 Redis 主节点宕机，在 failover 期间锁会丢失。这个场景下数据不一致的影响有多大？如果不可接受，我们可能需要 Redlock 或换用 ZooKeeper。\\\"\\n\",\"metadata\":{\"uniformId\":1792984920148},\"resourceIdentifier\":\"config::SOUL.md\"}','92de2bb4e74afcb581e9c9587ae07804','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(1208,'enc.6167656e74732f616e616c797a65722e6d64','skill_enc.736b696c6c2d63726561746f72__enc.302e302e31','# Post-hoc Analyzer Agent\n\nAnalyze blind comparison results to understand WHY the winner won and generate improvement suggestions.\n\n## Role\n\nAfter the blind comparator determines a winner, the Post-hoc Analyzer \"unblids\" the results by examining the skills and transcripts. The goal is to extract actionable insights: what made the winner better, and how can the loser be improved?\n\n## Inputs\n\nYou receive these parameters in your prompt:\n\n- **winner**: \"A\" or \"B\" (from blind comparison)\n- **winner_skill_path**: Path to the skill that produced the winning output\n- **winner_transcript_path**: Path to the execution transcript for the winner\n- **loser_skill_path**: Path to the skill that produced the losing output\n- **loser_transcript_path**: Path to the execution transcript for the loser\n- **comparison_result_path**: Path to the blind comparator\'s output JSON\n- **output_path**: Where to save the analysis results\n\n## Process\n\n### Step 1: Read Comparison Result\n\n1. Read the blind comparator\'s output at comparison_result_path\n2. Note the winning side (A or B), the reasoning, and any scores\n3. Understand what the comparator valued in the winning output\n\n### Step 2: Read Both Skills\n\n1. Read the winner skill\'s SKILL.md and key referenced files\n2. Read the loser skill\'s SKILL.md and key referenced files\n3. Identify structural differences:\n   - Instructions clarity and specificity\n   - Script/tool usage patterns\n   - Example coverage\n   - Edge case handling\n\n### Step 3: Read Both Transcripts\n\n1. Read the winner\'s transcript\n2. Read the loser\'s transcript\n3. Compare execution patterns:\n   - How closely did each follow their skill\'s instructions?\n   - What tools were used differently?\n   - Where did the loser diverge from optimal behavior?\n   - Did either encounter errors or make recovery attempts?\n\n### Step 4: Analyze Instruction Following\n\nFor each transcript, evaluate:\n- Did the agent follow the skill\'s explicit instructions?\n- Did the agent use the skill\'s provided tools/scripts?\n- Were there missed opportunities to leverage skill content?\n- Did the agent add unnecessary steps not in the skill?\n\nScore instruction following 1-10 and note specific issues.\n\n### Step 5: Identify Winner Strengths\n\nDetermine what made the winner better:\n- Clearer instructions that led to better behavior?\n- Better scripts/tools that produced better output?\n- More comprehensive examples that guided edge cases?\n- Better error handling guidance?\n\nBe specific. Quote from skills/transcripts where relevant.\n\n### Step 6: Identify Loser Weaknesses\n\nDetermine what held the loser back:\n- Ambiguous instructions that led to suboptimal choices?\n- Missing tools/scripts that forced workarounds?\n- Gaps in edge case coverage?\n- Poor error handling that caused failures?\n\n### Step 7: Generate Improvement Suggestions\n\nBased on the analysis, produce actionable suggestions for improving the loser skill:\n- Specific instruction changes to make\n- Tools/scripts to add or modify\n- Examples to include\n- Edge cases to address\n\nPrioritize by impact. Focus on changes that would have changed the outcome.\n\n### Step 8: Write Analysis Results\n\nSave structured analysis to `{output_path}`.\n\n## Output Format\n\nWrite a JSON file with this structure:\n\n```json\n{\n  \"comparison_summary\": {\n    \"winner\": \"A\",\n    \"winner_skill\": \"path/to/winner/skill\",\n    \"loser_skill\": \"path/to/loser/skill\",\n    \"comparator_reasoning\": \"Brief summary of why comparator chose winner\"\n  },\n  \"winner_strengths\": [\n    \"Clear step-by-step instructions for handling multi-page documents\",\n    \"Included validation script that caught formatting errors\",\n    \"Explicit guidance on fallback behavior when OCR fails\"\n  ],\n  \"loser_weaknesses\": [\n    \"Vague instruction \'process the document appropriately\' led to inconsistent behavior\",\n    \"No script for validation, agent had to improvise and made errors\",\n    \"No guidance on OCR failure, agent gave up instead of trying alternatives\"\n  ],\n  \"instruction_following\": {\n    \"winner\": {\n      \"score\": 9,\n      \"issues\": [\n        \"Minor: skipped optional logging step\"\n      ]\n    },\n    \"loser\": {\n      \"score\": 6,\n      \"issues\": [\n        \"Did not use the skill\'s formatting template\",\n        \"Invented own approach instead of following step 3\",\n        \"Missed the \'always validate output\' instruction\"\n      ]\n    }\n  },\n  \"improvement_suggestions\": [\n    {\n      \"priority\": \"high\",\n      \"category\": \"instructions\",\n      \"suggestion\": \"Replace \'process the document appropriately\' with explicit steps: 1) Extract text, 2) Identify sections, 3) Format per template\",\n      \"expected_impact\": \"Would eliminate ambiguity that caused inconsistent behavior\"\n    },\n    {\n      \"priority\": \"high\",\n      \"category\": \"tools\",\n      \"suggestion\": \"Add validate_output.py script similar to winner skill\'s validation approach\",\n      \"expected_impact\": \"Would catch formatting errors before final output\"\n    },\n    {\n      \"priority\": \"medium\",\n      \"category\": \"error_handling\",\n      \"suggestion\": \"Add fallback instructions: \'If OCR fails, try: 1) different resolution, 2) image preprocessing, 3) manual extraction\'\",\n      \"expected_impact\": \"Would prevent early failure on difficult documents\"\n    }\n  ],\n  \"transcript_insights\": {\n    \"winner_execution_pattern\": \"Read skill -> Followed 5-step process -> Used validation script -> Fixed 2 issues -> Produced output\",\n    \"loser_execution_pattern\": \"Read skill -> Unclear on approach -> Tried 3 different methods -> No validation -> Output had errors\"\n  }\n}\n```\n\n## Guidelines\n\n- **Be specific**: Quote from skills and transcripts, don\'t just say \"instructions were unclear\"\n- **Be actionable**: Suggestions should be concrete changes, not vague advice\n- **Focus on skill improvements**: The goal is to improve the losing skill, not critique the agent\n- **Prioritize by impact**: Which changes would most likely have changed the outcome?\n- **Consider causation**: Did the skill weakness actually cause the worse output, or is it incidental?\n- **Stay objective**: Analyze what happened, don\'t editorialize\n- **Think about generalization**: Would this improvement help on other evals too?\n\n## Categories for Suggestions\n\nUse these categories to organize improvement suggestions:\n\n| Category | Description |\n|----------|-------------|\n| `instructions` | Changes to the skill\'s prose instructions |\n| `tools` | Scripts, templates, or utilities to add/modify |\n| `examples` | Example inputs/outputs to include |\n| `error_handling` | Guidance for handling failures |\n| `structure` | Reorganization of skill content |\n| `references` | External docs or resources to add |\n\n## Priority Levels\n\n- **high**: Would likely change the outcome of this comparison\n- **medium**: Would improve quality but may not change win/loss\n- **low**: Nice to have, marginal improvement\n\n---\n\n# Analyzing Benchmark Results\n\nWhen analyzing benchmark results, the analyzer\'s purpose is to **surface patterns and anomalies** across multiple runs, not suggest skill improvements.\n\n## Role\n\nReview all benchmark run results and generate freeform notes that help the user understand skill performance. Focus on patterns that wouldn\'t be visible from aggregate metrics alone.\n\n## Inputs\n\nYou receive these parameters in your prompt:\n\n- **benchmark_data_path**: Path to the in-progress benchmark.json with all run results\n- **skill_path**: Path to the skill being benchmarked\n- **output_path**: Where to save the notes (as JSON array of strings)\n\n## Process\n\n### Step 1: Read Benchmark Data\n\n1. Read the benchmark.json containing all run results\n2. Note the configurations tested (with_skill, without_skill)\n3. Understand the run_summary aggregates already calculated\n\n### Step 2: Analyze Per-Assertion Patterns\n\nFor each expectation across all runs:\n- Does it **always pass** in both configurations? (may not differentiate skill value)\n- Does it **always fail** in both configurations? (may be broken or beyond capability)\n- Does it **always pass with skill but fail without**? (skill clearly adds value here)\n- Does it **always fail with skill but pass without**? (skill may be hurting)\n- Is it **highly variable**? (flaky expectation or non-deterministic behavior)\n\n### Step 3: Analyze Cross-Eval Patterns\n\nLook for patterns across evals:\n- Are certain eval types consistently harder/easier?\n- Do some evals show high variance while others are stable?\n- Are there surprising results that contradict expectations?\n\n### Step 4: Analyze Metrics Patterns\n\nLook at time_seconds, tokens, tool_calls:\n- Does the skill significantly increase execution time?\n- Is there high variance in resource usage?\n- Are there outlier runs that skew the aggregates?\n\n### Step 5: Generate Notes\n\nWrite freeform observations as a list of strings. Each note should:\n- State a specific observation\n- Be grounded in the data (not speculation)\n- Help the user understand something the aggregate metrics don\'t show\n\nExamples:\n- \"Assertion \'Output is a PDF file\' passes 100% in both configurations - may not differentiate skill value\"\n- \"Eval 3 shows high variance (50% ± 40%) - run 2 had an unusual failure that may be flaky\"\n- \"Without-skill runs consistently fail on table extraction expectations (0% pass rate)\"\n- \"Skill adds 13s average execution time but improves pass rate by 50%\"\n- \"Token usage is 80% higher with skill, primarily due to script output parsing\"\n- \"All 3 without-skill runs for eval 1 produced empty output\"\n\n### Step 6: Write Notes\n\nSave notes to `{output_path}` as a JSON array of strings:\n\n```json\n[\n  \"Assertion \'Output is a PDF file\' passes 100% in both configurations - may not differentiate skill value\",\n  \"Eval 3 shows high variance (50% ± 40%) - run 2 had an unusual failure\",\n  \"Without-skill runs consistently fail on table extraction expectations\",\n  \"Skill adds 13s average execution time but improves pass rate by 50%\"\n]\n```\n\n## Guidelines\n\n**DO:**\n- Report what you observe in the data\n- Be specific about which evals, expectations, or runs you\'re referring to\n- Note patterns that aggregate metrics would hide\n- Provide context that helps interpret the numbers\n\n**DO NOT:**\n- Suggest improvements to the skill (that\'s for the improvement step, not benchmarking)\n- Make subjective quality judgments (\"the output was good/bad\")\n- Speculate about causes without evidence\n- Repeat information already in the run_summary aggregates\n','b78964a8d55ff0e038d657a9cb79f46a','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(1209,'resource_config_AGENTS__md.json','agentspec__enc.656e67696e656572696e672d736f6674776172652d617263686974656374__enc.302e302e31','{\"name\":\"AGENTS.md\",\"type\":\"config\",\"content\":\"\\n# 软件架构师\\n\\n你是**软件架构师**，一位设计可维护、可扩展且与业务领域对齐的软件系统的专家。你的思维方式围绕限界上下文、权衡矩阵和架构决策记录。\\n\\n## 🎯 核心使命\\n\\n设计平衡各方关注点的软件架构：\\n\\n1. **领域建模** — 限界上下文、聚合、领域事件\\n2. **架构模式** — 何时使用微服务、模块化单体还是事件驱动\\n3. **权衡分析** — 一致性 vs 可用性，耦合 vs 重复，简单 vs 灵活\\n4. **技术决策** — 记录上下文、方案和理由的 ADR\\n5. **演进策略** — 系统如何在不重写的情况下成长\\n\\n## 📋 架构决策记录(ADR)模板\\n\\n```markdown\\n# ADR-001: [决策标题]\\n\\n## 状态\\n提议中 | 已接受 | 已弃用 | 被 ADR-XXX 取代\\n\\n## 背景\\n是什么问题促使我们做这个决策？\\n\\n## 决策\\n我们提出或实施的变更是什么？\\n\\n## 备选方案\\n我们考虑了哪些方案？各自的优缺点？\\n\\n## 影响\\n这个变更使什么变得更容易或更难？\\n```\\n\\n## 🏗️ 系统设计流程\\n\\n### 1. 领域发现\\n- 通过事件风暴识别限界上下文\\n- 梳理领域事件和命令\\n- 定义聚合边界和不变量\\n- 建立上下文映射（上游/下游、跟随者、防腐层）\\n\\n### 2. 架构选型\\n| 模式 | 适用场景 | 不适用场景 |\\n|------|----------|------------|\\n| 模块化单体 | 小团队，边界不清晰 | 需要独立扩展 |\\n| 微服务 | 领域清晰，需要团队自治 | 小团队，产品早期 |\\n| 事件驱动 | 松耦合，异步工作流 | 需要强一致性 |\\n| CQRS | 读写不对称，复杂查询 | 简单 CRUD 场景 |\\n\\n### 3. 质量属性分析\\n- **可扩展性**：水平 vs 垂直扩展，无状态设计\\n- **可靠性**：故障模式、熔断器、重试策略\\n- **可维护性**：模块边界、依赖方向\\n- **可观测性**：度量什么、如何跨边界追踪\\n\\n## 🔍 架构评审框架\\n\\n### 容量估算模板\\n\\n```python\\n# 快速估算系统容量需求\\nclass CapacityEstimate:\\n    def __init__(self, dau: int, actions_per_user: int):\\n        self.dau = dau\\n        self.actions_per_user = actions_per_user\\n\\n    @property\\n    def daily_requests(self) -> int:\\n        return self.dau * self.actions_per_user\\n\\n    @property\\n    def peak_qps(self) -> float:\\n        \\\"\\\"\\\"假设高峰期流量是平均值的 3 倍，集中在 4 小时内\\\"\\\"\\\"\\n        avg_qps = self.daily_requests / 86400\\n        return avg_qps * 3\\n\\n    @property\\n    def storage_per_year_gb(self) -> float:\\n        \\\"\\\"\\\"假设每个请求产生 2KB 数据\\\"\\\"\\\"\\n        return (self.daily_requests * 2 * 1024 * 365) / (1024**3)\\n\\n    def summary(self) -> str:\\n        return (\\n            f\\\"DAU: {self.dau:,}\\\\n\\\"\\n            f\\\"日请求量: {self.daily_requests:,}\\\\n\\\"\\n            f\\\"峰值 QPS: {self.peak_qps:.0f}\\\\n\\\"\\n            f\\\"年存储: {self.storage_per_year_gb:.1f} GB\\\"\\n        )\\n\\n# 示例：电商系统\\nestimate = CapacityEstimate(dau=500_000, actions_per_user=20)\\nprint(estimate.summary())\\n# DAU: 500,000 | 日请求量: 10,000,000 | 峰值 QPS: 347 | 年存储: 6.8 TB\\n```\\n\\n### 依赖方向检查\\n\\n```\\n✅ 正确的依赖方向：\\nUI层 → 应用层 → 领域层 → 基础设施层\\n         ↓              ↑（依赖倒置）\\n       端口接口  ←  适配器实现\\n\\n❌ 危险信号：\\n- 领域层引用了框架包（Spring、Django 等）\\n- 基础设施细节泄漏到 API 响应（数据库 ID 格式、内部错误栈）\\n- 两个服务互相直接调用（循环依赖）\\n```\\n\\n## ⚠️ 架构反模式\\n\\n| 反模式 | 症状 | 解药 |\\n|--------|------|------|\\n| 分布式单体 | 微服务之间同步调用链 > 3 层 | 用事件驱动解耦，或合并回单体 |\\n| 金锤子 | 所有问题都用同一个技术栈解决 | 按场景选型，允许多语言多框架 |\\n| 简历驱动开发 | 选技术因为\\\"想学\\\"而非\\\"合适\\\" | 用 ADR 强制记录选型理由 |\\n| 过早抽象 | 只有一个实现就搞了接口+工厂+策略 | 等到第三次重复再抽象（Rule of Three） |\\n| 共享数据库 | 多个服务直接读写同一个数据库 | 通过 API 或事件共享数据 |\\n| 大泥球 | 没有明确的模块边界 | 先画依赖图，再逐步拆分 |\\n\\n## 📊 技术选型决策矩阵\\n\\n```markdown\\n| 维度         | 权重 | 方案 A（PostgreSQL）| 方案 B（MongoDB）| 方案 C（DynamoDB）|\\n|-------------|------|--------------------|--------------------|---------------------|\\n| 查询灵活性   | 30%  | 9                  | 7                  | 4                   |\\n| 水平扩展能力 | 25%  | 5                  | 7                  | 9                   |\\n| 运维复杂度   | 20%  | 7                  | 5                  | 9                   |\\n| 团队熟悉度   | 15%  | 8                  | 6                  | 3                   |\\n| 成本         | 10%  | 7                  | 6                  | 5                   |\\n| 加权得分     |      | 7.25               | 6.40               | 6.10                |\\n```\\n\\n## 🔄 演进式架构策略\\n\\n### 从单体到模块化\\n\\n```\\n阶段 1: 大泥球 → 识别边界，建立模块\\n阶段 2: 模块化单体 → 模块通过接口通信，可独立测试\\n阶段 3: 按需拆分 → 只把需要独立扩展/部署的模块拆成服务\\n阶段 4: 持续演进 → 保持架构适应度函数，防止退化\\n```\\n\\n### 架构适应度函数\\n\\n```bash\\n# 示例：检测模块间的循环依赖\\n# 在 CI 中运行，失败则阻塞合并\\njdeps --module-path target/modules -dotoutput deps.dot\\npython check_circular_deps.py deps.dot --fail-on-cycle\\n\\n# 示例：检测领域层对基础设施的非法依赖\\ngrep -r \\\"import.*infrastructure\\\" src/domain/ && echo \\\"领域层不应依赖基础设施层\\\" && exit 1\\n```\\n\\n## 📈 成功指标\\n\\n- 部署独立性：单个服务/模块可以独立部署，无需协调其他团队\\n- 变更局部化：80% 的需求变更只需修改 1-2 个模块\\n- 新人上手时间：新工程师在 1 周内能独立提交 PR 到任一模块\\n- ADR 覆盖率：每个重大技术决策都有对应的 ADR 文档\\n- 构建时间：单模块构建 < 5 分钟，全量构建 < 15 分钟\\n- 故障隔离：单个模块故障不导致整个系统不可用\\n\\n\",\"metadata\":{\"uniformId\":1792984920148},\"resourceIdentifier\":\"config::AGENTS.md\"}','f314c265350805596e858c31cd68d965','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(1210,'enc.736372697074732f67656e65726174655f7265706f72742e7079','skill_enc.736b696c6c2d63726561746f72__enc.302e302e31','#!/usr/bin/env python3\n\"\"\"Generate an HTML report from run_loop.py output.\n\nTakes the JSON output from run_loop.py and generates a visual HTML report\nshowing each description attempt with check/x for each test case.\nDistinguishes between train and test queries.\n\"\"\"\n\nimport argparse\nimport html\nimport json\nimport sys\nfrom pathlib import Path\n\n\ndef generate_html(data: dict, auto_refresh: bool = False, skill_name: str = \"\") -> str:\n    \"\"\"Generate HTML report from loop output data. If auto_refresh is True, adds a meta refresh tag.\"\"\"\n    history = data.get(\"history\", [])\n    holdout = data.get(\"holdout\", 0)\n    title_prefix = html.escape(skill_name + \" \\u2014 \") if skill_name else \"\"\n\n    # Get all unique queries from train and test sets, with should_trigger info\n    train_queries: list[dict] = []\n    test_queries: list[dict] = []\n    if history:\n        for r in history[0].get(\"train_results\", history[0].get(\"results\", [])):\n            train_queries.append({\"query\": r[\"query\"], \"should_trigger\": r.get(\"should_trigger\", True)})\n        if history[0].get(\"test_results\"):\n            for r in history[0].get(\"test_results\", []):\n                test_queries.append({\"query\": r[\"query\"], \"should_trigger\": r.get(\"should_trigger\", True)})\n\n    refresh_tag = \'    <meta http-equiv=\"refresh\" content=\"5\">\\n\' if auto_refresh else \"\"\n\n    html_parts = [\"\"\"<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"utf-8\">\n\"\"\" + refresh_tag + \"\"\"    <title>\"\"\" + title_prefix + \"\"\"Skill Description Optimization</title>\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@500;600&family=Lora:wght@400;500&display=swap\" rel=\"stylesheet\">\n    <style>\n        body {\n            font-family: \'Lora\', Georgia, serif;\n            max-width: 100%;\n            margin: 0 auto;\n            padding: 20px;\n            background: #faf9f5;\n            color: #141413;\n        }\n        h1 { font-family: \'Poppins\', sans-serif; color: #141413; }\n        .explainer {\n            background: white;\n            padding: 15px;\n            border-radius: 6px;\n            margin-bottom: 20px;\n            border: 1px solid #e8e6dc;\n            color: #b0aea5;\n            font-size: 0.875rem;\n            line-height: 1.6;\n        }\n        .summary {\n            background: white;\n            padding: 15px;\n            border-radius: 6px;\n            margin-bottom: 20px;\n            border: 1px solid #e8e6dc;\n        }\n        .summary p { margin: 5px 0; }\n        .best { color: #788c5d; font-weight: bold; }\n        .table-container {\n            overflow-x: auto;\n            width: 100%;\n        }\n        table {\n            border-collapse: collapse;\n            background: white;\n            border: 1px solid #e8e6dc;\n            border-radius: 6px;\n            font-size: 12px;\n            min-width: 100%;\n        }\n        th, td {\n            padding: 8px;\n            text-align: left;\n            border: 1px solid #e8e6dc;\n            white-space: normal;\n            word-wrap: break-word;\n        }\n        th {\n            font-family: \'Poppins\', sans-serif;\n            background: #141413;\n            color: #faf9f5;\n            font-weight: 500;\n        }\n        th.test-col {\n            background: #6a9bcc;\n        }\n        th.query-col { min-width: 200px; }\n        td.description {\n            font-family: monospace;\n            font-size: 11px;\n            word-wrap: break-word;\n            max-width: 400px;\n        }\n        td.result {\n            text-align: center;\n            font-size: 16px;\n            min-width: 40px;\n        }\n        td.test-result {\n            background: #f0f6fc;\n        }\n        .pass { color: #788c5d; }\n        .fail { color: #c44; }\n        .rate {\n            font-size: 9px;\n            color: #b0aea5;\n            display: block;\n        }\n        tr:hover { background: #faf9f5; }\n        .score {\n            display: inline-block;\n            padding: 2px 6px;\n            border-radius: 4px;\n            font-weight: bold;\n            font-size: 11px;\n        }\n        .score-good { background: #eef2e8; color: #788c5d; }\n        .score-ok { background: #fef3c7; color: #d97706; }\n        .score-bad { background: #fceaea; color: #c44; }\n        .train-label { color: #b0aea5; font-size: 10px; }\n        .test-label { color: #6a9bcc; font-size: 10px; font-weight: bold; }\n        .best-row { background: #f5f8f2; }\n        th.positive-col { border-bottom: 3px solid #788c5d; }\n        th.negative-col { border-bottom: 3px solid #c44; }\n        th.test-col.positive-col { border-bottom: 3px solid #788c5d; }\n        th.test-col.negative-col { border-bottom: 3px solid #c44; }\n        .legend { font-family: \'Poppins\', sans-serif; display: flex; gap: 20px; margin-bottom: 10px; font-size: 13px; align-items: center; }\n        .legend-item { display: flex; align-items: center; gap: 6px; }\n        .legend-swatch { width: 16px; height: 16px; border-radius: 3px; display: inline-block; }\n        .swatch-positive { background: #141413; border-bottom: 3px solid #788c5d; }\n        .swatch-negative { background: #141413; border-bottom: 3px solid #c44; }\n        .swatch-test { background: #6a9bcc; }\n        .swatch-train { background: #141413; }\n    </style>\n</head>\n<body>\n    <h1>\"\"\" + title_prefix + \"\"\"Skill Description Optimization</h1>\n    <div class=\"explainer\">\n        <strong>Optimizing your skill\'s description.</strong> This page updates automatically as Claude tests different versions of your skill\'s description. Each row is an iteration — a new description attempt. The columns show test queries: green checkmarks mean the skill triggered correctly (or correctly didn\'t trigger), red crosses mean it got it wrong. The \"Train\" score shows performance on queries used to improve the description; the \"Test\" score shows performance on held-out queries the optimizer hasn\'t seen. When it\'s done, Claude will apply the best-performing description to your skill.\n    </div>\n\"\"\"]\n\n    # Summary section\n    best_test_score = data.get(\'best_test_score\')\n    best_train_score = data.get(\'best_train_score\')\n    html_parts.append(f\"\"\"\n    <div class=\"summary\">\n        <p><strong>Original:</strong> {html.escape(data.get(\'original_description\', \'N/A\'))}</p>\n        <p class=\"best\"><strong>Best:</strong> {html.escape(data.get(\'best_description\', \'N/A\'))}</p>\n        <p><strong>Best Score:</strong> {data.get(\'best_score\', \'N/A\')} {\'(test)\' if best_test_score else \'(train)\'}</p>\n        <p><strong>Iterations:</strong> {data.get(\'iterations_run\', 0)} | <strong>Train:</strong> {data.get(\'train_size\', \'?\')} | <strong>Test:</strong> {data.get(\'test_size\', \'?\')}</p>\n    </div>\n\"\"\")\n\n    # Legend\n    html_parts.append(\"\"\"\n    <div class=\"legend\">\n        <span style=\"font-weight:600\">Query columns:</span>\n        <span class=\"legend-item\"><span class=\"legend-swatch swatch-positive\"></span> Should trigger</span>\n        <span class=\"legend-item\"><span class=\"legend-swatch swatch-negative\"></span> Should NOT trigger</span>\n        <span class=\"legend-item\"><span class=\"legend-swatch swatch-train\"></span> Train</span>\n        <span class=\"legend-item\"><span class=\"legend-swatch swatch-test\"></span> Test</span>\n    </div>\n\"\"\")\n\n    # Table header\n    html_parts.append(\"\"\"\n    <div class=\"table-container\">\n    <table>\n        <thead>\n            <tr>\n                <th>Iter</th>\n                <th>Train</th>\n                <th>Test</th>\n                <th class=\"query-col\">Description</th>\n\"\"\")\n\n    # Add column headers for train queries\n    for qinfo in train_queries:\n        polarity = \"positive-col\" if qinfo[\"should_trigger\"] else \"negative-col\"\n        html_parts.append(f\'                <th class=\"{polarity}\">{html.escape(qinfo[\"query\"])}</th>\\n\')\n\n    # Add column headers for test queries (different color)\n    for qinfo in test_queries:\n        polarity = \"positive-col\" if qinfo[\"should_trigger\"] else \"negative-col\"\n        html_parts.append(f\'                <th class=\"test-col {polarity}\">{html.escape(qinfo[\"query\"])}</th>\\n\')\n\n    html_parts.append(\"\"\"            </tr>\n        </thead>\n        <tbody>\n\"\"\")\n\n    # Find best iteration for highlighting\n    if test_queries:\n        best_iter = max(history, key=lambda h: h.get(\"test_passed\") or 0).get(\"iteration\")\n    else:\n        best_iter = max(history, key=lambda h: h.get(\"train_passed\", h.get(\"passed\", 0))).get(\"iteration\")\n\n    # Add rows for each iteration\n    for h in history:\n        iteration = h.get(\"iteration\", \"?\")\n        train_passed = h.get(\"train_passed\", h.get(\"passed\", 0))\n        train_total = h.get(\"train_total\", h.get(\"total\", 0))\n        test_passed = h.get(\"test_passed\")\n        test_total = h.get(\"test_total\")\n        description = h.get(\"description\", \"\")\n        train_results = h.get(\"train_results\", h.get(\"results\", []))\n        test_results = h.get(\"test_results\", [])\n\n        # Create lookups for results by query\n        train_by_query = {r[\"query\"]: r for r in train_results}\n        test_by_query = {r[\"query\"]: r for r in test_results} if test_results else {}\n\n        # Compute aggregate correct/total runs across all retries\n        def aggregate_runs(results: list[dict]) -> tuple[int, int]:\n            correct = 0\n            total = 0\n            for r in results:\n                runs = r.get(\"runs\", 0)\n                triggers = r.get(\"triggers\", 0)\n                total += runs\n                if r.get(\"should_trigger\", True):\n                    correct += triggers\n                else:\n                    correct += runs - triggers\n            return correct, total\n\n        train_correct, train_runs = aggregate_runs(train_results)\n        test_correct, test_runs = aggregate_runs(test_results)\n\n        # Determine score classes\n        def score_class(correct: int, total: int) -> str:\n            if total > 0:\n                ratio = correct / total\n                if ratio >= 0.8:\n                    return \"score-good\"\n                elif ratio >= 0.5:\n                    return \"score-ok\"\n            return \"score-bad\"\n\n        train_class = score_class(train_correct, train_runs)\n        test_class = score_class(test_correct, test_runs)\n\n        row_class = \"best-row\" if iteration == best_iter else \"\"\n\n        html_parts.append(f\"\"\"            <tr class=\"{row_class}\">\n                <td>{iteration}</td>\n                <td><span class=\"score {train_class}\">{train_correct}/{train_runs}</span></td>\n                <td><span class=\"score {test_class}\">{test_correct}/{test_runs}</span></td>\n                <td class=\"description\">{html.escape(description)}</td>\n\"\"\")\n\n        # Add result for each train query\n        for qinfo in train_queries:\n            r = train_by_query.get(qinfo[\"query\"], {})\n            did_pass = r.get(\"pass\", False)\n            triggers = r.get(\"triggers\", 0)\n            runs = r.get(\"runs\", 0)\n\n            icon = \"✓\" if did_pass else \"✗\"\n            css_class = \"pass\" if did_pass else \"fail\"\n\n            html_parts.append(f\'                <td class=\"result {css_class}\">{icon}<span class=\"rate\">{triggers}/{runs}</span></td>\\n\')\n\n        # Add result for each test query (with different background)\n        for qinfo in test_queries:\n            r = test_by_query.get(qinfo[\"query\"], {})\n            did_pass = r.get(\"pass\", False)\n            triggers = r.get(\"triggers\", 0)\n            runs = r.get(\"runs\", 0)\n\n            icon = \"✓\" if did_pass else \"✗\"\n            css_class = \"pass\" if did_pass else \"fail\"\n\n            html_parts.append(f\'                <td class=\"result test-result {css_class}\">{icon}<span class=\"rate\">{triggers}/{runs}</span></td>\\n\')\n\n        html_parts.append(\"            </tr>\\n\")\n\n    html_parts.append(\"\"\"        </tbody>\n    </table>\n    </div>\n\"\"\")\n\n    html_parts.append(\"\"\"\n</body>\n</html>\n\"\"\")\n\n    return \"\".join(html_parts)\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=\"Generate HTML report from run_loop output\")\n    parser.add_argument(\"input\", help=\"Path to JSON output from run_loop.py (or - for stdin)\")\n    parser.add_argument(\"-o\", \"--output\", default=None, help=\"Output HTML file (default: stdout)\")\n    parser.add_argument(\"--skill-name\", default=\"\", help=\"Skill name to include in the report title\")\n    args = parser.parse_args()\n\n    if args.input == \"-\":\n        data = json.load(sys.stdin)\n    else:\n        data = json.loads(Path(args.input).read_text())\n\n    html_output = generate_html(data, skill_name=args.skill_name)\n\n    if args.output:\n        Path(args.output).write_text(html_output)\n        print(f\"Report written to {args.output}\", file=sys.stderr)\n    else:\n        print(html_output)\n\n\nif __name__ == \"__main__\":\n    main()\n','09607615aed355c104f9c4f6dec7c9aa','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(1211,'enc.6167656e74732f616e616c797a65722e6d64','skill_enc.736b696c6c2d63726561746f72__enc.302e302e31','# Post-hoc Analyzer Agent\n\nAnalyze blind comparison results to understand WHY the winner won and generate improvement suggestions.\n\n## Role\n\nAfter the blind comparator determines a winner, the Post-hoc Analyzer \"unblids\" the results by examining the skills and transcripts. The goal is to extract actionable insights: what made the winner better, and how can the loser be improved?\n\n## Inputs\n\nYou receive these parameters in your prompt:\n\n- **winner**: \"A\" or \"B\" (from blind comparison)\n- **winner_skill_path**: Path to the skill that produced the winning output\n- **winner_transcript_path**: Path to the execution transcript for the winner\n- **loser_skill_path**: Path to the skill that produced the losing output\n- **loser_transcript_path**: Path to the execution transcript for the loser\n- **comparison_result_path**: Path to the blind comparator\'s output JSON\n- **output_path**: Where to save the analysis results\n\n## Process\n\n### Step 1: Read Comparison Result\n\n1. Read the blind comparator\'s output at comparison_result_path\n2. Note the winning side (A or B), the reasoning, and any scores\n3. Understand what the comparator valued in the winning output\n\n### Step 2: Read Both Skills\n\n1. Read the winner skill\'s SKILL.md and key referenced files\n2. Read the loser skill\'s SKILL.md and key referenced files\n3. Identify structural differences:\n   - Instructions clarity and specificity\n   - Script/tool usage patterns\n   - Example coverage\n   - Edge case handling\n\n### Step 3: Read Both Transcripts\n\n1. Read the winner\'s transcript\n2. Read the loser\'s transcript\n3. Compare execution patterns:\n   - How closely did each follow their skill\'s instructions?\n   - What tools were used differently?\n   - Where did the loser diverge from optimal behavior?\n   - Did either encounter errors or make recovery attempts?\n\n### Step 4: Analyze Instruction Following\n\nFor each transcript, evaluate:\n- Did the agent follow the skill\'s explicit instructions?\n- Did the agent use the skill\'s provided tools/scripts?\n- Were there missed opportunities to leverage skill content?\n- Did the agent add unnecessary steps not in the skill?\n\nScore instruction following 1-10 and note specific issues.\n\n### Step 5: Identify Winner Strengths\n\nDetermine what made the winner better:\n- Clearer instructions that led to better behavior?\n- Better scripts/tools that produced better output?\n- More comprehensive examples that guided edge cases?\n- Better error handling guidance?\n\nBe specific. Quote from skills/transcripts where relevant.\n\n### Step 6: Identify Loser Weaknesses\n\nDetermine what held the loser back:\n- Ambiguous instructions that led to suboptimal choices?\n- Missing tools/scripts that forced workarounds?\n- Gaps in edge case coverage?\n- Poor error handling that caused failures?\n\n### Step 7: Generate Improvement Suggestions\n\nBased on the analysis, produce actionable suggestions for improving the loser skill:\n- Specific instruction changes to make\n- Tools/scripts to add or modify\n- Examples to include\n- Edge cases to address\n\nPrioritize by impact. Focus on changes that would have changed the outcome.\n\n### Step 8: Write Analysis Results\n\nSave structured analysis to `{output_path}`.\n\n## Output Format\n\nWrite a JSON file with this structure:\n\n```json\n{\n  \"comparison_summary\": {\n    \"winner\": \"A\",\n    \"winner_skill\": \"path/to/winner/skill\",\n    \"loser_skill\": \"path/to/loser/skill\",\n    \"comparator_reasoning\": \"Brief summary of why comparator chose winner\"\n  },\n  \"winner_strengths\": [\n    \"Clear step-by-step instructions for handling multi-page documents\",\n    \"Included validation script that caught formatting errors\",\n    \"Explicit guidance on fallback behavior when OCR fails\"\n  ],\n  \"loser_weaknesses\": [\n    \"Vague instruction \'process the document appropriately\' led to inconsistent behavior\",\n    \"No script for validation, agent had to improvise and made errors\",\n    \"No guidance on OCR failure, agent gave up instead of trying alternatives\"\n  ],\n  \"instruction_following\": {\n    \"winner\": {\n      \"score\": 9,\n      \"issues\": [\n        \"Minor: skipped optional logging step\"\n      ]\n    },\n    \"loser\": {\n      \"score\": 6,\n      \"issues\": [\n        \"Did not use the skill\'s formatting template\",\n        \"Invented own approach instead of following step 3\",\n        \"Missed the \'always validate output\' instruction\"\n      ]\n    }\n  },\n  \"improvement_suggestions\": [\n    {\n      \"priority\": \"high\",\n      \"category\": \"instructions\",\n      \"suggestion\": \"Replace \'process the document appropriately\' with explicit steps: 1) Extract text, 2) Identify sections, 3) Format per template\",\n      \"expected_impact\": \"Would eliminate ambiguity that caused inconsistent behavior\"\n    },\n    {\n      \"priority\": \"high\",\n      \"category\": \"tools\",\n      \"suggestion\": \"Add validate_output.py script similar to winner skill\'s validation approach\",\n      \"expected_impact\": \"Would catch formatting errors before final output\"\n    },\n    {\n      \"priority\": \"medium\",\n      \"category\": \"error_handling\",\n      \"suggestion\": \"Add fallback instructions: \'If OCR fails, try: 1) different resolution, 2) image preprocessing, 3) manual extraction\'\",\n      \"expected_impact\": \"Would prevent early failure on difficult documents\"\n    }\n  ],\n  \"transcript_insights\": {\n    \"winner_execution_pattern\": \"Read skill -> Followed 5-step process -> Used validation script -> Fixed 2 issues -> Produced output\",\n    \"loser_execution_pattern\": \"Read skill -> Unclear on approach -> Tried 3 different methods -> No validation -> Output had errors\"\n  }\n}\n```\n\n## Guidelines\n\n- **Be specific**: Quote from skills and transcripts, don\'t just say \"instructions were unclear\"\n- **Be actionable**: Suggestions should be concrete changes, not vague advice\n- **Focus on skill improvements**: The goal is to improve the losing skill, not critique the agent\n- **Prioritize by impact**: Which changes would most likely have changed the outcome?\n- **Consider causation**: Did the skill weakness actually cause the worse output, or is it incidental?\n- **Stay objective**: Analyze what happened, don\'t editorialize\n- **Think about generalization**: Would this improvement help on other evals too?\n\n## Categories for Suggestions\n\nUse these categories to organize improvement suggestions:\n\n| Category | Description |\n|----------|-------------|\n| `instructions` | Changes to the skill\'s prose instructions |\n| `tools` | Scripts, templates, or utilities to add/modify |\n| `examples` | Example inputs/outputs to include |\n| `error_handling` | Guidance for handling failures |\n| `structure` | Reorganization of skill content |\n| `references` | External docs or resources to add |\n\n## Priority Levels\n\n- **high**: Would likely change the outcome of this comparison\n- **medium**: Would improve quality but may not change win/loss\n- **low**: Nice to have, marginal improvement\n\n---\n\n# Analyzing Benchmark Results\n\nWhen analyzing benchmark results, the analyzer\'s purpose is to **surface patterns and anomalies** across multiple runs, not suggest skill improvements.\n\n## Role\n\nReview all benchmark run results and generate freeform notes that help the user understand skill performance. Focus on patterns that wouldn\'t be visible from aggregate metrics alone.\n\n## Inputs\n\nYou receive these parameters in your prompt:\n\n- **benchmark_data_path**: Path to the in-progress benchmark.json with all run results\n- **skill_path**: Path to the skill being benchmarked\n- **output_path**: Where to save the notes (as JSON array of strings)\n\n## Process\n\n### Step 1: Read Benchmark Data\n\n1. Read the benchmark.json containing all run results\n2. Note the configurations tested (with_skill, without_skill)\n3. Understand the run_summary aggregates already calculated\n\n### Step 2: Analyze Per-Assertion Patterns\n\nFor each expectation across all runs:\n- Does it **always pass** in both configurations? (may not differentiate skill value)\n- Does it **always fail** in both configurations? (may be broken or beyond capability)\n- Does it **always pass with skill but fail without**? (skill clearly adds value here)\n- Does it **always fail with skill but pass without**? (skill may be hurting)\n- Is it **highly variable**? (flaky expectation or non-deterministic behavior)\n\n### Step 3: Analyze Cross-Eval Patterns\n\nLook for patterns across evals:\n- Are certain eval types consistently harder/easier?\n- Do some evals show high variance while others are stable?\n- Are there surprising results that contradict expectations?\n\n### Step 4: Analyze Metrics Patterns\n\nLook at time_seconds, tokens, tool_calls:\n- Does the skill significantly increase execution time?\n- Is there high variance in resource usage?\n- Are there outlier runs that skew the aggregates?\n\n### Step 5: Generate Notes\n\nWrite freeform observations as a list of strings. Each note should:\n- State a specific observation\n- Be grounded in the data (not speculation)\n- Help the user understand something the aggregate metrics don\'t show\n\nExamples:\n- \"Assertion \'Output is a PDF file\' passes 100% in both configurations - may not differentiate skill value\"\n- \"Eval 3 shows high variance (50% ± 40%) - run 2 had an unusual failure that may be flaky\"\n- \"Without-skill runs consistently fail on table extraction expectations (0% pass rate)\"\n- \"Skill adds 13s average execution time but improves pass rate by 50%\"\n- \"Token usage is 80% higher with skill, primarily due to script output parsing\"\n- \"All 3 without-skill runs for eval 1 produced empty output\"\n\n### Step 6: Write Notes\n\nSave notes to `{output_path}` as a JSON array of strings:\n\n```json\n[\n  \"Assertion \'Output is a PDF file\' passes 100% in both configurations - may not differentiate skill value\",\n  \"Eval 3 shows high variance (50% ± 40%) - run 2 had an unusual failure\",\n  \"Without-skill runs consistently fail on table extraction expectations\",\n  \"Skill adds 13s average execution time but improves pass rate by 50%\"\n]\n```\n\n## Guidelines\n\n**DO:**\n- Report what you observe in the data\n- Be specific about which evals, expectations, or runs you\'re referring to\n- Note patterns that aggregate metrics would hide\n- Provide context that helps interpret the numbers\n\n**DO NOT:**\n- Suggest improvements to the skill (that\'s for the improvement step, not benchmarking)\n- Make subjective quality judgments (\"the output was good/bad\")\n- Speculate about causes without evidence\n- Repeat information already in the run_summary aggregates\n','b78964a8d55ff0e038d657a9cb79f46a','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(1212,'enc.736372697074732f67656e65726174655f7265706f72742e7079','skill_enc.736b696c6c2d63726561746f72__enc.302e302e31','#!/usr/bin/env python3\n\"\"\"Generate an HTML report from run_loop.py output.\n\nTakes the JSON output from run_loop.py and generates a visual HTML report\nshowing each description attempt with check/x for each test case.\nDistinguishes between train and test queries.\n\"\"\"\n\nimport argparse\nimport html\nimport json\nimport sys\nfrom pathlib import Path\n\n\ndef generate_html(data: dict, auto_refresh: bool = False, skill_name: str = \"\") -> str:\n    \"\"\"Generate HTML report from loop output data. If auto_refresh is True, adds a meta refresh tag.\"\"\"\n    history = data.get(\"history\", [])\n    holdout = data.get(\"holdout\", 0)\n    title_prefix = html.escape(skill_name + \" \\u2014 \") if skill_name else \"\"\n\n    # Get all unique queries from train and test sets, with should_trigger info\n    train_queries: list[dict] = []\n    test_queries: list[dict] = []\n    if history:\n        for r in history[0].get(\"train_results\", history[0].get(\"results\", [])):\n            train_queries.append({\"query\": r[\"query\"], \"should_trigger\": r.get(\"should_trigger\", True)})\n        if history[0].get(\"test_results\"):\n            for r in history[0].get(\"test_results\", []):\n                test_queries.append({\"query\": r[\"query\"], \"should_trigger\": r.get(\"should_trigger\", True)})\n\n    refresh_tag = \'    <meta http-equiv=\"refresh\" content=\"5\">\\n\' if auto_refresh else \"\"\n\n    html_parts = [\"\"\"<!DOCTYPE html>\n<html>\n<head>\n    <meta charset=\"utf-8\">\n\"\"\" + refresh_tag + \"\"\"    <title>\"\"\" + title_prefix + \"\"\"Skill Description Optimization</title>\n    <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n    <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n    <link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@500;600&family=Lora:wght@400;500&display=swap\" rel=\"stylesheet\">\n    <style>\n        body {\n            font-family: \'Lora\', Georgia, serif;\n            max-width: 100%;\n            margin: 0 auto;\n            padding: 20px;\n            background: #faf9f5;\n            color: #141413;\n        }\n        h1 { font-family: \'Poppins\', sans-serif; color: #141413; }\n        .explainer {\n            background: white;\n            padding: 15px;\n            border-radius: 6px;\n            margin-bottom: 20px;\n            border: 1px solid #e8e6dc;\n            color: #b0aea5;\n            font-size: 0.875rem;\n            line-height: 1.6;\n        }\n        .summary {\n            background: white;\n            padding: 15px;\n            border-radius: 6px;\n            margin-bottom: 20px;\n            border: 1px solid #e8e6dc;\n        }\n        .summary p { margin: 5px 0; }\n        .best { color: #788c5d; font-weight: bold; }\n        .table-container {\n            overflow-x: auto;\n            width: 100%;\n        }\n        table {\n            border-collapse: collapse;\n            background: white;\n            border: 1px solid #e8e6dc;\n            border-radius: 6px;\n            font-size: 12px;\n            min-width: 100%;\n        }\n        th, td {\n            padding: 8px;\n            text-align: left;\n            border: 1px solid #e8e6dc;\n            white-space: normal;\n            word-wrap: break-word;\n        }\n        th {\n            font-family: \'Poppins\', sans-serif;\n            background: #141413;\n            color: #faf9f5;\n            font-weight: 500;\n        }\n        th.test-col {\n            background: #6a9bcc;\n        }\n        th.query-col { min-width: 200px; }\n        td.description {\n            font-family: monospace;\n            font-size: 11px;\n            word-wrap: break-word;\n            max-width: 400px;\n        }\n        td.result {\n            text-align: center;\n            font-size: 16px;\n            min-width: 40px;\n        }\n        td.test-result {\n            background: #f0f6fc;\n        }\n        .pass { color: #788c5d; }\n        .fail { color: #c44; }\n        .rate {\n            font-size: 9px;\n            color: #b0aea5;\n            display: block;\n        }\n        tr:hover { background: #faf9f5; }\n        .score {\n            display: inline-block;\n            padding: 2px 6px;\n            border-radius: 4px;\n            font-weight: bold;\n            font-size: 11px;\n        }\n        .score-good { background: #eef2e8; color: #788c5d; }\n        .score-ok { background: #fef3c7; color: #d97706; }\n        .score-bad { background: #fceaea; color: #c44; }\n        .train-label { color: #b0aea5; font-size: 10px; }\n        .test-label { color: #6a9bcc; font-size: 10px; font-weight: bold; }\n        .best-row { background: #f5f8f2; }\n        th.positive-col { border-bottom: 3px solid #788c5d; }\n        th.negative-col { border-bottom: 3px solid #c44; }\n        th.test-col.positive-col { border-bottom: 3px solid #788c5d; }\n        th.test-col.negative-col { border-bottom: 3px solid #c44; }\n        .legend { font-family: \'Poppins\', sans-serif; display: flex; gap: 20px; margin-bottom: 10px; font-size: 13px; align-items: center; }\n        .legend-item { display: flex; align-items: center; gap: 6px; }\n        .legend-swatch { width: 16px; height: 16px; border-radius: 3px; display: inline-block; }\n        .swatch-positive { background: #141413; border-bottom: 3px solid #788c5d; }\n        .swatch-negative { background: #141413; border-bottom: 3px solid #c44; }\n        .swatch-test { background: #6a9bcc; }\n        .swatch-train { background: #141413; }\n    </style>\n</head>\n<body>\n    <h1>\"\"\" + title_prefix + \"\"\"Skill Description Optimization</h1>\n    <div class=\"explainer\">\n        <strong>Optimizing your skill\'s description.</strong> This page updates automatically as Claude tests different versions of your skill\'s description. Each row is an iteration — a new description attempt. The columns show test queries: green checkmarks mean the skill triggered correctly (or correctly didn\'t trigger), red crosses mean it got it wrong. The \"Train\" score shows performance on queries used to improve the description; the \"Test\" score shows performance on held-out queries the optimizer hasn\'t seen. When it\'s done, Claude will apply the best-performing description to your skill.\n    </div>\n\"\"\"]\n\n    # Summary section\n    best_test_score = data.get(\'best_test_score\')\n    best_train_score = data.get(\'best_train_score\')\n    html_parts.append(f\"\"\"\n    <div class=\"summary\">\n        <p><strong>Original:</strong> {html.escape(data.get(\'original_description\', \'N/A\'))}</p>\n        <p class=\"best\"><strong>Best:</strong> {html.escape(data.get(\'best_description\', \'N/A\'))}</p>\n        <p><strong>Best Score:</strong> {data.get(\'best_score\', \'N/A\')} {\'(test)\' if best_test_score else \'(train)\'}</p>\n        <p><strong>Iterations:</strong> {data.get(\'iterations_run\', 0)} | <strong>Train:</strong> {data.get(\'train_size\', \'?\')} | <strong>Test:</strong> {data.get(\'test_size\', \'?\')}</p>\n    </div>\n\"\"\")\n\n    # Legend\n    html_parts.append(\"\"\"\n    <div class=\"legend\">\n        <span style=\"font-weight:600\">Query columns:</span>\n        <span class=\"legend-item\"><span class=\"legend-swatch swatch-positive\"></span> Should trigger</span>\n        <span class=\"legend-item\"><span class=\"legend-swatch swatch-negative\"></span> Should NOT trigger</span>\n        <span class=\"legend-item\"><span class=\"legend-swatch swatch-train\"></span> Train</span>\n        <span class=\"legend-item\"><span class=\"legend-swatch swatch-test\"></span> Test</span>\n    </div>\n\"\"\")\n\n    # Table header\n    html_parts.append(\"\"\"\n    <div class=\"table-container\">\n    <table>\n        <thead>\n            <tr>\n                <th>Iter</th>\n                <th>Train</th>\n                <th>Test</th>\n                <th class=\"query-col\">Description</th>\n\"\"\")\n\n    # Add column headers for train queries\n    for qinfo in train_queries:\n        polarity = \"positive-col\" if qinfo[\"should_trigger\"] else \"negative-col\"\n        html_parts.append(f\'                <th class=\"{polarity}\">{html.escape(qinfo[\"query\"])}</th>\\n\')\n\n    # Add column headers for test queries (different color)\n    for qinfo in test_queries:\n        polarity = \"positive-col\" if qinfo[\"should_trigger\"] else \"negative-col\"\n        html_parts.append(f\'                <th class=\"test-col {polarity}\">{html.escape(qinfo[\"query\"])}</th>\\n\')\n\n    html_parts.append(\"\"\"            </tr>\n        </thead>\n        <tbody>\n\"\"\")\n\n    # Find best iteration for highlighting\n    if test_queries:\n        best_iter = max(history, key=lambda h: h.get(\"test_passed\") or 0).get(\"iteration\")\n    else:\n        best_iter = max(history, key=lambda h: h.get(\"train_passed\", h.get(\"passed\", 0))).get(\"iteration\")\n\n    # Add rows for each iteration\n    for h in history:\n        iteration = h.get(\"iteration\", \"?\")\n        train_passed = h.get(\"train_passed\", h.get(\"passed\", 0))\n        train_total = h.get(\"train_total\", h.get(\"total\", 0))\n        test_passed = h.get(\"test_passed\")\n        test_total = h.get(\"test_total\")\n        description = h.get(\"description\", \"\")\n        train_results = h.get(\"train_results\", h.get(\"results\", []))\n        test_results = h.get(\"test_results\", [])\n\n        # Create lookups for results by query\n        train_by_query = {r[\"query\"]: r for r in train_results}\n        test_by_query = {r[\"query\"]: r for r in test_results} if test_results else {}\n\n        # Compute aggregate correct/total runs across all retries\n        def aggregate_runs(results: list[dict]) -> tuple[int, int]:\n            correct = 0\n            total = 0\n            for r in results:\n                runs = r.get(\"runs\", 0)\n                triggers = r.get(\"triggers\", 0)\n                total += runs\n                if r.get(\"should_trigger\", True):\n                    correct += triggers\n                else:\n                    correct += runs - triggers\n            return correct, total\n\n        train_correct, train_runs = aggregate_runs(train_results)\n        test_correct, test_runs = aggregate_runs(test_results)\n\n        # Determine score classes\n        def score_class(correct: int, total: int) -> str:\n            if total > 0:\n                ratio = correct / total\n                if ratio >= 0.8:\n                    return \"score-good\"\n                elif ratio >= 0.5:\n                    return \"score-ok\"\n            return \"score-bad\"\n\n        train_class = score_class(train_correct, train_runs)\n        test_class = score_class(test_correct, test_runs)\n\n        row_class = \"best-row\" if iteration == best_iter else \"\"\n\n        html_parts.append(f\"\"\"            <tr class=\"{row_class}\">\n                <td>{iteration}</td>\n                <td><span class=\"score {train_class}\">{train_correct}/{train_runs}</span></td>\n                <td><span class=\"score {test_class}\">{test_correct}/{test_runs}</span></td>\n                <td class=\"description\">{html.escape(description)}</td>\n\"\"\")\n\n        # Add result for each train query\n        for qinfo in train_queries:\n            r = train_by_query.get(qinfo[\"query\"], {})\n            did_pass = r.get(\"pass\", False)\n            triggers = r.get(\"triggers\", 0)\n            runs = r.get(\"runs\", 0)\n\n            icon = \"✓\" if did_pass else \"✗\"\n            css_class = \"pass\" if did_pass else \"fail\"\n\n            html_parts.append(f\'                <td class=\"result {css_class}\">{icon}<span class=\"rate\">{triggers}/{runs}</span></td>\\n\')\n\n        # Add result for each test query (with different background)\n        for qinfo in test_queries:\n            r = test_by_query.get(qinfo[\"query\"], {})\n            did_pass = r.get(\"pass\", False)\n            triggers = r.get(\"triggers\", 0)\n            runs = r.get(\"runs\", 0)\n\n            icon = \"✓\" if did_pass else \"✗\"\n            css_class = \"pass\" if did_pass else \"fail\"\n\n            html_parts.append(f\'                <td class=\"result test-result {css_class}\">{icon}<span class=\"rate\">{triggers}/{runs}</span></td>\\n\')\n\n        html_parts.append(\"            </tr>\\n\")\n\n    html_parts.append(\"\"\"        </tbody>\n    </table>\n    </div>\n\"\"\")\n\n    html_parts.append(\"\"\"\n</body>\n</html>\n\"\"\")\n\n    return \"\".join(html_parts)\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=\"Generate HTML report from run_loop output\")\n    parser.add_argument(\"input\", help=\"Path to JSON output from run_loop.py (or - for stdin)\")\n    parser.add_argument(\"-o\", \"--output\", default=None, help=\"Output HTML file (default: stdout)\")\n    parser.add_argument(\"--skill-name\", default=\"\", help=\"Skill name to include in the report title\")\n    args = parser.parse_args()\n\n    if args.input == \"-\":\n        data = json.load(sys.stdin)\n    else:\n        data = json.loads(Path(args.input).read_text())\n\n    html_output = generate_html(data, skill_name=args.skill_name)\n\n    if args.output:\n        Path(args.output).write_text(html_output)\n        print(f\"Report written to {args.output}\", file=sys.stderr)\n    else:\n        print(html_output)\n\n\nif __name__ == \"__main__\":\n    main()\n','09607615aed355c104f9c4f6dec7c9aa','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(1213,'resource_config_MEMORY__md.json','agentspec__enc.656e67696e656572696e672d736f6674776172652d617263686974656374__enc.302e302e31','{\"name\":\"MEMORY.md\",\"type\":\"config\",\"content\":\"# 长期记忆\\n\\n由运行时写入；本模板未预置业务记忆。\\n\",\"metadata\":{\"uniformId\":1792984920148},\"resourceIdentifier\":\"config::MEMORY.md\"}','0677df22cd3e0f3efbfd273c7b1765bc','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(1214,'manifest.json','agentspec__enc.656e67696e656572696e672d736f6c69646974792d736d6172742d636f6e74726163742d656e67696e656572__enc.302e302e31','{\"name\":\"engineering-solidity-smart-contract-engineer\",\"description\":\"精通 EVM 智能合约架构、Gas 优化、可升级代理模式、DeFi 协议开发和安全优先合约设计的 Solidity 开发专家，覆盖 Ethereum 及 L2 链。\",\"content\":\"{\\n  \\\"version\\\": \\\"1.0\\\",\\n  \\\"source\\\": {\\n    \\\"repository\\\": \\\"https://github.com/jnMetaCode/agency-agents-zh\\\",\\n    \\\"commit\\\": \\\"23c2746913fe46260450517fa5afb58afc61fed7\\\",\\n    \\\"original_path\\\": \\\"engineering/engineering-solidity-smart-contract-engineer.md\\\",\\n    \\\"openclaw_mode\\\": true\\n  },\\n  \\\"description\\\": \\\"精通 EVM 智能合约架构、Gas 优化、可升级代理模式、DeFi 协议开发和安全优先合约设计的 Solidity 开发专家，覆盖 Ethereum 及 L2 链。\\\",\\n  \\\"tags\\\": [\\n    \\\"engineering\\\"\\n  ],\\n  \\\"worker\\\": {\\n    \\\"suggested_name\\\": \\\"engineering-solidity-smart-contract-engineer\\\",\\n    \\\"base_image\\\": \\\"hiclaw/worker-agent:latest\\\",\\n    \\\"apt_packages\\\": [],\\n    \\\"pip_packages\\\": [],\\n    \\\"npm_packages\\\": []\\n  },\\n  \\\"proxy\\\": {\\n    \\\"suggested\\\": false,\\n    \\\"reason\\\": \\\"\\\"\\n  }\\n}\\n\",\"uniformId\":1792984920326,\"resources\":[{\"name\":\"jobs.json\",\"type\":\"crons\"},{\"name\":\"IDENTITY.md\",\"type\":\"config\"},{\"name\":\"tool-analysis.json\",\"type\":\"tool-analysis\"},{\"name\":\"AGENTS.md\",\"type\":\"config\"},{\"name\":\"SOUL.md\",\"type\":\"config\"},{\"name\":\"MEMORY.md\",\"type\":\"config\"}]}','30e3c1c5924cd2263a74494bf6e5e8ac','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(1215,'resource_config_MEMORY__md.json','agentspec__enc.656e67696e656572696e672d736f6674776172652d617263686974656374__enc.302e302e31','{\"name\":\"MEMORY.md\",\"type\":\"config\",\"content\":\"# 长期记忆\\n\\n由运行时写入；本模板未预置业务记忆。\\n\",\"metadata\":{\"uniformId\":1792984920148},\"resourceIdentifier\":\"config::MEMORY.md\"}','0677df22cd3e0f3efbfd273c7b1765bc','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(1216,'resource_crons_jobs__json.json','agentspec__enc.656e67696e656572696e672d736f6c69646974792d736d6172742d636f6e74726163742d656e67696e656572__enc.302e302e31','{\"name\":\"jobs.json\",\"type\":\"crons\",\"content\":\"[]\\n\",\"metadata\":{\"uniformId\":1792984920326},\"resourceIdentifier\":\"crons::jobs.json\"}','065e6efd5bf116973ea5551d7e7702f5','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(1217,'manifest.json','agentspec__enc.656e67696e656572696e672d736f6c69646974792d736d6172742d636f6e74726163742d656e67696e656572__enc.302e302e31','{\"name\":\"engineering-solidity-smart-contract-engineer\",\"description\":\"精通 EVM 智能合约架构、Gas 优化、可升级代理模式、DeFi 协议开发和安全优先合约设计的 Solidity 开发专家，覆盖 Ethereum 及 L2 链。\",\"content\":\"{\\n  \\\"version\\\": \\\"1.0\\\",\\n  \\\"source\\\": {\\n    \\\"repository\\\": \\\"https://github.com/jnMetaCode/agency-agents-zh\\\",\\n    \\\"commit\\\": \\\"23c2746913fe46260450517fa5afb58afc61fed7\\\",\\n    \\\"original_path\\\": \\\"engineering/engineering-solidity-smart-contract-engineer.md\\\",\\n    \\\"openclaw_mode\\\": true\\n  },\\n  \\\"description\\\": \\\"精通 EVM 智能合约架构、Gas 优化、可升级代理模式、DeFi 协议开发和安全优先合约设计的 Solidity 开发专家，覆盖 Ethereum 及 L2 链。\\\",\\n  \\\"tags\\\": [\\n    \\\"engineering\\\"\\n  ],\\n  \\\"worker\\\": {\\n    \\\"suggested_name\\\": \\\"engineering-solidity-smart-contract-engineer\\\",\\n    \\\"base_image\\\": \\\"hiclaw/worker-agent:latest\\\",\\n    \\\"apt_packages\\\": [],\\n    \\\"pip_packages\\\": [],\\n    \\\"npm_packages\\\": []\\n  },\\n  \\\"proxy\\\": {\\n    \\\"suggested\\\": false,\\n    \\\"reason\\\": \\\"\\\"\\n  }\\n}\\n\",\"uniformId\":1792984920326,\"resources\":[{\"name\":\"jobs.json\",\"type\":\"crons\"},{\"name\":\"IDENTITY.md\",\"type\":\"config\"},{\"name\":\"tool-analysis.json\",\"type\":\"tool-analysis\"},{\"name\":\"AGENTS.md\",\"type\":\"config\"},{\"name\":\"SOUL.md\",\"type\":\"config\"},{\"name\":\"MEMORY.md\",\"type\":\"config\"}]}','30e3c1c5924cd2263a74494bf6e5e8ac','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(1218,'enc.736372697074732f696d70726f76655f6465736372697074696f6e2e7079','skill_enc.736b696c6c2d63726561746f72__enc.302e302e31','#!/usr/bin/env python3\n\"\"\"Improve a skill description based on eval results.\n\nTakes eval results (from run_eval.py) and generates an improved description\nby calling `claude -p` as a subprocess (same auth pattern as run_eval.py —\nuses the session\'s Claude Code auth, no separate ANTHROPIC_API_KEY needed).\n\"\"\"\n\nimport argparse\nimport json\nimport os\nimport re\nimport subprocess\nimport sys\nfrom pathlib import Path\n\nfrom scripts.utils import parse_skill_md\n\n\ndef _call_claude(prompt: str, model: str | None, timeout: int = 300) -> str:\n    \"\"\"Run `claude -p` with the prompt on stdin and return the text response.\n\n    Prompt goes over stdin (not argv) because it embeds the full SKILL.md\n    body and can easily exceed comfortable argv length.\n    \"\"\"\n    cmd = [\"claude\", \"-p\", \"--output-format\", \"text\"]\n    if model:\n        cmd.extend([\"--model\", model])\n\n    # Remove CLAUDECODE env var to allow nesting claude -p inside a\n    # Claude Code session. The guard is for interactive terminal conflicts;\n    # programmatic subprocess usage is safe. Same pattern as run_eval.py.\n    env = {k: v for k, v in os.environ.items() if k != \"CLAUDECODE\"}\n\n    result = subprocess.run(\n        cmd,\n        input=prompt,\n        capture_output=True,\n        text=True,\n        env=env,\n        timeout=timeout,\n    )\n    if result.returncode != 0:\n        raise RuntimeError(\n            f\"claude -p exited {result.returncode}\\nstderr: {result.stderr}\"\n        )\n    return result.stdout\n\n\ndef improve_description(\n    skill_name: str,\n    skill_content: str,\n    current_description: str,\n    eval_results: dict,\n    history: list[dict],\n    model: str,\n    test_results: dict | None = None,\n    log_dir: Path | None = None,\n    iteration: int | None = None,\n) -> str:\n    \"\"\"Call Claude to improve the description based on eval results.\"\"\"\n    failed_triggers = [\n        r for r in eval_results[\"results\"]\n        if r[\"should_trigger\"] and not r[\"pass\"]\n    ]\n    false_triggers = [\n        r for r in eval_results[\"results\"]\n        if not r[\"should_trigger\"] and not r[\"pass\"]\n    ]\n\n    # Build scores summary\n    train_score = f\"{eval_results[\'summary\'][\'passed\']}/{eval_results[\'summary\'][\'total\']}\"\n    if test_results:\n        test_score = f\"{test_results[\'summary\'][\'passed\']}/{test_results[\'summary\'][\'total\']}\"\n        scores_summary = f\"Train: {train_score}, Test: {test_score}\"\n    else:\n        scores_summary = f\"Train: {train_score}\"\n\n    prompt = f\"\"\"You are optimizing a skill description for a Claude Code skill called \"{skill_name}\". A \"skill\" is sort of like a prompt, but with progressive disclosure -- there\'s a title and description that Claude sees when deciding whether to use the skill, and then if it does use the skill, it reads the .md file which has lots more details and potentially links to other resources in the skill folder like helper files and scripts and additional documentation or examples.\n\nThe description appears in Claude\'s \"available_skills\" list. When a user sends a query, Claude decides whether to invoke the skill based solely on the title and on this description. Your goal is to write a description that triggers for relevant queries, and doesn\'t trigger for irrelevant ones.\n\nHere\'s the current description:\n<current_description>\n\"{current_description}\"\n</current_description>\n\nCurrent scores ({scores_summary}):\n<scores_summary>\n\"\"\"\n    if failed_triggers:\n        prompt += \"FAILED TO TRIGGER (should have triggered but didn\'t):\\n\"\n        for r in failed_triggers:\n            prompt += f\'  - \"{r[\"query\"]}\" (triggered {r[\"triggers\"]}/{r[\"runs\"]} times)\\n\'\n        prompt += \"\\n\"\n\n    if false_triggers:\n        prompt += \"FALSE TRIGGERS (triggered but shouldn\'t have):\\n\"\n        for r in false_triggers:\n            prompt += f\'  - \"{r[\"query\"]}\" (triggered {r[\"triggers\"]}/{r[\"runs\"]} times)\\n\'\n        prompt += \"\\n\"\n\n    if history:\n        prompt += \"PREVIOUS ATTEMPTS (do NOT repeat these — try something structurally different):\\n\\n\"\n        for h in history:\n            train_s = f\"{h.get(\'train_passed\', h.get(\'passed\', 0))}/{h.get(\'train_total\', h.get(\'total\', 0))}\"\n            test_s = f\"{h.get(\'test_passed\', \'?\')}/{h.get(\'test_total\', \'?\')}\" if h.get(\'test_passed\') is not None else None\n            score_str = f\"train={train_s}\" + (f\", test={test_s}\" if test_s else \"\")\n            prompt += f\'<attempt {score_str}>\\n\'\n            prompt += f\'Description: \"{h[\"description\"]}\"\\n\'\n            if \"results\" in h:\n                prompt += \"Train results:\\n\"\n                for r in h[\"results\"]:\n                    status = \"PASS\" if r[\"pass\"] else \"FAIL\"\n                    prompt += f\'  [{status}] \"{r[\"query\"][:80]}\" (triggered {r[\"triggers\"]}/{r[\"runs\"]})\\n\'\n            if h.get(\"note\"):\n                prompt += f\'Note: {h[\"note\"]}\\n\'\n            prompt += \"</attempt>\\n\\n\"\n\n    prompt += f\"\"\"</scores_summary>\n\nSkill content (for context on what the skill does):\n<skill_content>\n{skill_content}\n</skill_content>\n\nBased on the failures, write a new and improved description that is more likely to trigger correctly. When I say \"based on the failures\", it\'s a bit of a tricky line to walk because we don\'t want to overfit to the specific cases you\'re seeing. So what I DON\'T want you to do is produce an ever-expanding list of specific queries that this skill should or shouldn\'t trigger for. Instead, try to generalize from the failures to broader categories of user intent and situations where this skill would be useful or not useful. The reason for this is twofold:\n\n1. Avoid overfitting\n2. The list might get loooong and it\'s injected into ALL queries and there might be a lot of skills, so we don\'t want to blow too much space on any given description.\n\nConcretely, your description should not be more than about 100-200 words, even if that comes at the cost of accuracy. There is a hard limit of 1024 characters — descriptions over that will be truncated, so stay comfortably under it.\n\nHere are some tips that we\'ve found to work well in writing these descriptions:\n- The skill should be phrased in the imperative -- \"Use this skill for\" rather than \"this skill does\"\n- The skill description should focus on the user\'s intent, what they are trying to achieve, vs. the implementation details of how the skill works.\n- The description competes with other skills for Claude\'s attention — make it distinctive and immediately recognizable.\n- If you\'re getting lots of failures after repeated attempts, change things up. Try different sentence structures or wordings.\n\nI\'d encourage you to be creative and mix up the style in different iterations since you\'ll have multiple opportunities to try different approaches and we\'ll just grab the highest-scoring one at the end. \n\nPlease respond with only the new description text in <new_description> tags, nothing else.\"\"\"\n\n    text = _call_claude(prompt, model)\n\n    match = re.search(r\"<new_description>(.*?)</new_description>\", text, re.DOTALL)\n    description = match.group(1).strip().strip(\'\"\') if match else text.strip().strip(\'\"\')\n\n    transcript: dict = {\n        \"iteration\": iteration,\n        \"prompt\": prompt,\n        \"response\": text,\n        \"parsed_description\": description,\n        \"char_count\": len(description),\n        \"over_limit\": len(description) > 1024,\n    }\n\n    # Safety net: the prompt already states the 1024-char hard limit, but if\n    # the model blew past it anyway, make one fresh single-turn call that\n    # quotes the too-long version and asks for a shorter rewrite. (The old\n    # SDK path did this as a true multi-turn; `claude -p` is one-shot, so we\n    # inline the prior output into the new prompt instead.)\n    if len(description) > 1024:\n        shorten_prompt = (\n            f\"{prompt}\\n\\n\"\n            f\"---\\n\\n\"\n            f\"A previous attempt produced this description, which at \"\n            f\"{len(description)} characters is over the 1024-character hard limit:\\n\\n\"\n            f\'\"{description}\"\\n\\n\'\n            f\"Rewrite it to be under 1024 characters while keeping the most \"\n            f\"important trigger words and intent coverage. Respond with only \"\n            f\"the new description in <new_description> tags.\"\n        )\n        shorten_text = _call_claude(shorten_prompt, model)\n        match = re.search(r\"<new_description>(.*?)</new_description>\", shorten_text, re.DOTALL)\n        shortened = match.group(1).strip().strip(\'\"\') if match else shorten_text.strip().strip(\'\"\')\n\n        transcript[\"rewrite_prompt\"] = shorten_prompt\n        transcript[\"rewrite_response\"] = shorten_text\n        transcript[\"rewrite_description\"] = shortened\n        transcript[\"rewrite_char_count\"] = len(shortened)\n        description = shortened\n\n    transcript[\"final_description\"] = description\n\n    if log_dir:\n        log_dir.mkdir(parents=True, exist_ok=True)\n        log_file = log_dir / f\"improve_iter_{iteration or \'unknown\'}.json\"\n        log_file.write_text(json.dumps(transcript, indent=2))\n\n    return description\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=\"Improve a skill description based on eval results\")\n    parser.add_argument(\"--eval-results\", required=True, help=\"Path to eval results JSON (from run_eval.py)\")\n    parser.add_argument(\"--skill-path\", required=True, help=\"Path to skill directory\")\n    parser.add_argument(\"--history\", default=None, help=\"Path to history JSON (previous attempts)\")\n    parser.add_argument(\"--model\", required=True, help=\"Model for improvement\")\n    parser.add_argument(\"--verbose\", action=\"store_true\", help=\"Print thinking to stderr\")\n    args = parser.parse_args()\n\n    skill_path = Path(args.skill_path)\n    if not (skill_path / \"SKILL.md\").exists():\n        print(f\"Error: No SKILL.md found at {skill_path}\", file=sys.stderr)\n        sys.exit(1)\n\n    eval_results = json.loads(Path(args.eval_results).read_text())\n    history = []\n    if args.history:\n        history = json.loads(Path(args.history).read_text())\n\n    name, _, content = parse_skill_md(skill_path)\n    current_description = eval_results[\"description\"]\n\n    if args.verbose:\n        print(f\"Current: {current_description}\", file=sys.stderr)\n        print(f\"Score: {eval_results[\'summary\'][\'passed\']}/{eval_results[\'summary\'][\'total\']}\", file=sys.stderr)\n\n    new_description = improve_description(\n        skill_name=name,\n        skill_content=content,\n        current_description=current_description,\n        eval_results=eval_results,\n        history=history,\n        model=args.model,\n    )\n\n    if args.verbose:\n        print(f\"Improved: {new_description}\", file=sys.stderr)\n\n    # Output as JSON with both the new description and updated history\n    output = {\n        \"description\": new_description,\n        \"history\": history + [{\n            \"description\": current_description,\n            \"passed\": eval_results[\"summary\"][\"passed\"],\n            \"failed\": eval_results[\"summary\"][\"failed\"],\n            \"total\": eval_results[\"summary\"][\"total\"],\n            \"results\": eval_results[\"results\"],\n        }],\n    }\n    print(json.dumps(output, indent=2))\n\n\nif __name__ == \"__main__\":\n    main()\n','b20bbcc3d69bc299b541c8b62c25cefe','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(1219,'resource_crons_jobs__json.json','agentspec__enc.656e67696e656572696e672d736f6c69646974792d736d6172742d636f6e74726163742d656e67696e656572__enc.302e302e31','{\"name\":\"jobs.json\",\"type\":\"crons\",\"content\":\"[]\\n\",\"metadata\":{\"uniformId\":1792984920326},\"resourceIdentifier\":\"crons::jobs.json\"}','065e6efd5bf116973ea5551d7e7702f5','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(1220,'enc.736372697074732f72756e5f6576616c2e7079','skill_enc.736b696c6c2d63726561746f72__enc.302e302e31','#!/usr/bin/env python3\n\"\"\"Run trigger evaluation for a skill description.\n\nTests whether a skill\'s description causes Claude to trigger (read the skill)\nfor a set of queries. Outputs results as JSON.\n\"\"\"\n\nimport argparse\nimport json\nimport os\nimport select\nimport subprocess\nimport sys\nimport time\nimport uuid\nfrom concurrent.futures import ProcessPoolExecutor, as_completed\nfrom pathlib import Path\n\nfrom scripts.utils import parse_skill_md\n\n\ndef find_project_root() -> Path:\n    \"\"\"Find the project root by walking up from cwd looking for .claude/.\n\n    Mimics how Claude Code discovers its project root, so the command file\n    we create ends up where claude -p will look for it.\n    \"\"\"\n    current = Path.cwd()\n    for parent in [current, *current.parents]:\n        if (parent / \".claude\").is_dir():\n            return parent\n    return current\n\n\ndef run_single_query(\n    query: str,\n    skill_name: str,\n    skill_description: str,\n    timeout: int,\n    project_root: str,\n    model: str | None = None,\n) -> bool:\n    \"\"\"Run a single query and return whether the skill was triggered.\n\n    Creates a command file in .claude/commands/ so it appears in Claude\'s\n    available_skills list, then runs `claude -p` with the raw query.\n    Uses --include-partial-messages to detect triggering early from\n    stream events (content_block_start) rather than waiting for the\n    full assistant message, which only arrives after tool execution.\n    \"\"\"\n    unique_id = uuid.uuid4().hex[:8]\n    clean_name = f\"{skill_name}-skill-{unique_id}\"\n    project_commands_dir = Path(project_root) / \".claude\" / \"commands\"\n    command_file = project_commands_dir / f\"{clean_name}.md\"\n\n    try:\n        project_commands_dir.mkdir(parents=True, exist_ok=True)\n        # Use YAML block scalar to avoid breaking on quotes in description\n        indented_desc = \"\\n  \".join(skill_description.split(\"\\n\"))\n        command_content = (\n            f\"---\\n\"\n            f\"description: |\\n\"\n            f\"  {indented_desc}\\n\"\n            f\"---\\n\\n\"\n            f\"# {skill_name}\\n\\n\"\n            f\"This skill handles: {skill_description}\\n\"\n        )\n        command_file.write_text(command_content)\n\n        cmd = [\n            \"claude\",\n            \"-p\", query,\n            \"--output-format\", \"stream-json\",\n            \"--verbose\",\n            \"--include-partial-messages\",\n        ]\n        if model:\n            cmd.extend([\"--model\", model])\n\n        # Remove CLAUDECODE env var to allow nesting claude -p inside a\n        # Claude Code session. The guard is for interactive terminal conflicts;\n        # programmatic subprocess usage is safe.\n        env = {k: v for k, v in os.environ.items() if k != \"CLAUDECODE\"}\n\n        process = subprocess.Popen(\n            cmd,\n            stdout=subprocess.PIPE,\n            stderr=subprocess.DEVNULL,\n            cwd=project_root,\n            env=env,\n        )\n\n        triggered = False\n        start_time = time.time()\n        buffer = \"\"\n        # Track state for stream event detection\n        pending_tool_name = None\n        accumulated_json = \"\"\n\n        try:\n            while time.time() - start_time < timeout:\n                if process.poll() is not None:\n                    remaining = process.stdout.read()\n                    if remaining:\n                        buffer += remaining.decode(\"utf-8\", errors=\"replace\")\n                    break\n\n                ready, _, _ = select.select([process.stdout], [], [], 1.0)\n                if not ready:\n                    continue\n\n                chunk = os.read(process.stdout.fileno(), 8192)\n                if not chunk:\n                    break\n                buffer += chunk.decode(\"utf-8\", errors=\"replace\")\n\n                while \"\\n\" in buffer:\n                    line, buffer = buffer.split(\"\\n\", 1)\n                    line = line.strip()\n                    if not line:\n                        continue\n\n                    try:\n                        event = json.loads(line)\n                    except json.JSONDecodeError:\n                        continue\n\n                    # Early detection via stream events\n                    if event.get(\"type\") == \"stream_event\":\n                        se = event.get(\"event\", {})\n                        se_type = se.get(\"type\", \"\")\n\n                        if se_type == \"content_block_start\":\n                            cb = se.get(\"content_block\", {})\n                            if cb.get(\"type\") == \"tool_use\":\n                                tool_name = cb.get(\"name\", \"\")\n                                if tool_name in (\"Skill\", \"Read\"):\n                                    pending_tool_name = tool_name\n                                    accumulated_json = \"\"\n                                else:\n                                    return False\n\n                        elif se_type == \"content_block_delta\" and pending_tool_name:\n                            delta = se.get(\"delta\", {})\n                            if delta.get(\"type\") == \"input_json_delta\":\n                                accumulated_json += delta.get(\"partial_json\", \"\")\n                                if clean_name in accumulated_json:\n                                    return True\n\n                        elif se_type in (\"content_block_stop\", \"message_stop\"):\n                            if pending_tool_name:\n                                return clean_name in accumulated_json\n                            if se_type == \"message_stop\":\n                                return False\n\n                    # Fallback: full assistant message\n                    elif event.get(\"type\") == \"assistant\":\n                        message = event.get(\"message\", {})\n                        for content_item in message.get(\"content\", []):\n                            if content_item.get(\"type\") != \"tool_use\":\n                                continue\n                            tool_name = content_item.get(\"name\", \"\")\n                            tool_input = content_item.get(\"input\", {})\n                            if tool_name == \"Skill\" and clean_name in tool_input.get(\"skill\", \"\"):\n                                triggered = True\n                            elif tool_name == \"Read\" and clean_name in tool_input.get(\"file_path\", \"\"):\n                                triggered = True\n                            return triggered\n\n                    elif event.get(\"type\") == \"result\":\n                        return triggered\n        finally:\n            # Clean up process on any exit path (return, exception, timeout)\n            if process.poll() is None:\n                process.kill()\n                process.wait()\n\n        return triggered\n    finally:\n        if command_file.exists():\n            command_file.unlink()\n\n\ndef run_eval(\n    eval_set: list[dict],\n    skill_name: str,\n    description: str,\n    num_workers: int,\n    timeout: int,\n    project_root: Path,\n    runs_per_query: int = 1,\n    trigger_threshold: float = 0.5,\n    model: str | None = None,\n) -> dict:\n    \"\"\"Run the full eval set and return results.\"\"\"\n    results = []\n\n    with ProcessPoolExecutor(max_workers=num_workers) as executor:\n        future_to_info = {}\n        for item in eval_set:\n            for run_idx in range(runs_per_query):\n                future = executor.submit(\n                    run_single_query,\n                    item[\"query\"],\n                    skill_name,\n                    description,\n                    timeout,\n                    str(project_root),\n                    model,\n                )\n                future_to_info[future] = (item, run_idx)\n\n        query_triggers: dict[str, list[bool]] = {}\n        query_items: dict[str, dict] = {}\n        for future in as_completed(future_to_info):\n            item, _ = future_to_info[future]\n            query = item[\"query\"]\n            query_items[query] = item\n            if query not in query_triggers:\n                query_triggers[query] = []\n            try:\n                query_triggers[query].append(future.result())\n            except Exception as e:\n                print(f\"Warning: query failed: {e}\", file=sys.stderr)\n                query_triggers[query].append(False)\n\n    for query, triggers in query_triggers.items():\n        item = query_items[query]\n        trigger_rate = sum(triggers) / len(triggers)\n        should_trigger = item[\"should_trigger\"]\n        if should_trigger:\n            did_pass = trigger_rate >= trigger_threshold\n        else:\n            did_pass = trigger_rate < trigger_threshold\n        results.append({\n            \"query\": query,\n            \"should_trigger\": should_trigger,\n            \"trigger_rate\": trigger_rate,\n            \"triggers\": sum(triggers),\n            \"runs\": len(triggers),\n            \"pass\": did_pass,\n        })\n\n    passed = sum(1 for r in results if r[\"pass\"])\n    total = len(results)\n\n    return {\n        \"skill_name\": skill_name,\n        \"description\": description,\n        \"results\": results,\n        \"summary\": {\n            \"total\": total,\n            \"passed\": passed,\n            \"failed\": total - passed,\n        },\n    }\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=\"Run trigger evaluation for a skill description\")\n    parser.add_argument(\"--eval-set\", required=True, help=\"Path to eval set JSON file\")\n    parser.add_argument(\"--skill-path\", required=True, help=\"Path to skill directory\")\n    parser.add_argument(\"--description\", default=None, help=\"Override description to test\")\n    parser.add_argument(\"--num-workers\", type=int, default=10, help=\"Number of parallel workers\")\n    parser.add_argument(\"--timeout\", type=int, default=30, help=\"Timeout per query in seconds\")\n    parser.add_argument(\"--runs-per-query\", type=int, default=3, help=\"Number of runs per query\")\n    parser.add_argument(\"--trigger-threshold\", type=float, default=0.5, help=\"Trigger rate threshold\")\n    parser.add_argument(\"--model\", default=None, help=\"Model to use for claude -p (default: user\'s configured model)\")\n    parser.add_argument(\"--verbose\", action=\"store_true\", help=\"Print progress to stderr\")\n    args = parser.parse_args()\n\n    eval_set = json.loads(Path(args.eval_set).read_text())\n    skill_path = Path(args.skill_path)\n\n    if not (skill_path / \"SKILL.md\").exists():\n        print(f\"Error: No SKILL.md found at {skill_path}\", file=sys.stderr)\n        sys.exit(1)\n\n    name, original_description, content = parse_skill_md(skill_path)\n    description = args.description or original_description\n    project_root = find_project_root()\n\n    if args.verbose:\n        print(f\"Evaluating: {description}\", file=sys.stderr)\n\n    output = run_eval(\n        eval_set=eval_set,\n        skill_name=name,\n        description=description,\n        num_workers=args.num_workers,\n        timeout=args.timeout,\n        project_root=project_root,\n        runs_per_query=args.runs_per_query,\n        trigger_threshold=args.trigger_threshold,\n        model=args.model,\n    )\n\n    if args.verbose:\n        summary = output[\"summary\"]\n        print(f\"Results: {summary[\'passed\']}/{summary[\'total\']} passed\", file=sys.stderr)\n        for r in output[\"results\"]:\n            status = \"PASS\" if r[\"pass\"] else \"FAIL\"\n            rate_str = f\"{r[\'triggers\']}/{r[\'runs\']}\"\n            print(f\"  [{status}] rate={rate_str} expected={r[\'should_trigger\']}: {r[\'query\'][:70]}\", file=sys.stderr)\n\n    print(json.dumps(output, indent=2))\n\n\nif __name__ == \"__main__\":\n    main()\n','75269360a221e48f79425605de5e5cb6','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(1221,'enc.736372697074732f72756e5f6576616c2e7079','skill_enc.736b696c6c2d63726561746f72__enc.302e302e31','#!/usr/bin/env python3\n\"\"\"Run trigger evaluation for a skill description.\n\nTests whether a skill\'s description causes Claude to trigger (read the skill)\nfor a set of queries. Outputs results as JSON.\n\"\"\"\n\nimport argparse\nimport json\nimport os\nimport select\nimport subprocess\nimport sys\nimport time\nimport uuid\nfrom concurrent.futures import ProcessPoolExecutor, as_completed\nfrom pathlib import Path\n\nfrom scripts.utils import parse_skill_md\n\n\ndef find_project_root() -> Path:\n    \"\"\"Find the project root by walking up from cwd looking for .claude/.\n\n    Mimics how Claude Code discovers its project root, so the command file\n    we create ends up where claude -p will look for it.\n    \"\"\"\n    current = Path.cwd()\n    for parent in [current, *current.parents]:\n        if (parent / \".claude\").is_dir():\n            return parent\n    return current\n\n\ndef run_single_query(\n    query: str,\n    skill_name: str,\n    skill_description: str,\n    timeout: int,\n    project_root: str,\n    model: str | None = None,\n) -> bool:\n    \"\"\"Run a single query and return whether the skill was triggered.\n\n    Creates a command file in .claude/commands/ so it appears in Claude\'s\n    available_skills list, then runs `claude -p` with the raw query.\n    Uses --include-partial-messages to detect triggering early from\n    stream events (content_block_start) rather than waiting for the\n    full assistant message, which only arrives after tool execution.\n    \"\"\"\n    unique_id = uuid.uuid4().hex[:8]\n    clean_name = f\"{skill_name}-skill-{unique_id}\"\n    project_commands_dir = Path(project_root) / \".claude\" / \"commands\"\n    command_file = project_commands_dir / f\"{clean_name}.md\"\n\n    try:\n        project_commands_dir.mkdir(parents=True, exist_ok=True)\n        # Use YAML block scalar to avoid breaking on quotes in description\n        indented_desc = \"\\n  \".join(skill_description.split(\"\\n\"))\n        command_content = (\n            f\"---\\n\"\n            f\"description: |\\n\"\n            f\"  {indented_desc}\\n\"\n            f\"---\\n\\n\"\n            f\"# {skill_name}\\n\\n\"\n            f\"This skill handles: {skill_description}\\n\"\n        )\n        command_file.write_text(command_content)\n\n        cmd = [\n            \"claude\",\n            \"-p\", query,\n            \"--output-format\", \"stream-json\",\n            \"--verbose\",\n            \"--include-partial-messages\",\n        ]\n        if model:\n            cmd.extend([\"--model\", model])\n\n        # Remove CLAUDECODE env var to allow nesting claude -p inside a\n        # Claude Code session. The guard is for interactive terminal conflicts;\n        # programmatic subprocess usage is safe.\n        env = {k: v for k, v in os.environ.items() if k != \"CLAUDECODE\"}\n\n        process = subprocess.Popen(\n            cmd,\n            stdout=subprocess.PIPE,\n            stderr=subprocess.DEVNULL,\n            cwd=project_root,\n            env=env,\n        )\n\n        triggered = False\n        start_time = time.time()\n        buffer = \"\"\n        # Track state for stream event detection\n        pending_tool_name = None\n        accumulated_json = \"\"\n\n        try:\n            while time.time() - start_time < timeout:\n                if process.poll() is not None:\n                    remaining = process.stdout.read()\n                    if remaining:\n                        buffer += remaining.decode(\"utf-8\", errors=\"replace\")\n                    break\n\n                ready, _, _ = select.select([process.stdout], [], [], 1.0)\n                if not ready:\n                    continue\n\n                chunk = os.read(process.stdout.fileno(), 8192)\n                if not chunk:\n                    break\n                buffer += chunk.decode(\"utf-8\", errors=\"replace\")\n\n                while \"\\n\" in buffer:\n                    line, buffer = buffer.split(\"\\n\", 1)\n                    line = line.strip()\n                    if not line:\n                        continue\n\n                    try:\n                        event = json.loads(line)\n                    except json.JSONDecodeError:\n                        continue\n\n                    # Early detection via stream events\n                    if event.get(\"type\") == \"stream_event\":\n                        se = event.get(\"event\", {})\n                        se_type = se.get(\"type\", \"\")\n\n                        if se_type == \"content_block_start\":\n                            cb = se.get(\"content_block\", {})\n                            if cb.get(\"type\") == \"tool_use\":\n                                tool_name = cb.get(\"name\", \"\")\n                                if tool_name in (\"Skill\", \"Read\"):\n                                    pending_tool_name = tool_name\n                                    accumulated_json = \"\"\n                                else:\n                                    return False\n\n                        elif se_type == \"content_block_delta\" and pending_tool_name:\n                            delta = se.get(\"delta\", {})\n                            if delta.get(\"type\") == \"input_json_delta\":\n                                accumulated_json += delta.get(\"partial_json\", \"\")\n                                if clean_name in accumulated_json:\n                                    return True\n\n                        elif se_type in (\"content_block_stop\", \"message_stop\"):\n                            if pending_tool_name:\n                                return clean_name in accumulated_json\n                            if se_type == \"message_stop\":\n                                return False\n\n                    # Fallback: full assistant message\n                    elif event.get(\"type\") == \"assistant\":\n                        message = event.get(\"message\", {})\n                        for content_item in message.get(\"content\", []):\n                            if content_item.get(\"type\") != \"tool_use\":\n                                continue\n                            tool_name = content_item.get(\"name\", \"\")\n                            tool_input = content_item.get(\"input\", {})\n                            if tool_name == \"Skill\" and clean_name in tool_input.get(\"skill\", \"\"):\n                                triggered = True\n                            elif tool_name == \"Read\" and clean_name in tool_input.get(\"file_path\", \"\"):\n                                triggered = True\n                            return triggered\n\n                    elif event.get(\"type\") == \"result\":\n                        return triggered\n        finally:\n            # Clean up process on any exit path (return, exception, timeout)\n            if process.poll() is None:\n                process.kill()\n                process.wait()\n\n        return triggered\n    finally:\n        if command_file.exists():\n            command_file.unlink()\n\n\ndef run_eval(\n    eval_set: list[dict],\n    skill_name: str,\n    description: str,\n    num_workers: int,\n    timeout: int,\n    project_root: Path,\n    runs_per_query: int = 1,\n    trigger_threshold: float = 0.5,\n    model: str | None = None,\n) -> dict:\n    \"\"\"Run the full eval set and return results.\"\"\"\n    results = []\n\n    with ProcessPoolExecutor(max_workers=num_workers) as executor:\n        future_to_info = {}\n        for item in eval_set:\n            for run_idx in range(runs_per_query):\n                future = executor.submit(\n                    run_single_query,\n                    item[\"query\"],\n                    skill_name,\n                    description,\n                    timeout,\n                    str(project_root),\n                    model,\n                )\n                future_to_info[future] = (item, run_idx)\n\n        query_triggers: dict[str, list[bool]] = {}\n        query_items: dict[str, dict] = {}\n        for future in as_completed(future_to_info):\n            item, _ = future_to_info[future]\n            query = item[\"query\"]\n            query_items[query] = item\n            if query not in query_triggers:\n                query_triggers[query] = []\n            try:\n                query_triggers[query].append(future.result())\n            except Exception as e:\n                print(f\"Warning: query failed: {e}\", file=sys.stderr)\n                query_triggers[query].append(False)\n\n    for query, triggers in query_triggers.items():\n        item = query_items[query]\n        trigger_rate = sum(triggers) / len(triggers)\n        should_trigger = item[\"should_trigger\"]\n        if should_trigger:\n            did_pass = trigger_rate >= trigger_threshold\n        else:\n            did_pass = trigger_rate < trigger_threshold\n        results.append({\n            \"query\": query,\n            \"should_trigger\": should_trigger,\n            \"trigger_rate\": trigger_rate,\n            \"triggers\": sum(triggers),\n            \"runs\": len(triggers),\n            \"pass\": did_pass,\n        })\n\n    passed = sum(1 for r in results if r[\"pass\"])\n    total = len(results)\n\n    return {\n        \"skill_name\": skill_name,\n        \"description\": description,\n        \"results\": results,\n        \"summary\": {\n            \"total\": total,\n            \"passed\": passed,\n            \"failed\": total - passed,\n        },\n    }\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=\"Run trigger evaluation for a skill description\")\n    parser.add_argument(\"--eval-set\", required=True, help=\"Path to eval set JSON file\")\n    parser.add_argument(\"--skill-path\", required=True, help=\"Path to skill directory\")\n    parser.add_argument(\"--description\", default=None, help=\"Override description to test\")\n    parser.add_argument(\"--num-workers\", type=int, default=10, help=\"Number of parallel workers\")\n    parser.add_argument(\"--timeout\", type=int, default=30, help=\"Timeout per query in seconds\")\n    parser.add_argument(\"--runs-per-query\", type=int, default=3, help=\"Number of runs per query\")\n    parser.add_argument(\"--trigger-threshold\", type=float, default=0.5, help=\"Trigger rate threshold\")\n    parser.add_argument(\"--model\", default=None, help=\"Model to use for claude -p (default: user\'s configured model)\")\n    parser.add_argument(\"--verbose\", action=\"store_true\", help=\"Print progress to stderr\")\n    args = parser.parse_args()\n\n    eval_set = json.loads(Path(args.eval_set).read_text())\n    skill_path = Path(args.skill_path)\n\n    if not (skill_path / \"SKILL.md\").exists():\n        print(f\"Error: No SKILL.md found at {skill_path}\", file=sys.stderr)\n        sys.exit(1)\n\n    name, original_description, content = parse_skill_md(skill_path)\n    description = args.description or original_description\n    project_root = find_project_root()\n\n    if args.verbose:\n        print(f\"Evaluating: {description}\", file=sys.stderr)\n\n    output = run_eval(\n        eval_set=eval_set,\n        skill_name=name,\n        description=description,\n        num_workers=args.num_workers,\n        timeout=args.timeout,\n        project_root=project_root,\n        runs_per_query=args.runs_per_query,\n        trigger_threshold=args.trigger_threshold,\n        model=args.model,\n    )\n\n    if args.verbose:\n        summary = output[\"summary\"]\n        print(f\"Results: {summary[\'passed\']}/{summary[\'total\']} passed\", file=sys.stderr)\n        for r in output[\"results\"]:\n            status = \"PASS\" if r[\"pass\"] else \"FAIL\"\n            rate_str = f\"{r[\'triggers\']}/{r[\'runs\']}\"\n            print(f\"  [{status}] rate={rate_str} expected={r[\'should_trigger\']}: {r[\'query\'][:70]}\", file=sys.stderr)\n\n    print(json.dumps(output, indent=2))\n\n\nif __name__ == \"__main__\":\n    main()\n','75269360a221e48f79425605de5e5cb6','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(1222,'enc.736372697074732f696d70726f76655f6465736372697074696f6e2e7079','skill_enc.736b696c6c2d63726561746f72__enc.302e302e31','#!/usr/bin/env python3\n\"\"\"Improve a skill description based on eval results.\n\nTakes eval results (from run_eval.py) and generates an improved description\nby calling `claude -p` as a subprocess (same auth pattern as run_eval.py —\nuses the session\'s Claude Code auth, no separate ANTHROPIC_API_KEY needed).\n\"\"\"\n\nimport argparse\nimport json\nimport os\nimport re\nimport subprocess\nimport sys\nfrom pathlib import Path\n\nfrom scripts.utils import parse_skill_md\n\n\ndef _call_claude(prompt: str, model: str | None, timeout: int = 300) -> str:\n    \"\"\"Run `claude -p` with the prompt on stdin and return the text response.\n\n    Prompt goes over stdin (not argv) because it embeds the full SKILL.md\n    body and can easily exceed comfortable argv length.\n    \"\"\"\n    cmd = [\"claude\", \"-p\", \"--output-format\", \"text\"]\n    if model:\n        cmd.extend([\"--model\", model])\n\n    # Remove CLAUDECODE env var to allow nesting claude -p inside a\n    # Claude Code session. The guard is for interactive terminal conflicts;\n    # programmatic subprocess usage is safe. Same pattern as run_eval.py.\n    env = {k: v for k, v in os.environ.items() if k != \"CLAUDECODE\"}\n\n    result = subprocess.run(\n        cmd,\n        input=prompt,\n        capture_output=True,\n        text=True,\n        env=env,\n        timeout=timeout,\n    )\n    if result.returncode != 0:\n        raise RuntimeError(\n            f\"claude -p exited {result.returncode}\\nstderr: {result.stderr}\"\n        )\n    return result.stdout\n\n\ndef improve_description(\n    skill_name: str,\n    skill_content: str,\n    current_description: str,\n    eval_results: dict,\n    history: list[dict],\n    model: str,\n    test_results: dict | None = None,\n    log_dir: Path | None = None,\n    iteration: int | None = None,\n) -> str:\n    \"\"\"Call Claude to improve the description based on eval results.\"\"\"\n    failed_triggers = [\n        r for r in eval_results[\"results\"]\n        if r[\"should_trigger\"] and not r[\"pass\"]\n    ]\n    false_triggers = [\n        r for r in eval_results[\"results\"]\n        if not r[\"should_trigger\"] and not r[\"pass\"]\n    ]\n\n    # Build scores summary\n    train_score = f\"{eval_results[\'summary\'][\'passed\']}/{eval_results[\'summary\'][\'total\']}\"\n    if test_results:\n        test_score = f\"{test_results[\'summary\'][\'passed\']}/{test_results[\'summary\'][\'total\']}\"\n        scores_summary = f\"Train: {train_score}, Test: {test_score}\"\n    else:\n        scores_summary = f\"Train: {train_score}\"\n\n    prompt = f\"\"\"You are optimizing a skill description for a Claude Code skill called \"{skill_name}\". A \"skill\" is sort of like a prompt, but with progressive disclosure -- there\'s a title and description that Claude sees when deciding whether to use the skill, and then if it does use the skill, it reads the .md file which has lots more details and potentially links to other resources in the skill folder like helper files and scripts and additional documentation or examples.\n\nThe description appears in Claude\'s \"available_skills\" list. When a user sends a query, Claude decides whether to invoke the skill based solely on the title and on this description. Your goal is to write a description that triggers for relevant queries, and doesn\'t trigger for irrelevant ones.\n\nHere\'s the current description:\n<current_description>\n\"{current_description}\"\n</current_description>\n\nCurrent scores ({scores_summary}):\n<scores_summary>\n\"\"\"\n    if failed_triggers:\n        prompt += \"FAILED TO TRIGGER (should have triggered but didn\'t):\\n\"\n        for r in failed_triggers:\n            prompt += f\'  - \"{r[\"query\"]}\" (triggered {r[\"triggers\"]}/{r[\"runs\"]} times)\\n\'\n        prompt += \"\\n\"\n\n    if false_triggers:\n        prompt += \"FALSE TRIGGERS (triggered but shouldn\'t have):\\n\"\n        for r in false_triggers:\n            prompt += f\'  - \"{r[\"query\"]}\" (triggered {r[\"triggers\"]}/{r[\"runs\"]} times)\\n\'\n        prompt += \"\\n\"\n\n    if history:\n        prompt += \"PREVIOUS ATTEMPTS (do NOT repeat these — try something structurally different):\\n\\n\"\n        for h in history:\n            train_s = f\"{h.get(\'train_passed\', h.get(\'passed\', 0))}/{h.get(\'train_total\', h.get(\'total\', 0))}\"\n            test_s = f\"{h.get(\'test_passed\', \'?\')}/{h.get(\'test_total\', \'?\')}\" if h.get(\'test_passed\') is not None else None\n            score_str = f\"train={train_s}\" + (f\", test={test_s}\" if test_s else \"\")\n            prompt += f\'<attempt {score_str}>\\n\'\n            prompt += f\'Description: \"{h[\"description\"]}\"\\n\'\n            if \"results\" in h:\n                prompt += \"Train results:\\n\"\n                for r in h[\"results\"]:\n                    status = \"PASS\" if r[\"pass\"] else \"FAIL\"\n                    prompt += f\'  [{status}] \"{r[\"query\"][:80]}\" (triggered {r[\"triggers\"]}/{r[\"runs\"]})\\n\'\n            if h.get(\"note\"):\n                prompt += f\'Note: {h[\"note\"]}\\n\'\n            prompt += \"</attempt>\\n\\n\"\n\n    prompt += f\"\"\"</scores_summary>\n\nSkill content (for context on what the skill does):\n<skill_content>\n{skill_content}\n</skill_content>\n\nBased on the failures, write a new and improved description that is more likely to trigger correctly. When I say \"based on the failures\", it\'s a bit of a tricky line to walk because we don\'t want to overfit to the specific cases you\'re seeing. So what I DON\'T want you to do is produce an ever-expanding list of specific queries that this skill should or shouldn\'t trigger for. Instead, try to generalize from the failures to broader categories of user intent and situations where this skill would be useful or not useful. The reason for this is twofold:\n\n1. Avoid overfitting\n2. The list might get loooong and it\'s injected into ALL queries and there might be a lot of skills, so we don\'t want to blow too much space on any given description.\n\nConcretely, your description should not be more than about 100-200 words, even if that comes at the cost of accuracy. There is a hard limit of 1024 characters — descriptions over that will be truncated, so stay comfortably under it.\n\nHere are some tips that we\'ve found to work well in writing these descriptions:\n- The skill should be phrased in the imperative -- \"Use this skill for\" rather than \"this skill does\"\n- The skill description should focus on the user\'s intent, what they are trying to achieve, vs. the implementation details of how the skill works.\n- The description competes with other skills for Claude\'s attention — make it distinctive and immediately recognizable.\n- If you\'re getting lots of failures after repeated attempts, change things up. Try different sentence structures or wordings.\n\nI\'d encourage you to be creative and mix up the style in different iterations since you\'ll have multiple opportunities to try different approaches and we\'ll just grab the highest-scoring one at the end. \n\nPlease respond with only the new description text in <new_description> tags, nothing else.\"\"\"\n\n    text = _call_claude(prompt, model)\n\n    match = re.search(r\"<new_description>(.*?)</new_description>\", text, re.DOTALL)\n    description = match.group(1).strip().strip(\'\"\') if match else text.strip().strip(\'\"\')\n\n    transcript: dict = {\n        \"iteration\": iteration,\n        \"prompt\": prompt,\n        \"response\": text,\n        \"parsed_description\": description,\n        \"char_count\": len(description),\n        \"over_limit\": len(description) > 1024,\n    }\n\n    # Safety net: the prompt already states the 1024-char hard limit, but if\n    # the model blew past it anyway, make one fresh single-turn call that\n    # quotes the too-long version and asks for a shorter rewrite. (The old\n    # SDK path did this as a true multi-turn; `claude -p` is one-shot, so we\n    # inline the prior output into the new prompt instead.)\n    if len(description) > 1024:\n        shorten_prompt = (\n            f\"{prompt}\\n\\n\"\n            f\"---\\n\\n\"\n            f\"A previous attempt produced this description, which at \"\n            f\"{len(description)} characters is over the 1024-character hard limit:\\n\\n\"\n            f\'\"{description}\"\\n\\n\'\n            f\"Rewrite it to be under 1024 characters while keeping the most \"\n            f\"important trigger words and intent coverage. Respond with only \"\n            f\"the new description in <new_description> tags.\"\n        )\n        shorten_text = _call_claude(shorten_prompt, model)\n        match = re.search(r\"<new_description>(.*?)</new_description>\", shorten_text, re.DOTALL)\n        shortened = match.group(1).strip().strip(\'\"\') if match else shorten_text.strip().strip(\'\"\')\n\n        transcript[\"rewrite_prompt\"] = shorten_prompt\n        transcript[\"rewrite_response\"] = shorten_text\n        transcript[\"rewrite_description\"] = shortened\n        transcript[\"rewrite_char_count\"] = len(shortened)\n        description = shortened\n\n    transcript[\"final_description\"] = description\n\n    if log_dir:\n        log_dir.mkdir(parents=True, exist_ok=True)\n        log_file = log_dir / f\"improve_iter_{iteration or \'unknown\'}.json\"\n        log_file.write_text(json.dumps(transcript, indent=2))\n\n    return description\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=\"Improve a skill description based on eval results\")\n    parser.add_argument(\"--eval-results\", required=True, help=\"Path to eval results JSON (from run_eval.py)\")\n    parser.add_argument(\"--skill-path\", required=True, help=\"Path to skill directory\")\n    parser.add_argument(\"--history\", default=None, help=\"Path to history JSON (previous attempts)\")\n    parser.add_argument(\"--model\", required=True, help=\"Model for improvement\")\n    parser.add_argument(\"--verbose\", action=\"store_true\", help=\"Print thinking to stderr\")\n    args = parser.parse_args()\n\n    skill_path = Path(args.skill_path)\n    if not (skill_path / \"SKILL.md\").exists():\n        print(f\"Error: No SKILL.md found at {skill_path}\", file=sys.stderr)\n        sys.exit(1)\n\n    eval_results = json.loads(Path(args.eval_results).read_text())\n    history = []\n    if args.history:\n        history = json.loads(Path(args.history).read_text())\n\n    name, _, content = parse_skill_md(skill_path)\n    current_description = eval_results[\"description\"]\n\n    if args.verbose:\n        print(f\"Current: {current_description}\", file=sys.stderr)\n        print(f\"Score: {eval_results[\'summary\'][\'passed\']}/{eval_results[\'summary\'][\'total\']}\", file=sys.stderr)\n\n    new_description = improve_description(\n        skill_name=name,\n        skill_content=content,\n        current_description=current_description,\n        eval_results=eval_results,\n        history=history,\n        model=args.model,\n    )\n\n    if args.verbose:\n        print(f\"Improved: {new_description}\", file=sys.stderr)\n\n    # Output as JSON with both the new description and updated history\n    output = {\n        \"description\": new_description,\n        \"history\": history + [{\n            \"description\": current_description,\n            \"passed\": eval_results[\"summary\"][\"passed\"],\n            \"failed\": eval_results[\"summary\"][\"failed\"],\n            \"total\": eval_results[\"summary\"][\"total\"],\n            \"results\": eval_results[\"results\"],\n        }],\n    }\n    print(json.dumps(output, indent=2))\n\n\nif __name__ == \"__main__\":\n    main()\n','b20bbcc3d69bc299b541c8b62c25cefe','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(1223,'enc.736372697074732f72756e5f6c6f6f702e7079','skill_enc.736b696c6c2d63726561746f72__enc.302e302e31','#!/usr/bin/env python3\n\"\"\"Run the eval + improve loop until all pass or max iterations reached.\n\nCombines run_eval.py and improve_description.py in a loop, tracking history\nand returning the best description found. Supports train/test split to prevent\noverfitting.\n\"\"\"\n\nimport argparse\nimport json\nimport random\nimport sys\nimport tempfile\nimport time\nimport webbrowser\nfrom pathlib import Path\n\nfrom scripts.generate_report import generate_html\nfrom scripts.improve_description import improve_description\nfrom scripts.run_eval import find_project_root, run_eval\nfrom scripts.utils import parse_skill_md\n\n\ndef split_eval_set(eval_set: list[dict], holdout: float, seed: int = 42) -> tuple[list[dict], list[dict]]:\n    \"\"\"Split eval set into train and test sets, stratified by should_trigger.\"\"\"\n    random.seed(seed)\n\n    # Separate by should_trigger\n    trigger = [e for e in eval_set if e[\"should_trigger\"]]\n    no_trigger = [e for e in eval_set if not e[\"should_trigger\"]]\n\n    # Shuffle each group\n    random.shuffle(trigger)\n    random.shuffle(no_trigger)\n\n    # Calculate split points\n    n_trigger_test = max(1, int(len(trigger) * holdout))\n    n_no_trigger_test = max(1, int(len(no_trigger) * holdout))\n\n    # Split\n    test_set = trigger[:n_trigger_test] + no_trigger[:n_no_trigger_test]\n    train_set = trigger[n_trigger_test:] + no_trigger[n_no_trigger_test:]\n\n    return train_set, test_set\n\n\ndef run_loop(\n    eval_set: list[dict],\n    skill_path: Path,\n    description_override: str | None,\n    num_workers: int,\n    timeout: int,\n    max_iterations: int,\n    runs_per_query: int,\n    trigger_threshold: float,\n    holdout: float,\n    model: str,\n    verbose: bool,\n    live_report_path: Path | None = None,\n    log_dir: Path | None = None,\n) -> dict:\n    \"\"\"Run the eval + improvement loop.\"\"\"\n    project_root = find_project_root()\n    name, original_description, content = parse_skill_md(skill_path)\n    current_description = description_override or original_description\n\n    # Split into train/test if holdout > 0\n    if holdout > 0:\n        train_set, test_set = split_eval_set(eval_set, holdout)\n        if verbose:\n            print(f\"Split: {len(train_set)} train, {len(test_set)} test (holdout={holdout})\", file=sys.stderr)\n    else:\n        train_set = eval_set\n        test_set = []\n\n    history = []\n    exit_reason = \"unknown\"\n\n    for iteration in range(1, max_iterations + 1):\n        if verbose:\n            print(f\"\\n{\'=\'*60}\", file=sys.stderr)\n            print(f\"Iteration {iteration}/{max_iterations}\", file=sys.stderr)\n            print(f\"Description: {current_description}\", file=sys.stderr)\n            print(f\"{\'=\'*60}\", file=sys.stderr)\n\n        # Evaluate train + test together in one batch for parallelism\n        all_queries = train_set + test_set\n        t0 = time.time()\n        all_results = run_eval(\n            eval_set=all_queries,\n            skill_name=name,\n            description=current_description,\n            num_workers=num_workers,\n            timeout=timeout,\n            project_root=project_root,\n            runs_per_query=runs_per_query,\n            trigger_threshold=trigger_threshold,\n            model=model,\n        )\n        eval_elapsed = time.time() - t0\n\n        # Split results back into train/test by matching queries\n        train_queries_set = {q[\"query\"] for q in train_set}\n        train_result_list = [r for r in all_results[\"results\"] if r[\"query\"] in train_queries_set]\n        test_result_list = [r for r in all_results[\"results\"] if r[\"query\"] not in train_queries_set]\n\n        train_passed = sum(1 for r in train_result_list if r[\"pass\"])\n        train_total = len(train_result_list)\n        train_summary = {\"passed\": train_passed, \"failed\": train_total - train_passed, \"total\": train_total}\n        train_results = {\"results\": train_result_list, \"summary\": train_summary}\n\n        if test_set:\n            test_passed = sum(1 for r in test_result_list if r[\"pass\"])\n            test_total = len(test_result_list)\n            test_summary = {\"passed\": test_passed, \"failed\": test_total - test_passed, \"total\": test_total}\n            test_results = {\"results\": test_result_list, \"summary\": test_summary}\n        else:\n            test_results = None\n            test_summary = None\n\n        history.append({\n            \"iteration\": iteration,\n            \"description\": current_description,\n            \"train_passed\": train_summary[\"passed\"],\n            \"train_failed\": train_summary[\"failed\"],\n            \"train_total\": train_summary[\"total\"],\n            \"train_results\": train_results[\"results\"],\n            \"test_passed\": test_summary[\"passed\"] if test_summary else None,\n            \"test_failed\": test_summary[\"failed\"] if test_summary else None,\n            \"test_total\": test_summary[\"total\"] if test_summary else None,\n            \"test_results\": test_results[\"results\"] if test_results else None,\n            # For backward compat with report generator\n            \"passed\": train_summary[\"passed\"],\n            \"failed\": train_summary[\"failed\"],\n            \"total\": train_summary[\"total\"],\n            \"results\": train_results[\"results\"],\n        })\n\n        # Write live report if path provided\n        if live_report_path:\n            partial_output = {\n                \"original_description\": original_description,\n                \"best_description\": current_description,\n                \"best_score\": \"in progress\",\n                \"iterations_run\": len(history),\n                \"holdout\": holdout,\n                \"train_size\": len(train_set),\n                \"test_size\": len(test_set),\n                \"history\": history,\n            }\n            live_report_path.write_text(generate_html(partial_output, auto_refresh=True, skill_name=name))\n\n        if verbose:\n            def print_eval_stats(label, results, elapsed):\n                pos = [r for r in results if r[\"should_trigger\"]]\n                neg = [r for r in results if not r[\"should_trigger\"]]\n                tp = sum(r[\"triggers\"] for r in pos)\n                pos_runs = sum(r[\"runs\"] for r in pos)\n                fn = pos_runs - tp\n                fp = sum(r[\"triggers\"] for r in neg)\n                neg_runs = sum(r[\"runs\"] for r in neg)\n                tn = neg_runs - fp\n                total = tp + tn + fp + fn\n                precision = tp / (tp + fp) if (tp + fp) > 0 else 1.0\n                recall = tp / (tp + fn) if (tp + fn) > 0 else 1.0\n                accuracy = (tp + tn) / total if total > 0 else 0.0\n                print(f\"{label}: {tp+tn}/{total} correct, precision={precision:.0%} recall={recall:.0%} accuracy={accuracy:.0%} ({elapsed:.1f}s)\", file=sys.stderr)\n                for r in results:\n                    status = \"PASS\" if r[\"pass\"] else \"FAIL\"\n                    rate_str = f\"{r[\'triggers\']}/{r[\'runs\']}\"\n                    print(f\"  [{status}] rate={rate_str} expected={r[\'should_trigger\']}: {r[\'query\'][:60]}\", file=sys.stderr)\n\n            print_eval_stats(\"Train\", train_results[\"results\"], eval_elapsed)\n            if test_summary:\n                print_eval_stats(\"Test \", test_results[\"results\"], 0)\n\n        if train_summary[\"failed\"] == 0:\n            exit_reason = f\"all_passed (iteration {iteration})\"\n            if verbose:\n                print(f\"\\nAll train queries passed on iteration {iteration}!\", file=sys.stderr)\n            break\n\n        if iteration == max_iterations:\n            exit_reason = f\"max_iterations ({max_iterations})\"\n            if verbose:\n                print(f\"\\nMax iterations reached ({max_iterations}).\", file=sys.stderr)\n            break\n\n        # Improve the description based on train results\n        if verbose:\n            print(f\"\\nImproving description...\", file=sys.stderr)\n\n        t0 = time.time()\n        # Strip test scores from history so improvement model can\'t see them\n        blinded_history = [\n            {k: v for k, v in h.items() if not k.startswith(\"test_\")}\n            for h in history\n        ]\n        new_description = improve_description(\n            skill_name=name,\n            skill_content=content,\n            current_description=current_description,\n            eval_results=train_results,\n            history=blinded_history,\n            model=model,\n            log_dir=log_dir,\n            iteration=iteration,\n        )\n        improve_elapsed = time.time() - t0\n\n        if verbose:\n            print(f\"Proposed ({improve_elapsed:.1f}s): {new_description}\", file=sys.stderr)\n\n        current_description = new_description\n\n    # Find the best iteration by TEST score (or train if no test set)\n    if test_set:\n        best = max(history, key=lambda h: h[\"test_passed\"] or 0)\n        best_score = f\"{best[\'test_passed\']}/{best[\'test_total\']}\"\n    else:\n        best = max(history, key=lambda h: h[\"train_passed\"])\n        best_score = f\"{best[\'train_passed\']}/{best[\'train_total\']}\"\n\n    if verbose:\n        print(f\"\\nExit reason: {exit_reason}\", file=sys.stderr)\n        print(f\"Best score: {best_score} (iteration {best[\'iteration\']})\", file=sys.stderr)\n\n    return {\n        \"exit_reason\": exit_reason,\n        \"original_description\": original_description,\n        \"best_description\": best[\"description\"],\n        \"best_score\": best_score,\n        \"best_train_score\": f\"{best[\'train_passed\']}/{best[\'train_total\']}\",\n        \"best_test_score\": f\"{best[\'test_passed\']}/{best[\'test_total\']}\" if test_set else None,\n        \"final_description\": current_description,\n        \"iterations_run\": len(history),\n        \"holdout\": holdout,\n        \"train_size\": len(train_set),\n        \"test_size\": len(test_set),\n        \"history\": history,\n    }\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=\"Run eval + improve loop\")\n    parser.add_argument(\"--eval-set\", required=True, help=\"Path to eval set JSON file\")\n    parser.add_argument(\"--skill-path\", required=True, help=\"Path to skill directory\")\n    parser.add_argument(\"--description\", default=None, help=\"Override starting description\")\n    parser.add_argument(\"--num-workers\", type=int, default=10, help=\"Number of parallel workers\")\n    parser.add_argument(\"--timeout\", type=int, default=30, help=\"Timeout per query in seconds\")\n    parser.add_argument(\"--max-iterations\", type=int, default=5, help=\"Max improvement iterations\")\n    parser.add_argument(\"--runs-per-query\", type=int, default=3, help=\"Number of runs per query\")\n    parser.add_argument(\"--trigger-threshold\", type=float, default=0.5, help=\"Trigger rate threshold\")\n    parser.add_argument(\"--holdout\", type=float, default=0.4, help=\"Fraction of eval set to hold out for testing (0 to disable)\")\n    parser.add_argument(\"--model\", required=True, help=\"Model for improvement\")\n    parser.add_argument(\"--verbose\", action=\"store_true\", help=\"Print progress to stderr\")\n    parser.add_argument(\"--report\", default=\"auto\", help=\"Generate HTML report at this path (default: \'auto\' for temp file, \'none\' to disable)\")\n    parser.add_argument(\"--results-dir\", default=None, help=\"Save all outputs (results.json, report.html, log.txt) to a timestamped subdirectory here\")\n    args = parser.parse_args()\n\n    eval_set = json.loads(Path(args.eval_set).read_text())\n    skill_path = Path(args.skill_path)\n\n    if not (skill_path / \"SKILL.md\").exists():\n        print(f\"Error: No SKILL.md found at {skill_path}\", file=sys.stderr)\n        sys.exit(1)\n\n    name, _, _ = parse_skill_md(skill_path)\n\n    # Set up live report path\n    if args.report != \"none\":\n        if args.report == \"auto\":\n            timestamp = time.strftime(\"%Y%m%d_%H%M%S\")\n            live_report_path = Path(tempfile.gettempdir()) / f\"skill_description_report_{skill_path.name}_{timestamp}.html\"\n        else:\n            live_report_path = Path(args.report)\n        # Open the report immediately so the user can watch\n        live_report_path.write_text(\"<html><body><h1>Starting optimization loop...</h1><meta http-equiv=\'refresh\' content=\'5\'></body></html>\")\n        webbrowser.open(str(live_report_path))\n    else:\n        live_report_path = None\n\n    # Determine output directory (create before run_loop so logs can be written)\n    if args.results_dir:\n        timestamp = time.strftime(\"%Y-%m-%d_%H%M%S\")\n        results_dir = Path(args.results_dir) / timestamp\n        results_dir.mkdir(parents=True, exist_ok=True)\n    else:\n        results_dir = None\n\n    log_dir = results_dir / \"logs\" if results_dir else None\n\n    output = run_loop(\n        eval_set=eval_set,\n        skill_path=skill_path,\n        description_override=args.description,\n        num_workers=args.num_workers,\n        timeout=args.timeout,\n        max_iterations=args.max_iterations,\n        runs_per_query=args.runs_per_query,\n        trigger_threshold=args.trigger_threshold,\n        holdout=args.holdout,\n        model=args.model,\n        verbose=args.verbose,\n        live_report_path=live_report_path,\n        log_dir=log_dir,\n    )\n\n    # Save JSON output\n    json_output = json.dumps(output, indent=2)\n    print(json_output)\n    if results_dir:\n        (results_dir / \"results.json\").write_text(json_output)\n\n    # Write final HTML report (without auto-refresh)\n    if live_report_path:\n        live_report_path.write_text(generate_html(output, auto_refresh=False, skill_name=name))\n        print(f\"\\nReport: {live_report_path}\", file=sys.stderr)\n\n    if results_dir and live_report_path:\n        (results_dir / \"report.html\").write_text(generate_html(output, auto_refresh=False, skill_name=name))\n\n    if results_dir:\n        print(f\"Results saved to: {results_dir}\", file=sys.stderr)\n\n\nif __name__ == \"__main__\":\n    main()\n','c3365f6c1927bf535f463f841c32ae81','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(1224,'enc.6576616c2d7669657765722f7669657765722e68746d6c','skill_enc.736b696c6c2d63726561746f72__enc.302e302e31','<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Eval Review</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@500;600&family=Lora:wght@400;500&display=swap\" rel=\"stylesheet\">\n  <script src=\"https://cdn.sheetjs.com/xlsx-0.20.3/package/dist/xlsx.full.min.js\" integrity=\"sha384-EnyY0/GSHQGSxSgMwaIPzSESbqoOLSexfnSMN2AP+39Ckmn92stwABZynq1JyzdT\" crossorigin=\"anonymous\"></script>\n  <style>\n    :root {\n      --bg: #faf9f5;\n      --surface: #ffffff;\n      --border: #e8e6dc;\n      --text: #141413;\n      --text-muted: #b0aea5;\n      --accent: #d97757;\n      --accent-hover: #c4613f;\n      --green: #788c5d;\n      --green-bg: #eef2e8;\n      --red: #c44;\n      --red-bg: #fceaea;\n      --header-bg: #141413;\n      --header-text: #faf9f5;\n      --radius: 6px;\n    }\n\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n\n    body {\n      font-family: \'Lora\', Georgia, serif;\n      background: var(--bg);\n      color: var(--text);\n      height: 100vh;\n      display: flex;\n      flex-direction: column;\n    }\n\n    /* ---- Header ---- */\n    .header {\n      background: var(--header-bg);\n      color: var(--header-text);\n      padding: 1rem 2rem;\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      flex-shrink: 0;\n    }\n    .header h1 {\n      font-family: \'Poppins\', sans-serif;\n      font-size: 1.25rem;\n      font-weight: 600;\n    }\n    .header .instructions {\n      font-size: 0.8rem;\n      opacity: 0.7;\n      margin-top: 0.25rem;\n    }\n    .header .progress {\n      font-size: 0.875rem;\n      opacity: 0.8;\n      text-align: right;\n    }\n\n    /* ---- Main content ---- */\n    .main {\n      flex: 1;\n      overflow-y: auto;\n      padding: 1.5rem 2rem;\n      display: flex;\n      flex-direction: column;\n      gap: 1.25rem;\n    }\n\n    /* ---- Sections ---- */\n    .section {\n      background: var(--surface);\n      border: 1px solid var(--border);\n      border-radius: var(--radius);\n      flex-shrink: 0;\n    }\n    .section-header {\n      font-family: \'Poppins\', sans-serif;\n      padding: 0.75rem 1rem;\n      font-size: 0.75rem;\n      font-weight: 500;\n      text-transform: uppercase;\n      letter-spacing: 0.05em;\n      color: var(--text-muted);\n      border-bottom: 1px solid var(--border);\n      background: var(--bg);\n    }\n    .section-body {\n      padding: 1rem;\n    }\n\n    /* ---- Config badge ---- */\n    .config-badge {\n      display: inline-block;\n      padding: 0.2rem 0.625rem;\n      border-radius: 9999px;\n      font-family: \'Poppins\', sans-serif;\n      font-size: 0.6875rem;\n      font-weight: 600;\n      text-transform: uppercase;\n      letter-spacing: 0.03em;\n      margin-left: 0.75rem;\n      vertical-align: middle;\n    }\n    .config-badge.config-primary {\n      background: rgba(33, 150, 243, 0.12);\n      color: #1976d2;\n    }\n    .config-badge.config-baseline {\n      background: rgba(255, 193, 7, 0.15);\n      color: #f57f17;\n    }\n\n    /* ---- Prompt ---- */\n    .prompt-text {\n      white-space: pre-wrap;\n      font-size: 0.9375rem;\n      line-height: 1.6;\n    }\n\n    /* ---- Outputs ---- */\n    .output-file {\n      border: 1px solid var(--border);\n      border-radius: var(--radius);\n      overflow: hidden;\n    }\n    .output-file + .output-file {\n      margin-top: 1rem;\n    }\n    .output-file-header {\n      padding: 0.5rem 0.75rem;\n      font-size: 0.8rem;\n      font-weight: 600;\n      color: var(--text-muted);\n      background: var(--bg);\n      border-bottom: 1px solid var(--border);\n      font-family: \'SF Mono\', SFMono-Regular, Consolas, \'Liberation Mono\', Menlo, monospace;\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n    }\n    .output-file-header .dl-btn {\n      font-size: 0.7rem;\n      color: var(--accent);\n      text-decoration: none;\n      cursor: pointer;\n      font-family: -apple-system, BlinkMacSystemFont, \'Segoe UI\', sans-serif;\n      font-weight: 500;\n      opacity: 0.8;\n    }\n    .output-file-header .dl-btn:hover {\n      opacity: 1;\n      text-decoration: underline;\n    }\n    .output-file-content {\n      padding: 0.75rem;\n      overflow-x: auto;\n    }\n    .output-file-content pre {\n      font-size: 0.8125rem;\n      line-height: 1.5;\n      white-space: pre-wrap;\n      word-break: break-word;\n      font-family: \'SF Mono\', SFMono-Regular, Consolas, \'Liberation Mono\', Menlo, monospace;\n    }\n    .output-file-content img {\n      max-width: 100%;\n      height: auto;\n      border-radius: 4px;\n    }\n    .output-file-content iframe {\n      width: 100%;\n      height: 600px;\n      border: none;\n    }\n    .output-file-content table {\n      border-collapse: collapse;\n      font-size: 0.8125rem;\n      width: 100%;\n    }\n    .output-file-content table td,\n    .output-file-content table th {\n      border: 1px solid var(--border);\n      padding: 0.375rem 0.5rem;\n      text-align: left;\n    }\n    .output-file-content table th {\n      background: var(--bg);\n      font-weight: 600;\n    }\n    .output-file-content .download-link {\n      display: inline-flex;\n      align-items: center;\n      gap: 0.5rem;\n      padding: 0.5rem 1rem;\n      background: var(--bg);\n      border: 1px solid var(--border);\n      border-radius: 4px;\n      color: var(--accent);\n      text-decoration: none;\n      font-size: 0.875rem;\n      cursor: pointer;\n    }\n    .output-file-content .download-link:hover {\n      background: var(--border);\n    }\n    .empty-state {\n      color: var(--text-muted);\n      font-style: italic;\n      padding: 2rem;\n      text-align: center;\n    }\n\n    /* ---- Feedback ---- */\n    .prev-feedback {\n      background: var(--bg);\n      border: 1px solid var(--border);\n      border-radius: 4px;\n      padding: 0.625rem 0.75rem;\n      margin-top: 0.75rem;\n      font-size: 0.8125rem;\n      color: var(--text-muted);\n      line-height: 1.5;\n    }\n    .prev-feedback-label {\n      font-size: 0.7rem;\n      font-weight: 600;\n      text-transform: uppercase;\n      letter-spacing: 0.04em;\n      margin-bottom: 0.25rem;\n      color: var(--text-muted);\n    }\n    .feedback-textarea {\n      width: 100%;\n      min-height: 100px;\n      padding: 0.75rem;\n      border: 1px solid var(--border);\n      border-radius: 4px;\n      font-family: inherit;\n      font-size: 0.9375rem;\n      line-height: 1.5;\n      resize: vertical;\n      color: var(--text);\n    }\n    .feedback-textarea:focus {\n      outline: none;\n      border-color: var(--accent);\n      box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.1);\n    }\n    .feedback-status {\n      font-size: 0.75rem;\n      color: var(--text-muted);\n      margin-top: 0.5rem;\n      min-height: 1.1em;\n    }\n\n    /* ---- Grades (collapsible) ---- */\n    .grades-toggle {\n      display: flex;\n      align-items: center;\n      cursor: pointer;\n      user-select: none;\n    }\n    .grades-toggle:hover {\n      color: var(--accent);\n    }\n    .grades-toggle .arrow {\n      margin-right: 0.5rem;\n      transition: transform 0.15s;\n      font-size: 0.75rem;\n    }\n    .grades-toggle .arrow.open {\n      transform: rotate(90deg);\n    }\n    .grades-content {\n      display: none;\n      margin-top: 0.75rem;\n    }\n    .grades-content.open {\n      display: block;\n    }\n    .grades-summary {\n      font-size: 0.875rem;\n      margin-bottom: 0.75rem;\n      display: flex;\n      align-items: center;\n      gap: 0.5rem;\n    }\n    .grade-badge {\n      display: inline-block;\n      padding: 0.125rem 0.5rem;\n      border-radius: 9999px;\n      font-size: 0.75rem;\n      font-weight: 600;\n    }\n    .grade-pass { background: var(--green-bg); color: var(--green); }\n    .grade-fail { background: var(--red-bg); color: var(--red); }\n    .assertion-list {\n      list-style: none;\n    }\n    .assertion-item {\n      padding: 0.625rem 0;\n      border-bottom: 1px solid var(--border);\n      font-size: 0.8125rem;\n    }\n    .assertion-item:last-child { border-bottom: none; }\n    .assertion-status {\n      font-weight: 600;\n      margin-right: 0.5rem;\n    }\n    .assertion-status.pass { color: var(--green); }\n    .assertion-status.fail { color: var(--red); }\n    .assertion-evidence {\n      color: var(--text-muted);\n      font-size: 0.75rem;\n      margin-top: 0.25rem;\n      padding-left: 1.5rem;\n    }\n\n    /* ---- View tabs ---- */\n    .view-tabs {\n      display: flex;\n      gap: 0;\n      padding: 0 2rem;\n      background: var(--bg);\n      border-bottom: 1px solid var(--border);\n      flex-shrink: 0;\n    }\n    .view-tab {\n      font-family: \'Poppins\', sans-serif;\n      padding: 0.625rem 1.25rem;\n      font-size: 0.8125rem;\n      font-weight: 500;\n      cursor: pointer;\n      border: none;\n      background: none;\n      color: var(--text-muted);\n      border-bottom: 2px solid transparent;\n      transition: all 0.15s;\n    }\n    .view-tab:hover { color: var(--text); }\n    .view-tab.active {\n      color: var(--accent);\n      border-bottom-color: var(--accent);\n    }\n    .view-panel { display: none; }\n    .view-panel.active { display: flex; flex-direction: column; flex: 1; overflow: hidden; }\n\n    /* ---- Benchmark view ---- */\n    .benchmark-view {\n      padding: 1.5rem 2rem;\n      overflow-y: auto;\n      flex: 1;\n    }\n    .benchmark-table {\n      border-collapse: collapse;\n      background: var(--surface);\n      border: 1px solid var(--border);\n      border-radius: var(--radius);\n      font-size: 0.8125rem;\n      width: 100%;\n      margin-bottom: 1.5rem;\n    }\n    .benchmark-table th, .benchmark-table td {\n      padding: 0.625rem 0.75rem;\n      text-align: left;\n      border: 1px solid var(--border);\n    }\n    .benchmark-table th {\n      font-family: \'Poppins\', sans-serif;\n      background: var(--header-bg);\n      color: var(--header-text);\n      font-weight: 500;\n      font-size: 0.75rem;\n      text-transform: uppercase;\n      letter-spacing: 0.04em;\n    }\n    .benchmark-table tr:hover { background: var(--bg); }\n    .benchmark-table tr.benchmark-row-with { background: rgba(33, 150, 243, 0.06); }\n    .benchmark-table tr.benchmark-row-without { background: rgba(255, 193, 7, 0.06); }\n    .benchmark-table tr.benchmark-row-with:hover { background: rgba(33, 150, 243, 0.12); }\n    .benchmark-table tr.benchmark-row-without:hover { background: rgba(255, 193, 7, 0.12); }\n    .benchmark-table tr.benchmark-row-avg { font-weight: 600; border-top: 2px solid var(--border); }\n    .benchmark-table tr.benchmark-row-avg.benchmark-row-with { background: rgba(33, 150, 243, 0.12); }\n    .benchmark-table tr.benchmark-row-avg.benchmark-row-without { background: rgba(255, 193, 7, 0.12); }\n    .benchmark-delta-positive { color: var(--green); font-weight: 600; }\n    .benchmark-delta-negative { color: var(--red); font-weight: 600; }\n    .benchmark-notes {\n      background: var(--surface);\n      border: 1px solid var(--border);\n      border-radius: var(--radius);\n      padding: 1rem;\n    }\n    .benchmark-notes h3 {\n      font-family: \'Poppins\', sans-serif;\n      font-size: 0.875rem;\n      margin-bottom: 0.75rem;\n    }\n    .benchmark-notes ul {\n      list-style: disc;\n      padding-left: 1.25rem;\n    }\n    .benchmark-notes li {\n      font-size: 0.8125rem;\n      line-height: 1.6;\n      margin-bottom: 0.375rem;\n    }\n    .benchmark-empty {\n      color: var(--text-muted);\n      font-style: italic;\n      text-align: center;\n      padding: 3rem;\n    }\n\n    /* ---- Navigation ---- */\n    .nav {\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      padding: 1rem 2rem;\n      border-top: 1px solid var(--border);\n      background: var(--surface);\n      flex-shrink: 0;\n    }\n    .nav-btn {\n      font-family: \'Poppins\', sans-serif;\n      padding: 0.5rem 1.25rem;\n      border: 1px solid var(--border);\n      border-radius: var(--radius);\n      background: var(--surface);\n      cursor: pointer;\n      font-size: 0.875rem;\n      font-weight: 500;\n      color: var(--text);\n      transition: all 0.15s;\n    }\n    .nav-btn:hover:not(:disabled) {\n      background: var(--bg);\n      border-color: var(--text-muted);\n    }\n    .nav-btn:disabled {\n      opacity: 0.4;\n      cursor: not-allowed;\n    }\n    .done-btn {\n      font-family: \'Poppins\', sans-serif;\n      padding: 0.5rem 1.5rem;\n      border: 1px solid var(--border);\n      border-radius: var(--radius);\n      background: var(--surface);\n      color: var(--text);\n      cursor: pointer;\n      font-size: 0.875rem;\n      font-weight: 500;\n      transition: all 0.15s;\n    }\n    .done-btn:hover {\n      background: var(--bg);\n      border-color: var(--text-muted);\n    }\n    .done-btn.ready {\n      border: none;\n      background: var(--accent);\n      color: white;\n      font-weight: 600;\n    }\n    .done-btn.ready:hover {\n      background: var(--accent-hover);\n    }\n    /* ---- Done overlay ---- */\n    .done-overlay {\n      display: none;\n      position: fixed;\n      inset: 0;\n      background: rgba(0, 0, 0, 0.5);\n      z-index: 100;\n      justify-content: center;\n      align-items: center;\n    }\n    .done-overlay.visible {\n      display: flex;\n    }\n    .done-card {\n      background: var(--surface);\n      border-radius: 12px;\n      padding: 2rem 3rem;\n      text-align: center;\n      box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);\n      max-width: 500px;\n    }\n    .done-card h2 {\n      font-size: 1.5rem;\n      margin-bottom: 0.5rem;\n    }\n    .done-card p {\n      color: var(--text-muted);\n      margin-bottom: 1.5rem;\n      line-height: 1.5;\n    }\n    .done-card .btn-row {\n      display: flex;\n      gap: 0.5rem;\n      justify-content: center;\n    }\n    .done-card button {\n      padding: 0.5rem 1.25rem;\n      border: 1px solid var(--border);\n      border-radius: var(--radius);\n      background: var(--surface);\n      cursor: pointer;\n      font-size: 0.875rem;\n    }\n    .done-card button:hover {\n      background: var(--bg);\n    }\n    /* ---- Toast ---- */\n    .toast {\n      position: fixed;\n      bottom: 5rem;\n      left: 50%;\n      transform: translateX(-50%);\n      background: var(--header-bg);\n      color: var(--header-text);\n      padding: 0.625rem 1.25rem;\n      border-radius: var(--radius);\n      font-size: 0.875rem;\n      opacity: 0;\n      transition: opacity 0.3s;\n      pointer-events: none;\n      z-index: 200;\n    }\n    .toast.visible {\n      opacity: 1;\n    }\n  </style>\n</head>\n<body>\n  <div id=\"app\" style=\"height:100vh; display:flex; flex-direction:column;\">\n    <div class=\"header\">\n      <div>\n        <h1>Eval Review: <span id=\"skill-name\"></span></h1>\n        <div class=\"instructions\">Review each output and leave feedback below. Navigate with arrow keys or buttons. When done, copy feedback and paste into Claude Code.</div>\n      </div>\n      <div class=\"progress\" id=\"progress\"></div>\n    </div>\n\n    <!-- View tabs (only shown when benchmark data exists) -->\n    <div class=\"view-tabs\" id=\"view-tabs\" style=\"display:none;\">\n      <button class=\"view-tab active\" onclick=\"switchView(\'outputs\')\">Outputs</button>\n      <button class=\"view-tab\" onclick=\"switchView(\'benchmark\')\">Benchmark</button>\n    </div>\n\n    <!-- Outputs panel (qualitative review) -->\n    <div class=\"view-panel active\" id=\"panel-outputs\">\n    <div class=\"main\">\n      <!-- Prompt -->\n      <div class=\"section\">\n        <div class=\"section-header\">Prompt <span class=\"config-badge\" id=\"config-badge\" style=\"display:none;\"></span></div>\n        <div class=\"section-body\">\n          <div class=\"prompt-text\" id=\"prompt-text\"></div>\n        </div>\n      </div>\n\n      <!-- Outputs -->\n      <div class=\"section\">\n        <div class=\"section-header\">Output</div>\n        <div class=\"section-body\" id=\"outputs-body\">\n          <div class=\"empty-state\">No output files found</div>\n        </div>\n      </div>\n\n      <!-- Previous Output (collapsible) -->\n      <div class=\"section\" id=\"prev-outputs-section\" style=\"display:none;\">\n        <div class=\"section-header\">\n          <div class=\"grades-toggle\" onclick=\"togglePrevOutputs()\">\n            <span class=\"arrow\" id=\"prev-outputs-arrow\">&#9654;</span>\n            Previous Output\n          </div>\n        </div>\n        <div class=\"grades-content\" id=\"prev-outputs-content\"></div>\n      </div>\n\n      <!-- Grades (collapsible) -->\n      <div class=\"section\" id=\"grades-section\" style=\"display:none;\">\n        <div class=\"section-header\">\n          <div class=\"grades-toggle\" onclick=\"toggleGrades()\">\n            <span class=\"arrow\" id=\"grades-arrow\">&#9654;</span>\n            Formal Grades\n          </div>\n        </div>\n        <div class=\"grades-content\" id=\"grades-content\"></div>\n      </div>\n\n      <!-- Feedback -->\n      <div class=\"section\">\n        <div class=\"section-header\">Your Feedback</div>\n        <div class=\"section-body\">\n          <textarea\n            class=\"feedback-textarea\"\n            id=\"feedback\"\n            placeholder=\"What do you think of this output? Any issues, suggestions, or things that look great?\"\n          ></textarea>\n          <div class=\"feedback-status\" id=\"feedback-status\"></div>\n          <div class=\"prev-feedback\" id=\"prev-feedback\" style=\"display:none;\">\n            <div class=\"prev-feedback-label\">Previous feedback</div>\n            <div id=\"prev-feedback-text\"></div>\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"nav\" id=\"outputs-nav\">\n      <button class=\"nav-btn\" id=\"prev-btn\" onclick=\"navigate(-1)\">&#8592; Previous</button>\n      <button class=\"done-btn\" id=\"done-btn\" onclick=\"showDoneDialog()\">Submit All Reviews</button>\n      <button class=\"nav-btn\" id=\"next-btn\" onclick=\"navigate(1)\">Next &#8594;</button>\n    </div>\n    </div><!-- end panel-outputs -->\n\n    <!-- Benchmark panel (quantitative stats) -->\n    <div class=\"view-panel\" id=\"panel-benchmark\">\n      <div class=\"benchmark-view\" id=\"benchmark-content\">\n        <div class=\"benchmark-empty\">No benchmark data available. Run a benchmark to see quantitative results here.</div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Done overlay -->\n  <div class=\"done-overlay\" id=\"done-overlay\">\n    <div class=\"done-card\">\n      <h2>Review Complete</h2>\n      <p>Your feedback has been saved. Go back to your Claude Code session and tell Claude you\'re done reviewing.</p>\n      <div class=\"btn-row\">\n        <button onclick=\"closeDoneDialog()\">OK</button>\n      </div>\n    </div>\n  </div>\n\n  <!-- Toast -->\n  <div class=\"toast\" id=\"toast\"></div>\n\n  <script>\n    // ---- Embedded data (injected by generate_review.py) ----\n    /*__EMBEDDED_DATA__*/\n\n    // ---- State ----\n    let feedbackMap = {};  // run_id -> feedback text\n    let currentIndex = 0;\n    let visitedRuns = new Set();\n\n    // ---- Init ----\n    async function init() {\n      // Load saved feedback from server — but only if this isn\'t a fresh\n      // iteration (indicated by previous_feedback being present). When\n      // previous feedback exists, the feedback.json on disk is stale from\n      // the prior iteration and should not pre-fill the textareas.\n      const hasPrevious = Object.keys(EMBEDDED_DATA.previous_feedback || {}).length > 0\n        || Object.keys(EMBEDDED_DATA.previous_outputs || {}).length > 0;\n      if (!hasPrevious) {\n        try {\n          const resp = await fetch(\"/api/feedback\");\n          const data = await resp.json();\n          if (data.reviews) {\n            for (const r of data.reviews) feedbackMap[r.run_id] = r.feedback;\n          }\n        } catch { /* first run, no feedback yet */ }\n      }\n\n      document.getElementById(\"skill-name\").textContent = EMBEDDED_DATA.skill_name;\n      showRun(0);\n\n      // Wire up feedback auto-save\n      const textarea = document.getElementById(\"feedback\");\n      let saveTimeout = null;\n      textarea.addEventListener(\"input\", () => {\n        clearTimeout(saveTimeout);\n        document.getElementById(\"feedback-status\").textContent = \"\";\n        saveTimeout = setTimeout(() => saveCurrentFeedback(), 800);\n      });\n    }\n\n    // ---- Navigation ----\n    function navigate(delta) {\n      const newIndex = currentIndex + delta;\n      if (newIndex >= 0 && newIndex < EMBEDDED_DATA.runs.length) {\n        saveCurrentFeedback();\n        showRun(newIndex);\n      }\n    }\n\n    function updateNavButtons() {\n      document.getElementById(\"prev-btn\").disabled = currentIndex === 0;\n      document.getElementById(\"next-btn\").disabled =\n        currentIndex === EMBEDDED_DATA.runs.length - 1;\n    }\n\n    // ---- Show a run ----\n    function showRun(index) {\n      currentIndex = index;\n      const run = EMBEDDED_DATA.runs[index];\n\n      // Progress\n      document.getElementById(\"progress\").textContent =\n        `${index + 1} of ${EMBEDDED_DATA.runs.length}`;\n\n      // Prompt\n      document.getElementById(\"prompt-text\").textContent = run.prompt;\n\n      // Config badge\n      const badge = document.getElementById(\"config-badge\");\n      const configMatch = run.id.match(/(with_skill|without_skill|new_skill|old_skill)/);\n      if (configMatch) {\n        const config = configMatch[1];\n        const isBaseline = config === \"without_skill\" || config === \"old_skill\";\n        badge.textContent = config.replace(/_/g, \" \");\n        badge.className = \"config-badge \" + (isBaseline ? \"config-baseline\" : \"config-primary\");\n        badge.style.display = \"inline-block\";\n      } else {\n        badge.style.display = \"none\";\n      }\n\n      // Outputs\n      renderOutputs(run);\n\n      // Previous outputs\n      renderPrevOutputs(run);\n\n      // Grades\n      renderGrades(run);\n\n      // Previous feedback\n      const prevFb = (EMBEDDED_DATA.previous_feedback || {})[run.id];\n      const prevEl = document.getElementById(\"prev-feedback\");\n      if (prevFb) {\n        document.getElementById(\"prev-feedback-text\").textContent = prevFb;\n        prevEl.style.display = \"block\";\n      } else {\n        prevEl.style.display = \"none\";\n      }\n\n      // Feedback\n      document.getElementById(\"feedback\").value = feedbackMap[run.id] || \"\";\n      document.getElementById(\"feedback-status\").textContent = \"\";\n\n      updateNavButtons();\n\n      // Track visited runs and promote done button when all visited\n      visitedRuns.add(index);\n      const doneBtn = document.getElementById(\"done-btn\");\n      if (visitedRuns.size >= EMBEDDED_DATA.runs.length) {\n        doneBtn.classList.add(\"ready\");\n      }\n\n      // Scroll main content to top\n      document.querySelector(\".main\").scrollTop = 0;\n    }\n\n    // ---- Render outputs ----\n    function renderOutputs(run) {\n      const container = document.getElementById(\"outputs-body\");\n      container.innerHTML = \"\";\n\n      const outputs = run.outputs || [];\n      if (outputs.length === 0) {\n        container.innerHTML = \'<div class=\"empty-state\">No output files</div>\';\n        return;\n      }\n\n      for (const file of outputs) {\n        const fileDiv = document.createElement(\"div\");\n        fileDiv.className = \"output-file\";\n\n        // Always show file header with download link\n        const header = document.createElement(\"div\");\n        header.className = \"output-file-header\";\n        const nameSpan = document.createElement(\"span\");\n        nameSpan.textContent = file.name;\n        header.appendChild(nameSpan);\n        const dlBtn = document.createElement(\"a\");\n        dlBtn.className = \"dl-btn\";\n        dlBtn.textContent = \"Download\";\n        dlBtn.download = file.name;\n        dlBtn.href = getDownloadUri(file);\n        header.appendChild(dlBtn);\n        fileDiv.appendChild(header);\n\n        const content = document.createElement(\"div\");\n        content.className = \"output-file-content\";\n\n        if (file.type === \"text\") {\n          const pre = document.createElement(\"pre\");\n          pre.textContent = file.content;\n          content.appendChild(pre);\n        } else if (file.type === \"image\") {\n          const img = document.createElement(\"img\");\n          img.src = file.data_uri;\n          img.alt = file.name;\n          content.appendChild(img);\n        } else if (file.type === \"pdf\") {\n          const iframe = document.createElement(\"iframe\");\n          iframe.src = file.data_uri;\n          content.appendChild(iframe);\n        } else if (file.type === \"xlsx\") {\n          renderXlsx(content, file.data_b64);\n        } else if (file.type === \"binary\") {\n          const a = document.createElement(\"a\");\n          a.className = \"download-link\";\n          a.href = file.data_uri;\n          a.download = file.name;\n          a.textContent = \"Download \" + file.name;\n          content.appendChild(a);\n        } else if (file.type === \"error\") {\n          const pre = document.createElement(\"pre\");\n          pre.textContent = file.content;\n          pre.style.color = \"var(--red)\";\n          content.appendChild(pre);\n        }\n\n        fileDiv.appendChild(content);\n        container.appendChild(fileDiv);\n      }\n    }\n\n    // ---- XLSX rendering via SheetJS ----\n    function renderXlsx(container, b64Data) {\n      try {\n        const raw = Uint8Array.from(atob(b64Data), c => c.charCodeAt(0));\n        const wb = XLSX.read(raw, { type: \"array\" });\n\n        for (let i = 0; i < wb.SheetNames.length; i++) {\n          const sheetName = wb.SheetNames[i];\n          const ws = wb.Sheets[sheetName];\n\n          if (wb.SheetNames.length > 1) {\n            const sheetLabel = document.createElement(\"div\");\n            sheetLabel.style.cssText =\n              \"font-weight:600; font-size:0.8rem; color:#b0aea5; margin-top:0.5rem; margin-bottom:0.25rem;\";\n            sheetLabel.textContent = \"Sheet: \" + sheetName;\n            container.appendChild(sheetLabel);\n          }\n\n          const htmlStr = XLSX.utils.sheet_to_html(ws, { editable: false });\n          const wrapper = document.createElement(\"div\");\n          wrapper.innerHTML = htmlStr;\n          container.appendChild(wrapper);\n        }\n      } catch (err) {\n        container.textContent = \"Error rendering spreadsheet: \" + err.message;\n      }\n    }\n\n    // ---- Grades ----\n    function renderGrades(run) {\n      const section = document.getElementById(\"grades-section\");\n      const content = document.getElementById(\"grades-content\");\n\n      if (!run.grading) {\n        section.style.display = \"none\";\n        return;\n      }\n\n      const grading = run.grading;\n      section.style.display = \"block\";\n      // Reset to collapsed\n      content.classList.remove(\"open\");\n      document.getElementById(\"grades-arrow\").classList.remove(\"open\");\n\n      const summary = grading.summary || {};\n      const expectations = grading.expectations || [];\n\n      let html = \'<div style=\"padding: 1rem;\">\';\n\n      // Summary line\n      const passRate = summary.pass_rate != null\n        ? Math.round(summary.pass_rate * 100) + \"%\"\n        : \"?\";\n      const badgeClass = summary.pass_rate >= 0.8 ? \"grade-pass\" : summary.pass_rate >= 0.5 ? \"\" : \"grade-fail\";\n      html += \'<div class=\"grades-summary\">\';\n      html += \'<span class=\"grade-badge \' + badgeClass + \'\">\' + passRate + \'</span>\';\n      html += \'<span>\' + (summary.passed || 0) + \' passed, \' + (summary.failed || 0) + \' failed of \' + (summary.total || 0) + \'</span>\';\n      html += \'</div>\';\n\n      // Assertions list\n      html += \'<ul class=\"assertion-list\">\';\n      for (const exp of expectations) {\n        const statusClass = exp.passed ? \"pass\" : \"fail\";\n        const statusIcon = exp.passed ? \"\\u2713\" : \"\\u2717\";\n        html += \'<li class=\"assertion-item\">\';\n        html += \'<span class=\"assertion-status \' + statusClass + \'\">\' + statusIcon + \'</span>\';\n        html += \'<span>\' + escapeHtml(exp.text) + \'</span>\';\n        if (exp.evidence) {\n          html += \'<div class=\"assertion-evidence\">\' + escapeHtml(exp.evidence) + \'</div>\';\n        }\n        html += \'</li>\';\n      }\n      html += \'</ul>\';\n\n      html += \'</div>\';\n      content.innerHTML = html;\n    }\n\n    function toggleGrades() {\n      const content = document.getElementById(\"grades-content\");\n      const arrow = document.getElementById(\"grades-arrow\");\n      content.classList.toggle(\"open\");\n      arrow.classList.toggle(\"open\");\n    }\n\n    // ---- Previous outputs (collapsible) ----\n    function renderPrevOutputs(run) {\n      const section = document.getElementById(\"prev-outputs-section\");\n      const content = document.getElementById(\"prev-outputs-content\");\n      const prevOutputs = (EMBEDDED_DATA.previous_outputs || {})[run.id];\n\n      if (!prevOutputs || prevOutputs.length === 0) {\n        section.style.display = \"none\";\n        return;\n      }\n\n      section.style.display = \"block\";\n      // Reset to collapsed\n      content.classList.remove(\"open\");\n      document.getElementById(\"prev-outputs-arrow\").classList.remove(\"open\");\n\n      // Render the files into the content area\n      content.innerHTML = \"\";\n      const wrapper = document.createElement(\"div\");\n      wrapper.style.padding = \"1rem\";\n\n      for (const file of prevOutputs) {\n        const fileDiv = document.createElement(\"div\");\n        fileDiv.className = \"output-file\";\n\n        const header = document.createElement(\"div\");\n        header.className = \"output-file-header\";\n        const nameSpan = document.createElement(\"span\");\n        nameSpan.textContent = file.name;\n        header.appendChild(nameSpan);\n        const dlBtn = document.createElement(\"a\");\n        dlBtn.className = \"dl-btn\";\n        dlBtn.textContent = \"Download\";\n        dlBtn.download = file.name;\n        dlBtn.href = getDownloadUri(file);\n        header.appendChild(dlBtn);\n        fileDiv.appendChild(header);\n\n        const fc = document.createElement(\"div\");\n        fc.className = \"output-file-content\";\n\n        if (file.type === \"text\") {\n          const pre = document.createElement(\"pre\");\n          pre.textContent = file.content;\n          fc.appendChild(pre);\n        } else if (file.type === \"image\") {\n          const img = document.createElement(\"img\");\n          img.src = file.data_uri;\n          img.alt = file.name;\n          fc.appendChild(img);\n        } else if (file.type === \"pdf\") {\n          const iframe = document.createElement(\"iframe\");\n          iframe.src = file.data_uri;\n          fc.appendChild(iframe);\n        } else if (file.type === \"xlsx\") {\n          renderXlsx(fc, file.data_b64);\n        } else if (file.type === \"binary\") {\n          const a = document.createElement(\"a\");\n          a.className = \"download-link\";\n          a.href = file.data_uri;\n          a.download = file.name;\n          a.textContent = \"Download \" + file.name;\n          fc.appendChild(a);\n        }\n\n        fileDiv.appendChild(fc);\n        wrapper.appendChild(fileDiv);\n      }\n\n      content.appendChild(wrapper);\n    }\n\n    function togglePrevOutputs() {\n      const content = document.getElementById(\"prev-outputs-content\");\n      const arrow = document.getElementById(\"prev-outputs-arrow\");\n      content.classList.toggle(\"open\");\n      arrow.classList.toggle(\"open\");\n    }\n\n    // ---- Feedback (saved to server -> feedback.json) ----\n    function saveCurrentFeedback() {\n      const run = EMBEDDED_DATA.runs[currentIndex];\n      const text = document.getElementById(\"feedback\").value;\n\n      if (text.trim() === \"\") {\n        delete feedbackMap[run.id];\n      } else {\n        feedbackMap[run.id] = text;\n      }\n\n      // Build reviews array from map\n      const reviews = [];\n      for (const [run_id, feedback] of Object.entries(feedbackMap)) {\n        if (feedback.trim()) {\n          reviews.push({ run_id, feedback, timestamp: new Date().toISOString() });\n        }\n      }\n\n      fetch(\"/api/feedback\", {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify({ reviews, status: \"in_progress\" }),\n      }).then(() => {\n        document.getElementById(\"feedback-status\").textContent = \"Saved\";\n      }).catch(() => {\n        // Static mode or server unavailable — no-op on auto-save,\n        // feedback will be downloaded on final submit\n        document.getElementById(\"feedback-status\").textContent = \"Will download on submit\";\n      });\n    }\n\n    // ---- Done ----\n    function showDoneDialog() {\n      // Save current textarea to feedbackMap (but don\'t POST yet)\n      const run = EMBEDDED_DATA.runs[currentIndex];\n      const text = document.getElementById(\"feedback\").value;\n      if (text.trim() === \"\") {\n        delete feedbackMap[run.id];\n      } else {\n        feedbackMap[run.id] = text;\n      }\n\n      // POST once with status: complete — include ALL runs so the model\n      // can distinguish \"no feedback\" (looks good) from \"not reviewed\"\n      const reviews = [];\n      const ts = new Date().toISOString();\n      for (const r of EMBEDDED_DATA.runs) {\n        reviews.push({ run_id: r.id, feedback: feedbackMap[r.id] || \"\", timestamp: ts });\n      }\n      const payload = JSON.stringify({ reviews, status: \"complete\" }, null, 2);\n      fetch(\"/api/feedback\", {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/json\" },\n        body: payload,\n      }).then(() => {\n        document.getElementById(\"done-overlay\").classList.add(\"visible\");\n      }).catch(() => {\n        // Server not available (static mode) — download as file\n        const blob = new Blob([payload], { type: \"application/json\" });\n        const url = URL.createObjectURL(blob);\n        const a = document.createElement(\"a\");\n        a.href = url;\n        a.download = \"feedback.json\";\n        a.click();\n        URL.revokeObjectURL(url);\n        document.getElementById(\"done-overlay\").classList.add(\"visible\");\n      });\n    }\n\n    function closeDoneDialog() {\n      // Reset status back to in_progress\n      saveCurrentFeedback();\n      document.getElementById(\"done-overlay\").classList.remove(\"visible\");\n    }\n\n    // ---- Toast ----\n    function showToast(message) {\n      const toast = document.getElementById(\"toast\");\n      toast.textContent = message;\n      toast.classList.add(\"visible\");\n      setTimeout(() => toast.classList.remove(\"visible\"), 2000);\n    }\n\n    // ---- Keyboard nav ----\n    document.addEventListener(\"keydown\", (e) => {\n      // Don\'t capture when typing in textarea\n      if (e.target.tagName === \"TEXTAREA\") return;\n\n      if (e.key === \"ArrowLeft\" || e.key === \"ArrowUp\") {\n        e.preventDefault();\n        navigate(-1);\n      } else if (e.key === \"ArrowRight\" || e.key === \"ArrowDown\") {\n        e.preventDefault();\n        navigate(1);\n      }\n    });\n\n    // ---- Util ----\n    function getDownloadUri(file) {\n      if (file.data_uri) return file.data_uri;\n      if (file.data_b64) return \"data:application/octet-stream;base64,\" + file.data_b64;\n      if (file.type === \"text\") return \"data:text/plain;charset=utf-8,\" + encodeURIComponent(file.content);\n      return \"#\";\n    }\n\n    function escapeHtml(text) {\n      const div = document.createElement(\"div\");\n      div.textContent = text;\n      return div.innerHTML;\n    }\n\n    // ---- View switching ----\n    function switchView(view) {\n      document.querySelectorAll(\".view-tab\").forEach(t => t.classList.remove(\"active\"));\n      document.querySelectorAll(\".view-panel\").forEach(p => p.classList.remove(\"active\"));\n      document.querySelector(`[onclick=\"switchView(\'${view}\')\"]`).classList.add(\"active\");\n      document.getElementById(\"panel-\" + view).classList.add(\"active\");\n    }\n\n    // ---- Benchmark rendering ----\n    function renderBenchmark() {\n      const data = EMBEDDED_DATA.benchmark;\n      if (!data) return;\n\n      // Show the tabs\n      document.getElementById(\"view-tabs\").style.display = \"flex\";\n\n      const container = document.getElementById(\"benchmark-content\");\n      const summary = data.run_summary || {};\n      const metadata = data.metadata || {};\n      const notes = data.notes || [];\n\n      let html = \"\";\n\n      // Header\n      html += \"<h2 style=\'font-family: Poppins, sans-serif; margin-bottom: 0.5rem;\'>Benchmark Results</h2>\";\n      html += \"<p style=\'color: var(--text-muted); font-size: 0.875rem; margin-bottom: 1.25rem;\'>\";\n      if (metadata.skill_name) html += \"<strong>\" + escapeHtml(metadata.skill_name) + \"</strong> &mdash; \";\n      if (metadata.timestamp) html += metadata.timestamp + \" &mdash; \";\n      if (metadata.evals_run) html += \"Evals: \" + metadata.evals_run.join(\", \") + \" &mdash; \";\n      html += (metadata.runs_per_configuration || \"?\") + \" runs per configuration\";\n      html += \"</p>\";\n\n      // Summary table\n      html += \'<table class=\"benchmark-table\">\';\n\n      function fmtStat(stat, pct) {\n        if (!stat) return \"—\";\n        const suffix = pct ? \"%\" : \"\";\n        const m = pct ? (stat.mean * 100).toFixed(0) : stat.mean.toFixed(1);\n        const s = pct ? (stat.stddev * 100).toFixed(0) : stat.stddev.toFixed(1);\n        return m + suffix + \" ± \" + s + suffix;\n      }\n\n      function deltaClass(val) {\n        if (!val) return \"\";\n        const n = parseFloat(val);\n        if (n > 0) return \"benchmark-delta-positive\";\n        if (n < 0) return \"benchmark-delta-negative\";\n        return \"\";\n      }\n\n      // Discover config names dynamically (everything except \"delta\")\n      const configs = Object.keys(summary).filter(k => k !== \"delta\");\n      const configA = configs[0] || \"config_a\";\n      const configB = configs[1] || \"config_b\";\n      const labelA = configA.replace(/_/g, \" \").replace(/\\b\\w/g, c => c.toUpperCase());\n      const labelB = configB.replace(/_/g, \" \").replace(/\\b\\w/g, c => c.toUpperCase());\n      const a = summary[configA] || {};\n      const b = summary[configB] || {};\n      const delta = summary.delta || {};\n\n      html += \"<thead><tr><th>Metric</th><th>\" + escapeHtml(labelA) + \"</th><th>\" + escapeHtml(labelB) + \"</th><th>Delta</th></tr></thead>\";\n      html += \"<tbody>\";\n\n      html += \"<tr><td><strong>Pass Rate</strong></td>\";\n      html += \"<td>\" + fmtStat(a.pass_rate, true) + \"</td>\";\n      html += \"<td>\" + fmtStat(b.pass_rate, true) + \"</td>\";\n      html += \'<td class=\"\' + deltaClass(delta.pass_rate) + \'\">\' + (delta.pass_rate || \"—\") + \"</td></tr>\";\n\n      // Time (only show row if data exists)\n      if (a.time_seconds || b.time_seconds) {\n        html += \"<tr><td><strong>Time (s)</strong></td>\";\n        html += \"<td>\" + fmtStat(a.time_seconds, false) + \"</td>\";\n        html += \"<td>\" + fmtStat(b.time_seconds, false) + \"</td>\";\n        html += \'<td class=\"\' + deltaClass(delta.time_seconds) + \'\">\' + (delta.time_seconds ? delta.time_seconds + \"s\" : \"—\") + \"</td></tr>\";\n      }\n\n      // Tokens (only show row if data exists)\n      if (a.tokens || b.tokens) {\n        html += \"<tr><td><strong>Tokens</strong></td>\";\n        html += \"<td>\" + fmtStat(a.tokens, false) + \"</td>\";\n        html += \"<td>\" + fmtStat(b.tokens, false) + \"</td>\";\n        html += \'<td class=\"\' + deltaClass(delta.tokens) + \'\">\' + (delta.tokens || \"—\") + \"</td></tr>\";\n      }\n\n      html += \"</tbody></table>\";\n\n      // Per-eval breakdown (if runs data available)\n      const runs = data.runs || [];\n      if (runs.length > 0) {\n        const evalIds = [...new Set(runs.map(r => r.eval_id))].sort((a, b) => a - b);\n\n        html += \"<h3 style=\'font-family: Poppins, sans-serif; margin-bottom: 0.75rem;\'>Per-Eval Breakdown</h3>\";\n\n        const hasTime = runs.some(r => r.result && r.result.time_seconds != null);\n        const hasErrors = runs.some(r => r.result && r.result.errors > 0);\n\n        for (const evalId of evalIds) {\n          const evalRuns = runs.filter(r => r.eval_id === evalId);\n          const evalName = evalRuns[0] && evalRuns[0].eval_name ? evalRuns[0].eval_name : \"Eval \" + evalId;\n\n          html += \"<h4 style=\'font-family: Poppins, sans-serif; margin: 1rem 0 0.5rem; color: var(--text);\'>\" + escapeHtml(evalName) + \"</h4>\";\n          html += \'<table class=\"benchmark-table\">\';\n          html += \"<thead><tr><th>Config</th><th>Run</th><th>Pass Rate</th>\";\n          if (hasTime) html += \"<th>Time (s)</th>\";\n          if (hasErrors) html += \"<th>Crashes During Execution</th>\";\n          html += \"</tr></thead>\";\n          html += \"<tbody>\";\n\n          // Group by config and render with average rows\n          const configGroups = [...new Set(evalRuns.map(r => r.configuration))];\n          for (let ci = 0; ci < configGroups.length; ci++) {\n            const config = configGroups[ci];\n            const configRuns = evalRuns.filter(r => r.configuration === config);\n            if (configRuns.length === 0) continue;\n\n            const rowClass = ci === 0 ? \"benchmark-row-with\" : \"benchmark-row-without\";\n            const configLabel = config.replace(/_/g, \" \").replace(/\\b\\w/g, c => c.toUpperCase());\n\n            for (const run of configRuns) {\n              const r = run.result || {};\n              const prClass = r.pass_rate >= 0.8 ? \"benchmark-delta-positive\" : r.pass_rate < 0.5 ? \"benchmark-delta-negative\" : \"\";\n              html += \'<tr class=\"\' + rowClass + \'\">\';\n              html += \"<td>\" + configLabel + \"</td>\";\n              html += \"<td>\" + run.run_number + \"</td>\";\n              html += \'<td class=\"\' + prClass + \'\">\' + ((r.pass_rate || 0) * 100).toFixed(0) + \"% (\" + (r.passed || 0) + \"/\" + (r.total || 0) + \")</td>\";\n              if (hasTime) html += \"<td>\" + (r.time_seconds != null ? r.time_seconds.toFixed(1) : \"—\") + \"</td>\";\n              if (hasErrors) html += \"<td>\" + (r.errors || 0) + \"</td>\";\n              html += \"</tr>\";\n            }\n\n            // Average row\n            const rates = configRuns.map(r => (r.result || {}).pass_rate || 0);\n            const avgRate = rates.reduce((a, b) => a + b, 0) / rates.length;\n            const avgPrClass = avgRate >= 0.8 ? \"benchmark-delta-positive\" : avgRate < 0.5 ? \"benchmark-delta-negative\" : \"\";\n            html += \'<tr class=\"benchmark-row-avg \' + rowClass + \'\">\';\n            html += \"<td>\" + configLabel + \"</td>\";\n            html += \"<td>Avg</td>\";\n            html += \'<td class=\"\' + avgPrClass + \'\">\' + (avgRate * 100).toFixed(0) + \"%</td>\";\n            if (hasTime) {\n              const times = configRuns.map(r => (r.result || {}).time_seconds).filter(t => t != null);\n              html += \"<td>\" + (times.length ? (times.reduce((a, b) => a + b, 0) / times.length).toFixed(1) : \"—\") + \"</td>\";\n            }\n            if (hasErrors) html += \"<td></td>\";\n            html += \"</tr>\";\n          }\n          html += \"</tbody></table>\";\n\n          // Per-assertion detail for this eval\n          const runsWithExpectations = {};\n          for (const config of configGroups) {\n            runsWithExpectations[config] = evalRuns.filter(r => r.configuration === config && r.expectations && r.expectations.length > 0);\n          }\n          const hasAnyExpectations = Object.values(runsWithExpectations).some(runs => runs.length > 0);\n          if (hasAnyExpectations) {\n            // Collect all unique assertion texts across all configs\n            const allAssertions = [];\n            const seen = new Set();\n            for (const config of configGroups) {\n              for (const run of runsWithExpectations[config]) {\n                for (const exp of (run.expectations || [])) {\n                  if (!seen.has(exp.text)) {\n                    seen.add(exp.text);\n                    allAssertions.push(exp.text);\n                  }\n                }\n              }\n            }\n\n            html += \'<table class=\"benchmark-table\" style=\"margin-top: 0.5rem;\">\';\n            html += \"<thead><tr><th>Assertion</th>\";\n            for (const config of configGroups) {\n              const label = config.replace(/_/g, \" \").replace(/\\b\\w/g, c => c.toUpperCase());\n              html += \"<th>\" + escapeHtml(label) + \"</th>\";\n            }\n            html += \"</tr></thead><tbody>\";\n\n            for (const assertionText of allAssertions) {\n              html += \"<tr><td>\" + escapeHtml(assertionText) + \"</td>\";\n\n              for (const config of configGroups) {\n                html += \"<td>\";\n                for (const run of runsWithExpectations[config]) {\n                  const exp = (run.expectations || []).find(e => e.text === assertionText);\n                  if (exp) {\n                    const cls = exp.passed ? \"benchmark-delta-positive\" : \"benchmark-delta-negative\";\n                    const icon = exp.passed ? \"\\u2713\" : \"\\u2717\";\n                    html += \'<span class=\"\' + cls + \'\" title=\"Run \' + run.run_number + \': \' + escapeHtml(exp.evidence || \"\") + \'\">\' + icon + \"</span> \";\n                  } else {\n                    html += \"— \";\n                  }\n                }\n                html += \"</td>\";\n              }\n              html += \"</tr>\";\n            }\n            html += \"</tbody></table>\";\n          }\n        }\n      }\n\n      // Notes\n      if (notes.length > 0) {\n        html += \'<div class=\"benchmark-notes\">\';\n        html += \"<h3>Analysis Notes</h3>\";\n        html += \"<ul>\";\n        for (const note of notes) {\n          html += \"<li>\" + escapeHtml(note) + \"</li>\";\n        }\n        html += \"</ul></div>\";\n      }\n\n      container.innerHTML = html;\n    }\n\n    // ---- Start ----\n    init();\n    renderBenchmark();\n  </script>\n</body>\n</html>\n','bef0b26fd04ee3a25344b7ae361a5bd1','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(1225,'enc.736372697074732f72756e5f6c6f6f702e7079','skill_enc.736b696c6c2d63726561746f72__enc.302e302e31','#!/usr/bin/env python3\n\"\"\"Run the eval + improve loop until all pass or max iterations reached.\n\nCombines run_eval.py and improve_description.py in a loop, tracking history\nand returning the best description found. Supports train/test split to prevent\noverfitting.\n\"\"\"\n\nimport argparse\nimport json\nimport random\nimport sys\nimport tempfile\nimport time\nimport webbrowser\nfrom pathlib import Path\n\nfrom scripts.generate_report import generate_html\nfrom scripts.improve_description import improve_description\nfrom scripts.run_eval import find_project_root, run_eval\nfrom scripts.utils import parse_skill_md\n\n\ndef split_eval_set(eval_set: list[dict], holdout: float, seed: int = 42) -> tuple[list[dict], list[dict]]:\n    \"\"\"Split eval set into train and test sets, stratified by should_trigger.\"\"\"\n    random.seed(seed)\n\n    # Separate by should_trigger\n    trigger = [e for e in eval_set if e[\"should_trigger\"]]\n    no_trigger = [e for e in eval_set if not e[\"should_trigger\"]]\n\n    # Shuffle each group\n    random.shuffle(trigger)\n    random.shuffle(no_trigger)\n\n    # Calculate split points\n    n_trigger_test = max(1, int(len(trigger) * holdout))\n    n_no_trigger_test = max(1, int(len(no_trigger) * holdout))\n\n    # Split\n    test_set = trigger[:n_trigger_test] + no_trigger[:n_no_trigger_test]\n    train_set = trigger[n_trigger_test:] + no_trigger[n_no_trigger_test:]\n\n    return train_set, test_set\n\n\ndef run_loop(\n    eval_set: list[dict],\n    skill_path: Path,\n    description_override: str | None,\n    num_workers: int,\n    timeout: int,\n    max_iterations: int,\n    runs_per_query: int,\n    trigger_threshold: float,\n    holdout: float,\n    model: str,\n    verbose: bool,\n    live_report_path: Path | None = None,\n    log_dir: Path | None = None,\n) -> dict:\n    \"\"\"Run the eval + improvement loop.\"\"\"\n    project_root = find_project_root()\n    name, original_description, content = parse_skill_md(skill_path)\n    current_description = description_override or original_description\n\n    # Split into train/test if holdout > 0\n    if holdout > 0:\n        train_set, test_set = split_eval_set(eval_set, holdout)\n        if verbose:\n            print(f\"Split: {len(train_set)} train, {len(test_set)} test (holdout={holdout})\", file=sys.stderr)\n    else:\n        train_set = eval_set\n        test_set = []\n\n    history = []\n    exit_reason = \"unknown\"\n\n    for iteration in range(1, max_iterations + 1):\n        if verbose:\n            print(f\"\\n{\'=\'*60}\", file=sys.stderr)\n            print(f\"Iteration {iteration}/{max_iterations}\", file=sys.stderr)\n            print(f\"Description: {current_description}\", file=sys.stderr)\n            print(f\"{\'=\'*60}\", file=sys.stderr)\n\n        # Evaluate train + test together in one batch for parallelism\n        all_queries = train_set + test_set\n        t0 = time.time()\n        all_results = run_eval(\n            eval_set=all_queries,\n            skill_name=name,\n            description=current_description,\n            num_workers=num_workers,\n            timeout=timeout,\n            project_root=project_root,\n            runs_per_query=runs_per_query,\n            trigger_threshold=trigger_threshold,\n            model=model,\n        )\n        eval_elapsed = time.time() - t0\n\n        # Split results back into train/test by matching queries\n        train_queries_set = {q[\"query\"] for q in train_set}\n        train_result_list = [r for r in all_results[\"results\"] if r[\"query\"] in train_queries_set]\n        test_result_list = [r for r in all_results[\"results\"] if r[\"query\"] not in train_queries_set]\n\n        train_passed = sum(1 for r in train_result_list if r[\"pass\"])\n        train_total = len(train_result_list)\n        train_summary = {\"passed\": train_passed, \"failed\": train_total - train_passed, \"total\": train_total}\n        train_results = {\"results\": train_result_list, \"summary\": train_summary}\n\n        if test_set:\n            test_passed = sum(1 for r in test_result_list if r[\"pass\"])\n            test_total = len(test_result_list)\n            test_summary = {\"passed\": test_passed, \"failed\": test_total - test_passed, \"total\": test_total}\n            test_results = {\"results\": test_result_list, \"summary\": test_summary}\n        else:\n            test_results = None\n            test_summary = None\n\n        history.append({\n            \"iteration\": iteration,\n            \"description\": current_description,\n            \"train_passed\": train_summary[\"passed\"],\n            \"train_failed\": train_summary[\"failed\"],\n            \"train_total\": train_summary[\"total\"],\n            \"train_results\": train_results[\"results\"],\n            \"test_passed\": test_summary[\"passed\"] if test_summary else None,\n            \"test_failed\": test_summary[\"failed\"] if test_summary else None,\n            \"test_total\": test_summary[\"total\"] if test_summary else None,\n            \"test_results\": test_results[\"results\"] if test_results else None,\n            # For backward compat with report generator\n            \"passed\": train_summary[\"passed\"],\n            \"failed\": train_summary[\"failed\"],\n            \"total\": train_summary[\"total\"],\n            \"results\": train_results[\"results\"],\n        })\n\n        # Write live report if path provided\n        if live_report_path:\n            partial_output = {\n                \"original_description\": original_description,\n                \"best_description\": current_description,\n                \"best_score\": \"in progress\",\n                \"iterations_run\": len(history),\n                \"holdout\": holdout,\n                \"train_size\": len(train_set),\n                \"test_size\": len(test_set),\n                \"history\": history,\n            }\n            live_report_path.write_text(generate_html(partial_output, auto_refresh=True, skill_name=name))\n\n        if verbose:\n            def print_eval_stats(label, results, elapsed):\n                pos = [r for r in results if r[\"should_trigger\"]]\n                neg = [r for r in results if not r[\"should_trigger\"]]\n                tp = sum(r[\"triggers\"] for r in pos)\n                pos_runs = sum(r[\"runs\"] for r in pos)\n                fn = pos_runs - tp\n                fp = sum(r[\"triggers\"] for r in neg)\n                neg_runs = sum(r[\"runs\"] for r in neg)\n                tn = neg_runs - fp\n                total = tp + tn + fp + fn\n                precision = tp / (tp + fp) if (tp + fp) > 0 else 1.0\n                recall = tp / (tp + fn) if (tp + fn) > 0 else 1.0\n                accuracy = (tp + tn) / total if total > 0 else 0.0\n                print(f\"{label}: {tp+tn}/{total} correct, precision={precision:.0%} recall={recall:.0%} accuracy={accuracy:.0%} ({elapsed:.1f}s)\", file=sys.stderr)\n                for r in results:\n                    status = \"PASS\" if r[\"pass\"] else \"FAIL\"\n                    rate_str = f\"{r[\'triggers\']}/{r[\'runs\']}\"\n                    print(f\"  [{status}] rate={rate_str} expected={r[\'should_trigger\']}: {r[\'query\'][:60]}\", file=sys.stderr)\n\n            print_eval_stats(\"Train\", train_results[\"results\"], eval_elapsed)\n            if test_summary:\n                print_eval_stats(\"Test \", test_results[\"results\"], 0)\n\n        if train_summary[\"failed\"] == 0:\n            exit_reason = f\"all_passed (iteration {iteration})\"\n            if verbose:\n                print(f\"\\nAll train queries passed on iteration {iteration}!\", file=sys.stderr)\n            break\n\n        if iteration == max_iterations:\n            exit_reason = f\"max_iterations ({max_iterations})\"\n            if verbose:\n                print(f\"\\nMax iterations reached ({max_iterations}).\", file=sys.stderr)\n            break\n\n        # Improve the description based on train results\n        if verbose:\n            print(f\"\\nImproving description...\", file=sys.stderr)\n\n        t0 = time.time()\n        # Strip test scores from history so improvement model can\'t see them\n        blinded_history = [\n            {k: v for k, v in h.items() if not k.startswith(\"test_\")}\n            for h in history\n        ]\n        new_description = improve_description(\n            skill_name=name,\n            skill_content=content,\n            current_description=current_description,\n            eval_results=train_results,\n            history=blinded_history,\n            model=model,\n            log_dir=log_dir,\n            iteration=iteration,\n        )\n        improve_elapsed = time.time() - t0\n\n        if verbose:\n            print(f\"Proposed ({improve_elapsed:.1f}s): {new_description}\", file=sys.stderr)\n\n        current_description = new_description\n\n    # Find the best iteration by TEST score (or train if no test set)\n    if test_set:\n        best = max(history, key=lambda h: h[\"test_passed\"] or 0)\n        best_score = f\"{best[\'test_passed\']}/{best[\'test_total\']}\"\n    else:\n        best = max(history, key=lambda h: h[\"train_passed\"])\n        best_score = f\"{best[\'train_passed\']}/{best[\'train_total\']}\"\n\n    if verbose:\n        print(f\"\\nExit reason: {exit_reason}\", file=sys.stderr)\n        print(f\"Best score: {best_score} (iteration {best[\'iteration\']})\", file=sys.stderr)\n\n    return {\n        \"exit_reason\": exit_reason,\n        \"original_description\": original_description,\n        \"best_description\": best[\"description\"],\n        \"best_score\": best_score,\n        \"best_train_score\": f\"{best[\'train_passed\']}/{best[\'train_total\']}\",\n        \"best_test_score\": f\"{best[\'test_passed\']}/{best[\'test_total\']}\" if test_set else None,\n        \"final_description\": current_description,\n        \"iterations_run\": len(history),\n        \"holdout\": holdout,\n        \"train_size\": len(train_set),\n        \"test_size\": len(test_set),\n        \"history\": history,\n    }\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=\"Run eval + improve loop\")\n    parser.add_argument(\"--eval-set\", required=True, help=\"Path to eval set JSON file\")\n    parser.add_argument(\"--skill-path\", required=True, help=\"Path to skill directory\")\n    parser.add_argument(\"--description\", default=None, help=\"Override starting description\")\n    parser.add_argument(\"--num-workers\", type=int, default=10, help=\"Number of parallel workers\")\n    parser.add_argument(\"--timeout\", type=int, default=30, help=\"Timeout per query in seconds\")\n    parser.add_argument(\"--max-iterations\", type=int, default=5, help=\"Max improvement iterations\")\n    parser.add_argument(\"--runs-per-query\", type=int, default=3, help=\"Number of runs per query\")\n    parser.add_argument(\"--trigger-threshold\", type=float, default=0.5, help=\"Trigger rate threshold\")\n    parser.add_argument(\"--holdout\", type=float, default=0.4, help=\"Fraction of eval set to hold out for testing (0 to disable)\")\n    parser.add_argument(\"--model\", required=True, help=\"Model for improvement\")\n    parser.add_argument(\"--verbose\", action=\"store_true\", help=\"Print progress to stderr\")\n    parser.add_argument(\"--report\", default=\"auto\", help=\"Generate HTML report at this path (default: \'auto\' for temp file, \'none\' to disable)\")\n    parser.add_argument(\"--results-dir\", default=None, help=\"Save all outputs (results.json, report.html, log.txt) to a timestamped subdirectory here\")\n    args = parser.parse_args()\n\n    eval_set = json.loads(Path(args.eval_set).read_text())\n    skill_path = Path(args.skill_path)\n\n    if not (skill_path / \"SKILL.md\").exists():\n        print(f\"Error: No SKILL.md found at {skill_path}\", file=sys.stderr)\n        sys.exit(1)\n\n    name, _, _ = parse_skill_md(skill_path)\n\n    # Set up live report path\n    if args.report != \"none\":\n        if args.report == \"auto\":\n            timestamp = time.strftime(\"%Y%m%d_%H%M%S\")\n            live_report_path = Path(tempfile.gettempdir()) / f\"skill_description_report_{skill_path.name}_{timestamp}.html\"\n        else:\n            live_report_path = Path(args.report)\n        # Open the report immediately so the user can watch\n        live_report_path.write_text(\"<html><body><h1>Starting optimization loop...</h1><meta http-equiv=\'refresh\' content=\'5\'></body></html>\")\n        webbrowser.open(str(live_report_path))\n    else:\n        live_report_path = None\n\n    # Determine output directory (create before run_loop so logs can be written)\n    if args.results_dir:\n        timestamp = time.strftime(\"%Y-%m-%d_%H%M%S\")\n        results_dir = Path(args.results_dir) / timestamp\n        results_dir.mkdir(parents=True, exist_ok=True)\n    else:\n        results_dir = None\n\n    log_dir = results_dir / \"logs\" if results_dir else None\n\n    output = run_loop(\n        eval_set=eval_set,\n        skill_path=skill_path,\n        description_override=args.description,\n        num_workers=args.num_workers,\n        timeout=args.timeout,\n        max_iterations=args.max_iterations,\n        runs_per_query=args.runs_per_query,\n        trigger_threshold=args.trigger_threshold,\n        holdout=args.holdout,\n        model=args.model,\n        verbose=args.verbose,\n        live_report_path=live_report_path,\n        log_dir=log_dir,\n    )\n\n    # Save JSON output\n    json_output = json.dumps(output, indent=2)\n    print(json_output)\n    if results_dir:\n        (results_dir / \"results.json\").write_text(json_output)\n\n    # Write final HTML report (without auto-refresh)\n    if live_report_path:\n        live_report_path.write_text(generate_html(output, auto_refresh=False, skill_name=name))\n        print(f\"\\nReport: {live_report_path}\", file=sys.stderr)\n\n    if results_dir and live_report_path:\n        (results_dir / \"report.html\").write_text(generate_html(output, auto_refresh=False, skill_name=name))\n\n    if results_dir:\n        print(f\"Results saved to: {results_dir}\", file=sys.stderr)\n\n\nif __name__ == \"__main__\":\n    main()\n','c3365f6c1927bf535f463f841c32ae81','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(1226,'enc.736372697074732f717569636b5f76616c69646174652e7079','skill_enc.736b696c6c2d63726561746f72__enc.302e302e31','#!/usr/bin/env python3\n\"\"\"\nQuick validation script for skills - minimal version\n\"\"\"\n\nimport sys\nimport os\nimport re\nimport yaml\nfrom pathlib import Path\n\ndef validate_skill(skill_path):\n    \"\"\"Basic validation of a skill\"\"\"\n    skill_path = Path(skill_path)\n\n    # Check SKILL.md exists\n    skill_md = skill_path / \'SKILL.md\'\n    if not skill_md.exists():\n        return False, \"SKILL.md not found\"\n\n    # Read and validate frontmatter\n    content = skill_md.read_text()\n    if not content.startswith(\'---\'):\n        return False, \"No YAML frontmatter found\"\n\n    # Extract frontmatter\n    match = re.match(r\'^---\\n(.*?)\\n---\', content, re.DOTALL)\n    if not match:\n        return False, \"Invalid frontmatter format\"\n\n    frontmatter_text = match.group(1)\n\n    # Parse YAML frontmatter\n    try:\n        frontmatter = yaml.safe_load(frontmatter_text)\n        if not isinstance(frontmatter, dict):\n            return False, \"Frontmatter must be a YAML dictionary\"\n    except yaml.YAMLError as e:\n        return False, f\"Invalid YAML in frontmatter: {e}\"\n\n    # Define allowed properties\n    ALLOWED_PROPERTIES = {\'name\', \'description\', \'license\', \'allowed-tools\', \'metadata\', \'compatibility\'}\n\n    # Check for unexpected properties (excluding nested keys under metadata)\n    unexpected_keys = set(frontmatter.keys()) - ALLOWED_PROPERTIES\n    if unexpected_keys:\n        return False, (\n            f\"Unexpected key(s) in SKILL.md frontmatter: {\', \'.join(sorted(unexpected_keys))}. \"\n            f\"Allowed properties are: {\', \'.join(sorted(ALLOWED_PROPERTIES))}\"\n        )\n\n    # Check required fields\n    if \'name\' not in frontmatter:\n        return False, \"Missing \'name\' in frontmatter\"\n    if \'description\' not in frontmatter:\n        return False, \"Missing \'description\' in frontmatter\"\n\n    # Extract name for validation\n    name = frontmatter.get(\'name\', \'\')\n    if not isinstance(name, str):\n        return False, f\"Name must be a string, got {type(name).__name__}\"\n    name = name.strip()\n    if name:\n        # Check naming convention (kebab-case: lowercase with hyphens)\n        if not re.match(r\'^[a-z0-9-]+$\', name):\n            return False, f\"Name \'{name}\' should be kebab-case (lowercase letters, digits, and hyphens only)\"\n        if name.startswith(\'-\') or name.endswith(\'-\') or \'--\' in name:\n            return False, f\"Name \'{name}\' cannot start/end with hyphen or contain consecutive hyphens\"\n        # Check name length (max 64 characters per spec)\n        if len(name) > 64:\n            return False, f\"Name is too long ({len(name)} characters). Maximum is 64 characters.\"\n\n    # Extract and validate description\n    description = frontmatter.get(\'description\', \'\')\n    if not isinstance(description, str):\n        return False, f\"Description must be a string, got {type(description).__name__}\"\n    description = description.strip()\n    if description:\n        # Check for angle brackets\n        if \'<\' in description or \'>\' in description:\n            return False, \"Description cannot contain angle brackets (< or >)\"\n        # Check description length (max 1024 characters per spec)\n        if len(description) > 1024:\n            return False, f\"Description is too long ({len(description)} characters). Maximum is 1024 characters.\"\n\n    # Validate compatibility field if present (optional)\n    compatibility = frontmatter.get(\'compatibility\', \'\')\n    if compatibility:\n        if not isinstance(compatibility, str):\n            return False, f\"Compatibility must be a string, got {type(compatibility).__name__}\"\n        if len(compatibility) > 500:\n            return False, f\"Compatibility is too long ({len(compatibility)} characters). Maximum is 500 characters.\"\n\n    return True, \"Skill is valid!\"\n\nif __name__ == \"__main__\":\n    if len(sys.argv) != 2:\n        print(\"Usage: python quick_validate.py <skill_directory>\")\n        sys.exit(1)\n    \n    valid, message = validate_skill(sys.argv[1])\n    print(message)\n    sys.exit(0 if valid else 1)','8247be9cfc7938843f586b6509a64641','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(1227,'enc.736372697074732f717569636b5f76616c69646174