lidation\n    name = frontmatter.get(\'name\', \'\')\n    if not isinstance(name, str):\n        return False, f\"Name must be a string, got {type(name).__name__}\"\n    name = name.strip()\n    if name:\n        # Check naming convention (kebab-case: lowercase with hyphens)\n        if not re.match(r\'^[a-z0-9-]+$\', name):\n            return False, f\"Name \'{name}\' should be kebab-case (lowercase letters, digits, and hyphens only)\"\n        if name.startswith(\'-\') or name.endswith(\'-\') or \'--\' in name:\n            return False, f\"Name \'{name}\' cannot start/end with hyphen or contain consecutive hyphens\"\n        # Check name length (max 64 characters per spec)\n        if len(name) > 64:\n            return False, f\"Name is too long ({len(name)} characters). Maximum is 64 characters.\"\n\n    # Extract and validate description\n    description = frontmatter.get(\'description\', \'\')\n    if not isinstance(description, str):\n        return False, f\"Description must be a string, got {type(description).__name__}\"\n    description = description.strip()\n    if description:\n        # Check for angle brackets\n        if \'<\' in description or \'>\' in description:\n            return False, \"Description cannot contain angle brackets (< or >)\"\n        # Check description length (max 1024 characters per spec)\n        if len(description) > 1024:\n            return False, f\"Description is too long ({len(description)} characters). Maximum is 1024 characters.\"\n\n    # Validate compatibility field if present (optional)\n    compatibility = frontmatter.get(\'compatibility\', \'\')\n    if compatibility:\n        if not isinstance(compatibility, str):\n            return False, f\"Compatibility must be a string, got {type(compatibility).__name__}\"\n        if len(compatibility) > 500:\n            return False, f\"Compatibility is too long ({len(compatibility)} characters). Maximum is 500 characters.\"\n\n    return True, \"Skill is valid!\"\n\nif __name__ == \"__main__\":\n    if len(sys.argv) != 2:\n        print(\"Usage: python quick_validate.py <skill_directory>\")\n        sys.exit(1)\n    \n    valid, message = validate_skill(sys.argv[1])\n    print(message)\n    sys.exit(0 if valid else 1)','8247be9cfc7938843f586b6509a64641','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(1228,'enc.6576616c2d7669657765722f7669657765722e68746d6c','skill_enc.736b696c6c2d63726561746f72__enc.302e302e31','<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Eval Review</title>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@500;600&family=Lora:wght@400;500&display=swap\" rel=\"stylesheet\">\n  <script src=\"https://cdn.sheetjs.com/xlsx-0.20.3/package/dist/xlsx.full.min.js\" integrity=\"sha384-EnyY0/GSHQGSxSgMwaIPzSESbqoOLSexfnSMN2AP+39Ckmn92stwABZynq1JyzdT\" crossorigin=\"anonymous\"></script>\n  <style>\n    :root {\n      --bg: #faf9f5;\n      --surface: #ffffff;\n      --border: #e8e6dc;\n      --text: #141413;\n      --text-muted: #b0aea5;\n      --accent: #d97757;\n      --accent-hover: #c4613f;\n      --green: #788c5d;\n      --green-bg: #eef2e8;\n      --red: #c44;\n      --red-bg: #fceaea;\n      --header-bg: #141413;\n      --header-text: #faf9f5;\n      --radius: 6px;\n    }\n\n    * { box-sizing: border-box; margin: 0; padding: 0; }\n\n    body {\n      font-family: \'Lora\', Georgia, serif;\n      background: var(--bg);\n      color: var(--text);\n      height: 100vh;\n      display: flex;\n      flex-direction: column;\n    }\n\n    /* ---- Header ---- */\n    .header {\n      background: var(--header-bg);\n      color: var(--header-text);\n      padding: 1rem 2rem;\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      flex-shrink: 0;\n    }\n    .header h1 {\n      font-family: \'Poppins\', sans-serif;\n      font-size: 1.25rem;\n      font-weight: 600;\n    }\n    .header .instructions {\n      font-size: 0.8rem;\n      opacity: 0.7;\n      margin-top: 0.25rem;\n    }\n    .header .progress {\n      font-size: 0.875rem;\n      opacity: 0.8;\n      text-align: right;\n    }\n\n    /* ---- Main content ---- */\n    .main {\n      flex: 1;\n      overflow-y: auto;\n      padding: 1.5rem 2rem;\n      display: flex;\n      flex-direction: column;\n      gap: 1.25rem;\n    }\n\n    /* ---- Sections ---- */\n    .section {\n      background: var(--surface);\n      border: 1px solid var(--border);\n      border-radius: var(--radius);\n      flex-shrink: 0;\n    }\n    .section-header {\n      font-family: \'Poppins\', sans-serif;\n      padding: 0.75rem 1rem;\n      font-size: 0.75rem;\n      font-weight: 500;\n      text-transform: uppercase;\n      letter-spacing: 0.05em;\n      color: var(--text-muted);\n      border-bottom: 1px solid var(--border);\n      background: var(--bg);\n    }\n    .section-body {\n      padding: 1rem;\n    }\n\n    /* ---- Config badge ---- */\n    .config-badge {\n      display: inline-block;\n      padding: 0.2rem 0.625rem;\n      border-radius: 9999px;\n      font-family: \'Poppins\', sans-serif;\n      font-size: 0.6875rem;\n      font-weight: 600;\n      text-transform: uppercase;\n      letter-spacing: 0.03em;\n      margin-left: 0.75rem;\n      vertical-align: middle;\n    }\n    .config-badge.config-primary {\n      background: rgba(33, 150, 243, 0.12);\n      color: #1976d2;\n    }\n    .config-badge.config-baseline {\n      background: rgba(255, 193, 7, 0.15);\n      color: #f57f17;\n    }\n\n    /* ---- Prompt ---- */\n    .prompt-text {\n      white-space: pre-wrap;\n      font-size: 0.9375rem;\n      line-height: 1.6;\n    }\n\n    /* ---- Outputs ---- */\n    .output-file {\n      border: 1px solid var(--border);\n      border-radius: var(--radius);\n      overflow: hidden;\n    }\n    .output-file + .output-file {\n      margin-top: 1rem;\n    }\n    .output-file-header {\n      padding: 0.5rem 0.75rem;\n      font-size: 0.8rem;\n      font-weight: 600;\n      color: var(--text-muted);\n      background: var(--bg);\n      border-bottom: 1px solid var(--border);\n      font-family: \'SF Mono\', SFMono-Regular, Consolas, \'Liberation Mono\', Menlo, monospace;\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n    }\n    .output-file-header .dl-btn {\n      font-size: 0.7rem;\n      color: var(--accent);\n      text-decoration: none;\n      cursor: pointer;\n      font-family: -apple-system, BlinkMacSystemFont, \'Segoe UI\', sans-serif;\n      font-weight: 500;\n      opacity: 0.8;\n    }\n    .output-file-header .dl-btn:hover {\n      opacity: 1;\n      text-decoration: underline;\n    }\n    .output-file-content {\n      padding: 0.75rem;\n      overflow-x: auto;\n    }\n    .output-file-content pre {\n      font-size: 0.8125rem;\n      line-height: 1.5;\n      white-space: pre-wrap;\n      word-break: break-word;\n      font-family: \'SF Mono\', SFMono-Regular, Consolas, \'Liberation Mono\', Menlo, monospace;\n    }\n    .output-file-content img {\n      max-width: 100%;\n      height: auto;\n      border-radius: 4px;\n    }\n    .output-file-content iframe {\n      width: 100%;\n      height: 600px;\n      border: none;\n    }\n    .output-file-content table {\n      border-collapse: collapse;\n      font-size: 0.8125rem;\n      width: 100%;\n    }\n    .output-file-content table td,\n    .output-file-content table th {\n      border: 1px solid var(--border);\n      padding: 0.375rem 0.5rem;\n      text-align: left;\n    }\n    .output-file-content table th {\n      background: var(--bg);\n      font-weight: 600;\n    }\n    .output-file-content .download-link {\n      display: inline-flex;\n      align-items: center;\n      gap: 0.5rem;\n      padding: 0.5rem 1rem;\n      background: var(--bg);\n      border: 1px solid var(--border);\n      border-radius: 4px;\n      color: var(--accent);\n      text-decoration: none;\n      font-size: 0.875rem;\n      cursor: pointer;\n    }\n    .output-file-content .download-link:hover {\n      background: var(--border);\n    }\n    .empty-state {\n      color: var(--text-muted);\n      font-style: italic;\n      padding: 2rem;\n      text-align: center;\n    }\n\n    /* ---- Feedback ---- */\n    .prev-feedback {\n      background: var(--bg);\n      border: 1px solid var(--border);\n      border-radius: 4px;\n      padding: 0.625rem 0.75rem;\n      margin-top: 0.75rem;\n      font-size: 0.8125rem;\n      color: var(--text-muted);\n      line-height: 1.5;\n    }\n    .prev-feedback-label {\n      font-size: 0.7rem;\n      font-weight: 600;\n      text-transform: uppercase;\n      letter-spacing: 0.04em;\n      margin-bottom: 0.25rem;\n      color: var(--text-muted);\n    }\n    .feedback-textarea {\n      width: 100%;\n      min-height: 100px;\n      padding: 0.75rem;\n      border: 1px solid var(--border);\n      border-radius: 4px;\n      font-family: inherit;\n      font-size: 0.9375rem;\n      line-height: 1.5;\n      resize: vertical;\n      color: var(--text);\n    }\n    .feedback-textarea:focus {\n      outline: none;\n      border-color: var(--accent);\n      box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.1);\n    }\n    .feedback-status {\n      font-size: 0.75rem;\n      color: var(--text-muted);\n      margin-top: 0.5rem;\n      min-height: 1.1em;\n    }\n\n    /* ---- Grades (collapsible) ---- */\n    .grades-toggle {\n      display: flex;\n      align-items: center;\n      cursor: pointer;\n      user-select: none;\n    }\n    .grades-toggle:hover {\n      color: var(--accent);\n    }\n    .grades-toggle .arrow {\n      margin-right: 0.5rem;\n      transition: transform 0.15s;\n      font-size: 0.75rem;\n    }\n    .grades-toggle .arrow.open {\n      transform: rotate(90deg);\n    }\n    .grades-content {\n      display: none;\n      margin-top: 0.75rem;\n    }\n    .grades-content.open {\n      display: block;\n    }\n    .grades-summary {\n      font-size: 0.875rem;\n      margin-bottom: 0.75rem;\n      display: flex;\n      align-items: center;\n      gap: 0.5rem;\n    }\n    .grade-badge {\n      display: inline-block;\n      padding: 0.125rem 0.5rem;\n      border-radius: 9999px;\n      font-size: 0.75rem;\n      font-weight: 600;\n    }\n    .grade-pass { background: var(--green-bg); color: var(--green); }\n    .grade-fail { background: var(--red-bg); color: var(--red); }\n    .assertion-list {\n      list-style: none;\n    }\n    .assertion-item {\n      padding: 0.625rem 0;\n      border-bottom: 1px solid var(--border);\n      font-size: 0.8125rem;\n    }\n    .assertion-item:last-child { border-bottom: none; }\n    .assertion-status {\n      font-weight: 600;\n      margin-right: 0.5rem;\n    }\n    .assertion-status.pass { color: var(--green); }\n    .assertion-status.fail { color: var(--red); }\n    .assertion-evidence {\n      color: var(--text-muted);\n      font-size: 0.75rem;\n      margin-top: 0.25rem;\n      padding-left: 1.5rem;\n    }\n\n    /* ---- View tabs ---- */\n    .view-tabs {\n      display: flex;\n      gap: 0;\n      padding: 0 2rem;\n      background: var(--bg);\n      border-bottom: 1px solid var(--border);\n      flex-shrink: 0;\n    }\n    .view-tab {\n      font-family: \'Poppins\', sans-serif;\n      padding: 0.625rem 1.25rem;\n      font-size: 0.8125rem;\n      font-weight: 500;\n      cursor: pointer;\n      border: none;\n      background: none;\n      color: var(--text-muted);\n      border-bottom: 2px solid transparent;\n      transition: all 0.15s;\n    }\n    .view-tab:hover { color: var(--text); }\n    .view-tab.active {\n      color: var(--accent);\n      border-bottom-color: var(--accent);\n    }\n    .view-panel { display: none; }\n    .view-panel.active { display: flex; flex-direction: column; flex: 1; overflow: hidden; }\n\n    /* ---- Benchmark view ---- */\n    .benchmark-view {\n      padding: 1.5rem 2rem;\n      overflow-y: auto;\n      flex: 1;\n    }\n    .benchmark-table {\n      border-collapse: collapse;\n      background: var(--surface);\n      border: 1px solid var(--border);\n      border-radius: var(--radius);\n      font-size: 0.8125rem;\n      width: 100%;\n      margin-bottom: 1.5rem;\n    }\n    .benchmark-table th, .benchmark-table td {\n      padding: 0.625rem 0.75rem;\n      text-align: left;\n      border: 1px solid var(--border);\n    }\n    .benchmark-table th {\n      font-family: \'Poppins\', sans-serif;\n      background: var(--header-bg);\n      color: var(--header-text);\n      font-weight: 500;\n      font-size: 0.75rem;\n      text-transform: uppercase;\n      letter-spacing: 0.04em;\n    }\n    .benchmark-table tr:hover { background: var(--bg); }\n    .benchmark-table tr.benchmark-row-with { background: rgba(33, 150, 243, 0.06); }\n    .benchmark-table tr.benchmark-row-without { background: rgba(255, 193, 7, 0.06); }\n    .benchmark-table tr.benchmark-row-with:hover { background: rgba(33, 150, 243, 0.12); }\n    .benchmark-table tr.benchmark-row-without:hover { background: rgba(255, 193, 7, 0.12); }\n    .benchmark-table tr.benchmark-row-avg { font-weight: 600; border-top: 2px solid var(--border); }\n    .benchmark-table tr.benchmark-row-avg.benchmark-row-with { background: rgba(33, 150, 243, 0.12); }\n    .benchmark-table tr.benchmark-row-avg.benchmark-row-without { background: rgba(255, 193, 7, 0.12); }\n    .benchmark-delta-positive { color: var(--green); font-weight: 600; }\n    .benchmark-delta-negative { color: var(--red); font-weight: 600; }\n    .benchmark-notes {\n      background: var(--surface);\n      border: 1px solid var(--border);\n      border-radius: var(--radius);\n      padding: 1rem;\n    }\n    .benchmark-notes h3 {\n      font-family: \'Poppins\', sans-serif;\n      font-size: 0.875rem;\n      margin-bottom: 0.75rem;\n    }\n    .benchmark-notes ul {\n      list-style: disc;\n      padding-left: 1.25rem;\n    }\n    .benchmark-notes li {\n      font-size: 0.8125rem;\n      line-height: 1.6;\n      margin-bottom: 0.375rem;\n    }\n    .benchmark-empty {\n      color: var(--text-muted);\n      font-style: italic;\n      text-align: center;\n      padding: 3rem;\n    }\n\n    /* ---- Navigation ---- */\n    .nav {\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      padding: 1rem 2rem;\n      border-top: 1px solid var(--border);\n      background: var(--surface);\n      flex-shrink: 0;\n    }\n    .nav-btn {\n      font-family: \'Poppins\', sans-serif;\n      padding: 0.5rem 1.25rem;\n      border: 1px solid var(--border);\n      border-radius: var(--radius);\n      background: var(--surface);\n      cursor: pointer;\n      font-size: 0.875rem;\n      font-weight: 500;\n      color: var(--text);\n      transition: all 0.15s;\n    }\n    .nav-btn:hover:not(:disabled) {\n      background: var(--bg);\n      border-color: var(--text-muted);\n    }\n    .nav-btn:disabled {\n      opacity: 0.4;\n      cursor: not-allowed;\n    }\n    .done-btn {\n      font-family: \'Poppins\', sans-serif;\n      padding: 0.5rem 1.5rem;\n      border: 1px solid var(--border);\n      border-radius: var(--radius);\n      background: var(--surface);\n      color: var(--text);\n      cursor: pointer;\n      font-size: 0.875rem;\n      font-weight: 500;\n      transition: all 0.15s;\n    }\n    .done-btn:hover {\n      background: var(--bg);\n      border-color: var(--text-muted);\n    }\n    .done-btn.ready {\n      border: none;\n      background: var(--accent);\n      color: white;\n      font-weight: 600;\n    }\n    .done-btn.ready:hover {\n      background: var(--accent-hover);\n    }\n    /* ---- Done overlay ---- */\n    .done-overlay {\n      display: none;\n      position: fixed;\n      inset: 0;\n      background: rgba(0, 0, 0, 0.5);\n      z-index: 100;\n      justify-content: center;\n      align-items: center;\n    }\n    .done-overlay.visible {\n      display: flex;\n    }\n    .done-card {\n      background: var(--surface);\n      border-radius: 12px;\n      padding: 2rem 3rem;\n      text-align: center;\n      box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);\n      max-width: 500px;\n    }\n    .done-card h2 {\n      font-size: 1.5rem;\n      margin-bottom: 0.5rem;\n    }\n    .done-card p {\n      color: var(--text-muted);\n      margin-bottom: 1.5rem;\n      line-height: 1.5;\n    }\n    .done-card .btn-row {\n      display: flex;\n      gap: 0.5rem;\n      justify-content: center;\n    }\n    .done-card button {\n      padding: 0.5rem 1.25rem;\n      border: 1px solid var(--border);\n      border-radius: var(--radius);\n      background: var(--surface);\n      cursor: pointer;\n      font-size: 0.875rem;\n    }\n    .done-card button:hover {\n      background: var(--bg);\n    }\n    /* ---- Toast ---- */\n    .toast {\n      position: fixed;\n      bottom: 5rem;\n      left: 50%;\n      transform: translateX(-50%);\n      background: var(--header-bg);\n      color: var(--header-text);\n      padding: 0.625rem 1.25rem;\n      border-radius: var(--radius);\n      font-size: 0.875rem;\n      opacity: 0;\n      transition: opacity 0.3s;\n      pointer-events: none;\n      z-index: 200;\n    }\n    .toast.visible {\n      opacity: 1;\n    }\n  </style>\n</head>\n<body>\n  <div id=\"app\" style=\"height:100vh; display:flex; flex-direction:column;\">\n    <div class=\"header\">\n      <div>\n        <h1>Eval Review: <span id=\"skill-name\"></span></h1>\n        <div class=\"instructions\">Review each output and leave feedback below. Navigate with arrow keys or buttons. When done, copy feedback and paste into Claude Code.</div>\n      </div>\n      <div class=\"progress\" id=\"progress\"></div>\n    </div>\n\n    <!-- View tabs (only shown when benchmark data exists) -->\n    <div class=\"view-tabs\" id=\"view-tabs\" style=\"display:none;\">\n      <button class=\"view-tab active\" onclick=\"switchView(\'outputs\')\">Outputs</button>\n      <button class=\"view-tab\" onclick=\"switchView(\'benchmark\')\">Benchmark</button>\n    </div>\n\n    <!-- Outputs panel (qualitative review) -->\n    <div class=\"view-panel active\" id=\"panel-outputs\">\n    <div class=\"main\">\n      <!-- Prompt -->\n      <div class=\"section\">\n        <div class=\"section-header\">Prompt <span class=\"config-badge\" id=\"config-badge\" style=\"display:none;\"></span></div>\n        <div class=\"section-body\">\n          <div class=\"prompt-text\" id=\"prompt-text\"></div>\n        </div>\n      </div>\n\n      <!-- Outputs -->\n      <div class=\"section\">\n        <div class=\"section-header\">Output</div>\n        <div class=\"section-body\" id=\"outputs-body\">\n          <div class=\"empty-state\">No output files found</div>\n        </div>\n      </div>\n\n      <!-- Previous Output (collapsible) -->\n      <div class=\"section\" id=\"prev-outputs-section\" style=\"display:none;\">\n        <div class=\"section-header\">\n          <div class=\"grades-toggle\" onclick=\"togglePrevOutputs()\">\n            <span class=\"arrow\" id=\"prev-outputs-arrow\">&#9654;</span>\n            Previous Output\n          </div>\n        </div>\n        <div class=\"grades-content\" id=\"prev-outputs-content\"></div>\n      </div>\n\n      <!-- Grades (collapsible) -->\n      <div class=\"section\" id=\"grades-section\" style=\"display:none;\">\n        <div class=\"section-header\">\n          <div class=\"grades-toggle\" onclick=\"toggleGrades()\">\n            <span class=\"arrow\" id=\"grades-arrow\">&#9654;</span>\n            Formal Grades\n          </div>\n        </div>\n        <div class=\"grades-content\" id=\"grades-content\"></div>\n      </div>\n\n      <!-- Feedback -->\n      <div class=\"section\">\n        <div class=\"section-header\">Your Feedback</div>\n        <div class=\"section-body\">\n          <textarea\n            class=\"feedback-textarea\"\n            id=\"feedback\"\n            placeholder=\"What do you think of this output? Any issues, suggestions, or things that look great?\"\n          ></textarea>\n          <div class=\"feedback-status\" id=\"feedback-status\"></div>\n          <div class=\"prev-feedback\" id=\"prev-feedback\" style=\"display:none;\">\n            <div class=\"prev-feedback-label\">Previous feedback</div>\n            <div id=\"prev-feedback-text\"></div>\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"nav\" id=\"outputs-nav\">\n      <button class=\"nav-btn\" id=\"prev-btn\" onclick=\"navigate(-1)\">&#8592; Previous</button>\n      <button class=\"done-btn\" id=\"done-btn\" onclick=\"showDoneDialog()\">Submit All Reviews</button>\n      <button class=\"nav-btn\" id=\"next-btn\" onclick=\"navigate(1)\">Next &#8594;</button>\n    </div>\n    </div><!-- end panel-outputs -->\n\n    <!-- Benchmark panel (quantitative stats) -->\n    <div class=\"view-panel\" id=\"panel-benchmark\">\n      <div class=\"benchmark-view\" id=\"benchmark-content\">\n        <div class=\"benchmark-empty\">No benchmark data available. Run a benchmark to see quantitative results here.</div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Done overlay -->\n  <div class=\"done-overlay\" id=\"done-overlay\">\n    <div class=\"done-card\">\n      <h2>Review Complete</h2>\n      <p>Your feedback has been saved. Go back to your Claude Code session and tell Claude you\'re done reviewing.</p>\n      <div class=\"btn-row\">\n        <button onclick=\"closeDoneDialog()\">OK</button>\n      </div>\n    </div>\n  </div>\n\n  <!-- Toast -->\n  <div class=\"toast\" id=\"toast\"></div>\n\n  <script>\n    // ---- Embedded data (injected by generate_review.py) ----\n    /*__EMBEDDED_DATA__*/\n\n    // ---- State ----\n    let feedbackMap = {};  // run_id -> feedback text\n    let currentIndex = 0;\n    let visitedRuns = new Set();\n\n    // ---- Init ----\n    async function init() {\n      // Load saved feedback from server — but only if this isn\'t a fresh\n      // iteration (indicated by previous_feedback being present). When\n      // previous feedback exists, the feedback.json on disk is stale from\n      // the prior iteration and should not pre-fill the textareas.\n      const hasPrevious = Object.keys(EMBEDDED_DATA.previous_feedback || {}).length > 0\n        || Object.keys(EMBEDDED_DATA.previous_outputs || {}).length > 0;\n      if (!hasPrevious) {\n        try {\n          const resp = await fetch(\"/api/feedback\");\n          const data = await resp.json();\n          if (data.reviews) {\n            for (const r of data.reviews) feedbackMap[r.run_id] = r.feedback;\n          }\n        } catch { /* first run, no feedback yet */ }\n      }\n\n      document.getElementById(\"skill-name\").textContent = EMBEDDED_DATA.skill_name;\n      showRun(0);\n\n      // Wire up feedback auto-save\n      const textarea = document.getElementById(\"feedback\");\n      let saveTimeout = null;\n      textarea.addEventListener(\"input\", () => {\n        clearTimeout(saveTimeout);\n        document.getElementById(\"feedback-status\").textContent = \"\";\n        saveTimeout = setTimeout(() => saveCurrentFeedback(), 800);\n      });\n    }\n\n    // ---- Navigation ----\n    function navigate(delta) {\n      const newIndex = currentIndex + delta;\n      if (newIndex >= 0 && newIndex < EMBEDDED_DATA.runs.length) {\n        saveCurrentFeedback();\n        showRun(newIndex);\n      }\n    }\n\n    function updateNavButtons() {\n      document.getElementById(\"prev-btn\").disabled = currentIndex === 0;\n      document.getElementById(\"next-btn\").disabled =\n        currentIndex === EMBEDDED_DATA.runs.length - 1;\n    }\n\n    // ---- Show a run ----\n    function showRun(index) {\n      currentIndex = index;\n      const run = EMBEDDED_DATA.runs[index];\n\n      // Progress\n      document.getElementById(\"progress\").textContent =\n        `${index + 1} of ${EMBEDDED_DATA.runs.length}`;\n\n      // Prompt\n      document.getElementById(\"prompt-text\").textContent = run.prompt;\n\n      // Config badge\n      const badge = document.getElementById(\"config-badge\");\n      const configMatch = run.id.match(/(with_skill|without_skill|new_skill|old_skill)/);\n      if (configMatch) {\n        const config = configMatch[1];\n        const isBaseline = config === \"without_skill\" || config === \"old_skill\";\n        badge.textContent = config.replace(/_/g, \" \");\n        badge.className = \"config-badge \" + (isBaseline ? \"config-baseline\" : \"config-primary\");\n        badge.style.display = \"inline-block\";\n      } else {\n        badge.style.display = \"none\";\n      }\n\n      // Outputs\n      renderOutputs(run);\n\n      // Previous outputs\n      renderPrevOutputs(run);\n\n      // Grades\n      renderGrades(run);\n\n      // Previous feedback\n      const prevFb = (EMBEDDED_DATA.previous_feedback || {})[run.id];\n      const prevEl = document.getElementById(\"prev-feedback\");\n      if (prevFb) {\n        document.getElementById(\"prev-feedback-text\").textContent = prevFb;\n        prevEl.style.display = \"block\";\n      } else {\n        prevEl.style.display = \"none\";\n      }\n\n      // Feedback\n      document.getElementById(\"feedback\").value = feedbackMap[run.id] || \"\";\n      document.getElementById(\"feedback-status\").textContent = \"\";\n\n      updateNavButtons();\n\n      // Track visited runs and promote done button when all visited\n      visitedRuns.add(index);\n      const doneBtn = document.getElementById(\"done-btn\");\n      if (visitedRuns.size >= EMBEDDED_DATA.runs.length) {\n        doneBtn.classList.add(\"ready\");\n      }\n\n      // Scroll main content to top\n      document.querySelector(\".main\").scrollTop = 0;\n    }\n\n    // ---- Render outputs ----\n    function renderOutputs(run) {\n      const container = document.getElementById(\"outputs-body\");\n      container.innerHTML = \"\";\n\n      const outputs = run.outputs || [];\n      if (outputs.length === 0) {\n        container.innerHTML = \'<div class=\"empty-state\">No output files</div>\';\n        return;\n      }\n\n      for (const file of outputs) {\n        const fileDiv = document.createElement(\"div\");\n        fileDiv.className = \"output-file\";\n\n        // Always show file header with download link\n        const header = document.createElement(\"div\");\n        header.className = \"output-file-header\";\n        const nameSpan = document.createElement(\"span\");\n        nameSpan.textContent = file.name;\n        header.appendChild(nameSpan);\n        const dlBtn = document.createElement(\"a\");\n        dlBtn.className = \"dl-btn\";\n        dlBtn.textContent = \"Download\";\n        dlBtn.download = file.name;\n        dlBtn.href = getDownloadUri(file);\n        header.appendChild(dlBtn);\n        fileDiv.appendChild(header);\n\n        const content = document.createElement(\"div\");\n        content.className = \"output-file-content\";\n\n        if (file.type === \"text\") {\n          const pre = document.createElement(\"pre\");\n          pre.textContent = file.content;\n          content.appendChild(pre);\n        } else if (file.type === \"image\") {\n          const img = document.createElement(\"img\");\n          img.src = file.data_uri;\n          img.alt = file.name;\n          content.appendChild(img);\n        } else if (file.type === \"pdf\") {\n          const iframe = document.createElement(\"iframe\");\n          iframe.src = file.data_uri;\n          content.appendChild(iframe);\n        } else if (file.type === \"xlsx\") {\n          renderXlsx(content, file.data_b64);\n        } else if (file.type === \"binary\") {\n          const a = document.createElement(\"a\");\n          a.className = \"download-link\";\n          a.href = file.data_uri;\n          a.download = file.name;\n          a.textContent = \"Download \" + file.name;\n          content.appendChild(a);\n        } else if (file.type === \"error\") {\n          const pre = document.createElement(\"pre\");\n          pre.textContent = file.content;\n          pre.style.color = \"var(--red)\";\n          content.appendChild(pre);\n        }\n\n        fileDiv.appendChild(content);\n        container.appendChild(fileDiv);\n      }\n    }\n\n    // ---- XLSX rendering via SheetJS ----\n    function renderXlsx(container, b64Data) {\n      try {\n        const raw = Uint8Array.from(atob(b64Data), c => c.charCodeAt(0));\n        const wb = XLSX.read(raw, { type: \"array\" });\n\n        for (let i = 0; i < wb.SheetNames.length; i++) {\n          const sheetName = wb.SheetNames[i];\n          const ws = wb.Sheets[sheetName];\n\n          if (wb.SheetNames.length > 1) {\n            const sheetLabel = document.createElement(\"div\");\n            sheetLabel.style.cssText =\n              \"font-weight:600; font-size:0.8rem; color:#b0aea5; margin-top:0.5rem; margin-bottom:0.25rem;\";\n            sheetLabel.textContent = \"Sheet: \" + sheetName;\n            container.appendChild(sheetLabel);\n          }\n\n          const htmlStr = XLSX.utils.sheet_to_html(ws, { editable: false });\n          const wrapper = document.createElement(\"div\");\n          wrapper.innerHTML = htmlStr;\n          container.appendChild(wrapper);\n        }\n      } catch (err) {\n        container.textContent = \"Error rendering spreadsheet: \" + err.message;\n      }\n    }\n\n    // ---- Grades ----\n    function renderGrades(run) {\n      const section = document.getElementById(\"grades-section\");\n      const content = document.getElementById(\"grades-content\");\n\n      if (!run.grading) {\n        section.style.display = \"none\";\n        return;\n      }\n\n      const grading = run.grading;\n      section.style.display = \"block\";\n      // Reset to collapsed\n      content.classList.remove(\"open\");\n      document.getElementById(\"grades-arrow\").classList.remove(\"open\");\n\n      const summary = grading.summary || {};\n      const expectations = grading.expectations || [];\n\n      let html = \'<div style=\"padding: 1rem;\">\';\n\n      // Summary line\n      const passRate = summary.pass_rate != null\n        ? Math.round(summary.pass_rate * 100) + \"%\"\n        : \"?\";\n      const badgeClass = summary.pass_rate >= 0.8 ? \"grade-pass\" : summary.pass_rate >= 0.5 ? \"\" : \"grade-fail\";\n      html += \'<div class=\"grades-summary\">\';\n      html += \'<span class=\"grade-badge \' + badgeClass + \'\">\' + passRate + \'</span>\';\n      html += \'<span>\' + (summary.passed || 0) + \' passed, \' + (summary.failed || 0) + \' failed of \' + (summary.total || 0) + \'</span>\';\n      html += \'</div>\';\n\n      // Assertions list\n      html += \'<ul class=\"assertion-list\">\';\n      for (const exp of expectations) {\n        const statusClass = exp.passed ? \"pass\" : \"fail\";\n        const statusIcon = exp.passed ? \"\\u2713\" : \"\\u2717\";\n        html += \'<li class=\"assertion-item\">\';\n        html += \'<span class=\"assertion-status \' + statusClass + \'\">\' + statusIcon + \'</span>\';\n        html += \'<span>\' + escapeHtml(exp.text) + \'</span>\';\n        if (exp.evidence) {\n          html += \'<div class=\"assertion-evidence\">\' + escapeHtml(exp.evidence) + \'</div>\';\n        }\n        html += \'</li>\';\n      }\n      html += \'</ul>\';\n\n      html += \'</div>\';\n      content.innerHTML = html;\n    }\n\n    function toggleGrades() {\n      const content = document.getElementById(\"grades-content\");\n      const arrow = document.getElementById(\"grades-arrow\");\n      content.classList.toggle(\"open\");\n      arrow.classList.toggle(\"open\");\n    }\n\n    // ---- Previous outputs (collapsible) ----\n    function renderPrevOutputs(run) {\n      const section = document.getElementById(\"prev-outputs-section\");\n      const content = document.getElementById(\"prev-outputs-content\");\n      const prevOutputs = (EMBEDDED_DATA.previous_outputs || {})[run.id];\n\n      if (!prevOutputs || prevOutputs.length === 0) {\n        section.style.display = \"none\";\n        return;\n      }\n\n      section.style.display = \"block\";\n      // Reset to collapsed\n      content.classList.remove(\"open\");\n      document.getElementById(\"prev-outputs-arrow\").classList.remove(\"open\");\n\n      // Render the files into the content area\n      content.innerHTML = \"\";\n      const wrapper = document.createElement(\"div\");\n      wrapper.style.padding = \"1rem\";\n\n      for (const file of prevOutputs) {\n        const fileDiv = document.createElement(\"div\");\n        fileDiv.className = \"output-file\";\n\n        const header = document.createElement(\"div\");\n        header.className = \"output-file-header\";\n        const nameSpan = document.createElement(\"span\");\n        nameSpan.textContent = file.name;\n        header.appendChild(nameSpan);\n        const dlBtn = document.createElement(\"a\");\n        dlBtn.className = \"dl-btn\";\n        dlBtn.textContent = \"Download\";\n        dlBtn.download = file.name;\n        dlBtn.href = getDownloadUri(file);\n        header.appendChild(dlBtn);\n        fileDiv.appendChild(header);\n\n        const fc = document.createElement(\"div\");\n        fc.className = \"output-file-content\";\n\n        if (file.type === \"text\") {\n          const pre = document.createElement(\"pre\");\n          pre.textContent = file.content;\n          fc.appendChild(pre);\n        } else if (file.type === \"image\") {\n          const img = document.createElement(\"img\");\n          img.src = file.data_uri;\n          img.alt = file.name;\n          fc.appendChild(img);\n        } else if (file.type === \"pdf\") {\n          const iframe = document.createElement(\"iframe\");\n          iframe.src = file.data_uri;\n          fc.appendChild(iframe);\n        } else if (file.type === \"xlsx\") {\n          renderXlsx(fc, file.data_b64);\n        } else if (file.type === \"binary\") {\n          const a = document.createElement(\"a\");\n          a.className = \"download-link\";\n          a.href = file.data_uri;\n          a.download = file.name;\n          a.textContent = \"Download \" + file.name;\n          fc.appendChild(a);\n        }\n\n        fileDiv.appendChild(fc);\n        wrapper.appendChild(fileDiv);\n      }\n\n      content.appendChild(wrapper);\n    }\n\n    function togglePrevOutputs() {\n      const content = document.getElementById(\"prev-outputs-content\");\n      const arrow = document.getElementById(\"prev-outputs-arrow\");\n      content.classList.toggle(\"open\");\n      arrow.classList.toggle(\"open\");\n    }\n\n    // ---- Feedback (saved to server -> feedback.json) ----\n    function saveCurrentFeedback() {\n      const run = EMBEDDED_DATA.runs[currentIndex];\n      const text = document.getElementById(\"feedback\").value;\n\n      if (text.trim() === \"\") {\n        delete feedbackMap[run.id];\n      } else {\n        feedbackMap[run.id] = text;\n      }\n\n      // Build reviews array from map\n      const reviews = [];\n      for (const [run_id, feedback] of Object.entries(feedbackMap)) {\n        if (feedback.trim()) {\n          reviews.push({ run_id, feedback, timestamp: new Date().toISOString() });\n        }\n      }\n\n      fetch(\"/api/feedback\", {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/json\" },\n        body: JSON.stringify({ reviews, status: \"in_progress\" }),\n      }).then(() => {\n        document.getElementById(\"feedback-status\").textContent = \"Saved\";\n      }).catch(() => {\n        // Static mode or server unavailable — no-op on auto-save,\n        // feedback will be downloaded on final submit\n        document.getElementById(\"feedback-status\").textContent = \"Will download on submit\";\n      });\n    }\n\n    // ---- Done ----\n    function showDoneDialog() {\n      // Save current textarea to feedbackMap (but don\'t POST yet)\n      const run = EMBEDDED_DATA.runs[currentIndex];\n      const text = document.getElementById(\"feedback\").value;\n      if (text.trim() === \"\") {\n        delete feedbackMap[run.id];\n      } else {\n        feedbackMap[run.id] = text;\n      }\n\n      // POST once with status: complete — include ALL runs so the model\n      // can distinguish \"no feedback\" (looks good) from \"not reviewed\"\n      const reviews = [];\n      const ts = new Date().toISOString();\n      for (const r of EMBEDDED_DATA.runs) {\n        reviews.push({ run_id: r.id, feedback: feedbackMap[r.id] || \"\", timestamp: ts });\n      }\n      const payload = JSON.stringify({ reviews, status: \"complete\" }, null, 2);\n      fetch(\"/api/feedback\", {\n        method: \"POST\",\n        headers: { \"Content-Type\": \"application/json\" },\n        body: payload,\n      }).then(() => {\n        document.getElementById(\"done-overlay\").classList.add(\"visible\");\n      }).catch(() => {\n        // Server not available (static mode) — download as file\n        const blob = new Blob([payload], { type: \"application/json\" });\n        const url = URL.createObjectURL(blob);\n        const a = document.createElement(\"a\");\n        a.href = url;\n        a.download = \"feedback.json\";\n        a.click();\n        URL.revokeObjectURL(url);\n        document.getElementById(\"done-overlay\").classList.add(\"visible\");\n      });\n    }\n\n    function closeDoneDialog() {\n      // Reset status back to in_progress\n      saveCurrentFeedback();\n      document.getElementById(\"done-overlay\").classList.remove(\"visible\");\n    }\n\n    // ---- Toast ----\n    function showToast(message) {\n      const toast = document.getElementById(\"toast\");\n      toast.textContent = message;\n      toast.classList.add(\"visible\");\n      setTimeout(() => toast.classList.remove(\"visible\"), 2000);\n    }\n\n    // ---- Keyboard nav ----\n    document.addEventListener(\"keydown\", (e) => {\n      // Don\'t capture when typing in textarea\n      if (e.target.tagName === \"TEXTAREA\") return;\n\n      if (e.key === \"ArrowLeft\" || e.key === \"ArrowUp\") {\n        e.preventDefault();\n        navigate(-1);\n      } else if (e.key === \"ArrowRight\" || e.key === \"ArrowDown\") {\n        e.preventDefault();\n        navigate(1);\n      }\n    });\n\n    // ---- Util ----\n    function getDownloadUri(file) {\n      if (file.data_uri) return file.data_uri;\n      if (file.data_b64) return \"data:application/octet-stream;base64,\" + file.data_b64;\n      if (file.type === \"text\") return \"data:text/plain;charset=utf-8,\" + encodeURIComponent(file.content);\n      return \"#\";\n    }\n\n    function escapeHtml(text) {\n      const div = document.createElement(\"div\");\n      div.textContent = text;\n      return div.innerHTML;\n    }\n\n    // ---- View switching ----\n    function switchView(view) {\n      document.querySelectorAll(\".view-tab\").forEach(t => t.classList.remove(\"active\"));\n      document.querySelectorAll(\".view-panel\").forEach(p => p.classList.remove(\"active\"));\n      document.querySelector(`[onclick=\"switchView(\'${view}\')\"]`).classList.add(\"active\");\n      document.getElementById(\"panel-\" + view).classList.add(\"active\");\n    }\n\n    // ---- Benchmark rendering ----\n    function renderBenchmark() {\n      const data = EMBEDDED_DATA.benchmark;\n      if (!data) return;\n\n      // Show the tabs\n      document.getElementById(\"view-tabs\").style.display = \"flex\";\n\n      const container = document.getElementById(\"benchmark-content\");\n      const summary = data.run_summary || {};\n      const metadata = data.metadata || {};\n      const notes = data.notes || [];\n\n      let html = \"\";\n\n      // Header\n      html += \"<h2 style=\'font-family: Poppins, sans-serif; margin-bottom: 0.5rem;\'>Benchmark Results</h2>\";\n      html += \"<p style=\'color: var(--text-muted); font-size: 0.875rem; margin-bottom: 1.25rem;\'>\";\n      if (metadata.skill_name) html += \"<strong>\" + escapeHtml(metadata.skill_name) + \"</strong> &mdash; \";\n      if (metadata.timestamp) html += metadata.timestamp + \" &mdash; \";\n      if (metadata.evals_run) html += \"Evals: \" + metadata.evals_run.join(\", \") + \" &mdash; \";\n      html += (metadata.runs_per_configuration || \"?\") + \" runs per configuration\";\n      html += \"</p>\";\n\n      // Summary table\n      html += \'<table class=\"benchmark-table\">\';\n\n      function fmtStat(stat, pct) {\n        if (!stat) return \"—\";\n        const suffix = pct ? \"%\" : \"\";\n        const m = pct ? (stat.mean * 100).toFixed(0) : stat.mean.toFixed(1);\n        const s = pct ? (stat.stddev * 100).toFixed(0) : stat.stddev.toFixed(1);\n        return m + suffix + \" ± \" + s + suffix;\n      }\n\n      function deltaClass(val) {\n        if (!val) return \"\";\n        const n = parseFloat(val);\n        if (n > 0) return \"benchmark-delta-positive\";\n        if (n < 0) return \"benchmark-delta-negative\";\n        return \"\";\n      }\n\n      // Discover config names dynamically (everything except \"delta\")\n      const configs = Object.keys(summary).filter(k => k !== \"delta\");\n      const configA = configs[0] || \"config_a\";\n      const configB = configs[1] || \"config_b\";\n      const labelA = configA.replace(/_/g, \" \").replace(/\\b\\w/g, c => c.toUpperCase());\n      const labelB = configB.replace(/_/g, \" \").replace(/\\b\\w/g, c => c.toUpperCase());\n      const a = summary[configA] || {};\n      const b = summary[configB] || {};\n      const delta = summary.delta || {};\n\n      html += \"<thead><tr><th>Metric</th><th>\" + escapeHtml(labelA) + \"</th><th>\" + escapeHtml(labelB) + \"</th><th>Delta</th></tr></thead>\";\n      html += \"<tbody>\";\n\n      html += \"<tr><td><strong>Pass Rate</strong></td>\";\n      html += \"<td>\" + fmtStat(a.pass_rate, true) + \"</td>\";\n      html += \"<td>\" + fmtStat(b.pass_rate, true) + \"</td>\";\n      html += \'<td class=\"\' + deltaClass(delta.pass_rate) + \'\">\' + (delta.pass_rate || \"—\") + \"</td></tr>\";\n\n      // Time (only show row if data exists)\n      if (a.time_seconds || b.time_seconds) {\n        html += \"<tr><td><strong>Time (s)</strong></td>\";\n        html += \"<td>\" + fmtStat(a.time_seconds, false) + \"</td>\";\n        html += \"<td>\" + fmtStat(b.time_seconds, false) + \"</td>\";\n        html += \'<td class=\"\' + deltaClass(delta.time_seconds) + \'\">\' + (delta.time_seconds ? delta.time_seconds + \"s\" : \"—\") + \"</td></tr>\";\n      }\n\n      // Tokens (only show row if data exists)\n      if (a.tokens || b.tokens) {\n        html += \"<tr><td><strong>Tokens</strong></td>\";\n        html += \"<td>\" + fmtStat(a.tokens, false) + \"</td>\";\n        html += \"<td>\" + fmtStat(b.tokens, false) + \"</td>\";\n        html += \'<td class=\"\' + deltaClass(delta.tokens) + \'\">\' + (delta.tokens || \"—\") + \"</td></tr>\";\n      }\n\n      html += \"</tbody></table>\";\n\n      // Per-eval breakdown (if runs data available)\n      const runs = data.runs || [];\n      if (runs.length > 0) {\n        const evalIds = [...new Set(runs.map(r => r.eval_id))].sort((a, b) => a - b);\n\n        html += \"<h3 style=\'font-family: Poppins, sans-serif; margin-bottom: 0.75rem;\'>Per-Eval Breakdown</h3>\";\n\n        const hasTime = runs.some(r => r.result && r.result.time_seconds != null);\n        const hasErrors = runs.some(r => r.result && r.result.errors > 0);\n\n        for (const evalId of evalIds) {\n          const evalRuns = runs.filter(r => r.eval_id === evalId);\n          const evalName = evalRuns[0] && evalRuns[0].eval_name ? evalRuns[0].eval_name : \"Eval \" + evalId;\n\n          html += \"<h4 style=\'font-family: Poppins, sans-serif; margin: 1rem 0 0.5rem; color: var(--text);\'>\" + escapeHtml(evalName) + \"</h4>\";\n          html += \'<table class=\"benchmark-table\">\';\n          html += \"<thead><tr><th>Config</th><th>Run</th><th>Pass Rate</th>\";\n          if (hasTime) html += \"<th>Time (s)</th>\";\n          if (hasErrors) html += \"<th>Crashes During Execution</th>\";\n          html += \"</tr></thead>\";\n          html += \"<tbody>\";\n\n          // Group by config and render with average rows\n          const configGroups = [...new Set(evalRuns.map(r => r.configuration))];\n          for (let ci = 0; ci < configGroups.length; ci++) {\n            const config = configGroups[ci];\n            const configRuns = evalRuns.filter(r => r.configuration === config);\n            if (configRuns.length === 0) continue;\n\n            const rowClass = ci === 0 ? \"benchmark-row-with\" : \"benchmark-row-without\";\n            const configLabel = config.replace(/_/g, \" \").replace(/\\b\\w/g, c => c.toUpperCase());\n\n            for (const run of configRuns) {\n              const r = run.result || {};\n              const prClass = r.pass_rate >= 0.8 ? \"benchmark-delta-positive\" : r.pass_rate < 0.5 ? \"benchmark-delta-negative\" : \"\";\n              html += \'<tr class=\"\' + rowClass + \'\">\';\n              html += \"<td>\" + configLabel + \"</td>\";\n              html += \"<td>\" + run.run_number + \"</td>\";\n              html += \'<td class=\"\' + prClass + \'\">\' + ((r.pass_rate || 0) * 100).toFixed(0) + \"% (\" + (r.passed || 0) + \"/\" + (r.total || 0) + \")</td>\";\n              if (hasTime) html += \"<td>\" + (r.time_seconds != null ? r.time_seconds.toFixed(1) : \"—\") + \"</td>\";\n              if (hasErrors) html += \"<td>\" + (r.errors || 0) + \"</td>\";\n              html += \"</tr>\";\n            }\n\n            // Average row\n            const rates = configRuns.map(r => (r.result || {}).pass_rate || 0);\n            const avgRate = rates.reduce((a, b) => a + b, 0) / rates.length;\n            const avgPrClass = avgRate >= 0.8 ? \"benchmark-delta-positive\" : avgRate < 0.5 ? \"benchmark-delta-negative\" : \"\";\n            html += \'<tr class=\"benchmark-row-avg \' + rowClass + \'\">\';\n            html += \"<td>\" + configLabel + \"</td>\";\n            html += \"<td>Avg</td>\";\n            html += \'<td class=\"\' + avgPrClass + \'\">\' + (avgRate * 100).toFixed(0) + \"%</td>\";\n            if (hasTime) {\n              const times = configRuns.map(r => (r.result || {}).time_seconds).filter(t => t != null);\n              html += \"<td>\" + (times.length ? (times.reduce((a, b) => a + b, 0) / times.length).toFixed(1) : \"—\") + \"</td>\";\n            }\n            if (hasErrors) html += \"<td></td>\";\n            html += \"</tr>\";\n          }\n          html += \"</tbody></table>\";\n\n          // Per-assertion detail for this eval\n          const runsWithExpectations = {};\n          for (const config of configGroups) {\n            runsWithExpectations[config] = evalRuns.filter(r => r.configuration === config && r.expectations && r.expectations.length > 0);\n          }\n          const hasAnyExpectations = Object.values(runsWithExpectations).some(runs => runs.length > 0);\n          if (hasAnyExpectations) {\n            // Collect all unique assertion texts across all configs\n            const allAssertions = [];\n            const seen = new Set();\n            for (const config of configGroups) {\n              for (const run of runsWithExpectations[config]) {\n                for (const exp of (run.expectations || [])) {\n                  if (!seen.has(exp.text)) {\n                    seen.add(exp.text);\n                    allAssertions.push(exp.text);\n                  }\n                }\n              }\n            }\n\n            html += \'<table class=\"benchmark-table\" style=\"margin-top: 0.5rem;\">\';\n            html += \"<thead><tr><th>Assertion</th>\";\n            for (const config of configGroups) {\n              const label = config.replace(/_/g, \" \").replace(/\\b\\w/g, c => c.toUpperCase());\n              html += \"<th>\" + escapeHtml(label) + \"</th>\";\n            }\n            html += \"</tr></thead><tbody>\";\n\n            for (const assertionText of allAssertions) {\n              html += \"<tr><td>\" + escapeHtml(assertionText) + \"</td>\";\n\n              for (const config of configGroups) {\n                html += \"<td>\";\n                for (const run of runsWithExpectations[config]) {\n                  const exp = (run.expectations || []).find(e => e.text === assertionText);\n                  if (exp) {\n                    const cls = exp.passed ? \"benchmark-delta-positive\" : \"benchmark-delta-negative\";\n                    const icon = exp.passed ? \"\\u2713\" : \"\\u2717\";\n                    html += \'<span class=\"\' + cls + \'\" title=\"Run \' + run.run_number + \': \' + escapeHtml(exp.evidence || \"\") + \'\">\' + icon + \"</span> \";\n                  } else {\n                    html += \"— \";\n                  }\n                }\n                html += \"</td>\";\n              }\n              html += \"</tr>\";\n            }\n            html += \"</tbody></table>\";\n          }\n        }\n      }\n\n      // Notes\n      if (notes.length > 0) {\n        html += \'<div class=\"benchmark-notes\">\';\n        html += \"<h3>Analysis Notes</h3>\";\n        html += \"<ul>\";\n        for (const note of notes) {\n          html += \"<li>\" + escapeHtml(note) + \"</li>\";\n        }\n        html += \"</ul></div>\";\n      }\n\n      container.innerHTML = html;\n    }\n\n    // ---- Start ----\n    init();\n    renderBenchmark();\n  </script>\n</body>\n</html>\n','bef0b26fd04ee3a25344b7ae361a5bd1','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(1229,'enc.736372697074732f7574696c732e7079','skill_enc.736b696c6c2d63726561746f72__enc.302e302e31','\"\"\"Shared utilities for skill-creator scripts.\"\"\"\n\nfrom pathlib import Path\n\n\n\ndef parse_skill_md(skill_path: Path) -> tuple[str, str, str]:\n    \"\"\"Parse a SKILL.md file, returning (name, description, full_content).\"\"\"\n    content = (skill_path / \"SKILL.md\").read_text()\n    lines = content.split(\"\\n\")\n\n    if lines[0].strip() != \"---\":\n        raise ValueError(\"SKILL.md missing frontmatter (no opening ---)\")\n\n    end_idx = None\n    for i, line in enumerate(lines[1:], start=1):\n        if line.strip() == \"---\":\n            end_idx = i\n            break\n\n    if end_idx is None:\n        raise ValueError(\"SKILL.md missing frontmatter (no closing ---)\")\n\n    name = \"\"\n    description = \"\"\n    frontmatter_lines = lines[1:end_idx]\n    i = 0\n    while i < len(frontmatter_lines):\n        line = frontmatter_lines[i]\n        if line.startswith(\"name:\"):\n            name = line[len(\"name:\"):].strip().strip(\'\"\').strip(\"\'\")\n        elif line.startswith(\"description:\"):\n            value = line[len(\"description:\"):].strip()\n            # Handle YAML multiline indicators (>, |, >-, |-)\n            if value in (\">\", \"|\", \">-\", \"|-\"):\n                continuation_lines: list[str] = []\n                i += 1\n                while i < len(frontmatter_lines) and (frontmatter_lines[i].startswith(\"  \") or frontmatter_lines[i].startswith(\"\\t\")):\n                    continuation_lines.append(frontmatter_lines[i].strip())\n                    i += 1\n                description = \" \".join(continuation_lines)\n                continue\n            else:\n                description = value.strip(\'\"\').strip(\"\'\")\n        i += 1\n\n    return name, description, content\n','6cf213a77cbadc39febbaf9ee57fac10','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(1230,'SKILL.md','skill_enc.736c61636b2d6769662d63726561746f72__enc.302e302e31','---\nversion: 0.0.1\nname: slack-gif-creator\ndescription: Knowledge and utilities for creating animated GIFs optimized for Slack. Provides constraints, validation tools, and animation concepts. Use when users request animated GIFs for Slack like \"make me a GIF of X doing Y for Slack.\"\nlicense: Complete terms in LICENSE.txt\n---\n\n# Slack GIF Creator\n\nA toolkit providing utilities and knowledge for creating animated GIFs optimized for Slack.\n\n## Slack Requirements\n\n**Dimensions:**\n- Emoji GIFs: 128x128 (recommended)\n- Message GIFs: 480x480\n\n**Parameters:**\n- FPS: 10-30 (lower is smaller file size)\n- Colors: 48-128 (fewer = smaller file size)\n- Duration: Keep under 3 seconds for emoji GIFs\n\n## Core Workflow\n\n```python\nfrom core.gif_builder import GIFBuilder\nfrom PIL import Image, ImageDraw\n\n# 1. Create builder\nbuilder = GIFBuilder(width=128, height=128, fps=10)\n\n# 2. Generate frames\nfor i in range(12):\n    frame = Image.new(\'RGB\', (128, 128), (240, 248, 255))\n    draw = ImageDraw.Draw(frame)\n\n    # Draw your animation using PIL primitives\n    # (circles, polygons, lines, etc.)\n\n    builder.add_frame(frame)\n\n# 3. Save with optimization\nbuilder.save(\'output.gif\', num_colors=48, optimize_for_emoji=True)\n```\n\n## Drawing Graphics\n\n### Working with User-Uploaded Images\nIf a user uploads an image, consider whether they want to:\n- **Use it directly** (e.g., \"animate this\", \"split this into frames\")\n- **Use it as inspiration** (e.g., \"make something like this\")\n\nLoad and work with images using PIL:\n```python\nfrom PIL import Image\n\nuploaded = Image.open(\'file.png\')\n# Use directly, or just as reference for colors/style\n```\n\n### Drawing from Scratch\nWhen drawing graphics from scratch, use PIL ImageDraw primitives:\n\n```python\nfrom PIL import ImageDraw\n\ndraw = ImageDraw.Draw(frame)\n\n# Circles/ovals\ndraw.ellipse([x1, y1, x2, y2], fill=(r, g, b), outline=(r, g, b), width=3)\n\n# Stars, triangles, any polygon\npoints = [(x1, y1), (x2, y2), (x3, y3), ...]\ndraw.polygon(points, fill=(r, g, b), outline=(r, g, b), width=3)\n\n# Lines\ndraw.line([(x1, y1), (x2, y2)], fill=(r, g, b), width=5)\n\n# Rectangles\ndraw.rectangle([x1, y1, x2, y2], fill=(r, g, b), outline=(r, g, b), width=3)\n```\n\n**Don\'t use:** Emoji fonts (unreliable across platforms) or assume pre-packaged graphics exist in this skill.\n\n### Making Graphics Look Good\n\nGraphics should look polished and creative, not basic. Here\'s how:\n\n**Use thicker lines** - Always set `width=2` or higher for outlines and lines. Thin lines (width=1) look choppy and amateurish.\n\n**Add visual depth**:\n- Use gradients for backgrounds (`create_gradient_background`)\n- Layer multiple shapes for complexity (e.g., a star with a smaller star inside)\n\n**Make shapes more interesting**:\n- Don\'t just draw a plain circle - add highlights, rings, or patterns\n- Stars can have glows (draw larger, semi-transparent versions behind)\n- Combine multiple shapes (stars + sparkles, circles + rings)\n\n**Pay attention to colors**:\n- Use vibrant, complementary colors\n- Add contrast (dark outlines on light shapes, light outlines on dark shapes)\n- Consider the overall composition\n\n**For complex shapes** (hearts, snowflakes, etc.):\n- Use combinations of polygons and ellipses\n- Calculate points carefully for symmetry\n- Add details (a heart can have a highlight curve, snowflakes have intricate branches)\n\nBe creative and detailed! A good Slack GIF should look polished, not like placeholder graphics.\n\n## Available Utilities\n\n### GIFBuilder (`core.gif_builder`)\nAssembles frames and optimizes for Slack:\n```python\nbuilder = GIFBuilder(width=128, height=128, fps=10)\nbuilder.add_frame(frame)  # Add PIL Image\nbuilder.add_frames(frames)  # Add list of frames\nbuilder.save(\'out.gif\', num_colors=48, optimize_for_emoji=True, remove_duplicates=True)\n```\n\n### Validators (`core.validators`)\nCheck if GIF meets Slack requirements:\n```python\nfrom core.validators import validate_gif, is_slack_ready\n\n# Detailed validation\npasses, info = validate_gif(\'my.gif\', is_emoji=True, verbose=True)\n\n# Quick check\nif is_slack_ready(\'my.gif\'):\n    print(\"Ready!\")\n```\n\n### Easing Functions (`core.easing`)\nSmooth motion instead of linear:\n```python\nfrom core.easing import interpolate\n\n# Progress from 0.0 to 1.0\nt = i / (num_frames - 1)\n\n# Apply easing\ny = interpolate(start=0, end=400, t=t, easing=\'ease_out\')\n\n# Available: linear, ease_in, ease_out, ease_in_out,\n#           bounce_out, elastic_out, back_out\n```\n\n### Frame Helpers (`core.frame_composer`)\nConvenience functions for common needs:\n```python\nfrom core.frame_composer import (\n    create_blank_frame,         # Solid color background\n    create_gradient_background,  # Vertical gradient\n    draw_circle,                # Helper for circles\n    draw_text,                  # Simple text rendering\n    draw_star                   # 5-pointed star\n)\n```\n\n## Animation Concepts\n\n### Shake/Vibrate\nOffset object position with oscillation:\n- Use `math.sin()` or `math.cos()` with frame index\n- Add small random variations for natural feel\n- Apply to x and/or y position\n\n### Pulse/Heartbeat\nScale object size rhythmically:\n- Use `math.sin(t * frequency * 2 * math.pi)` for smooth pulse\n- For heartbeat: two quick pulses then pause (adjust sine wave)\n- Scale between 0.8 and 1.2 of base size\n\n### Bounce\nObject falls and bounces:\n- Use `interpolate()` with `easing=\'bounce_out\'` for landing\n- Use `easing=\'ease_in\'` for falling (accelerating)\n- Apply gravity by increasing y velocity each frame\n\n### Spin/Rotate\nRotate object around center:\n- PIL: `image.rotate(angle, resample=Image.BICUBIC)`\n- For wobble: use sine wave for angle instead of linear\n\n### Fade In/Out\nGradually appear or disappear:\n- Create RGBA image, adjust alpha channel\n- Or use `Image.blend(image1, image2, alpha)`\n- Fade in: alpha from 0 to 1\n- Fade out: alpha from 1 to 0\n\n### Slide\nMove object from off-screen to position:\n- Start position: outside frame bounds\n- End position: target location\n- Use `interpolate()` with `easing=\'ease_out\'` for smooth stop\n- For overshoot: use `easing=\'back_out\'`\n\n### Zoom\nScale and position for zoom effect:\n- Zoom in: scale from 0.1 to 2.0, crop center\n- Zoom out: scale from 2.0 to 1.0\n- Can add motion blur for drama (PIL filter)\n\n### Explode/Particle Burst\nCreate particles radiating outward:\n- Generate particles with random angles and velocities\n- Update each particle: `x += vx`, `y += vy`\n- Add gravity: `vy += gravity_constant`\n- Fade out particles over time (reduce alpha)\n\n## Optimization Strategies\n\nOnly when asked to make the file size smaller, implement a few of the following methods:\n\n1. **Fewer frames** - Lower FPS (10 instead of 20) or shorter duration\n2. **Fewer colors** - `num_colors=48` instead of 128\n3. **Smaller dimensions** - 128x128 instead of 480x480\n4. **Remove duplicates** - `remove_duplicates=True` in save()\n5. **Emoji mode** - `optimize_for_emoji=True` auto-optimizes\n\n```python\n# Maximum optimization for emoji\nbuilder.save(\n    \'emoji.gif\',\n    num_colors=48,\n    optimize_for_emoji=True,\n    remove_duplicates=True\n)\n```\n\n## Philosophy\n\nThis skill provides:\n- **Knowledge**: Slack\'s requirements and animation concepts\n- **Utilities**: GIFBuilder, validators, easing functions\n- **Flexibility**: Create the animation logic using PIL primitives\n\nIt does NOT provide:\n- Rigid animation templates or pre-made functions\n- Emoji font rendering (unreliable across platforms)\n- A library of pre-packaged graphics built into the skill\n\n**Note on user uploads**: This skill doesn\'t include pre-built graphics, but if a user uploads an image, use PIL to load and work with it - interpret based on their request whether they want it used directly or just as inspiration.\n\nBe creative! Combine concepts (bouncing + rotating, pulsing + sliding, etc.) and use PIL\'s full capabilities.\n\n## Dependencies\n\n```bash\npip install pillow imageio numpy\n```\n','20df858cb97a6638728d658d825f4683','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(1231,'enc.736372697074732f7574696c732e7079','skill_enc.736b696c6c2d63726561746f72__enc.302e302e31','\"\"\"Shared utilities for skill-creator scripts.\"\"\"\n\nfrom pathlib import Path\n\n\n\ndef parse_skill_md(skill_path: Path) -> tuple[str, str, str]:\n    \"\"\"Parse a SKILL.md file, returning (name, description, full_content).\"\"\"\n    content = (skill_path / \"SKILL.md\").read_text()\n    lines = content.split(\"\\n\")\n\n    if lines[0].strip() != \"---\":\n        raise ValueError(\"SKILL.md missing frontmatter (no opening ---)\")\n\n    end_idx = None\n    for i, line in enumerate(lines[1:], start=1):\n        if line.strip() == \"---\":\n            end_idx = i\n            break\n\n    if end_idx is None:\n        raise ValueError(\"SKILL.md missing frontmatter (no closing ---)\")\n\n    name = \"\"\n    description = \"\"\n    frontmatter_lines = lines[1:end_idx]\n    i = 0\n    while i < len(frontmatter_lines):\n        line = frontmatter_lines[i]\n        if line.startswith(\"name:\"):\n            name = line[len(\"name:\"):].strip().strip(\'\"\').strip(\"\'\")\n        elif line.startswith(\"description:\"):\n            value = line[len(\"description:\"):].strip()\n            # Handle YAML multiline indicators (>, |, >-, |-)\n            if value in (\">\", \"|\", \">-\", \"|-\"):\n                continuation_lines: list[str] = []\n                i += 1\n                while i < len(frontmatter_lines) and (frontmatter_lines[i].startswith(\"  \") or frontmatter_lines[i].startswith(\"\\t\")):\n                    continuation_lines.append(frontmatter_lines[i].strip())\n                    i += 1\n                description = \" \".join(continuation_lines)\n                continue\n            else:\n                description = value.strip(\'\"\').strip(\"\'\")\n        i += 1\n\n    return name, description, content\n','6cf213a77cbadc39febbaf9ee57fac10','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(1232,'enc.6576616c2d7669657765722f67656e65726174655f7265766965772e7079','skill_enc.736b696c6c2d63726561746f72__enc.302e302e31','#!/usr/bin/env python3\n\"\"\"Generate and serve a review page for eval results.\n\nReads the workspace directory, discovers runs (directories with outputs/),\nembeds all output data into a self-contained HTML page, and serves it via\na tiny HTTP server. Feedback auto-saves to feedback.json in the workspace.\n\nUsage:\n    python generate_review.py <workspace-path> [--port PORT] [--skill-name NAME]\n    python generate_review.py <workspace-path> --previous-feedback /path/to/old/feedback.json\n\nNo dependencies beyond the Python stdlib are required.\n\"\"\"\n\nimport argparse\nimport base64\nimport json\nimport mimetypes\nimport os\nimport re\nimport signal\nimport subprocess\nimport sys\nimport time\nimport webbrowser\nfrom functools import partial\nfrom http.server import HTTPServer, BaseHTTPRequestHandler\nfrom pathlib import Path\n\n# Files to exclude from output listings\nMETADATA_FILES = {\"transcript.md\", \"user_notes.md\", \"metrics.json\"}\n\n# Extensions we render as inline text\nTEXT_EXTENSIONS = {\n    \".txt\", \".md\", \".json\", \".csv\", \".py\", \".js\", \".ts\", \".tsx\", \".jsx\",\n    \".yaml\", \".yml\", \".xml\", \".html\", \".css\", \".sh\", \".rb\", \".go\", \".rs\",\n    \".java\", \".c\", \".cpp\", \".h\", \".hpp\", \".sql\", \".r\", \".toml\",\n}\n\n# Extensions we render as inline images\nIMAGE_EXTENSIONS = {\".png\", \".jpg\", \".jpeg\", \".gif\", \".svg\", \".webp\"}\n\n# MIME type overrides for common types\nMIME_OVERRIDES = {\n    \".svg\": \"image/svg+xml\",\n    \".xlsx\": \"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\",\n    \".docx\": \"application/vnd.openxmlformats-officedocument.wordprocessingml.document\",\n    \".pptx\": \"application/vnd.openxmlformats-officedocument.presentationml.presentation\",\n}\n\n\ndef get_mime_type(path: Path) -> str:\n    ext = path.suffix.lower()\n    if ext in MIME_OVERRIDES:\n        return MIME_OVERRIDES[ext]\n    mime, _ = mimetypes.guess_type(str(path))\n    return mime or \"application/octet-stream\"\n\n\ndef find_runs(workspace: Path) -> list[dict]:\n    \"\"\"Recursively find directories that contain an outputs/ subdirectory.\"\"\"\n    runs: list[dict] = []\n    _find_runs_recursive(workspace, workspace, runs)\n    runs.sort(key=lambda r: (r.get(\"eval_id\", float(\"inf\")), r[\"id\"]))\n    return runs\n\n\ndef _find_runs_recursive(root: Path, current: Path, runs: list[dict]) -> None:\n    if not current.is_dir():\n        return\n\n    outputs_dir = current / \"outputs\"\n    if outputs_dir.is_dir():\n        run = build_run(root, current)\n        if run:\n            runs.append(run)\n        return\n\n    skip = {\"node_modules\", \".git\", \"__pycache__\", \"skill\", \"inputs\"}\n    for child in sorted(current.iterdir()):\n        if child.is_dir() and child.name not in skip:\n            _find_runs_recursive(root, child, runs)\n\n\ndef build_run(root: Path, run_dir: Path) -> dict | None:\n    \"\"\"Build a run dict with prompt, outputs, and grading data.\"\"\"\n    prompt = \"\"\n    eval_id = None\n\n    # Try eval_metadata.json\n    for candidate in [run_dir / \"eval_metadata.json\", run_dir.parent / \"eval_metadata.json\"]:\n        if candidate.exists():\n            try:\n                metadata = json.loads(candidate.read_text())\n                prompt = metadata.get(\"prompt\", \"\")\n                eval_id = metadata.get(\"eval_id\")\n            except (json.JSONDecodeError, OSError):\n                pass\n            if prompt:\n                break\n\n    # Fall back to transcript.md\n    if not prompt:\n        for candidate in [run_dir / \"transcript.md\", run_dir / \"outputs\" / \"transcript.md\"]:\n            if candidate.exists():\n                try:\n                    text = candidate.read_text()\n                    match = re.search(r\"## Eval Prompt\\n\\n([\\s\\S]*?)(?=\\n##|$)\", text)\n                    if match:\n                        prompt = match.group(1).strip()\n                except OSError:\n                    pass\n                if prompt:\n                    break\n\n    if not prompt:\n        prompt = \"(No prompt found)\"\n\n    run_id = str(run_dir.relative_to(root)).replace(\"/\", \"-\").replace(\"\\\\\", \"-\")\n\n    # Collect output files\n    outputs_dir = run_dir / \"outputs\"\n    output_files: list[dict] = []\n    if outputs_dir.is_dir():\n        for f in sorted(outputs_dir.iterdir()):\n            if f.is_file() and f.name not in METADATA_FILES:\n                output_files.append(embed_file(f))\n\n    # Load grading if present\n    grading = None\n    for candidate in [run_dir / \"grading.json\", run_dir.parent / \"grading.json\"]:\n        if candidate.exists():\n            try:\n                grading = json.loads(candidate.read_text())\n            except (json.JSONDecodeError, OSError):\n                pass\n            if grading:\n                break\n\n    return {\n        \"id\": run_id,\n        \"prompt\": prompt,\n        \"eval_id\": eval_id,\n        \"outputs\": output_files,\n        \"grading\": grading,\n    }\n\n\ndef embed_file(path: Path) -> dict:\n    \"\"\"Read a file and return an embedded representation.\"\"\"\n    ext = path.suffix.lower()\n    mime = get_mime_type(path)\n\n    if ext in TEXT_EXTENSIONS:\n        try:\n            content = path.read_text(errors=\"replace\")\n        except OSError:\n            content = \"(Error reading file)\"\n        return {\n            \"name\": path.name,\n            \"type\": \"text\",\n            \"content\": content,\n        }\n    elif ext in IMAGE_EXTENSIONS:\n        try:\n            raw = path.read_bytes()\n            b64 = base64.b64encode(raw).decode(\"ascii\")\n        except OSError:\n            return {\"name\": path.name, \"type\": \"error\", \"content\": \"(Error reading file)\"}\n        return {\n            \"name\": path.name,\n            \"type\": \"image\",\n            \"mime\": mime,\n            \"data_uri\": f\"data:{mime};base64,{b64}\",\n        }\n    elif ext == \".pdf\":\n        try:\n            raw = path.read_bytes()\n            b64 = base64.b64encode(raw).decode(\"ascii\")\n        except OSError:\n            return {\"name\": path.name, \"type\": \"error\", \"content\": \"(Error reading file)\"}\n        return {\n            \"name\": path.name,\n            \"type\": \"pdf\",\n            \"data_uri\": f\"data:{mime};base64,{b64}\",\n        }\n    elif ext == \".xlsx\":\n        try:\n            raw = path.read_bytes()\n            b64 = base64.b64encode(raw).decode(\"ascii\")\n        except OSError:\n            return {\"name\": path.name, \"type\": \"error\", \"content\": \"(Error reading file)\"}\n        return {\n            \"name\": path.name,\n            \"type\": \"xlsx\",\n            \"data_b64\": b64,\n        }\n    else:\n        # Binary / unknown — base64 download link\n        try:\n            raw = path.read_bytes()\n            b64 = base64.b64encode(raw).decode(\"ascii\")\n        except OSError:\n            return {\"name\": path.name, \"type\": \"error\", \"content\": \"(Error reading file)\"}\n        return {\n            \"name\": path.name,\n            \"type\": \"binary\",\n            \"mime\": mime,\n            \"data_uri\": f\"data:{mime};base64,{b64}\",\n        }\n\n\ndef load_previous_iteration(workspace: Path) -> dict[str, dict]:\n    \"\"\"Load previous iteration\'s feedback and outputs.\n\n    Returns a map of run_id -> {\"feedback\": str, \"outputs\": list[dict]}.\n    \"\"\"\n    result: dict[str, dict] = {}\n\n    # Load feedback\n    feedback_map: dict[str, str] = {}\n    feedback_path = workspace / \"feedback.json\"\n    if feedback_path.exists():\n        try:\n            data = json.loads(feedback_path.read_text())\n            feedback_map = {\n                r[\"run_id\"]: r[\"feedback\"]\n                for r in data.get(\"reviews\", [])\n                if r.get(\"feedback\", \"\").strip()\n            }\n        except (json.JSONDecodeError, OSError, KeyError):\n            pass\n\n    # Load runs (to get outputs)\n    prev_runs = find_runs(workspace)\n    for run in prev_runs:\n        result[run[\"id\"]] = {\n            \"feedback\": feedback_map.get(run[\"id\"], \"\"),\n            \"outputs\": run.get(\"outputs\", []),\n        }\n\n    # Also add feedback for run_ids that had feedback but no matching run\n    for run_id, fb in feedback_map.items():\n        if run_id not in result:\n            result[run_id] = {\"feedback\": fb, \"outputs\": []}\n\n    return result\n\n\ndef generate_html(\n    runs: list[dict],\n    skill_name: str,\n    previous: dict[str, dict] | None = None,\n    benchmark: dict | None = None,\n) -> str:\n    \"\"\"Generate the complete standalone HTML page with embedded data.\"\"\"\n    template_path = Path(__file__).parent / \"viewer.html\"\n    template = template_path.read_text()\n\n    # Build previous_feedback and previous_outputs maps for the template\n    previous_feedback: dict[str, str] = {}\n    previous_outputs: dict[str, list[dict]] = {}\n    if previous:\n        for run_id, data in previous.items():\n            if data.get(\"feedback\"):\n                previous_feedback[run_id] = data[\"feedback\"]\n            if data.get(\"outputs\"):\n                previous_outputs[run_id] = data[\"outputs\"]\n\n    embedded = {\n        \"skill_name\": skill_name,\n        \"runs\": runs,\n        \"previous_feedback\": previous_feedback,\n        \"previous_outputs\": previous_outputs,\n    }\n    if benchmark:\n        embedded[\"benchmark\"] = benchmark\n\n    data_json = json.dumps(embedded)\n\n    return template.replace(\"/*__EMBEDDED_DATA__*/\", f\"const EMBEDDED_DATA = {data_json};\")\n\n\n# ---------------------------------------------------------------------------\n# HTTP server (stdlib only, zero dependencies)\n# ---------------------------------------------------------------------------\n\ndef _kill_port(port: int) -> None:\n    \"\"\"Kill any process listening on the given port.\"\"\"\n    try:\n        result = subprocess.run(\n            [\"lsof\", \"-ti\", f\":{port}\"],\n            capture_output=True, text=True, timeout=5,\n        )\n        for pid_str in result.stdout.strip().split(\"\\n\"):\n            if pid_str.strip():\n                try:\n                    os.kill(int(pid_str.strip()), signal.SIGTERM)\n                except (ProcessLookupError, ValueError):\n                    pass\n        if result.stdout.strip():\n            time.sleep(0.5)\n    except subprocess.TimeoutExpired:\n        pass\n    except FileNotFoundError:\n        print(\"Note: lsof not found, cannot check if port is in use\", file=sys.stderr)\n\nclass ReviewHandler(BaseHTTPRequestHandler):\n    \"\"\"Serves the review HTML and handles feedback saves.\n\n    Regenerates the HTML on each page load so that refreshing the browser\n    picks up new eval outputs without restarting the server.\n    \"\"\"\n\n    def __init__(\n        self,\n        workspace: Path,\n        skill_name: str,\n        feedback_path: Path,\n        previous: dict[str, dict],\n        benchmark_path: Path | None,\n        *args,\n        **kwargs,\n    ):\n        self.workspace = workspace\n        self.skill_name = skill_name\n        self.feedback_path = feedback_path\n        self.previous = previous\n        self.benchmark_path = benchmark_path\n        super().__init__(*args, **kwargs)\n\n    def do_GET(self) -> None:\n        if self.path == \"/\" or self.path == \"/index.html\":\n            # Regenerate HTML on each request (re-scans workspace for new outputs)\n            runs = find_runs(self.workspace)\n            benchmark = None\n            if self.benchmark_path and self.benchmark_path.exists():\n                try:\n                    benchmark = json.loads(self.benchmark_path.read_text())\n                except (json.JSONDecodeError, OSError):\n                    pass\n            html = generate_html(runs, self.skill_name, self.previous, benchmark)\n            content = html.encode(\"utf-8\")\n            self.send_response(200)\n            self.send_header(\"Content-Type\", \"text/html; charset=utf-8\")\n            self.send_header(\"Content-Length\", str(len(content)))\n            self.end_headers()\n            self.wfile.write(content)\n        elif self.path == \"/api/feedback\":\n            data = b\"{}\"\n            if self.feedback_path.exists():\n                data = self.feedback_path.read_bytes()\n            self.send_response(200)\n            self.send_header(\"Content-Type\", \"application/json\")\n            self.send_header(\"Content-Length\", str(len(data)))\n            self.end_headers()\n            self.wfile.write(data)\n        else:\n            self.send_error(404)\n\n    def do_POST(self) -> None:\n        if self.path == \"/api/feedback\":\n            length = int(self.headers.get(\"Content-Length\", 0))\n            body = self.rfile.read(length)\n            try:\n                data = json.loads(body)\n                if not isinstance(data, dict) or \"reviews\" not in data:\n                    raise ValueError(\"Expected JSON object with \'reviews\' key\")\n                self.feedback_path.write_text(json.dumps(data, indent=2) + \"\\n\")\n                resp = b\'{\"ok\":true}\'\n                self.send_response(200)\n            except (json.JSONDecodeError, OSError, ValueError) as e:\n                resp = json.dumps({\"error\": str(e)}).encode()\n                self.send_response(500)\n            self.send_header(\"Content-Type\", \"application/json\")\n            self.send_header(\"Content-Length\", str(len(resp)))\n            self.end_headers()\n            self.wfile.write(resp)\n        else:\n            self.send_error(404)\n\n    def log_message(self, format: str, *args: object) -> None:\n        # Suppress request logging to keep terminal clean\n        pass\n\n\ndef main() -> None:\n    parser = argparse.ArgumentParser(description=\"Generate and serve eval review\")\n    parser.add_argument(\"workspace\", type=Path, help=\"Path to workspace directory\")\n    parser.add_argument(\"--port\", \"-p\", type=int, default=3117, help=\"Server port (default: 3117)\")\n    parser.add_argument(\"--skill-name\", \"-n\", type=str, default=None, help=\"Skill name for header\")\n    parser.add_argument(\n        \"--previous-workspace\", type=Path, default=None,\n        help=\"Path to previous iteration\'s workspace (shows old outputs and feedback as context)\",\n    )\n    parser.add_argument(\n        \"--benchmark\", type=Path, default=None,\n        help=\"Path to benchmark.json to show in the Benchmark tab\",\n    )\n    parser.add_argument(\n        \"--static\", \"-s\", type=Path, default=None,\n        help=\"Write standalone HTML to this path instead of starting a server\",\n    )\n    args = parser.parse_args()\n\n    workspace = args.workspace.resolve()\n    if not workspace.is_dir():\n        print(f\"Error: {workspace} is not a directory\", file=sys.stderr)\n        sys.exit(1)\n\n    runs = find_runs(workspace)\n    if not runs:\n        print(f\"No runs found in {workspace}\", file=sys.stderr)\n        sys.exit(1)\n\n    skill_name = args.skill_name or workspace.name.replace(\"-workspace\", \"\")\n    feedback_path = workspace / \"feedback.json\"\n\n    previous: dict[str, dict] = {}\n    if args.previous_workspace:\n        previous = load_previous_iteration(args.previous_workspace.resolve())\n\n    benchmark_path = args.benchmark.resolve() if args.benchmark else None\n    benchmark = None\n    if benchmark_path and benchmark_path.exists():\n        try:\n            benchmark = json.loads(benchmark_path.read_text())\n        except (json.JSONDecodeError, OSError):\n            pass\n\n    if args.static:\n        html = generate_html(runs, skill_name, previous, benchmark)\n        args.static.parent.mkdir(parents=True, exist_ok=True)\n        args.static.write_text(html)\n        print(f\"\\n  Static viewer written to: {args.static}\\n\")\n        sys.exit(0)\n\n    # Kill any existing process on the target port\n    port = args.port\n    _kill_port(port)\n    handler = partial(ReviewHandler, workspace, skill_name, feedback_path, previous, benchmark_path)\n    try:\n        server = HTTPServer((\"127.0.0.1\", port), handler)\n    except OSError:\n        # Port still in use after kill attempt — find a free one\n        server = HTTPServer((\"127.0.0.1\", 0), handler)\n        port = server.server_address[1]\n\n    url = f\"http://localhost:{port}\"\n    print(f\"\\n  Eval Viewer\")\n    print(f\"  ─────────────────────────────────\")\n    print(f\"  URL:       {url}\")\n    print(f\"  Workspace: {workspace}\")\n    print(f\"  Feedback:  {feedback_path}\")\n    if previous:\n        print(f\"  Previous:  {args.previous_workspace} ({len(previous)} runs)\")\n    if benchmark_path:\n        print(f\"  Benchmark: {benchmark_path}\")\n    print(f\"\\n  Press Ctrl+C to stop.\\n\")\n\n    webbrowser.open(url)\n\n    try:\n        server.serve_forever()\n    except KeyboardInterrupt:\n        print(\"\\nStopped.\")\n        server.server_close()\n\n\nif __name__ == \"__main__\":\n    main()\n','d7f883f3d3596e62618faecf298c4f5f','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(1233,'SKILL.md','skill_enc.736c61636b2d6769662d63726561746f72__enc.302e302e31','---\nversion: 0.0.1\nname: slack-gif-creator\ndescription: Knowledge and utilities for creating animated GIFs optimized for Slack. Provides constraints, validation tools, and animation concepts. Use when users request animated GIFs for Slack like \"make me a GIF of X doing Y for Slack.\"\nlicense: Complete terms in LICENSE.txt\n---\n\n# Slack GIF Creator\n\nA toolkit providing utilities and knowledge for creating animated GIFs optimized for Slack.\n\n## Slack Requirements\n\n**Dimensions:**\n- Emoji GIFs: 128x128 (recommended)\n- Message GIFs: 480x480\n\n**Parameters:**\n- FPS: 10-30 (lower is smaller file size)\n- Colors: 48-128 (fewer = smaller file size)\n- Duration: Keep under 3 seconds for emoji GIFs\n\n## Core Workflow\n\n```python\nfrom core.gif_builder import GIFBuilder\nfrom PIL import Image, ImageDraw\n\n# 1. Create builder\nbuilder = GIFBuilder(width=128, height=128, fps=10)\n\n# 2. Generate frames\nfor i in range(12):\n    frame = Image.new(\'RGB\', (128, 128), (240, 248, 255))\n    draw = ImageDraw.Draw(frame)\n\n    # Draw your animation using PIL primitives\n    # (circles, polygons, lines, etc.)\n\n    builder.add_frame(frame)\n\n# 3. Save with optimization\nbuilder.save(\'output.gif\', num_colors=48, optimize_for_emoji=True)\n```\n\n## Drawing Graphics\n\n### Working with User-Uploaded Images\nIf a user uploads an image, consider whether they want to:\n- **Use it directly** (e.g., \"animate this\", \"split this into frames\")\n- **Use it as inspiration** (e.g., \"make something like this\")\n\nLoad and work with images using PIL:\n```python\nfrom PIL import Image\n\nuploaded = Image.open(\'file.png\')\n# Use directly, or just as reference for colors/style\n```\n\n### Drawing from Scratch\nWhen drawing graphics from scratch, use PIL ImageDraw primitives:\n\n```python\nfrom PIL import ImageDraw\n\ndraw = ImageDraw.Draw(frame)\n\n# Circles/ovals\ndraw.ellipse([x1, y1, x2, y2], fill=(r, g, b), outline=(r, g, b), width=3)\n\n# Stars, triangles, any polygon\npoints = [(x1, y1), (x2, y2), (x3, y3), ...]\ndraw.polygon(points, fill=(r, g, b), outline=(r, g, b), width=3)\n\n# Lines\ndraw.line([(x1, y1), (x2, y2)], fill=(r, g, b), width=5)\n\n# Rectangles\ndraw.rectangle([x1, y1, x2, y2], fill=(r, g, b), outline=(r, g, b), width=3)\n```\n\n**Don\'t use:** Emoji fonts (unreliable across platforms) or assume pre-packaged graphics exist in this skill.\n\n### Making Graphics Look Good\n\nGraphics should look polished and creative, not basic. Here\'s how:\n\n**Use thicker lines** - Always set `width=2` or higher for outlines and lines. Thin lines (width=1) look choppy and amateurish.\n\n**Add visual depth**:\n- Use gradients for backgrounds (`create_gradient_background`)\n- Layer multiple shapes for complexity (e.g., a star with a smaller star inside)\n\n**Make shapes more interesting**:\n- Don\'t just draw a plain circle - add highlights, rings, or patterns\n- Stars can have glows (draw larger, semi-transparent versions behind)\n- Combine multiple shapes (stars + sparkles, circles + rings)\n\n**Pay attention to colors**:\n- Use vibrant, complementary colors\n- Add contrast (dark outlines on light shapes, light outlines on dark shapes)\n- Consider the overall composition\n\n**For complex shapes** (hearts, snowflakes, etc.):\n- Use combinations of polygons and ellipses\n- Calculate points carefully for symmetry\n- Add details (a heart can have a highlight curve, snowflakes have intricate branches)\n\nBe creative and detailed! A good Slack GIF should look polished, not like placeholder graphics.\n\n## Available Utilities\n\n### GIFBuilder (`core.gif_builder`)\nAssembles frames and optimizes for Slack:\n```python\nbuilder = GIFBuilder(width=128, height=128, fps=10)\nbuilder.add_frame(frame)  # Add PIL Image\nbuilder.add_frames(frames)  # Add list of frames\nbuilder.save(\'out.gif\', num_colors=48, optimize_for_emoji=True, remove_duplicates=True)\n```\n\n### Validators (`core.validators`)\nCheck if GIF meets Slack requirements:\n```python\nfrom core.validators import validate_gif, is_slack_ready\n\n# Detailed validation\npasses, info = validate_gif(\'my.gif\', is_emoji=True, verbose=True)\n\n# Quick check\nif is_slack_ready(\'my.gif\'):\n    print(\"Ready!\")\n```\n\n### Easing Functions (`core.easing`)\nSmooth motion instead of linear:\n```python\nfrom core.easing import interpolate\n\n# Progress from 0.0 to 1.0\nt = i / (num_frames - 1)\n\n# Apply easing\ny = interpolate(start=0, end=400, t=t, easing=\'ease_out\')\n\n# Available: linear, ease_in, ease_out, ease_in_out,\n#           bounce_out, elastic_out, back_out\n```\n\n### Frame Helpers (`core.frame_composer`)\nConvenience functions for common needs:\n```python\nfrom core.frame_composer import (\n    create_blank_frame,         # Solid color background\n    create_gradient_background,  # Vertical gradient\n    draw_circle,                # Helper for circles\n    draw_text,                  # Simple text rendering\n    draw_star                   # 5-pointed star\n)\n```\n\n## Animation Concepts\n\n### Shake/Vibrate\nOffset object position with oscillation:\n- Use `math.sin()` or `math.cos()` with frame index\n- Add small random variations for natural feel\n- Apply to x and/or y position\n\n### Pulse/Heartbeat\nScale object size rhythmically:\n- Use `math.sin(t * frequency * 2 * math.pi)` for smooth pulse\n- For heartbeat: two quick pulses then pause (adjust sine wave)\n- Scale between 0.8 and 1.2 of base size\n\n### Bounce\nObject falls and bounces:\n- Use `interpolate()` with `easing=\'bounce_out\'` for landing\n- Use `easing=\'ease_in\'` for falling (accelerating)\n- Apply gravity by increasing y velocity each frame\n\n### Spin/Rotate\nRotate object around center:\n- PIL: `image.rotate(angle, resample=Image.BICUBIC)`\n- For wobble: use sine wave for angle instead of linear\n\n### Fade In/Out\nGradually appear or disappear:\n- Create RGBA image, adjust alpha channel\n- Or use `Image.blend(image1, image2, alpha)`\n- Fade in: alpha from 0 to 1\n- Fade out: alpha from 1 to 0\n\n### Slide\nMove object from off-screen to position:\n- Start position: outside frame bounds\n- End position: target location\n- Use `interpolate()` with `easing=\'ease_out\'` for smooth stop\n- For overshoot: use `easing=\'back_out\'`\n\n### Zoom\nScale and position for zoom effect:\n- Zoom in: scale from 0.1 to 2.0, crop center\n- Zoom out: scale from 2.0 to 1.0\n- Can add motion blur for drama (PIL filter)\n\n### Explode/Particle Burst\nCreate particles radiating outward:\n- Generate particles with random angles and velocities\n- Update each particle: `x += vx`, `y += vy`\n- Add gravity: `vy += gravity_constant`\n- Fade out particles over time (reduce alpha)\n\n## Optimization Strategies\n\nOnly when asked to make the file size smaller, implement a few of the following methods:\n\n1. **Fewer frames** - Lower FPS (10 instead of 20) or shorter duration\n2. **Fewer colors** - `num_colors=48` instead of 128\n3. **Smaller dimensions** - 128x128 instead of 480x480\n4. **Remove duplicates** - `remove_duplicates=True` in save()\n5. **Emoji mode** - `optimize_for_emoji=True` auto-optimizes\n\n```python\n# Maximum optimization for emoji\nbuilder.save(\n    \'emoji.gif\',\n    num_colors=48,\n    optimize_for_emoji=True,\n    remove_duplicates=True\n)\n```\n\n## Philosophy\n\nThis skill provides:\n- **Knowledge**: Slack\'s requirements and animation concepts\n- **Utilities**: GIFBuilder, validators, easing functions\n- **Flexibility**: Create the animation logic using PIL primitives\n\nIt does NOT provide:\n- Rigid animation templates or pre-made functions\n- Emoji font rendering (unreliable across platforms)\n- A library of pre-packaged graphics built into the skill\n\n**Note on user uploads**: This skill doesn\'t include pre-built graphics, but if a user uploads an image, use PIL to load and work with it - interpret based on their request whether they want it used directly or just as inspiration.\n\nBe creative! Combine concepts (bouncing + rotating, pulsing + sliding, etc.) and use PIL\'s full capabilities.\n\n## Dependencies\n\n```bash\npip install pillow imageio numpy\n```\n','20df858cb97a6638728d658d825f4683','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(1234,'skill_index.json','skill_pptx','{\"labels\":{\"latest\":\"0.0.1\"},\"versions\":{\"0.0.1\":[\"SKILL.md\",\"scripts/office/schemas/ecma/fouth-edition/opc-digSig.xsd\",\"scripts/clean.py\",\"scripts/office/validators/__init__.py\",\"LICENSE.txt\",\"scripts/office/schemas/microsoft/wml-cex-2018.xsd\",\"editing.md\",\"scripts/office/schemas/ISO-IEC29500-4_2016/dml-main.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/shared-math.xsd\",\"scripts/office/validators/redlining.py\",\"scripts/office/validate.py\",\"scripts/office/validators/docx.py\",\"scripts/office/helpers/merge_runs.py\",\"scripts/office/schemas/ISO-IEC29500-4_2016/vml-spreadsheetDrawing.xsd\",\"scripts/office/helpers/simplify_redlines.py\",\"scripts/office/schemas/ISO-IEC29500-4_2016/dml-spreadsheetDrawing.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/sml.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/shared-documentPropertiesVariantTypes.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/dml-diagram.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/shared-customXmlDataProperties.xsd\",\"scripts/__init__.py\",\"scripts/office/schemas/ISO-IEC29500-4_2016/vml-officeDrawing.xsd\",\"scripts/office/schemas/microsoft/wml-2010.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/dml-lockedCanvas.xsd\",\"scripts/office/schemas/ecma/fouth-edition/opc-contentTypes.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/wml.xsd\",\"scripts/office/schemas/mce/mc.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/vml-presentationDrawing.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/shared-documentPropertiesExtended.xsd\",\"pptxgenjs.md\",\"scripts/thumbnail.py\",\"scripts/office/schemas/ISO-IEC29500-4_2016/shared-commonSimpleTypes.xsd\",\"scripts/office/schemas/ecma/fouth-edition/opc-relationships.xsd\",\"scripts/office/validators/base.py\",\"scripts/office/schemas/microsoft/wml-2018.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/dml-picture.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/vml-main.xsd\",\"scripts/office/schemas/microsoft/wml-2012.xsd\",\"scripts/office/helpers/__init__.py\",\"scripts/office/schemas/ISO-IEC29500-4_2016/vml-wordprocessingDrawing.xsd\",\"scripts/office/schemas/microsoft/wml-symex-2015.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/shared-documentPropertiesCustom.xsd\",\"scripts/office/schemas/microsoft/wml-cid-2016.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/shared-relationshipReference.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/dml-chartDrawing.xsd\",\"scripts/office/unpack.py\",\"scripts/office/schemas/ISO-IEC29500-4_2016/dml-chart.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/dml-wordprocessingDrawing.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/shared-additionalCharacteristics.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/shared-customXmlSchemaProperties.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/pml.xsd\",\"scripts/office/schemas/ecma/fouth-edition/opc-coreProperties.xsd\",\"scripts/office/validators/pptx.py\",\"scripts/office/soffice.py\",\"scripts/office/schemas/ISO-IEC29500-4_2016/shared-bibliography.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/xml.xsd\",\"scripts/office/schemas/microsoft/wml-sdtdatahash-2020.xsd\",\"scripts/add_slide.py\",\"scripts/office/pack.py\"]}}','dd643ae91b03e129e3cc1029c1cf4997','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(1235,'enc.636f72652f6672616d655f636f6d706f7365722e7079','skill_enc.736c61636b2d6769662d63726561746f72__enc.302e302e31','#!/usr/bin/env python3\n\"\"\"\nFrame Composer - Utilities for composing visual elements into frames.\n\nProvides functions for drawing shapes, text, emojis, and compositing elements\ntogether to create animation frames.\n\"\"\"\n\nfrom typing import Optional\n\nimport numpy as np\nfrom PIL import Image, ImageDraw, ImageFont\n\n\ndef create_blank_frame(\n    width: int, height: int, color: tuple[int, int, int] = (255, 255, 255)\n) -> Image.Image:\n    \"\"\"\n    Create a blank frame with solid color background.\n\n    Args:\n        width: Frame width\n        height: Frame height\n        color: RGB color tuple (default: white)\n\n    Returns:\n        PIL Image\n    \"\"\"\n    return Image.new(\"RGB\", (width, height), color)\n\n\ndef draw_circle(\n    frame: Image.Image,\n    center: tuple[int, int],\n    radius: int,\n    fill_color: Optional[tuple[int, int, int]] = None,\n    outline_color: Optional[tuple[int, int, int]] = None,\n    outline_width: int = 1,\n) -> Image.Image:\n    \"\"\"\n    Draw a circle on a frame.\n\n    Args:\n        frame: PIL Image to draw on\n        center: (x, y) center position\n        radius: Circle radius\n        fill_color: RGB fill color (None for no fill)\n        outline_color: RGB outline color (None for no outline)\n        outline_width: Outline width in pixels\n\n    Returns:\n        Modified frame\n    \"\"\"\n    draw = ImageDraw.Draw(frame)\n    x, y = center\n    bbox = [x - radius, y - radius, x + radius, y + radius]\n    draw.ellipse(bbox, fill=fill_color, outline=outline_color, width=outline_width)\n    return frame\n\n\ndef draw_text(\n    frame: Image.Image,\n    text: str,\n    position: tuple[int, int],\n    color: tuple[int, int, int] = (0, 0, 0),\n    centered: bool = False,\n) -> Image.Image:\n    \"\"\"\n    Draw text on a frame.\n\n    Args:\n        frame: PIL Image to draw on\n        text: Text to draw\n        position: (x, y) position (top-left unless centered=True)\n        color: RGB text color\n        centered: If True, center text at position\n\n    Returns:\n        Modified frame\n    \"\"\"\n    draw = ImageDraw.Draw(frame)\n\n    # Uses Pillow\'s default font.\n    # If the font should be changed for the emoji, add additional logic here.\n    font = ImageFont.load_default()\n\n    if centered:\n        bbox = draw.textbbox((0, 0), text, font=font)\n        text_width = bbox[2] - bbox[0]\n        text_height = bbox[3] - bbox[1]\n        x = position[0] - text_width // 2\n        y = position[1] - text_height // 2\n        position = (x, y)\n\n    draw.text(position, text, fill=color, font=font)\n    return frame\n\n\ndef create_gradient_background(\n    width: int,\n    height: int,\n    top_color: tuple[int, int, int],\n    bottom_color: tuple[int, int, int],\n) -> Image.Image:\n    \"\"\"\n    Create a vertical gradient background.\n\n    Args:\n        width: Frame width\n        height: Frame height\n        top_color: RGB color at top\n        bottom_color: RGB color at bottom\n\n    Returns:\n        PIL Image with gradient\n    \"\"\"\n    frame = Image.new(\"RGB\", (width, height))\n    draw = ImageDraw.Draw(frame)\n\n    # Calculate color step for each row\n    r1, g1, b1 = top_color\n    r2, g2, b2 = bottom_color\n\n    for y in range(height):\n        # Interpolate color\n        ratio = y / height\n        r = int(r1 * (1 - ratio) + r2 * ratio)\n        g = int(g1 * (1 - ratio) + g2 * ratio)\n        b = int(b1 * (1 - ratio) + b2 * ratio)\n\n        # Draw horizontal line\n        draw.line([(0, y), (width, y)], fill=(r, g, b))\n\n    return frame\n\n\ndef draw_star(\n    frame: Image.Image,\n    center: tuple[int, int],\n    size: int,\n    fill_color: tuple[int, int, int],\n    outline_color: Optional[tuple[int, int, int]] = None,\n    outline_width: int = 1,\n) -> Image.Image:\n    \"\"\"\n    Draw a 5-pointed star.\n\n    Args:\n        frame: PIL Image to draw on\n        center: (x, y) center position\n        size: Star size (outer radius)\n        fill_color: RGB fill color\n        outline_color: RGB outline color (None for no outline)\n        outline_width: Outline width\n\n    Returns:\n        Modified frame\n    \"\"\"\n    import math\n\n    draw = ImageDraw.Draw(frame)\n    x, y = center\n\n    # Calculate star points\n    points = []\n    for i in range(10):\n        angle = (i * 36 - 90) * math.pi / 180  # 36 degrees per point, start at top\n        radius = size if i % 2 == 0 else size * 0.4  # Alternate between outer and inner\n        px = x + radius * math.cos(angle)\n        py = y + radius * math.sin(angle)\n        points.append((px, py))\n\n    # Draw star\n    draw.polygon(points, fill=fill_color, outline=outline_color, width=outline_width)\n\n    return frame\n','12b7331866a67b0653b2c8e026210637','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(1236,'enc.6576616c2d7669657765722f67656e65726174655f7265766965772e7079','skill_enc.736b696c6c2d63726561746f72__enc.302e302e31','#!/usr/bin/env python3\n\"\"\"Generate and serve a review page for eval results.\n\nReads the workspace directory, discovers runs (directories with outputs/),\nembeds all output data into a self-contained HTML page, and serves it via\na tiny HTTP server. Feedback auto-saves to feedback.json in the workspace.\n\nUsage:\n    python generate_review.py <workspace-path> [--port PORT] [--skill-name NAME]\n    python generate_review.py <workspace-path> --previous-feedback /path/to/old/feedback.json\n\nNo dependencies beyond the Python stdlib are required.\n\"\"\"\n\nimport argparse\nimport base64\nimport json\nimport mimetypes\nimport os\nimport re\nimport signal\nimport subprocess\nimport sys\nimport time\nimport webbrowser\nfrom functools import partial\nfrom http.server import HTTPServer, BaseHTTPRequestHandler\nfrom pathlib import Path\n\n# Files to exclude from output listings\nMETADATA_FILES = {\"transcript.md\", \"user_notes.md\", \"metrics.json\"}\n\n# Extensions we render as inline text\nTEXT_EXTENSIONS = {\n    \".txt\", \".md\", \".json\", \".csv\", \".py\", \".js\", \".ts\", \".tsx\", \".jsx\",\n    \".yaml\", \".yml\", \".xml\", \".html\", \".css\", \".sh\", \".rb\", \".go\", \".rs\",\n    \".java\", \".c\", \".cpp\", \".h\", \".hpp\", \".sql\", \".r\", \".toml\",\n}\n\n# Extensions we render as inline images\nIMAGE_EXTENSIONS = {\".png\", \".jpg\", \".jpeg\", \".gif\", \".svg\", \".webp\"}\n\n# MIME type overrides for common types\nMIME_OVERRIDES = {\n    \".svg\": \"image/svg+xml\",\n    \".xlsx\": \"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\",\n    \".docx\": \"application/vnd.openxmlformats-officedocument.wordprocessingml.document\",\n    \".pptx\": \"application/vnd.openxmlformats-officedocument.presentationml.presentation\",\n}\n\n\ndef get_mime_type(path: Path) -> str:\n    ext = path.suffix.lower()\n    if ext in MIME_OVERRIDES:\n        return MIME_OVERRIDES[ext]\n    mime, _ = mimetypes.guess_type(str(path))\n    return mime or \"application/octet-stream\"\n\n\ndef find_runs(workspace: Path) -> list[dict]:\n    \"\"\"Recursively find directories that contain an outputs/ subdirectory.\"\"\"\n    runs: list[dict] = []\n    _find_runs_recursive(workspace, workspace, runs)\n    runs.sort(key=lambda r: (r.get(\"eval_id\", float(\"inf\")), r[\"id\"]))\n    return runs\n\n\ndef _find_runs_recursive(root: Path, current: Path, runs: list[dict]) -> None:\n    if not current.is_dir():\n        return\n\n    outputs_dir = current / \"outputs\"\n    if outputs_dir.is_dir():\n        run = build_run(root, current)\n        if run:\n            runs.append(run)\n        return\n\n    skip = {\"node_modules\", \".git\", \"__pycache__\", \"skill\", \"inputs\"}\n    for child in sorted(current.iterdir()):\n        if child.is_dir() and child.name not in skip:\n            _find_runs_recursive(root, child, runs)\n\n\ndef build_run(root: Path, run_dir: Path) -> dict | None:\n    \"\"\"Build a run dict with prompt, outputs, and grading data.\"\"\"\n    prompt = \"\"\n    eval_id = None\n\n    # Try eval_metadata.json\n    for candidate in [run_dir / \"eval_metadata.json\", run_dir.parent / \"eval_metadata.json\"]:\n        if candidate.exists():\n            try:\n                metadata = json.loads(candidate.read_text())\n                prompt = metadata.get(\"prompt\", \"\")\n                eval_id = metadata.get(\"eval_id\")\n            except (json.JSONDecodeError, OSError):\n                pass\n            if prompt:\n                break\n\n    # Fall back to transcript.md\n    if not prompt:\n        for candidate in [run_dir / \"transcript.md\", run_dir / \"outputs\" / \"transcript.md\"]:\n            if candidate.exists():\n                try:\n                    text = candidate.read_text()\n                    match = re.search(r\"## Eval Prompt\\n\\n([\\s\\S]*?)(?=\\n##|$)\", text)\n                    if match:\n                        prompt = match.group(1).strip()\n                except OSError:\n                    pass\n                if prompt:\n                    break\n\n    if not prompt:\n        prompt = \"(No prompt found)\"\n\n    run_id = str(run_dir.relative_to(root)).replace(\"/\", \"-\").replace(\"\\\\\", \"-\")\n\n    # Collect output files\n    outputs_dir = run_dir / \"outputs\"\n    output_files: list[dict] = []\n    if outputs_dir.is_dir():\n        for f in sorted(outputs_dir.iterdir()):\n            if f.is_file() and f.name not in METADATA_FILES:\n                output_files.append(embed_file(f))\n\n    # Load grading if present\n    grading = None\n    for candidate in [run_dir / \"grading.json\", run_dir.parent / \"grading.json\"]:\n        if candidate.exists():\n            try:\n                grading = json.loads(candidate.read_text())\n            except (json.JSONDecodeError, OSError):\n                pass\n            if grading:\n                break\n\n    return {\n        \"id\": run_id,\n        \"prompt\": prompt,\n        \"eval_id\": eval_id,\n        \"outputs\": output_files,\n        \"grading\": grading,\n    }\n\n\ndef embed_file(path: Path) -> dict:\n    \"\"\"Read a file and return an embedded representation.\"\"\"\n    ext = path.suffix.lower()\n    mime = get_mime_type(path)\n\n    if ext in TEXT_EXTENSIONS:\n        try:\n            content = path.read_text(errors=\"replace\")\n        except OSError:\n            content = \"(Error reading file)\"\n        return {\n            \"name\": path.name,\n            \"type\": \"text\",\n            \"content\": content,\n        }\n    elif ext in IMAGE_EXTENSIONS:\n        try:\n            raw = path.read_bytes()\n            b64 = base64.b64encode(raw).decode(\"ascii\")\n        except OSError:\n            return {\"name\": path.name, \"type\": \"error\", \"content\": \"(Error reading file)\"}\n        return {\n            \"name\": path.name,\n            \"type\": \"image\",\n            \"mime\": mime,\n            \"data_uri\": f\"data:{mime};base64,{b64}\",\n        }\n    elif ext == \".pdf\":\n        try:\n            raw = path.read_bytes()\n            b64 = base64.b64encode(raw).decode(\"ascii\")\n        except OSError:\n            return {\"name\": path.name, \"type\": \"error\", \"content\": \"(Error reading file)\"}\n        return {\n            \"name\": path.name,\n            \"type\": \"pdf\",\n            \"data_uri\": f\"data:{mime};base64,{b64}\",\n        }\n    elif ext == \".xlsx\":\n        try:\n            raw = path.read_bytes()\n            b64 = base64.b64encode(raw).decode(\"ascii\")\n        except OSError:\n            return {\"name\": path.name, \"type\": \"error\", \"content\": \"(Error reading file)\"}\n        return {\n            \"name\": path.name,\n            \"type\": \"xlsx\",\n            \"data_b64\": b64,\n        }\n    else:\n        # Binary / unknown — base64 download link\n        try:\n            raw = path.read_bytes()\n            b64 = base64.b64encode(raw).decode(\"ascii\")\n        except OSError:\n            return {\"name\": path.name, \"type\": \"error\", \"content\": \"(Error reading file)\"}\n        return {\n            \"name\": path.name,\n            \"type\": \"binary\",\n            \"mime\": mime,\n            \"data_uri\": f\"data:{mime};base64,{b64}\",\n        }\n\n\ndef load_previous_iteration(workspace: Path) -> dict[str, dict]:\n    \"\"\"Load previous iteration\'s feedback and outputs.\n\n    Returns a map of run_id -> {\"feedback\": str, \"outputs\": list[dict]}.\n    \"\"\"\n    result: dict[str, dict] = {}\n\n    # Load feedback\n    feedback_map: dict[str, str] = {}\n    feedback_path = workspace / \"feedback.json\"\n    if feedback_path.exists():\n        try:\n            data = json.loads(feedback_path.read_text())\n            feedback_map = {\n                r[\"run_id\"]: r[\"feedback\"]\n                for r in data.get(\"reviews\", [])\n                if r.get(\"feedback\", \"\").strip()\n            }\n        except (json.JSONDecodeError, OSError, KeyError):\n            pass\n\n    # Load runs (to get outputs)\n    prev_runs = find_runs(workspace)\n    for run in prev_runs:\n        result[run[\"id\"]] = {\n            \"feedback\": feedback_map.get(run[\"id\"], \"\"),\n            \"outputs\": run.get(\"outputs\", []),\n        }\n\n    # Also add feedback for run_ids that had feedback but no matching run\n    for run_id, fb in feedback_map.items():\n        if run_id not in result:\n            result[run_id] = {\"feedback\": fb, \"outputs\": []}\n\n    return result\n\n\ndef generate_html(\n    runs: list[dict],\n    skill_name: str,\n    previous: dict[str, dict] | None = None,\n    benchmark: dict | None = None,\n) -> str:\n    \"\"\"Generate the complete standalone HTML page with embedded data.\"\"\"\n    template_path = Path(__file__).parent / \"viewer.html\"\n    template = template_path.read_text()\n\n    # Build previous_feedback and previous_outputs maps for the template\n    previous_feedback: dict[str, str] = {}\n    previous_outputs: dict[str, list[dict]] = {}\n    if previous:\n        for run_id, data in previous.items():\n            if data.get(\"feedback\"):\n                previous_feedback[run_id] = data[\"feedback\"]\n            if data.get(\"outputs\"):\n                previous_outputs[run_id] = data[\"outputs\"]\n\n    embedded = {\n        \"skill_name\": skill_name,\n        \"runs\": runs,\n        \"previous_feedback\": previous_feedback,\n        \"previous_outputs\": previous_outputs,\n    }\n    if benchmark:\n        embedded[\"benchmark\"] = benchmark\n\n    data_json = json.dumps(embedded)\n\n    return template.replace(\"/*__EMBEDDED_DATA__*/\", f\"const EMBEDDED_DATA = {data_json};\")\n\n\n# ---------------------------------------------------------------------------\n# HTTP server (stdlib only, zero dependencies)\n# ---------------------------------------------------------------------------\n\ndef _kill_port(port: int) -> None:\n    \"\"\"Kill any process listening on the given port.\"\"\"\n    try:\n        result = subprocess.run(\n            [\"lsof\", \"-ti\", f\":{port}\"],\n            capture_output=True, text=True, timeout=5,\n        )\n        for pid_str in result.stdout.strip().split(\"\\n\"):\n            if pid_str.strip():\n                try:\n                    os.kill(int(pid_str.strip()), signal.SIGTERM)\n                except (ProcessLookupError, ValueError):\n                    pass\n        if result.stdout.strip():\n            time.sleep(0.5)\n    except subprocess.TimeoutExpired:\n        pass\n    except FileNotFoundError:\n        print(\"Note: lsof not found, cannot check if port is in use\", file=sys.stderr)\n\nclass ReviewHandler(BaseHTTPRequestHandler):\n    \"\"\"Serves the review HTML and handles feedback saves.\n\n    Regenerates the HTML on each page load so that refreshing the browser\n    picks up new eval outputs without restarting the server.\n    \"\"\"\n\n    def __init__(\n        self,\n        workspace: Path,\n        skill_name: str,\n        feedback_path: Path,\n        previous: dict[str, dict],\n        benchmark_path: Path | None,\n        *args,\n        **kwargs,\n    ):\n        self.workspace = workspace\n        self.skill_name = skill_name\n        self.feedback_path = feedback_path\n        self.previous = previous\n        self.benchmark_path = benchmark_path\n        super().__init__(*args, **kwargs)\n\n    def do_GET(self) -> None:\n        if self.path == \"/\" or self.path == \"/index.html\":\n            # Regenerate HTML on each request (re-scans workspace for new outputs)\n            runs = find_runs(self.workspace)\n            benchmark = None\n            if self.benchmark_path and self.benchmark_path.exists():\n                try:\n                    benchmark = json.loads(self.benchmark_path.read_text())\n                except (json.JSONDecodeError, OSError):\n                    pass\n            html = generate_html(runs, self.skill_name, self.previous, benchmark)\n            content = html.encode(\"utf-8\")\n            self.send_response(200)\n            self.send_header(\"Content-Type\", \"text/html; charset=utf-8\")\n            self.send_header(\"Content-Length\", str(len(content)))\n            self.end_headers()\n            self.wfile.write(content)\n        elif self.path == \"/api/feedback\":\n            data = b\"{}\"\n            if self.feedback_path.exists():\n                data = self.feedback_path.read_bytes()\n            self.send_response(200)\n            self.send_header(\"Content-Type\", \"application/json\")\n            self.send_header(\"Content-Length\", str(len(data)))\n            self.end_headers()\n            self.wfile.write(data)\n        else:\n            self.send_error(404)\n\n    def do_POST(self) -> None:\n        if self.path == \"/api/feedback\":\n            length = int(self.headers.get(\"Content-Length\", 0))\n            body = self.rfile.read(length)\n            try:\n                data = json.loads(body)\n                if not isinstance(data, dict) or \"reviews\" not in data:\n                    raise ValueError(\"Expected JSON object with \'reviews\' key\")\n                self.feedback_path.write_text(json.dumps(data, indent=2) + \"\\n\")\n                resp = b\'{\"ok\":true}\'\n                self.send_response(200)\n            except (json.JSONDecodeError, OSError, ValueError) as e:\n                resp = json.dumps({\"error\": str(e)}).encode()\n                self.send_response(500)\n            self.send_header(\"Content-Type\", \"application/json\")\n            self.send_header(\"Content-Length\", str(len(resp)))\n            self.end_headers()\n            self.wfile.write(resp)\n        else:\n            self.send_error(404)\n\n    def log_message(self, format: str, *args: object) -> None:\n        # Suppress request logging to keep terminal clean\n        pass\n\n\ndef main() -> None:\n    parser = argparse.ArgumentParser(description=\"Generate and serve eval review\")\n    parser.add_argument(\"workspace\", type=Path, help=\"Path to workspace directory\")\n    parser.add_argument(\"--port\", \"-p\", type=int, default=3117, help=\"Server port (default: 3117)\")\n    parser.add_argument(\"--skill-name\", \"-n\", type=str, default=None, help=\"Skill name for header\")\n    parser.add_argument(\n        \"--previous-workspace\", type=Path, default=None,\n        help=\"Path to previous iteration\'s workspace (shows old outputs and feedback as context)\",\n    )\n    parser.add_argument(\n        \"--benchmark\", type=Path, default=None,\n        help=\"Path to benchmark.json to show in the Benchmark tab\",\n    )\n    parser.add_argument(\n        \"--static\", \"-s\", type=Path, default=None,\n        help=\"Write standalone HTML to this path instead of starting a server\",\n    )\n    args = parser.parse_args()\n\n    workspace = args.workspace.resolve()\n    if not workspace.is_dir():\n        print(f\"Error: {workspace} is not a directory\", file=sys.stderr)\n        sys.exit(1)\n\n    runs = find_runs(workspace)\n    if not runs:\n        print(f\"No runs found in {workspace}\", file=sys.stderr)\n        sys.exit(1)\n\n    skill_name = args.skill_name or workspace.name.replace(\"-workspace\", \"\")\n    feedback_path = workspace / \"feedback.json\"\n\n    previous: dict[str, dict] = {}\n    if args.previous_workspace:\n        previous = load_previous_iteration(args.previous_workspace.resolve())\n\n    benchmark_path = args.benchmark.resolve() if args.benchmark else None\n    benchmark = None\n    if benchmark_path and benchmark_path.exists():\n        try:\n            benchmark = json.loads(benchmark_path.read_text())\n        except (json.JSONDecodeError, OSError):\n            pass\n\n    if args.static:\n        html = generate_html(runs, skill_name, previous, benchmark)\n        args.static.parent.mkdir(parents=True, exist_ok=True)\n        args.static.write_text(html)\n        print(f\"\\n  Static viewer written to: {args.static}\\n\")\n        sys.exit(0)\n\n    # Kill any existing process on the target port\n    port = args.port\n    _kill_port(port)\n    handler = partial(ReviewHandler, workspace, skill_name, feedback_path, previous, benchmark_path)\n    try:\n        server = HTTPServer((\"127.0.0.1\", port), handler)\n    except OSError:\n        # Port still in use after kill attempt — find a free one\n        server = HTTPServer((\"127.0.0.1\", 0), handler)\n        port = server.server_address[1]\n\n    url = f\"http://localhost:{port}\"\n    print(f\"\\n  Eval Viewer\")\n    print(f\"  ─────────────────────────────────\")\n    print(f\"  URL:       {url}\")\n    print(f\"  Workspace: {workspace}\")\n    print(f\"  Feedback:  {feedback_path}\")\n    if previous:\n        print(f\"  Previous:  {args.previous_workspace} ({len(previous)} runs)\")\n    if benchmark_path:\n        print(f\"  Benchmark: {benchmark_path}\")\n    print(f\"\\n  Press Ctrl+C to stop.\\n\")\n\n    webbrowser.open(url)\n\n    try:\n        server.serve_forever()\n    except KeyboardInterrupt:\n        print(\"\\nStopped.\")\n        server.server_close()\n\n\nif __name__ == \"__main__\":\n    main()\n','d7f883f3d3596e62618faecf298c4f5f','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(1237,'resource_config_IDENTITY__md.json','agentspec__enc.656e67696e656572696e672d736f6c69646974792d736d6172742d636f6e74726163742d656e67696e656572__enc.302e302e31','{\"name\":\"IDENTITY.md\",\"type\":\"config\",\"content\":\"# Solidity 智能合约工程师\\n精通 EVM 智能合约架构、Gas 优化、可升级代理模式、DeFi 协议开发和安全优先合约设计的 Solidity 开发专家，覆盖 Ethereum 及 L2 链。\\n\",\"metadata\":{\"uniformId\":1792984920326},\"resourceIdentifier\":\"config::IDENTITY.md\"}','0cc4422e3f76d131efd8578393d2a74d','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(1238,'skill_index.json','skill_pptx','{\"labels\":{\"latest\":\"0.0.1\"},\"versions\":{\"0.0.1\":[\"SKILL.md\",\"scripts/office/schemas/ecma/fouth-edition/opc-digSig.xsd\",\"scripts/clean.py\",\"scripts/office/validators/__init__.py\",\"LICENSE.txt\",\"scripts/office/schemas/microsoft/wml-cex-2018.xsd\",\"editing.md\",\"scripts/office/schemas/ISO-IEC29500-4_2016/dml-main.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/shared-math.xsd\",\"scripts/office/validators/redlining.py\",\"scripts/office/validate.py\",\"scripts/office/validators/docx.py\",\"scripts/office/helpers/merge_runs.py\",\"scripts/office/schemas/ISO-IEC29500-4_2016/vml-spreadsheetDrawing.xsd\",\"scripts/office/helpers/simplify_redlines.py\",\"scripts/office/schemas/ISO-IEC29500-4_2016/dml-spreadsheetDrawing.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/sml.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/shared-documentPropertiesVariantTypes.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/dml-diagram.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/shared-customXmlDataProperties.xsd\",\"scripts/__init__.py\",\"scripts/office/schemas/ISO-IEC29500-4_2016/vml-officeDrawing.xsd\",\"scripts/office/schemas/microsoft/wml-2010.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/dml-lockedCanvas.xsd\",\"scripts/office/schemas/ecma/fouth-edition/opc-contentTypes.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/wml.xsd\",\"scripts/office/schemas/mce/mc.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/vml-presentationDrawing.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/shared-documentPropertiesExtended.xsd\",\"pptxgenjs.md\",\"scripts/thumbnail.py\",\"scripts/office/schemas/ISO-IEC29500-4_2016/shared-commonSimpleTypes.xsd\",\"scripts/office/schemas/ecma/fouth-edition/opc-relationships.xsd\",\"scripts/office/validators/base.py\",\"scripts/office/schemas/microsoft/wml-2018.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/dml-picture.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/vml-main.xsd\",\"scripts/office/schemas/microsoft/wml-2012.xsd\",\"scripts/office/helpers/__init__.py\",\"scripts/office/schemas/ISO-IEC29500-4_2016/vml-wordprocessingDrawing.xsd\",\"scripts/office/schemas/microsoft/wml-symex-2015.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/shared-documentPropertiesCustom.xsd\",\"scripts/office/schemas/microsoft/wml-cid-2016.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/shared-relationshipReference.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/dml-chartDrawing.xsd\",\"scripts/office/unpack.py\",\"scripts/office/schemas/ISO-IEC29500-4_2016/dml-chart.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/dml-wordprocessingDrawing.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/shared-additionalCharacteristics.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/shared-customXmlSchemaProperties.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/pml.xsd\",\"scripts/office/schemas/ecma/fouth-edition/opc-coreProperties.xsd\",\"scripts/office/validators/pptx.py\",\"scripts/office/soffice.py\",\"scripts/office/schemas/ISO-IEC29500-4_2016/shared-bibliography.xsd\",\"scripts/office/schemas/ISO-IEC29500-4_2016/xml.xsd\",\"scripts/office/schemas/microsoft/wml-sdtdatahash-2020.xsd\",\"scripts/add_slide.py\",\"scripts/office/pack.py\"]}}','dd643ae91b03e129e3cc1029c1cf4997','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,'');
INSERT INTO `config_info` VALUES (1239,'enc.636f72652f6769665f6275696c6465722e7079','skill_enc.736c61636b2d6769662d63726561746f72__enc.302e302e31','#!/usr/bin/env python3\n\"\"\"\nGIF Builder - Core module for assembling frames into GIFs optimized for Slack.\n\nThis module provides the main interface for creating GIFs from programmatically\ngenerated frames, with automatic optimization for Slack\'s requirements.\n\"\"\"\n\nfrom pathlib import Path\nfrom typing import Optional\n\nimport imageio.v3 as imageio\nimport numpy as np\nfrom PIL import Image\n\n\nclass GIFBuilder:\n    \"\"\"Builder for creating optimized GIFs from frames.\"\"\"\n\n    def __init__(self, width: int = 480, height: int = 480, fps: int = 15):\n        \"\"\"\n        Initialize GIF builder.\n\n        Args:\n            width: Frame width in pixels\n            height: Frame height in pixels\n            fps: Frames per second\n        \"\"\"\n        self.width = width\n        self.height = height\n        self.fps = fps\n        self.frames: list[np.ndarray] = []\n\n    def add_frame(self, frame: np.ndarray | Image.Image):\n        \"\"\"\n        Add a frame to the GIF.\n\n        Args:\n            frame: Frame as numpy array or PIL Image (will be converted to RGB)\n        \"\"\"\n        if isinstance(frame, Image.Image):\n            frame = np.array(frame.convert(\"RGB\"))\n\n        # Ensure frame is correct size\n        if frame.shape[:2] != (self.height, self.width):\n            pil_frame = Image.fromarray(frame)\n            pil_frame = pil_frame.resize(\n                (self.width, self.height), Image.Resampling.LANCZOS\n            )\n            frame = np.array(pil_frame)\n\n        self.frames.append(frame)\n\n    def add_frames(self, frames: list[np.ndarray | Image.Image]):\n        \"\"\"Add multiple frames at once.\"\"\"\n        for frame in frames:\n            self.add_frame(frame)\n\n    def optimize_colors(\n        self, num_colors: int = 128, use_global_palette: bool = True\n    ) -> list[np.ndarray]:\n        \"\"\"\n        Reduce colors in all frames using quantization.\n\n        Args:\n            num_colors: Target number of colors (8-256)\n            use_global_palette: Use a single palette for all frames (better compression)\n\n        Returns:\n            List of color-optimized frames\n        \"\"\"\n        optimized = []\n\n        if use_global_palette and len(self.frames) > 1:\n            # Create a global palette from all frames\n            # Sample frames to build palette\n            sample_size = min(5, len(self.frames))\n            sample_indices = [\n                int(i * len(self.frames) / sample_size) for i in range(sample_size)\n            ]\n            sample_frames = [self.frames[i] for i in sample_indices]\n\n            # Combine sample frames into a single image for palette generation\n            # Flatten each frame to get all pixels, then stack them\n            all_pixels = np.vstack(\n                [f.reshape(-1, 3) for f in sample_frames]\n            )  # (total_pixels, 3)\n\n            # Create a properly-shaped RGB image from the pixel data\n            # We\'ll make a roughly square image from all the pixels\n            total_pixels = len(all_pixels)\n            width = min(512, int(np.sqrt(total_pixels)))  # Reasonable width, max 512\n            height = (total_pixels + width - 1) // width  # Ceiling division\n\n            # Pad if necessary to fill the rectangle\n            pixels_needed = width * height\n            if pixels_needed > total_pixels:\n                padding = np.zeros((pixels_needed - total_pixels, 3), dtype=np.uint8)\n                all_pixels = np.vstack([all_pixels, padding])\n\n            # Reshape to proper RGB image format (H, W, 3)\n            img_array = (\n                all_pixels[:pixels_needed].reshape(height, width, 3).astype(np.uint8)\n            )\n            combined_img = Image.fromarray(img_array, mode=\"RGB\")\n\n            # Generate global palette\n            global_palette = combined_img.quantize(colors=num_colors, method=2)\n\n            # Apply global palette to all frames\n            for frame in self.frames:\n                pil_frame = Image.fromarray(frame)\n                quantized = pil_frame.quantize(palette=global_palette, dither=1)\n                optimized.append(np.array(quantized.convert(\"RGB\")))\n        else:\n            # Use per-frame quantization\n            for frame in self.frames:\n                pil_frame = Image.fromarray(frame)\n                quantized = pil_frame.quantize(colors=num_colors, method=2, dither=1)\n                optimized.append(np.array(quantized.convert(\"RGB\")))\n\n        return optimized\n\n    def deduplicate_frames(self, threshold: float = 0.9995) -> int:\n        \"\"\"\n        Remove duplicate or near-duplicate consecutive frames.\n\n        Args:\n            threshold: Similarity threshold (0.0-1.0). Higher = more strict (0.9995 = nearly identical).\n                      Use 0.9995+ to preserve subtle animations, 0.98 for aggressive removal.\n\n        Returns:\n            Number of frames removed\n        \"\"\"\n        if len(self.frames) < 2:\n            return 0\n\n        deduplicated = [self.frames[0]]\n        removed_count = 0\n\n        for i in range(1, len(self.frames)):\n            # Compare with previous frame\n            prev_frame = np.array(deduplicated[-1], dtype=np.float32)\n            curr_frame = np.array(self.frames[i], dtype=np.float32)\n\n            # Calculate similarity (normalized)\n            diff = np.abs(prev_frame - curr_frame)\n            similarity = 1.0 - (np.mean(diff) / 255.0)\n\n            # Keep frame if sufficiently different\n            # High threshold (0.9995+) means only remove nearly identical frames\n            if similarity < threshold:\n                deduplicated.append(self.frames[i])\n            else:\n                removed_count += 1\n\n        self.frames = deduplicated\n        return removed_count\n\n    def save(\n        self,\n        output_path: str | Path,\n        num_colors: int = 128,\n        optimize_for_emoji: bool = False,\n        remove_duplicates: bool = False,\n    ) -> dict:\n        \"\"\"\n        Save frames as optimized GIF for Slack.\n\n        Args:\n            output_path: Where to save the GIF\n            num_colors: Number of colors to use (fewer = smaller file)\n            optimize_for_emoji: If True, optimize for emoji size (128x128, fewer colors)\n            remove_duplicates: If True, remove duplicate consecutive frames (opt-in)\n\n        Returns:\n            Dictionary with file info (path, size, dimensions, frame_count)\n        \"\"\"\n        if not self.frames:\n            raise ValueError(\"No frames to save. Add frames with add_frame() first.\")\n\n        output_path = Path(output_path)\n\n        # Remove duplicate frames to reduce file size\n        if remove_duplicates:\n            removed = self.deduplicate_frames(threshold=0.9995)\n            if removed > 0:\n                print(\n                    f\"  Removed {removed} nearly identical frames (preserved subtle animations)\"\n                )\n\n        # Optimize for emoji if requested\n        if optimize_for_emoji:\n            if self.width > 128 or self.height > 128:\n                print(\n                    f\"  Resizing from {self.width}x{self.height} to 128x128 for emoji\"\n                )\n                self.width = 128\n                self.height = 128\n                # Resize all frames\n                resized_frames = []\n                for frame in self.frames:\n                    pil_frame = Image.fromarray(frame)\n                    pil_frame = pil_frame.resize((128, 128), Image.Resampling.LANCZOS)\n                    resized_frames.append(np.array(pil_frame))\n                self.frames = resized_frames\n            num_colors = min(num_colors, 48)  # More aggressive color limit for emoji\n\n            # More aggressive FPS reduction for emoji\n            if len(self.frames) > 12:\n                print(\n                    f\"  Reducing frames from {len(self.frames)} to ~12 for emoji size\"\n                )\n                # Keep every nth frame to get close to 12 frames\n                keep_every = max(1, len(self.frames) // 12)\n                self.frames = [\n                    self.frames[i] for i in range(0, len(self.frames), keep_every)\n                ]\n\n        # Optimize colors with global palette\n        optimized_frames = self.optimize_colors(num_colors, use_global_palette=True)\n\n        # Calculate frame duration in milliseconds\n        frame_duration = 1000 / self.fps\n\n        # Save GIF\n        imageio.imwrite(\n            output_path,\n            optimized_frames,\n            duration=frame_duration,\n            loop=0,  # Infinite loop\n        )\n\n        # Get file info\n        file_size_kb = output_path.stat().st_size / 1024\n        file_size_mb = file_size_kb / 1024\n\n        info = {\n            \"path\": str(output_path),\n            \"size_kb\": file_size_kb,\n            \"size_mb\": file_size_mb,\n            \"dimensions\": f\"{self.width}x{self.height}\",\n            \"frame_count\": len(optimized_frames),\n            \"fps\": self.fps,\n            \"duration_seconds\": len(optimized_frames) / self.fps,\n            \"colors\": num_colors,\n        }\n\n        # Print info\n        print(f\"\\n✓ GIF created successfully!\")\n        print(f\"  Path: {output_path}\")\n        print(f\"  Size: {file_size_kb:.1f} KB ({file_size_mb:.2f} MB)\")\n        print(f\"  Dimensions: {self.width}x{self.height}\")\n        print(f\"  Frames: {len(optimized_frames)} @ {self.fps} fps\")\n        print(f\"  Duration: {info[\'duration_seconds\']:.1f}s\")\n        print(f\"  Colors: {num_colors}\")\n\n        # Size info\n        if optimize_for_emoji:\n            print(f\"  Optimized for emoji (128x128, reduced colors)\")\n        if file_size_mb > 1.0:\n            print(f\"\\n  Note: Large file size ({file_size_kb:.1f} KB)\")\n            print(\"  Consider: fewer frames, smaller dimensions, or fewer colors\")\n\n        return info\n\n    def clear(self):\n        \"\"\"Clear all frames (useful for creating multiple GIFs).\"\"\"\n        self.frames = []\n','ad49e19c1e0219bc0e4156a5d8d240fe','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(1240,'resource_tool-analysis_tool-analysis__json.json','agentspec__enc.656e67696e656572696e672d736f6c69646974792d736d6172742d636f6e74726163742d656e67696e656572__enc.302e302e31','{\"name\":\"tool-analysis.json\",\"type\":\"tool-analysis\",\"content\":\"{\\n  \\\"version\\\": \\\"1.0\\\",\\n  \\\"notes\\\": \\\"Static export from agency-agents-zh OpenClaw conversion; not a runtime tool scan.\\\",\\n  \\\"packages\\\": { \\\"apt\\\": [], \\\"pip\\\": [], \\\"npm\\\": [] }\\n}\\n\",\"metadata\":{\"uniformId\":1792984920326},\"resourceIdentifier\":\"tool-analysis::tool-analysis.json\"}','4d383245d04aa41062712d1f41996ead','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(1241,'enc.636f72652f6672616d655f636f6d706f7365722e7079','skill_enc.736c61636b2d6769662d63726561746f72__enc.302e302e31','#!/usr/bin/env python3\n\"\"\"\nFrame Composer - Utilities for composing visual elements into frames.\n\nProvides functions for drawing shapes, text, emojis, and compositing elements\ntogether to create animation frames.\n\"\"\"\n\nfrom typing import Optional\n\nimport numpy as np\nfrom PIL import Image, ImageDraw, ImageFont\n\n\ndef create_blank_frame(\n    width: int, height: int, color: tuple[int, int, int] = (255, 255, 255)\n) -> Image.Image:\n    \"\"\"\n    Create a blank frame with solid color background.\n\n    Args:\n        width: Frame width\n        height: Frame height\n        color: RGB color tuple (default: white)\n\n    Returns:\n        PIL Image\n    \"\"\"\n    return Image.new(\"RGB\", (width, height), color)\n\n\ndef draw_circle(\n    frame: Image.Image,\n    center: tuple[int, int],\n    radius: int,\n    fill_color: Optional[tuple[int, int, int]] = None,\n    outline_color: Optional[tuple[int, int, int]] = None,\n    outline_width: int = 1,\n) -> Image.Image:\n    \"\"\"\n    Draw a circle on a frame.\n\n    Args:\n        frame: PIL Image to draw on\n        center: (x, y) center position\n        radius: Circle radius\n        fill_color: RGB fill color (None for no fill)\n        outline_color: RGB outline color (None for no outline)\n        outline_width: Outline width in pixels\n\n    Returns:\n        Modified frame\n    \"\"\"\n    draw = ImageDraw.Draw(frame)\n    x, y = center\n    bbox = [x - radius, y - radius, x + radius, y + radius]\n    draw.ellipse(bbox, fill=fill_color, outline=outline_color, width=outline_width)\n    return frame\n\n\ndef draw_text(\n    frame: Image.Image,\n    text: str,\n    position: tuple[int, int],\n    color: tuple[int, int, int] = (0, 0, 0),\n    centered: bool = False,\n) -> Image.Image:\n    \"\"\"\n    Draw text on a frame.\n\n    Args:\n        frame: PIL Image to draw on\n        text: Text to draw\n        position: (x, y) position (top-left unless centered=True)\n        color: RGB text color\n        centered: If True, center text at position\n\n    Returns:\n        Modified frame\n    \"\"\"\n    draw = ImageDraw.Draw(frame)\n\n    # Uses Pillow\'s default font.\n    # If the font should be changed for the emoji, add additional logic here.\n    font = ImageFont.load_default()\n\n    if centered:\n        bbox = draw.textbbox((0, 0), text, font=font)\n        text_width = bbox[2] - bbox[0]\n        text_height = bbox[3] - bbox[1]\n        x = position[0] - text_width // 2\n        y = position[1] - text_height // 2\n        position = (x, y)\n\n    draw.text(position, text, fill=color, font=font)\n    return frame\n\n\ndef create_gradient_background(\n    width: int,\n    height: int,\n    top_color: tuple[int, int, int],\n    bottom_color: tuple[int, int, int],\n) -> Image.Image:\n    \"\"\"\n    Create a vertical gradient background.\n\n    Args:\n        width: Frame width\n        height: Frame height\n        top_color: RGB color at top\n        bottom_color: RGB color at bottom\n\n    Returns:\n        PIL Image with gradient\n    \"\"\"\n    frame = Image.new(\"RGB\", (width, height))\n    draw = ImageDraw.Draw(frame)\n\n    # Calculate color step for each row\n    r1, g1, b1 = top_color\n    r2, g2, b2 = bottom_color\n\n    for y in range(height):\n        # Interpolate color\n        ratio = y / height\n        r = int(r1 * (1 - ratio) + r2 * ratio)\n        g = int(g1 * (1 - ratio) + g2 * ratio)\n        b = int(b1 * (1 - ratio) + b2 * ratio)\n\n        # Draw horizontal line\n        draw.line([(0, y), (width, y)], fill=(r, g, b))\n\n    return frame\n\n\ndef draw_star(\n    frame: Image.Image,\n    center: tuple[int, int],\n    size: int,\n    fill_color: tuple[int, int, int],\n    outline_color: Optional[tuple[int, int, int]] = None,\n    outline_width: int = 1,\n) -> Image.Image:\n    \"\"\"\n    Draw a 5-pointed star.\n\n    Args:\n        frame: PIL Image to draw on\n        center: (x, y) center position\n        size: Star size (outer radius)\n        fill_color: RGB fill color\n        outline_color: RGB outline color (None for no outline)\n        outline_width: Outline width\n\n    Returns:\n        Modified frame\n    \"\"\"\n    import math\n\n    draw = ImageDraw.Draw(frame)\n    x, y = center\n\n    # Calculate star points\n    points = []\n    for i in range(10):\n        angle = (i * 36 - 90) * math.pi / 180  # 36 degrees per point, start at top\n        radius = size if i % 2 == 0 else size * 0.4  # Alternate between outer and inner\n        px = x + radius * math.cos(angle)\n        py = y + radius * math.sin(angle)\n        points.append((px, py))\n\n    # Draw star\n    draw.polygon(points, fill=fill_color, outline=outline_color, width=outline_width)\n\n    return frame\n','12b7331866a67b0653b2c8e026210637','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(1242,'resource_config_IDENTITY__md.json','agentspec__enc.656e67696e656572696e672d736f6c69646974792d736d6172742d636f6e74726163742d656e67696e656572__enc.302e302e31','{\"name\":\"IDENTITY.md\",\"type\":\"config\",\"content\":\"# Solidity 智能合约工程师\\n精通 EVM 智能合约架构、Gas 优化、可升级代理模式、DeFi 协议开发和安全优先合约设计的 Solidity 开发专家，覆盖 Ethereum 及 L2 链。\\n\",\"metadata\":{\"uniformId\":1792984920326},\"resourceIdentifier\":\"config::IDENTITY.md\"}','0cc4422e3f76d131efd8578393d2a74d','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(1243,'enc.636f72652f6769665f6275696c6465722e7079','skill_enc.736c61636b2d6769662d63726561746f72__enc.302e302e31','#!/usr/bin/env python3\n\"\"\"\nGIF Builder - Core module for assembling frames into GIFs optimized for Slack.\n\nThis module provides the main interface for creating GIFs from programmatically\ngenerated frames, with automatic optimization for Slack\'s requirements.\n\"\"\"\n\nfrom pathlib import Path\nfrom typing import Optional\n\nimport imageio.v3 as imageio\nimport numpy as np\nfrom PIL import Image\n\n\nclass GIFBuilder:\n    \"\"\"Builder for creating optimized GIFs from frames.\"\"\"\n\n    def __init__(self, width: int = 480, height: int = 480, fps: int = 15):\n        \"\"\"\n        Initialize GIF builder.\n\n        Args:\n            width: Frame width in pixels\n            height: Frame height in pixels\n            fps: Frames per second\n        \"\"\"\n        self.width = width\n        self.height = height\n        self.fps = fps\n        self.frames: list[np.ndarray] = []\n\n    def add_frame(self, frame: np.ndarray | Image.Image):\n        \"\"\"\n        Add a frame to the GIF.\n\n        Args:\n            frame: Frame as numpy array or PIL Image (will be converted to RGB)\n        \"\"\"\n        if isinstance(frame, Image.Image):\n            frame = np.array(frame.convert(\"RGB\"))\n\n        # Ensure frame is correct size\n        if frame.shape[:2] != (self.height, self.width):\n            pil_frame = Image.fromarray(frame)\n            pil_frame = pil_frame.resize(\n                (self.width, self.height), Image.Resampling.LANCZOS\n            )\n            frame = np.array(pil_frame)\n\n        self.frames.append(frame)\n\n    def add_frames(self, frames: list[np.ndarray | Image.Image]):\n        \"\"\"Add multiple frames at once.\"\"\"\n        for frame in frames:\n            self.add_frame(frame)\n\n    def optimize_colors(\n        self, num_colors: int = 128, use_global_palette: bool = True\n    ) -> list[np.ndarray]:\n        \"\"\"\n        Reduce colors in all frames using quantization.\n\n        Args:\n            num_colors: Target number of colors (8-256)\n            use_global_palette: Use a single palette for all frames (better compression)\n\n        Returns:\n            List of color-optimized frames\n        \"\"\"\n        optimized = []\n\n        if use_global_palette and len(self.frames) > 1:\n            # Create a global palette from all frames\n            # Sample frames to build palette\n            sample_size = min(5, len(self.frames))\n            sample_indices = [\n                int(i * len(self.frames) / sample_size) for i in range(sample_size)\n            ]\n            sample_frames = [self.frames[i] for i in sample_indices]\n\n            # Combine sample frames into a single image for palette generation\n            # Flatten each frame to get all pixels, then stack them\n            all_pixels = np.vstack(\n                [f.reshape(-1, 3) for f in sample_frames]\n            )  # (total_pixels, 3)\n\n            # Create a properly-shaped RGB image from the pixel data\n            # We\'ll make a roughly square image from all the pixels\n            total_pixels = len(all_pixels)\n            width = min(512, int(np.sqrt(total_pixels)))  # Reasonable width, max 512\n            height = (total_pixels + width - 1) // width  # Ceiling division\n\n            # Pad if necessary to fill the rectangle\n            pixels_needed = width * height\n            if pixels_needed > total_pixels:\n                padding = np.zeros((pixels_needed - total_pixels, 3), dtype=np.uint8)\n                all_pixels = np.vstack([all_pixels, padding])\n\n            # Reshape to proper RGB image format (H, W, 3)\n            img_array = (\n                all_pixels[:pixels_needed].reshape(height, width, 3).astype(np.uint8)\n            )\n            combined_img = Image.fromarray(img_array, mode=\"RGB\")\n\n            # Generate global palette\n            global_palette = combined_img.quantize(colors=num_colors, method=2)\n\n            # Apply global palette to all frames\n            for frame in self.frames:\n                pil_frame = Image.fromarray(frame)\n                quantized = pil_frame.quantize(palette=global_palette, dither=1)\n                optimized.append(np.array(quantized.convert(\"RGB\")))\n        else:\n            # Use per-frame quantization\n            for frame in self.frames:\n                pil_frame = Image.fromarray(frame)\n                quantized = pil_frame.quantize(colors=num_colors, method=2, dither=1)\n                optimized.append(np.array(quantized.convert(\"RGB\")))\n\n        return optimized\n\n    def deduplicate_frames(self, threshold: float = 0.9995) -> int:\n        \"\"\"\n        Remove duplicate or near-duplicate consecutive frames.\n\n        Args:\n            threshold: Similarity threshold (0.0-1.0). Higher = more strict (0.9995 = nearly identical).\n                      Use 0.9995+ to preserve subtle animations, 0.98 for aggressive removal.\n\n        Returns:\n            Number of frames removed\n        \"\"\"\n        if len(self.frames) < 2:\n            return 0\n\n        deduplicated = [self.frames[0]]\n        removed_count = 0\n\n        for i in range(1, len(self.frames)):\n            # Compare with previous frame\n            prev_frame = np.array(deduplicated[-1], dtype=np.float32)\n            curr_frame = np.array(self.frames[i], dtype=np.float32)\n\n            # Calculate similarity (normalized)\n            diff = np.abs(prev_frame - curr_frame)\n            similarity = 1.0 - (np.mean(diff) / 255.0)\n\n            # Keep frame if sufficiently different\n            # High threshold (0.9995+) means only remove nearly identical frames\n            if similarity < threshold:\n                deduplicated.append(self.frames[i])\n            else:\n                removed_count += 1\n\n        self.frames = deduplicated\n        return removed_count\n\n    def save(\n        self,\n        output_path: str | Path,\n        num_colors: int = 128,\n        optimize_for_emoji: bool = False,\n        remove_duplicates: bool = False,\n    ) -> dict:\n        \"\"\"\n        Save frames as optimized GIF for Slack.\n\n        Args:\n            output_path: Where to save the GIF\n            num_colors: Number of colors to use (fewer = smaller file)\n            optimize_for_emoji: If True, optimize for emoji size (128x128, fewer colors)\n            remove_duplicates: If True, remove duplicate consecutive frames (opt-in)\n\n        Returns:\n            Dictionary with file info (path, size, dimensions, frame_count)\n        \"\"\"\n        if not self.frames:\n            raise ValueError(\"No frames to save. Add frames with add_frame() first.\")\n\n        output_path = Path(output_path)\n\n        # Remove duplicate frames to reduce file size\n        if remove_duplicates:\n            removed = self.deduplicate_frames(threshold=0.9995)\n            if removed > 0:\n                print(\n                    f\"  Removed {removed} nearly identical frames (preserved subtle animations)\"\n                )\n\n        # Optimize for emoji if requested\n        if optimize_for_emoji:\n            if self.width > 128 or self.height > 128:\n                print(\n                    f\"  Resizing from {self.width}x{self.height} to 128x128 for emoji\"\n                )\n                self.width = 128\n                self.height = 128\n                # Resize all frames\n                resized_frames = []\n                for frame in self.frames:\n                    pil_frame = Image.fromarray(frame)\n                    pil_frame = pil_frame.resize((128, 128), Image.Resampling.LANCZOS)\n                    resized_frames.append(np.array(pil_frame))\n                self.frames = resized_frames\n            num_colors = min(num_colors, 48)  # More aggressive color limit for emoji\n\n            # More aggressive FPS reduction for emoji\n            if len(self.frames) > 12:\n                print(\n                    f\"  Reducing frames from {len(self.frames)} to ~12 for emoji size\"\n                )\n                # Keep every nth frame to get close to 12 frames\n                keep_every = max(1, len(self.frames) // 12)\n                self.frames = [\n                    self.frames[i] for i in range(0, len(self.frames), keep_every)\n                ]\n\n        # Optimize colors with global palette\n        optimized_frames = self.optimize_colors(num_colors, use_global_palette=True)\n\n        # Calculate frame duration in milliseconds\n        frame_duration = 1000 / self.fps\n\n        # Save GIF\n        imageio.imwrite(\n            output_path,\n            optimized_frames,\n            duration=frame_duration,\n            loop=0,  # Infinite loop\n        )\n\n        # Get file info\n        file_size_kb = output_path.stat().st_size / 1024\n        file_size_mb = file_size_kb / 1024\n\n        info = {\n            \"path\": str(output_path),\n            \"size_kb\": file_size_kb,\n            \"size_mb\": file_size_mb,\n            \"dimensions\": f\"{self.width}x{self.height}\",\n            \"frame_count\": len(optimized_frames),\n            \"fps\": self.fps,\n            \"duration_seconds\": len(optimized_frames) / self.fps,\n            \"colors\": num_colors,\n        }\n\n        # Print info\n        print(f\"\\n✓ GIF created successfully!\")\n        print(f\"  Path: {output_path}\")\n        print(f\"  Size: {file_size_kb:.1f} KB ({file_size_mb:.2f} MB)\")\n        print(f\"  Dimensions: {self.width}x{self.height}\")\n        print(f\"  Frames: {len(optimized_frames)} @ {self.fps} fps\")\n        print(f\"  Duration: {info[\'duration_seconds\']:.1f}s\")\n        print(f\"  Colors: {num_colors}\")\n\n        # Size info\n        if optimize_for_emoji:\n            print(f\"  Optimized for emoji (128x128, reduced colors)\")\n        if file_size_mb > 1.0:\n            print(f\"\\n  Note: Large file size ({file_size_kb:.1f} KB)\")\n            print(\"  Consider: fewer frames, smaller dimensions, or fewer colors\")\n\n        return info\n\n    def clear(self):\n        \"\"\"Clear all frames (useful for creating multiple GIFs).\"\"\"\n        self.frames = []\n','ad49e19c1e0219bc0e4156a5d8d240fe','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(1244,'LICENSE.txt','skill_enc.736c61636b2d6769662d63726561746f72__enc.302e302e31','\n                                 Apache License\n                           Version 2.0, January 2004\n                        http://www.apache.org/licenses/\n\n   TERMS AND CONDITIONS FOR USE, REPRODUCTION, AND DISTRIBUTION\n\n   1. Definitions.\n\n      \"License\" shall mean the terms and conditions for use, reproduction,\n      and distribution as defined by Sections 1 through 9 of this document.\n\n      \"Licensor\" shall mean the copyright owner or entity authorized by\n      the copyright owner that is granting the License.\n\n      \"Legal Entity\" shall mean the union of