nv python3\n\"\"\"\nEasing Functions - Timing functions for smooth animations.\n\nProvides various easing functions for natural motion and timing.\nAll functions take a value t (0.0 to 1.0) and return eased value (0.0 to 1.0).\n\"\"\"\n\nimport math\n\n\ndef linear(t: float) -> float:\n    \"\"\"Linear interpolation (no easing).\"\"\"\n    return t\n\n\ndef ease_in_quad(t: float) -> float:\n    \"\"\"Quadratic ease-in (slow start, accelerating).\"\"\"\n    return t * t\n\n\ndef ease_out_quad(t: float) -> float:\n    \"\"\"Quadratic ease-out (fast start, decelerating).\"\"\"\n    return t * (2 - t)\n\n\ndef ease_in_out_quad(t: float) -> float:\n    \"\"\"Quadratic ease-in-out (slow start and end).\"\"\"\n    if t < 0.5:\n        return 2 * t * t\n    return -1 + (4 - 2 * t) * t\n\n\ndef ease_in_cubic(t: float) -> float:\n    \"\"\"Cubic ease-in (slow start).\"\"\"\n    return t * t * t\n\n\ndef ease_out_cubic(t: float) -> float:\n    \"\"\"Cubic ease-out (fast start).\"\"\"\n    return (t - 1) * (t - 1) * (t - 1) + 1\n\n\ndef ease_in_out_cubic(t: float) -> float:\n    \"\"\"Cubic ease-in-out.\"\"\"\n    if t < 0.5:\n        return 4 * t * t * t\n    return (t - 1) * (2 * t - 2) * (2 * t - 2) + 1\n\n\ndef ease_in_bounce(t: float) -> float:\n    \"\"\"Bounce ease-in (bouncy start).\"\"\"\n    return 1 - ease_out_bounce(1 - t)\n\n\ndef ease_out_bounce(t: float) -> float:\n    \"\"\"Bounce ease-out (bouncy end).\"\"\"\n    if t < 1 / 2.75:\n        return 7.5625 * t * t\n    elif t < 2 / 2.75:\n        t -= 1.5 / 2.75\n        return 7.5625 * t * t + 0.75\n    elif t < 2.5 / 2.75:\n        t -= 2.25 / 2.75\n        return 7.5625 * t * t + 0.9375\n    else:\n        t -= 2.625 / 2.75\n        return 7.5625 * t * t + 0.984375\n\n\ndef ease_in_out_bounce(t: float) -> float:\n    \"\"\"Bounce ease-in-out.\"\"\"\n    if t < 0.5:\n        return ease_in_bounce(t * 2) * 0.5\n    return ease_out_bounce(t * 2 - 1) * 0.5 + 0.5\n\n\ndef ease_in_elastic(t: float) -> float:\n    \"\"\"Elastic ease-in (spring effect).\"\"\"\n    if t == 0 or t == 1:\n        return t\n    return -math.pow(2, 10 * (t - 1)) * math.sin((t - 1.1) * 5 * math.pi)\n\n\ndef ease_out_elastic(t: float) -> float:\n    \"\"\"Elastic ease-out (spring effect).\"\"\"\n    if t == 0 or t == 1:\n        return t\n    return math.pow(2, -10 * t) * math.sin((t - 0.1) * 5 * math.pi) + 1\n\n\ndef ease_in_out_elastic(t: float) -> float:\n    \"\"\"Elastic ease-in-out.\"\"\"\n    if t == 0 or t == 1:\n        return t\n    t = t * 2 - 1\n    if t < 0:\n        return -0.5 * math.pow(2, 10 * t) * math.sin((t - 0.1) * 5 * math.pi)\n    return math.pow(2, -10 * t) * math.sin((t - 0.1) * 5 * math.pi) * 0.5 + 1\n\n\n# Convenience mapping\nEASING_FUNCTIONS = {\n    \"linear\": linear,\n    \"ease_in\": ease_in_quad,\n    \"ease_out\": ease_out_quad,\n    \"ease_in_out\": ease_in_out_quad,\n    \"bounce_in\": ease_in_bounce,\n    \"bounce_out\": ease_out_bounce,\n    \"bounce\": ease_in_out_bounce,\n    \"elastic_in\": ease_in_elastic,\n    \"elastic_out\": ease_out_elastic,\n    \"elastic\": ease_in_out_elastic,\n}\n\n\ndef get_easing(name: str = \"linear\"):\n    \"\"\"Get easing function by name.\"\"\"\n    return EASING_FUNCTIONS.get(name, linear)\n\n\ndef interpolate(start: float, end: float, t: float, easing: str = \"linear\") -> float:\n    \"\"\"\n    Interpolate between two values with easing.\n\n    Args:\n        start: Start value\n        end: End value\n        t: Progress from 0.0 to 1.0\n        easing: Name of easing function\n\n    Returns:\n        Interpolated value\n    \"\"\"\n    ease_func = get_easing(easing)\n    eased_t = ease_func(t)\n    return start + (end - start) * eased_t\n\n\ndef ease_back_in(t: float) -> float:\n    \"\"\"Back ease-in (slight overshoot backward before forward motion).\"\"\"\n    c1 = 1.70158\n    c3 = c1 + 1\n    return c3 * t * t * t - c1 * t * t\n\n\ndef ease_back_out(t: float) -> float:\n    \"\"\"Back ease-out (overshoot forward then settle back).\"\"\"\n    c1 = 1.70158\n    c3 = c1 + 1\n    return 1 + c3 * pow(t - 1, 3) + c1 * pow(t - 1, 2)\n\n\ndef ease_back_in_out(t: float) -> float:\n    \"\"\"Back ease-in-out (overshoot at both ends).\"\"\"\n    c1 = 1.70158\n    c2 = c1 * 1.525\n    if t < 0.5:\n        return (pow(2 * t, 2) * ((c2 + 1) * 2 * t - c2)) / 2\n    return (pow(2 * t - 2, 2) * ((c2 + 1) * (t * 2 - 2) + c2) + 2) / 2\n\n\ndef apply_squash_stretch(\n    base_scale: tuple[float, float], intensity: float, direction: str = \"vertical\"\n) -> tuple[float, float]:\n    \"\"\"\n    Calculate squash and stretch scales for more dynamic animation.\n\n    Args:\n        base_scale: (width_scale, height_scale) base scales\n        intensity: Squash/stretch intensity (0.0-1.0)\n        direction: \'vertical\', \'horizontal\', or \'both\'\n\n    Returns:\n        (width_scale, height_scale) with squash/stretch applied\n    \"\"\"\n    width_scale, height_scale = base_scale\n\n    if direction == \"vertical\":\n        # Compress vertically, expand horizontally (preserve volume)\n        height_scale *= 1 - intensity * 0.5\n        width_scale *= 1 + intensity * 0.5\n    elif direction == \"horizontal\":\n        # Compress horizontally, expand vertically\n        width_scale *= 1 - intensity * 0.5\n        height_scale *= 1 + intensity * 0.5\n    elif direction == \"both\":\n        # General squash (both dimensions)\n        width_scale *= 1 - intensity * 0.3\n        height_scale *= 1 - intensity * 0.3\n\n    return (width_scale, height_scale)\n\n\ndef calculate_arc_motion(\n    start: tuple[float, float], end: tuple[float, float], height: float, t: float\n) -> tuple[float, float]:\n    \"\"\"\n    Calculate position along a parabolic arc (natural motion path).\n\n    Args:\n        start: (x, y) starting position\n        end: (x, y) ending position\n        height: Arc height at midpoint (positive = upward)\n        t: Progress (0.0-1.0)\n\n    Returns:\n        (x, y) position along arc\n    \"\"\"\n    x1, y1 = start\n    x2, y2 = end\n\n    # Linear interpolation for x\n    x = x1 + (x2 - x1) * t\n\n    # Parabolic interpolation for y\n    # y = start + progress * (end - start) + arc_offset\n    # Arc offset peaks at t=0.5\n    arc_offset = 4 * height * t * (1 - t)\n    y = y1 + (y2 - y1) * t - arc_offset\n\n    return (x, y)\n\n\n# Add new easing functions to the convenience mapping\nEASING_FUNCTIONS.update(\n    {\n        \"back_in\": ease_back_in,\n        \"back_out\": ease_back_out,\n        \"back_in_out\": ease_back_in_out,\n        \"anticipate\": ease_back_in,  # Alias\n        \"overshoot\": ease_back_out,  # Alias\n    }\n)\n','e7fc06b3a101335c6f9c2694920f2905','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(1247,'requirements.txt','skill_enc.736c61636b2d6769662d63726561746f72__enc.302e302e31','pillow>=10.0.0\nimageio>=2.31.0\nimageio-ffmpeg>=0.4.9\nnumpy>=1.24.0','f0438b406aa799a2f7be030d5f0e2185','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(1248,'enc.636f72652f76616c696461746f72732e7079','skill_enc.736c61636b2d6769662d63726561746f72__enc.302e302e31','#!/usr/bin/env python3\n\"\"\"\nValidators - Check if GIFs meet Slack\'s requirements.\n\nThese validators help ensure your GIFs meet Slack\'s size and dimension constraints.\n\"\"\"\n\nfrom pathlib import Path\n\n\ndef validate_gif(\n    gif_path: str | Path, is_emoji: bool = True, verbose: bool = True\n) -> tuple[bool, dict]:\n    \"\"\"\n    Validate GIF for Slack (dimensions, size, frame count).\n\n    Args:\n        gif_path: Path to GIF file\n        is_emoji: True for emoji (128x128 recommended), False for message GIF\n        verbose: Print validation details\n\n    Returns:\n        Tuple of (passes: bool, results: dict with all details)\n    \"\"\"\n    from PIL import Image\n\n    gif_path = Path(gif_path)\n\n    if not gif_path.exists():\n        return False, {\"error\": f\"File not found: {gif_path}\"}\n\n    # Get file size\n    size_bytes = gif_path.stat().st_size\n    size_kb = size_bytes / 1024\n    size_mb = size_kb / 1024\n\n    # Get dimensions and frame info\n    try:\n        with Image.open(gif_path) as img:\n            width, height = img.size\n\n            # Count frames\n            frame_count = 0\n            try:\n                while True:\n                    img.seek(frame_count)\n                    frame_count += 1\n            except EOFError:\n                pass\n\n            # Get duration\n            try:\n                duration_ms = img.info.get(\"duration\", 100)\n                total_duration = (duration_ms * frame_count) / 1000\n                fps = frame_count / total_duration if total_duration > 0 else 0\n            except:\n                total_duration = None\n                fps = None\n\n    except Exception as e:\n        return False, {\"error\": f\"Failed to read GIF: {e}\"}\n\n    # Validate dimensions\n    if is_emoji:\n        optimal = width == height == 128\n        acceptable = width == height and 64 <= width <= 128\n        dim_pass = acceptable\n    else:\n        aspect_ratio = (\n            max(width, height) / min(width, height)\n            if min(width, height) > 0\n            else float(\"inf\")\n        )\n        dim_pass = aspect_ratio <= 2.0 and 320 <= min(width, height) <= 640\n\n    results = {\n        \"file\": str(gif_path),\n        \"passes\": dim_pass,\n        \"width\": width,\n        \"height\": height,\n        \"size_kb\": size_kb,\n        \"size_mb\": size_mb,\n        \"frame_count\": frame_count,\n        \"duration_seconds\": total_duration,\n        \"fps\": fps,\n        \"is_emoji\": is_emoji,\n        \"optimal\": optimal if is_emoji else None,\n    }\n\n    # Print if verbose\n    if verbose:\n        print(f\"\\nValidating {gif_path.name}:\")\n        print(\n            f\"  Dimensions: {width}x{height}\"\n            + (\n                f\" ({\'optimal\' if optimal else \'acceptable\'})\"\n                if is_emoji and acceptable\n                else \"\"\n            )\n        )\n        print(\n            f\"  Size: {size_kb:.1f} KB\"\n            + (f\" ({size_mb:.2f} MB)\" if size_mb >= 1.0 else \"\")\n        )\n        print(\n            f\"  Frames: {frame_count}\"\n            + (f\" @ {fps:.1f} fps ({total_duration:.1f}s)\" if fps else \"\")\n        )\n\n        if not dim_pass:\n            print(\n                f\"  Note: {\'Emoji should be 128x128\' if is_emoji else \'Unusual dimensions for Slack\'}\"\n            )\n\n        if size_mb > 5.0:\n            print(f\"  Note: Large file size - consider fewer frames/colors\")\n\n    return dim_pass, results\n\n\ndef is_slack_ready(\n    gif_path: str | Path, is_emoji: bool = True, verbose: bool = True\n) -> bool:\n    \"\"\"\n    Quick check if GIF is ready for Slack.\n\n    Args:\n        gif_path: Path to GIF file\n        is_emoji: True for emoji GIF, False for message GIF\n        verbose: Print feedback\n\n    Returns:\n        True if dimensions are acceptable\n    \"\"\"\n    passes, _ = validate_gif(gif_path, is_emoji, verbose)\n    return passes\n','b5e65b65d0d099f5b0f92201adfaac05','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(1249,'enc.636f72652f656173696e672e7079','skill_enc.736c61636b2d6769662d63726561746f72__enc.302e302e31','#!/usr/bin/env python3\n\"\"\"\nEasing Functions - Timing functions for smooth animations.\n\nProvides various easing functions for natural motion and timing.\nAll functions take a value t (0.0 to 1.0) and return eased value (0.0 to 1.0).\n\"\"\"\n\nimport math\n\n\ndef linear(t: float) -> float:\n    \"\"\"Linear interpolation (no easing).\"\"\"\n    return t\n\n\ndef ease_in_quad(t: float) -> float:\n    \"\"\"Quadratic ease-in (slow start, accelerating).\"\"\"\n    return t * t\n\n\ndef ease_out_quad(t: float) -> float:\n    \"\"\"Quadratic ease-out (fast start, decelerating).\"\"\"\n    return t * (2 - t)\n\n\ndef ease_in_out_quad(t: float) -> float:\n    \"\"\"Quadratic ease-in-out (slow start and end).\"\"\"\n    if t < 0.5:\n        return 2 * t * t\n    return -1 + (4 - 2 * t) * t\n\n\ndef ease_in_cubic(t: float) -> float:\n    \"\"\"Cubic ease-in (slow start).\"\"\"\n    return t * t * t\n\n\ndef ease_out_cubic(t: float) -> float:\n    \"\"\"Cubic ease-out (fast start).\"\"\"\n    return (t - 1) * (t - 1) * (t - 1) + 1\n\n\ndef ease_in_out_cubic(t: float) -> float:\n    \"\"\"Cubic ease-in-out.\"\"\"\n    if t < 0.5:\n        return 4 * t * t * t\n    return (t - 1) * (2 * t - 2) * (2 * t - 2) + 1\n\n\ndef ease_in_bounce(t: float) -> float:\n    \"\"\"Bounce ease-in (bouncy start).\"\"\"\n    return 1 - ease_out_bounce(1 - t)\n\n\ndef ease_out_bounce(t: float) -> float:\n    \"\"\"Bounce ease-out (bouncy end).\"\"\"\n    if t < 1 / 2.75:\n        return 7.5625 * t * t\n    elif t < 2 / 2.75:\n        t -= 1.5 / 2.75\n        return 7.5625 * t * t + 0.75\n    elif t < 2.5 / 2.75:\n        t -= 2.25 / 2.75\n        return 7.5625 * t * t + 0.9375\n    else:\n        t -= 2.625 / 2.75\n        return 7.5625 * t * t + 0.984375\n\n\ndef ease_in_out_bounce(t: float) -> float:\n    \"\"\"Bounce ease-in-out.\"\"\"\n    if t < 0.5:\n        return ease_in_bounce(t * 2) * 0.5\n    return ease_out_bounce(t * 2 - 1) * 0.5 + 0.5\n\n\ndef ease_in_elastic(t: float) -> float:\n    \"\"\"Elastic ease-in (spring effect).\"\"\"\n    if t == 0 or t == 1:\n        return t\n    return -math.pow(2, 10 * (t - 1)) * math.sin((t - 1.1) * 5 * math.pi)\n\n\ndef ease_out_elastic(t: float) -> float:\n    \"\"\"Elastic ease-out (spring effect).\"\"\"\n    if t == 0 or t == 1:\n        return t\n    return math.pow(2, -10 * t) * math.sin((t - 0.1) * 5 * math.pi) + 1\n\n\ndef ease_in_out_elastic(t: float) -> float:\n    \"\"\"Elastic ease-in-out.\"\"\"\n    if t == 0 or t == 1:\n        return t\n    t = t * 2 - 1\n    if t < 0:\n        return -0.5 * math.pow(2, 10 * t) * math.sin((t - 0.1) * 5 * math.pi)\n    return math.pow(2, -10 * t) * math.sin((t - 0.1) * 5 * math.pi) * 0.5 + 1\n\n\n# Convenience mapping\nEASING_FUNCTIONS = {\n    \"linear\": linear,\n    \"ease_in\": ease_in_quad,\n    \"ease_out\": ease_out_quad,\n    \"ease_in_out\": ease_in_out_quad,\n    \"bounce_in\": ease_in_bounce,\n    \"bounce_out\": ease_out_bounce,\n    \"bounce\": ease_in_out_bounce,\n    \"elastic_in\": ease_in_elastic,\n    \"elastic_out\": ease_out_elastic,\n    \"elastic\": ease_in_out_elastic,\n}\n\n\ndef get_easing(name: str = \"linear\"):\n    \"\"\"Get easing function by name.\"\"\"\n    return EASING_FUNCTIONS.get(name, linear)\n\n\ndef interpolate(start: float, end: float, t: float, easing: str = \"linear\") -> float:\n    \"\"\"\n    Interpolate between two values with easing.\n\n    Args:\n        start: Start value\n        end: End value\n        t: Progress from 0.0 to 1.0\n        easing: Name of easing function\n\n    Returns:\n        Interpolated value\n    \"\"\"\n    ease_func = get_easing(easing)\n    eased_t = ease_func(t)\n    return start + (end - start) * eased_t\n\n\ndef ease_back_in(t: float) -> float:\n    \"\"\"Back ease-in (slight overshoot backward before forward motion).\"\"\"\n    c1 = 1.70158\n    c3 = c1 + 1\n    return c3 * t * t * t - c1 * t * t\n\n\ndef ease_back_out(t: float) -> float:\n    \"\"\"Back ease-out (overshoot forward then settle back).\"\"\"\n    c1 = 1.70158\n    c3 = c1 + 1\n    return 1 + c3 * pow(t - 1, 3) + c1 * pow(t - 1, 2)\n\n\ndef ease_back_in_out(t: float) -> float:\n    \"\"\"Back ease-in-out (overshoot at both ends).\"\"\"\n    c1 = 1.70158\n    c2 = c1 * 1.525\n    if t < 0.5:\n        return (pow(2 * t, 2) * ((c2 + 1) * 2 * t - c2)) / 2\n    return (pow(2 * t - 2, 2) * ((c2 + 1) * (t * 2 - 2) + c2) + 2) / 2\n\n\ndef apply_squash_stretch(\n    base_scale: tuple[float, float], intensity: float, direction: str = \"vertical\"\n) -> tuple[float, float]:\n    \"\"\"\n    Calculate squash and stretch scales for more dynamic animation.\n\n    Args:\n        base_scale: (width_scale, height_scale) base scales\n        intensity: Squash/stretch intensity (0.0-1.0)\n        direction: \'vertical\', \'horizontal\', or \'both\'\n\n    Returns:\n        (width_scale, height_scale) with squash/stretch applied\n    \"\"\"\n    width_scale, height_scale = base_scale\n\n    if direction == \"vertical\":\n        # Compress vertically, expand horizontally (preserve volume)\n        height_scale *= 1 - intensity * 0.5\n        width_scale *= 1 + intensity * 0.5\n    elif direction == \"horizontal\":\n        # Compress horizontally, expand vertically\n        width_scale *= 1 - intensity * 0.5\n        height_scale *= 1 + intensity * 0.5\n    elif direction == \"both\":\n        # General squash (both dimensions)\n        width_scale *= 1 - intensity * 0.3\n        height_scale *= 1 - intensity * 0.3\n\n    return (width_scale, height_scale)\n\n\ndef calculate_arc_motion(\n    start: tuple[float, float], end: tuple[float, float], height: float, t: float\n) -> tuple[float, float]:\n    \"\"\"\n    Calculate position along a parabolic arc (natural motion path).\n\n    Args:\n        start: (x, y) starting position\n        end: (x, y) ending position\n        height: Arc height at midpoint (positive = upward)\n        t: Progress (0.0-1.0)\n\n    Returns:\n        (x, y) position along arc\n    \"\"\"\n    x1, y1 = start\n    x2, y2 = end\n\n    # Linear interpolation for x\n    x = x1 + (x2 - x1) * t\n\n    # Parabolic interpolation for y\n    # y = start + progress * (end - start) + arc_offset\n    # Arc offset peaks at t=0.5\n    arc_offset = 4 * height * t * (1 - t)\n    y = y1 + (y2 - y1) * t - arc_offset\n\n    return (x, y)\n\n\n# Add new easing functions to the convenience mapping\nEASING_FUNCTIONS.update(\n    {\n        \"back_in\": ease_back_in,\n        \"back_out\": ease_back_out,\n        \"back_in_out\": ease_back_in_out,\n        \"anticipate\": ease_back_in,  # Alias\n        \"overshoot\": ease_back_out,  # Alias\n    }\n)\n','e7fc06b3a101335c6f9c2694920f2905','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(1250,'requirements.txt','skill_enc.736c61636b2d6769662d63726561746f72__enc.302e302e31','pillow>=10.0.0\nimageio>=2.31.0\nimageio-ffmpeg>=0.4.9\nnumpy>=1.24.0','f0438b406aa799a2f7be030d5f0e2185','2026-10-26 11:22:01','2026-10-26 11:22:01','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(1251,'LICENSE.txt','skill_enc.736c61636b2d6769662d63726561746f72__enc.302e302e31','\n                                 Apache License\n                           Version 2.0, January 2004\n                        http://www.apache.org/licenses/\n\n   TERMS AND CONDITIONS FOR USE, REPRODUCTION, AND DISTRIBUTION\n\n   1. Definitions.\n\n      \"License\" shall mean the terms and conditions for use, reproduction,\n      and distribution as defined by Sections 1 through 9 of this document.\n\n      \"Licensor\" shall mean the copyright owner or entity authorized by\n      the copyright owner that is granting the License.\n\n      \"Legal Entity\" shall mean the union of the acting entity and all\n      other entities that control, are controlled by, or are under common\n      control with that entity. For the purposes of this definition,\n      \"control\" means (i) the power, direct or indirect, to cause the\n      direction or management of such entity, whether by contract or\n      otherwise, or (ii) ownership of fifty percent (50%) or more of the\n      outstanding shares, or (iii) beneficial ownership of such entity.\n\n      \"You\" (or \"Your\") shall mean an individual or Legal Entity\n      exercising permissions granted by this License.\n\n      \"Source\" form shall mean the preferred form for making modifications,\n      including but not limited to software source code, d