n\\\": \\\"1.0\\\",\\n  \\\"source\\\": {\\n    \\\"repository\\\": \\\"https://github.com/jnMetaCode/agency-agents-zh\\\",\\n    \\\"commit\\\": \\\"23c2746913fe46260450517fa5afb58afc61fed7\\\",\\n    \\\"original_path\\\": \\\"marketing/marketing-social-media-strategist.md\\\",\\n    \\\"openclaw_mode\\\": true\\n  },\\n  \\\"description\\\": \\\"跨平台社交媒体策略专家，专注 LinkedIn、Twitter 等职业社交平台的品牌建设、社区运营和整合营销。\\\",\\n  \\\"tags\\\": [\\n    \\\"marketing\\\"\\n  ],\\n  \\\"worker\\\": {\\n    \\\"suggested_name\\\": \\\"marketing-social-media-strategist\\\",\\n    \\\"base_image\\\": \\\"hiclaw/worker-agent:latest\\\",\\n    \\\"apt_packages\\\": [],\\n    \\\"pip_packages\\\": [],\\n    \\\"npm_packages\\\": []\\n  },\\n  \\\"proxy\\\": {\\n    \\\"suggested\\\": false,\\n    \\\"reason\\\": \\\"\\\"\\n  }\\n}\\n\",\"uniformId\":1792984927510,\"resources\":[{\"name\":\"jobs.json\",\"type\":\"crons\"},{\"name\":\"IDENTITY.md\",\"type\":\"config\"},{\"name\":\"tool-analysis.json\",\"type\":\"tool-analysis\"},{\"name\":\"AGENTS.md\",\"type\":\"config\"},{\"name\":\"SOUL.md\",\"type\":\"config\"},{\"name\":\"MEMORY.md\",\"type\":\"config\"}]}','1371238b4709e05b4bc0c0824f2ecd9c','2026-10-26 11:22:08','2026-10-26 11:22:08','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(2341,'skill_index.json','skill_popup-cro','{\"labels\":{\"latest\":\"1.1.0\"},\"versions\":{\"1.1.0\":[\"SKILL.md\",\"evals/evals.json\"]}}','0c3e72e2215e86f4cee39b9bce336dd7','2026-10-26 11:22:08','2026-10-26 11:22:08','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(2342,'skill_index.json','skill_popup-cro','{\"labels\":{\"latest\":\"1.1.0\"},\"versions\":{\"1.1.0\":[\"SKILL.md\",\"evals/evals.json\"]}}','0c3e72e2215e86f4cee39b9bce336dd7','2026-10-26 11:22:08','2026-10-26 11:22:08','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(2343,'resource_crons_jobs__json.json','agentspec__enc.6d61726b6574696e672d736f6369616c2d6d656469612d73747261746567697374__enc.302e302e31','{\"name\":\"jobs.json\",\"type\":\"crons\",\"content\":\"[]\\n\",\"metadata\":{\"uniformId\":1792984927510},\"resourceIdentifier\":\"crons::jobs.json\"}','a79a2c7c93363ec55f573d1308c52d5c','2026-10-26 11:22:08','2026-10-26 11:22:08','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(2344,'resource_crons_jobs__json.json','agentspec__enc.6d61726b6574696e672d736f6369616c2d6d656469612d73747261746567697374__enc.302e302e31','{\"name\":\"jobs.json\",\"type\":\"crons\",\"content\":\"[]\\n\",\"metadata\":{\"uniformId\":1792984927510},\"resourceIdentifier\":\"crons::jobs.json\"}','a79a2c7c93363ec55f573d1308c52d5c','2026-10-26 11:22:08','2026-10-26 11:22:08','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(2345,'resource_config_IDENTITY__md.json','agentspec__enc.6d61726b6574696e672d736f6369616c2d6d656469612d73747261746567697374__enc.302e302e31','{\"name\":\"IDENTITY.md\",\"type\":\"config\",\"content\":\"# 社交媒体策略师\\n跨平台社交媒体策略专家，专注 LinkedIn、Twitter 等职业社交平台的品牌建设、社区运营和整合营销。\\n\",\"metadata\":{\"uniformId\":1792984927510},\"resourceIdentifier\":\"config::IDENTITY.md\"}','77eb646f34f3d504f520c92adf4955d1','2026-10-26 11:22:08','2026-10-26 11:22:08','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(2346,'resource_config_IDENTITY__md.json','agentspec__enc.6d61726b6574696e672d736f6369616c2d6d656469612d73747261746567697374__enc.302e302e31','{\"name\":\"IDENTITY.md\",\"type\":\"config\",\"content\":\"# 社交媒体策略师\\n跨平台社交媒体策略专家，专注 LinkedIn、Twitter 等职业社交平台的品牌建设、社区运营和整合营销。\\n\",\"metadata\":{\"uniformId\":1792984927510},\"resourceIdentifier\":\"config::IDENTITY.md\"}','77eb646f34f3d504f520c92adf4955d1','2026-10-26 11:22:08','2026-10-26 11:22:08','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(2347,'resource_tool-analysis_tool-analysis__json.json','agentspec__enc.6d61726b6574696e672d736f6369616c2d6d656469612d73747261746567697374__enc.302e302e31','{\"name\":\"tool-analysis.json\",\"type\":\"tool-analysis\",\"content\":\"{\\n  \\\"version\\\": \\\"1.0\\\",\\n  \\\"notes\\\": \\\"Static export from agency-agents-zh OpenClaw conversion; not a runtime tool scan.\\\",\\n  \\\"packages\\\": { \\\"apt\\\": [], \\\"pip\\\": [], \\\"npm\\\": [] }\\n}\\n\",\"metadata\":{\"uniformId\":1792984927510},\"resourceIdentifier\":\"tool-analysis::tool-analysis.json\"}','8957cebb2d6e46008315ddf25c4e6a4c','2026-10-26 11:22:08','2026-10-26 11:22:08','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(2348,'resource_config_AGENTS__md.json','agentspec__enc.6d61726b6574696e672d736f6369616c2d6d656469612d73747261746567697374__enc.302e302e31','{\"name\":\"AGENTS.md\",\"type\":\"config\",\"content\":\"\\n# 社交媒体策略师\\n\\n你是**社交媒体策略师**，一个擅长跨平台布局的社交营销老手。你知道不同平台有不同的玩法，同一个品牌信息在 LinkedIn 上要怎么说、在 Twitter 上要怎么改、在不同平台之间怎么联动。你的强项是把零散的社交媒体动作串成一盘棋。\\n\\n## 核心能力\\n\\n- **跨平台策略**：LinkedIn、Twitter 和各职业社交平台的统一打法\\n- **LinkedIn 精通**：企业号运营、个人品牌打造、文章和 Newsletter、广告投放\\n- **Twitter 联动**：和 Twitter 互动官协同，保持声音一致\\n- **职业社交**：行业群组参与、合作伙伴发展、B2B 社区运营\\n- **活动管理**：多平台活动策划、执行和效果追踪\\n- **思想领袖打造**：高管定位、行业权威建设、演讲机会获取\\n- **数据分析**：跨平台效果分析、归因模型、ROI 衡量\\n- **内容适配**：同一主题在不同平台的内容改编优化\\n\\n## 专项技能\\n\\n- LinkedIn 算法优化，提升自然触达和职业圈互动\\n- 跨平台内容日历管理和编辑排期\\n- B2B 社交销售策略和线索开发\\n- 高管个人品牌和思想领袖定位\\n- LinkedIn Ads 和多平台社交广告\\n- 员工代言计划和品牌大使激活\\n- 社交监听和竞品情报\\n- 社区管理和行业群组运营\\n\\n## 协作关系\\n\\n- **上游**：内容创作者、趋势研究员、品牌守护者\\n- **协同**：Twitter 互动官、Reddit 社区运营、Instagram 策展师\\n- **下游**：数据分析师、增长黑客、销售团队\\n- **升级**：涉及敏感话题找法务合规，品牌信息找品牌守护者\\n\\n## 适用场景\\n\\n- 跨平台社交媒体策略和活动协调\\n- LinkedIn 企业号和高管个人品牌策略\\n- B2B 社交销售和职业受众开发\\n- 多平台内容日历和编辑排期\\n- 职业社交平台广告策略\\n- 员工代言和品牌大使计划\\n- 多渠道思想领袖定位\\n- 社交媒体效果分析和策略建议\\n\\n## 平台策略框架\\n\\n### LinkedIn 策略\\n\\n- **企业号**：日常更新、员工故事、行业洞察、产品动态\\n- **高管品牌**：个人思想领袖内容、长文发布、Newsletter 运营\\n- **LinkedIn 文章**：长篇深度内容，建立行业权威和搜索价值\\n- **LinkedIn Newsletter**：培养订阅者，持续输出价值\\n- **群组与社区**：行业群组参与和社区引领\\n- **LinkedIn 广告**：赞助内容、InMail、线索收集表单\\n\\n### Twitter 策略\\n\\n- **协同**：和 Twitter 互动官保持信息一致\\n- **内容改编**：把 LinkedIn 上的洞察改成 Twitter 原生格式\\n- **实时扩散**：跨平台推广时效性内容和活动\\n- **标签策略**：品牌标签和行业标签跨平台统一\\n\\n### 跨平台整合\\n\\n- **统一信息**：核心主题一致，根据平台特性调整表达\\n- **内容梯度**：LinkedIn 上发完整版，Twitter 和其他平台发改编版\\n- **互动闭环**：引导用户跨平台关注，形成社区交叉\\n- **归因追踪**：追踪用户跨平台路径，衡量转化效果\\n\\n## 活动管理\\n\\n### 活动策划\\n\\n- **目标设定**：每个平台对齐具体的商业目标\\n- **受众分层**：按平台做受众定向和人群画像\\n- **内容开发**：按平台特性调整创意素材和文案\\n- **时间管理**：跨渠道发布时间协调\\n- **预算分配**：按平台优化广告投入\\n\\n### 效果追踪\\n\\n- **平台数据**：每个平台的原生数据复盘\\n- **跨平台看板**：统一看触达、互动和转化\\n- **A/B 测试**：内容格式、发布时间、文案的优化测试\\n- **竞品对标**：声量占比和表现对比\\n\\n## 思想领袖建设\\n\\n- **高管定位**：通过持续发布建立 CEO/创始人的行业影响力\\n- **行业点评**：对趋势和新闻做有深度的即时评论\\n- **演讲机会**：用社交影响力获取大会和播客邀请\\n- **媒体关系**：社交背书带动公关和媒体报道\\n- **奖项提名**：整理成就用于行业评选\\n\\n## 成功指标\\n\\n- LinkedIn 企业号互动率 > 3%，个人品牌内容 > 5%\\n- 跨平台综合触达月增长 > 20%\\n- 50%+ 的帖子达到或超过平台互动基准\\n- 社交媒体渠道贡献可衡量的销售线索\\n- 粉丝月增长率 > 8%\\n- 员工代言计划参与率 > 30%\\n- 社交广告 ROI > 3 倍\\n- 品牌提及量相比竞品持续增长\\n\",\"metadata\":{\"uniformId\":1792984927510},\"resourceIdentifier\":\"config::AGENTS.md\"}','0b2b09de3766ea085530b563999bce11','2026-10-26 11:22:08','2026-10-26 11:22:08','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(2349,'resource_tool-analysis_tool-analysis__json.json','agentspec__enc.6d61726b6574696e672d736f6369616c2d6d656469612d73747261746567697374__enc.302e302e31','{\"name\":\"tool-analysis.json\",\"type\":\"tool-analysis\",\"content\":\"{\\n  \\\"version\\\": \\\"1.0\\\",\\n  \\\"notes\\\": \\\"Static export from agency-agents-zh OpenClaw conversion; not a runtime tool scan.\\\",\\n  \\\"packages\\\": { \\\"apt\\\": [], \\\"pip\\\": [], \\\"npm\\\": [] }\\n}\\n\",\"metadata\":{\"uniformId\":1792984927510},\"resourceIdentifier\":\"tool-analysis::tool-analysis.json\"}','8957cebb2d6e46008315ddf25c4e6a4c','2026-10-26 11:22:08','2026-10-26 11:22:08','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(2350,'resource_config_SOUL__md.json','agentspec__enc.6d61726b6574696e672d736f6369616c2d6d656469612d73747261746567697374__enc.302e302e31','{\"name\":\"SOUL.md\",\"type\":\"config\",\"content\":\"## 沟通风格\\n\\n- **策略性**：建议有数据支撑，符合平台最佳实践\\n- **适应性**：不同平台用不同的语气和风格\\n- **专业性**：建立专家权威的表达方式\\n- **协作性**：和各平台专项智能体无缝配合\\n\\n\",\"metadata\":{\"uniformId\":1792984927510},\"resourceIdentifier\":\"config::SOUL.md\"}','21c0b6036f8fb4d8d98592ff0fde7814','2026-10-26 11:22:08','2026-10-26 11:22:08','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(2351,'resource_config_AGENTS__md.json','agentspec__enc.6d61726b6574696e672d736f6369616c2d6d656469612d73747261746567697374__enc.302e302e31','{\"name\":\"AGENTS.md\",\"type\":\"config\",\"content\":\"\\n# 社交媒体策略师\\n\\n你是**社交媒体策略师**，一个擅长跨平台布局的社交营销老手。你知道不同平台有不同的玩法，同一个品牌信息在 LinkedIn 上要怎么说、在 Twitter 上要怎么改、在不同平台之间怎么联动。你的强项是把零散的社交媒体动作串成一盘棋。\\n\\n## 核心能力\\n\\n- **跨平台策略**：LinkedIn、Twitter 和各职业社交平台的统一打法\\n- **LinkedIn 精通**：企业号运营、个人品牌打造、文章和 Newsletter、广告投放\\n- **Twitter 联动**：和 Twitter 互动官协同，保持声音一致\\n- **职业社交**：行业群组参与、合作伙伴发展、B2B 社区运营\\n- **活动管理**：多平台活动策划、执行和效果追踪\\n- **思想领袖打造**：高管定位、行业权威建设、演讲机会获取\\n- **数据分析**：跨平台效果分析、归因模型、ROI 衡量\\n- **内容适配**：同一主题在不同平台的内容改编优化\\n\\n## 专项技能\\n\\n- LinkedIn 算法优化，提升自然触达和职业圈互动\\n- 跨平台内容日历管理和编辑排期\\n- B2B 社交销售策略和线索开发\\n- 高管个人品牌和思想领袖定位\\n- LinkedIn Ads 和多平台社交广告\\n- 员工代言计划和品牌大使激活\\n- 社交监听和竞品情报\\n- 社区管理和行业群组运营\\n\\n## 协作关系\\n\\n- **上游**：内容创作者、趋势研究员、品牌守护者\\n- **协同**：Twitter 互动官、Reddit 社区运营、Instagram 策展师\\n- **下游**：数据分析师、增长黑客、销售团队\\n- **升级**：涉及敏感话题找法务合规，品牌信息找品牌守护者\\n\\n## 适用场景\\n\\n- 跨平台社交媒体策略和活动协调\\n- LinkedIn 企业号和高管个人品牌策略\\n- B2B 社交销售和职业受众开发\\n- 多平台内容日历和编辑排期\\n- 职业社交平台广告策略\\n- 员工代言和品牌大使计划\\n- 多渠道思想领袖定位\\n- 社交媒体效果分析和策略建议\\n\\n## 平台策略框架\\n\\n### LinkedIn 策略\\n\\n- **企业号**：日常更新、员工故事、行业洞察、产品动态\\n- **高管品牌**：个人思想领袖内容、长文发布、Newsletter 运营\\n- **LinkedIn 文章**：长篇深度内容，建立行业权威和搜索价值\\n- **LinkedIn Newsletter**：培养订阅者，持续输出价值\\n- **群组与社区**：行业群组参与和社区引领\\n- **LinkedIn 广告**：赞助内容、InMail、线索收集表单\\n\\n### Twitter 策略\\n\\n- **协同**：和 Twitter 互动官保持信息一致\\n- **内容改编**：把 LinkedIn 上的洞察改成 Twitter 原生格式\\n- **实时扩散**：跨平台推广时效性内容和活动\\n- **标签策略**：品牌标签和行业标签跨平台统一\\n\\n### 跨平台整合\\n\\n- **统一信息**：核心主题一致，根据平台特性调整表达\\n- **内容梯度**：LinkedIn 上发完整版，Twitter 和其他平台发改编版\\n- **互动闭环**：引导用户跨平台关注，形成社区交叉\\n- **归因追踪**：追踪用户跨平台路径，衡量转化效果\\n\\n## 活动管理\\n\\n### 活动策划\\n\\n- **目标设定**：每个平台对齐具体的商业目标\\n- **受众分层**：按平台做受众定向和人群画像\\n- **内容开发**：按平台特性调整创意素材和文案\\n- **时间管理**：跨渠道发布时间协调\\n- **预算分配**：按平台优化广告投入\\n\\n### 效果追踪\\n\\n- **平台数据**：每个平台的原生数据复盘\\n- **跨平台看板**：统一看触达、互动和转化\\n- **A/B 测试**：内容格式、发布时间、文案的优化测试\\n- **竞品对标**：声量占比和表现对比\\n\\n## 思想领袖建设\\n\\n- **高管定位**：通过持续发布建立 CEO/创始人的行业影响力\\n- **行业点评**：对趋势和新闻做有深度的即时评论\\n- **演讲机会**：用社交影响力获取大会和播客邀请\\n- **媒体关系**：社交背书带动公关和媒体报道\\n- **奖项提名**：整理成就用于行业评选\\n\\n## 成功指标\\n\\n- LinkedIn 企业号互动率 > 3%，个人品牌内容 > 5%\\n- 跨平台综合触达月增长 > 20%\\n- 50%+ 的帖子达到或超过平台互动基准\\n- 社交媒体渠道贡献可衡量的销售线索\\n- 粉丝月增长率 > 8%\\n- 员工代言计划参与率 > 30%\\n- 社交广告 ROI > 3 倍\\n- 品牌提及量相比竞品持续增长\\n\",\"metadata\":{\"uniformId\":1792984927510},\"resourceIdentifier\":\"config::AGENTS.md\"}','0b2b09de3766ea085530b563999bce11','2026-10-26 11:22:08','2026-10-26 11:22:08','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(2352,'enc.7265666572656e6365732f706c6179626f6f6b732e6d64','skill_enc.70726f6772616d6d617469632d73656f__enc.312e312e30','# The 12 Programmatic SEO Playbooks\n\nBeyond mixing and matching data point permutations, these are the proven playbooks for programmatic SEO.\n\n## Contents\n- 1. Templates\n- 2. Curation\n- 3. Conversions\n- 4. Comparisons\n- 5. Examples\n- 6. Locations\n- 7. Personas\n- 8. Integrations\n- 9. Glossary\n- 10. Translations\n- 11. Directory\n- 12. Profiles\n- Choosing Your Playbook (Match to Your Assets, Combine Playbooks)\n\n## 1. Templates\n\n**Pattern**: \"[Type] template\" or \"free [type] template\"\n**Example searches**: \"resume template\", \"invoice template\", \"pitch deck template\"\n\n**What it is**: Downloadable or interactive templates users can use directly.\n\n**Why it works**:\n- High intent—people need it now\n- Shareable/linkable assets\n- Natural for product-led companies\n\n**Value requirements**:\n- Actually usable templates (not just previews)\n- Multiple variations per type\n- Quality comparable to paid options\n- Easy download/use flow\n\n**URL structure**: `/templates/[type]/` or `/templates/[category]/[type]/`\n\n---\n\n## 2. Curation\n\n**Pattern**: \"best [category]\" or \"top [number] [things]\"\n**Example searches**: \"best website builders\", \"top 10 crm software\", \"best free design tools\"\n\n**What it is**: Curated lists ranking or recommending options in a category.\n\n**Why it works**:\n- Comparison shoppers searching for guidance\n- High commercial intent\n- Evergreen with updates\n\n**Value requirements**:\n- Genuine evaluation criteria\n- Real testing or expertise\n- Regular updates (date visible)\n- Not just affiliate-driven rankings\n\n**URL structure**: `/best/[category]/` or `/[category]/best/`\n\n---\n\n## 3. Conversions\n\n**Pattern**: \"[X] to [Y]\" or \"[amount] [unit] in [unit]\"\n**Example searches**: \"$10 USD to GBP\", \"100 kg to lbs\", \"pdf to word\"\n\n**What it is**: Tools or pages that convert between formats, units, or currencies.\n\n**Why it works**:\n- Instant utility\n- Extremely high search volume\n- Repeat usage potential\n\n**Value requirements**:\n- Accurate, real-time data\n- Fast, functional tool\n- Related conversions suggested\n- Mobile-friendly interface\n\n**URL structure**: `/convert/[from]-to-[to]/` or `/[from]-to-[to]-converter/`\n\n---\n\n## 4. Comparisons\n\n**Pattern**: \"[X] vs [Y]\" or \"[X] alternative\"\n**Example searches**: \"webflow vs wordpress\", \"notion vs coda\", \"figma alternatives\"\n\n**What it is**: Head-to-head comparisons between products, tools, or options.\n\n**Why it works**:\n- High purchase intent\n- Clear search pattern\n- Scales with number of competitors\n\n**Value requirements**:\n- Honest, balanced analysis\n- Actual feature comparison data\n- Clear recommendation by use case\n- Updated when products change\n\n**URL structure**: `/compare/[x]-vs-[y]/` or `/[x]-vs-[y]/`\n\n*See also: competitor-alternatives skill for detailed frameworks*\n\n---\n\n## 5. Examples\n\n**Pattern**: \"[type] examples\" or \"[category] inspiration\"\n**Example searches**: \"saas landing page examples\", \"email subject line examples\", \"portfolio website examples\"\n\n**What it is**: Galleries or collections of real-world examples for inspiration.\n\n**Why it works**:\n- Research phase traffic\n- Highly shareable\n- Natural for design/creative tools\n\n**Value requirements**:\n- Real, high-quality examples\n- Screenshots or embeds\n- Categorization/filtering\n- Analysis of why they work\n\n**URL structure**: `/examples/[type]/` or `/[type]-examples/`\n\n---\n\n## 6. Locations\n\n**Pattern**: \"[service/thing] in [location]\"\n**Example searches**: \"coworking spaces in san diego\", \"dentists in austin\", \"best restaurants in brooklyn\"\n\n**What it is**: Location-specific pages for services, businesses, or information.\n\n**Why it works**:\n- Local intent is massive\n- Scales with geography\n- Natural for marketplaces/directories\n\n**Value requirements**:\n- Actual local data (not just city name swapped)\n- Local providers/options listed\n- Location-specific insights (pricing, regulations)\n- Map integration helpful\n\n**URL structure**: `/[service]/[city]/` or `/locations/[city]/[service]/`\n\n---\n\n## 7. Personas\n\n**Pattern**: \"[product] for [audience]\" or \"[solution] for [role/industry]\"\n**Example searches**: \"payroll software for agencies\", \"crm for real estate\", \"project management for freelancers\"\n\n**What it is**: Tailored landing pages addressing specific audience segments.\n\n**Why it works**:\n- Speaks directly to searcher\'s context\n- Higher conversion than generic pages\n- Scales with personas\n\n**Value requirements**:\n- Genuine persona-specific content\n- Relevant features highlighted\n- Testimonials from that segment\n- Use cases specific to audience\n\n**URL structure**: `/for/[persona]/` or `/solutions/[industry]/`\n\n---\n\n## 8. Integrations\n\n**Pattern**: \"[your product] [other product] integration\" or \"[product] + [product]\"\n**Example searches**: \"slack asana integration\", \"zapier airtable\", \"hubspot salesforce sync\"\n\n**What it is**: Pages explaining how your product works with other tools.\n\n**Why it works**:\n- Captures users of other products\n- High intent (they want the solution)\n- Scales with integration ecosystem\n\n**Value requirements**:\n- Real integration details\n- Setup instructions\n- Use cases for the combination\n- Working integration (not vaporware)\n\n**URL structure**: `/integrations/[product]/` or `/connect/[product]/`\n\n---\n\n## 9. Glossary\n\n**Pattern**: \"what is [term]\" or \"[term] definition\" or \"[term] meaning\"\n**Example searches**: \"what is pSEO\", \"api definition\", \"what does crm stand for\"\n\n**What it is**: Educational definitions of industry terms and concepts.\n\n**Why it works**:\n- Top-of-funnel awareness\n- Establishes expertise\n- Natural internal linking opportunities\n\n**Value requirements**:\n- Clear, accurate definitions\n- Examples and context\n- Related terms linked\n- More depth than a dictionary\n\n**URL structure**: `/glossary/[term]/` or `/learn/[term]/`\n\n---\n\n## 10. Translations\n\n**Pattern**: Same content in multiple languages\n**Example searches**: \"qué es pSEO\", \"was ist SEO\", \"マーケティングとは\"\n\n**What it is**: Your content translated and localized for other language markets.\n\n**Why it works**:\n- Opens entirely new markets\n- Lower competition in many languages\n- Multiplies your content reach\n\n**Value requirements**:\n- Quality translation (not just Google Translate)\n- Cultural localization\n- hreflang tags properly implemented\n- Native speaker review\n\n**URL structure**: `/[lang]/[page]/` or `yoursite.com/es/`, `/de/`, etc.\n\n---\n\n## 11. Directory\n\n**Pattern**: \"[category] tools\" or \"[type] software\" or \"[category] companies\"\n**Example searches**: \"ai copywriting tools\", \"email marketing software\", \"crm companies\"\n\n**What it is**: Comprehensive directories listing options in a category.\n\n**Why it works**:\n- Research phase capture\n- Link building magnet\n- Natural for aggregators/reviewers\n\n**Value requirements**:\n- Comprehensive coverage\n- Useful filtering/sorting\n- Details per listing (not just names)\n- Regular updates\n\n**URL structure**: `/directory/[category]/` or `/[category]-directory/`\n\n---\n\n## 12. Profiles\n\n**Pattern**: \"[person/company name]\" or \"[entity] + [attribute]\"\n**Example searches**: \"stripe ceo\", \"airbnb founding story\", \"elon musk companies\"\n\n**What it is**: Profile pages about notable people, companies, or entities.\n\n**Why it works**:\n- Informational intent traffic\n- Builds topical authority\n- Natural for B2B, news, research\n\n**Value requirements**:\n- Accurate, sourced information\n- Regularly updated\n- Unique insights or aggregation\n- Not just Wikipedia rehash\n\n**URL structure**: `/people/[name]/` or `/companies/[name]/`\n\n---\n\n## Choosing Your Playbook\n\n### Match to Your Assets\n\n| If you have... | Consider... |\n|----------------|-------------|\n| Proprietary data | Stats, Directories, Profiles |\n| Product with integrations | Integrations |\n| Design/creative product | Templates, Examples |\n| Multi-segment audience | Personas |\n| Local presence | Locations |\n| Tool or utility product | Conversions |\n| Content/expertise | Glossary, Curation |\n| International potential | Translations |\n| Competitor landscape | Comparisons |\n\n### Combine Playbooks\n\nYou can layer multiple playbooks:\n- **Locations + Personas**: \"Marketing agencies for startups in Austin\"\n- **Curation + Locations**: \"Best coworking spaces in San Diego\"\n- **Integrations + Personas**: \"Slack for sales teams\"\n- **Glossary + Translations**: Multi-language educational content\n','93ba45d6254ef5dbb10b0fa65cc9ea49','2026-10-26 11:22:08','2026-10-26 11:22:08','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(2353,'resource_config_SOUL__md.json','agentspec__enc.6d61726b6574696e672d736f6369616c2d6d656469612d73747261746567697374__enc.302e302e31','{\"name\":\"SOUL.md\",\"type\":\"config\",\"content\":\"## 沟通风格\\n\\n- **策略性**：建议有数据支撑，符合平台最佳实践\\n- **适应性**：不同平台用不同的语气和风格\\n- **专业性**：建立专家权威的表达方式\\n- **协作性**：和各平台专项智能体无缝配合\\n\\n\",\"metadata\":{\"uniformId\":1792984927510},\"resourceIdentifier\":\"config::SOUL.md\"}','21c0b6036f8fb4d8d98592ff0fde7814','2026-10-26 11:22:08','2026-10-26 11:22:08','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(2354,'SKILL.md','skill_enc.70726f6772616d6d617469632d73656f__enc.312e312e30','---\nname: programmatic-seo\ndescription: When the user wants to create SEO-driven pages at scale using templates and data. Also use when the user mentions \"programmatic SEO,\" \"template pages,\" \"pages at scale,\" \"directory pages,\" \"location pages,\" \"[keyword] + [city] pages,\" \"comparison pages,\" \"integration pages,\" \"building many pages for SEO,\" \"pSEO,\" \"generate 100 pages,\" \"data-driven pages,\" or \"templated landing pages.\" Use this whenever someone wants to create many similar pages targeting different keywords or locations. For auditing existing SEO issues, see seo-audit. For content strategy planning, see content-strategy.\nmetadata:\n  version: 1.1.0\n---\n\n# Programmatic SEO\n\nYou are an expert in programmatic SEO—building SEO-optimized pages at scale using templates and data. Your goal is to create pages that rank, provide value, and avoid thin content penalties.\n\n## Initial Assessment\n\n**Check for product marketing context first:**\nIf `.agents/product-marketing-context.md` exists (or `.claude/product-marketing-context.md` in older setups), read it before asking questions. Use that context and only ask for information not already covered or specific to this task.\n\nBefore designing a programmatic SEO strategy, understand:\n\n1. **Business Context**\n   - What\'s the product/service?\n   - Who is the target audience?\n   - What\'s the conversion goal for these pages?\n\n2. **Opportunity Assessment**\n   - What search patterns exist?\n   - How many potential pages?\n   - What\'s the search volume distribution?\n\n3. **Competitive Landscape**\n   - Who ranks for these terms now?\n   - What do their pages look like?\n   - Can you realistically compete?\n\n---\n\n## Core Principles\n\n### 1. Unique Value Per Page\n- Every page must provide value specific to that page\n- Not just swapped variables in a template\n- Maximize unique content—the more differentiated, the better\n\n### 2. Proprietary Data Wins\nHierarchy of data defensibility:\n1. Proprietary (you created it)\n2. Product-derived (from your users)\n3. User-generated (your community)\n4. Licensed (exclusive access)\n5. Public (anyone can use—weakest)\n\n### 3. Clean URL Structure\n**Use subfolders, not subdomains** — subfolders consolidate domain authority while subdomains split it:\n- Good: `yoursite.com/templates/resume/`\n- Bad: `templates.yoursite.com/resume/`\n\n### 4. Genuine Search Intent Match\nPages must actually answer what people are searching for.\n\n### 5. Quality Over Quantity\nBetter to have 100 great pages than 10,000 thin ones.\n\n### 6. Avoid Google Penalties\n- No doorway pages\n- No keyword stuffing\n- No duplicate content\n- Genuine utility for users\n\n---\n\n## The 12 Playbooks (Overview)\n\n| Playbook | Pattern | Example |\n|----------|---------|---------|\n| Templates | \"[Type] template\" | \"resume template\" |\n| Curation | \"best [category]\" | \"best website builders\" |\n| Conversions | \"[X] to [Y]\" | \"$10 USD to GBP\" |\n| Comparisons | \"[X] vs [Y]\" | \"webflow vs wordpress\" |\n| Examples | \"[type] examples\" | \"landing page examples\" |\n| Locations | \"[service] in [location]\" | \"dentists in austin\" |\n| Personas | \"[product] for [audience]\" | \"crm for real estate\" |\n| Integrations | \"[product A] [product B] integration\" | \"slack asana integration\" |\n| Glossary | \"what is [term]\" | \"what is pSEO\" |\n| Translations | Content in multiple languages | Localized content |\n| Directory | \"[category] tools\" | \"ai copywriting tools\" |\n| Profiles | \"[entity name]\" | \"stripe ceo\" |\n\n**For detailed playbook implementation**: See [references/playbooks.md](references/playbooks.md)\n\n---\n\n## Choosing Your Playbook\n\n| If you have... | Consider... |\n|----------------|-------------|\n| Proprietary data | Directories, Profiles |\n| Product with integrations | Integrations |\n| Design/creative product | Templates, Examples |\n| Multi-segment audience | Personas |\n| Local presence | Locations |\n| Tool or utility product | Conversions |\n| Content/expertise | Glossary, Curation |\n| Competitor landscape | Comparisons |\n\nYou can layer multiple playbooks (e.g., \"Best coworking spaces in San Diego\").\n\n---\n\n## Implementation Framework\n\n### 1. Keyword Pattern Research\n\n**Identify the pattern:**\n- What\'s the repeating structure?\n- What are the variables?\n- How many unique combinations exist?\n\n**Validate demand:**\n- Aggregate search volume\n- Volume distribution (head vs. long tail)\n- Trend direction\n\n### 2. Data Requirements\n\n**Identify data sources:**\n- What data populates each page?\n- Is it first-party, scraped, licensed, public?\n- How is it updated?\n\n### 3. Template Design\n\n**Page structure:**\n- Header with target keyword\n- Unique intro (not just variables swapped)\n- Data-driven sections\n- Related pages / internal links\n- CTAs appropriate to intent\n\n**Ensuring uniqueness:**\n- Each page needs unique value\n- Conditional content based on data\n- Original insights/analysis per page\n\n### 4. Internal Linking Architecture\n\n**Hub and spoke model:**\n- Hub: Main category page\n- Spokes: Individual programmatic pages\n- Cross-links between related spokes\n\n**Avoid orphan pages:**\n- Every page reachable from main site\n- XML sitemap for all pages\n- Breadcrumbs with structured data\n\n### 5. Indexation Strategy\n\n- Prioritize high-volume patterns\n- Noindex very thin variations\n- Manage crawl budget thoughtfully\n- Separate sitemaps by page type\n\n---\n\n## Quality Checks\n\n### Pre-Launch Checklist\n\n**Content quality:**\n- [ ] Each page provides unique value\n- [ ] Answers search intent\n- [ ] Readable and useful\n\n**Technical SEO:**\n- [ ] Unique titles and meta descriptions\n- [ ] Proper heading structure\n- [ ] Schema markup implemented\n- [ ] Page speed acceptable\n\n**Internal linking:**\n- [ ] Connected to site architecture\n- [ ] Related pages linked\n- [ ] No orphan pages\n\n**Indexation:**\n- [ ] In XML sitemap\n- [ ] Crawlable\n- [ ] No conflicting noindex\n\n### Post-Launch Monitoring\n\nTrack: Indexation rate, Rankings, Traffic, Engagement, Conversion\n\nWatch for: Thin content warnings, Ranking drops, Manual actions, Crawl errors\n\n---\n\n## Common Mistakes\n\n- **Thin content**: Just swapping city names in identical content\n- **Keyword cannibalization**: Multiple pages targeting same keyword\n- **Over-generation**: Creating pages with no search demand\n- **Poor data quality**: Outdated or incorrect information\n- **Ignoring UX**: Pages exist for Google, not users\n\n---\n\n## Output Format\n\n### Strategy Document\n- Opportunity analysis\n- Implementation plan\n- Content guidelines\n\n### Page Template\n- URL structure\n- Title/meta templates\n- Content outline\n- Schema markup\n\n---\n\n## Task-Specific Questions\n\n1. What keyword patterns are you targeting?\n2. What data do you have (or can acquire)?\n3. How many pages are you planning?\n4. What does your site authority look like?\n5. Who currently ranks for these terms?\n6. What\'s your technical stack?\n\n---\n\n## Related Skills\n\n- **seo-audit**: For auditing programmatic pages after launch\n- **schema-markup**: For adding structured data\n- **site-architecture**: For page hierarchy, URL structure, and internal linking\n- **competitor-alternatives**: For comparison page frameworks\n','939289647b2370744db0ad7011dc1da3','2026-10-26 11:22:08','2026-10-26 11:22:08','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(2355,'enc.7265666572656e6365732f706c6179626f6f6b732e6d64','skill_enc.70726f6772616d6d617469632d73656f__enc.312e312e30','# The 12 Programmatic SEO Playbooks\n\nBeyond mixing and matching data point permutations, these are the proven playbooks for programmatic SEO.\n\n## Contents\n- 1. Templates\n- 2. Curation\n- 3. Conversions\n- 4. Comparisons\n- 5. Examples\n- 6. Locations\n- 7. Personas\n- 8. Integrations\n- 9. Glossary\n- 10. Translations\n- 11. Directory\n- 12. Profiles\n- Choosing Your Playbook (Match to Your Assets, Combine Playbooks)\n\n## 1. Templates\n\n**Pattern**: \"[Type] template\" or \"free [type] template\"\n**Example searches**: \"resume template\", \"invoice template\", \"pitch deck template\"\n\n**What it is**: Downloadable or interactive templates users can use directly.\n\n**Why it works**:\n- High intent—people need it now\n- Shareable/linkable assets\n- Natural for product-led companies\n\n**Value requirements**:\n- Actually usable templates (not just previews)\n- Multiple variations per type\n- Quality comparable to paid options\n- Easy download/use flow\n\n**URL structure**: `/templates/[type]/` or `/templates/[category]/[type]/`\n\n---\n\n## 2. Curation\n\n**Pattern**: \"best [category]\" or \"top [number] [things]\"\n**Example searches**: \"best website builders\", \"top 10 crm software\", \"best free design tools\"\n\n**What it is**: Curated lists ranking or recommending options in a category.\n\n**Why it works**:\n- Comparison shoppers searching for guidance\n- High commercial intent\n- Evergreen with updates\n\n**Value requirements**:\n- Genuine evaluation criteria\n- Real testing or expertise\n- Regular updates (date visible)\n- Not just affiliate-driven rankings\n\n**URL structure**: `/best/[category]/` or `/[category]/best/`\n\n---\n\n## 3. Conversions\n\n**Pattern**: \"[X] to [Y]\" or \"[amount] [unit] in [unit]\"\n**Example searches**: \"$10 USD to GBP\", \"100 kg to lbs\", \"pdf to word\"\n\n**What it is**: Tools or pages that convert between formats, units, or currencies.\n\n**Why it works**:\n- Instant utility\n- Extremely high search volume\n- Repeat usage potential\n\n**Value requirements**:\n- Accurate, real-time data\n- Fast, functional tool\n- Related conversions suggested\n- Mobile-friendly interface\n\n**URL structure**: `/convert/[from]-to-[to]/` or `/[from]-to-[to]-converter/`\n\n---\n\n## 4. Comparisons\n\n**Pattern**: \"[X] vs [Y]\" or \"[X] alternative\"\n**Example searches**: \"webflow vs wordpress\", \"notion vs coda\", \"figma alternatives\"\n\n**What it is**: Head-to-head comparisons between products, tools, or options.\n\n**Why it works**:\n- High purchase intent\n- Clear search pattern\n- Scales with number of competitors\n\n**Value requirements**:\n- Honest, balanced analysis\n- Actual feature comparison data\n- Clear recommendation by use case\n- Updated when products change\n\n**URL structure**: `/compare/[x]-vs-[y]/` or `/[x]-vs-[y]/`\n\n*See also: competitor-alternatives skill for detailed frameworks*\n\n---\n\n## 5. Examples\n\n**Pattern**: \"[type] examples\" or \"[category] inspiration\"\n**Example searches**: \"saas landing page examples\", \"email subject line examples\", \"portfolio website examples\"\n\n**What it is**: Galleries or collections of real-world examples for inspiration.\n\n**Why it works**:\n- Research phase traffic\n- Highly shareable\n- Natural for design/creative tools\n\n**Value requirements**:\n- Real, high-quality examples\n- Screenshots or embeds\n- Categorization/filtering\n- Analysis of why they work\n\n**URL structure**: `/examples/[type]/` or `/[type]-examples/`\n\n---\n\n## 6. Locations\n\n**Pattern**: \"[service/thing] in [location]\"\n**Example searches**: \"coworking spaces in san diego\", \"dentists in austin\", \"best restaurants in brooklyn\"\n\n**What it is**: Location-specific pages for services, businesses, or information.\n\n**Why it works**:\n- Local intent is massive\n- Scales with geography\n- Natural for marketplaces/directories\n\n**Value requirements**:\n- Actual local data (not just city name swapped)\n- Local providers/options listed\n- Location-specific insights (pricing, regulations)\n- Map integration helpful\n\n**URL structure**: `/[service]/[city]/` or `/locations/[city]/[service]/`\n\n---\n\n## 7. Personas\n\n**Pattern**: \"[product] for [audience]\" or \"[solution] for [role/industry]\"\n**Example searches**: \"payroll software for agencies\", \"crm for real estate\", \"project management for freelancers\"\n\n**What it is**: Tailored landing pages addressing specific audience segments.\n\n**Why it works**:\n- Speaks directly to searcher\'s context\n- Higher conversion than generic pages\n- Scales with personas\n\n**Value requirements**:\n- Genuine persona-specific content\n- Relevant features highlighted\n- Testimonials from that segment\n- Use cases specific to audience\n\n**URL structure**: `/for/[persona]/` or `/solutions/[industry]/`\n\n---\n\n## 8. Integrations\n\n**Pattern**: \"[your product] [other product] integration\" or \"[product] + [product]\"\n**Example searches**: \"slack asana integration\", \"zapier airtable\", \"hubspot salesforce sync\"\n\n**What it is**: Pages explaining how your product works with other tools.\n\n**Why it works**:\n- Captures users of other products\n- High intent (they want the solution)\n- Scales with integration ecosystem\n\n**Value requirements**:\n- Real integration details\n- Setup instructions\n- Use cases for the combination\n- Working integration (not vaporware)\n\n**URL structure**: `/integrations/[product]/` or `/connect/[product]/`\n\n---\n\n## 9. Glossary\n\n**Pattern**: \"what is [term]\" or \"[term] definition\" or \"[term] meaning\"\n**Example searches**: \"what is pSEO\", \"api definition\", \"what does crm stand for\"\n\n**What it is**: Educational definitions of industry terms and concepts.\n\n**Why it works**:\n- Top-of-funnel awareness\n- Establishes expertise\n- Natural internal linking opportunities\n\n**Value requirements**:\n- Clear, accurate definitions\n- Examples and context\n- Related terms linked\n- More depth than a dictionary\n\n**URL structure**: `/glossary/[term]/` or `/learn/[term]/`\n\n---\n\n## 10. Translations\n\n**Pattern**: Same content in multiple languages\n**Example searches**: \"qué es pSEO\", \"was ist SEO\", \"マーケティングとは\"\n\n**What it is**: Your content translated and localized for other language markets.\n\n**Why it works**:\n- Opens entirely new markets\n- Lower competition in many languages\n- Multiplies your content reach\n\n**Value requirements**:\n- Quality translation (not just Google Translate)\n- Cultural localization\n- hreflang tags properly implemented\n- Native speaker review\n\n**URL structure**: `/[lang]/[page]/` or `yoursite.com/es/`, `/de/`, etc.\n\n---\n\n## 11. Directory\n\n**Pattern**: \"[category] tools\" or \"[type] software\" or \"[category] companies\"\n**Example searches**: \"ai copywriting tools\", \"email marketing software\", \"crm companies\"\n\n**What it is**: Comprehensive directories listing options in a category.\n\n**Why it works**:\n- Research phase capture\n- Link building magnet\n- Natural for aggregators/reviewers\n\n**Value requirements**:\n- Comprehensive coverage\n- Useful filtering/sorting\n- Details per listing (not just names)\n- Regular updates\n\n**URL structure**: `/directory/[category]/` or `/[category]-directory/`\n\n---\n\n## 12. Profiles\n\n**Pattern**: \"[person/company name]\" or \"[entity] + [attribute]\"\n**Example searches**: \"stripe ceo\", \"airbnb founding story\", \"elon musk companies\"\n\n**What it is**: Profile pages about notable people, companies, or entities.\n\n**Why it works**:\n- Informational intent traffic\n- Builds topical authority\n- Natural for B2B, news, research\n\n**Value requirements**:\n- Accurate, sourced information\n- Regularly updated\n- Unique insights or aggregation\n- Not just Wikipedia rehash\n\n**URL structure**: `/people/[name]/` or `/companies/[name]/`\n\n---\n\n## Choosing Your Playbook\n\n### Match to Your Assets\n\n| If you have... | Consider... |\n|----------------|-------------|\n| Proprietary data | Stats, Directories, Profiles |\n| Product with integrations | Integrations |\n| Design/creative product | Templates, Examples |\n| Multi-segment audience | Personas |\n| Local presence | Locations |\n| Tool or utility product | Conversions |\n| Content/expertise | Glossary, Curation |\n| International potential | Translations |\n| Competitor landscape | Comparisons |\n\n### Combine Playbooks\n\nYou can layer multiple playbooks:\n- **Locations + Personas**: \"Marketing agencies for startups in Austin\"\n- **Curation + Locations**: \"Best coworking spaces in San Diego\"\n- **Integrations + Personas**: \"Slack for sales teams\"\n- **Glossary + Translations**: Multi-language educational content\n','93ba45d6254ef5dbb10b0fa65cc9ea49','2026-10-26 11:22:08','2026-10-26 11:22:08','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(2356,'enc.6576616c732f6576616c732e6a736f6e','skill_enc.70726f6772616d6d617469632d73656f__enc.312e312e30','{\n  \"skill_name\": \"programmatic-seo\",\n  \"evals\": [\n    {\n      \"id\": 1,\n      \"prompt\": \"We want to create programmatic SEO pages for our CRM. We\'re thinking of \'CRM for [industry]\' pages — like \'CRM for Real Estate,\' \'CRM for Healthcare,\' etc. How should we approach this?\",\n      \"expected_output\": \"Should check for product-marketing-context.md first. Should identify this as the Personas playbook (industry-specific pages). Should apply the core principles: unique value per page (not just swapping the industry name), proprietary data or insights per industry, clean URL structure. Should recommend the implementation framework: keyword research for each industry variation, data requirements (what industry-specific content makes each page unique), template design, internal linking strategy between industry pages and main pages, and indexation strategy. Should warn against thin content (just template + keyword swap).\",\n      \"assertions\": [\n        \"Checks for product-marketing-context.md\",\n        \"Identifies as Personas playbook\",\n        \"Applies core principles (unique value, proprietary data, clean URLs)\",\n        \"Recommends keyword research per variation\",\n        \"Addresses data requirements for unique content\",\n        \"Provides template design guidance\",\n        \"Includes internal linking strategy\",\n        \"Warns against thin content\"\n      ],\n      \"files\": []\n    },\n    {\n      \"id\": 2,\n      \"prompt\": \"Create a comparison page strategy. We want pages like \'Notion vs Asana\', \'Notion vs Monday\', etc. for all our competitors. We have 15 competitors.\",\n      \"expected_output\": \"Should identify this as the Comparisons playbook. Should apply the programmatic approach for competitor comparison pages at scale. Should recommend: template structure for comparison pages, unique data per comparison (not just the same template with names swapped), keyword research for each \'[competitor A] vs [competitor B]\' variation, URL structure (/compare/notion-vs-asana), internal linking between comparison pages, and quality checks. Should cross-reference the competitor-alternatives skill for page content structure.\",\n      \"assertions\": [\n        \"Identifies as Comparisons playbook\",\n        \"Recommends template structure for scale\",\n        \"Addresses unique data per comparison\",\n        \"Includes keyword research for variations\",\n        \"Provides URL structure recommendation\",\n        \"Includes internal linking strategy\",\n        \"Cross-references competitor-alternatives skill\",\n        \"Applies quality checks\"\n      ],\n      \"files\": []\n    },\n    {\n      \"id\": 3,\n      \"prompt\": \"we want to rank for \'[tool name] integration\' keywords. we integrate with 50+ tools and want a page for each. like \'Slack integration\', \'Salesforce integration\' etc.\",\n      \"expected_output\": \"Should trigger on casual phrasing. Should identify this as the Integrations playbook. Should recommend: template design for integration pages (what it does, how to set up, use cases), unique content per integration (specific workflows, screenshots, setup steps), keyword research for \'[tool] + [your product] integration\', URL structure (/integrations/slack), hub page linking to all integration pages, and schema markup considerations. Should emphasize that each page needs genuine unique value, not just \'we integrate with [tool].\'\",\n      \"assertions\": [\n        \"Triggers on casual phrasing\",\n        \"Identifies as Integrations playbook\",\n        \"Recommends template with unique content per integration\",\n        \"Includes setup steps and use cases per page\",\n        \"Provides URL structure recommendation\",\n        \"Recommends hub page for all integrations\",\n        \"Emphasizes genuine unique value per page\"\n      ],\n      \"files\": []\n    },\n    {\n      \"id\": 4,\n      \"prompt\": \"We built 500 programmatic pages but Google isn\'t indexing most of them. Only 80 are in the index. What\'s going wrong?\",\n      \"expected_output\": \"Should diagnose the indexation problem. Should apply the quality checks and indexation strategy guidance. Should investigate: thin content (are pages providing unique value or just template + keyword?), crawl budget (500 pages may be fine but depends on site authority), internal linking (are the pages discoverable?), XML sitemap inclusion, duplicate/near-duplicate content issues. Should recommend specific fixes: improve content uniqueness, strengthen internal linking, submit sitemap, check robots.txt, use Search Console for indexation requests. Should warn that Google may choose not to index thin pages regardless.\",\n      \"assertions\": [\n        \"Diagnoses indexation problem\",\n        \"Investigates thin content as likely cause\",\n        \"Checks crawl budget considerations\",\n        \"Checks internal linking to programmatic pages\",\n        \"Checks XML sitemap and robots.txt\",\n        \"Recommends specific fixes for indexation\",\n        \"Warns about Google\'s thin content policies\"\n      ],\n      \"files\": []\n    },\n    {\n      \"id\": 5,\n      \"prompt\": \"Help me create a glossary section for our marketing automation platform. We want to define 200+ marketing terms and rank for \'[term] definition\' keywords.\",\n      \"expected_output\": \"Should identify this as the Glossary playbook. Should apply the template design: term definition page template (definition, examples, related terms, how it applies to the user\'s product), hub/index page linking to all terms, URL structure (/glossary/[term]), alphabetical and categorical navigation. Should address quality: each definition should provide genuine value beyond a dictionary definition. Should include internal linking strategy and schema markup (DefinedTerm schema). Should recommend starting with highest-volume terms.\",\n      \"assertions\": [\n        \"Identifies as Glossary playbook\",\n        \"Provides template design for term pages\",\n        \"Recommends hub/index page\",\n        \"Provides URL structure\",\n        \"Addresses content quality beyond dictionary definitions\",\n        \"Includes internal linking strategy\",\n        \"Recommends starting with highest-volume terms\"\n      ],\n      \"files\": []\n    },\n    {\n      \"id\": 6,\n      \"prompt\": \"Can you audit our existing programmatic SEO pages for technical issues? We have crawl errors and some pages return 404s.\",\n      \"expected_output\": \"Should recognize this is a technical SEO audit task, not a programmatic SEO strategy task. Should defer to or cross-reference the seo-audit skill, which handles crawlability, indexation, and technical SEO issues. Programmatic-seo focuses on strategy, template design, and content planning for scaled pages.\",\n      \"assertions\": [\n        \"Recognizes this as technical SEO audit task\",\n        \"References or defers to seo-audit skill\",\n        \"Explains that programmatic-seo is for strategy and template design\",\n        \"Does not attempt full technical SEO audit\"\n      ],\n      \"files\": []\n    }\n  ]\n}\n','7d72ace3b7bd1dbcad6f0bdafdb75008','2026-10-26 11:22:08','2026-10-26 11:22:08','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(2357,'SKILL.md','skill_enc.70726f6772616d6d617469632d73656f__enc.312e312e30','---\nname: programmatic-seo\ndescription: When the user wants to create SEO-driven pages at scale using templates and data. Also use when the user mentions \"programmatic SEO,\" \"template pages,\" \"pages at scale,\" \"directory pages,\" \"location pages,\" \"[keyword] + [city] pages,\" \"comparison pages,\" \"integration pages,\" \"building many pages for SEO,\" \"pSEO,\" \"generate 100 pages,\" \"data-driven pages,\" or \"templated landing pages.\" Use this whenever someone wants to create many similar pages targeting different keywords or locations. For auditing existing SEO issues, see seo-audit. For content strategy planning, see content-strategy.\nmetadata:\n  version: 1.1.0\n---\n\n# Programmatic SEO\n\nYou are an expert in programmatic SEO—building SEO-optimized pages at scale using templates and data. Your goal is to create pages that rank, provide value, and avoid thin content penalties.\n\n## Initial Assessment\n\n**Check for product marketing context first:**\nIf `.agents/product-marketing-context.md` exists (or `.claude/product-marketing-context.md` in older setups), read it before asking questions. Use that context and only ask for information not already covered or specific to this task.\n\nBefore designing a programmatic SEO strategy, understand:\n\n1. **Business Context**\n   - What\'s the product/service?\n   - Who is the target audience?\n   - What\'s the conversion goal for these pages?\n\n2. **Opportunity Assessment**\n   - What search patterns exist?\n   - How many potential pages?\n   - What\'s the search volume distribution?\n\n3. **Competitive Landscape**\n   - Who ranks for these terms now?\n   - What do their pages look like?\n   - Can you realistically compete?\n\n---\n\n## Core Principles\n\n### 1. Unique Value Per Page\n- Every page must provide value specific to that page\n- Not just swapped variables in a template\n- Maximize unique content—the more differentiated, the better\n\n### 2. Proprietary Data Wins\nHierarchy of data defensibility:\n1. Proprietary (you created it)\n2. Product-derived (from your users)\n3. User-generated (your community)\n4. Licensed (exclusive access)\n5. Public (anyone can use—weakest)\n\n### 3. Clean URL Structure\n**Use subfolders, not subdomains** — subfolders consolidate domain authority while subdomains split it:\n- Good: `yoursite.com/templates/resume/`\n- Bad: `templates.yoursite.com/resume/`\n\n### 4. Genuine Search Intent Match\nPages must actually answer what people are searching for.\n\n### 5. Quality Over Quantity\nBetter to have 100 great pages than 10,000 thin ones.\n\n### 6. Avoid Google Penalties\n- No doorway pages\n- No keyword stuffing\n- No duplicate content\n- Genuine utility for users\n\n---\n\n## The 12 Playbooks (Overview)\n\n| Playbook | Pattern | Example |\n|----------|---------|---------|\n| Templates | \"[Type] template\" | \"resume template\" |\n| Curation | \"best [category]\" | \"best website builders\" |\n| Conversions | \"[X] to [Y]\" | \"$10 USD to GBP\" |\n| Comparisons | \"[X] vs [Y]\" | \"webflow vs wordpress\" |\n| Examples | \"[type] examples\" | \"landing page examples\" |\n| Locations | \"[service] in [location]\" | \"dentists in austin\" |\n| Personas | \"[product] for [audience]\" | \"crm for real estate\" |\n| Integrations | \"[product A] [product B] integration\" | \"slack asana integration\" |\n| Glossary | \"what is [term]\" | \"what is pSEO\" |\n| Translations | Content in multiple languages | Localized content |\n| Directory | \"[category] tools\" | \"ai copywriting tools\" |\n| Profiles | \"[entity name]\" | \"stripe ceo\" |\n\n**For detailed playbook implementation**: See [references/playbooks.md](references/playbooks.md)\n\n---\n\n## Choosing Your Playbook\n\n| If you have... | Consider... |\n|----------------|-------------|\n| Proprietary data | Directories, Profiles |\n| Product with integrations | Integrations |\n| Design/creative product | Templates, Examples |\n| Multi-segment audience | Personas |\n| Local presence | Locations |\n| Tool or utility product | Conversions |\n| Content/expertise | Glossary, Curation |\n| Competitor landscape | Comparisons |\n\nYou can layer multiple playbooks (e.g., \"Best coworking spaces in San Diego\").\n\n---\n\n## Implementation Framework\n\n### 1. Keyword Pattern Research\n\n**Identify the pattern:**\n- What\'s the repeating structure?\n- What are the variables?\n- How many unique combinations exist?\n\n**Validate demand:**\n- Aggregate search volume\n- Volume distribution (head vs. long tail)\n- Trend direction\n\n### 2. Data Requirements\n\n**Identify data sources:**\n- What data populates each page?\n- Is it first-party, scraped, licensed, public?\n- How is it updated?\n\n### 3. Template Design\n\n**Page structure:**\n- Header with target keyword\n- Unique intro (not just variables swapped)\n- Data-driven sections\n- Related pages / internal links\n- CTAs appropriate to intent\n\n**Ensuring uniqueness:**\n- Each page needs unique value\n- Conditional content based on data\n- Original insights/analysis per page\n\n### 4. Internal Linking Architecture\n\n**Hub and spoke model:**\n- Hub: Main category page\n- Spokes: Individual programmatic pages\n- Cross-links between related spokes\n\n**Avoid orphan pages:**\n- Every page reachable from main site\n- XML sitemap for all pages\n- Breadcrumbs with structured data\n\n### 5. Indexation Strategy\n\n- Prioritize high-volume patterns\n- Noindex very thin variations\n- Manage crawl budget thoughtfully\n- Separate sitemaps by page type\n\n---\n\n## Quality Checks\n\n### Pre-Launch Checklist\n\n**Content quality:**\n- [ ] Each page provides unique value\n- [ ] Answers search intent\n- [ ] Readable and useful\n\n**Technical SEO:**\n- [ ] Unique titles and meta descriptions\n- [ ] Proper heading structure\n- [ ] Schema markup implemented\n- [ ] Page speed acceptable\n\n**Internal linking:**\n- [ ] Connected to site architecture\n- [ ] Related pages linked\n- [ ] No orphan pages\n\n**Indexation:**\n- [ ] In XML sitemap\n- [ ] Crawlable\n- [ ] No conflicting noindex\n\n### Post-Launch Monitoring\n\nTrack: Indexation rate, Rankings, Traffic, Engagement, Conversion\n\nWatch for: Thin content warnings, Ranking drops, Manual actions, Crawl errors\n\n---\n\n## Common Mistakes\n\n- **Thin content**: Just swapping city names in identical content\n- **Keyword cannibalization**: Multiple pages targeting same keyword\n- **Over-generation**: Creating pages with no search demand\n- **Poor data quality**: Outdated or incorrect information\n- **Ignoring UX**: Pages exist for Google, not users\n\n---\n\n## Output Format\n\n### Strategy Document\n- Opportunity analysis\n- Implementation plan\n- Content guidelines\n\n### Page Template\n- URL structure\n- Title/meta templates\n- Content outline\n- Schema markup\n\n---\n\n## Task-Specific Questions\n\n1. What keyword patterns are you targeting?\n2. What data do you have (or can acquire)?\n3. How many pages are you planning?\n4. What does your site authority look like?\n5. Who currently ranks for these terms?\n6. What\'s your technical stack?\n\n---\n\n## Related Skills\n\n- **seo-audit**: For auditing programmatic pages after launch\n- **schema-markup**: For adding structured data\n- **site-architecture**: For page hierarchy, URL structure, and internal linking\n- **competitor-alternatives**: For comparison page frameworks\n','939289647b2370744db0ad7011dc1da3','2026-10-26 11:22:08','2026-10-26 11:22:08','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(2358,'resource_config_MEMORY__md.json','agentspec__enc.6d61726b6574696e672d736f6369616c2d6d656469612d73747261746567697374__enc.302e302e31','{\"name\":\"MEMORY.md\",\"type\":\"config\",\"content\":\"# 长期记忆\\n\\n由运行时写入；本模板未预置业务记忆。\\n\",\"metadata\":{\"uniformId\":1792984927510},\"resourceIdentifier\":\"config::MEMORY.md\"}','27f56fde1674bf82f391bd451d8a36dc','2026-10-26 11:22:08','2026-10-26 11:22:08','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(2359,'enc.6576616c732f6576616c732e6a736f6e','skill_enc.70726f6772616d6d617469632d73656f__enc.312e312e30','{\n  \"skill_name\": \"programmatic-seo\",\n  \"evals\": [\n    {\n      \"id\": 1,\n      \"prompt\": \"We want to create programmatic SEO pages for our CRM. We\'re thinking of \'CRM for [industry]\' pages — like \'CRM for Real Estate,\' \'CRM for Healthcare,\' etc. How should we approach this?\",\n      \"expected_output\": \"Should check for product-marketing-context.md first. Should identify this as the Personas playbook (industry-specific pages). Should apply the core principles: unique value per page (not just swapping the industry name), proprietary data or insights per industry, clean URL structure. Should recommend the implementation framework: keyword research for each industry variation, data requirements (what industry-specific content makes each page unique), template design, internal linking strategy between industry pages and main pages, and indexation strategy. Should warn against thin content (just template + keyword swap).\",\n      \"assertions\": [\n        \"Checks for product-marketing-context.md\",\n        \"Identifies as Personas playbook\",\n        \"Applies core principles (unique value, proprietary data, clean URLs)\",\n        \"Recommends keyword research per variation\",\n        \"Addresses data requirements for unique content\",\n        \"Provides template design guidance\",\n        \"Includes internal linking strategy\",\n        \"Warns against thin content\"\n      ],\n      \"files\": []\n    },\n    {\n      \"id\": 2,\n      \"prompt\": \"Create a comparison page strategy. We want pages like \'Notion vs Asana\', \'Notion vs Monday\', etc. for all our competitors. We have 15 competitors.\",\n      \"expected_output\": \"Should identify this as the Comparisons playbook. Should apply the programmatic approach for competitor comparison pages at scale. Should recommend: template structure for comparison pages, unique data per comparison (not just the same template with names swapped), keyword research for each \'[competitor A] vs [competitor B]\' variation, URL structure (/compare/notion-vs-asana), internal linking between comparison pages, and quality checks. Should cross-reference the competitor-alternatives skill for page content structure.\",\n      \"assertions\": [\n        \"Identifies as Comparisons playbook\",\n        \"Recommends template structure for scale\",\n        \"Addresses unique data per comparison\",\n        \"Includes keyword research for variations\",\n        \"Provides URL structure recommendation\",\n        \"Includes internal linking strategy\",\n        \"Cross-references competitor-alternatives skill\",\n        \"Applies quality checks\"\n      ],\n      \"files\": []\n    },\n    {\n      \"id\": 3,\n      \"prompt\": \"we want to rank for \'[tool name] integration\' keywords. we integrate with 50+ tools and want a page for each. like \'Slack integration\', \'Salesforce integration\' etc.\",\n      \"expected_output\": \"Should trigger on casual phrasing. Should identify this as the Integrations playbook. Should recommend: template design for integration pages (what it does, how to set up, use cases), unique content per integration (specific workflows, screenshots, setup steps), keyword research for \'[tool] + [your product] integration\', URL structure (/integrations/slack), hub page linking to all integration pages, and schema markup considerations. Should emphasize that each page needs genuine unique value, not just \'we integrate with [tool].\'\",\n      \"assertions\": [\n        \"Triggers on casual phrasing\",\n        \"Identifies as Integrations playbook\",\n        \"Recommends template with unique content per integration\",\n        \"Includes setup steps and use cases per page\",\n        \"Provides URL structure recommendation\",\n        \"Recommends hub page for all integrations\",\n        \"Emphasizes genuine unique value per page\"\n      ],\n      \"files\": []\n    },\n    {\n      \"id\": 4,\n      \"prompt\": \"We built 500 programmatic pages but Google isn\'t indexing most of them. Only 80 are in the index. What\'s going wrong?\",\n      \"expected_output\": \"Should diagnose the indexation problem. Should apply the quality checks and indexation strategy guidance. Should investigate: thin content (are pages providing unique value or just template + keyword?), crawl budget (500 pages may be fine but depends on site authority), internal linking (are the pages discoverable?), XML sitemap inclusion, duplicate/near-duplicate content issues. Should recommend specific fixes: improve content uniqueness, strengthen internal linking, submit sitemap, check robots.txt, use Search Console for indexation requests. Should warn that Google may choose not to index thin pages regardless.\",\n      \"assertions\": [\n        \"Diagnoses indexation problem\",\n        \"Investigates thin content as likely cause\",\n        \"Checks crawl budget considerations\",\n        \"Checks internal linking to programmatic pages\",\n        \"Checks XML sitemap and robots.txt\",\n        \"Recommends specific fixes for indexation\",\n        \"Warns about Google\'s thin content policies\"\n      ],\n      \"files\": []\n    },\n    {\n      \"id\": 5,\n      \"prompt\": \"Help me create a glossary section for our marketing automation platform. We want to define 200+ marketing terms and rank for \'[term] definition\' keywords.\",\n      \"expected_output\": \"Should identify this as the Glossary playbook. Should apply the template design: term definition page template (definition, examples, related terms, how it applies to the user\'s product), hub/index page linking to all terms, URL structure (/glossary/[term]), alphabetical and categorical navigation. Should address quality: each definition should provide genuine value beyond a dictionary definition. Should include internal linking strategy and schema markup (DefinedTerm schema). Should recommend starting with highest-volume terms.\",\n      \"assertions\": [\n        \"Identifies as Glossary playbook\",\n        \"Provides template design for term pages\",\n        \"Recommends hub/index page\",\n        \"Provides URL structure\",\n        \"Addresses content quality beyond dictionary definitions\",\n        \"Includes internal linking strategy\",\n        \"Recommends starting with highest-volume terms\"\n      ],\n      \"files\": []\n    },\n    {\n      \"id\": 6,\n      \"prompt\": \"Can you audit our existing programmatic SEO pages for technical issues? We have crawl errors and some pages return 404s.\",\n      \"expected_output\": \"Should recognize this is a technical SEO audit task, not a programmatic SEO strategy task. Should defer to or cross-reference the seo-audit skill, which handles crawlability, indexation, and technical SEO issues. Programmatic-seo focuses on strategy, template design, and content planning for scaled pages.\",\n      \"assertions\": [\n        \"Recognizes this as technical SEO audit task\",\n        \"References or defers to seo-audit skill\",\n        \"Explains that programmatic-seo is for strategy and template design\",\n        \"Does not attempt full technical SEO audit\"\n      ],\n      \"files\": []\n    }\n  ]\n}\n','7d72ace3b7bd1dbcad6f0bdafdb75008','2026-10-26 11:22:08','2026-10-26 11:22:08','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(2360,'resource_config_MEMORY__md.json','agentspec__enc.6d61726b6574696e672d736f6369616c2d6d656469612d73747261746567697374__enc.302e302e31','{\"name\":\"MEMORY.md\",\"type\":\"config\",\"content\":\"# 长期记忆\\n\\n由运行时写入；本模板未预置业务记忆。\\n\",\"metadata\":{\"uniformId\":1792984927510},\"resourceIdentifier\":\"config::MEMORY.md\"}','27f56fde1674bf82f391bd451d8a36dc','2026-10-26 11:22:08','2026-10-26 11:22:08','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(2361,'manifest.json','agentspec__enc.6d61726b6574696e672d74696b746f6b2d73747261746567697374__enc.302e302e31','{\"name\":\"marketing-tiktok-strategist\",\"description\":\"TikTok 营销专家，适合出海营销场景。擅长病毒式内容创作、算法优化和社区运营，精通 TikTok 独特的文化生态和玩法。\",\"content\":\"{\\n  \\\"version\\\": \\\"1.0\\\",\\n  \\\"source\\\": {\\n    \\\"repository\\\": \\\"https://github.com/jnMetaCode/agency-agents-zh\\\",\\n    \\\"commit\\\": \\\"23c2746913fe46260450517fa5afb58afc61fed7\\\",\\n    \\\"original_path\\\": \\\"marketing/marketing-tiktok-strategist.md\\\",\\n    \\\"openclaw_mode\\\": true\\n  },\\n  \\\"description\\\": \\\"TikTok 营销专家，适合出海营销场景。擅长病毒式内容创作、算法优化和社区运营，精通 TikTok 独特的文化生态和玩法。\\\",\\n  \\\"tags\\\": [\\n    \\\"marketing\\\"\\n  ],\\n  \\\"worker\\\": {\\n    \\\"suggested_name\\\": \\\"marketing-tiktok-strategist\\\",\\n    \\\"base_image\\\": \\\"hiclaw/worker-agent:latest\\\",\\n    \\\"apt_packages\\\": [],\\n    \\\"pip_packages\\\": [],\\n    \\\"npm_packages\\\": []\\n  },\\n  \\\"proxy\\\": {\\n    \\\"suggested\\\": false,\\n    \\\"reason\\\": \\\"\\\"\\n  }\\n}\\n\",\"uniformId\":1792984927649,\"resources\":[{\"name\":\"jobs.json\",\"type\":\"crons\"},{\"name\":\"IDENTITY.md\",\"type\":\"config\"},{\"name\":\"tool-analysis.json\",\"type\":\"tool-analysis\"},{\"name\":\"AGENTS.md\",\"type\":\"config\"},{\"name\":\"SOUL.md\",\"type\":\"config\"},{\"name\":\"MEMORY.md\",\"type\":\"config\"}]}','6282f8ce3abbc63f5182514a9fd575e4','2026-10-26 11:22:08','2026-10-26 11:22:08','nacos_namespace_migrate',NULL,''