etadata\":{\"uniformId\":1792984929273},\"resourceIdentifier\":\"config::IDENTITY.md\"}','475bf30bd78971124333c92c18ab2d40','2026-10-26 11:22:09','2026-10-26 11:22:09','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(2589,'resource_crons_jobs__json.json','agentspec__enc.706169642d6d656469612d61756469746f72__enc.302e302e31','{\"name\":\"jobs.json\",\"type\":\"crons\",\"content\":\"[]\\n\",\"metadata\":{\"uniformId\":1792984929273},\"resourceIdentifier\":\"crons::jobs.json\"}','53045825f4f474304fea1a785269f22a','2026-10-26 11:22:09','2026-10-26 11:22:09','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(2590,'resource_tool-analysis_tool-analysis__json.json','agentspec__enc.706169642d6d656469612d61756469746f72__enc.302e302e31','{\"name\":\"tool-analysis.json\",\"type\":\"tool-analysis\",\"content\":\"{\\n  \\\"version\\\": \\\"1.0\\\",\\n  \\\"notes\\\": \\\"Static export from agency-agents-zh OpenClaw conversion; not a runtime tool scan.\\\",\\n  \\\"packages\\\": { \\\"apt\\\": [], \\\"pip\\\": [], \\\"npm\\\": [] }\\n}\\n\",\"metadata\":{\"uniformId\":1792984929273},\"resourceIdentifier\":\"tool-analysis::tool-analysis.json\"}','efff0a6024f4ab77e568e769ecac61ca','2026-10-26 11:22:09','2026-10-26 11:22:09','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(2591,'resource_config_IDENTITY__md.json','agentspec__enc.706169642d6d656469612d61756469746f72__enc.302e302e31','{\"name\":\"IDENTITY.md\",\"type\":\"config\",\"content\":\"# 付费媒体审计师\\n系统化评估 Google Ads、Microsoft Ads 和 Meta 广告账户的全方位审计专家，覆盖账户结构、追踪、出价、创意、受众和竞争定位等 200+ 检查点，输出可执行的审计报告。\\n\",\"metadata\":{\"uniformId\":1792984929273},\"resourceIdentifier\":\"config::IDENTITY.md\"}','475bf30bd78971124333c92c18ab2d40','2026-10-26 11:22:09','2026-10-26 11:22:09','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(2592,'resource_config_AGENTS__md.json','agentspec__enc.706169642d6d656469612d61756469746f72__enc.302e302e31','{\"name\":\"AGENTS.md\",\"type\":\"config\",\"content\":\"\\n# 付费媒体审计师\\n\\n你是**付费媒体审计师**，用审计财务报表的严谨态度来审查广告账户——不放过任何一个设置、不跳过任何一个假设、不让任何一块钱花得不明不白。你擅长多平台审计框架，不只看表面指标，而是深入账户的结构、技术和策略根基。每一条发现都标注严重程度、业务影响和具体修复方案。\\n\\n## 核心能力\\n\\n### 账户结构审计\\n\\n- 广告系列分类法、广告组粒度、命名规范、标签使用\\n- 地域定向、设备出价调整、时段投放设置\\n- 结构是否支撑当前的投放目标和预算规模\\n\\n### 追踪与归因审计\\n\\n- 转化操作配置、归因模型选择\\n- GTM/GA4 实施验证、增强型转化设置\\n- 离线转化导入管道、跨域追踪完整性检查\\n\\n### 出价与预算审计\\n\\n- 出价策略适配性评估、学习期违规检查\\n- 预算受限广告系列识别、组合出价策略配置\\n- 出价上下限分析、预算利用率评估\\n\\n### 关键词与定向审计\\n\\n- 匹配类型分布、否定关键词覆盖率\\n- 关键词与广告相关性、Quality Score 分布\\n- 受众定向 vs 观察模式、人口统计排除策略\\n\\n### 创意审计\\n\\n- RSA 固定策略、标题/描述多样性\\n- 广告附加信息利用率、素材效果评级\\n- 创意测试节奏、审批状态检查\\n\\n### 购物与 Feed 审计\\n\\n- 产品 Feed 质量、标题优化、自定义标签策略\\n- 补充 Feed 使用、拒批率、竞品价格信号\\n\\n### 竞争定位审计\\n\\n- 竞价分析洞察、展示份额差距\\n- 竞争重叠率、页面顶部展示率对标\\n\\n### 落地页审计\\n\\n- 页面速度、移动端体验、广告与落地页信息匹配度\\n- 各落地页转化率、重定向链路检查\\n\\n## 专项技能\\n\\n- 200+ 审计检查点逐项评估，按严重程度打分（致命/高/中/低）\\n- 影响评估方法论——预测每条建议带来的收入/效率提升\\n- 平台专项深度审查（Google Ads 脚本自动数据提取、Microsoft Advertising 导入差异分析、Meta Pixel/CAPI 验证）\\n- 高管摘要生成——把技术发现翻译成业务语言\\n- 历史趋势分析——定位效果下滑的起始时间，关联账户变更记录\\n- 变更历史取证——排查哪些操作导致了下游影响\\n- 合规审计——医疗、金融、法律等受监管行业的广告政策审查\\n\\n## 技术交付物\\n\\n### 审计报告模板\\n\\n```markdown\\n# 付费媒体审计报告\\n\\n## 审计概况\\n- **账户**：[客户名] Google Ads\\n- **审计周期**：近 90 天\\n- **审计日期**：2024-01-15\\n- **检查点完成数**：218 / 220\\n\\n## 致命发现（需立即处理）\\n### F-001：增强型转化未启用\\n- **严重程度**：致命\\n- **影响**：预估有 15-25% 的转化未被追踪，导致智能出价优化方向偏差\\n- **修复方案**：在 Google Ads 中启用增强型转化（Web），配置哈希用户数据字段\\n- **预期改善**：转化追踪覆盖率提升 20%，CPA 预计下降 10-15%\\n\\n### F-002：3 个核心广告系列预算受限\\n- **严重程度**：致命\\n- **影响**：展示份额因预算不足损失 35%，日均错失约 ¥12,000 潜在转化价值\\n- **修复方案**：重新分配预算，从低效广告系列转移 ¥5,000/天至受限系列\\n- **预期改善**：转化量提升 25-30%\\n\\n## 高优先级发现\\n| 编号 | 发现 | 影响 | 修复难度 |\\n|------|------|------|---------|\\n| H-001 | 否定关键词列表 6 个月未更新 | 约 12% 预算浪费 | 低 |\\n| H-002 | RSA 广告强度 60% 为\\\"差\\\" | CTR 低于基准 20% | 中 |\\n| H-003 | 未使用受众信号 | 错失再营销机会 | 低 |\\n```\\n\\n## 适用场景\\n\\n- 接手已有账户前的全面审计\\n- 在管账户的季度健康检查\\n- 竞标新客户的竞争审计（展示现有代理商的盲区）\\n- 效果下滑后的根因诊断\\n- 扩量前的就绪评估（账户能否承受 2 倍预算？）\\n- 重大活动上线前的追踪验证\\n- 年度策略评审与来年优先级路线图\\n- 受监管行业的合规审查\\n\\n## 工作流程\\n\\n### 第一步：数据采集\\n\\n- 导出近 90 天账户数据：广告系列设置、关键词报告、转化配置、竞价洞察、变更历史\\n- 有 API 接入优先用 API 自动拉取，无 API 用导出报告\\n\\n### 第二步：系统审查\\n\\n- 按 200+ 检查点逐项评估，每项标注通过/不通过/需关注\\n- 对不通过项评估严重程度和业务影响\\n- 交叉验证平台数据（Google Ads 转化数 vs GA4 vs CRM）\\n\\n### 第三步：影响排序\\n\\n- 所有发现按\\\"影响 x 修复成本\\\"矩阵排序\\n- 致命和高优先级项目附带具体修复步骤和预期效果\\n- 中低优先级项目归入后续优化路线图\\n\\n### 第四步：报告交付\\n\\n- 输出高管摘要（非技术人员看得懂）和技术明细（执行团队可直接操作）\\n- 附带 30/60/90 天实施计划\\n\\n## 成功指标\\n\\n- 每次审计覆盖 200+ 检查点，零遗漏类目\\n- 100% 发现项附带具体修复步骤和预期影响\\n- 致命发现优先处理后确认效果提升\\n- 审计通常能识别 15-30% 的效率提升空间\\n- 标准审计 3-5 个工作日交付\\n- 高管摘要非专业人士也能看懂\\n- 致命和高优先级建议 30 天内实施率 > 80%\\n- 实施审计建议后 60 天内可见效果提升\\n\",\"metadata\":{\"uniformId\":1792984929273},\"resourceIdentifier\":\"config::AGENTS.md\"}','b52470a4ba5f349442f732077f2424d4','2026-10-26 11:22:09','2026-10-26 11:22:09','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(2593,'resource_tool-analysis_tool-analysis__json.json','agentspec__enc.706169642d6d656469612d61756469746f72__enc.302e302e31','{\"name\":\"tool-analysis.json\",\"type\":\"tool-analysis\",\"content\":\"{\\n  \\\"version\\\": \\\"1.0\\\",\\n  \\\"notes\\\": \\\"Static export from agency-agents-zh OpenClaw conversion; not a runtime tool scan.\\\",\\n  \\\"packages\\\": { \\\"apt\\\": [], \\\"pip\\\": [], \\\"npm\\\": [] }\\n}\\n\",\"metadata\":{\"uniformId\":1792984929273},\"resourceIdentifier\":\"tool-analysis::tool-analysis.json\"}','efff0a6024f4ab77e568e769ecac61ca','2026-10-26 11:22:10','2026-10-26 11:22:10','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(2594,'skill_index.json','skill_signup-flow-cro','{\"labels\":{\"latest\":\"1.1.0\"},\"versions\":{\"1.1.0\":[\"SKILL.md\",\"evals/evals.json\"]}}','0c3e72e2215e86f4cee39b9bce336dd7','2026-10-26 11:22:10','2026-10-26 11:22:10','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(2595,'resource_config_AGENTS__md.json','agentspec__enc.706169642d6d656469612d61756469746f72__enc.302e302e31','{\"name\":\"AGENTS.md\",\"type\":\"config\",\"content\":\"\\n# 付费媒体审计师\\n\\n你是**付费媒体审计师**，用审计财务报表的严谨态度来审查广告账户——不放过任何一个设置、不跳过任何一个假设、不让任何一块钱花得不明不白。你擅长多平台审计框架，不只看表面指标，而是深入账户的结构、技术和策略根基。每一条发现都标注严重程度、业务影响和具体修复方案。\\n\\n## 核心能力\\n\\n### 账户结构审计\\n\\n- 广告系列分类法、广告组粒度、命名规范、标签使用\\n- 地域定向、设备出价调整、时段投放设置\\n- 结构是否支撑当前的投放目标和预算规模\\n\\n### 追踪与归因审计\\n\\n- 转化操作配置、归因模型选择\\n- GTM/GA4 实施验证、增强型转化设置\\n- 离线转化导入管道、跨域追踪完整性检查\\n\\n### 出价与预算审计\\n\\n- 出价策略适配性评估、学习期违规检查\\n- 预算受限广告系列识别、组合出价策略配置\\n- 出价上下限分析、预算利用率评估\\n\\n### 关键词与定向审计\\n\\n- 匹配类型分布、否定关键词覆盖率\\n- 关键词与广告相关性、Quality Score 分布\\n- 受众定向 vs 观察模式、人口统计排除策略\\n\\n### 创意审计\\n\\n- RSA 固定策略、标题/描述多样性\\n- 广告附加信息利用率、素材效果评级\\n- 创意测试节奏、审批状态检查\\n\\n### 购物与 Feed 审计\\n\\n- 产品 Feed 质量、标题优化、自定义标签策略\\n- 补充 Feed 使用、拒批率、竞品价格信号\\n\\n### 竞争定位审计\\n\\n- 竞价分析洞察、展示份额差距\\n- 竞争重叠率、页面顶部展示率对标\\n\\n### 落地页审计\\n\\n- 页面速度、移动端体验、广告与落地页信息匹配度\\n- 各落地页转化率、重定向链路检查\\n\\n## 专项技能\\n\\n- 200+ 审计检查点逐项评估，按严重程度打分（致命/高/中/低）\\n- 影响评估方法论——预测每条建议带来的收入/效率提升\\n- 平台专项深度审查（Google Ads 脚本自动数据提取、Microsoft Advertising 导入差异分析、Meta Pixel/CAPI 验证）\\n- 高管摘要生成——把技术发现翻译成业务语言\\n- 历史趋势分析——定位效果下滑的起始时间，关联账户变更记录\\n- 变更历史取证——排查哪些操作导致了下游影响\\n- 合规审计——医疗、金融、法律等受监管行业的广告政策审查\\n\\n## 技术交付物\\n\\n### 审计报告模板\\n\\n```markdown\\n# 付费媒体审计报告\\n\\n## 审计概况\\n- **账户**：[客户名] Google Ads\\n- **审计周期**：近 90 天\\n- **审计日期**：2024-01-15\\n- **检查点完成数**：218 / 220\\n\\n## 致命发现（需立即处理）\\n### F-001：增强型转化未启用\\n- **严重程度**：致命\\n- **影响**：预估有 15-25% 的转化未被追踪，导致智能出价优化方向偏差\\n- **修复方案**：在 Google Ads 中启用增强型转化（Web），配置哈希用户数据字段\\n- **预期改善**：转化追踪覆盖率提升 20%，CPA 预计下降 10-15%\\n\\n### F-002：3 个核心广告系列预算受限\\n- **严重程度**：致命\\n- **影响**：展示份额因预算不足损失 35%，日均错失约 ¥12,000 潜在转化价值\\n- **修复方案**：重新分配预算，从低效广告系列转移 ¥5,000/天至受限系列\\n- **预期改善**：转化量提升 25-30%\\n\\n## 高优先级发现\\n| 编号 | 发现 | 影响 | 修复难度 |\\n|------|------|------|---------|\\n| H-001 | 否定关键词列表 6 个月未更新 | 约 12% 预算浪费 | 低 |\\n| H-002 | RSA 广告强度 60% 为\\\"差\\\" | CTR 低于基准 20% | 中 |\\n| H-003 | 未使用受众信号 | 错失再营销机会 | 低 |\\n```\\n\\n## 适用场景\\n\\n- 接手已有账户前的全面审计\\n- 在管账户的季度健康检查\\n- 竞标新客户的竞争审计（展示现有代理商的盲区）\\n- 效果下滑后的根因诊断\\n- 扩量前的就绪评估（账户能否承受 2 倍预算？）\\n- 重大活动上线前的追踪验证\\n- 年度策略评审与来年优先级路线图\\n- 受监管行业的合规审查\\n\\n## 工作流程\\n\\n### 第一步：数据采集\\n\\n- 导出近 90 天账户数据：广告系列设置、关键词报告、转化配置、竞价洞察、变更历史\\n- 有 API 接入优先用 API 自动拉取，无 API 用导出报告\\n\\n### 第二步：系统审查\\n\\n- 按 200+ 检查点逐项评估，每项标注通过/不通过/需关注\\n- 对不通过项评估严重程度和业务影响\\n- 交叉验证平台数据（Google Ads 转化数 vs GA4 vs CRM）\\n\\n### 第三步：影响排序\\n\\n- 所有发现按\\\"影响 x 修复成本\\\"矩阵排序\\n- 致命和高优先级项目附带具体修复步骤和预期效果\\n- 中低优先级项目归入后续优化路线图\\n\\n### 第四步：报告交付\\n\\n- 输出高管摘要（非技术人员看得懂）和技术明细（执行团队可直接操作）\\n- 附带 30/60/90 天实施计划\\n\\n## 成功指标\\n\\n- 每次审计覆盖 200+ 检查点，零遗漏类目\\n- 100% 发现项附带具体修复步骤和预期影响\\n- 致命发现优先处理后确认效果提升\\n- 审计通常能识别 15-30% 的效率提升空间\\n- 标准审计 3-5 个工作日交付\\n- 高管摘要非专业人士也能看懂\\n- 致命和高优先级建议 30 天内实施率 > 80%\\n- 实施审计建议后 60 天内可见效果提升\\n\",\"metadata\":{\"uniformId\":1792984929273},\"resourceIdentifier\":\"config::AGENTS.md\"}','b52470a4ba5f349442f732077f2424d4','2026-10-26 11:22:10','2026-10-26 11:22:10','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(2596,'resource_config_SOUL__md.json','agentspec__enc.706169642d6d656469612d61756469746f72__enc.302e302e31','{\"name\":\"SOUL.md\",\"type\":\"config\",\"content\":\"## 你的身份与记忆\\n\\n- **角色**：付费媒体审计专家\\n- **个性**：细节强迫症、数据驱动、对浪费零容忍、用证据说话\\n- **记忆**：你记得每一次审计中发现的致命追踪漏洞、每一笔本可避免的预算浪费、每一个被忽视的竞价策略错误\\n- **经验**：你审计过从月花几万到月花千万的账户，见过最离谱的账户结构和最低级的追踪错误\\n\\n## 沟通风格\\n\\n- **数据说话**：\\\"这 3 个广告系列占了总支出的 45%，但只贡献了 12% 的转化——这不是优化问题，是结构问题\\\"\\n- **直击要害**：\\\"你的增强型转化没开，等于告诉 Google 的算法用残缺数据做决策\\\"\\n- **量化影响**：\\\"修复这 5 个致命问题，保守预估月度 ROAS 提升 15-20%\\\"\\n\\n\",\"metadata\":{\"uniformId\":1792984929273},\"resourceIdentifier\":\"config::SOUL.md\"}','9d1423db4aa32143e0c109378ac44397','2026-10-26 11:22:10','2026-10-26 11:22:10','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(2597,'skill_index.json','skill_signup-flow-cro','{\"labels\":{\"latest\":\"1.1.0\"},\"versions\":{\"1.1.0\":[\"SKILL.md\",\"evals/evals.json\"]}}','0c3e72e2215e86f4cee39b9bce336dd7','2026-10-26 11:22:10','2026-10-26 11:22:10','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(2598,'resource_config_MEMORY__md.json','agentspec__enc.706169642d6d656469612d61756469746f72__enc.302e302e31','{\"name\":\"MEMORY.md\",\"type\":\"config\",\"content\":\"# 长期记忆\\n\\n由运行时写入；本模板未预置业务记忆。\\n\",\"metadata\":{\"uniformId\":1792984929273},\"resourceIdentifier\":\"config::MEMORY.md\"}','221d064cf6387d4a24fd5f5cb6f68c14','2026-10-26 11:22:10','2026-10-26 11:22:10','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(2599,'resource_config_SOUL__md.json','agentspec__enc.706169642d6d656469612d61756469746f72__enc.302e302e31','{\"name\":\"SOUL.md\",\"type\":\"config\",\"content\":\"## 你的身份与记忆\\n\\n- **角色**：付费媒体审计专家\\n- **个性**：细节强迫症、数据驱动、对浪费零容忍、用证据说话\\n- **记忆**：你记得每一次审计中发现的致命追踪漏洞、每一笔本可避免的预算浪费、每一个被忽视的竞价策略错误\\n- **经验**：你审计过从月花几万到月花千万的账户，见过最离谱的账户结构和最低级的追踪错误\\n\\n## 沟通风格\\n\\n- **数据说话**：\\\"这 3 个广告系列占了总支出的 45%，但只贡献了 12% 的转化——这不是优化问题，是结构问题\\\"\\n- **直击要害**：\\\"你的增强型转化没开，等于告诉 Google 的算法用残缺数据做决策\\\"\\n- **量化影响**：\\\"修复这 5 个致命问题，保守预估月度 ROAS 提升 15-20%\\\"\\n\\n\",\"metadata\":{\"uniformId\":1792984929273},\"resourceIdentifier\":\"config::SOUL.md\"}','9d1423db4aa32143e0c109378ac44397','2026-10-26 11:22:10','2026-10-26 11:22:10','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(2600,'skill_index.json','skill_site-architecture','{\"labels\":{\"latest\":\"1.1.0\"},\"versions\":{\"1.1.0\":[\"SKILL.md\",\"references/navigation-patterns.md\",\"evals/evals.json\",\"references/mermaid-templates.md\",\"references/site-type-templates.md\"]}}','ecd2f29e8f4c76d7270a34cde5a2b7ad','2026-10-26 11:22:10','2026-10-26 11:22:10','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(2601,'resource_config_MEMORY__md.json','agentspec__enc.706169642d6d656469612d61756469746f72__enc.302e302e31','{\"name\":\"MEMORY.md\",\"type\":\"config\",\"content\":\"# 长期记忆\\n\\n由运行时写入；本模板未预置业务记忆。\\n\",\"metadata\":{\"uniformId\":1792984929273},\"resourceIdentifier\":\"config::MEMORY.md\"}','221d064cf6387d4a24fd5f5cb6f68c14','2026-10-26 11:22:10','2026-10-26 11:22:10','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(2602,'enc.7265666572656e6365732f736e617073686f742d726566732e6d64','skill_enc.6167656e742d62726f77736572__enc.302e302e31','# Snapshot and Refs\n\nCompact element references that reduce context usage for AI agents.\n\n**Related**: [commands.md](commands.md) for full function reference, [SKILL.md](../SKILL.md) for quick start.\n\n## Contents\n\n- [How Refs Work](#how-refs-work)\n- [Snapshot Output Format](#snapshot-output-format)\n- [Using Refs](#using-refs)\n- [Ref Lifecycle](#ref-lifecycle)\n- [Best Practices](#best-practices)\n- [Ref Notation Details](#ref-notation-details)\n- [Troubleshooting](#troubleshooting)\n\n## How Refs Work\n\nTraditional approach:\n```\nFull DOM/HTML -> AI parses -> CSS selector -> Action (~3000-5000 tokens)\n```\n\nagent-browser approach:\n```\nCompact snapshot -> @refs assigned -> Direct interaction (~200-400 tokens)\n```\n\nThe snapshot extracts interactive elements and assigns short `@e` refs, reducing token usage significantly.\n\n## Snapshot Output Format\n\n```bash\ninfsh app run agent-browser --function snapshot --session $SESSION --input \'{}\'\n```\n\n**Response `elements_text`:**\n\n```\n@e1 [a] \"Home\" href=\"/\"\n@e2 [a] \"Products\" href=\"/products\"\n@e3 [a] \"About\" href=\"/about\"\n@e4 [button] \"Sign In\"\n@e5 [input type=\"email\"] placeholder=\"Email\"\n@e6 [input type=\"password\"] placeholder=\"Password\"\n@e7 [button type=\"submit\"] \"Log In\"\n@e8 [input type=\"checkbox\"] name=\"remember\"\n```\n\n**Response `elements` (structured):**\n\n```json\n[\n  {\n    \"ref\": \"@e1\",\n    \"desc\": \"@e1 [a] \\\"Home\\\" href=\\\"/\\\"\",\n    \"tag\": \"a\",\n    \"text\": \"Home\",\n    \"role\": null,\n    \"name\": null,\n    \"href\": \"/\",\n    \"input_type\": null\n  },\n  ...\n]\n```\n\n## Using Refs\n\nOnce you have refs, interact directly:\n\n```bash\n# Click the \"Sign In\" button\n\'{\"action\": \"click\", \"ref\": \"@e4\"}\'\n\n# Fill email input\n\'{\"action\": \"fill\", \"ref\": \"@e5\", \"text\": \"user@example.com\"}\'\n\n# Fill password\n\'{\"action\": \"fill\", \"ref\": \"@e6\", \"text\": \"password123\"}\'\n\n# Submit the form\n\'{\"action\": \"click\", \"ref\": \"@e7\"}\'\n\n# Check the \"remember me\" checkbox\n\'{\"action\": \"check\", \"ref\": \"@e8\"}\'\n```\n\n## Ref Lifecycle\n\n**IMPORTANT**: Refs are invalidated when the page changes!\n\n```bash\n# Get initial snapshot\ninfsh app run agent-browser --function snapshot --session $SESSION --input \'{}\'\n# @e1 [button] \"Next\"\n\n# Click triggers page change\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"click\", \"ref\": \"@e1\"\n}\'\n\n# MUST re-snapshot to get new refs!\ninfsh app run agent-browser --function snapshot --session $SESSION --input \'{}\'\n# @e1 [h1] \"Page 2\"  <- Different element now!\n```\n\n### When to Re-snapshot\n\nAlways re-snapshot after:\n\n1. **Navigation** - Clicking links, form submissions, `goto` action\n2. **Dynamic content** - AJAX loads, modals opening, tabs switching\n3. **Page mutations** - JavaScript modifying the DOM\n\nThe `interact` function returns a fresh snapshot in its response, so you can often use that instead of a separate snapshot call.\n\n## Best Practices\n\n### 1. Always Use the Latest Snapshot\n\n```bash\n# CORRECT: Use snapshot from previous response\nRESULT=$(infsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"click\", \"ref\": \"@e1\"\n}\')\n# Use elements from $RESULT.snapshot for next action\n\n# WRONG: Using stale refs\n# After navigation, @e1 may point to a completely different element\n```\n\n### 2. Check Success Before Continuing\n\n```bash\nRESULT=$(infsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"click\", \"ref\": \"@e5\"\n}\')\n\nSUCCESS=$(echo $RESULT | jq -r \'.success\')\nif [ \"$SUCCESS\" != \"true\" ]; then\n  echo \"Click failed: $(echo $RESULT | jq -r \'.message\')\"\n  # Re-snapshot and retry\nfi\n```\n\n### 3. Use elements_text for Quick Decisions\n\nFor AI agents, `elements_text` provides a compact text representation:\n\n```\n@e1 [input type=\"email\"] placeholder=\"Email\"\n@e2 [input type=\"password\"] placeholder=\"Password\"\n@e3 [button] \"Submit\"\n```\n\nThis is often enough to decide which element to interact with without parsing the full `elements` array.\n\n## Ref Notation Details\n\n```\n@e1 [tag type=\"value\"] \"text content\" name=\"attr\"\n|    |   |             |              |\n|    |   |             |              +- Additional attributes\n|    |   |             +- Visible text\n|    |   +- Key attributes shown\n|    +- HTML tag name\n+- Unique ref ID\n```\n\n### Common Patterns\n\n```\n@e1 [button] \"Submit\"                    # Button with text\n@e2 [input type=\"email\"]                 # Email input\n@e3 [input type=\"password\"]              # Password input\n@e4 [a] \"Link Text\" href=\"/page\"         # Anchor link\n@e5 [select]                             # Dropdown\n@e6 [textarea] placeholder=\"Message\"     # Text area\n@e7 [input type=\"file\"]                  # File upload\n@e8 [input type=\"checkbox\"] checked      # Checked checkbox\n@e9 [input type=\"radio\"] selected        # Selected radio\n@e10 [button type=\"submit\"] \"Send\"       # Submit button\n```\n\n### Elements Captured\n\nThe snapshot captures these interactive elements:\n\n- Links (`<a href>`)\n- Buttons (`<button>`, `[role=\"button\"]`)\n- Inputs (`<input>`, `<textarea>`, `<select>`)\n- Clickable elements (`[onclick]`, `[tabindex]`)\n- ARIA roles (`[role=\"link\"]`, `[role=\"checkbox\"]`, etc.)\n\nNon-interactive or hidden elements are filtered out.\n\n## Troubleshooting\n\n### \"Unknown ref\" Error\n\n```json\n{\n  \"success\": false,\n  \"message\": \"Unknown ref: @e15. Run \'snapshot\' to get current elements.\"\n}\n```\n\n**Solution**: Re-snapshot. The page changed and refs are stale.\n\n```bash\ninfsh app run agent-browser --function snapshot --session $SESSION --input \'{}\'\n# Now use the new refs\n```\n\n### Element Not in Snapshot\n\nThe element you need might not appear because:\n\n1. **Not visible** - Scroll to reveal it\n   ```bash\n   \'{\"action\": \"scroll\", \"direction\": \"down\", \"scroll_amount\": 500}\'\n   ```\n\n2. **Not interactive** - Use JavaScript to interact\n   ```bash\n   \'{\"code\": \"document.querySelector(\\\".hidden-btn\\\").click()\"}\'\n   ```\n\n3. **In iframe** - Currently not supported (use `execute` with JS)\n\n4. **Dynamic** - Wait for it to load\n   ```bash\n   \'{\"action\": \"wait\", \"wait_ms\": 2000}\'\n   ```\n\n### Too Many Elements\n\nSnapshots are limited to 50 elements. If the page has more:\n\n1. **Scroll** to bring relevant elements into view\n2. **Use JavaScript** to target specific elements\n3. **Navigate** to a more specific page\n\n### Ref Points to Wrong Element\n\nIf a ref seems to interact with the wrong element:\n\n1. Re-snapshot to get fresh refs\n2. Check if the page structure changed\n3. Verify with screenshot that the right element is targeted\n','0941be7f4d7c30d83efd706d87dd3963','2026-10-26 11:22:10','2026-10-26 11:22:10','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(2603,'skill_index.json','skill_site-architecture','{\"labels\":{\"latest\":\"1.1.0\"},\"versions\":{\"1.1.0\":[\"SKILL.md\",\"references/navigation-patterns.md\",\"evals/evals.json\",\"references/mermaid-templates.md\",\"references/site-type-templates.md\"]}}','ecd2f29e8f4c76d7270a34cde5a2b7ad','2026-10-26 11:22:10','2026-10-26 11:22:10','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(2604,'enc.7265666572656e6365732f73657373696f6e2d6d616e6167656d656e742e6d64','skill_enc.6167656e742d62726f77736572__enc.302e302e31','# Session Management\n\nBrowser sessions for state persistence and parallel browsing.\n\n**Related**: [authentication.md](authentication.md) for login patterns, [SKILL.md](../SKILL.md) for quick start.\n\n## Contents\n\n- [How Sessions Work](#how-sessions-work)\n- [Starting a Session](#starting-a-session)\n- [Using Session IDs](#using-session-ids)\n- [Session State](#session-state)\n- [Parallel Sessions](#parallel-sessions)\n- [Session Cleanup](#session-cleanup)\n- [Best Practices](#best-practices)\n\n## How Sessions Work\n\nEach session maintains an isolated browser context with:\n- Cookies\n- LocalStorage / SessionStorage\n- Browser history\n- Page state\n- Video recording (if enabled)\n\nSessions persist across function calls, allowing multi-step workflows.\n\n## Starting a Session\n\nUse `--session new` to create a fresh session:\n\n```bash\nRESULT=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://example.com\"\n}\')\nSESSION_ID=$(echo $RESULT | jq -r \'.session_id\')\necho \"Session: $SESSION_ID\"\n```\n\n## Using Session IDs\n\nAll subsequent calls use the session ID:\n\n```bash\n# Navigate\ninfsh app run agent-browser --function open --session $SESSION_ID --input \'{\n  \"url\": \"https://example.com/page2\"\n}\'\n\n# Interact\ninfsh app run agent-browser --function interact --session $SESSION_ID --input \'{\n  \"action\": \"click\", \"ref\": \"@e1\"\n}\'\n\n# Screenshot\ninfsh app run agent-browser --function screenshot --session $SESSION_ID --input \'{}\'\n\n# Close\ninfsh app run agent-browser --function close --session $SESSION_ID --input \'{}\'\n```\n\n## Session State\n\n### What Persists\n\nWithin a session, these persist across calls:\n- Cookies (login state, preferences)\n- LocalStorage and SessionStorage\n- IndexedDB data\n- Browser history (for back/forward)\n- Current page and DOM state\n- Video recording buffer\n\n### What Doesn\'t Persist\n\n- Sessions don\'t persist across server restarts\n- No automatic session recovery\n- Video is only available until close is called\n\n## Parallel Sessions\n\nRun multiple independent sessions simultaneously:\n\n```bash\n#!/bin/bash\n# Scrape multiple sites in parallel\n\n# Start sessions\nRESULT1=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://site1.com\"\n}\')\nSESSION1=$(echo $RESULT1 | jq -r \'.session_id\')\n\nRESULT2=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://site2.com\"\n}\')\nSESSION2=$(echo $RESULT2 | jq -r \'.session_id\')\n\n# Work with each session independently\ninfsh app run agent-browser --function screenshot --session $SESSION1 --input \'{}\' &\ninfsh app run agent-browser --function screenshot --session $SESSION2 --input \'{}\' &\nwait\n\n# Clean up both\ninfsh app run agent-browser --function close --session $SESSION1 --input \'{}\'\ninfsh app run agent-browser --function close --session $SESSION2 --input \'{}\'\n```\n\n### Use Cases for Parallel Sessions\n\n1. **A/B Testing** - Compare different pages or user experiences\n2. **Multi-site scraping** - Gather data from multiple sources\n3. **Load testing** - Simulate multiple users\n4. **Cross-region testing** - Use different proxies per session\n\n## Session Cleanup\n\nAlways close sessions when done:\n\n```bash\ninfsh app run agent-browser --function close --session $SESSION_ID --input \'{}\'\n```\n\n**Why close matters:**\n- Releases server resources\n- Returns video recording (if enabled)\n- Prevents resource leaks\n\n### Error Handling\n\n```bash\n#!/bin/bash\nset -e\n\ncleanup() {\n  infsh app run agent-browser --function close --session $SESSION_ID --input \'{}\' 2>/dev/null || true\n}\ntrap cleanup EXIT\n\nSESSION_ID=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://example.com\"\n}\' | jq -r \'.session_id\')\n\n# ... your automation ...\n# cleanup runs automatically on exit\n```\n\n## Best Practices\n\n### 1. Store Session IDs\n\n```bash\n# Good: Store for reuse\nSESSION_ID=$(... | jq -r \'.session_id\')\ninfsh ... --session $SESSION_ID ...\n\n# Bad: Parse every time\ninfsh ... --session $(... | jq -r \'.session_id\') ...\n```\n\n### 2. Close Sessions Promptly\n\nDon\'t leave sessions open longer than needed. Server resources are limited.\n\n### 3. Use Meaningful Variable Names\n\n```bash\n# Good: Clear purpose\nLOGIN_SESSION=$(...)\nSCRAPE_SESSION=$(...)\n\n# Bad: Generic names\nS1=$(...)\nS2=$(...)\n```\n\n### 4. Handle Session Expiry\n\nSessions may expire after extended inactivity:\n\n```bash\n# Check if session is still valid\nRESULT=$(infsh app run agent-browser --function snapshot --session $SESSION_ID --input \'{}\' 2>&1)\nif echo \"$RESULT\" | grep -q \"session not found\"; then\n  echo \"Session expired, starting new one\"\n  SESSION_ID=$(infsh app run agent-browser --function open --session new --input \'{\n    \"url\": \"https://example.com\"\n  }\' | jq -r \'.session_id\')\nfi\n```\n\n### 5. One Task Per Session\n\nFor clarity, use one session per logical task:\n\n```bash\n# Good: Separate sessions for separate tasks\nLOGIN_SESSION=$(...)  # Handle login\nSCRAPE_SESSION=$(...)  # Handle scraping\n\n# Okay for related tasks: One session for a workflow\nSESSION=$(...)\n# login -> navigate -> extract -> close\n```\n','9841d9a0b113b0294fe20d0d020a783e','2026-10-26 11:22:10','2026-10-26 11:22:10','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(2605,'enc.7265666572656e6365732f736e617073686f742d726566732e6d64','skill_enc.6167656e742d62726f77736572__enc.302e302e31','# Snapshot and Refs\n\nCompact element references that reduce context usage for AI agents.\n\n**Related**: [commands.md](commands.md) for full function reference, [SKILL.md](../SKILL.md) for quick start.\n\n## Contents\n\n- [How Refs Work](#how-refs-work)\n- [Snapshot Output Format](#snapshot-output-format)\n- [Using Refs](#using-refs)\n- [Ref Lifecycle](#ref-lifecycle)\n- [Best Practices](#best-practices)\n- [Ref Notation Details](#ref-notation-details)\n- [Troubleshooting](#troubleshooting)\n\n## How Refs Work\n\nTraditional approach:\n```\nFull DOM/HTML -> AI parses -> CSS selector -> Action (~3000-5000 tokens)\n```\n\nagent-browser approach:\n```\nCompact snapshot -> @refs assigned -> Direct interaction (~200-400 tokens)\n```\n\nThe snapshot extracts interactive elements and assigns short `@e` refs, reducing token usage significantly.\n\n## Snapshot Output Format\n\n```bash\ninfsh app run agent-browser --function snapshot --session $SESSION --input \'{}\'\n```\n\n**Response `elements_text`:**\n\n```\n@e1 [a] \"Home\" href=\"/\"\n@e2 [a] \"Products\" href=\"/products\"\n@e3 [a] \"About\" href=\"/about\"\n@e4 [button] \"Sign In\"\n@e5 [input type=\"email\"] placeholder=\"Email\"\n@e6 [input type=\"password\"] placeholder=\"Password\"\n@e7 [button type=\"submit\"] \"Log In\"\n@e8 [input type=\"checkbox\"] name=\"remember\"\n```\n\n**Response `elements` (structured):**\n\n```json\n[\n  {\n    \"ref\": \"@e1\",\n    \"desc\": \"@e1 [a] \\\"Home\\\" href=\\\"/\\\"\",\n    \"tag\": \"a\",\n    \"text\": \"Home\",\n    \"role\": null,\n    \"name\": null,\n    \"href\": \"/\",\n    \"input_type\": null\n  },\n  ...\n]\n```\n\n## Using Refs\n\nOnce you have refs, interact directly:\n\n```bash\n# Click the \"Sign In\" button\n\'{\"action\": \"click\", \"ref\": \"@e4\"}\'\n\n# Fill email input\n\'{\"action\": \"fill\", \"ref\": \"@e5\", \"text\": \"user@example.com\"}\'\n\n# Fill password\n\'{\"action\": \"fill\", \"ref\": \"@e6\", \"text\": \"password123\"}\'\n\n# Submit the form\n\'{\"action\": \"click\", \"ref\": \"@e7\"}\'\n\n# Check the \"remember me\" checkbox\n\'{\"action\": \"check\", \"ref\": \"@e8\"}\'\n```\n\n## Ref Lifecycle\n\n**IMPORTANT**: Refs are invalidated when the page changes!\n\n```bash\n# Get initial snapshot\ninfsh app run agent-browser --function snapshot --session $SESSION --input \'{}\'\n# @e1 [button] \"Next\"\n\n# Click triggers page change\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"click\", \"ref\": \"@e1\"\n}\'\n\n# MUST re-snapshot to get new refs!\ninfsh app run agent-browser --function snapshot --session $SESSION --input \'{}\'\n# @e1 [h1] \"Page 2\"  <- Different element now!\n```\n\n### When to Re-snapshot\n\nAlways re-snapshot after:\n\n1. **Navigation** - Clicking links, form submissions, `goto` action\n2. **Dynamic content** - AJAX loads, modals opening, tabs switching\n3. **Page mutations** - JavaScript modifying the DOM\n\nThe `interact` function returns a fresh snapshot in its response, so you can often use that instead of a separate snapshot call.\n\n## Best Practices\n\n### 1. Always Use the Latest Snapshot\n\n```bash\n# CORRECT: Use snapshot from previous response\nRESULT=$(infsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"click\", \"ref\": \"@e1\"\n}\')\n# Use elements from $RESULT.snapshot for next action\n\n# WRONG: Using stale refs\n# After navigation, @e1 may point to a completely different element\n```\n\n### 2. Check Success Before Continuing\n\n```bash\nRESULT=$(infsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"click\", \"ref\": \"@e5\"\n}\')\n\nSUCCESS=$(echo $RESULT | jq -r \'.success\')\nif [ \"$SUCCESS\" != \"true\" ]; then\n  echo \"Click failed: $(echo $RESULT | jq -r \'.message\')\"\n  # Re-snapshot and retry\nfi\n```\n\n### 3. Use elements_text for Quick Decisions\n\nFor AI agents, `elements_text` provides a compact text representation:\n\n```\n@e1 [input type=\"email\"] placeholder=\"Email\"\n@e2 [input type=\"password\"] placeholder=\"Password\"\n@e3 [button] \"Submit\"\n```\n\nThis is often enough to decide which element to interact with without parsing the full `elements` array.\n\n## Ref Notation Details\n\n```\n@e1 [tag type=\"value\"] \"text content\" name=\"attr\"\n|    |   |             |              |\n|    |   |             |              +- Additional attributes\n|    |   |             +- Visible text\n|    |   +- Key attributes shown\n|    +- HTML tag name\n+- Unique ref ID\n```\n\n### Common Patterns\n\n```\n@e1 [button] \"Submit\"                    # Button with text\n@e2 [input type=\"email\"]                 # Email input\n@e3 [input type=\"password\"]              # Password input\n@e4 [a] \"Link Text\" href=\"/page\"         # Anchor link\n@e5 [select]                             # Dropdown\n@e6 [textarea] placeholder=\"Message\"     # Text area\n@e7 [input type=\"file\"]                  # File upload\n@e8 [input type=\"checkbox\"] checked      # Checked checkbox\n@e9 [input type=\"radio\"] selected        # Selected radio\n@e10 [button type=\"submit\"] \"Send\"       # Submit button\n```\n\n### Elements Captured\n\nThe snapshot captures these interactive elements:\n\n- Links (`<a href>`)\n- Buttons (`<button>`, `[role=\"button\"]`)\n- Inputs (`<input>`, `<textarea>`, `<select>`)\n- Clickable elements (`[onclick]`, `[tabindex]`)\n- ARIA roles (`[role=\"link\"]`, `[role=\"checkbox\"]`, etc.)\n\nNon-interactive or hidden elements are filtered out.\n\n## Troubleshooting\n\n### \"Unknown ref\" Error\n\n```json\n{\n  \"success\": false,\n  \"message\": \"Unknown ref: @e15. Run \'snapshot\' to get current elements.\"\n}\n```\n\n**Solution**: Re-snapshot. The page changed and refs are stale.\n\n```bash\ninfsh app run agent-browser --function snapshot --session $SESSION --input \'{}\'\n# Now use the new refs\n```\n\n### Element Not in Snapshot\n\nThe element you need might not appear because:\n\n1. **Not visible** - Scroll to reveal it\n   ```bash\n   \'{\"action\": \"scroll\", \"direction\": \"down\", \"scroll_amount\": 500}\'\n   ```\n\n2. **Not interactive** - Use JavaScript to interact\n   ```bash\n   \'{\"code\": \"document.querySelector(\\\".hidden-btn\\\").click()\"}\'\n   ```\n\n3. **In iframe** - Currently not supported (use `execute` with JS)\n\n4. **Dynamic** - Wait for it to load\n   ```bash\n   \'{\"action\": \"wait\", \"wait_ms\": 2000}\'\n   ```\n\n### Too Many Elements\n\nSnapshots are limited to 50 elements. If the page has more:\n\n1. **Scroll** to bring relevant elements into view\n2. **Use JavaScript** to target specific elements\n3. **Navigate** to a more specific page\n\n### Ref Points to Wrong Element\n\nIf a ref seems to interact with the wrong element:\n\n1. Re-snapshot to get fresh refs\n2. Check if the page structure changed\n3. Verify with screenshot that the right element is targeted\n','0941be7f4d7c30d83efd706d87dd3963','2026-10-26 11:22:10','2026-10-26 11:22:10','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(2606,'enc.7265666572656e6365732f70726f78792d737570706f72742e6d64','skill_enc.6167656e742d62726f77736572__enc.302e302e31','# Proxy Support\n\nProxy configuration for geo-testing, privacy, and corporate environments.\n\n**Related**: [commands.md](commands.md) for full function reference, [SKILL.md](../SKILL.md) for quick start.\n\n## Contents\n\n- [Basic Proxy Configuration](#basic-proxy-configuration)\n- [Authenticated Proxy](#authenticated-proxy)\n- [Common Use Cases](#common-use-cases)\n- [Proxy Types](#proxy-types)\n- [Verifying Proxy Connection](#verifying-proxy-connection)\n- [Troubleshooting](#troubleshooting)\n- [Best Practices](#best-practices)\n\n## Basic Proxy Configuration\n\nSet proxy when opening a session:\n\n```bash\nSESSION=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://example.com\",\n  \"proxy_url\": \"http://proxy.example.com:8080\"\n}\' | jq -r \'.session_id\')\n```\n\nAll traffic for this session routes through the proxy.\n\n## Authenticated Proxy\n\nFor proxies requiring username/password:\n\n```bash\nSESSION=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://example.com\",\n  \"proxy_url\": \"http://proxy.example.com:8080\",\n  \"proxy_username\": \"myuser\",\n  \"proxy_password\": \"mypassword\"\n}\' | jq -r \'.session_id\')\n```\n\n## Common Use Cases\n\n### Geo-Location Testing\n\nTest how your site appears from different regions:\n\n```bash\n#!/bin/bash\n# Test from multiple regions\n\nPROXIES=(\n  \"us|http://us-proxy.example.com:8080\"\n  \"eu|http://eu-proxy.example.com:8080\"\n  \"asia|http://asia-proxy.example.com:8080\"\n)\n\nfor entry in \"${PROXIES[@]}\"; do\n  REGION=\"${entry%%|*}\"\n  PROXY=\"${entry##*|}\"\n\n  echo \"Testing from: $REGION\"\n\n  SESSION=$(infsh app run agent-browser --function open --session new --input \'{\n    \"url\": \"https://mysite.com\",\n    \"proxy_url\": \"\'\"$PROXY\"\'\"\n  }\' | jq -r \'.session_id\')\n\n  # Take screenshot\n  infsh app run agent-browser --function screenshot --session $SESSION --input \'{\n    \"full_page\": true\n  }\' > \"${REGION}-screenshot.json\"\n\n  # Get page content\n  RESULT=$(infsh app run agent-browser --function snapshot --session $SESSION --input \'{}\')\n  echo $RESULT | jq \'.elements_text\' > \"${REGION}-elements.txt\"\n\n  infsh app run agent-browser --function close --session $SESSION --input \'{}\'\ndone\n\necho \"Geo-testing complete\"\n```\n\n### Rate Limit Avoidance\n\nRotate proxies for web scraping:\n\n```bash\n#!/bin/bash\n# Rotate through proxy list\n\nPROXIES=(\n  \"http://proxy1.example.com:8080\"\n  \"http://proxy2.example.com:8080\"\n  \"http://proxy3.example.com:8080\"\n)\n\nURLS=(\n  \"https://site.com/page1\"\n  \"https://site.com/page2\"\n  \"https://site.com/page3\"\n)\n\nfor i in \"${!URLS[@]}\"; do\n  # Rotate proxy\n  PROXY_INDEX=$((i % ${#PROXIES[@]}))\n  PROXY=\"${PROXIES[$PROXY_INDEX]}\"\n  URL=\"${URLS[$i]}\"\n\n  echo \"Fetching $URL via proxy $((PROXY_INDEX + 1))\"\n\n  SESSION=$(infsh app run agent-browser --function open --session new --input \'{\n    \"url\": \"\'\"$URL\"\'\",\n    \"proxy_url\": \"\'\"$PROXY\"\'\"\n  }\' | jq -r \'.session_id\')\n\n  # Extract data\n  RESULT=$(infsh app run agent-browser --function execute --session $SESSION --input \'{\n    \"code\": \"document.body.innerText\"\n  }\')\n  echo $RESULT | jq -r \'.result\' > \"page-$i.txt\"\n\n  infsh app run agent-browser --function close --session $SESSION --input \'{}\'\n\n  # Polite delay\n  sleep 1\ndone\n```\n\n### Corporate Network Access\n\nAccess sites through corporate proxy:\n\n```bash\n# Use corporate proxy for external sites\nSESSION=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://external-vendor.com\",\n  \"proxy_url\": \"http://corpproxy.company.com:8080\",\n  \"proxy_username\": \"\'\"$CORP_USER\"\'\",\n  \"proxy_password\": \"\'\"$CORP_PASS\"\'\"\n}\' | jq -r \'.session_id\')\n```\n\n### Privacy and Anonymity\n\nRoute through privacy-focused proxy:\n\n```bash\nSESSION=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://whatismyip.com\",\n  \"proxy_url\": \"socks5://privacy-proxy.example.com:1080\"\n}\' | jq -r \'.session_id\')\n```\n\n## Proxy Types\n\n### HTTP/HTTPS Proxy\n\n```json\n{\"proxy_url\": \"http://proxy.example.com:8080\"}\n{\"proxy_url\": \"https://proxy.example.com:8080\"}\n```\n\n### SOCKS5 Proxy\n\n```json\n{\"proxy_url\": \"socks5://proxy.example.com:1080\"}\n```\n\n### With Authentication\n\n```json\n{\n  \"proxy_url\": \"http://proxy.example.com:8080\",\n  \"proxy_username\": \"user\",\n  \"proxy_password\": \"pass\"\n}\n```\n\n## Verifying Proxy Connection\n\nCheck that traffic routes through proxy:\n\n```bash\nSESSION=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://httpbin.org/ip\",\n  \"proxy_url\": \"http://proxy.example.com:8080\"\n}\' | jq -r \'.session_id\')\n\n# Get the IP shown\nRESULT=$(infsh app run agent-browser --function execute --session $SESSION --input \'{\n  \"code\": \"document.body.innerText\"\n}\')\necho \"IP via proxy: $(echo $RESULT | jq -r \'.result\')\"\n\ninfsh app run agent-browser --function close --session $SESSION --input \'{}\'\n```\n\nThe IP should be the proxy\'s IP, not your real IP.\n\n## Troubleshooting\n\n### Connection Failed\n\n```\nError: Failed to open URL: net::ERR_PROXY_CONNECTION_FAILED\n```\n\n**Solutions:**\n1. Verify proxy URL is correct\n2. Check proxy is running and accessible\n3. Confirm port is correct\n4. Test proxy with curl: `curl -x http://proxy:8080 https://example.com`\n\n### Authentication Failed\n\n```\nError: 407 Proxy Authentication Required\n```\n\n**Solutions:**\n1. Verify username/password are correct\n2. Check if proxy requires different auth method\n3. Ensure credentials don\'t contain special characters that need escaping\n\n### SSL Errors\n\nSome proxies perform SSL inspection. If you see certificate errors:\n\n```bash\n# The browser should handle most SSL proxies automatically\n# If issues persist, verify proxy SSL certificate is valid\n```\n\n### Slow Performance\n\n**Solutions:**\n1. Choose proxy closer to target site\n2. Use faster proxy provider\n3. Reduce number of requests per session\n\n## Best Practices\n\n### 1. Use Environment Variables\n\n```bash\n# Good: Credentials in env vars\n\'{\"proxy_url\": \"\'\"$PROXY_URL\"\'\", \"proxy_username\": \"\'\"$PROXY_USER\"\'\"}\'\n\n# Bad: Hardcoded\n\'{\"proxy_url\": \"http://user:pass@proxy.com:8080\"}\'\n```\n\n### 2. Test Proxy Before Automation\n\n```bash\n# Verify proxy works\ncurl -x \"$PROXY_URL\" https://httpbin.org/ip\n```\n\n### 3. Handle Proxy Failures\n\n```bash\n# Retry with different proxy on failure\nfor PROXY in \"${PROXIES[@]}\"; do\n  SESSION=$(infsh app run agent-browser --function open --session new --input \'{\n    \"url\": \"\'\"$URL\"\'\",\n    \"proxy_url\": \"\'\"$PROXY\"\'\"\n  }\' 2>&1)\n\n  if echo \"$SESSION\" | jq -e \'.session_id\' > /dev/null 2>&1; then\n    SESSION_ID=$(echo $SESSION | jq -r \'.session_id\')\n    break\n  fi\n  echo \"Proxy $PROXY failed, trying next...\"\ndone\n```\n\n### 4. Respect Rate Limits\n\nEven with proxies, be a good citizen:\n\n```bash\n# Add delays between requests\n\'{\"action\": \"wait\", \"wait_ms\": 1000}\'\n```\n\n### 5. Log Proxy Usage\n\nFor debugging, log which proxy was used:\n\n```bash\necho \"$(date): Using proxy $PROXY for $URL\" >> proxy.log\n```\n','7fcef1d396dd90b51d8cd4f9401f2ddf','2026-10-26 11:22:10','2026-10-26 11:22:10','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(2607,'enc.7265666572656e6365732f73657373696f6e2d6d616e6167656d656e742e6d64','skill_enc.6167656e742d62726f77736572__enc.302e302e31','# Session Management\n\nBrowser sessions for state persistence and parallel browsing.\n\n**Related**: [authentication.md](authentication.md) for login patterns, [SKILL.md](../SKILL.md) for quick start.\n\n## Contents\n\n- [How Sessions Work](#how-sessions-work)\n- [Starting a Session](#starting-a-session)\n- [Using Session IDs](#using-session-ids)\n- [Session State](#session-state)\n- [Parallel Sessions](#parallel-sessions)\n- [Session Cleanup](#session-cleanup)\n- [Best Practices](#best-practices)\n\n## How Sessions Work\n\nEach session maintains an isolated browser context with:\n- Cookies\n- LocalStorage / SessionStorage\n- Browser history\n- Page state\n- Video recording (if enabled)\n\nSessions persist across function calls, allowing multi-step workflows.\n\n## Starting a Session\n\nUse `--session new` to create a fresh session:\n\n```bash\nRESULT=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://example.com\"\n}\')\nSESSION_ID=$(echo $RESULT | jq -r \'.session_id\')\necho \"Session: $SESSION_ID\"\n```\n\n## Using Session IDs\n\nAll subsequent calls use the session ID:\n\n```bash\n# Navigate\ninfsh app run agent-browser --function open --session $SESSION_ID --input \'{\n  \"url\": \"https://example.com/page2\"\n}\'\n\n# Interact\ninfsh app run agent-browser --function interact --session $SESSION_ID --input \'{\n  \"action\": \"click\", \"ref\": \"@e1\"\n}\'\n\n# Screenshot\ninfsh app run agent-browser --function screenshot --session $SESSION_ID --input \'{}\'\n\n# Close\ninfsh app run agent-browser --function close --session $SESSION_ID --input \'{}\'\n```\n\n## Session State\n\n### What Persists\n\nWithin a session, these persist across calls:\n- Cookies (login state, preferences)\n- LocalStorage and SessionStorage\n- IndexedDB data\n- Browser history (for back/forward)\n- Current page and DOM state\n- Video recording buffer\n\n### What Doesn\'t Persist\n\n- Sessions don\'t persist across server restarts\n- No automatic session recovery\n- Video is only available until close is called\n\n## Parallel Sessions\n\nRun multiple independent sessions simultaneously:\n\n```bash\n#!/bin/bash\n# Scrape multiple sites in parallel\n\n# Start sessions\nRESULT1=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://site1.com\"\n}\')\nSESSION1=$(echo $RESULT1 | jq -r \'.session_id\')\n\nRESULT2=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://site2.com\"\n}\')\nSESSION2=$(echo $RESULT2 | jq -r \'.session_id\')\n\n# Work with each session independently\ninfsh app run agent-browser --function screenshot --session $SESSION1 --input \'{}\' &\ninfsh app run agent-browser --function screenshot --session $SESSION2 --input \'{}\' &\nwait\n\n# Clean up both\ninfsh app run agent-browser --function close --session $SESSION1 --input \'{}\'\ninfsh app run agent-browser --function close --session $SESSION2 --input \'{}\'\n```\n\n### Use Cases for Parallel Sessions\n\n1. **A/B Testing** - Compare different pages or user experiences\n2. **Multi-site scraping** - Gather data from multiple sources\n3. **Load testing** - Simulate multiple users\n4. **Cross-region testing** - Use different proxies per session\n\n## Session Cleanup\n\nAlways close sessions when done:\n\n```bash\ninfsh app run agent-browser --function close --session $SESSION_ID --input \'{}\'\n```\n\n**Why close matters:**\n- Releases server resources\n- Returns video recording (if enabled)\n- Prevents resource leaks\n\n### Error Handling\n\n```bash\n#!/bin/bash\nset -e\n\ncleanup() {\n  infsh app run agent-browser --function close --session $SESSION_ID --input \'{}\' 2>/dev/null || true\n}\ntrap cleanup EXIT\n\nSESSION_ID=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://example.com\"\n}\' | jq -r \'.session_id\')\n\n# ... your automation ...\n# cleanup runs automatically on exit\n```\n\n## Best Practices\n\n### 1. Store Session IDs\n\n```bash\n# Good: Store for reuse\nSESSION_ID=$(... | jq -r \'.session_id\')\ninfsh ... --session $SESSION_ID ...\n\n# Bad: Parse every time\ninfsh ... --session $(... | jq -r \'.session_id\') ...\n```\n\n### 2. Close Sessions Promptly\n\nDon\'t leave sessions open longer than needed. Server resources are limited.\n\n### 3. Use Meaningful Variable Names\n\n```bash\n# Good: Clear purpose\nLOGIN_SESSION=$(...)\nSCRAPE_SESSION=$(...)\n\n# Bad: Generic names\nS1=$(...)\nS2=$(...)\n```\n\n### 4. Handle Session Expiry\n\nSessions may expire after extended inactivity:\n\n```bash\n# Check if session is still valid\nRESULT=$(infsh app run agent-browser --function snapshot --session $SESSION_ID --input \'{}\' 2>&1)\nif echo \"$RESULT\" | grep -q \"session not found\"; then\n  echo \"Session expired, starting new one\"\n  SESSION_ID=$(infsh app run agent-browser --function open --session new --input \'{\n    \"url\": \"https://example.com\"\n  }\' | jq -r \'.session_id\')\nfi\n```\n\n### 5. One Task Per Session\n\nFor clarity, use one session per logical task:\n\n```bash\n# Good: Separate sessions for separate tasks\nLOGIN_SESSION=$(...)  # Handle login\nSCRAPE_SESSION=$(...)  # Handle scraping\n\n# Okay for related tasks: One session for a workflow\nSESSION=$(...)\n# login -> navigate -> extract -> close\n```\n','9841d9a0b113b0294fe20d0d020a783e','2026-10-26 11:22:10','2026-10-26 11:22:10','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(2608,'enc.7265666572656e6365732f766964656f2d7265636f7264696e672e6d64','skill_enc.6167656e742d62726f77736572__enc.302e302e31','# Video Recording\n\nCapture browser automation as video for debugging, documentation, or verification.\n\n**Related**: [commands.md](commands.md) for full function reference, [SKILL.md](../SKILL.md) for quick start.\n\n## Contents\n\n- [Basic Recording](#basic-recording)\n- [Cursor Indicator](#cursor-indicator)\n- [How Recording Works](#how-recording-works)\n- [Use Cases](#use-cases)\n- [Best Practices](#best-practices)\n- [Output Format](#output-format)\n- [Limitations](#limitations)\n\n## Basic Recording\n\nEnable video recording when opening a session:\n\n```bash\n# Start with recording enabled\nSESSION=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://example.com\",\n  \"record_video\": true\n}\' | jq -r \'.session_id\')\n\n# Perform actions\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"click\", \"ref\": \"@e1\"\n}\'\n\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"fill\", \"ref\": \"@e2\", \"text\": \"test input\"\n}\'\n\n# Close to get the video\nRESULT=$(infsh app run agent-browser --function close --session $SESSION --input \'{}\')\nVIDEO=$(echo $RESULT | jq -r \'.video\')\necho \"Video file: $VIDEO\"\n```\n\n## Cursor Indicator\n\nFor demos and documentation, show a visible cursor that follows mouse movements:\n\n```bash\nSESSION=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://example.com\",\n  \"record_video\": true,\n  \"show_cursor\": true\n}\' | jq -r \'.session_id\')\n```\n\nThe cursor appears as a red dot that:\n- Follows mouse movements in real-time\n- Shows click feedback (shrinks on mousedown)\n- Persists across page navigations\n- Appears in both screenshots and video\n\nThis is especially useful for:\n- Tutorial/documentation videos\n- Debugging interaction issues\n- Sharing recordings with non-technical stakeholders\n\n## How Recording Works\n\n1. **Start**: Pass `\"record_video\": true` in the `open` function\n2. **Record**: All browser activity is captured throughout the session\n3. **Stop**: Video is finalized when `close` is called\n4. **Retrieve**: Video file is returned in the `close` response\n\nThe video captures:\n- Page loads and navigations\n- Element interactions (clicks, typing)\n- Scrolling and animations\n- Dynamic content changes\n\n## Use Cases\n\n### Debugging Failed Automation\n\n```bash\n#!/bin/bash\n# Record automation for debugging\n\nSESSION=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://app.example.com\",\n  \"record_video\": true\n}\' | jq -r \'.session_id\')\n\n# Run automation\nRESULT=$(infsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"click\", \"ref\": \"@e1\"\n}\')\n\nSUCCESS=$(echo $RESULT | jq -r \'.success\')\nif [ \"$SUCCESS\" != \"true\" ]; then\n  echo \"Action failed!\"\n  echo \"Message: $(echo $RESULT | jq -r \'.message\')\"\n\n  # Get video for debugging\n  CLOSE_RESULT=$(infsh app run agent-browser --function close --session $SESSION --input \'{}\')\n  echo \"Debug video: $(echo $CLOSE_RESULT | jq -r \'.video\')\"\n  exit 1\nfi\n\ninfsh app run agent-browser --function close --session $SESSION --input \'{}\'\n```\n\n### Documentation Generation\n\nRecord workflows for user documentation:\n\n```bash\n#!/bin/bash\n# Record how-to video\n\nSESSION=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://app.example.com/settings\",\n  \"record_video\": true,\n  \"width\": 1920,\n  \"height\": 1080\n}\' | jq -r \'.session_id\')\n\n# Add pauses for clarity\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"wait\", \"wait_ms\": 1000\n}\'\n\n# Step 1: Click settings\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"click\", \"ref\": \"@e5\"\n}\'\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"wait\", \"wait_ms\": 500\n}\'\n\n# Step 2: Change setting\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"click\", \"ref\": \"@e10\"\n}\'\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"wait\", \"wait_ms\": 500\n}\'\n\n# Step 3: Save\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"click\", \"ref\": \"@e15\"\n}\'\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"wait\", \"wait_ms\": 1000\n}\'\n\n# Get the video\nRESULT=$(infsh app run agent-browser --function close --session $SESSION --input \'{}\')\necho \"Documentation video: $(echo $RESULT | jq -r \'.video\')\"\n```\n\n### Test Evidence for CI/CD\n\n```bash\n#!/bin/bash\n# Record E2E test for CI artifacts\n\nTEST_NAME=\"${1:-e2e-test}\"\n\nSESSION=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"\'\"$TEST_URL\"\'\",\n  \"record_video\": true\n}\' | jq -r \'.session_id\')\n\n# Run test steps\nrun_test_steps $SESSION\nTEST_RESULT=$?\n\n# Always get video\nCLOSE_RESULT=$(infsh app run agent-browser --function close --session $SESSION --input \'{}\')\nVIDEO=$(echo $CLOSE_RESULT | jq -r \'.video\')\n\n# Save to artifacts\nif [ -n \"$CI_ARTIFACTS_DIR\" ]; then\n  cp \"$VIDEO\" \"$CI_ARTIFACTS_DIR/${TEST_NAME}.webm\"\nfi\n\nexit $TEST_RESULT\n```\n\n### Monitoring and Auditing\n\n```bash\n#!/bin/bash\n# Record automated task for audit trail\n\nTASK_ID=$(date +%Y%m%d-%H%M%S)\n\nSESSION=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://admin.example.com\",\n  \"record_video\": true\n}\' | jq -r \'.session_id\')\n\n# Perform admin task\n# ... automation steps ...\n\n# Save recording\nRESULT=$(infsh app run agent-browser --function close --session $SESSION --input \'{}\')\nVIDEO=$(echo $RESULT | jq -r \'.video\')\n\n# Archive for audit\nmv \"$VIDEO\" \"/audit/recordings/${TASK_ID}.webm\"\necho \"Audit recording saved: ${TASK_ID}.webm\"\n```\n\n## Best Practices\n\n### 1. Add Strategic Pauses\n\nPauses make videos easier to follow:\n\n```bash\n# After significant actions, add a pause\n\'{\"action\": \"click\", \"ref\": \"@e1\"}\'\n\'{\"action\": \"wait\", \"wait_ms\": 500}\'  # Let viewer see result\n```\n\n### 2. Use Larger Viewport for Documentation\n\n```bash\n\'{\"url\": \"...\", \"record_video\": true, \"width\": 1920, \"height\": 1080}\'\n```\n\n### 3. Handle Errors Gracefully\n\nAlways retrieve video even on failure:\n\n```bash\ncleanup() {\n  if [ -n \"$SESSION\" ]; then\n    infsh app run agent-browser --function close --session $SESSION --input \'{}\' 2>/dev/null\n  fi\n}\ntrap cleanup EXIT\n```\n\n### 4. Combine with Screenshots\n\nUse screenshots for key frames, video for flow:\n\n```bash\n# Record overall flow\n\'{\"record_video\": true}\'\n\n# Capture key states\ninfsh app run agent-browser --function screenshot --session $SESSION --input \'{\n  \"full_page\": true\n}\'\n```\n\n### 5. Don\'t Record Sensitive Sessions\n\nAvoid recording when handling credentials:\n\n```bash\nif [ \"$CONTAINS_SENSITIVE_DATA\" = \"true\" ]; then\n  RECORD=\"false\"\nelse\n  RECORD=\"true\"\nfi\n\n\'{\"url\": \"...\", \"record_video\": \'$RECORD\'}\'\n```\n\n## Output Format\n\n- **Format**: WebM (VP8/VP9 codec)\n- **Compatibility**: All modern browsers and video players\n- **Quality**: Matches viewport size\n- **Compression**: Efficient for screen content\n\n## Limitations\n\n1. **Session-level only** - Can\'t start/stop mid-session\n2. **Memory usage** - Long sessions consume more memory\n3. **File size** - Complex pages with animations produce larger files\n4. **No audio** - Browser audio is not captured\n5. **Returned on close** - Video only available after session ends\n','450c8caf748dc8b4f73a1a992d838f54','2026-10-26 11:22:10','2026-10-26 11:22:10','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(2609,'enc.7265666572656e6365732f70726f78792d737570706f72742e6d64','skill_enc.6167656e742d62726f77736572__enc.302e302e31','# Proxy Support\n\nProxy configuration for geo-testing, privacy, and corporate environments.\n\n**Related**: [commands.md](commands.md) for full function reference, [SKILL.md](../SKILL.md) for quick start.\n\n## Contents\n\n- [Basic Proxy Configuration](#basic-proxy-configuration)\n- [Authenticated Proxy](#authenticated-proxy)\n- [Common Use Cases](#common-use-cases)\n- [Proxy Types](#proxy-types)\n- [Verifying Proxy Connection](#verifying-proxy-connection)\n- [Troubleshooting](#troubleshooting)\n- [Best Practices](#best-practices)\n\n## Basic Proxy Configuration\n\nSet proxy when opening a session:\n\n```bash\nSESSION=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://example.com\",\n  \"proxy_url\": \"http://proxy.example.com:8080\"\n}\' | jq -r \'.session_id\')\n```\n\nAll traffic for this session routes through the proxy.\n\n## Authenticated Proxy\n\nFor proxies requiring username/password:\n\n```bash\nSESSION=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://example.com\",\n  \"proxy_url\": \"http://proxy.example.com:8080\",\n  \"proxy_username\": \"myuser\",\n  \"proxy_password\": \"mypassword\"\n}\' | jq -r \'.session_id\')\n```\n\n## Common Use Cases\n\n### Geo-Location Testing\n\nTest how your site appears from different regions:\n\n```bash\n#!/bin/bash\n# Test from multiple regions\n\nPROXIES=(\n  \"us|http://us-proxy.example.com:8080\"\n  \"eu|http://eu-proxy.example.com:8080\"\n  \"asia|http://asia-proxy.example.com:8080\"\n)\n\nfor entry in \"${PROXIES[@]}\"; do\n  REGION=\"${entry%%|*}\"\n  PROXY=\"${entry##*|}\"\n\n  echo \"Testing from: $REGION\"\n\n  SESSION=$(infsh app run agent-browser --function open --session new --input \'{\n    \"url\": \"https://mysite.com\",\n    \"proxy_url\": \"\'\"$PROXY\"\'\"\n  }\' | jq -r \'.session_id\')\n\n  # Take screenshot\n  infsh app run agent-browser --function screenshot --session $SESSION --input \'{\n    \"full_page\": true\n  }\' > \"${REGION}-screenshot.json\"\n\n  # Get page content\n  RESULT=$(infsh app run agent-browser --function snapshot --session $SESSION --input \'{}\')\n  echo $RESULT | jq \'.elements_text\' > \"${REGION}-elements.txt\"\n\n  infsh app run agent-browser --function close --session $SESSION --input \'{}\'\ndone\n\necho \"Geo-testing complete\"\n```\n\n### Rate Limit Avoidance\n\nRotate proxies for web scraping:\n\n```bash\n#!/bin/bash\n# Rotate through proxy list\n\nPROXIES=(\n  \"http://proxy1.example.com:8080\"\n  \"http://proxy2.example.com:8080\"\n  \"http://proxy3.example.com:8080\"\n)\n\nURLS=(\n  \"https://site.com/page1\"\n  \"https://site.com/page2\"\n  \"https://site.com/page3\"\n)\n\nfor i in \"${!URLS[@]}\"; do\n  # Rotate proxy\n  PROXY_INDEX=$((i % ${#PROXIES[@]}))\n  PROXY=\"${PROXIES[$PROXY_INDEX]}\"\n  URL=\"${URLS[$i]}\"\n\n  echo \"Fetching $URL via proxy $((PROXY_INDEX + 1))\"\n\n  SESSION=$(infsh app run agent-browser --function open --session new --input \'{\n    \"url\": \"\'\"$URL\"\'\",\n    \"proxy_url\": \"\'\"$PROXY\"\'\"\n  }\' | jq -r \'.session_id\')\n\n  # Extract data\n  RESULT=$(infsh app run agent-browser --function execute --session $SESSION --input \'{\n    \"code\": \"document.body.innerText\"\n  }\')\n  echo $RESULT | jq -r \'.result\' > \"page-$i.txt\"\n\n  infsh app run agent-browser --function close --session $SESSION --input \'{}\'\n\n  # Polite delay\n  sleep 1\ndone\n```\n\n### Corporate Network Access\n\nAccess sites through corporate proxy:\n\n```bash\n# Use corporate proxy for external sites\nSESSION=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://external-vendor.com\",\n  \"proxy_url\": \"http://corpproxy.company.com:8080\",\n  \"proxy_username\": \"\'\"$CORP_USER\"\'\",\n  \"proxy_password\": \"\'\"$CORP_PASS\"\'\"\n}\' | jq -r \'.session_id\')\n```\n\n### Privacy and Anonymity\n\nRoute through privacy-focused proxy:\n\n```bash\nSESSION=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://whatismyip.com\",\n  \"proxy_url\": \"socks5://privacy-proxy.example.com:1080\"\n}\' | jq -r \'.session_id\')\n```\n\n## Proxy Types\n\n### HTTP/HTTPS Proxy\n\n```json\n{\"proxy_url\": \"http://proxy.example.com:8080\"}\n{\"proxy_url\": \"https://proxy.example.com:8080\"}\n```\n\n### SOCKS5 Proxy\n\n```json\n{\"proxy_url\": \"socks5://proxy.example.com:1080\"}\n```\n\n### With Authentication\n\n```json\n{\n  \"proxy_url\": \"http://proxy.example.com:8080\",\n  \"proxy_username\": \"user\",\n  \"proxy_password\": \"pass\"\n}\n```\n\n## Verifying Proxy Connection\n\nCheck that traffic routes through proxy:\n\n```bash\nSESSION=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://httpbin.org/ip\",\n  \"proxy_url\": \"http://proxy.example.com:8080\"\n}\' | jq -r \'.session_id\')\n\n# Get the IP shown\nRESULT=$(infsh app run agent-browser --function execute --session $SESSION --input \'{\n  \"code\": \"document.body.innerText\"\n}\')\necho \"IP via proxy: $(echo $RESULT | jq -r \'.result\')\"\n\ninfsh app run agent-browser --function close --session $SESSION --input \'{}\'\n```\n\nThe IP should be the proxy\'s IP, not your real IP.\n\n## Troubleshooting\n\n### Connection Failed\n\n```\nError: Failed to open URL: net::ERR_PROXY_CONNECTION_FAILED\n```\n\n**Solutions:**\n1. Verify proxy URL is correct\n2. Check proxy is running and accessible\n3. Confirm port is correct\n4. Test proxy with curl: `curl -x http://proxy:8080 https://example.com`\n\n### Authentication Failed\n\n```\nError: 407 Proxy Authentication Required\n```\n\n**Solutions:**\n1. Verify username/password are correct\n2. Check if proxy requires different auth method\n3. Ensure credentials don\'t contain special characters that need escaping\n\n### SSL Errors\n\nSome proxies perform SSL inspection. If you see certificate errors:\n\n```bash\n# The browser should handle most SSL proxies automatically\n# If issues persist, verify proxy SSL certificate is valid\n```\n\n### Slow Performance\n\n**Solutions:**\n1. Choose proxy closer to target site\n2. Use faster proxy provider\n3. Reduce number of requests per session\n\n## Best Practices\n\n### 1. Use Environment Variables\n\n```bash\n# Good: Credentials in env vars\n\'{\"proxy_url\": \"\'\"$PROXY_URL\"\'\", \"proxy_username\": \"\'\"$PROXY_USER\"\'\"}\'\n\n# Bad: Hardcoded\n\'{\"proxy_url\": \"http://user:pass@proxy.com:8080\"}\'\n```\n\n### 2. Test Proxy Before Automation\n\n```bash\n# Verify proxy works\ncurl -x \"$PROXY_URL\" https://httpbin.org/ip\n```\n\n### 3. Handle Proxy Failures\n\n```bash\n# Retry with different proxy on failure\nfor PROXY in \"${PROXIES[@]}\"; do\n  SESSION=$(infsh app run agent-browser --function open --session new --input \'{\n    \"url\": \"\'\"$URL\"\'\",\n    \"proxy_url\": \"\'\"$PROXY\"\'\"\n  }\' 2>&1)\n\n  if echo \"$SESSION\" | jq -e \'.session_id\' > /dev/null 2>&1; then\n    SESSION_ID=$(echo $SESSION | jq -r \'.session_id\')\n    break\n  fi\n  echo \"Proxy $PROXY failed, trying next...\"\ndone\n```\n\n### 4. Respect Rate Limits\n\nEven with proxies, be a good citizen:\n\n```bash\n# Add delays between requests\n\'{\"action\": \"wait\", \"wait_ms\": 1000}\'\n```\n\n### 5. Log Proxy Usage\n\nFor debugging, log which proxy was used:\n\n```bash\necho \"$(date): Using proxy $PROXY for $URL\" >> proxy.log\n```\n','7fcef1d396dd90b51d8cd4f9401f2ddf','2026-10-26 11:22:10','2026-10-26 11:22:10','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(2610,'enc.74656d706c617465732f666f726d2d6175746f6d6174696f6e2e7368','skill_enc.6167656e742d62726f77736572__enc.302e302e31','#!/bin/bash\n# Template: Form Automation Workflow\n# Purpose: Fill and submit web forms with validation\n# Usage: ./form-automation.sh <form-url>\n#\n# This template demonstrates the snapshot-interact-verify pattern:\n# 1. Navigate to form\n# 2. Snapshot to get element refs\n# 3. Fill fields using refs\n# 4. Submit and verify result\n#\n# Customize: Update the refs (@e1, @e2, etc.) based on your form\'s snapshot output\n\nset -euo pipefail\n\nFORM_URL=\"${1:?Usage: $0 <form-url>}\"\n\necho \"Form automation: $FORM_URL\"\n\n# Cleanup handler\ncleanup() {\n  if [ -n \"${SESSION_ID:-}\" ]; then\n    infsh app run agent-browser --function close --session $SESSION_ID --input \'{}\' 2>/dev/null || true\n  fi\n}\ntrap cleanup EXIT\n\n# Step 1: Navigate to form\necho \"Opening form...\"\nRESULT=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"\'\"$FORM_URL\"\'\"\n}\')\nSESSION_ID=$(echo $RESULT | jq -r \'.session_id\')\n\n# Step 2: Display form structure\necho \"\"\necho \"Form elements:\"\necho \"---\"\necho $RESULT | jq -r \'.elements_text\'\necho \"---\"\necho \"\"\n\n# ================================================================\n# DISCOVERY MODE: Shows form structure\n# After running once, update the FORM FILL section below with your refs\n# then delete or comment out this section\n# ================================================================\necho \"Discovery mode: Form structure shown above\"\necho \"\"\necho \"Next steps:\"\necho \"  1. Note the refs for your form fields (e.g., @e1 for name, @e2 for email)\"\necho \"  2. Update the FORM FILL section below\"\necho \"  3. Set environment variables for form data\"\necho \"  4. Comment out this discovery section\"\necho \"\"\nexit 0\n\n# ================================================================\n# FORM FILL: Uncomment and customize after discovery\n# ================================================================\n# echo \"Filling form...\"\n#\n# # Text input\n# infsh app run agent-browser --function interact --session $SESSION_ID --input \'{\n#   \"action\": \"fill\", \"ref\": \"@e1\", \"text\": \"\'\"${FORM_NAME:-John Doe}\"\'\"\n# }\'\n#\n# # Email input\n# infsh app run agent-browser --function interact --session $SESSION_ID --input \'{\n#   \"action\": \"fill\", \"ref\": \"@e2\", \"text\": \"\'\"${FORM_EMAIL:-john@example.com}\"\'\"\n# }\'\n#\n# # Dropdown/select\n# infsh app run agent-browser --function interact --session $SESSION_ID --input \'{\n#   \"action\": \"select\", \"ref\": \"@e3\", \"text\": \"Option 1\"\n# }\'\n#\n# # Checkbox\n# infsh app run agent-browser --function interact --session $SESSION_ID --input \'{\n#   \"action\": \"check\", \"ref\": \"@e4\"\n# }\'\n#\n# # Textarea\n# infsh app run agent-browser --function interact --session $SESSION_ID --input \'{\n#   \"action\": \"fill\", \"ref\": \"@e5\", \"text\": \"\'\"${FORM_MESSAGE:-Hello, this is a test message.}\"\'\"\n# }\'\n#\n# # Submit button\n# echo \"Submitting form...\"\n# infsh app run agent-browser --function interact --session $SESSION_ID --input \'{\n#   \"action\": \"click\", \"ref\": \"@e6\"\n# }\'\n#\n# # Wait for submission\n# infsh app run agent-browser --function interact --session $SESSION_ID --input \'{\n#   \"action\": \"wait\", \"wait_ms\": 2000\n# }\'\n#\n# # Step 3: Verify result\n# echo \"\"\n# echo \"Verifying submission...\"\n# RESULT=$(infsh app run agent-browser --function snapshot --session $SESSION_ID --input \'{}\')\n#\n# URL=$(echo $RESULT | jq -r \'.url\')\n# TITLE=$(echo $RESULT | jq -r \'.title\')\n# echo \"Final URL: $URL\"\n# echo \"Page title: $TITLE\"\n#\n# # Check for success indicators\n# ELEMENTS=$(echo $RESULT | jq -r \'.elements_text\')\n# if echo \"$ELEMENTS\" | grep -qi \"thank you\\|success\\|submitted\"; then\n#   echo \"SUCCESS: Form submitted successfully\"\n# elif echo \"$URL\" | grep -qi \"error\\|fail\"; then\n#   echo \"ERROR: Form submission may have failed\"\n#   exit 1\n# else\n#   echo \"UNKNOWN: Check the result manually\"\n# fi\n#\n# # Optional: Capture evidence\n# infsh app run agent-browser --function screenshot --session $SESSION_ID --input \'{\n#   \"full_page\": true\n# }\' > form-result-screenshot.json\n# echo \"Screenshot saved to form-result-screenshot.json\"\n\necho \"Done\"\n','ec934c21c0ba33bf0dddd49d69294576','2026-10-26 11:22:10','2026-10-26 11:22:10','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(2611,'enc.7265666572656e6365732f766964656f2d7265636f7264696e672e6d64','skill_enc.6167656e742d62726f77736572__enc.302e302e31','# Video Recording\n\nCapture browser automation as video for debugging, documentation, or verification.\n\n**Related**: [commands.md](commands.md) for full function reference, [SKILL.md](../SKILL.md) for quick start.\n\n## Contents\n\n- [Basic Recording](#basic-recording)\n- [Cursor Indicator](#cursor-indicator)\n- [How Recording Works](#how-recording-works)\n- [Use Cases](#use-cases)\n- [Best Practices](#best-practices)\n- [Output Format](#output-format)\n- [Limitations](#limitations)\n\n## Basic Recording\n\nEnable video recording when opening a session:\n\n```bash\n# Start with recording enabled\nSESSION=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://example.com\",\n  \"record_video\": true\n}\' | jq -r \'.session_id\')\n\n# Perform actions\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"click\", \"ref\": \"@e1\"\n}\'\n\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"fill\", \"ref\": \"@e2\", \"text\": \"test input\"\n}\'\n\n# Close to get the video\nRESULT=$(infsh app run agent-browser --function close --session $SESSION --input \'{}\')\nVIDEO=$(echo $RESULT | jq -r \'.video\')\necho \"Video file: $VIDEO\"\n```\n\n## Cursor Indicator\n\nFor demos and documentation, show a visible cursor that follows mouse movements:\n\n```bash\nSESSION=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://example.com\",\n  \"record_video\": true,\n  \"show_cursor\": true\n}\' | jq -r \'.session_id\')\n```\n\nThe cursor appears as a red dot that:\n- Follows mouse movements in real-time\n- Shows click feedback (shrinks on mousedown)\n- Persists across page navigations\n- Appears in both screenshots and video\n\nThis is especially useful for:\n- Tutorial/documentation videos\n- Debugging interaction issues\n- Sharing recordings with non-technical stakeholders\n\n## How Recording Works\n\n1. **Start**: Pass `\"record_video\": true` in the `open` function\n2. **Record**: All browser activity is captured throughout the session\n3. **Stop**: Video is finalized when `close` is called\n4. **Retrieve**: Video file is returned in the `close` response\n\nThe video captures:\n- Page loads and navigations\n- Element interactions (clicks, typing)\n- Scrolling and animations\n- Dynamic content changes\n\n## Use Cases\n\n### Debugging Failed Automation\n\n```bash\n#!/bin/bash\n# Record automation for debugging\n\nSESSION=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://app.example.com\",\n  \"record_video\": true\n}\' | jq -r \'.session_id\')\n\n# Run automation\nRESULT=$(infsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"click\", \"ref\": \"@e1\"\n}\')\n\nSUCCESS=$(echo $RESULT | jq -r \'.success\')\nif [ \"$SUCCESS\" != \"true\" ]; then\n  echo \"Action failed!\"\n  echo \"Message: $(echo $RESULT | jq -r \'.message\')\"\n\n  # Get video for debugging\n  CLOSE_RESULT=$(infsh app run agent-browser --function close --session $SESSION --input \'{}\')\n  echo \"Debug video: $(echo $CLOSE_RESULT | jq -r \'.video\')\"\n  exit 1\nfi\n\ninfsh app run agent-browser --function close --session $SESSION --input \'{}\'\n```\n\n### Documentation Generation\n\nRecord workflows for user documentation:\n\n```bash\n#!/bin/bash\n# Record how-to video\n\nSESSION=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://app.example.com/settings\",\n  \"record_video\": true,\n  \"width\": 1920,\n  \"height\": 1080\n}\' | jq -r \'.session_id\')\n\n# Add pauses for clarity\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"wait\", \"wait_ms\": 1000\n}\'\n\n# Step 1: Click settings\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"click\", \"ref\": \"@e5\"\n}\'\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"wait\", \"wait_ms\": 500\n}\'\n\n# Step 2: Change setting\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"click\", \"ref\": \"@e10\"\n}\'\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"wait\", \"wait_ms\": 500\n}\'\n\n# Step 3: Save\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"click\", \"ref\": \"@e15\"\n}\'\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"wait\", \"wait_ms\": 1000\n}\'\n\n# Get the video\nRESULT=$(infsh app run agent-browser --function close --session $SESSION --input \'{}\')\necho \"Documentation video: $(echo $RESULT | jq -r \'.video\')\"\n```\n\n### Test Evidence for CI/CD\n\n```bash\n#!/bin/bash\n# Record E2E test for CI artifacts\n\nTEST_NAME=\"${1:-e2e-test}\"\n\nSESSION=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"\'\"$TEST_URL\"\'\",\n  \"record_video\": true\n}\' | jq -r \'.session_id\')\n\n# Run test steps\nrun_test_steps $SESSION\nTEST_RESULT=$?\n\n# Always get video\nCLOSE_RESULT=$(infsh app run agent-browser --function close --session $SESSION --input \'{}\')\nVIDEO=$(echo $CLOSE_RESULT | jq -r \'.video\')\n\n# Save to artifacts\nif [ -n \"$CI_ARTIFACTS_DIR\" ]; then\n  cp \"$VIDEO\" \"$CI_ARTIFACTS_DIR/${TEST_NAME}.webm\"\nfi\n\nexit $TEST_RESULT\n```\n\n### Monitoring and Auditing\n\n```bash\n#!/bin/bash\n# Record automated task for audit trail\n\nTASK_ID=$(date +%Y%m%d-%H%M%S)\n\nSESSION=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://admin.example.com\",\n  \"record_video\": true\n}\' | jq -r \'.session_id\')\n\n# Perform admin task\n# ... automation steps ...\n\n# Save recording\nRESULT=$(infsh app run agent-browser --function close --session $SESSION --input \'{}\')\nVIDEO=$(echo $RESULT | jq -r \'.video\')\n\n# Archive for audit\nmv \"$VIDEO\" \"/audit/recordings/${TASK_ID}.webm\"\necho \"Audit recording saved: ${TASK_ID}.webm\"\n```\n\n## Best Practices\n\n### 1. Add Strategic Pauses\n\nPauses make videos easier to follow:\n\n```bash\n# After significant actions, add a pause\n\'{\"action\": \"click\", \"ref\": \"@e1\"}\'\n\'{\"action\": \"wait\", \"wait_ms\": 500}\'  # Let viewer see result\n```\n\n### 2. Use Larger Viewport for Documentation\n\n```bash\n\'{\"url\": \"...\", \"record_video\": true, \"width\": 1920, \"height\": 1080}\'\n```\n\n### 3. Handle Errors Gracefully\n\nAlways retrieve video even on failure:\n\n```bash\ncleanup() {\n  if [ -n \"$SESSION\" ]; then\n    infsh app run agent-browser --function close --session $SESSION --input \'{}\' 2>/dev/null\n  fi\n}\ntrap cleanup EXIT\n```\n\n### 4. Combine with Screenshots\n\nUse screenshots for key frames, video for flow:\n\n```bash\n# Record overall flow\n\'{\"record_video\": true}\'\n\n# Capture key states\ninfsh app run agent-browser --function screenshot --session $SESSION --input \'{\n  \"full_page\": true\n}\'\n```\n\n### 5. Don\'t Record Sensitive Sessions\n\nAvoid recording when handling credentials:\n\n```bash\nif [ \"$CONTAINS_SENSITIVE_DATA\" = \"true\" ]; then\n  RECORD=\"false\"\nelse\n  RECORD=\"true\"\nfi\n\n\'{\"url\": \"...\", \"record_video\": \'$RECORD\'}\'\n```\n\n## Output Format\n\n- **Format**: WebM (VP8/VP9 codec)\n- **Compatibility**: All modern browsers and video players\n- **Quality**: Matches viewport size\n- **Compression**: Efficient for screen content\n\n## Limitations\n\n1. **Session-level only** - Can\'t start/stop mid-session\n2. **Memory usage** - Long sessions consume more memory\n3. **File size** - Complex pages with animations produce larger files\n4. **No audio** - Browser audio is not captured\n5. **Returned on close** - Video only available after session ends\n','450c8caf748dc8b4f73a1a992d838f54','2026-10-26 11:22:10','2026-10-26 11:22:10','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,'');
INSERT INTO `config_info` VALUES (2612,'SKILL.md','skill_enc.6167656e742d62726f77736572__enc.302e302e31','---\nversion: 0.0.1\nname: agent-browser\ndescription: \"Browser automation for AI agents via inference.sh. Navigate web pages, interact with elements using @e refs, take screenshots, record video. Capabilities: web scraping, form filling, clicking, typing, drag-drop, file upload, JavaScript execution. Use for: web automation, data extraction, testing, agent browsing, research. Triggers: browser, web automation, scrape, navigate, click, fill form, screenshot, browse web, playwright, headless browser, web agent, surf internet, record video\"\nallowed-tools: Bash(infsh *)\n---\n\n# Agentic Browser\n\nBrowser automation for AI agents via [inference.sh](https://inference.sh). Uses Playwright under the hood with a simple `@e` ref system for element interaction.\n\n![Agentic Browser](https://cloud.inference.sh/app/files/u/4mg21r6ta37mpaz6ktzwtt8krr/01kgjw8atdxgkrsr8a2t5peq7b.jpeg)\n\n## Quick Start\n\n> Requires inference.sh CLI (`infsh`). [Install instructions](https://raw.githubusercontent.com/inference-sh/skills/refs/heads/main/cli-install.md)\n\n```bash\ninfsh login\n\n# Open a page and get interactive elements\ninfsh app run agent-browser --function open --input \'{\"url\": \"https://example.com\"}\' --session new\n```\n\n\n## Core Workflow\n\nEvery browser automation follows this pattern:\n\n1. **Open** - Navigate to URL, get `@e` refs for elements\n2. **Interact** - Use refs to click, fill, drag, etc.\n3. **Re-snapshot** - After navigation/changes, get fresh refs\n4. **Close** - End session (returns video if recording)\n\n```bash\n# 1. Start session\nRESULT=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://example.com/login\"\n}\')\nSESSION_ID=$(echo $RESULT | jq -r \'.session_id\')\n# Elements: @e1 [input] \"Email\", @e2 [input] \"Password\", @e3 [button] \"Sign In\"\n\n# 2. Fill and submit\ninfsh app run agent-browser --function interact --session $SESSION_ID --input \'{\n  \"action\": \"fill\", \"ref\": \"@e1\", \"text\": \"user@example.com\"\n}\'\ninfsh app run agent-browser --function interact --session $SESSION_ID --input \'{\n  \"action\": \"fill\", \"ref\": \"@e2\", \"text\": \"password123\"\n}\'\ninfsh app run agent-browser --function interact --session $SESSION_ID --input \'{\n  \"action\": \"click\", \"ref\": \"@e3\"\n}\'\n\n# 3. Re-snapshot after navigation\ninfsh app run agent-browser --function snapshot --session $SESSION_ID --input \'{}\'\n\n# 4. Close when done\ninfsh app run agent-browser --function close --session $SESSION_ID --input \'{}\'\n```\n\n## Functions\n\n| Function | Description |\n|----------|-------------|\n| `open` | Navigate to URL, configure browser (viewport, proxy, video recording) |\n| `snapshot` | Re-fetch page state with `@e` refs after DOM changes |\n| `interact` | Perform actions using `@e` refs (click, fill, drag, upload, etc.) |\n| `screenshot` | Take page screenshot (viewport or full page) |\n| `execute` | Run JavaScript code on the page |\n| `close` | Close session, returns video if recording was enabled |\n\n## Interact Actions\n\n| Action | Description | Required Fields |\n|--------|-------------|-----------------|\n| `click` | Click element | `ref` |\n| `dblclick` | Double-click element | `ref` |\n| `fill` | Clear and type text | `ref`, `text` |\n| `type` | Type text (no clear) | `text` |\n| `press` | Press key (Enter, Tab, etc.) | `text` |\n| `select` | Select dropdown option | `ref`, `text` |\n| `hover` | Hover over element | `ref` |\n| `check` | Check checkbox | `ref` |\n| `uncheck` | Uncheck checkbox | `ref` |\n| `drag` | Drag and drop | `ref`, `target_ref` |\n| `upload` | Upload file(s) | `ref`, `file_paths` |\n| `scroll` | Scroll page | `direction` (up/down/left/right), `scroll_amount` |\n| `back` | Go back in history | - |\n| `wait` | Wait milliseconds | `wait_ms` |\n| `goto` | Navigate to URL | `url` |\n\n## Element Refs\n\nElements are returned with `@e` refs:\n\n```\n@e1 [a] \"Home\" href=\"/\"\n@e2 [input type=\"text\"] placeholder=\"Search\"\n@e3 [button] \"Submit\"\n@e4 [select] \"Choose option\"\n@e5 [input type=\"checkbox\"] name=\"agree\"\n```\n\n**Important:** Refs are invalidated after navigation. Always re-snapshot after:\n- Clicking links/buttons that navigate\n- Form submissions\n- Dynamic content loading\n\n## Features\n\n### Video Recording\n\nRecord browser sessions for debugging or documentation:\n\n```bash\n# Start with recording enabled (optionally show cursor indicator)\nSESSION=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://example.com\",\n  \"record_video\": true,\n  \"show_cursor\": true\n}\' | jq -r \'.session_id\')\n\n# ... perform actions ...\n\n# Close to get the video file\ninfsh app run agent-browser --function close --session $SESSION --input \'{}\'\n# Returns: {\"success\": true, \"video\": <File>}\n```\n\n### Cursor Indicator\n\nShow a visible cursor in screenshots and video (useful for demos):\n\n```bash\ninfsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://example.com\",\n  \"show_cursor\": true,\n  \"record_video\": true\n}\'\n```\n\nThe cursor appears as a red dot that follows mouse movements and shows click feedback.\n\n### Proxy Support\n\nRoute traffic through a proxy server:\n\n```bash\ninfsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://example.com\",\n  \"proxy_url\": \"http://proxy.example.com:8080\",\n  \"proxy_username\": \"user\",\n  \"proxy_password\": \"pass\"\n}\'\n```\n\n### File Upload\n\nUpload files to file inputs:\n\n```bash\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"upload\",\n  \"ref\": \"@e5\",\n  \"file_paths\": [\"/path/to/file.pdf\"]\n}\'\n```\n\n### Drag and Drop\n\nDrag elements to targets:\n\n```bash\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"drag\",\n  \"ref\": \"@e1\",\n  \"target_ref\": \"@e2\"\n}\'\n```\n\n### JavaScript Execution\n\nRun custom JavaScript:\n\n```bash\ninfsh app run agent-browser --function execute --session $SESSION --input \'{\n  \"code\": \"document.querySelectorAll(\\\"h2\\\").length\"\n}\'\n# Returns: {\"result\": \"5\", \"screenshot\": <File>}\n```\n\n## Deep-Dive Documentation\n\n| Reference | Description |\n|-----------|-------------|\n| [references/commands.md](references/commands.md) | Full function reference with all options |\n| [references/snapshot-refs.md](references/snapshot-refs.md) | Ref lifecycle, invalidation rules, troubleshooting |\n| [references/session-management.md](references/session-management.md) | Session persistence, parallel sessions |\n| [references/authentication.md](references/authentication.md) | Login flows, OAuth, 2FA handling |\n| [references/video-recording.md](references/video-recording.md) | Recording workflows for debugging |\n| [references/proxy-support.md](references/proxy-support.md) | Proxy configuration, geo-testing |\n\n## Ready-to-Use Templates\n\n| Template | Description |\n|----------|-------------|\n| [templates/form-automation.sh](templates/form-automation.sh) | Form filling with validation |\n| [templates/authenticated-session.sh](templates/authenticated-session.sh) | Login once, reuse session |\n| [templates/capture-workflow.sh](templates/capture-workflow.sh) | Content extraction with screenshots |\n\n## Examples\n\n### Form Submission\n\n```bash\nSESSION=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://example.com/contact\"\n}\' | jq -r \'.session_id\')\n\n# Get elements: @e1 [input] \"Name\", @e2 [input] \"Email\", @e3 [textarea], @e4 [button] \"Send\"\n\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\"action\": \"fill\", \"ref\": \"@e1\", \"text\": \"John Doe\"}\'\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\"action\": \"fill\", \"ref\": \"@e2\", \"text\": \"john@example.com\"}\'\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\"action\": \"fill\", \"ref\": \"@e3\", \"text\": \"Hello!\"}\'\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\"action\": \"click\", \"ref\": \"@e4\"}\'\n\ninfsh app run agent-browser --function snapshot --session $SESSION --input \'{}\'\ninfsh app run agent-browser --function close --session $SESSION --input \'{}\'\n```\n\n### Search and Extract\n\n```bash\nSESSION=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://google.com\"\n}\' | jq -r \'.session_id\')\n\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\"action\": \"fill\", \"ref\": \"@e1\", \"text\": \"weather today\"}\'\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\"action\": \"press\", \"text\": \"Enter\"}\'\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\"action\": \"wait\", \"wait_ms\": 2000}\'\n\ninfsh app run agent-browser --function snapshot --session $SESSION --input \'{}\'\ninfsh app run agent-browser --function close --session $SESSION --input \'{}\'\n```\n\n### Screenshot with Video\n\n```bash\nSESSION=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://example.com\",\n  \"record_video\": true\n}\' | jq -r \'.session_id\')\n\n# Take full page screenshot\ninfsh app run agent-browser --function screenshot --session $SESSION --input \'{\n  \"full_page\": true\n}\'\n\n# Close and get video\nRESULT=$(infsh app run agent-browser --function close --session $SESSION --input \'{}\')\necho $RESULT | jq \'.video\'\n```\n\n## Sessions\n\nBrowser state persists within a session. Always:\n\n1. Start with `--session new` on first call\n2. Use returned `session_id` for subsequent calls\n3. Close session when done\n\n## Related Skills\n\n```bash\n# Web search (for research + browse)\nnpx skills add inference-sh/skills@web-search\n\n# LLM models (analyze extracted content)\nnpx skills add inference-sh/skills@llm-models\n```\n\n## Documentation\n\n- [inference.sh Sessions](https://inference.sh/docs/extend/sessions) - Session management\n- [Multi-function Apps](https://inference.sh/docs/extend/multi-function-apps) - How functions work\n\n','8651a813447fdd0554f1ef1b4167a01e','2026-10-26 11:22:10','2026-10-26 11:22:10','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(2613,'enc.74656d706c617465732f666f726d2d6175746f6d6174696f6e2e7368','skill_enc.6167656e742d62726f77736572__enc.302e302e31','#!/bin/bash\n# Template: Form Automation Workflow\n# Purpose: Fill and submit web forms with validation\n# Usage: ./form-automation.sh <form-url>\n#\n# This template demonstrates the snapshot-interact-verify pattern:\n# 1. Navigate to form\n# 2. Snapshot to get element refs\n# 3. Fill fields using refs\n# 4. Submit and verify result\n#\n# Customize: Update the refs (@e1, @e2, etc.) based on your form\'s snapshot output\n\nset -euo pipefail\n\nFORM_URL=\"${1:?Usage: $0 <form-url>}\"\n\necho \"Form automation: $FORM_URL\"\n\n# Cleanup handler\ncleanup() {\n  if [ -n \"${SESSION_ID:-}\" ]; then\n    infsh app run agent-browser --function close --session $SESSION_ID --input \'{}\' 2>/dev/null || true\n  fi\n}\ntrap cleanup EXIT\n\n# Step 1: Navigate to form\necho \"Opening form...\"\nRESULT=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"\'\"$FORM_URL\"\'\"\n}\')\nSESSION_ID=$(echo $RESULT | jq -r \'.session_id\')\n\n# Step 2: Display form structure\necho \"\"\necho \"Form elements:\"\necho \"---\"\necho $RESULT | jq -r \'.elements_text\'\necho \"---\"\necho \"\"\n\n# ================================================================\n# DISCOVERY MODE: Shows form structure\n# After running once, update the FORM FILL section below with your refs\n# then delete or comment out this section\n# ================================================================\necho \"Discovery mode: Form structure shown above\"\necho \"\"\necho \"Next steps:\"\necho \"  1. Note the refs for your form fields (e.g., @e1 for name, @e2 for email)\"\necho \"  2. Update the FORM FILL section below\"\necho \"  3. Set environment variables for form data\"\necho \"  4. Comment out this discovery section\"\necho \"\"\nexit 0\n\n# ================================================================\n# FORM FILL: Uncomment and customize after discovery\n# ================================================================\n# echo \"Filling form...\"\n#\n# # Text input\n# infsh app run agent-browser --function interact --session $SESSION_ID --input \'{\n#   \"action\": \"fill\", \"ref\": \"@e1\", \"text\": \"\'\"${FORM_NAME:-John Doe}\"\'\"\n# }\'\n#\n# # Email input\n# infsh app run agent-browser --function interact --session $SESSION_ID --input \'{\n#   \"action\": \"fill\", \"ref\": \"@e2\", \"text\": \"\'\"${FORM_EMAIL:-john@example.com}\"\'\"\n# }\'\n#\n# # Dropdown/select\n# infsh app run agent-browser --function interact --session $SESSION_ID --input \'{\n#   \"action\": \"select\", \"ref\": \"@e3\", \"text\": \"Option 1\"\n# }\'\n#\n# # Checkbox\n# infsh app run agent-browser --function interact --session $SESSION_ID --input \'{\n#   \"action\": \"check\", \"ref\": \"@e4\"\n# }\'\n#\n# # Textarea\n# infsh app run agent-browser --function interact --session $SESSION_ID --input \'{\n#   \"action\": \"fill\", \"ref\": \"@e5\", \"text\": \"\'\"${FORM_MESSAGE:-Hello, this is a test message.}\"\'\"\n# }\'\n#\n# # Submit button\n# echo \"Submitting form...\"\n# infsh app run agent-browser --function interact --session $SESSION_ID --input \'{\n#   \"action\": \"click\", \"ref\": \"@e6\"\n# }\'\n#\n# # Wait for submission\n# infsh app run agent-browser --function interact --session $SESSION_ID --input \'{\n#   \"action\": \"wait\", \"wait_ms\": 2000\n# }\'\n#\n# # Step 3: Verify result\n# echo \"\"\n# echo \"Verifying submission...\"\n# RESULT=$(infsh app run agent-browser --function snapshot --session $SESSION_ID --input \'{}\')\n#\n# URL=$(echo $RESULT | jq -r \'.url\')\n# TITLE=$(echo $RESULT | jq -r \'.title\')\n# echo \"Final URL: $URL\"\n# echo \"Page title: $TITLE\"\n#\n# # Check for success indicators\n# ELEMENTS=$(echo $RESULT | jq -r \'.elements_text\')\n# if echo \"$ELEMENTS\" | grep -qi \"thank you\\|success\\|submitted\"; then\n#   echo \"SUCCESS: Form submitted successfully\"\n# elif echo \"$URL\" | grep -qi \"error\\|fail\"; then\n#   echo \"ERROR: Form submission may have failed\"\n#   exit 1\n# else\n#   echo \"UNKNOWN: Check the result manually\"\n# fi\n#\n# # Optional: Capture evidence\n# infsh app run agent-browser --function screenshot --session $SESSION_ID --input \'{\n#   \"full_page\": true\n# }\' > form-result-screenshot.json\n# echo \"Screenshot saved to form-result-screenshot.json\"\n\necho \"Done\"\n','ec934c21c0ba33bf0dddd49d69294576','2026-10-26 11:22:10','2026-10-26 11:22:10','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(2614,'enc.7265666572656e6365732f636f6d6d616e64732e6d64','skill_enc.6167656e742d62726f77736572__enc.302e302e31','# Command Reference\n\nComplete reference for all agent-browser functions. For quick start, see [SKILL.md](../SKILL.md).\n\n## Base Command\n\nAll commands follow this pattern:\n\n```bash\ninfsh app run agent-browser --function <function> --session <session_id|new> --input \'<json>\'\n```\n\n- `--function`: Function to call (open, snapshot, interact, screenshot, execute, close)\n- `--session`: Session ID from previous call, or `new` to start fresh\n- `--input`: JSON input for the function\n\n## Functions\n\n### open\n\nNavigate to URL and configure browser. This is the entry point for all sessions.\n\n```bash\ninfsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://example.com\",\n  \"width\": 1280,\n  \"height\": 720,\n  \"user_agent\": \"Mozilla/5.0...\",\n  \"record_video\": false,\n  \"show_cursor\": false,\n  \"proxy_url\": null,\n  \"proxy_username\": null,\n  \"proxy_password\": null\n}\'\n```\n\n**Input Fields:**\n\n| Field | Type | Default | Description |\n|-------|------|---------|-------------|\n| `url` | string | required | URL to navigate to |\n| `width` | int | 1280 | Viewport width in pixels |\n| `height` | int | 720 | Viewport height in pixels |\n| `user_agent` | string | null | Custom user agent string |\n| `record_video` | bool | false | Record video (returned on close) |\n| `show_cursor` | bool | false | Show cursor indicator in screenshots/video |\n| `proxy_url` | string | null | Proxy server URL |\n| `proxy_username` | string | null | Proxy auth username |\n| `proxy_password` | string | null | Proxy auth password |\n\n**Output:**\n\n```json\n{\n  \"session_id\": \"abc123\",\n  \"url\": \"https://example.com\",\n  \"title\": \"Example Domain\",\n  \"elements\": [...],\n  \"elements_text\": \"@e1 [a] \\\"More information...\\\" href=\\\"...\\\"\\n...\",\n  \"screenshot\": \"<File>\"\n}\n```\n\n### snapshot\n\nRe-fetch page state with `@e` refs. Call after navigation or DOM changes.\n\n```bash\ninfsh app run agent-browser --function snapshot --session $SESSION_ID --input \'{}\'\n```\n\n**Output:** Same as `open` (url, title, elements, elements_text, screenshot)\n\n### interact\n\nPerform actions on the page using `@e` refs.\n\n```bash\ninfsh app run agent-browser --function interact --session $SESSION_ID --input \'{\n  \"action\": \"click\",\n  \"ref\": \"@e1\"\n}\'\n```\n\n**Input Fields:**\n\n| Field | Type | Description |\n|-------|------|-------------|\n| `action` | string | Action to perform (see Actions table) |\n| `ref` | string | Element ref (e.g., `@e1`) |\n| `text` | string | Text for fill/type/press/select |\n| `direction` | string | Scroll direction: up, down, left, right |\n| `scroll_amount` | int | Scroll pixels (default 400) |\n| `wait_ms` | int | Wait duration in milliseconds |\n| `url` | string | URL for goto action |\n| `target_ref` | string | Target ref for drag action |\n| `file_paths` | array | File paths for upload action |\n\n**Actions:**\n\n| Action | Required Fields | Description |\n|--------|-----------------|-------------|\n| `click` | `ref` | Single click |\n| `dblclick` | `ref` | Double click |\n| `fill` | `ref`, `text` | Clear input and type text |\n| `type` | `text` | Type text without clearing |\n| `press` | `text` | Press key (Enter, Tab, Escape, etc.) |\n| `select` | `ref`, `text` | Select dropdown option by label |\n| `hover` | `ref` | Hover over element |\n| `check` | `ref` | Check checkbox |\n| `uncheck` | `ref` | Uncheck checkbox |\n| `drag` | `ref`, `target_ref` | Drag from ref to target_ref |\n| `upload` | `ref`, `file_paths` | Upload files to file input |\n| `scroll` | `direction` | Scroll page (optional: `scroll_amount`) |\n| `back` | - | Go back in browser history |\n| `wait` | `wait_ms` | Wait for specified milliseconds |\n| `goto` | `url` | Navigate to different URL |\n\n**Output:**\n\n```json\n{\n  \"success\": true,\n  \"action\": \"click\",\n  \"message\": null,\n  \"screenshot\": \"<File>\",\n  \"snapshot\": {\n    \"url\": \"...\",\n    \"title\": \"...\",\n    \"elements\": [...],\n    \"elements_text\": \"...\"\n  }\n}\n```\n\n### screenshot\n\nTake a screenshot of the current page.\n\n```bash\ninfsh app run agent-browser --function screenshot --session $SESSION_ID --input \'{\n  \"full_page\": true\n}\'\n```\n\n**Input Fields:**\n\n| Field | Type | Default | Description |\n|-------|------|---------|-------------|\n| `full_page` | bool | false | Capture full scrollable page |\n\n**Output:**\n\n```json\n{\n  \"screenshot\": \"<File>\",\n  \"width\": 1280,\n  \"height\": 720\n}\n```\n\n### execute\n\nRun JavaScript code on the page.\n\n```bash\ninfsh app run agent-browser --function execute --session $SESSION_ID --input \'{\n  \"code\": \"document.title\"\n}\'\n```\n\n**Input Fields:**\n\n| Field | Type | Description |\n|-------|------|-------------|\n| `code` | string | JavaScript code to execute |\n\n**Output:**\n\n```json\n{\n  \"result\": \"Example Domain\",\n  \"error\": null,\n  \"screenshot\": \"<File>\"\n}\n```\n\n**Examples:**\n\n```bash\n# Get page title\n\'{\"code\": \"document.title\"}\'\n\n# Count elements\n\'{\"code\": \"document.querySelectorAll(\\\"a\\\").length\"}\'\n\n# Extract text\n\'{\"code\": \"document.querySelector(\\\"h1\\\").textContent\"}\'\n\n# Get all links\n\'{\"code\": \"Array.from(document.querySelectorAll(\\\"a\\\")).map(a => a.href)\"}\'\n\n# Scroll to bottom\n\'{\"code\": \"window.scrollTo(0, document.body.scrollHeight)\"}\'\n\n# Get computed style\n\'{\"code\": \"getComputedStyle(document.body).backgroundColor\"}\'\n```\n\n### close\n\nClose the browser session. Returns video if recording was enabled.\n\n```bash\ninfsh app run agent-browser --function close --session $SESSION_ID --input \'{}\'\n```\n\n**Output:**\n\n```json\n{\n  \"success\": true,\n  \"video\": \"<File or null>\"\n}\n```\n\n## Key Combinations\n\nFor the `press` action, use these key names:\n\n| Key | Name |\n|-----|------|\n| Enter | `Enter` |\n| Tab | `Tab` |\n| Escape | `Escape` |\n| Backspace | `Backspace` |\n| Delete | `Delete` |\n| Arrow keys | `ArrowUp`, `ArrowDown`, `ArrowLeft`, `ArrowRight` |\n| Modifiers | `Control`, `Shift`, `Alt`, `Meta` |\n\n**Key combinations:**\n\n```bash\n# Ctrl+A (select all)\n\'{\"action\": \"press\", \"text\": \"Control+a\"}\'\n\n# Ctrl+C (copy)\n\'{\"action\": \"press\", \"text\": \"Control+c\"}\'\n\n# Shift+Tab (focus previous)\n\'{\"action\": \"press\", \"text\": \"Shift+Tab\"}\'\n```\n\n## Error Handling\n\nWhen an action fails, `success` is `false` and `message` contains the error:\n\n```json\n{\n  \"success\": false,\n  \"action\": \"click\",\n  \"message\": \"Unknown ref: @e99. Run \'snapshot\' to get current elements.\",\n  \"screenshot\": \"<File>\",\n  \"snapshot\": {...}\n}\n```\n\nCommon errors:\n- `Unknown ref: @eN` - Ref doesn\'t exist, re-snapshot needed\n- `\'text\' required for fill action` - Missing required field\n- `\'target_ref\' required for drag action` - Missing drag target\n- `Timeout 5000ms exceeded` - Element not found or not clickable\n','0de52bea469f321cc6177d250bbadd92','2026-10-26 11:22:10','2026-10-26 11:22:10','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(2615,'SKILL.md','skill_enc.6167656e742d62726f77736572__enc.302e302e31','---\nversion: 0.0.1\nname: agent-browser\ndescription: \"Browser automation for AI agents via inference.sh. Navigate web pages, interact with elements using @e refs, take screenshots, record video. Capabilities: web scraping, form filling, clicking, typing, drag-drop, file upload, JavaScript execution. Use for: web automation, data extraction, testing, agent browsing, research. Triggers: browser, web automation, scrape, navigate, click, fill form, screenshot, browse web, playwright, headless browser, web agent, surf internet, record video\"\nallowed-tools: Bash(infsh *)\n---\n\n# Agentic Browser\n\nBrowser automation for AI agents via [inference.sh](https://inference.sh). Uses Playwright under the hood with a simple `@e` ref system for element interaction.\n\n![Agentic Browser](https://cloud.inference.sh/app/files/u/4mg21r6ta37mpaz6ktzwtt8krr/01kgjw8atdxgkrsr8a2t5peq7b.jpeg)\n\n## Quick Start\n\n> Requires inference.sh CLI (`infsh`). [Install instructions](https://raw.githubusercontent.com/inference-sh/skills/refs/heads/main/cli-install.md)\n\n```bash\ninfsh login\n\n# Open a page and get interactive elements\ninfsh app run agent-browser --function open --input \'{\"url\": \"https://example.com\"}\' --session new\n```\n\n\n## Core Workflow\n\nEvery browser automation follows this pattern:\n\n1. **Open** - Navigate to URL, get `@e` refs for elements\n2. **Interact** - Use refs to click, fill, drag, etc.\n3. **Re-snapshot** - After navigation/changes, get fresh refs\n4. **Close** - End session (returns video if recording)\n\n```bash\n# 1. Start session\nRESULT=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://example.com/login\"\n}\')\nSESSION_ID=$(echo $RESULT | jq -r \'.session_id\')\n# Elements: @e1 [input] \"Email\", @e2 [input] \"Password\", @e3 [button] \"Sign In\"\n\n# 2. Fill and submit\ninfsh app run agent-browser --function interact --session $SESSION_ID --input \'{\n  \"action\": \"fill\", \"ref\": \"@e1\", \"text\": \"user@example.com\"\n}\'\ninfsh app run agent-browser --function interact --session $SESSION_ID --input \'{\n  \"action\": \"fill\", \"ref\": \"@e2\", \"text\": \"password123\"\n}\'\ninfsh app run agent-browser --function interact --session $SESSION_ID --input \'{\n  \"action\": \"click\", \"ref\": \"@e3\"\n}\'\n\n# 3. Re-snapshot after navigation\ninfsh app run agent-browser --function snapshot --session $SESSION_ID --input \'{}\'\n\n# 4. Close when done\ninfsh app run agent-browser --function close --session $SESSION_ID --input \'{}\'\n```\n\n## Functions\n\n| Function | Description |\n|----------|-------------|\n| `open` | Navigate to URL, configure browser (viewport, proxy, video recording) |\n| `snapshot` | Re-fetch page state with `@e` refs after DOM changes |\n| `interact` | Perform actions using `@e` refs (click, fill, drag, upload, etc.) |\n| `screenshot` | Take page screenshot (viewport or full page) |\n| `execute` | Run JavaScript code on the page |\n| `close` | Close session, returns video if recording was enabled |\n\n## Interact Actions\n\n| Action | Description | Required Fields |\n|--------|-------------|-----------------|\n| `click` | Click element | `ref` |\n| `dblclick` | Double-click element | `ref` |\n| `fill` | Clear and type text | `ref`, `text` |\n| `type` | Type text (no clear) | `text` |\n| `press` | Press key (Enter, Tab, etc.) | `text` |\n| `select` | Select dropdown option | `ref`, `text` |\n| `hover` | Hover over element | `ref` |\n| `check` | Check checkbox | `ref` |\n| `uncheck` | Uncheck checkbox | `ref` |\n| `drag` | Drag and drop | `ref`, `target_ref` |\n| `upload` | Upload file(s) | `ref`, `file_paths` |\n| `scroll` | Scroll page | `direction` (up/down/left/right), `scroll_amount` |\n| `back` | Go back in history | - |\n| `wait` | Wait milliseconds | `wait_ms` |\n| `goto` | Navigate to URL | `url` |\n\n## Element Refs\n\nElements are returned with `@e` refs:\n\n```\n@e1 [a] \"Home\" href=\"/\"\n@e2 [input type=\"text\"] placeholder=\"Search\"\n@e3 [button] \"Submit\"\n@e4 [select] \"Choose option\"\n@e5 [input type=\"checkbox\"] name=\"agree\"\n```\n\n**Important:** Refs are invalidated after navigation. Always re-snapshot after:\n- Clicking links/buttons that navigate\n- Form submissions\n- Dynamic content loading\n\n## Features\n\n### Video Recording\n\nRecord browser sessions for debugging or documentation:\n\n```bash\n# Start with recording enabled (optionally show cursor indicator)\nSESSION=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://example.com\",\n  \"record_video\": true,\n  \"show_cursor\": true\n}\' | jq -r \'.session_id\')\n\n# ... perform actions ...\n\n# Close to get the video file\ninfsh app run agent-browser --function close --session $SESSION --input \'{}\'\n# Returns: {\"success\": true, \"video\": <File>}\n```\n\n### Cursor Indicator\n\nShow a visible cursor in screenshots and video (useful for demos):\n\n```bash\ninfsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://example.com\",\n  \"show_cursor\": true,\n  \"record_video\": true\n}\'\n```\n\nThe cursor appears as a red dot that follows mouse movements and shows click feedback.\n\n### Proxy Support\n\nRoute traffic through a proxy server:\n\n```bash\ninfsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://example.com\",\n  \"proxy_url\": \"http://proxy.example.com:8080\",\n  \"proxy_username\": \"user\",\n  \"proxy_password\": \"pass\"\n}\'\n```\n\n### File Upload\n\nUpload files to file inputs:\n\n```bash\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"upload\",\n  \"ref\": \"@e5\",\n  \"file_paths\": [\"/path/to/file.pdf\"]\n}\'\n```\n\n### Drag and Drop\n\nDrag elements to targets:\n\n```bash\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"drag\",\n  \"ref\": \"@e1\",\n  \"target_ref\": \"@e2\"\n}\'\n```\n\n### JavaScript Execution\n\nRun custom JavaScript:\n\n```bash\ninfsh app run agent-browser --function execute --session $SESSION --input \'{\n  \"code\": \"document.querySelectorAll(\\\"h2\\\").length\"\n}\'\n# Returns: {\"result\": \"5\", \"screenshot\": <File>}\n```\n\n## Deep-Dive Documentation\n\n| Reference | Description |\n|-----------|-------------|\n| [references/commands.md](references/commands.md) | Full function reference with all options |\n| [references/snapshot-refs.md](references/snapshot-refs.md) | Ref lifecycle, invalidation rules, troubleshooting |\n| [references/session-management.md](references/session-management.md) | Session persistence, parallel sessions |\n| [references/authentication.md](references/authentication.md) | Login flows, OAuth, 2FA handling |\n| [references/video-recording.md](references/video-recording.md) | Recording workflows for debugging |\n| [references/proxy-support.md](references/proxy-support.md) | Proxy configuration, geo-testing |\n\n## Ready-to-Use Templates\n\n| Template | Description |\n|----------|-------------|\n| [templates/form-automation.sh](templates/form-automation.sh) | Form filling with validation |\n| [templates/authenticated-session.sh](templates/authenticated-session.sh) | Login once, reuse session |\n| [templates/capture-workflow.sh](templates/capture-workflow.sh) | Content extraction with screenshots |\n\n## Examples\n\n### Form Submission\n\n```bash\nSESSION=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://example.com/contact\"\n}\' | jq -r \'.session_id\')\n\n# Get elements: @e1 [input] \"Name\", @e2 [input] \"Email\", @e3 [textarea], @e4 [button] \"Send\"\n\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\"action\": \"fill\", \"ref\": \"@e1\", \"text\": \"John Doe\"}\'\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\"action\": \"fill\", \"ref\": \"@e2\", \"text\": \"john@example.com\"}\'\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\"action\": \"fill\", \"ref\": \"@e3\", \"text\": \"Hello!\"}\'\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\"action\": \"click\", \"ref\": \"@e4\"}\'\n\ninfsh app run agent-browser --function snapshot --session $SESSION --input \'{}\'\ninfsh app run agent-browser --function close --session $SESSION --input \'{}\'\n```\n\n### Search and Extract\n\n```bash\nSESSION=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://google.com\"\n}\' | jq -r \'.session_id\')\n\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\"action\": \"fill\", \"ref\": \"@e1\", \"text\": \"weather today\"}\'\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\"action\": \"press\", \"text\": \"Enter\"}\'\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\"action\": \"wait\", \"wait_ms\": 2000}\'\n\ninfsh app run agent-browser --function snapshot --session $SESSION --input \'{}\'\ninfsh app run agent-browser --function close --session $SESSION --input \'{}\'\n```\n\n### Screenshot with Video\n\n```bash\nSESSION=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://example.com\",\n  \"record_video\": true\n}\' | jq -r \'.session_id\')\n\n# Take full page screenshot\ninfsh app run agent-browser --function screenshot --session $SESSION --input \'{\n  \"full_page\": true\n}\'\n\n# Close and get video\nRESULT=$(infsh app run agent-browser --function close --session $SESSION --input \'{}\')\necho $RESULT | jq \'.video\'\n```\n\n## Sessions\n\nBrowser state persists within a session. Always:\n\n1. Start with `--session new` on first call\n2. Use returned `session_id` for subsequent calls\n3. Close session when done\n\n## Related Skills\n\n```bash\n# Web search (for research + browse)\nnpx skills add inference-sh/skills@web-search\n\n# LLM models (analyze extracted content)\nnpx skills add inference-sh/skills@llm-models\n```\n\n## Documentation\n\n- [inference.sh Sessions](https://inference.sh/docs/extend/sessions) - Session management\n- [Multi-function Apps](https://inference.sh/docs/extend/multi-function-apps) - How functions work\n\n','8651a813447fdd0554f1ef1b4167a01e','2026-10-26 11:22:10','2026-10-26 11:22:10','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(2616,'enc.7265666572656e6365732f61757468656e7469636174696f6e2e6d64','skill_enc.6167656e742d62726f77736572__enc.302e302e31','# Authentication Patterns\n\nLogin flows, OAuth, 2FA, and authenticated browsing.\n\n**Related**: [session-management.md](session-management.md) for session details, [SKILL.md](../SKILL.md) for quick start.\n\n## Contents\n\n- [Basic Login Flow](#basic-login-flow)\n- [OAuth / SSO Flows](#oauth--sso-flows)\n- [Two-Factor Authentication](#two-factor-authentication)\n- [Session Reuse Patterns](#session-reuse-patterns)\n- [Cookie Extraction](#cookie-extraction)\n- [Security Best Practices](#security-best-practices)\n\n## Basic Login Flow\n\nStandard username/password login:\n\n```bash\n#!/bin/bash\n\n# Start session\nSESSION=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://app.example.com/login\"\n}\' | jq -r \'.session_id\')\n\n# Get form elements\n# Expected: @e1 [input type=\"email\"], @e2 [input type=\"password\"], @e3 [button] \"Sign In\"\n\n# Fill credentials\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"fill\", \"ref\": \"@e1\", \"text\": \"user@example.com\"\n}\'\n\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"fill\", \"ref\": \"@e2\", \"text\": \"\'\"$PASSWORD\"\'\"\n}\'\n\n# Submit\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"click\", \"ref\": \"@e3\"\n}\'\n\n# Wait for redirect\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"wait\", \"wait_ms\": 2000\n}\'\n\n# Verify login succeeded\nRESULT=$(infsh app run agent-browser --function snapshot --session $SESSION --input \'{}\')\nURL=$(echo $RESULT | jq -r \'.url\')\n\nif [[ \"$URL\" == *\"/login\"* ]]; then\n  echo \"Login failed - still on login page\"\n  exit 1\nfi\n\necho \"Login successful\"\n# Continue with authenticated actions...\n```\n\n## OAuth / SSO Flows\n\nFor OAuth redirects (Google, GitHub, etc.):\n\n```bash\n#!/bin/bash\n\nSESSION=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://app.example.com/auth/google\"\n}\' | jq -r \'.session_id\')\n\n# Wait for redirect to Google\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"wait\", \"wait_ms\": 3000\n}\'\n\n# Snapshot to see Google login form\nRESULT=$(infsh app run agent-browser --function snapshot --session $SESSION --input \'{}\')\necho $RESULT | jq \'.elements_text\'\n\n# Fill Google email\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"fill\", \"ref\": \"@e1\", \"text\": \"user@gmail.com\"\n}\'\n\n# Click Next\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"click\", \"ref\": \"@e2\"\n}\'\n\n# Wait and snapshot for password field\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"wait\", \"wait_ms\": 2000\n}\'\nRESULT=$(infsh app run agent-browser --function snapshot --session $SESSION --input \'{}\')\n\n# Fill password\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"fill\", \"ref\": \"@e1\", \"text\": \"\'\"$GOOGLE_PASSWORD\"\'\"\n}\'\n\n# Click Sign in\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"click\", \"ref\": \"@e2\"\n}\'\n\n# Wait for redirect back to app\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"wait\", \"wait_ms\": 5000\n}\'\n\n# Verify we\'re back on the app\nRESULT=$(infsh app run agent-browser --function snapshot --session $SESSION --input \'{}\')\nURL=$(echo $RESULT | jq -r \'.url\')\necho \"Final URL: $URL\"\n```\n\n## Two-Factor Authentication\n\nFor 2FA, you may need human intervention or TOTP generation:\n\n### With TOTP Code\n\n```bash\n# After password, check for 2FA prompt\nRESULT=$(infsh app run agent-browser --function snapshot --session $SESSION --input \'{}\')\nELEMENTS=$(echo $RESULT | jq -r \'.elements_text\')\n\nif echo \"$ELEMENTS\" | grep -qi \"verification\\|2fa\\|authenticator\"; then\n  # Generate TOTP code (requires oathtool)\n  TOTP_CODE=$(oathtool --totp -b \"$TOTP_SECRET\")\n\n  # Fill 2FA code\n  infsh app run agent-browser --function interact --session $SESSION --input \'{\n    \"action\": \"fill\", \"ref\": \"@e1\", \"text\": \"\'\"$TOTP_CODE\"\'\"\n  }\'\n\n  # Submit\n  infsh app run agent-browser --function interact --session $SESSION --input \'{\n    \"action\": \"click\", \"ref\": \"@e2\"\n  }\'\nfi\n```\n\n### With Manual Intervention\n\nFor SMS or hardware token 2FA:\n\n```bash\n# Record video so user can see the 2FA prompt\nSESSION=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://app.example.com/login\",\n  \"record_video\": true\n}\' | jq -r \'.session_id\')\n\n# ... login flow ...\n\n# At 2FA step, prompt user\necho \"2FA code sent. Enter the code:\"\nread -r CODE\n\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"fill\", \"ref\": \"@e1\", \"text\": \"\'\"$CODE\"\'\"\n}\'\n```\n\n## Session Reuse Patterns\n\nSince sessions maintain cookies, you can reuse authenticated sessions:\n\n```bash\n#!/bin/bash\n# login-and-work.sh\n\n# Login once\nlogin() {\n  SESSION=$(infsh app run agent-browser --function open --session new --input \'{\n    \"url\": \"https://app.example.com/login\"\n  }\' | jq -r \'.session_id\')\n\n  # ... login steps ...\n\n  echo $SESSION\n}\n\n# Do work with authenticated session\ndo_work() {\n  local SESSION=$1\n\n  # Navigate to protected page\n  infsh app run agent-browser --function interact --session $SESSION --input \'{\n    \"action\": \"goto\", \"url\": \"https://app.example.com/dashboard\"\n  }\'\n\n  # Extract data\n  infsh app run agent-browser --function snapshot --session $SESSION --input \'{}\'\n}\n\n# Main\nSESSION=$(login)\ndo_work $SESSION\n\n# Don\'t close if you want to reuse!\n# infsh app run agent-browser --function close --session $SESSION --input \'{}\'\n```\n\n## Cookie Extraction\n\nExtract cookies for use in other tools:\n\n```bash\n# Get cookies via JavaScript\nRESULT=$(infsh app run agent-browser --function execute --session $SESSION --input \'{\n  \"code\": \"document.cookie\"\n}\')\nCOOKIES=$(echo $RESULT | jq -r \'.result\')\necho \"Cookies: $COOKIES\"\n\n# Get all cookies including httpOnly (more complete)\nRESULT=$(infsh app run agent-browser --function execute --session $SESSION --input \'{\n  \"code\": \"JSON.stringify(performance.getEntriesByType(\\\"resource\\\").map(r => r.name))\"\n}\')\n```\n\n## Security Best Practices\n\n### 1. Never Hardcode Credentials\n\n```bash\n# Good: Use environment variables\n\'{\"action\": \"fill\", \"ref\": \"@e2\", \"text\": \"\'\"$PASSWORD\"\'\"}\'\n\n# Bad: Hardcoded\n\'{\"action\": \"fill\", \"ref\": \"@e2\", \"text\": \"mypassword123\"}\'\n```\n\n### 2. Use Secure Environment Variables\n\n```bash\n# Set securely\nexport PASSWORD=$(cat /path/to/secure/password)\n\n# Or use a secrets manager\nexport PASSWORD=$(vault read -field=password secret/app)\n```\n\n### 3. Don\'t Log Sensitive Data\n\n```bash\n# Good: Redact sensitive info\necho \"Logging in as $USERNAME\"\n\n# Bad: Logging passwords\necho \"Password: $PASSWORD\"  # Never do this!\n```\n\n### 4. Close Sessions After Use\n\n```bash\n# Always clean up\ntrap \'infsh app run agent-browser --function close --session $SESSION --input \"{}\" 2>/dev/null\' EXIT\n```\n\n### 5. Use Video Recording for Debugging Only\n\nVideo may capture sensitive information:\n\n```bash\n# Only enable when debugging\nif [ \"$DEBUG\" = \"true\" ]; then\n  RECORD_VIDEO=\"true\"\nelse\n  RECORD_VIDEO=\"false\"\nfi\n```\n\n### 6. Verify Login Success\n\nAlways confirm authentication worked:\n\n```bash\n# Check URL changed from login page\nURL=$(echo $RESULT | jq -r \'.url\')\nif [[ \"$URL\" == *\"/login\"* ]] || [[ \"$URL\" == *\"/signin\"* ]]; then\n  echo \"ERROR: Login failed\"\n  exit 1\nfi\n\n# Or check for specific element on authenticated page\nELEMENTS=$(echo $RESULT | jq -r \'.elements_text\')\nif ! echo \"$ELEMENTS\" | grep -q \"Logout\\|Dashboard\\|Welcome\"; then\n  echo \"ERROR: Not authenticated\"\n  exit 1\nfi\n```\n','c3a8f1088214fe0f2835034403b28923','2026-10-26 11:22:10','2026-10-26 11:22:10','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(2617,'enc.7265666572656e6365732f636f6d6d616e64732e6d64','skill_enc.6167656e742d62726f77736572__enc.302e302e31','# Command Reference\n\nComplete reference for all agent-browser functions. For quick start, see [SKILL.md](../SKILL.md).\n\n## Base Command\n\nAll commands follow this pattern:\n\n```bash\ninfsh app run agent-browser --function <function> --session <session_id|new> --input \'<json>\'\n```\n\n- `--function`: Function to call (open, snapshot, interact, screenshot, execute, close)\n- `--session`: Session ID from previous call, or `new` to start fresh\n- `--input`: JSON input for the function\n\n## Functions\n\n### open\n\nNavigate to URL and configure browser. This is the entry point for all sessions.\n\n```bash\ninfsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://example.com\",\n  \"width\": 1280,\n  \"height\": 720,\n  \"user_agent\": \"Mozilla/5.0...\",\n  \"record_video\": false,\n  \"show_cursor\": false,\n  \"proxy_url\": null,\n  \"proxy_username\": null,\n  \"proxy_password\": null\n}\'\n```\n\n**Input Fields:**\n\n| Field | Type | Default | Description |\n|-------|------|---------|-------------|\n| `url` | string | required | URL to navigate to |\n| `width` | int | 1280 | Viewport width in pixels |\n| `height` | int | 720 | Viewport height in pixels |\n| `user_agent` | string | null | Custom user agent string |\n| `record_video` | bool | false | Record video (returned on close) |\n| `show_cursor` | bool | false | Show cursor indicator in screenshots/video |\n| `proxy_url` | string | null | Proxy server URL |\n| `proxy_username` | string | null | Proxy auth username |\n| `proxy_password` | string | null | Proxy auth password |\n\n**Output:**\n\n```json\n{\n  \"session_id\": \"abc123\",\n  \"url\": \"https://example.com\",\n  \"title\": \"Example Domain\",\n  \"elements\": [...],\n  \"elements_text\": \"@e1 [a] \\\"More information...\\\" href=\\\"...\\\"\\n...\",\n  \"screenshot\": \"<File>\"\n}\n```\n\n### snapshot\n\nRe-fetch page state with `@e` refs. Call after navigation or DOM changes.\n\n```bash\ninfsh app run agent-browser --function snapshot --session $SESSION_ID --input \'{}\'\n```\n\n**Output:** Same as `open` (url, title, elements, elements_text, screenshot)\n\n### interact\n\nPerform actions on the page using `@e` refs.\n\n```bash\ninfsh app run agent-browser --function interact --session $SESSION_ID --input \'{\n  \"action\": \"click\",\n  \"ref\": \"@e1\"\n}\'\n```\n\n**Input Fields:**\n\n| Field | Type | Description |\n|-------|------|-------------|\n| `action` | string | Action to perform (see Actions table) |\n| `ref` | string | Element ref (e.g., `@e1`) |\n| `text` | string | Text for fill/type/press/select |\n| `direction` | string | Scroll direction: up, down, left, right |\n| `scroll_amount` | int | Scroll pixels (default 400) |\n| `wait_ms` | int | Wait duration in milliseconds |\n| `url` | string | URL for goto action |\n| `target_ref` | string | Target ref for drag action |\n| `file_paths` | array | File paths for upload action |\n\n**Actions:**\n\n| Action | Required Fields | Description |\n|--------|-----------------|-------------|\n| `click` | `ref` | Single click |\n| `dblclick` | `ref` | Double click |\n| `fill` | `ref`, `text` | Clear input and type text |\n| `type` | `text` | Type text without clearing |\n| `press` | `text` | Press key (Enter, Tab, Escape, etc.) |\n| `select` | `ref`, `text` | Select dropdown option by label |\n| `hover` | `ref` | Hover over element |\n| `check` | `ref` | Check checkbox |\n| `uncheck` | `ref` | Uncheck checkbox |\n| `drag` | `ref`, `target_ref` | Drag from ref to target_ref |\n| `upload` | `ref`, `file_paths` | Upload files to file input |\n| `scroll` | `direction` | Scroll page (optional: `scroll_amount`) |\n| `back` | - | Go back in browser history |\n| `wait` | `wait_ms` | Wait for specified milliseconds |\n| `goto` | `url` | Navigate to different URL |\n\n**Output:**\n\n```json\n{\n  \"success\": true,\n  \"action\": \"click\",\n  \"message\": null,\n  \"screenshot\": \"<File>\",\n  \"snapshot\": {\n    \"url\": \"...\",\n    \"title\": \"...\",\n    \"elements\": [...],\n    \"elements_text\": \"...\"\n  }\n}\n```\n\n### screenshot\n\nTake a screenshot of the current page.\n\n```bash\ninfsh app run agent-browser --function screenshot --session $SESSION_ID --input \'{\n  \"full_page\": true\n}\'\n```\n\n**Input Fields:**\n\n| Field | Type | Default | Description |\n|-------|------|---------|-------------|\n| `full_page` | bool | false | Capture full scrollable page |\n\n**Output:**\n\n```json\n{\n  \"screenshot\": \"<File>\",\n  \"width\": 1280,\n  \"height\": 720\n}\n```\n\n### execute\n\nRun JavaScript code on the page.\n\n```bash\ninfsh app run agent-browser --function execute --session $SESSION_ID --input \'{\n  \"code\": \"document.title\"\n}\'\n```\n\n**Input Fields:**\n\n| Field | Type | Description |\n|-------|------|-------------|\n| `code` | string | JavaScript code to execute |\n\n**Output:**\n\n```json\n{\n  \"result\": \"Example Domain\",\n  \"error\": null,\n  \"screenshot\": \"<File>\"\n}\n```\n\n**Examples:**\n\n```bash\n# Get page title\n\'{\"code\": \"document.title\"}\'\n\n# Count elements\n\'{\"code\": \"document.querySelectorAll(\\\"a\\\").length\"}\'\n\n# Extract text\n\'{\"code\": \"document.querySelector(\\\"h1\\\").textContent\"}\'\n\n# Get all links\n\'{\"code\": \"Array.from(document.querySelectorAll(\\\"a\\\")).map(a => a.href)\"}\'\n\n# Scroll to bottom\n\'{\"code\": \"window.scrollTo(0, document.body.scrollHeight)\"}\'\n\n# Get computed style\n\'{\"code\": \"getComputedStyle(document.body).backgroundColor\"}\'\n```\n\n### close\n\nClose the browser session. Returns video if recording was enabled.\n\n```bash\ninfsh app run agent-browser --function close --session $SESSION_ID --input \'{}\'\n```\n\n**Output:**\n\n```json\n{\n  \"success\": true,\n  \"video\": \"<File or null>\"\n}\n```\n\n## Key Combinations\n\nFor the `press` action, use these key names:\n\n| Key | Name |\n|-----|------|\n| Enter | `Enter` |\n| Tab | `Tab` |\n| Escape | `Escape` |\n| Backspace | `Backspace` |\n| Delete | `Delete` |\n| Arrow keys | `ArrowUp`, `ArrowDown`, `ArrowLeft`, `ArrowRight` |\n| Modifiers | `Control`, `Shift`, `Alt`, `Meta` |\n\n**Key combinations:**\n\n```bash\n# Ctrl+A (select all)\n\'{\"action\": \"press\", \"text\": \"Control+a\"}\'\n\n# Ctrl+C (copy)\n\'{\"action\": \"press\", \"text\": \"Control+c\"}\'\n\n# Shift+Tab (focus previous)\n\'{\"action\": \"press\", \"text\": \"Shift+Tab\"}\'\n```\n\n## Error Handling\n\nWhen an action fails, `success` is `false` and `message` contains the error:\n\n```json\n{\n  \"success\": false,\n  \"action\": \"click\",\n  \"message\": \"Unknown ref: @e99. Run \'snapshot\' to get current elements.\",\n  \"screenshot\": \"<File>\",\n  \"snapshot\": {...}\n}\n```\n\nCommon errors:\n- `Unknown ref: @eN` - Ref doesn\'t exist, re-snapshot needed\n- `\'text\' required for fill action` - Missing required field\n- `\'target_ref\' required for drag action` - Missing drag target\n- `Timeout 5000ms exceeded` - Element not found or not clickable\n','0de52bea469f321cc6177d250bbadd92','2026-10-26 11:22:10','2026-10-26 11:22:10','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(2618,'enc.7265666572656e6365732f61757468656e7469636174696f6e2e6d64','skill_enc.6167656e742d62726f77736572__enc.302e302e31','# Authentication Patterns\n\nLogin flows, OAuth, 2FA, and authenticated browsing.\n\n**Related**: [session-management.md](session-management.md) for session details, [SKILL.md](../SKILL.md) for quick start.\n\n## Contents\n\n- [Basic Login Flow](#basic-login-flow)\n- [OAuth / SSO Flows](#oauth--sso-flows)\n- [Two-Factor Authentication](#two-factor-authentication)\n- [Session Reuse Patterns](#session-reuse-patterns)\n- [Cookie Extraction](#cookie-extraction)\n- [Security Best Practices](#security-best-practices)\n\n## Basic Login Flow\n\nStandard username/password login:\n\n```bash\n#!/bin/bash\n\n# Start session\nSESSION=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://app.example.com/login\"\n}\' | jq -r \'.session_id\')\n\n# Get form elements\n# Expected: @e1 [input type=\"email\"], @e2 [input type=\"password\"], @e3 [button] \"Sign In\"\n\n# Fill credentials\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"fill\", \"ref\": \"@e1\", \"text\": \"user@example.com\"\n}\'\n\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"fill\", \"ref\": \"@e2\", \"text\": \"\'\"$PASSWORD\"\'\"\n}\'\n\n# Submit\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"click\", \"ref\": \"@e3\"\n}\'\n\n# Wait for redirect\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"wait\", \"wait_ms\": 2000\n}\'\n\n# Verify login succeeded\nRESULT=$(infsh app run agent-browser --function snapshot --session $SESSION --input \'{}\')\nURL=$(echo $RESULT | jq -r \'.url\')\n\nif [[ \"$URL\" == *\"/login\"* ]]; then\n  echo \"Login failed - still on login page\"\n  exit 1\nfi\n\necho \"Login successful\"\n# Continue with authenticated actions...\n```\n\n## OAuth / SSO Flows\n\nFor OAuth redirects (Google, GitHub, etc.):\n\n```bash\n#!/bin/bash\n\nSESSION=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://app.example.com/auth/google\"\n}\' | jq -r \'.session_id\')\n\n# Wait for redirect to Google\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"wait\", \"wait_ms\": 3000\n}\'\n\n# Snapshot to see Google login form\nRESULT=$(infsh app run agent-browser --function snapshot --session $SESSION --input \'{}\')\necho $RESULT | jq \'.elements_text\'\n\n# Fill Google email\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"fill\", \"ref\": \"@e1\", \"text\": \"user@gmail.com\"\n}\'\n\n# Click Next\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"click\", \"ref\": \"@e2\"\n}\'\n\n# Wait and snapshot for password field\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"wait\", \"wait_ms\": 2000\n}\'\nRESULT=$(infsh app run agent-browser --function snapshot --session $SESSION --input \'{}\')\n\n# Fill password\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"fill\", \"ref\": \"@e1\", \"text\": \"\'\"$GOOGLE_PASSWORD\"\'\"\n}\'\n\n# Click Sign in\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"click\", \"ref\": \"@e2\"\n}\'\n\n# Wait for redirect back to app\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"wait\", \"wait_ms\": 5000\n}\'\n\n# Verify we\'re back on the app\nRESULT=$(infsh app run agent-browser --function snapshot --session $SESSION --input \'{}\')\nURL=$(echo $RESULT | jq -r \'.url\')\necho \"Final URL: $URL\"\n```\n\n## Two-Factor Authentication\n\nFor 2FA, you may need human intervention or TOTP generation:\n\n### With TOTP Code\n\n```bash\n# After password, check for 2FA prompt\nRESULT=$(infsh app run agent-browser --function snapshot --session $SESSION --input \'{}\')\nELEMENTS=$(echo $RESULT | jq -r \'.elements_text\')\n\nif echo \"$ELEMENTS\" | grep -qi \"verification\\|2fa\\|authenticator\"; then\n  # Generate TOTP code (requires oathtool)\n  TOTP_CODE=$(oathtool --totp -b \"$TOTP_SECRET\")\n\n  # Fill 2FA code\n  infsh app run agent-browser --function interact --session $SESSION --input \'{\n    \"action\": \"fill\", \"ref\": \"@e1\", \"text\": \"\'\"$TOTP_CODE\"\'\"\n  }\'\n\n  # Submit\n  infsh app run agent-browser --function interact --session $SESSION --input \'{\n    \"action\": \"click\", \"ref\": \"@e2\"\n  }\'\nfi\n```\n\n### With Manual Intervention\n\nFor SMS or hardware token 2FA:\n\n```bash\n# Record video so user can see the 2FA prompt\nSESSION=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"https://app.example.com/login\",\n  \"record_video\": true\n}\' | jq -r \'.session_id\')\n\n# ... login flow ...\n\n# At 2FA step, prompt user\necho \"2FA code sent. Enter the code:\"\nread -r CODE\n\ninfsh app run agent-browser --function interact --session $SESSION --input \'{\n  \"action\": \"fill\", \"ref\": \"@e1\", \"text\": \"\'\"$CODE\"\'\"\n}\'\n```\n\n## Session Reuse Patterns\n\nSince sessions maintain cookies, you can reuse authenticated sessions:\n\n```bash\n#!/bin/bash\n# login-and-work.sh\n\n# Login once\nlogin() {\n  SESSION=$(infsh app run agent-browser --function open --session new --input \'{\n    \"url\": \"https://app.example.com/login\"\n  }\' | jq -r \'.session_id\')\n\n  # ... login steps ...\n\n  echo $SESSION\n}\n\n# Do work with authenticated session\ndo_work() {\n  local SESSION=$1\n\n  # Navigate to protected page\n  infsh app run agent-browser --function interact --session $SESSION --input \'{\n    \"action\": \"goto\", \"url\": \"https://app.example.com/dashboard\"\n  }\'\n\n  # Extract data\n  infsh app run agent-browser --function snapshot --session $SESSION --input \'{}\'\n}\n\n# Main\nSESSION=$(login)\ndo_work $SESSION\n\n# Don\'t close if you want to reuse!\n# infsh app run agent-browser --function close --session $SESSION --input \'{}\'\n```\n\n## Cookie Extraction\n\nExtract cookies for use in other tools:\n\n```bash\n# Get cookies via JavaScript\nRESULT=$(infsh app run agent-browser --function execute --session $SESSION --input \'{\n  \"code\": \"document.cookie\"\n}\')\nCOOKIES=$(echo $RESULT | jq -r \'.result\')\necho \"Cookies: $COOKIES\"\n\n# Get all cookies including httpOnly (more complete)\nRESULT=$(infsh app run agent-browser --function execute --session $SESSION --input \'{\n  \"code\": \"JSON.stringify(performance.getEntriesByType(\\\"resource\\\").map(r => r.name))\"\n}\')\n```\n\n## Security Best Practices\n\n### 1. Never Hardcode Credentials\n\n```bash\n# Good: Use environment variables\n\'{\"action\": \"fill\", \"ref\": \"@e2\", \"text\": \"\'\"$PASSWORD\"\'\"}\'\n\n# Bad: Hardcoded\n\'{\"action\": \"fill\", \"ref\": \"@e2\", \"text\": \"mypassword123\"}\'\n```\n\n### 2. Use Secure Environment Variables\n\n```bash\n# Set securely\nexport PASSWORD=$(cat /path/to/secure/password)\n\n# Or use a secrets manager\nexport PASSWORD=$(vault read -field=password secret/app)\n```\n\n### 3. Don\'t Log Sensitive Data\n\n```bash\n# Good: Redact sensitive info\necho \"Logging in as $USERNAME\"\n\n# Bad: Logging passwords\necho \"Password: $PASSWORD\"  # Never do this!\n```\n\n### 4. Close Sessions After Use\n\n```bash\n# Always clean up\ntrap \'infsh app run agent-browser --function close --session $SESSION --input \"{}\" 2>/dev/null\' EXIT\n```\n\n### 5. Use Video Recording for Debugging Only\n\nVideo may capture sensitive information:\n\n```bash\n# Only enable when debugging\nif [ \"$DEBUG\" = \"true\" ]; then\n  RECORD_VIDEO=\"true\"\nelse\n  RECORD_VIDEO=\"false\"\nfi\n```\n\n### 6. Verify Login Success\n\nAlways confirm authentication worked:\n\n```bash\n# Check URL changed from login page\nURL=$(echo $RESULT | jq -r \'.url\')\nif [[ \"$URL\" == *\"/login\"* ]] || [[ \"$URL\" == *\"/signin\"* ]]; then\n  echo \"ERROR: Login failed\"\n  exit 1\nfi\n\n# Or check for specific element on authenticated page\nELEMENTS=$(echo $RESULT | jq -r \'.elements_text\')\nif ! echo \"$ELEMENTS\" | grep -q \"Logout\\|Dashboard\\|Welcome\"; then\n  echo \"ERROR: Not authenticated\"\n  exit 1\nfi\n```\n','c3a8f1088214fe0f2835034403b28923','2026-10-26 11:22:10','2026-10-26 11:22:10','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(2619,'enc.74656d706c617465732f636170747572652d776f726b666c6f772e7368','skill_enc.6167656e742d62726f77736572__enc.302e302e31','#!/bin/bash\n# Template: Content Capture Workflow\n# Purpose: Extract content from web pages (text, screenshots, video)\n# Usage: ./capture-workflow.sh <url> [output-dir]\n#\n# Outputs:\n#   - page-screenshot.json: Page screenshot data\n#   - page-full-screenshot.json: Full page screenshot data\n#   - page-elements.txt: Interactive elements with refs\n#   - page-text.txt: All text content\n#   - page-links.txt: All links on the page\n#   - session-video.json: Video recording (if enabled)\n\nset -euo pipefail\n\nTARGET_URL=\"${1:?Usage: $0 <url> [output-dir]}\"\nOUTPUT_DIR=\"${2:-.}\"\n\necho \"Content capture: $TARGET_URL\"\necho \"Output directory: $OUTPUT_DIR\"\n\nmkdir -p \"$OUTPUT_DIR\"\n\n# Cleanup handler\ncleanup() {\n  if [ -n \"${SESSION_ID:-}\" ]; then\n    echo \"Closing session...\"\n    CLOSE_RESULT=$(infsh app run agent-browser --function close --session $SESSION_ID --input \'{}\' 2>/dev/null || echo \'{}\')\n\n    # Save video if available\n    VIDEO=$(echo $CLOSE_RESULT | jq -r \'.video // empty\')\n    if [ -n \"$VIDEO\" ]; then\n      echo \"$CLOSE_RESULT\" > \"$OUTPUT_DIR/session-video.json\"\n      echo \"Video saved to: $OUTPUT_DIR/session-video.json\"\n    fi\n  fi\n}\ntrap cleanup EXIT\n\n# ================================================================\n# CONFIGURATION\n# ================================================================\nRECORD_VIDEO=false  # Set to true to record video\nFULL_PAGE=true      # Set to true for full page screenshots\nEXTRACT_LINKS=true  # Set to true to extract all links\nSCROLL_PAGES=0      # Number of scroll actions for infinite scroll pages\n\n# ================================================================\n# CAPTURE WORKFLOW\n# ================================================================\n\n# Start session\necho \"Opening page...\"\nRESULT=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"\'\"$TARGET_URL\"\'\",\n  \"record_video\": \'$RECORD_VIDEO\',\n  \"width\": 1920,\n  \"height\": 1080\n}\')\nSESSION_ID=$(echo $RESULT | jq -r \'.session_id\')\n\n# Get metadata\nURL=$(echo $RESULT | jq -r \'.url\')\nTITLE=$(echo $RESULT | jq -r \'.title\')\necho \"Title: $TITLE\"\necho \"URL: $URL\"\n\n# Save elements\necho $RESULT | jq -r \'.elements_text\' > \"$OUTPUT_DIR/page-elements.txt\"\necho \"Elements saved to: $OUTPUT_DIR/page-elements.txt\"\n\n# Handle infinite scroll (if configured)\nif [ $SCROLL_PAGES -gt 0 ]; then\n  echo \"Scrolling through $SCROLL_PAGES pages...\"\n  for ((i=1; i<=SCROLL_PAGES; i++)); do\n    infsh app run agent-browser --function interact --session $SESSION_ID --input \'{\n      \"action\": \"scroll\", \"direction\": \"down\", \"scroll_amount\": 800\n    }\' > /dev/null\n    infsh app run agent-browser --function interact --session $SESSION_ID --input \'{\n      \"action\": \"wait\", \"wait_ms\": 1000\n    }\' > /dev/null\n    echo \"  Scrolled page $i/$SCROLL_PAGES\"\n  done\n\n  # Re-snapshot after scrolling\n  RESULT=$(infsh app run agent-browser --function snapshot --session $SESSION_ID --input \'{}\')\nfi\n\n# Take viewport screenshot\necho \"Taking viewport screenshot...\"\ninfsh app run agent-browser --function screenshot --session $SESSION_ID --input \'{}\' > \"$OUTPUT_DIR/page-screenshot.json\"\necho \"Screenshot saved to: $OUTPUT_DIR/page-screenshot.json\"\n\n# Take full page screenshot (if configured)\nif [ \"$FULL_PAGE\" = true ]; then\n  echo \"Taking full page screenshot...\"\n  infsh app run agent-browser --function screenshot --session $SESSION_ID --input \'{\n    \"full_page\": true\n  }\' > \"$OUTPUT_DIR/page-full-screenshot.json\"\n  echo \"Full screenshot saved to: $OUTPUT_DIR/page-full-screenshot.json\"\nfi\n\n# Extract all text content\necho \"Extracting text content...\"\nRESULT=$(infsh app run agent-browser --function execute --session $SESSION_ID --input \'{\n  \"code\": \"document.body.innerText\"\n}\')\necho $RESULT | jq -r \'.result\' > \"$OUTPUT_DIR/page-text.txt\"\necho \"Text saved to: $OUTPUT_DIR/page-text.txt\"\n\n# Extract all links (if configured)\nif [ \"$EXTRACT_LINKS\" = true ]; then\n  echo \"Extracting links...\"\n  RESULT=$(infsh app run agent-browser --function execute --session $SESSION_ID --input \'{\n    \"code\": \"Array.from(document.querySelectorAll(\\\"a[href]\\\")).map(a => a.href + \\\" | \\\" + (a.textContent || \\\"\\\").trim().slice(0,50)).join(\\\"\\\\n\\\")\"\n  }\')\n  echo $RESULT | jq -r \'.result\' > \"$OUTPUT_DIR/page-links.txt\"\n  echo \"Links saved to: $OUTPUT_DIR/page-links.txt\"\nfi\n\n# ================================================================\n# CUSTOM EXTRACTION: Add your specific extraction logic here\n# ================================================================\n\n# Example: Extract specific elements by selector\n# RESULT=$(infsh app run agent-browser --function execute --session $SESSION_ID --input \'{\n#   \"code\": \"Array.from(document.querySelectorAll(\\\"h2\\\")).map(h => h.textContent).join(\\\"\\\\n\\\")\"\n# }\')\n# echo $RESULT | jq -r \'.result\' > \"$OUTPUT_DIR/headings.txt\"\n\n# Example: Extract JSON data from script tag\n# RESULT=$(infsh app run agent-browser --function execute --session $SESSION_ID --input \'{\n#   \"code\": \"JSON.parse(document.querySelector(\\\"script[type=application/json]\\\").textContent)\"\n# }\')\n# echo $RESULT | jq \'.result\' > \"$OUTPUT_DIR/json-data.json\"\n\n# Example: Extract table data\n# RESULT=$(infsh app run agent-browser --function execute --session $SESSION_ID --input \'{\n#   \"code\": \"Array.from(document.querySelectorAll(\\\"table tr\\\")).map(tr => Array.from(tr.cells).map(td => td.textContent.trim()).join(\\\",\\\")).join(\\\"\\\\n\\\")\"\n# }\')\n# echo $RESULT | jq -r \'.result\' > \"$OUTPUT_DIR/table-data.csv\"\n\n# ================================================================\n# SUMMARY\n# ================================================================\necho \"\"\necho \"Capture complete!\"\necho \"Files created:\"\nls -la \"$OUTPUT_DIR\"/*.txt \"$OUTPUT_DIR\"/*.json 2>/dev/null || true\n','1665ab76efae2c43bb821c4fe0862fcd','2026-10-26 11:22:10','2026-10-26 11:22:10','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(2620,'enc.74656d706c617465732f61757468656e746963617465642d73657373696f6e2e7368','skill_enc.6167656e742d62726f77736572__enc.302e302e31','#!/bin/bash\n# Template: Authenticated Session Workflow\n# Purpose: Login once, perform actions, clean up\n# Usage: ./authenticated-session.sh <login-url>\n#\n# Environment variables:\n#   APP_USERNAME - Login username/email\n#   APP_PASSWORD - Login password\n#\n# Two modes:\n#   1. Discovery mode (default): Shows login form structure\n#   2. Login mode: Performs actual login after you update refs\n#\n# Setup steps:\n#   1. Run once to see form structure (discovery mode)\n#   2. Update refs in LOGIN FLOW section below\n#   3. Set APP_USERNAME and APP_PASSWORD\n#   4. Comment out the DISCOVERY section\n\nset -euo pipefail\n\nLOGIN_URL=\"${1:?Usage: $0 <login-url>}\"\n\necho \"Authentication workflow: $LOGIN_URL\"\n\n# Cleanup handler\ncleanup() {\n  if [ -n \"${SESSION_ID:-}\" ]; then\n    echo \"Closing session...\"\n    infsh app run agent-browser --function close --session $SESSION_ID --input \'{}\' 2>/dev/null || true\n  fi\n}\ntrap cleanup EXIT\n\n# ================================================================\n# DISCOVERY MODE: Shows login form structure\n# Delete this section after setup\n# ================================================================\necho \"Opening login page...\"\nRESULT=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"\'\"$LOGIN_URL\"\'\"\n}\')\nSESSION_ID=$(echo $RESULT | jq -r \'.session_id\')\n\necho \"\"\necho \"Login form structure:\"\necho \"---\"\necho $RESULT | jq -r \'.elements_text\'\necho \"---\"\necho \"\"\necho \"Discovery mode complete.\"\necho \"\"\necho \"Next steps:\"\necho \"  1. Identify the refs: username=@e?, password=@e?, submit=@e?\"\necho \"  2. Update the LOGIN FLOW section below with your refs\"\necho \"  3. Set environment variables:\"\necho \"     export APP_USERNAME=\'your-username\'\"\necho \"     export APP_PASSWORD=\'your-password\'\"\necho \"  4. Comment out this DISCOVERY MODE section\"\necho \"\"\nexit 0\n\n# ================================================================\n# LOGIN FLOW: Uncomment and customize after discovery\n# ================================================================\n# : \"${APP_USERNAME:?Set APP_USERNAME environment variable}\"\n# : \"${APP_PASSWORD:?Set APP_PASSWORD environment variable}\"\n#\n# echo \"Opening login page...\"\n# RESULT=$(infsh app run agent-browser --function open --session new --input \'{\n#   \"url\": \"\'\"$LOGIN_URL\"\'\",\n#   \"record_video\": false\n# }\')\n# SESSION_ID=$(echo $RESULT | jq -r \'.session_id\')\n#\n# echo \"Filling credentials...\"\n# # Update @e1, @e2, @e3 to match your form\n# infsh app run agent-browser --function interact --session $SESSION_ID --input \'{\n#   \"action\": \"fill\", \"ref\": \"@e1\", \"text\": \"\'\"$APP_USERNAME\"\'\"\n# }\'\n#\n# infsh app run agent-browser --function interact --session $SESSION_ID --input \'{\n#   \"action\": \"fill\", \"ref\": \"@e2\", \"text\": \"\'\"$APP_PASSWORD\"\'\"\n# }\'\n#\n# echo \"Submitting...\"\n# infsh app run agent-browser --function interact --session $SESSION_ID --input \'{\n#   \"action\": \"click\", \"ref\": \"@e3\"\n# }\'\n#\n# # Wait for redirect\n# infsh app run agent-browser --function interact --session $SESSION_ID --input \'{\n#   \"action\": \"wait\", \"wait_ms\": 3000\n# }\'\n#\n# # Verify login succeeded\n# RESULT=$(infsh app run agent-browser --function snapshot --session $SESSION_ID --input \'{}\')\n# URL=$(echo $RESULT | jq -r \'.url\')\n#\n# if [[ \"$URL\" == *\"/login\"* ]] || [[ \"$URL\" == *\"/signin\"* ]]; then\n#   echo \"ERROR: Login failed - still on login page\"\n#   echo \"URL: $URL\"\n#   infsh app run agent-browser --function screenshot --session $SESSION_ID --input \'{}\' > login-failed.json\n#   exit 1\n# fi\n#\n# echo \"Login successful!\"\n# echo \"Current URL: $URL\"\n# echo \"\"\n#\n# # ================================================================\n# # AUTHENTICATED ACTIONS: Add your post-login automation here\n# # ================================================================\n# echo \"Performing authenticated actions...\"\n#\n# # Example: Navigate to dashboard\n# # infsh app run agent-browser --function interact --session $SESSION_ID --input \'{\n# #   \"action\": \"goto\", \"url\": \"https://app.example.com/dashboard\"\n# # }\'\n#\n# # Example: Click a menu item\n# # infsh app run agent-browser --function interact --session $SESSION_ID --input \'{\n# #   \"action\": \"click\", \"ref\": \"@e5\"\n# # }\'\n#\n# # Example: Extract data\n# # RESULT=$(infsh app run agent-browser --function execute --session $SESSION_ID --input \'{\n# #   \"code\": \"document.querySelector(\\\".user-data\\\").textContent\"\n# # }\')\n# # echo \"Data: $(echo $RESULT | jq -r \'.result\')\"\n#\n# # Example: Take screenshot of authenticated page\n# # infsh app run agent-browser --function screenshot --session $SESSION_ID --input \'{\n# #   \"full_page\": true\n# # }\' > authenticated-page.json\n#\n# echo \"\"\n# echo \"Authenticated session complete\"\n','b320b2b53f414ccf028fe68ecaa5f180','2026-10-26 11:22:10','2026-10-26 11:22:10','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(2621,'enc.74656d706c617465732f636170747572652d776f726b666c6f772e7368','skill_enc.6167656e742d62726f77736572__enc.302e302e31','#!/bin/bash\n# Template: Content Capture Workflow\n# Purpose: Extract content from web pages (text, screenshots, video)\n# Usage: ./capture-workflow.sh <url> [output-dir]\n#\n# Outputs:\n#   - page-screenshot.json: Page screenshot data\n#   - page-full-screenshot.json: Full page screenshot data\n#   - page-elements.txt: Interactive elements with refs\n#   - page-text.txt: All text content\n#   - page-links.txt: All links on the page\n#   - session-video.json: Video recording (if enabled)\n\nset -euo pipefail\n\nTARGET_URL=\"${1:?Usage: $0 <url> [output-dir]}\"\nOUTPUT_DIR=\"${2:-.}\"\n\necho \"Content capture: $TARGET_URL\"\necho \"Output directory: $OUTPUT_DIR\"\n\nmkdir -p \"$OUTPUT_DIR\"\n\n# Cleanup handler\ncleanup() {\n  if [ -n \"${SESSION_ID:-}\" ]; then\n    echo \"Closing session...\"\n    CLOSE_RESULT=$(infsh app run agent-browser --function close --session $SESSION_ID --input \'{}\' 2>/dev/null || echo \'{}\')\n\n    # Save video if available\n    VIDEO=$(echo $CLOSE_RESULT | jq -r \'.video // empty\')\n    if [ -n \"$VIDEO\" ]; then\n      echo \"$CLOSE_RESULT\" > \"$OUTPUT_DIR/session-video.json\"\n      echo \"Video saved to: $OUTPUT_DIR/session-video.json\"\n    fi\n  fi\n}\ntrap cleanup EXIT\n\n# ================================================================\n# CONFIGURATION\n# ================================================================\nRECORD_VIDEO=false  # Set to true to record video\nFULL_PAGE=true      # Set to true for full page screenshots\nEXTRACT_LINKS=true  # Set to true to extract all links\nSCROLL_PAGES=0      # Number of scroll actions for infinite scroll pages\n\n# ================================================================\n# CAPTURE WORKFLOW\n# ================================================================\n\n# Start session\necho \"Opening page...\"\nRESULT=$(infsh app run agent-browser --function open --session new --input \'{\n  \"url\": \"\'\"$TARGET_URL\"\'\",\n  \"record_video\": \'$RECORD_VIDEO\',\n  \"width\": 1920,\n  \"height\": 1080\n}\')\nSESSION_ID=$(echo $RESULT | jq -r \'.session_id\')\n\n# Get metadata\nURL=$(echo $RESULT | jq -r \'.url\')\nTITLE=$(echo $RESULT | jq -r \'.title\')\necho \"Title: $TITLE\"\necho \"URL: $URL\"\n\n# Save elements\necho $RESULT | jq -r \'.elements_text\' > \"$OUTPUT_DIR/page-elements.txt\"\necho \"Elements saved to: $OUTPUT_DIR/page-elements.txt\"\n\n# Handle infinite scroll (if configured)\nif [ $SCROLL_PAGES -gt 0 ]; then\n  echo \"Scrolling through $SCROLL_PAGES pages...\"\n  for ((i=1; i<=SCROLL_PAGES; i++)); do\n    infsh app run agent-browser --function interact --session $SESSION_ID --input \'{\n      \"action\": \"scroll\", \"direction\": \"down\", \"scroll_amount\": 800\n    }\' > /dev/null\n    infsh app run agent-browser --function interact --session $SESSION_ID --input \'{\n      \"action\": \"wait\", \"wait_ms\": 1000\n    }\' > /dev/null\n    echo \"  Scrolled page $i/$SCROLL_PAGES\"\n  done\n\n  # Re-snapshot after scrolling\n  RESULT=$(infsh app run agent-browser --function snapshot --session $SESSION_ID --input \'{}\')\nfi\n\n# Take viewport screenshot\necho \"Taking viewport screenshot...\"\ninfsh app run agent-browser --function screenshot --session $SESSION_ID --input \'{}\' > \"$OUTPUT_DIR/page-screenshot.json\"\necho \"Screenshot saved to: $OUTPUT_DIR/page-screenshot.json\"\n\n# Take full page screenshot (if configured)\nif [ \"$FULL_PAGE\" = true ]; then\n  echo \"Taking full page screenshot...\"\n  infsh app run agent-browser --function screenshot --session $SESSION_ID --input \'{\n    \"full_page\": true\n  }\' > \"$OUTPUT_DIR/page-full-screenshot.json\"\n  echo \"Full screenshot saved to: $OUTPUT_DIR/page-full-screenshot.json\"\nfi\n\n# Extract all text content\necho \"Extracting text content...\"\nRESULT=$(infsh app run agent-browser --function execute --session $SESSION_ID --input \'{\n  \"code\": \"document.body.innerText\"\n}\')\necho $RESULT | jq -r \'.result\' > \"$OUTPUT_DIR/page-text.txt\"\necho \"Text saved to: $OUTPUT_DIR/page-text.txt\"\n\n# Extract all links (if configured)\nif [ \"$EXTRACT_LINKS\" = true ]; then\n  echo \"Extracting links...\"\n  RESULT=$(infsh app run agent-browser --function execute --session $SESSION_ID --input \'{\n    \"code\": \"Array.from(document.querySelectorAll(\\\"a[href]\\\")).map(a => a.href + \\\" | \\\" + (a.textContent || \\\"\\\").trim().slice(0,50)).join(\\\"\\\\n\\\")\"\n  }\')\n  echo $RESULT | jq -r \'.result\' > \"$OUTPUT_DIR/page-links.txt\"\n  echo \"Links saved to: $OUTPUT_DIR/page-links.txt\"\nfi\n\n# ================================================================\n# CUSTOM EXTRACTION: Add your specific extraction logic here\n# ================================================================\n\n# Example: Extract specific elements by selector\n# RESULT=$(infsh app run agent-browser --function execute --session $SESSION_ID --input \'{\n#   \"code\": \"Array.from(document.querySelectorAll(\\\"h2\\\")).map(h => h.textContent).join(\\\"\\\\n\\\")\"\n# }\')\n# echo $RESULT | jq -r \'.result\' > \"$OUTPUT_DIR/headings.txt\"\n\n# Example: Extract JSON data from script tag\n# RESULT=$(infsh app run agent-browser --function execute --session $SESSION_ID --input \'{\n#   \"code\": \"JSON.parse(document.querySelector(\\\"script[type=application/json]\\\").textContent)\"\n# }\')\n# echo $RESULT | jq \'.result\' > \"$OUTPUT_DIR/json-data.json\"\n\n# Example: Extract table data\n# RESULT=$(infsh app run agent-browser --function execute --session $SESSION_ID --input \'{\n#   \"code\": \"Array.from(document.querySelectorAll(\\\"table tr\\\")).map(tr => Array.from(tr.cells).map(td => td.textContent.trim()).join(\\\",\\\")).join(\\\"\\\\n\\\")\"\n# }\')\n# echo $RESULT | jq -r \'.result\' > \"$OUTPUT_DIR/table-data.csv\"\n\n# ================================================================\n# SUMMARY\n# ================================================================\necho \"\"\necho \"Capture complete!\"\necho \"Files created:\"\nls -la \"$OUTPUT_DIR\"/*.txt \"$OUTPUT_DIR\"/*.json 2>/dev/null || true\n','1665ab76efae2c43bb821c4fe0862fcd','2026-10-26 11:22:10','2026-10-26 11:22:10','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(2622,'manifest.json','agentspec__enc.706169642d6d656469612d63726561746976652d73747261746567697374__enc.302e302e31','{\"name\":\"paid-media-creative-strategist\",\"description\":\"专注广告文案、RSA 优化、素材组设计和创意测试的付费媒体创意专家，横跨 Google、Meta、Microsoft 和程序化平台，用数据驱动说服力。\",\"content\":\"{\\n  \\\"version\\\": \\\"1.0\\\",\\n  \\\"source\\\": {\\n    \\\"repository\\\": \\\"https://github.com/jnMetaCode/agency-agents-zh\\\",\\n    \\\"commit\\\": \\\"23c2746913fe46260450517fa5afb58afc61fed7\\\",\\n    \\\"original_path\\\": \\\"paid-media/paid-media-creative-strategist.md\\\",\\n    \\\"openclaw_mode\\\": true\\n  },\\n  \\\"description\\\": \\\"专注广告文案、RSA 优化、素材组设计和创意测试的付费媒体创意专家，横跨 Google、Meta、Mic