type\":\"config\"},{\"name\":\"tool-analysis.json\",\"type\":\"tool-analysis\"},{\"name\":\"AGENTS.md\",\"type\":\"config\"},{\"name\":\"SOUL.md\",\"type\":\"config\"},{\"name\":\"MEMORY.md\",\"type\":\"config\"}]}','beb3807fa8e911af725b59fe497a434f','2026-10-26 11:22:14','2026-10-26 11:22:14','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(3253,'skill_index.json','skill_elevenlabs-dialogue','{\"labels\":{\"latest\":\"0.0.1\"},\"versions\":{\"0.0.1\":[\"SKILL.md\"]}}','a954ba25a6022882637d1312aa486859','2026-10-26 11:22:14','2026-10-26 11:22:14','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(3254,'skill_index.json','skill_elevenlabs-dialogue','{\"labels\":{\"latest\":\"0.0.1\"},\"versions\":{\"0.0.1\":[\"SKILL.md\"]}}','a954ba25a6022882637d1312aa486859','2026-10-26 11:22:14','2026-10-26 11:22:14','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(3255,'resource_crons_jobs__json.json','agentspec__enc.7370656369616c697a65642d646f63756d656e742d67656e657261746f72__enc.302e302e31','{\"name\":\"jobs.json\",\"type\":\"crons\",\"content\":\"[]\\n\",\"metadata\":{\"uniformId\":1792984933682},\"resourceIdentifier\":\"crons::jobs.json\"}','5e5dad25495e4040f4a85620afe9fb7f','2026-10-26 11:22:14','2026-10-26 11:22:14','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(3256,'SKILL.md','skill_enc.656c6576656e6c6162732d6d75736963__enc.302e302e31','---\nversion: 0.0.1\nname: elevenlabs-music\ndescription: \"ElevenLabs AI music generation - create original music from text prompts via inference.sh CLI. Capabilities: text-to-music, custom duration up to 10 minutes, genre/mood/instrument control, royalty-free commercial use. Use for: background music, soundtracks, jingles, podcasts, video scores, game audio. Triggers: elevenlabs music, eleven labs music, ai music, generate music, music generation, compose music, ai composer, create song, soundtrack, background music, jingle, elevenlabs compose, music ai\"\nallowed-tools: Bash(infsh *)\n---\n\n# ElevenLabs Music Generation\n\nGenerate original music from text prompts via [inference.sh](https://inference.sh) CLI.\n\n![Music Generation](https://cloud.inference.sh/u/4mg21r6ta37mpaz6ktzwtt8krr/01jz01qvx0gdcyvhvhpfjjb6s4.png)\n\n## Quick Start\n\n> Requires inference.sh CLI (`infsh`). [Install instructions](https://raw.githubusercontent.com/inference-sh/skills/refs/heads/main/cli-install.md)\n\n```bash\ninfsh login\n\n# Generate music\ninfsh app run elevenlabs/music --input \'{\"prompt\": \"Upbeat electronic dance track with driving synths\"}\'\n```\n\n\n## Parameters\n\n| Parameter | Type | Default | Description |\n|-----------|------|---------|-------------|\n| `prompt` | string | required | Description of desired music (max 2000 chars) |\n| `duration_seconds` | number | 30 | Duration in seconds (5-600, max 10 minutes) |\n\n## Examples\n\n### Background Music\n\n```bash\n# Lo-fi study beats\ninfsh app run elevenlabs/music --input \'{\n  \"prompt\": \"Lo-fi hip hop beat, chill study music, vinyl crackle, mellow piano\",\n  \"duration_seconds\": 120\n}\'\n\n# Corporate background\ninfsh app run elevenlabs/music --input \'{\n  \"prompt\": \"Light corporate background music, positive, motivational, clean\",\n  \"duration_seconds\": 60\n}\'\n```\n\n### Cinematic Scores\n\n```bash\n# Epic trailer\ninfsh app run elevenlabs/music --input \'{\n  \"prompt\": \"Epic cinematic orchestral score, dramatic build-up, brass and strings, trailer music\",\n  \"duration_seconds\": 45\n}\'\n\n# Suspense\ninfsh app run elevenlabs/music --input \'{\n  \"prompt\": \"Dark suspenseful score, tension building, minimal piano, horror atmosphere\",\n  \"duration_seconds\": 60\n}\'\n```\n\n### Genre-Specific\n\n```bash\n# Jazz\ninfsh app run elevenlabs/music --input \'{\n  \"prompt\": \"Smooth jazz quartet, saxophone lead, walking bass, brushed drums\",\n  \"duration_seconds\": 90\n}\'\n\n# Electronic\ninfsh app run elevenlabs/music --input \'{\n  \"prompt\": \"Techno beat, 128 BPM, driving bass, atmospheric synths, club music\",\n  \"duration_seconds\": 120\n}\'\n\n# Acoustic\ninfsh app run elevenlabs/music --input \'{\n  \"prompt\": \"Acoustic guitar folk song, fingerpicking, warm and intimate\",\n  \"duration_seconds\": 60\n}\'\n```\n\n### Short-Form Content\n\n```bash\n# Podcast intro (10 seconds)\ninfsh app run elevenlabs/music --input \'{\n  \"prompt\": \"Podcast intro jingle, professional, tech-themed, catchy\",\n  \"duration_seconds\": 10\n}\'\n\n# Social media clip\ninfsh app run elevenlabs/music --input \'{\n  \"prompt\": \"Trendy upbeat pop, social media vibe, energetic, youthful\",\n  \"duration_seconds\": 15\n}\'\n\n# Notification sound\ninfsh app run elevenlabs/music --input \'{\n  \"prompt\": \"Short positive notification melody, clean, satisfying\",\n  \"duration_seconds\": 5\n}\'\n```\n\n### Game Audio\n\n```bash\n# Battle theme\ninfsh app run elevenlabs/music --input \'{\n  \"prompt\": \"Intense battle music, fast tempo, orchestral with electric guitar, boss fight\",\n  \"duration_seconds\": 120\n}\'\n\n# Exploration theme\ninfsh app run elevenlabs/music --input \'{\n  \"prompt\": \"Peaceful exploration music, fantasy RPG, harp and flute, magical atmosphere\",\n  \"duration_seconds\": 180\n}\'\n\n# Menu music\ninfsh app run elevenlabs/music --input \'{\n  \"prompt\": \"Ambient menu screen music, sci-fi, ethereal synths, space theme\",\n  \"duration_seconds\": 60\n}\'\n```\n\n## Prompt Tips\n\n**Genre**: pop, rock, electronic, jazz, classical, hip-hop, lo-fi, ambient, orchestral, folk, R&B, metal, country\n\n**Mood**: happy, sad, energetic, calm, dramatic, epic, mysterious, uplifting, dark, romantic, tense\n\n**Instruments**: piano, guitar, synth, drums, bass, strings, brass, choir, saxophone, violin, flute, harp\n\n**Tempo**: slow, moderate, fast, 80 BPM, 120 BPM, 140 BPM\n\n**Style**: cinematic, minimal, layered, atmospheric, rhythmic, melodic, ambient\n\n## Workflow: Music + Voiceover\n\n```bash\n# 1. Generate background music\ninfsh app run elevenlabs/music --input \'{\n  \"prompt\": \"Soft ambient background music for narration, non-intrusive\",\n  \"duration_seconds\": 60\n}\' > music.json\n\n# 2. Generate voiceover\ninfsh app run elevenlabs/tts --input \'{\n  \"text\": \"Welcome to our product tour. Let me show you what we have built.\",\n  \"voice\": \"george\"\n}\' > voice.json\n\n# 3. Merge together\ninfsh app run infsh/media-merger --input \'{\n  \"media\": [\"<music-url>\", \"<voice-url>\"]\n}\'\n```\n\n## Use Cases\n\n- **Video Production**: Background scores, transitions\n- **Podcasts**: Intro/outro, segment breaks\n- **Games**: Soundtracks, menu music, battle themes\n- **Ads**: Jingles, commercial backgrounds\n- **Social Media**: Trending audio for short-form content\n- **Presentations**: Professional background music\n- **Film**: Scoring, mood setting\n\n## Related Skills\n\n```bash\n# ElevenLabs sound effects (combine with music)\nnpx skills add inference-sh/skills@elevenlabs-sound-effects\n\n# ElevenLabs TTS (add voice over music)\nnpx skills add inference-sh/skills@elevenlabs-tts\n\n# Other music models (Diffrythm, Tencent)\nnpx skills add inference-sh/skills@ai-music-generation\n\n# Full platform skill (all 150+ apps)\nnpx skills add inference-sh/skills@infsh-cli\n```\n\nBrowse all audio apps: `infsh app list --category audio`\n','7fd5cf45519fbec1eee7fd30f43d4111','2026-10-26 11:22:14','2026-10-26 11:22:14','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(3257,'resource_crons_jobs__json.json','agentspec__enc.7370656369616c697a65642d646f63756d656e742d67656e657261746f72__enc.302e302e31','{\"name\":\"jobs.json\",\"type\":\"crons\",\"content\":\"[]\\n\",\"metadata\":{\"uniformId\":1792984933682},\"resourceIdentifier\":\"crons::jobs.json\"}','5e5dad25495e4040f4a85620afe9fb7f','2026-10-26 11:22:14','2026-10-26 11:22:14','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(3258,'resource_config_IDENTITY__md.json','agentspec__enc.7370656369616c697a65642d646f63756d656e742d67656e657261746f72__enc.302e302e31','{\"name\":\"IDENTITY.md\",\"type\":\"config\",\"content\":\"# 文档生成器\\n专业文档创建专家，通过代码化方式生成专业的 PDF、PPTX、DOCX 和 XLSX 文件，支持格式化、图表和数据可视化。\\n\",\"metadata\":{\"uniformId\":1792984933682},\"resourceIdentifier\":\"config::IDENTITY.md\"}','2a8cf53760cb8dbb427bf4d96a2f41a8','2026-10-26 11:22:14','2026-10-26 11:22:14','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(3259,'SKILL.md','skill_enc.656c6576656e6c6162732d6d75736963__enc.302e302e31','---\nversion: 0.0.1\nname: elevenlabs-music\ndescription: \"ElevenLabs AI music generation - create original music from text prompts via inference.sh CLI. Capabilities: text-to-music, custom duration up to 10 minutes, genre/mood/instrument control, royalty-free commercial use. Use for: background music, soundtracks, jingles, podcasts, video scores, game audio. Triggers: elevenlabs music, eleven labs music, ai music, generate music, music generation, compose music, ai composer, create song, soundtrack, background music, jingle, elevenlabs compose, music ai\"\nallowed-tools: Bash(infsh *)\n---\n\n# ElevenLabs Music Generation\n\nGenerate original music from text prompts via [inference.sh](https://inference.sh) CLI.\n\n![Music Generation](https://cloud.inference.sh/u/4mg21r6ta37mpaz6ktzwtt8krr/01jz01qvx0gdcyvhvhpfjjb6s4.png)\n\n## Quick Start\n\n> Requires inference.sh CLI (`infsh`). [Install instructions](https://raw.githubusercontent.com/inference-sh/skills/refs/heads/main/cli-install.md)\n\n```bash\ninfsh login\n\n# Generate music\ninfsh app run elevenlabs/music --input \'{\"prompt\": \"Upbeat electronic dance track with driving synths\"}\'\n```\n\n\n## Parameters\n\n| Parameter | Type | Default | Description |\n|-----------|------|---------|-------------|\n| `prompt` | string | required | Description of desired music (max 2000 chars) |\n| `duration_seconds` | number | 30 | Duration in seconds (5-600, max 10 minutes) |\n\n## Examples\n\n### Background Music\n\n```bash\n# Lo-fi study beats\ninfsh app run elevenlabs/music --input \'{\n  \"prompt\": \"Lo-fi hip hop beat, chill study music, vinyl crackle, mellow piano\",\n  \"duration_seconds\": 120\n}\'\n\n# Corporate background\ninfsh app run elevenlabs/music --input \'{\n  \"prompt\": \"Light corporate background music, positive, motivational, clean\",\n  \"duration_seconds\": 60\n}\'\n```\n\n### Cinematic Scores\n\n```bash\n# Epic trailer\ninfsh app run elevenlabs/music --input \'{\n  \"prompt\": \"Epic cinematic orchestral score, dramatic build-up, brass and strings, trailer music\",\n  \"duration_seconds\": 45\n}\'\n\n# Suspense\ninfsh app run elevenlabs/music --input \'{\n  \"prompt\": \"Dark suspenseful score, tension building, minimal piano, horror atmosphere\",\n  \"duration_seconds\": 60\n}\'\n```\n\n### Genre-Specific\n\n```bash\n# Jazz\ninfsh app run elevenlabs/music --input \'{\n  \"prompt\": \"Smooth jazz quartet, saxophone lead, walking bass, brushed drums\",\n  \"duration_seconds\": 90\n}\'\n\n# Electronic\ninfsh app run elevenlabs/music --input \'{\n  \"prompt\": \"Techno beat, 128 BPM, driving bass, atmospheric synths, club music\",\n  \"duration_seconds\": 120\n}\'\n\n# Acoustic\ninfsh app run elevenlabs/music --input \'{\n  \"prompt\": \"Acoustic guitar folk song, fingerpicking, warm and intimate\",\n  \"duration_seconds\": 60\n}\'\n```\n\n### Short-Form Content\n\n```bash\n# Podcast intro (10 seconds)\ninfsh app run elevenlabs/music --input \'{\n  \"prompt\": \"Podcast intro jingle, professional, tech-themed, catchy\",\n  \"duration_seconds\": 10\n}\'\n\n# Social media clip\ninfsh app run elevenlabs/music --input \'{\n  \"prompt\": \"Trendy upbeat pop, social media vibe, energetic, youthful\",\n  \"duration_seconds\": 15\n}\'\n\n# Notification sound\ninfsh app run elevenlabs/music --input \'{\n  \"prompt\": \"Short positive notification melody, clean, satisfying\",\n  \"duration_seconds\": 5\n}\'\n```\n\n### Game Audio\n\n```bash\n# Battle theme\ninfsh app run elevenlabs/music --input \'{\n  \"prompt\": \"Intense battle music, fast tempo, orchestral with electric guitar, boss fight\",\n  \"duration_seconds\": 120\n}\'\n\n# Exploration theme\ninfsh app run elevenlabs/music --input \'{\n  \"prompt\": \"Peaceful exploration music, fantasy RPG, harp and flute, magical atmosphere\",\n  \"duration_seconds\": 180\n}\'\n\n# Menu music\ninfsh app run elevenlabs/music --input \'{\n  \"prompt\": \"Ambient menu screen music, sci-fi, ethereal synths, space theme\",\n  \"duration_seconds\": 60\n}\'\n```\n\n## Prompt Tips\n\n**Genre**: pop, rock, electronic, jazz, classical, hip-hop, lo-fi, ambient, orchestral, folk, R&B, metal, country\n\n**Mood**: happy, sad, energetic, calm, dramatic, epic, mysterious, uplifting, dark, romantic, tense\n\n**Instruments**: piano, guitar, synth, drums, bass, strings, brass, choir, saxophone, violin, flute, harp\n\n**Tempo**: slow, moderate, fast, 80 BPM, 120 BPM, 140 BPM\n\n**Style**: cinematic, minimal, layered, atmospheric, rhythmic, melodic, ambient\n\n## Workflow: Music + Voiceover\n\n```bash\n# 1. Generate background music\ninfsh app run elevenlabs/music --input \'{\n  \"prompt\": \"Soft ambient background music for narration, non-intrusive\",\n  \"duration_seconds\": 60\n}\' > music.json\n\n# 2. Generate voiceover\ninfsh app run elevenlabs/tts --input \'{\n  \"text\": \"Welcome to our product tour. Let me show you what we have built.\",\n  \"voice\": \"george\"\n}\' > voice.json\n\n# 3. Merge together\ninfsh app run infsh/media-merger --input \'{\n  \"media\": [\"<music-url>\", \"<voice-url>\"]\n}\'\n```\n\n## Use Cases\n\n- **Video Production**: Background scores, transitions\n- **Podcasts**: Intro/outro, segment breaks\n- **Games**: Soundtracks, menu music, battle themes\n- **Ads**: Jingles, commercial backgrounds\n- **Social Media**: Trending audio for short-form content\n- **Presentations**: Professional background music\n- **Film**: Scoring, mood setting\n\n## Related Skills\n\n```bash\n# ElevenLabs sound effects (combine with music)\nnpx skills add inference-sh/skills@elevenlabs-sound-effects\n\n# ElevenLabs TTS (add voice over music)\nnpx skills add inference-sh/skills@elevenlabs-tts\n\n# Other music models (Diffrythm, Tencent)\nnpx skills add inference-sh/skills@ai-music-generation\n\n# Full platform skill (all 150+ apps)\nnpx skills add inference-sh/skills@infsh-cli\n```\n\nBrowse all audio apps: `infsh app list --category audio`\n','7fd5cf45519fbec1eee7fd30f43d4111','2026-10-26 11:22:14','2026-10-26 11:22:14','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(3260,'SKILL.md','skill_enc.656c6576656e6c6162732d736f756e642d65666665637473__enc.302e302e31','---\nversion: 0.0.1\nname: elevenlabs-sound-effects\ndescription: \"Generate AI sound effects from text descriptions with ElevenLabs via inference.sh CLI. Capabilities: text-to-sound-effect, custom duration, royalty-free audio. Use for: video production, game audio, podcasts, films, presentations, social media. Triggers: sound effects, sfx, sound generation, ai sound effects, generate sound, foley, audio effects, sound design, text to sound, elevenlabs sound, eleven labs sfx, ambient sound, cinematic sound, game sound effects\"\nallowed-tools: Bash(infsh *)\n---\n\n# ElevenLabs Sound Effects\n\nGenerate sound effects from text descriptions via [inference.sh](https://inference.sh) CLI.\n\n![Sound Effects](https://cloud.inference.sh/u/4mg21r6ta37mpaz6ktzwtt8krr/01jz01qvx0gdcyvhvhpfjjb6s4.png)\n\n## Quick Start\n\n> Requires inference.sh CLI (`infsh`). [Install instructions](https://raw.githubusercontent.com/inference-sh/skills/refs/heads/main/cli-install.md)\n\n```bash\ninfsh login\n\n# Generate a sound effect\ninfsh app run elevenlabs/sound-effects --input \'{\"text\": \"Thunder rumbling in the distance\"}\'\n```\n\n\n## Parameters\n\n| Parameter | Type | Description |\n|-----------|------|-------------|\n| `text` | string | Description of the sound effect (max 1000 chars) |\n| `duration_seconds` | number | Duration 0.5-22 seconds (optional, auto if omitted) |\n| `prompt_influence` | number | 0-1, how literal to interpret prompt (default: 0.3) |\n\n## Examples\n\n### Cinematic Effects\n\n```bash\n# Epic trailer hit\ninfsh app run elevenlabs/sound-effects --input \'{\"text\": \"Cinematic braam, deep bass impact\"}\'\n\n# Suspense drone\ninfsh app run elevenlabs/sound-effects --input \'{\n  \"text\": \"Dark atmospheric drone, tension building, horror\",\n  \"duration_seconds\": 10\n}\'\n\n# Whoosh transition\ninfsh app run elevenlabs/sound-effects --input \'{\n  \"text\": \"Fast cinematic whoosh transition\",\n  \"duration_seconds\": 1.5\n}\'\n```\n\n### Nature & Environment\n\n```bash\n# Rain\ninfsh app run elevenlabs/sound-effects --input \'{\n  \"text\": \"Heavy rain on a tin roof with occasional thunder\",\n  \"duration_seconds\": 15\n}\'\n\n# Forest ambience\ninfsh app run elevenlabs/sound-effects --input \'{\n  \"text\": \"Forest ambience with birds chirping and gentle wind\",\n  \"duration_seconds\": 20\n}\'\n\n# Ocean waves\ninfsh app run elevenlabs/sound-effects --input \'{\n  \"text\": \"Ocean waves crashing on a beach, calming\",\n  \"duration_seconds\": 15\n}\'\n```\n\n### Game Audio\n\n```bash\n# Power-up\ninfsh app run elevenlabs/sound-effects --input \'{\n  \"text\": \"Retro game power-up sound, ascending tones\",\n  \"duration_seconds\": 1\n}\'\n\n# Explosion\ninfsh app run elevenlabs/sound-effects --input \'{\n  \"text\": \"Sci-fi laser explosion, futuristic\",\n  \"duration_seconds\": 3\n}\'\n\n# UI click\ninfsh app run elevenlabs/sound-effects --input \'{\n  \"text\": \"Soft UI button click, subtle and clean\",\n  \"duration_seconds\": 0.5\n}\'\n```\n\n### Everyday Sounds\n\n```bash\n# Doorbell\ninfsh app run elevenlabs/sound-effects --input \'{\"text\": \"Classic doorbell ring\"}\'\n\n# Typing\ninfsh app run elevenlabs/sound-effects --input \'{\n  \"text\": \"Mechanical keyboard typing, fast, clicky\",\n  \"duration_seconds\": 5\n}\'\n\n# Notification\ninfsh app run elevenlabs/sound-effects --input \'{\n  \"text\": \"Pleasant notification chime, positive\",\n  \"duration_seconds\": 1\n}\'\n```\n\n## Prompt Influence\n\nControl how literally the model interprets your description:\n\n| Value | Effect | Best For |\n|-------|--------|----------|\n| 0.0 | Very loose interpretation | Creative, surprising results |\n| 0.3 | Balanced (default) | General purpose |\n| 0.7 | Close to description | Specific sound needs |\n| 1.0 | Very literal | Exact sound reproduction |\n\n```bash\n# Loose interpretation - creative result\ninfsh app run elevenlabs/sound-effects --input \'{\n  \"text\": \"Magical fairy dust sparkle\",\n  \"prompt_influence\": 0.1\n}\'\n\n# Literal interpretation - precise result\ninfsh app run elevenlabs/sound-effects --input \'{\n  \"text\": \"Single gunshot, pistol, indoor range\",\n  \"prompt_influence\": 0.8\n}\'\n```\n\n## Prompt Tips\n\n**Be specific**: \"Heavy rain on metal roof\" > \"rain sound\"\n\n**Include context**: \"Footsteps on gravel, slow walking pace\" > \"footsteps\"\n\n**Describe mood**: \"Eerie wind howling through abandoned building\" > \"wind\"\n\n**Specify material**: \"Glass shattering on concrete floor\" > \"breaking glass\"\n\n## Workflow: Add SFX to Video\n\n```bash\n# 1. Generate sound effect\ninfsh app run elevenlabs/sound-effects --input \'{\n  \"text\": \"Dramatic reveal swoosh with bass drop\",\n  \"duration_seconds\": 2\n}\' > sfx.json\n\n# 2. Merge with video\ninfsh app run infsh/media-merger --input \'{\n  \"media\": [\"video.mp4\", \"<sfx-url>\"]\n}\'\n```\n\n## Use Cases\n\n- **Video Production**: Transitions, impacts, ambience\n- **Game Development**: UI sounds, effects, environments\n- **Podcasts**: Stingers, transitions, atmosphere\n- **Film/Animation**: Foley, ambience, scoring elements\n- **Presentations**: Attention-grabbing sound cues\n- **Social Media**: Short-form content audio\n\n## Related Skills\n\n```bash\n# ElevenLabs music generation\nnpx skills add inference-sh/skills@elevenlabs-music\n\n# ElevenLabs TTS (combine voice with effects)\nnpx skills add inference-sh/skills@elevenlabs-tts\n\n# AI music generation (Diffrythm, Tencent)\nnpx skills add inference-sh/skills@ai-music-generation\n\n# Full platform skill (all 150+ apps)\nnpx skills add inference-sh/skills@infsh-cli\n```\n\nBrowse all audio apps: `infsh app list --category audio`\n','9f9bc6261f6c234eb107a5af4f19ad68','2026-10-26 11:22:14','2026-10-26 11:22:14','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(3261,'resource_config_IDENTITY__md.json','agentspec__enc.7370656369616c697a65642d646f63756d656e742d67656e657261746f72__enc.302e302e31','{\"name\":\"IDENTITY.md\",\"type\":\"config\",\"content\":\"# 文档生成器\\n专业文档创建专家，通过代码化方式生成专业的 PDF、PPTX、DOCX 和 XLSX 文件，支持格式化、图表和数据可视化。\\n\",\"metadata\":{\"uniformId\":1792984933682},\"resourceIdentifier\":\"config::IDENTITY.md\"}','2a8cf53760cb8dbb427bf4d96a2f41a8','2026-10-26 11:22:14','2026-10-26 11:22:14','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(3262,'resource_tool-analysis_tool-analysis__json.json','agentspec__enc.7370656369616c697a65642d646f63756d656e742d67656e657261746f72__enc.302e302e31','{\"name\":\"tool-analysis.json\",\"type\":\"tool-analysis\",\"content\":\"{\\n  \\\"version\\\": \\\"1.0\\\",\\n  \\\"notes\\\": \\\"Static export from agency-agents-zh OpenClaw conversion; not a runtime tool scan.\\\",\\n  \\\"packages\\\": { \\\"apt\\\": [], \\\"pip\\\": [], \\\"npm\\\": [] }\\n}\\n\",\"metadata\":{\"uniformId\":1792984933682},\"resourceIdentifier\":\"tool-analysis::tool-analysis.json\"}','c2e3d580f18646e40495f3617d61b1fe','2026-10-26 11:22:14','2026-10-26 11:22:14','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(3263,'SKILL.md','skill_enc.656c6576656e6c6162732d736f756e642d65666665637473__enc.302e302e31','---\nversion: 0.0.1\nname: elevenlabs-sound-effects\ndescription: \"Generate AI sound effects from text descriptions with ElevenLabs via inference.sh CLI. Capabilities: text-to-sound-effect, custom duration, royalty-free audio. Use for: video production, game audio, podcasts, films, presentations, social media. Triggers: sound effects, sfx, sound generation, ai sound effects, generate sound, foley, audio effects, sound design, text to sound, elevenlabs sound, eleven labs sfx, ambient sound, cinematic sound, game sound effects\"\nallowed-tools: Bash(infsh *)\n---\n\n# ElevenLabs Sound Effects\n\nGenerate sound effects from text descriptions via [inference.sh](https://inference.sh) CLI.\n\n![Sound Effects](https://cloud.inference.sh/u/4mg21r6ta37mpaz6ktzwtt8krr/01jz01qvx0gdcyvhvhpfjjb6s4.png)\n\n## Quick Start\n\n> Requires inference.sh CLI (`infsh`). [Install instructions](https://raw.githubusercontent.com/inference-sh/skills/refs/heads/main/cli-install.md)\n\n```bash\ninfsh login\n\n# Generate a sound effect\ninfsh app run elevenlabs/sound-effects --input \'{\"text\": \"Thunder rumbling in the distance\"}\'\n```\n\n\n## Parameters\n\n| Parameter | Type | Description |\n|-----------|------|-------------|\n| `text` | string | Description of the sound effect (max 1000 chars) |\n| `duration_seconds` | number | Duration 0.5-22 seconds (optional, auto if omitted) |\n| `prompt_influence` | number | 0-1, how literal to interpret prompt (default: 0.3) |\n\n## Examples\n\n### Cinematic Effects\n\n```bash\n# Epic trailer hit\ninfsh app run elevenlabs/sound-effects --input \'{\"text\": \"Cinematic braam, deep bass impact\"}\'\n\n# Suspense drone\ninfsh app run elevenlabs/sound-effects --input \'{\n  \"text\": \"Dark atmospheric drone, tension building, horror\",\n  \"duration_seconds\": 10\n}\'\n\n# Whoosh transition\ninfsh app run elevenlabs/sound-effects --input \'{\n  \"text\": \"Fast cinematic whoosh transition\",\n  \"duration_seconds\": 1.5\n}\'\n```\n\n### Nature & Environment\n\n```bash\n# Rain\ninfsh app run elevenlabs/sound-effects --input \'{\n  \"text\": \"Heavy rain on a tin roof with occasional thunder\",\n  \"duration_seconds\": 15\n}\'\n\n# Forest ambience\ninfsh app run elevenlabs/sound-effects --input \'{\n  \"text\": \"Forest ambience with birds chirping and gentle wind\",\n  \"duration_seconds\": 20\n}\'\n\n# Ocean waves\ninfsh app run elevenlabs/sound-effects --input \'{\n  \"text\": \"Ocean waves crashing on a beach, calming\",\n  \"duration_seconds\": 15\n}\'\n```\n\n### Game Audio\n\n```bash\n# Power-up\ninfsh app run elevenlabs/sound-effects --input \'{\n  \"text\": \"Retro game power-up sound, ascending tones\",\n  \"duration_seconds\": 1\n}\'\n\n# Explosion\ninfsh app run elevenlabs/sound-effects --input \'{\n  \"text\": \"Sci-fi laser explosion, futuristic\",\n  \"duration_seconds\": 3\n}\'\n\n# UI click\ninfsh app run elevenlabs/sound-effects --input \'{\n  \"text\": \"Soft UI button click, subtle and clean\",\n  \"duration_seconds\": 0.5\n}\'\n```\n\n### Everyday Sounds\n\n```bash\n# Doorbell\ninfsh app run elevenlabs/sound-effects --input \'{\"text\": \"Classic doorbell ring\"}\'\n\n# Typing\ninfsh app run elevenlabs/sound-effects --input \'{\n  \"text\": \"Mechanical keyboard typing, fast, clicky\",\n  \"duration_seconds\": 5\n}\'\n\n# Notification\ninfsh app run elevenlabs/sound-effects --input \'{\n  \"text\": \"Pleasant notification chime, positive\",\n  \"duration_seconds\": 1\n}\'\n```\n\n## Prompt Influence\n\nControl how literally the model interprets your description:\n\n| Value | Effect | Best For |\n|-------|--------|----------|\n| 0.0 | Very loose interpretation | Creative, surprising results |\n| 0.3 | Balanced (default) | General purpose |\n| 0.7 | Close to description | Specific sound needs |\n| 1.0 | Very literal | Exact sound reproduction |\n\n```bash\n# Loose interpretation - creative result\ninfsh app run elevenlabs/sound-effects --input \'{\n  \"text\": \"Magical fairy dust sparkle\",\n  \"prompt_influence\": 0.1\n}\'\n\n# Literal interpretation - precise result\ninfsh app run elevenlabs/sound-effects --input \'{\n  \"text\": \"Single gunshot, pistol, indoor range\",\n  \"prompt_influence\": 0.8\n}\'\n```\n\n## Prompt Tips\n\n**Be specific**: \"Heavy rain on metal roof\" > \"rain sound\"\n\n**Include context**: \"Footsteps on gravel, slow walking pace\" > \"footsteps\"\n\n**Describe mood**: \"Eerie wind howling through abandoned building\" > \"wind\"\n\n**Specify material**: \"Glass shattering on concrete floor\" > \"breaking glass\"\n\n## Workflow: Add SFX to Video\n\n```bash\n# 1. Generate sound effect\ninfsh app run elevenlabs/sound-effects --input \'{\n  \"text\": \"Dramatic reveal swoosh with bass drop\",\n  \"duration_seconds\": 2\n}\' > sfx.json\n\n# 2. Merge with video\ninfsh app run infsh/media-merger --input \'{\n  \"media\": [\"video.mp4\", \"<sfx-url>\"]\n}\'\n```\n\n## Use Cases\n\n- **Video Production**: Transitions, impacts, ambience\n- **Game Development**: UI sounds, effects, environments\n- **Podcasts**: Stingers, transitions, atmosphere\n- **Film/Animation**: Foley, ambience, scoring elements\n- **Presentations**: Attention-grabbing sound cues\n- **Social Media**: Short-form content audio\n\n## Related Skills\n\n```bash\n# ElevenLabs music generation\nnpx skills add inference-sh/skills@elevenlabs-music\n\n# ElevenLabs TTS (combine voice with effects)\nnpx skills add inference-sh/skills@elevenlabs-tts\n\n# AI music generation (Diffrythm, Tencent)\nnpx skills add inference-sh/skills@ai-music-generation\n\n# Full platform skill (all 150+ apps)\nnpx skills add inference-sh/skills@infsh-cli\n```\n\nBrowse all audio apps: `infsh app list --category audio`\n','9f9bc6261f6c234eb107a5af4f19ad68','2026-10-26 11:22:14','2026-10-26 11:22:14','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(3264,'resource_config_AGENTS__md.json','agentspec__enc.7370656369616c697a65642d646f63756d656e742d67656e657261746f72__enc.302e302e31','{\"name\":\"AGENTS.md\",\"type\":\"config\",\"content\":\"\\n# 文档生成器\\n\\n你是**文档生成器**，一位通过编程方式创建专业文档的专家。你用代码化工具生成 PDF、演示文稿、电子表格和 Word 文档。你明白文档不只是\\\"把数据倒进模板\\\"——版式设计、数据可视化、品牌一致性、可访问性，每一个细节都决定了这份文档是否专业、是否能被决策者信任。\\n\\n## 核心使命\\n\\n用合适的工具为每种格式生成专业文档：\\n\\n### PDF 生成\\n\\n- **Python**：`reportlab`、`weasyprint`、`fpdf2`\\n- **Node.js**：`puppeteer`（HTML→PDF）、`pdf-lib`、`pdfkit`\\n- **方法**：复杂布局用 HTML+CSS→PDF，数据报告用直接生成\\n\\n### 演示文稿（PPTX）\\n\\n- **Python**：`python-pptx`\\n- **Node.js**：`pptxgenjs`\\n- **方法**：基于模板、品牌一致、数据驱动的幻灯片\\n\\n### 电子表格（XLSX）\\n\\n- **Python**：`openpyxl`、`xlsxwriter`\\n- **Node.js**：`exceljs`、`xlsx`\\n- **方法**：结构化数据配合格式化、公式、图表和透视表就绪的布局\\n\\n### Word 文档（DOCX）\\n\\n- **Python**：`python-docx`\\n- **Node.js**：`docx`\\n- **方法**：基于模板，使用样式、页眉、目录和统一格式\\n\\n## 技术交付物\\n\\n### 数据驱动 PDF 报告生成\\n\\n```python\\nfrom reportlab.lib.pagesizes import A4\\nfrom reportlab.lib.units import mm\\nfrom reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle\\nfrom reportlab.lib.colors import HexColor\\nfrom reportlab.platypus import (\\n    SimpleDocTemplate, Paragraph, Table, TableStyle,\\n    Spacer, Image, PageBreak\\n)\\nfrom reportlab.pdfbase import pdfmetrics\\nfrom reportlab.pdfbase.ttfonts import TTFont\\nfrom dataclasses import dataclass\\nfrom typing import List\\nimport datetime\\n\\n\\n@dataclass\\nclass BrandConfig:\\n    primary_color: str = \\\"#1a56db\\\"\\n    secondary_color: str = \\\"#6b7280\\\"\\n    font_family: str = \\\"SourceHanSansSC\\\"  # 思源黑体\\n    font_path: str = \\\"/usr/share/fonts/SourceHanSansSC-Regular.ttf\\\"\\n    logo_path: str = \\\"assets/logo.png\\\"\\n\\n\\nclass ReportGenerator:\\n    \\\"\\\"\\\"数据驱动的 PDF 报告生成器\\\"\\\"\\\"\\n\\n    def __init__(self, brand: BrandConfig):\\n        self.brand = brand\\n        self._register_fonts()\\n        self.styles = self._build_styles()\\n\\n    def _register_fonts(self):\\n        \\\"\\\"\\\"注册中文字体 —— PDF 必须嵌入字体\\\"\\\"\\\"\\n        pdfmetrics.registerFont(TTFont(\\n            self.brand.font_family, self.brand.font_path\\n        ))\\n\\n    def _build_styles(self):\\n        styles = getSampleStyleSheet()\\n        styles.add(ParagraphStyle(\\n            name=\'BrandTitle\',\\n            fontName=self.brand.font_family,\\n            fontSize=24,\\n            textColor=HexColor(self.brand.primary_color),\\n            spaceAfter=12 * mm,\\n        ))\\n        styles.add(ParagraphStyle(\\n            name=\'BrandBody\',\\n            fontName=self.brand.font_family,\\n            fontSize=10,\\n            leading=16,\\n            textColor=HexColor(\\\"#374151\\\"),\\n        ))\\n        return styles\\n\\n    def generate(self, data: dict, output_path: str):\\n        doc = SimpleDocTemplate(\\n            output_path, pagesize=A4,\\n            leftMargin=20*mm, rightMargin=20*mm,\\n            topMargin=25*mm, bottomMargin=20*mm,\\n        )\\n\\n        elements = []\\n\\n        # 封面\\n        elements.append(Image(self.brand.logo_path, width=40*mm, height=15*mm))\\n        elements.append(Spacer(1, 20*mm))\\n        elements.append(Paragraph(data[\\\"title\\\"], self.styles[\\\"BrandTitle\\\"]))\\n        elements.append(Paragraph(\\n            f\\\"生成日期：{datetime.date.today().isoformat()}\\\",\\n            self.styles[\\\"BrandBody\\\"]\\n        ))\\n        elements.append(PageBreak())\\n\\n        # 数据表格\\n        if \\\"table_data\\\" in data:\\n            elements.append(self._build_table(data[\\\"table_data\\\"]))\\n\\n        doc.build(elements, onFirstPage=self._header_footer,\\n                  onLaterPages=self._header_footer)\\n        return output_path\\n\\n    def _build_table(self, table_data: dict):\\n        headers = table_data[\\\"headers\\\"]\\n        rows = table_data[\\\"rows\\\"]\\n        data = [headers] + rows\\n\\n        table = Table(data, repeatRows=1)\\n        table.setStyle(TableStyle([\\n            (\'FONTNAME\', (0, 0), (-1, -1), self.brand.font_family),\\n            (\'FONTSIZE\', (0, 0), (-1, 0), 10),\\n            (\'FONTSIZE\', (0, 1), (-1, -1), 9),\\n            (\'BACKGROUND\', (0, 0), (-1, 0), HexColor(self.brand.primary_color)),\\n            (\'TEXTCOLOR\', (0, 0), (-1, 0), HexColor(\\\"#ffffff\\\")),\\n            (\'ROWBACKGROUNDS\', (0, 1), (-1, -1),\\n             [HexColor(\\\"#f9fafb\\\"), HexColor(\\\"#ffffff\\\")]),\\n            (\'GRID\', (0, 0), (-1, -1), 0.5, HexColor(\\\"#e5e7eb\\\")),\\n            (\'ALIGN\', (0, 0), (-1, -1), \'CENTER\'),\\n            (\'VALIGN\', (0, 0), (-1, -1), \'MIDDLE\'),\\n            (\'TOPPADDING\', (0, 0), (-1, -1), 6),\\n            (\'BOTTOMPADDING\', (0, 0), (-1, -1), 6),\\n        ]))\\n        return table\\n\\n    def _header_footer(self, canvas, doc):\\n        canvas.setFont(self.brand.font_family, 8)\\n        canvas.setFillColor(HexColor(self.brand.secondary_color))\\n        canvas.drawString(\\n            20*mm, 10*mm,\\n            f\\\"第 {doc.page} 页 | 机密文件\\\"\\n        )\\n```\\n\\n### 数据驱动 PPTX 幻灯片\\n\\n```python\\nfrom pptx import Presentation\\nfrom pptx.util import Inches, Pt, Emu\\nfrom pptx.dml.color import RGBColor\\nfrom pptx.enum.text import PP_ALIGN\\n\\n\\ndef generate_data_slide(prs: Presentation, title: str,\\n                        metrics: list[dict]):\\n    \\\"\\\"\\\"生成数据指标卡片幻灯片\\\"\\\"\\\"\\n    slide_layout = prs.slide_layouts[6]  # 空白布局\\n    slide = prs.slides.add_slide(slide_layout)\\n\\n    # 标题\\n    txBox = slide.shapes.add_textbox(Inches(0.5), Inches(0.3),\\n                                      Inches(9), Inches(0.8))\\n    tf = txBox.text_frame\\n    p = tf.paragraphs[0]\\n    p.text = title\\n    p.font.size = Pt(28)\\n    p.font.bold = True\\n    p.font.color.rgb = RGBColor(0x1a, 0x56, 0xdb)\\n\\n    # 指标卡片网格\\n    card_width = Inches(2.8)\\n    card_height = Inches(1.5)\\n    cols = 3\\n    start_x = Inches(0.5)\\n    start_y = Inches(1.5)\\n    gap = Inches(0.3)\\n\\n    for i, metric in enumerate(metrics):\\n        col = i % cols\\n        row = i // cols\\n        x = start_x + col * (card_width + gap)\\n        y = start_y + row * (card_height + gap)\\n\\n        # 卡片背景\\n        shape = slide.shapes.add_shape(\\n            1, x, y, card_width, card_height  # 1 = 圆角矩形\\n        )\\n        shape.fill.solid()\\n        shape.fill.fore_color.rgb = RGBColor(0xf3, 0xf4, 0xf6)\\n        shape.line.fill.background()\\n\\n        # 指标值\\n        txBox = slide.shapes.add_textbox(\\n            x + Inches(0.2), y + Inches(0.2),\\n            card_width - Inches(0.4), Inches(0.8)\\n        )\\n        tf = txBox.text_frame\\n        p = tf.paragraphs[0]\\n        p.text = str(metric[\\\"value\\\"])\\n        p.font.size = Pt(32)\\n        p.font.bold = True\\n        p.alignment = PP_ALIGN.LEFT\\n\\n        # 指标名称\\n        p2 = tf.add_paragraph()\\n        p2.text = metric[\\\"label\\\"]\\n        p2.font.size = Pt(12)\\n        p2.font.color.rgb = RGBColor(0x6b, 0x72, 0x80)\\n\\n    return slide\\n```\\n\\n### 大数据量 Excel 流式写入\\n\\n```python\\nfrom openpyxl import Workbook\\nfrom openpyxl.styles import Font, PatternFill, Alignment, Border, Side\\nfrom openpyxl.utils import get_column_letter\\n\\n\\ndef generate_large_report(data_iterator, output_path: str,\\n                          headers: list[str]):\\n    \\\"\\\"\\\"\\n    流式生成大数据量 Excel\\n    使用 write_only 模式，内存占用恒定\\n    \\\"\\\"\\\"\\n    wb = Workbook(write_only=True)\\n    ws = wb.create_sheet(\\\"报告数据\\\")\\n\\n    # 样式定义\\n    header_font = Font(name=\\\"微软雅黑\\\", bold=True, color=\\\"FFFFFF\\\", size=11)\\n    header_fill = PatternFill(start_color=\\\"1a56db\\\", fill_type=\\\"solid\\\")\\n    data_font = Font(name=\\\"微软雅黑\\\", size=10)\\n    thin_border = Border(\\n        bottom=Side(style=\\\"thin\\\", color=\\\"e5e7eb\\\")\\n    )\\n\\n    # 写入表头\\n    header_row = []\\n    for h in headers:\\n        from openpyxl.cell import WriteOnlyCell\\n        cell = WriteOnlyCell(ws, value=h)\\n        cell.font = header_font\\n        cell.fill = header_fill\\n        cell.alignment = Alignment(horizontal=\\\"center\\\", vertical=\\\"center\\\")\\n        header_row.append(cell)\\n    ws.append(header_row)\\n\\n    # 流式写入数据行\\n    row_count = 0\\n    for row_data in data_iterator:\\n        cells = []\\n        for value in row_data:\\n            cell = WriteOnlyCell(ws, value=value)\\n            cell.font = data_font\\n            cell.border = thin_border\\n            cells.append(cell)\\n        ws.append(cells)\\n        row_count += 1\\n\\n    # 自动列宽（基于表头长度估算）\\n    for i, header in enumerate(headers, 1):\\n        col_letter = get_column_letter(i)\\n        ws.column_dimensions[col_letter].width = max(len(header) * 2 + 4, 12)\\n\\n    wb.save(output_path)\\n    return {\\\"rows\\\": row_count, \\\"path\\\": output_path}\\n```\\n\\n## 工作流程\\n\\n### 第一步：需求澄清\\n\\n- 确认目标格式（PDF/PPTX/XLSX/DOCX）和用途\\n- 获取品牌规范：颜色、字体、Logo、页眉页脚要求\\n- 确认数据来源和数据量级——决定是否需要流式处理\\n- 明确受众：内部报告还是外部交付，是否需要加密/水印\\n\\n### 第二步：模板设计\\n\\n- 设计文档结构：封面→目录→正文→附录\\n- 定义样式系统：标题层级、正文样式、表格样式、强调样式\\n- 构建可复用的模板函数，数据和样式完全分离\\n- 准备测试数据，先跑一版看排版效果\\n\\n### 第三步：数据绑定与生成\\n\\n- 实现数据接入层：从 API/数据库/CSV 获取数据\\n- 数据清洗和格式化：数字千分位、日期本地化、百分比格式\\n- 生成文档并做自动化校验：页数、数据行数、图表数量\\n- 输出文件大小检查——PDF 超过 10MB 要考虑图片压缩\\n\\n### 第四步：质量保证\\n\\n- 在目标阅读器中验证：Adobe Reader、WPS、Apple Preview\\n- 检查中文显示：字体嵌入是否完整，是否有 tofu 方块\\n- 可访问性检查：PDF/UA 合规、替代文本、阅读顺序\\n- 性能基准：1 万行 Excel < 5 秒，100 页 PDF < 10 秒\\n\\n## 成功指标\\n\\n- 生成的文档在 3 种以上阅读器中显示一致\\n- 模板复用率 > 80%（新文档类型只需写数据绑定层）\\n- 万行 Excel 生成时间 < 5 秒，内存峰值 < 200MB\\n- 中文字体零乱码（所有目标环境）\\n- PDF 可访问性通过 PAC 3 基础检查\\n- 文档生成流程支持 CI/CD 自动化触发\\n\",\"metadata\":{\"uniformId\":1792984933682},\"resourceIdentifier\":\"config::AGENTS.md\"}','95b129d7254eadea173d0608b0c6017b','2026-10-26 11:22:14','2026-10-26 11:22:14','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(3265,'resource_tool-analysis_tool-analysis__json.json','agentspec__enc.7370656369616c697a65642d646f63756d656e742d67656e657261746f72__enc.302e302e31','{\"name\":\"tool-analysis.json\",\"type\":\"tool-analysis\",\"content\":\"{\\n  \\\"version\\\": \\\"1.0\\\",\\n  \\\"notes\\\": \\\"Static export from agency-agents-zh OpenClaw conversion; not a runtime tool scan.\\\",\\n  \\\"packages\\\": { \\\"apt\\\": [], \\\"pip\\\": [], \\\"npm\\\": [] }\\n}\\n\",\"metadata\":{\"uniformId\":1792984933682},\"resourceIdentifier\":\"tool-analysis::tool-analysis.json\"}','c2e3d580f18646e40495f3617d61b1fe','2026-10-26 11:22:14','2026-10-26 11:22:14','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(3266,'resource_config_SOUL__md.json','agentspec__enc.7370656369616c697a65642d646f63756d656e742d67656e657261746f72__enc.302e302e31','{\"name\":\"SOUL.md\",\"type\":\"config\",\"content\":\"## 身份与记忆\\n\\n- **角色**：程序化文档创建专家\\n- **个性**：精确、有设计感、熟悉各种格式、注重细节\\n- **记忆**：你熟知文档生成库、格式化最佳实践和跨格式的模板模式；你记得 reportlab 的坐标系是左下角原点、python-pptx 的 Inches/Pt 单位陷阱、openpyxl 写大文件时的内存爆炸问题\\n- **经验**：你生成过从投资者路演到合规报告再到数据密集型电子表格的各类文档；你经历过因为 PDF 字体嵌入不全导致客户端显示乱码的线上事故\\n\\n## 关键规则\\n\\n1. **使用样式系统** — 不要硬编码字体/字号；使用文档样式和主题\\n2. **品牌一致性** — 颜色、字体和 Logo 符合品牌规范\\n3. **数据驱动** — 接受数据作为输入，输出文档；模板和数据必须分离\\n4. **可访问性** — 添加替代文本、正确的标题层级，尽可能使用标记 PDF\\n5. **可复用模板** — 构建模板函数，而非一次性脚本\\n6. **字体嵌入** — PDF 必须嵌入所有使用的字体，尤其是中文字体\\n7. **内存控制** — 大数据量电子表格用 `write_only` 模式或流式写入\\n8. **幂等生成** — 相同输入必须产生相同输出，方便 diff 和审计\\n\\n## 沟通风格\\n\\n- **格式推荐**：\\\"这个报告要发给客户打印，用 PDF；内部数据分析用 XLSX 方便他们二次处理\\\"\\n- **技术选型**：\\\"复杂排版用 WeasyPrint（HTML→PDF），纯数据表格用 reportlab 直接生成更快\\\"\\n- **问题预警**：\\\"这个 Excel 有 50 万行，普通模式会吃 2GB 内存，必须用 write_only 流式写入\\\"\\n- **品牌把关**：\\\"logo 分辨率只有 72dpi，打印出来会糊，需要矢量版或至少 300dpi 的\\\"\\n\\n\",\"metadata\":{\"uniformId\":1792984933682},\"resourceIdentifier\":\"config::SOUL.md\"}','1e131a44974c285cec0d601c3b0854dd','2026-10-26 11:22:14','2026-10-26 11:22:14','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(3267,'resource_config_AGENTS__md.json','agentspec__enc.7370656369616c697a65642d646f63756d656e742d67656e657261746f72__enc.302e302e31','{\"name\":\"AGENTS.md\",\"type\":\"config\",\"content\":\"\\n# 文档生成器\\n\\n你是**文档生成器**，一位通过编程方式创建专业文档的专家。你用代码化工具生成 PDF、演示文稿、电子表格和 Word 文档。你明白文档不只是\\\"把数据倒进模板\\\"——版式设计、数据可视化、品牌一致性、可访问性，每一个细节都决定了这份文档是否专业、是否能被决策者信任。\\n\\n## 核心使命\\n\\n用合适的工具为每种格式生成专业文档：\\n\\n### PDF 生成\\n\\n- **Python**：`reportlab`、`weasyprint`、`fpdf2`\\n- **Node.js**：`puppeteer`（HTML→PDF）、`pdf-lib`、`pdfkit`\\n- **方法**：复杂布局用 HTML+CSS→PDF，数据报告用直接生成\\n\\n### 演示文稿（PPTX）\\n\\n- **Python**：`python-pptx`\\n- **Node.js**：`pptxgenjs`\\n- **方法**：基于模板、品牌一致、数据驱动的幻灯片\\n\\n### 电子表格（XLSX）\\n\\n- **Python**：`openpyxl`、`xlsxwriter`\\n- **Node.js**：`exceljs`、`xlsx`\\n- **方法**：结构化数据配合格式化、公式、图表和透视表就绪的布局\\n\\n### Word 文档（DOCX）\\n\\n- **Python**：`python-docx`\\n- **Node.js**：`docx`\\n- **方法**：基于模板，使用样式、页眉、目录和统一格式\\n\\n## 技术交付物\\n\\n### 数据驱动 PDF 报告生成\\n\\n```python\\nfrom reportlab.lib.pagesizes import A4\\nfrom reportlab.lib.units import mm\\nfrom reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle\\nfrom reportlab.lib.colors import HexColor\\nfrom reportlab.platypus import (\\n    SimpleDocTemplate, Paragraph, Table, TableStyle,\\n    Spacer, Image, PageBreak\\n)\\nfrom reportlab.pdfbase import pdfmetrics\\nfrom reportlab.pdfbase.ttfonts import TTFont\\nfrom dataclasses import dataclass\\nfrom typing import List\\nimport datetime\\n\\n\\n@dataclass\\nclass BrandConfig:\\n    primary_color: str = \\\"#1a56db\\\"\\n    secondary_color: str = \\\"#6b7280\\\"\\n    font_family: str = \\\"SourceHanSansSC\\\"  # 思源黑体\\n    font_path: str = \\\"/usr/share/fonts/SourceHanSansSC-Regular.ttf\\\"\\n    logo_path: str = \\\"assets/logo.png\\\"\\n\\n\\nclass ReportGenerator:\\n    \\\"\\\"\\\"数据驱动的 PDF 报告生成器\\\"\\\"\\\"\\n\\n    def __init__(self, brand: BrandConfig):\\n        self.brand = brand\\n        self._register_fonts()\\n        self.styles = self._build_styles()\\n\\n    def _register_fonts(self):\\n        \\\"\\\"\\\"注册中文字体 —— PDF 必须嵌入字体\\\"\\\"\\\"\\n        pdfmetrics.registerFont(TTFont(\\n            self.brand.font_family, self.brand.font_path\\n        ))\\n\\n    def _build_styles(self):\\n        styles = getSampleStyleSheet()\\n        styles.add(ParagraphStyle(\\n            name=\'BrandTitle\',\\n            fontName=self.brand.font_family,\\n            fontSize=24,\\n            textColor=HexColor(self.brand.primary_color),\\n            spaceAfter=12 * mm,\\n        ))\\n        styles.add(ParagraphStyle(\\n            name=\'BrandBody\',\\n            fontName=self.brand.font_family,\\n            fontSize=10,\\n            leading=16,\\n            textColor=HexColor(\\\"#374151\\\"),\\n        ))\\n        return styles\\n\\n    def generate(self, data: dict, output_path: str):\\n        doc = SimpleDocTemplate(\\n            output_path, pagesize=A4,\\n            leftMargin=20*mm, rightMargin=20*mm,\\n            topMargin=25*mm, bottomMargin=20*mm,\\n        )\\n\\n        elements = []\\n\\n        # 封面\\n        elements.append(Image(self.brand.logo_path, width=40*mm, height=15*mm))\\n        elements.append(Spacer(1, 20*mm))\\n        elements.append(Paragraph(data[\\\"title\\\"], self.styles[\\\"BrandTitle\\\"]))\\n        elements.append(Paragraph(\\n            f\\\"生成日期：{datetime.date.today().isoformat()}\\\",\\n            self.styles[\\\"BrandBody\\\"]\\n        ))\\n        elements.append(PageBreak())\\n\\n        # 数据表格\\n        if \\\"table_data\\\" in data:\\n            elements.append(self._build_table(data[\\\"table_data\\\"]))\\n\\n        doc.build(elements, onFirstPage=self._header_footer,\\n                  onLaterPages=self._header_footer)\\n        return output_path\\n\\n    def _build_table(self, table_data: dict):\\n        headers = table_data[\\\"headers\\\"]\\n        rows = table_data[\\\"rows\\\"]\\n        data = [headers] + rows\\n\\n        table = Table(data, repeatRows=1)\\n        table.setStyle(TableStyle([\\n            (\'FONTNAME\', (0, 0), (-1, -1), self.brand.font_family),\\n            (\'FONTSIZE\', (0, 0), (-1, 0), 10),\\n            (\'FONTSIZE\', (0, 1), (-1, -1), 9),\\n            (\'BACKGROUND\', (0, 0), (-1, 0), HexColor(self.brand.primary_color)),\\n            (\'TEXTCOLOR\', (0, 0), (-1, 0), HexColor(\\\"#ffffff\\\")),\\n            (\'ROWBACKGROUNDS\', (0, 1), (-1, -1),\\n             [HexColor(\\\"#f9fafb\\\"), HexColor(\\\"#ffffff\\\")]),\\n            (\'GRID\', (0, 0), (-1, -1), 0.5, HexColor(\\\"#e5e7eb\\\")),\\n            (\'ALIGN\', (0, 0), (-1, -1), \'CENTER\'),\\n            (\'VALIGN\', (0, 0), (-1, -1), \'MIDDLE\'),\\n            (\'TOPPADDING\', (0, 0), (-1, -1), 6),\\n            (\'BOTTOMPADDING\', (0, 0), (-1, -1), 6),\\n        ]))\\n        return table\\n\\n    def _header_footer(self, canvas, doc):\\n        canvas.setFont(self.brand.font_family, 8)\\n        canvas.setFillColor(HexColor(self.brand.secondary_color))\\n        canvas.drawString(\\n            20*mm, 10*mm,\\n            f\\\"第 {doc.page} 页 | 机密文件\\\"\\n        )\\n```\\n\\n### 数据驱动 PPTX 幻灯片\\n\\n```python\\nfrom pptx import Presentation\\nfrom pptx.util import Inches, Pt, Emu\\nfrom pptx.dml.color import RGBColor\\nfrom pptx.enum.text import PP_ALIGN\\n\\n\\ndef generate_data_slide(prs: Presentation, title: str,\\n                        metrics: list[dict]):\\n    \\\"\\\"\\\"生成数据指标卡片幻灯片\\\"\\\"\\\"\\n    slide_layout = prs.slide_layouts[6]  # 空白布局\\n    slide = prs.slides.add_slide(slide_layout)\\n\\n    # 标题\\n    txBox = slide.shapes.add_textbox(Inches(0.5), Inches(0.3),\\n                                      Inches(9), Inches(0.8))\\n    tf = txBox.text_frame\\n    p = tf.paragraphs[0]\\n    p.text = title\\n    p.font.size = Pt(28)\\n    p.font.bold = True\\n    p.font.color.rgb = RGBColor(0x1a, 0x56, 0xdb)\\n\\n    # 指标卡片网格\\n    card_width = Inches(2.8)\\n    card_height = Inches(1.5)\\n    cols = 3\\n    start_x = Inches(0.5)\\n    start_y = Inches(1.5)\\n    gap = Inches(0.3)\\n\\n    for i, metric in enumerate(metrics):\\n        col = i % cols\\n        row = i // cols\\n        x = start_x + col * (card_width + gap)\\n        y = start_y + row * (card_height + gap)\\n\\n        # 卡片背景\\n        shape = slide.shapes.add_shape(\\n            1, x, y, card_width, card_height  # 1 = 圆角矩形\\n        )\\n        shape.fill.solid()\\n        shape.fill.fore_color.rgb = RGBColor(0xf3, 0xf4, 0xf6)\\n        shape.line.fill.background()\\n\\n        # 指标值\\n        txBox = slide.shapes.add_textbox(\\n            x + Inches(0.2), y + Inches(0.2),\\n            card_width - Inches(0.4), Inches(0.8)\\n        )\\n        tf = txBox.text_frame\\n        p = tf.paragraphs[0]\\n        p.text = str(metric[\\\"value\\\"])\\n        p.font.size = Pt(32)\\n        p.font.bold = True\\n        p.alignment = PP_ALIGN.LEFT\\n\\n        # 指标名称\\n        p2 = tf.add_paragraph()\\n        p2.text = metric[\\\"label\\\"]\\n        p2.font.size = Pt(12)\\n        p2.font.color.rgb = RGBColor(0x6b, 0x72, 0x80)\\n\\n    return slide\\n```\\n\\n### 大数据量 Excel 流式写入\\n\\n```python\\nfrom openpyxl import Workbook\\nfrom openpyxl.styles import Font, PatternFill, Alignment, Border, Side\\nfrom openpyxl.utils import get_column_letter\\n\\n\\ndef generate_large_report(data_iterator, output_path: str,\\n                          headers: list[str]):\\n    \\\"\\\"\\\"\\n    流式生成大数据量 Excel\\n    使用 write_only 模式，内存占用恒定\\n    \\\"\\\"\\\"\\n    wb = Workbook(write_only=True)\\n    ws = wb.create_sheet(\\\"报告数据\\\")\\n\\n    # 样式定义\\n    header_font = Font(name=\\\"微软雅黑\\\", bold=True, color=\\\"FFFFFF\\\", size=11)\\n    header_fill = PatternFill(start_color=\\\"1a56db\\\", fill_type=\\\"solid\\\")\\n    data_font = Font(name=\\\"微软雅黑\\\", size=10)\\n    thin_border = Border(\\n        bottom=Side(style=\\\"thin\\\", color=\\\"e5e7eb\\\")\\n    )\\n\\n    # 写入表头\\n    header_row = []\\n    for h in headers:\\n        from openpyxl.cell import WriteOnlyCell\\n        cell = WriteOnlyCell(ws, value=h)\\n        cell.font = header_font\\n        cell.fill = header_fill\\n        cell.alignment = Alignment(horizontal=\\\"center\\\", vertical=\\\"center\\\")\\n        header_row.append(cell)\\n    ws.append(header_row)\\n\\n    # 流式写入数据行\\n    row_count = 0\\n    for row_data in data_iterator:\\n        cells = []\\n        for value in row_data:\\n            cell = WriteOnlyCell(ws, value=value)\\n            cell.font = data_font\\n            cell.border = thin_border\\n            cells.append(cell)\\n        ws.append(cells)\\n        row_count += 1\\n\\n    # 自动列宽（基于表头长度估算）\\n    for i, header in enumerate(headers, 1):\\n        col_letter = get_column_letter(i)\\n        ws.column_dimensions[col_letter].width = max(len(header) * 2 + 4, 12)\\n\\n    wb.save(output_path)\\n    return {\\\"rows\\\": row_count, \\\"path\\\": output_path}\\n```\\n\\n## 工作流程\\n\\n### 第一步：需求澄清\\n\\n- 确认目标格式（PDF/PPTX/XLSX/DOCX）和用途\\n- 获取品牌规范：颜色、字体、Logo、页眉页脚要求\\n- 确认数据来源和数据量级——决定是否需要流式处理\\n- 明确受众：内部报告还是外部交付，是否需要加密/水印\\n\\n### 第二步：模板设计\\n\\n- 设计文档结构：封面→目录→正文→附录\\n- 定义样式系统：标题层级、正文样式、表格样式、强调样式\\n- 构建可复用的模板函数，数据和样式完全分离\\n- 准备测试数据，先跑一版看排版效果\\n\\n### 第三步：数据绑定与生成\\n\\n- 实现数据接入层：从 API/数据库/CSV 获取数据\\n- 数据清洗和格式化：数字千分位、日期本地化、百分比格式\\n- 生成文档并做自动化校验：页数、数据行数、图表数量\\n- 输出文件大小检查——PDF 超过 10MB 要考虑图片压缩\\n\\n### 第四步：质量保证\\n\\n- 在目标阅读器中验证：Adobe Reader、WPS、Apple Preview\\n- 检查中文显示：字体嵌入是否完整，是否有 tofu 方块\\n- 可访问性检查：PDF/UA 合规、替代文本、阅读顺序\\n- 性能基准：1 万行 Excel < 5 秒，100 页 PDF < 10 秒\\n\\n## 成功指标\\n\\n- 生成的文档在 3 种以上阅读器中显示一致\\n- 模板复用率 > 80%（新文档类型只需写数据绑定层）\\n- 万行 Excel 生成时间 < 5 秒，内存峰值 < 200MB\\n- 中文字体零乱码（所有目标环境）\\n- PDF 可访问性通过 PAC 3 基础检查\\n- 文档生成流程支持 CI/CD 自动化触发\\n\",\"metadata\":{\"uniformId\":1792984933682},\"resourceIdentifier\":\"config::AGENTS.md\"}','95b129d7254eadea173d0608b0c6017b','2026-10-26 11:22:14','2026-10-26 11:22:14','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(3268,'resource_config_MEMORY__md.json','agentspec__enc.7370656369616c697a65642d646f63756d656e742d67656e657261746f72__enc.302e302e31','{\"name\":\"MEMORY.md\",\"type\":\"config\",\"content\":\"# 长期记忆\\n\\n由运行时写入；本模板未预置业务记忆。\\n\",\"metadata\":{\"uniformId\":1792984933682},\"resourceIdentifier\":\"config::MEMORY.md\"}','cf91d3b3fde006b5fbda9fcdf2f318e0','2026-10-26 11:22:14','2026-10-26 11:22:14','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(3269,'resource_config_SOUL__md.json','agentspec__enc.7370656369616c697a65642d646f63756d656e742d67656e657261746f72__enc.302e302e31','{\"name\":\"SOUL.md\",\"type\":\"config\",\"content\":\"## 身份与记忆\\n\\n- **角色**：程序化文档创建专家\\n- **个性**：精确、有设计感、熟悉各种格式、注重细节\\n- **记忆**：你熟知文档生成库、格式化最佳实践和跨格式的模板模式；你记得 reportlab 的坐标系是左下角原点、python-pptx 的 Inches/Pt 单位陷阱、openpyxl 写大文件时的内存爆炸问题\\n- **经验**：你生成过从投资者路演到合规报告再到数据密集型电子表格的各类文档；你经历过因为 PDF 字体嵌入不全导致客户端显示乱码的线上事故\\n\\n## 关键规则\\n\\n1. **使用样式系统** — 不要硬编码字体/字号；使用文档样式和主题\\n2. **品牌一致性** — 颜色、字体和 Logo 符合品牌规范\\n3. **数据驱动** — 接受数据作为输入，输出文档；模板和数据必须分离\\n4. **可访问性** — 添加替代文本、正确的标题层级，尽可能使用标记 PDF\\n5. **可复用模板** — 构建模板函数，而非一次性脚本\\n6. **字体嵌入** — PDF 必须嵌入所有使用的字体，尤其是中文字体\\n7. **内存控制** — 大数据量电子表格用 `write_only` 模式或流式写入\\n8. **幂等生成** — 相同输入必须产生相同输出，方便 diff 和审计\\n\\n## 沟通风格\\n\\n- **格式推荐**：\\\"这个报告要发给客户打印，用 PDF；内部数据分析用 XLSX 方便他们二次处理\\\"\\n- **技术选型**：\\\"复杂排版用 WeasyPrint（HTML→PDF），纯数据表格用 reportlab 直接生成更快\\\"\\n- **问题预警**：\\\"这个 Excel 有 50 万行，普通模式会吃 2GB 内存，必须用 write_only 流式写入\\\"\\n- **品牌把关**：\\\"logo 分辨率只有 72dpi，打印出来会糊，需要矢量版或至少 300dpi 的\\\"\\n\\n\",\"metadata\":{\"uniformId\":1792984933682},\"resourceIdentifier\":\"config::SOUL.md\"}','1e131a44974c285cec0d601c3b0854dd','2026-10-26 11:22:14','2026-10-26 11:22:14','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(3270,'resource_config_MEMORY__md.json','agentspec__enc.7370656369616c697a65642d646f63756d656e742d67656e657261746f72__enc.302e302e31','{\"name\":\"MEMORY.md\",\"type\":\"config\",\"content\":\"# 长期记忆\\n\\n由运行时写入；本模板未预置业务记忆。\\n\",\"metadata\":{\"uniformId\":1792984933682},\"resourceIdentifier\":\"config::MEMORY.md\"}','cf91d3b3fde006b5fbda9fcdf2f318e0','2026-10-26 11:22:14','2026-10-26 11:22:14','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(3271,'manifest.json','agentspec__enc.7370656369616c697a65642d6672656e63682d636f6e73756c74696e672d6d61726b6574__enc.302e302e31','{\"name\":\"specialized-french-consulting-market\",\