RY.md\",\"type\":\"config\"}]}','979865ad1f1e2a87958294ff1b1fdc93','2026-10-26 11:22:15','2026-10-26 11:22:15','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(3497,'resource_crons_jobs__json.json','agentspec__enc.737570706c792d636861696e2d76656e646f722d6576616c7561746f72__enc.302e302e31','{\"name\":\"jobs.json\",\"type\":\"crons\",\"content\":\"[]\\n\",\"metadata\":{\"uniformId\":1792984935240},\"resourceIdentifier\":\"crons::jobs.json\"}','c3be10fe23d0d01f03afc9b5ff54ca62','2026-10-26 11:22:15','2026-10-26 11:22:15','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(3498,'resource_crons_jobs__json.json','agentspec__enc.737570706c792d636861696e2d76656e646f722d6576616c7561746f72__enc.302e302e31','{\"name\":\"jobs.json\",\"type\":\"crons\",\"content\":\"[]\\n\",\"metadata\":{\"uniformId\":1792984935240},\"resourceIdentifier\":\"crons::jobs.json\"}','c3be10fe23d0d01f03afc9b5ff54ca62','2026-10-26 11:22:15','2026-10-26 11:22:15','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(3499,'skill_index.json','skill_image-to-video','{\"labels\":{\"latest\":\"0.0.1\"},\"versions\":{\"0.0.1\":[\"SKILL.md\"]}}','a954ba25a6022882637d1312aa486859','2026-10-26 11:22:15','2026-10-26 11:22:15','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(3500,'resource_config_IDENTITY__md.json','agentspec__enc.737570706c792d636861696e2d76656e646f722d6576616c7561746f72__enc.302e302e31','{\"name\":\"IDENTITY.md\",\"type\":\"config\",\"content\":\"# 供应商评估专家\\n专注供应商全生命周期管理的采购策略专家，擅长供应商筛选与评分、验厂审核、质量管理体系搭建、账期与成本谈判，帮助企业在1688等采购平台上建立稳定可靠的供应商体系。\\n\",\"metadata\":{\"uniformId\":1792984935240},\"resourceIdentifier\":\"config::IDENTITY.md\"}','f1fa0bb271b2e15fd813281d0667052c','2026-10-26 11:22:15','2026-10-26 11:22:15','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(3501,'skill_index.json','skill_image-to-video','{\"labels\":{\"latest\":\"0.0.1\"},\"versions\":{\"0.0.1\":[\"SKILL.md\"]}}','a954ba25a6022882637d1312aa486859','2026-10-26 11:22:15','2026-10-26 11:22:15','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(3502,'enc.7265666572656e6365732f636c692d7265666572656e63652e6d64','skill_enc.696e6673682d636c69__enc.302e302e31','# CLI Reference\n\n## Installation\n\n```bash\ncurl -fsSL https://cli.inference.sh | sh\n```\n\n## Global Commands\n\n| Command | Description |\n|---------|-------------|\n| `infsh help` | Show help |\n| `infsh version` | Show CLI version |\n| `infsh update` | Update CLI to latest |\n| `infsh login` | Authenticate |\n| `infsh me` | Show current user |\n\n## App Commands\n\n### Discovery\n\n| Command | Description |\n|---------|-------------|\n| `infsh app list` | List available apps |\n| `infsh app list --category <cat>` | Filter by category (image, video, audio, text, other) |\n| `infsh app search <query>` | Search apps |\n| `infsh app list --search <query>` | Search apps (flag form) |\n| `infsh app list --featured` | Show featured apps |\n| `infsh app list --new` | Sort by newest |\n| `infsh app list --page <n>` | Pagination |\n| `infsh app list -l` | Detailed table view |\n| `infsh app list --save <file>` | Save to JSON file |\n| `infsh app my` | List your deployed apps |\n| `infsh app get <app>` | Get app details |\n| `infsh app get <app> --json` | Get app details as JSON |\n\n### Execution\n\n| Command | Description |\n|---------|-------------|\n| `infsh app run <app> --input <file>` | Run app with input file |\n| `infsh app run <app> --input \'<json>\'` | Run with inline JSON |\n| `infsh app run <app> --input <file> --no-wait` | Run without waiting for completion |\n| `infsh app sample <app>` | Show sample input |\n| `infsh app sample <app> --save <file>` | Save sample to file |\n\n## Task Commands\n\n| Command | Description |\n|---------|-------------|\n| `infsh task get <task-id>` | Get task status and result |\n| `infsh task get <task-id> --json` | Get task as JSON |\n| `infsh task get <task-id> --save <file>` | Save task result to file |\n\n### Development\n\n| Command | Description |\n|---------|-------------|\n| `infsh app init` | Create new app (interactive) |\n| `infsh app init <name>` | Create new app with name |\n| `infsh app test --input <file>` | Test app locally |\n| `infsh app deploy` | Deploy app |\n| `infsh app deploy --dry-run` | Validate without deploying |\n| `infsh app pull <id>` | Pull app source |\n| `infsh app pull --all` | Pull all your apps |\n\n## Environment Variables\n\n| Variable | Description |\n|----------|-------------|\n| `INFSH_API_KEY` | API key (overrides config) |\n\n## Shell Completions\n\n```bash\n# Bash\ninfsh completion bash > /etc/bash_completion.d/infsh\n\n# Zsh\ninfsh completion zsh > \"${fpath[1]}/_infsh\"\n\n# Fish\ninfsh completion fish > ~/.config/fish/completions/infsh.fish\n```\n\n## App Name Format\n\nApps use the format `namespace/app-name`:\n\n- `falai/flux-dev-lora` - fal.ai\'s FLUX 2 Dev\n- `google/veo-3` - Google\'s Veo 3\n- `infsh/sdxl` - inference.sh\'s SDXL\n- `bytedance/seedance-1-5-pro` - ByteDance\'s Seedance\n- `xai/grok-imagine-image` - xAI\'s Grok\n\nVersion pinning: `namespace/app-name@version`\n\n## Documentation\n\n- [CLI Setup](https://inference.sh/docs/extend/cli-setup) - Complete CLI installation guide\n- [Running Apps](https://inference.sh/docs/apps/running) - How to run apps via CLI\n- [Creating an App](https://inference.sh/docs/extend/creating-app) - Build your own apps\n- [Deploying](https://inference.sh/docs/extend/deploying) - Deploy apps to the cloud\n','b0c112393310a53890afa25fa4a74632','2026-10-26 11:22:15','2026-10-26 11:22:15','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(3503,'resource_config_IDENTITY__md.json','agentspec__enc.737570706c792d636861696e2d76656e646f722d6576616c7561746f72__enc.302e302e31','{\"name\":\"IDENTITY.md\",\"type\":\"config\",\"content\":\"# 供应商评估专家\\n专注供应商全生命周期管理的采购策略专家，擅长供应商筛选与评分、验厂审核、质量管理体系搭建、账期与成本谈判，帮助企业在1688等采购平台上建立稳定可靠的供应商体系。\\n\",\"metadata\":{\"uniformId\":1792984935240},\"resourceIdentifier\":\"config::IDENTITY.md\"}','f1fa0bb271b2e15fd813281d0667052c','2026-10-26 11:22:15','2026-10-26 11:22:15','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(3504,'SKILL.md','skill_enc.696e6673682d636c69__enc.302e302e31','---\nversion: 0.0.1\nname: infsh-cli\ndescription: \"Run 150+ AI apps via inference.sh CLI - image generation, video creation, LLMs, search, 3D, Twitter automation. Models: FLUX, Veo, Gemini, Grok, Claude, Seedance, OmniHuman, Tavily, Exa, OpenRouter, and many more. Use when running AI apps, generating images/videos, calling LLMs, web search, or automating Twitter. Triggers: inference.sh, infsh, ai model, run ai, serverless ai, ai api, flux, veo, claude api, image generation, video generation, openrouter, tavily, exa search, twitter api, grok\"\nallowed-tools: Bash(infsh *)\n---\n\n# [inference.sh](https://inference.sh)\n\nRun 150+ AI apps in the cloud with a simple CLI. No GPU required.\n\n![[inference.sh](https://inference.sh)](https://cloud.inference.sh/app/files/u/4mg21r6ta37mpaz6ktzwtt8krr/01kgjw8atdxgkrsr8a2t5peq7b.jpeg)\n\n## Install CLI\n\n```bash\ncurl -fsSL https://cli.inference.sh | sh\ninfsh login\n```\n\n> **What does the installer do?** The [install script](https://cli.inference.sh) detects your OS and architecture, downloads the correct binary from `dist.inference.sh`, verifies its SHA-256 checksum, and places it in your PATH. That\'s it — no elevated permissions, no background processes, no telemetry. If you have [cosign](https://docs.sigstore.dev/cosign/system_config/installation/) installed, the installer also verifies the Sigstore signature automatically.\n>\n> **Manual install** (if you prefer not to pipe to sh):\n> ```bash\n> # Download the binary and checksums\n> curl -LO https://dist.inference.sh/cli/checksums.txt\n> curl -LO $(curl -fsSL https://dist.inference.sh/cli/manifest.json | grep -o \'\"url\":\"[^\"]*\"\' | grep $(uname -s | tr A-Z a-z)-$(uname -m | sed \'s/x86_64/amd64/;s/aarch64/arm64/\') | head -1 | cut -d\'\"\' -f4)\n> # Verify checksum\n> sha256sum -c checksums.txt --ignore-missing\n> # Extract and install\n> tar -xzf inferencesh-cli-*.tar.gz\n> mv inferencesh-cli-* ~/.local/bin/inferencesh\n> ```\n\n## Quick Examples\n\n```bash\n# Generate an image\ninfsh app run falai/flux-dev-lora --input \'{\"prompt\": \"a cat astronaut\"}\'\n\n# Generate a video\ninfsh app run google/veo-3-1-fast --input \'{\"prompt\": \"drone over mountains\"}\'\n\n# Call Claude\ninfsh app run openrouter/claude-sonnet-45 --input \'{\"prompt\": \"Explain quantum computing\"}\'\n\n# Web search\ninfsh app run tavily/search-assistant --input \'{\"query\": \"latest AI news\"}\'\n\n# Post to Twitter\ninfsh app run x/post-tweet --input \'{\"text\": \"Hello from AI!\"}\'\n\n# Generate 3D model\ninfsh app run infsh/rodin-3d-generator --input \'{\"prompt\": \"a wooden chair\"}\'\n```\n\n## Local File Uploads\n\nThe CLI automatically uploads local files when you provide a path instead of a URL:\n\n```bash\n# Upscale a local image\ninfsh app run falai/topaz-image-upscaler --input \'{\"image\": \"/path/to/photo.jpg\", \"upscale_factor\": 2}\'\n\n# Image-to-video from local file\ninfsh app run falai/wan-2-5-i2v --input \'{\"image\": \"./my-image.png\", \"prompt\": \"make it move\"}\'\n\n# Avatar with local audio and image\ninfsh app run bytedance/omnihuman-1-5 --input \'{\"audio\": \"/path/to/speech.mp3\", \"image\": \"/path/to/face.jpg\"}\'\n\n# Post tweet with local media\ninfsh app run x/post-create --input \'{\"text\": \"Check this out!\", \"media\": \"./screenshot.png\"}\'\n```\n\n## Commands\n\n| Task | Command |\n|------|---------|\n| List all apps | `infsh app list` |\n| Search apps | `infsh app list --search \"flux\"` |\n| Filter by category | `infsh app list --category image` |\n| Get app details | `infsh app get google/veo-3-1-fast` |\n| Generate sample input | `infsh app sample google/veo-3-1-fast --save input.json` |\n| Run app | `infsh app run google/veo-3-1-fast --input input.json` |\n| Run without waiting | `infsh app run <app> --input input.json --no-wait` |\n| Check task status | `infsh task get <task-id>` |\n\n## What\'s Available\n\n| Category | Examples |\n|----------|----------|\n| **Image** | FLUX, Gemini 3 Pro, Grok Imagine, Seedream 4.5, Reve, Topaz Upscaler |\n| **Video** | Veo 3.1, Seedance 1.5, Wan 2.5, OmniHuman, Fabric, HunyuanVideo Foley |\n| **LLMs** | Claude Opus/Sonnet/Haiku, Gemini 3 Pro, Kimi K2, GLM-4, any OpenRouter model |\n| **Search** | Tavily Search, Tavily Extract, Exa Search, Exa Answer, Exa Extract |\n| **3D** | Rodin 3D Generator |\n| **Twitter/X** | post-tweet, post-create, dm-send, user-follow, post-like, post-retweet |\n| **Utilities** | Media merger, caption videos, image stitching, audio extraction |\n\n## Related Skills\n\n```bash\n# Image generation (FLUX, Gemini, Grok, Seedream)\nnpx skills add inference-sh/skills@ai-image-generation\n\n# Video generation (Veo, Seedance, Wan, OmniHuman)\nnpx skills add inference-sh/skills@ai-video-generation\n\n# LLMs (Claude, Gemini, Kimi, GLM via OpenRouter)\nnpx skills add inference-sh/skills@llm-models\n\n# Web search (Tavily, Exa)\nnpx skills add inference-sh/skills@web-search\n\n# AI avatars & lipsync (OmniHuman, Fabric, PixVerse)\nnpx skills add inference-sh/skills@ai-avatar-video\n\n# Twitter/X automation\nnpx skills add inference-sh/skills@twitter-automation\n\n# Model-specific\nnpx skills add inference-sh/skills@flux-image\nnpx skills add inference-sh/skills@google-veo\n\n# Utilities\nnpx skills add inference-sh/skills@image-upscaling\nnpx skills add inference-sh/skills@background-removal\n```\n\n## Reference Files\n\n- [Authentication & Setup](references/authentication.md)\n- [Discovering Apps](references/app-discovery.md)\n- [Running Apps](references/running-apps.md)\n- [CLI Reference](references/cli-reference.md)\n\n## Documentation\n\n- [Agent Skills Overview](https://inference.sh/blog/skills/skills-overview) - The open standard for AI capabilities\n- [Getting Started](https://inference.sh/docs/getting-started/introduction) - Introduction to inference.sh\n- [What is inference.sh?](https://inference.sh/docs/getting-started/what-is-inference) - Platform overview\n- [Apps Overview](https://inference.sh/docs/apps/overview) - Understanding the app ecosystem\n- [CLI Setup](https://inference.sh/docs/extend/cli-setup) - Installing the CLI\n- [Workflows vs Agents](https://inference.sh/blog/concepts/workflows-vs-agents) - When to use each\n- [Why Agent Runtimes Matter](https://inference.sh/blog/agent-runtime/why-runtimes-matter) - Runtime benefits\n\n','a562dbcf1e9e2340ae155767089cd360','2026-10-26 11:22:15','2026-10-26 11:22:15','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(3505,'enc.7265666572656e6365732f636c692d7265666572656e63652e6d64','skill_enc.696e6673682d636c69__enc.302e302e31','# CLI Reference\n\n## Installation\n\n```bash\ncurl -fsSL https://cli.inference.sh | sh\n```\n\n## Global Commands\n\n| Command | Description |\n|---------|-------------|\n| `infsh help` | Show help |\n| `infsh version` | Show CLI version |\n| `infsh update` | Update CLI to latest |\n| `infsh login` | Authenticate |\n| `infsh me` | Show current user |\n\n## App Commands\n\n### Discovery\n\n| Command | Description |\n|---------|-------------|\n| `infsh app list` | List available apps |\n| `infsh app list --category <cat>` | Filter by category (image, video, audio, text, other) |\n| `infsh app search <query>` | Search apps |\n| `infsh app list --search <query>` | Search apps (flag form) |\n| `infsh app list --featured` | Show featured apps |\n| `infsh app list --new` | Sort by newest |\n| `infsh app list --page <n>` | Pagination |\n| `infsh app list -l` | Detailed table view |\n| `infsh app list --save <file>` | Save to JSON file |\n| `infsh app my` | List your deployed apps |\n| `infsh app get <app>` | Get app details |\n| `infsh app get <app> --json` | Get app details as JSON |\n\n### Execution\n\n| Command | Description |\n|---------|-------------|\n| `infsh app run <app> --input <file>` | Run app with input file |\n| `infsh app run <app> --input \'<json>\'` | Run with inline JSON |\n| `infsh app run <app> --input <file> --no-wait` | Run without waiting for completion |\n| `infsh app sample <app>` | Show sample input |\n| `infsh app sample <app> --save <file>` | Save sample to file |\n\n## Task Commands\n\n| Command | Description |\n|---------|-------------|\n| `infsh task get <task-id>` | Get task status and result |\n| `infsh task get <task-id> --json` | Get task as JSON |\n| `infsh task get <task-id> --save <file>` | Save task result to file |\n\n### Development\n\n| Command | Description |\n|---------|-------------|\n| `infsh app init` | Create new app (interactive) |\n| `infsh app init <name>` | Create new app with name |\n| `infsh app test --input <file>` | Test app locally |\n| `infsh app deploy` | Deploy app |\n| `infsh app deploy --dry-run` | Validate without deploying |\n| `infsh app pull <id>` | Pull app source |\n| `infsh app pull --all` | Pull all your apps |\n\n## Environment Variables\n\n| Variable | Description |\n|----------|-------------|\n| `INFSH_API_KEY` | API key (overrides config) |\n\n## Shell Completions\n\n```bash\n# Bash\ninfsh completion bash > /etc/bash_completion.d/infsh\n\n# Zsh\ninfsh completion zsh > \"${fpath[1]}/_infsh\"\n\n# Fish\ninfsh completion fish > ~/.config/fish/completions/infsh.fish\n```\n\n## App Name Format\n\nApps use the format `namespace/app-name`:\n\n- `falai/flux-dev-lora` - fal.ai\'s FLUX 2 Dev\n- `google/veo-3` - Google\'s Veo 3\n- `infsh/sdxl` - inference.sh\'s SDXL\n- `bytedance/seedance-1-5-pro` - ByteDance\'s Seedance\n- `xai/grok-imagine-image` - xAI\'s Grok\n\nVersion pinning: `namespace/app-name@version`\n\n## Documentation\n\n- [CLI Setup](https://inference.sh/docs/extend/cli-setup) - Complete CLI installation guide\n- [Running Apps](https://inference.sh/docs/apps/running) - How to run apps via CLI\n- [Creating an App](https://inference.sh/docs/extend/creating-app) - Build your own apps\n- [Deploying](https://inference.sh/docs/extend/deploying) - Deploy apps to the cloud\n','b0c112393310a53890afa25fa4a74632','2026-10-26 11:22:15','2026-10-26 11:22:15','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(3506,'enc.7265666572656e6365732f61757468656e7469636174696f6e2e6d64','skill_enc.696e6673682d636c69__enc.302e302e31','# Authentication & Setup\n\n## Install the CLI\n\n```bash\ncurl -fsSL https://cli.inference.sh | sh\n```\n\n## Login\n\n```bash\ninfsh login\n```\n\nThis opens a browser for authentication. After login, credentials are stored locally.\n\n## Check Authentication\n\n```bash\ninfsh me\n```\n\nShows your user info if authenticated.\n\n## Environment Variable\n\nFor CI/CD or scripts, set your API key:\n\n```bash\nexport INFSH_API_KEY=your-api-key\n```\n\nThe environment variable overrides the config file.\n\n## Update CLI\n\n```bash\ninfsh update\n```\n\nOr reinstall:\n\n```bash\ncurl -fsSL https://cli.inference.sh | sh\n```\n\n## Troubleshooting\n\n| Error | Solution |\n|-------|----------|\n| \"not authenticated\" | Run `infsh login` |\n| \"command not found\" | Reinstall CLI or add to PATH |\n| \"API key invalid\" | Check `INFSH_API_KEY` or re-login |\n\n## Documentation\n\n- [CLI Setup](https://inference.sh/docs/extend/cli-setup) - Complete CLI installation guide\n- [API Authentication](https://inference.sh/docs/api/authentication) - API key management\n- [Secrets](https://inference.sh/docs/secrets/overview) - Managing credentials\n','deb0ec845ad1813c3e54906b4a952b88','2026-10-26 11:22:15','2026-10-26 11:22:15','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(3507,'SKILL.md','skill_enc.696e6673682d636c69__enc.302e302e31','---\nversion: 0.0.1\nname: infsh-cli\ndescription: \"Run 150+ AI apps via inference.sh CLI - image generation, video creation, LLMs, search, 3D, Twitter automation. Models: FLUX, Veo, Gemini, Grok, Claude, Seedance, OmniHuman, Tavily, Exa, OpenRouter, and many more. Use when running AI apps, generating images/videos, calling LLMs, web search, or automating Twitter. Triggers: inference.sh, infsh, ai model, run ai, serverless ai, ai api, flux, veo, claude api, image generation, video generation, openrouter, tavily, exa search, twitter api, grok\"\nallowed-tools: Bash(infsh *)\n---\n\n# [inference.sh](https://inference.sh)\n\nRun 150+ AI apps in the cloud with a simple CLI. No GPU required.\n\n![[inference.sh](https://inference.sh)](https://cloud.inference.sh/app/files/u/4mg21r6ta37mpaz6ktzwtt8krr/01kgjw8atdxgkrsr8a2t5peq7b.jpeg)\n\n## Install CLI\n\n```bash\ncurl -fsSL https://cli.inference.sh | sh\ninfsh login\n```\n\n> **What does the installer do?** The [install script](https://cli.inference.sh) detects your OS and architecture, downloads the correct binary from `dist.inference.sh`, verifies its SHA-256 checksum, and places it in your PATH. That\'s it — no elevated permissions, no background processes, no telemetry. If you have [cosign](https://docs.sigstore.dev/cosign/system_config/installation/) installed, the installer also verifies the Sigstore signature automatically.\n>\n> **Manual install** (if you prefer not to pipe to sh):\n> ```bash\n> # Download the binary and checksums\n> curl -LO https://dist.inference.sh/cli/checksums.txt\n> curl -LO $(curl -fsSL https://dist.inference.sh/cli/manifest.json | grep -o \'\"url\":\"[^\"]*\"\' | grep $(uname -s | tr A-Z a-z)-$(uname -m | sed \'s/x86_64/amd64/;s/aarch64/arm64/\') | head -1 | cut -d\'\"\' -f4)\n> # Verify checksum\n> sha256sum -c checksums.txt --ignore-missing\n> # Extract and install\n> tar -xzf inferencesh-cli-*.tar.gz\n> mv inferencesh-cli-* ~/.local/bin/inferencesh\n> ```\n\n## Quick Examples\n\n```bash\n# Generate an image\ninfsh app run falai/flux-dev-lora --input \'{\"prompt\": \"a cat astronaut\"}\'\n\n# Generate a video\ninfsh app run google/veo-3-1-fast --input \'{\"prompt\": \"drone over mountains\"}\'\n\n# Call Claude\ninfsh app run openrouter/claude-sonnet-45 --input \'{\"prompt\": \"Explain quantum computing\"}\'\n\n# Web search\ninfsh app run tavily/search-assistant --input \'{\"query\": \"latest AI news\"}\'\n\n# Post to Twitter\ninfsh app run x/post-tweet --input \'{\"text\": \"Hello from AI!\"}\'\n\n# Generate 3D model\ninfsh app run infsh/rodin-3d-generator --input \'{\"prompt\": \"a wooden chair\"}\'\n```\n\n## Local File Uploads\n\nThe CLI automatically uploads local files when you provide a path instead of a URL:\n\n```bash\n# Upscale a local image\ninfsh app run falai/topaz-image-upscaler --input \'{\"image\": \"/path/to/photo.jpg\", \"upscale_factor\": 2}\'\n\n# Image-to-video from local file\ninfsh app run falai/wan-2-5-i2v --input \'{\"image\": \"./my-image.png\", \"prompt\": \"make it move\"}\'\n\n# Avatar with local audio and image\ninfsh app run bytedance/omnihuman-1-5 --input \'{\"audio\": \"/path/to/speech.mp3\", \"image\": \"/path/to/face.jpg\"}\'\n\n# Post tweet with local media\ninfsh app run x/post-create --input \'{\"text\": \"Check this out!\", \"media\": \"./screenshot.png\"}\'\n```\n\n## Commands\n\n| Task | Command |\n|------|---------|\n| List all apps | `infsh app list` |\n| Search apps | `infsh app list --search \"flux\"` |\n| Filter by category | `infsh app list --category image` |\n| Get app details | `infsh app get google/veo-3-1-fast` |\n| Generate sample input | `infsh app sample google/veo-3-1-fast --save input.json` |\n| Run app | `infsh app run google/veo-3-1-fast --input input.json` |\n| Run without waiting | `infsh app run <app> --input input.json --no-wait` |\n| Check task status | `infsh task get <task-id>` |\n\n## What\'s Available\n\n| Category | Examples |\n|----------|----------|\n| **Image** | FLUX, Gemini 3 Pro, Grok Imagine, Seedream 4.5, Reve, Topaz Upscaler |\n| **Video** | Veo 3.1, Seedance 1.5, Wan 2.5, OmniHuman, Fabric, HunyuanVideo Foley |\n| **LLMs** | Claude Opus/Sonnet/Haiku, Gemini 3 Pro, Kimi K2, GLM-4, any OpenRouter model |\n| **Search** | Tavily Search, Tavily Extract, Exa Search, Exa Answer, Exa Extract |\n| **3D** | Rodin 3D Generator |\n| **Twitter/X** | post-tweet, post-create, dm-send, user-follow, post-like, post-retweet |\n| **Utilities** | Media merger, caption videos, image stitching, audio extraction |\n\n## Related Skills\n\n```bash\n# Image generation (FLUX, Gemini, Grok, Seedream)\nnpx skills add inference-sh/skills@ai-image-generation\n\n# Video generation (Veo, Seedance, Wan, OmniHuman)\nnpx skills add inference-sh/skills@ai-video-generation\n\n# LLMs (Claude, Gemini, Kimi, GLM via OpenRouter)\nnpx skills add inference-sh/skills@llm-models\n\n# Web search (Tavily, Exa)\nnpx skills add inference-sh/skills@web-search\n\n# AI avatars & lipsync (OmniHuman, Fabric, PixVerse)\nnpx skills add inference-sh/skills@ai-avatar-video\n\n# Twitter/X automation\nnpx skills add inference-sh/skills@twitter-automation\n\n# Model-specific\nnpx skills add inference-sh/skills@flux-image\nnpx skills add inference-sh/skills@google-veo\n\n# Utilities\nnpx skills add inference-sh/skills@image-upscaling\nnpx skills add inference-sh/skills@background-removal\n```\n\n## Reference Files\n\n- [Authentication & Setup](references/authentication.md)\n- [Discovering Apps](references/app-discovery.md)\n- [Running Apps](references/running-apps.md)\n- [CLI Reference](references/cli-reference.md)\n\n## Documentation\n\n- [Agent Skills Overview](https://inference.sh/blog/skills/skills-overview) - The open standard for AI capabilities\n- [Getting Started](https://inference.sh/docs/getting-started/introduction) - Introduction to inference.sh\n- [What is inference.sh?](https://inference.sh/docs/getting-started/what-is-inference) - Platform overview\n- [Apps Overview](https://inference.sh/docs/apps/overview) - Understanding the app ecosystem\n- [CLI Setup](https://inference.sh/docs/extend/cli-setup) - Installing the CLI\n- [Workflows vs Agents](https://inference.sh/blog/concepts/workflows-vs-agents) - When to use each\n- [Why Agent Runtimes Matter](https://inference.sh/blog/agent-runtime/why-runtimes-matter) - Runtime benefits\n\n','a562dbcf1e9e2340ae155767089cd360','2026-10-26 11:22:15','2026-10-26 11:22:15','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(3508,'enc.7265666572656e6365732f72756e6e696e672d617070732e6d64','skill_enc.696e6673682d636c69__enc.302e302e31','# Running Apps\n\n## Basic Run\n\n```bash\ninfsh app run user/app-name --input input.json\n```\n\n## Inline JSON\n\n```bash\ninfsh app run falai/flux-dev-lora --input \'{\"prompt\": \"a sunset over mountains\"}\'\n```\n\n## Version Pinning\n\n```bash\ninfsh app run user/app-name@1.0.0 --input input.json\n```\n\n## Local File Uploads\n\nThe CLI automatically uploads local files when you provide a file path instead of a URL. Any field that accepts a URL also accepts a local path:\n\n```bash\n# Upscale a local image\ninfsh app run falai/topaz-image-upscaler --input \'{\"image\": \"/path/to/photo.jpg\", \"upscale_factor\": 2}\'\n\n# Image-to-video from local file\ninfsh app run falai/wan-2-5-i2v --input \'{\"image\": \"./my-image.png\", \"prompt\": \"make it move\"}\'\n\n# Avatar with local audio and image\ninfsh app run bytedance/omnihuman-1-5 --input \'{\"audio\": \"/path/to/speech.mp3\", \"image\": \"/path/to/face.jpg\"}\'\n\n# Post tweet with local media\ninfsh app run x/post-create --input \'{\"text\": \"Check this out!\", \"media\": \"./screenshot.png\"}\'\n```\n\nSupported paths:\n- Absolute paths: `/home/user/images/photo.jpg`\n- Relative paths: `./image.png`, `../data/video.mp4`\n- Home directory: `~/Pictures/photo.jpg`\n\n## Generate Sample Input\n\nBefore running, generate a sample input file:\n\n```bash\ninfsh app sample falai/flux-dev-lora\n```\n\nSave to file:\n\n```bash\ninfsh app sample falai/flux-dev-lora --save input.json\n```\n\nThen edit `input.json` and run:\n\n```bash\ninfsh app run falai/flux-dev-lora --input input.json\n```\n\n## Workflow Example\n\n### Image Generation with FLUX\n\n```bash\n# 1. Get app details\ninfsh app get falai/flux-dev-lora\n\n# 2. Generate sample input\ninfsh app sample falai/flux-dev-lora --save input.json\n\n# 3. Edit input.json\n# {\n#   \"prompt\": \"a cat astronaut floating in space\",\n#   \"num_images\": 1,\n#   \"image_size\": \"landscape_16_9\"\n# }\n\n# 4. Run\ninfsh app run falai/flux-dev-lora --input input.json\n```\n\n### Video Generation with Veo\n\n```bash\n# 1. Generate sample\ninfsh app sample google/veo-3-1-fast --save input.json\n\n# 2. Edit prompt\n# {\n#   \"prompt\": \"A drone shot flying over a forest at sunset\"\n# }\n\n# 3. Run\ninfsh app run google/veo-3-1-fast --input input.json\n```\n\n### Text-to-Speech\n\n```bash\n# Quick inline run\ninfsh app run infsh/kokoro-tts --input \'{\"text\": \"Hello, this is a test.\"}\'\n```\n\n## Task Tracking\n\nWhen you run an app, the CLI shows the task ID:\n\n```\nRunning falai/flux-dev-lora\nTask ID: abc123def456\n```\n\nFor long-running tasks, you can check status anytime:\n\n```bash\n# Check task status\ninfsh task get abc123def456\n\n# Get result as JSON\ninfsh task get abc123def456 --json\n\n# Save result to file\ninfsh task get abc123def456 --save result.json\n```\n\n### Run Without Waiting\n\nFor very long tasks, run in background:\n\n```bash\n# Submit and return immediately\ninfsh app run google/veo-3 --input input.json --no-wait\n\n# Check later\ninfsh task get <task-id>\n```\n\n## Output\n\nThe CLI returns the app output directly. For file outputs (images, videos, audio), you\'ll receive URLs to download.\n\nExample output:\n\n```json\n{\n  \"images\": [\n    {\n      \"url\": \"https://cloud.inference.sh/...\",\n      \"content_type\": \"image/png\"\n    }\n  ]\n}\n```\n\n## Error Handling\n\n| Error | Cause | Solution |\n|-------|-------|----------|\n| \"invalid input\" | Schema mismatch | Check `infsh app get` for required fields |\n| \"app not found\" | Wrong app name | Check `infsh app list --search` |\n| \"quota exceeded\" | Out of credits | Check account balance |\n\n## Documentation\n\n- [Running Apps](https://inference.sh/docs/apps/running) - Complete running apps guide\n- [Streaming Results](https://inference.sh/docs/api/sdk/streaming) - Real-time progress updates\n- [Setup Parameters](https://inference.sh/docs/apps/setup-parameters) - Configuring app inputs\n','fd689c450695dec66cdf013741d66273','2026-10-26 11:22:15','2026-10-26 11:22:15','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(3509,'enc.7265666572656e6365732f61757468656e7469636174696f6e2e6d64','skill_enc.696e6673682d636c69__enc.302e302e31','# Authentication & Setup\n\n## Install the CLI\n\n```bash\ncurl -fsSL https://cli.inference.sh | sh\n```\n\n## Login\n\n```bash\ninfsh login\n```\n\nThis opens a browser for authentication. After login, credentials are stored locally.\n\n## Check Authentication\n\n```bash\ninfsh me\n```\n\nShows your user info if authenticated.\n\n## Environment Variable\n\nFor CI/CD or scripts, set your API key:\n\n```bash\nexport INFSH_API_KEY=your-api-key\n```\n\nThe environment variable overrides the config file.\n\n## Update CLI\n\n```bash\ninfsh update\n```\n\nOr reinstall:\n\n```bash\ncurl -fsSL https://cli.inference.sh | sh\n```\n\n## Troubleshooting\n\n| Error | Solution |\n|-------|----------|\n| \"not authenticated\" | Run `infsh login` |\n| \"command not found\" | Reinstall CLI or add to PATH |\n| \"API key invalid\" | Check `INFSH_API_KEY` or re-login |\n\n## Documentation\n\n- [CLI Setup](https://inference.sh/docs/extend/cli-setup) - Complete CLI installation guide\n- [API Authentication](https://inference.sh/docs/api/authentication) - API key management\n- [Secrets](https://inference.sh/docs/secrets/overview) - Managing credentials\n','deb0ec845ad1813c3e54906b4a952b88','2026-10-26 11:22:15','2026-10-26 11:22:15','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(3510,'enc.7265666572656e6365732f6170702d646973636f766572792e6d64','skill_enc.696e6673682d636c69__enc.302e302e31','# Discovering Apps\n\n## List All Apps\n\n```bash\ninfsh app list\n```\n\n## Pagination\n\n```bash\ninfsh app list --page 2\n```\n\n## Filter by Category\n\n```bash\ninfsh app list --category image\ninfsh app list --category video\ninfsh app list --category audio\ninfsh app list --category text\ninfsh app list --category other\n```\n\n## Search\n\n```bash\ninfsh app search \"flux\"\ninfsh app search \"video generation\"\ninfsh app search \"tts\" -l\ninfsh app search \"image\" --category image\n```\n\nOr use the flag form:\n\n```bash\ninfsh app list --search \"flux\"\ninfsh app list --search \"video generation\"\ninfsh app list --search \"tts\"\n```\n\n## Featured Apps\n\n```bash\ninfsh app list --featured\n```\n\n## Newest First\n\n```bash\ninfsh app list --new\n```\n\n## Detailed View\n\n```bash\ninfsh app list -l\n```\n\nShows table with app name, category, description, and featured status.\n\n## Save to File\n\n```bash\ninfsh app list --save apps.json\n```\n\n## Your Apps\n\nList apps you\'ve deployed:\n\n```bash\ninfsh app my\ninfsh app my -l  # detailed\n```\n\n## Get App Details\n\n```bash\ninfsh app get falai/flux-dev-lora\ninfsh app get falai/flux-dev-lora --json\n```\n\nShows full app info including input/output schema.\n\n## Popular Apps by Category\n\n### Image Generation\n- `falai/flux-dev-lora` - FLUX.2 Dev (high quality)\n- `falai/flux-2-klein-lora` - FLUX.2 Klein (fastest)\n- `infsh/sdxl` - Stable Diffusion XL\n- `google/gemini-3-pro-image-preview` - Gemini 3 Pro\n- `xai/grok-imagine-image` - Grok image generation\n\n### Video Generation\n- `google/veo-3-1-fast` - Veo 3.1 Fast\n- `google/veo-3` - Veo 3\n- `bytedance/seedance-1-5-pro` - Seedance 1.5 Pro\n- `infsh/ltx-video-2` - LTX Video 2 (with audio)\n- `bytedance/omnihuman-1-5` - OmniHuman avatar\n\n### Audio\n- `infsh/dia-tts` - Conversational TTS\n- `infsh/kokoro-tts` - Kokoro TTS\n- `infsh/fast-whisper-large-v3` - Fast transcription\n- `infsh/diffrythm` - Music generation\n\n## Documentation\n\n- [Browsing the Grid](https://inference.sh/docs/apps/browsing-grid) - Visual app browsing\n- [Apps Overview](https://inference.sh/docs/apps/overview) - Understanding apps\n- [Running Apps](https://inference.sh/docs/apps/running) - How to run apps\n','d9f79e2efd476655587f07121b20b8e0','2026-10-26 11:22:15','2026-10-26 11:22:15','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(3511,'enc.7265666572656e6365732f72756e6e696e672d617070732e6d64','skill_enc.696e6673682d636c69__enc.302e302e31','# Running Apps\n\n## Basic Run\n\n```bash\ninfsh app run user/app-name --input input.json\n```\n\n## Inline JSON\n\n```bash\ninfsh app run falai/flux-dev-lora --input \'{\"prompt\": \"a sunset over mountains\"}\'\n```\n\n## Version Pinning\n\n```bash\ninfsh app run user/app-name@1.0.0 --input input.json\n```\n\n## Local File Uploads\n\nThe CLI automatically uploads local files when you provide a file path instead of a URL. Any field that accepts a URL also accepts a local path:\n\n```bash\n# Upscale a local image\ninfsh app run falai/topaz-image-upscaler --input \'{\"image\": \"/path/to/photo.jpg\", \"upscale_factor\": 2}\'\n\n# Image-to-video from local file\ninfsh app run falai/wan-2-5-i2v --input \'{\"image\": \"./my-image.png\", \"prompt\": \"make it move\"}\'\n\n# Avatar with local audio and image\ninfsh app run bytedance/omnihuman-1-5 --input \'{\"audio\": \"/path/to/speech.mp3\", \"image\": \"/path/to/face.jpg\"}\'\n\n# Post tweet with local media\ninfsh app run x/post-create --input \'{\"text\": \"Check this out!\", \"media\": \"./screenshot.png\"}\'\n```\n\nSupported paths:\n- Absolute paths: `/home/user/images/photo.jpg`\n- Relative paths: `./image.png`, `../data/video.mp4`\n- Home directory: `~/Pictures/photo.jpg`\n\n## Generate Sample Input\n\nBefore running, generate a sample input file:\n\n```bash\ninfsh app sample falai/flux-dev-lora\n```\n\nSave to file:\n\n```bash\ninfsh app sample falai/flux-dev-lora --save input.json\n```\n\nThen edit `input.json` and run:\n\n```bash\ninfsh app run falai/flux-dev-lora --input input.json\n```\n\n## Workflow Example\n\n### Image Generation with FLUX\n\n```bash\n# 1. Get app details\ninfsh app get falai/flux-dev-lora\n\n# 2. Generate sample input\ninfsh app sample falai/flux-dev-lora --save input.json\n\n# 3. Edit input.json\n# {\n#   \"prompt\": \"a cat astronaut floating in space\",\n#   \"num_images\": 1,\n#   \"image_size\": \"landscape_16_9\"\n# }\n\n# 4. Run\ninfsh app run falai/flux-dev-lora --input input.json\n```\n\n### Video Generation with Veo\n\n```bash\n# 1. Generate sample\ninfsh app sample google/veo-3-1-fast --save input.json\n\n# 2. Edit prompt\n# {\n#   \"prompt\": \"A drone shot flying over a forest at sunset\"\n# }\n\n# 3. Run\ninfsh app run google/veo-3-1-fast --input input.json\n```\n\n### Text-to-Speech\n\n```bash\n# Quick inline run\ninfsh app run infsh/kokoro-tts --input \'{\"text\": \"Hello, this is a test.\"}\'\n```\n\n## Task Tracking\n\nWhen you run an app, the CLI shows the task ID:\n\n```\nRunning falai/flux-dev-lora\nTask ID: abc123def456\n```\n\nFor long-running tasks, you can check status anytime:\n\n```bash\n# Check task status\ninfsh task get abc123def456\n\n# Get result as JSON\ninfsh task get abc123def456 --json\n\n# Save result to file\ninfsh task get abc123def456 --save result.json\n```\n\n### Run Without Waiting\n\nFor very long tasks, run in background:\n\n```bash\n# Submit and return immediately\ninfsh app run google/veo-3 --input input.json --no-wait\n\n# Check later\ninfsh task get <task-id>\n```\n\n## Output\n\nThe CLI returns the app output directly. For file outputs (images, videos, audio), you\'ll receive URLs to download.\n\nExample output:\n\n```json\n{\n  \"images\": [\n    {\n      \"url\": \"https://cloud.inference.sh/...\",\n      \"content_type\": \"image/png\"\n    }\n  ]\n}\n```\n\n## Error Handling\n\n| Error | Cause | Solution |\n|-------|-------|----------|\n| \"invalid input\" | Schema mismatch | Check `infsh app get` for required fields |\n| \"app not found\" | Wrong app name | Check `infsh app list --search` |\n| \"quota exceeded\" | Out of credits | Check account balance |\n\n## Documentation\n\n- [Running Apps](https://inference.sh/docs/apps/running) - Complete running apps guide\n- [Streaming Results](https://inference.sh/docs/api/sdk/streaming) - Real-time progress updates\n- [Setup Parameters](https://inference.sh/docs/apps/setup-parameters) - Configuring app inputs\n','fd689c450695dec66cdf013741d66273','2026-10-26 11:22:15','2026-10-26 11:22:15','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(3512,'resource_tool-analysis_tool-analysis__json.json','agentspec__enc.737570706c792d636861696e2d76656e646f722d6576616c7561746f72__enc.302e302e31','{\"name\":\"tool-analysis.json\",\"type\":\"tool-analysis\",\"content\":\"{\\n  \\\"version\\\": \\\"1.0\\\",\\n  \\\"notes\\\": \\\"Static export from agency-agents-zh OpenClaw conversion; not a runtime tool scan.\\\",\\n  \\\"packages\\\": { \\\"apt\\\": [], \\\"pip\\\": [], \\\"npm\\\": [] }\\n}\\n\",\"metadata\":{\"uniformId\":1792984935240},\"resourceIdentifier\":\"tool-analysis::tool-analysis.json\"}','26adf908ac2a7735449209512267d512','2026-10-26 11:22:15','2026-10-26 11:22:15','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(3513,'enc.7265666572656e6365732f6170702d646973636f766572792e6d64','skill_enc.696e6673682d636c69__enc.302e302e31','# Discovering Apps\n\n## List All Apps\n\n```bash\ninfsh app list\n```\n\n## Pagination\n\n```bash\ninfsh app list --page 2\n```\n\n## Filter by Category\n\n```bash\ninfsh app list --category image\ninfsh app list --category video\ninfsh app list --category audio\ninfsh app list --category text\ninfsh app list --category other\n```\n\n## Search\n\n```bash\ninfsh app search \"flux\"\ninfsh app search \"video generation\"\ninfsh app search \"tts\" -l\ninfsh app search \"image\" --category image\n```\n\nOr use the flag form:\n\n```bash\ninfsh app list --search \"flux\"\ninfsh app list --search \"video generation\"\ninfsh app list --search \"tts\"\n```\n\n## Featured Apps\n\n```bash\ninfsh app list --featured\n```\n\n## Newest First\n\n```bash\ninfsh app list --new\n```\n\n## Detailed View\n\n```bash\ninfsh app list -l\n```\n\nShows table with app name, category, description, and featured status.\n\n## Save to File\n\n```bash\ninfsh app list --save apps.json\n```\n\n## Your Apps\n\nList apps you\'ve deployed:\n\n```bash\ninfsh app my\ninfsh app my -l  # detailed\n```\n\n## Get App Details\n\n```bash\ninfsh app get falai/flux-dev-lora\ninfsh app get falai/flux-dev-lora --json\n```\n\nShows full app info including input/output schema.\n\n## Popular Apps by Category\n\n### Image Generation\n- `falai/flux-dev-lora` - FLUX.2 Dev (high quality)\n- `falai/flux-2-klein-lora` - FLUX.2 Klein (fastest)\n- `infsh/sdxl` - Stable Diffusion XL\n- `google/gemini-3-pro-image-preview` - Gemini 3 Pro\n- `xai/grok-imagine-image` - Grok image generation\n\n### Video Generation\n- `google/veo-3-1-fast` - Veo 3.1 Fast\n- `google/veo-3` - Veo 3\n- `bytedance/seedance-1-5-pro` - Seedance 1.5 Pro\n- `infsh/ltx-video-2` - LTX Video 2 (with audio)\n- `bytedance/omnihuman-1-5` - OmniHuman avatar\n\n### Audio\n- `infsh/dia-tts` - Conversational TTS\n- `infsh/kokoro-tts` - Kokoro TTS\n- `infsh/fast-whisper-large-v3` - Fast transcription\n- `infsh/diffrythm` - Music generation\n\n## Documentation\n\n- [Browsing the Grid](https://inference.sh/docs/apps/browsing-grid) - Visual app browsing\n- [Apps Overview](https://inference.sh/docs/apps/overview) - Understanding apps\n- [Running Apps](https://inference.sh/docs/apps/running) - How to run apps\n','d9f79e2efd476655587f07121b20b8e0','2026-10-26 11:22:15','2026-10-26 11:22:15','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(3514,'resource_config_AGENTS__md.json','agentspec__enc.737570706c792d636861696e2d76656e646f722d6576616c7561746f72__enc.302e302e31','{\"name\":\"AGENTS.md\",\"type\":\"config\",\"content\":\"\\n# 供应商评估专家\\n\\n你是**供应商评估专家**，一位在中国制造业供应链摸爬滚打多年的采购管理老手。你精通供应商筛选评估、工厂验厂审核、质量管理体系搭建和采购成本优化，能够帮助企业从1688海量供应商中筛选出真正靠谱的合作伙伴，并建立长期稳定的供应商管理机制。\\n\\n## 核心使命\\n\\n### 供应商筛选与准入\\n- 建立供应商准入标准：营业执照、生产资质、质量认证（ISO9001/ISO14001）、行业资质\\n- 1688平台供应商初筛：实力商家/超级工厂标签、交易勋章、买家评价、回头率\\n- 行业展会和产业带实地考察：广州、义乌、深圳、佛山等核心产业集群\\n- 样品评估流程：外观、功能、包装、物流测试全链路验证\\n- 新供应商试用期机制：首批小单测试，通过后逐步放量\\n\\n### 供应商评分体系\\n- 建立五维评分模型：质量（30%）、价格（25%）、交期（20%）、服务（15%）、创新（10%）\\n- 质量维度：来料合格率、客诉率、质量改进响应速度\\n- 价格维度：单价竞争力、年度降本幅度、隐性成本（运费/模具/打样费）\\n- 交期维度：准时交货率、紧急订单响应能力、产能弹性\\n- 服务维度：沟通效率、问题处理态度、售后配合度\\n- 创新维度：新品开发能力、工艺改进建议、材料替代方案\\n\\n### 验厂审核体系\\n- 生产能力审核：设备清单、产能数据、排产逻辑、人员配置\\n- 质量体系审核：QC流程、检验标准、不良品处理机制、追溯体系\\n- 社会责任审核：用工合规、安全生产、环保达标（特别是外贸客户要求的BSCI/SA8000）\\n- 财务健康评估：注册资本、经营年限、主要客户集中度、负债情况\\n- 现场管理评估：5S管理水平、仓储条件、物料管理规范\\n\\n### 供应商分级管理\\n- **战略供应商**（S级）：年采购额占比>20%，深度绑定，联合开发\\n- **核心供应商**（A级）：主力供应，优先分配订单，享有年度框架协议\\n- **一般供应商**（B级）：补充供应，维持基本合作，定期评估\\n- **观察供应商**（C级）：试用期或降级供应商，限制订单量\\n- **淘汰供应商**（D级）：触发红线或连续不达标，启动退出机制\\n\\n### 采购成本与账期管理\\n- 建立成本分析模型：材料成本 + 加工成本 + 管理费用 + 合理利润\\n- 谈判策略：年度框架量价锁定、阶梯价格、原材料联动机制\\n- 账期设计：月结30天/60天/90天，预付比例控制，票据结算方式\\n- 降本路径：集中采购、替代材料、工艺优化、包装简化\\n- 价格基准库：建立核心物料的市场价格监控和历史价格数据库\\n\\n## 必须遵守的规则\\n\\n### 合规与廉洁\\n- 供应商评估必须由至少两人交叉进行，杜绝单人决策\\n- 验厂报告必须附现场照片和原始记录，不接受仅凭供应商提供的资料\\n- 采购人员与供应商之间的利益关系必须主动申报\\n- 涉及食品、化妆品、母婴用品的供应商必须持有对应的GB国标检测报告和生产许可证\\n\\n### 质量底线\\n- 来料合格率低于95%的供应商自动触发整改通知\\n- 连续两批不合格的供应商立即暂停供货并启动根因分析\\n- 涉及安全性能问题（如有害物质超标）的供应商一票否决\\n- 关键物料必须有第二供应源，不允许单一来源依赖\\n\\n### 合同与风险\\n- 所有采购合同必须包含质量条款、交期条款、违约罚则\\n- 年采购额超过50万的供应商必须签订保密协议和竞业条款\\n- 供应商经营异常（工商变更、法律纠纷、环保处罚）必须48小时内预警\\n\\n## 专业能力与交付物\\n\\n### 供应商评分卡\\n\\n```markdown\\n# 供应商季度评分卡\\n\\n## 基本信息\\n- 供应商名称：XX包装材料有限公司\\n- 供应商编号：SUP-2024-0086\\n- 合作年限：3年\\n- 当前等级：A级（核心供应商）\\n- 评估周期：2024年Q3\\n\\n## 五维评分\\n\\n| 维度 | 权重 | 得分 | 加权分 | 趋势 |\\n|------|------|------|-------|------|\\n| 质量 | 30% | 88分 | 26.4 | ↑ +3 |\\n| 价格 | 25% | 82分 | 20.5 | → 持平 |\\n| 交期 | 20% | 75分 | 15.0 | ↓ -5 |\\n| 服务 | 15% | 90分 | 13.5 | ↑ +2 |\\n| 创新 | 10% | 70分 | 7.0  | → 持平 |\\n| **综合** | **100%** | - | **82.4** | **↑ +1.2** |\\n\\n## 关键数据\\n- 来料合格率：98.2%（目标>97%）✅\\n- 准时交货率：88.5%（目标>92%）❌\\n- 客诉响应时间：4.2小时（目标<8小时）✅\\n- 年度降本完成率：3.1%（目标>3%）✅\\n\\n## 改进要求\\n1. 交期问题：Q3有3次延迟交货，主因为排产冲突，要求提交改进方案\\n2. 建议增加产线以应对旺季产能需求\\n3. 下季度目标：综合评分提升至85分以上\\n```\\n\\n### 验厂审核报告\\n\\n```markdown\\n# 工厂审核报告\\n\\n## 工厂概况\\n- 工厂名称：XX日化制品有限公司\\n- 地址：广东省广州市白云区XX工业园\\n- 审核日期：2024年9月15日\\n- 审核人员：张三（质量部）、李四（采购部）\\n\\n## 审核项目评分\\n\\n| 审核项 | 满分 | 得分 | 等级 |\\n|--------|------|------|------|\\n| 营业资质与许可 | 10 | 9 | A |\\n| 生产设备与产能 | 20 | 16 | B |\\n| 质量管理体系 | 25 | 21 | A |\\n| 仓储与物料管理 | 15 | 11 | B |\\n| 现场5S管理 | 10 | 7 | B |\\n| 安全与环保 | 10 | 8 | A |\\n| 人员管理与培训 | 10 | 7 | B |\\n| **总分** | **100** | **79** | **B+** |\\n\\n## 关键发现\\n### 优势项\\n- 持有ISO9001:2015认证和化妆品生产许可证\\n- QC实验室配备完善，有专职质检人员6人\\n- 核心客户包括两家知名品牌，有大单生产经验\\n\\n### 风险项\\n- 仓库温湿度监控设备老旧，部分区域超标\\n- 车间内原料与成品未完全隔离存放\\n- 员工培训记录不完整，新员工上岗培训流于形式\\n\\n## 审核结论\\n- 总体评定：**有条件通过**\\n- 整改要求：3项风险项须在30天内完成整改并提交证据\\n- 复审安排：整改完成后15天内安排复审\\n```\\n\\n### 供应商年度采购策略\\n\\n```markdown\\n# 年度供应商采购策略\\n\\n## 供应商结构优化目标\\n| 等级 | 当前数量 | 目标数量 | 采购额占比 |\\n|------|---------|---------|-----------|\\n| S级战略 | 3家 | 3家 | 35% |\\n| A级核心 | 12家 | 10家 | 40% |\\n| B级一般 | 25家 | 20家 | 20% |\\n| C级观察 | 8家 | 5家 | 5% |\\n| 合计 | 48家 | 38家 | 100% |\\n\\n## 年度降本目标\\n- 整体采购成本降低3%-5%\\n- 路径：集中采购（1.5%）+ 工艺优化（1%）+ 替代材料（0.5-1%）+ 账期优化（0.5-1%）\\n\\n## 新供应商开发计划\\n- Q1：完成包装材料备选供应商开发（当前单一来源风险）\\n- Q2：参加广州美博会、义乌小商品展，储备新品类供应商\\n- Q3：完成3家新供应商的验厂和试单\\n- Q4：年度供应商大会，评优与淘汰\\n\\n## 账期策略\\n- S/A级供应商：月结45天，季度对账\\n- B级供应商：月结30天，按单结算\\n- 新供应商试用期：预付30% + 验收后付尾款\\n```\\n\\n## 工作流程\\n\\n### 第一步：需求分析与供应商寻源\\n- 明确采购品类、规格要求、年度预估用量\\n- 1688平台搜索+行业展会+同行推荐多渠道寻源\\n- 初步筛选3-5家候选供应商进入评估流程\\n- 发送RFQ（询价单），收集报价和基本资质信息\\n\\n### 第二步：样品评估与验厂\\n- 向候选供应商索取样品，进行功能、外观、包装全面测试\\n- 对通过样品评估的供应商安排实地验厂\\n- 验厂团队至少包含采购和质量两个部门人员\\n- 输出验厂报告，明确通过/有条件通过/不通过结论\\n\\n### 第三步：商务谈判与合同签订\\n- 基于成本分析模型进行价格谈判，目标是\\\"合理价格\\\"而非\\\"最低价格\\\"\\n- 明确质量标准、交期要求、违约条款、账期安排\\n- 签订框架采购协议和质量保证协议\\n- 新供应商进入3个月试用期，小单验证后逐步放量\\n\\n### 第四步：日常管理与绩效评估\\n- 每批次来料检验，记录合格率数据\\n- 每月跟踪交货准时率和服务响应情况\\n- 每季度输出供应商评分卡，进行等级评定\\n- 针对不达标项发出整改通知并跟踪闭环\\n\\n### 第五步：年度复盘与策略调整\\n- 年度供应商大会：表彰优秀、约谈问题供应商\\n- 更新供应商分级：晋级/维持/降级/淘汰\\n- 优化供应商结构：减少尾部供应商数量，集中资源\\n- 制定下一年度采购策略和降本计划\\n\\n## 成功指标\\n\\n- 供应商来料合格率整体 > 97%\\n- 供应商准时交货率 > 92%\\n- 年度采购成本降幅 > 3%\\n- 核心物料第二供应源覆盖率 > 80%\\n- 供应商淘汰率控制在10%-15%（持续优化但保持稳定）\\n- 新供应商试用期通过率 > 70%\\n- 验厂整改闭环率 100%\\n- 供应商满意度评分 > 85分（双向评估机制）\\n\",\"metadata\":{\"uniformId\":1792984935240},\"resourceIdentifier\":\"config::AGENTS.md\"}','9d98f844823ca2d9e22471854343f7b5','2026-10-26 11:22:15','2026-10-26 11:22:15','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(3515,'resource_tool-analysis_tool-analysis__json.json','agentspec__enc.737570706c792d636861696e2d76656e646f722d6576616c7561746f72__enc.302e302e31','{\"name\":\"tool-analysis.json\",\"type\":\"tool-analysis\",\"content\":\"{\\n  \\\"version\\\": \\\"1.0\\\",\\n  \\\"notes\\\": \\\"Static export from agency-agents-zh OpenClaw conversion; not a runtime tool scan.\\\",\\n  \\\"packages\\\": { \\\"apt\\\": [], \\\"pip\\\": [], \\\"npm\\\": [] }\\n}\\n\",\"metadata\":{\"uniformId\":1792984935240},\"resourceIdentifier\":\"tool-analysis::tool-analysis.json\"}','26adf908ac2a7735449209512267d512','2026-10-26 11:22:15','2026-10-26 11:22:15','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(3516,'SKILL.md','skill_enc.6a6176617363726970742d73646b__enc.302e302e31','---\nversion: 0.0.1\nname: javascript-sdk\ndescription: \"JavaScript/TypeScript SDK for inference.sh - run AI apps, build agents, integrate 150+ models. Package: @inferencesh/sdk (npm install). Full TypeScript support, streaming, file uploads. Build agents with template or ad-hoc patterns, tool builder API, skills, human approval. Use for: JavaScript integration, TypeScript, Node.js, React, Next.js, frontend apps. Triggers: javascript sdk, typescript sdk, npm install, node.js api, js client, react ai, next.js ai, frontend sdk, @inferencesh/sdk, typescript agent, browser sdk, js integration\"\nallowed-tools: Bash(npm *), Bash(npx *), Bash(node *), Bash(pnpm *), Bash(yarn *)\n---\n\n# JavaScript SDK\n\nBuild AI applications with the [inference.sh](https://inference.sh) JavaScript/TypeScript SDK.\n\n![JavaScript SDK](https://cloud.inference.sh/app/files/u/4mg21r6ta37mpaz6ktzwtt8krr/01kgvftjwhby36trvaj66bwzcf.jpeg)\n\n## Quick Start\n\n```bash\nnpm install @inferencesh/sdk\n```\n\n```typescript\nimport { inference } from \'@inferencesh/sdk\';\n\nconst client = inference({ apiKey: \'inf_your_key\' });\n\n// Run an AI app\nconst result = await client.run({\n  app: \'infsh/flux-schnell\',\n  input: { prompt: \'A sunset over mountains\' }\n});\nconsole.log(result.output);\n```\n\n## Installation\n\n```bash\nnpm install @inferencesh/sdk\n# or\nyarn add @inferencesh/sdk\n# or\npnpm add @inferencesh/sdk\n```\n\n**Requirements:** Node.js 18.0.0+ (or modern browser with fetch)\n\n## Authentication\n\n```typescript\nimport { inference } from \'@inferencesh/sdk\';\n\n// Direct API key\nconst client = inference({ apiKey: \'inf_your_key\' });\n\n// From environment variable (recommended)\nconst client = inference({ apiKey: process.env.INFERENCE_API_KEY });\n\n// For frontend apps (use proxy)\nconst client = inference({ proxyUrl: \'/api/inference/proxy\' });\n```\n\nGet your API key: Settings → API Keys → Create API Key\n\n## Running Apps\n\n### Basic Execution\n\n```typescript\nconst result = await client.run({\n  app: \'infsh/flux-schnell\',\n  input: { prompt: \'A cat astronaut\' }\n});\n\nconsole.log(result.status);  // \"completed\"\nconsole.log(result.output);  // Output data\n```\n\n### Fire and Forget\n\n```typescript\nconst task = await client.run({\n  app: \'google/veo-3-1-fast\',\n  input: { prompt: \'Drone flying over mountains\' }\n}, { wait: false });\n\nconsole.log(`Task ID: ${task.id}`);\n// Check later with client.getTask(task.id)\n```\n\n### Streaming Progress\n\n```typescript\nconst stream = await client.run({\n  app: \'google/veo-3-1-fast\',\n  input: { prompt: \'Ocean waves at sunset\' }\n}, { stream: true });\n\nfor await (const update of stream) {\n  console.log(`Status: ${update.status}`);\n  if (update.logs?.length) {\n    console.log(update.logs.at(-1));\n  }\n}\n```\n\n### Run Parameters\n\n| Parameter | Type | Description |\n|-----------|------|-------------|\n| `app` | string | App ID (namespace/name@version) |\n| `input` | object | Input matching app schema |\n| `setup` | object | Hidden setup configuration |\n| `infra` | string | \'cloud\' or \'private\' |\n| `session` | string | Session ID for stateful execution |\n| `session_timeout` | number | Idle timeout (1-3600 seconds) |\n\n## File Handling\n\n### Automatic Upload\n\n```typescript\nconst result = await client.run({\n  app: \'image-processor\',\n  input: {\n    image: \'/path/to/image.png\'  // Auto-uploaded\n  }\n});\n```\n\n### Manual Upload\n\n```typescript\n// Basic upload\nconst file = await client.uploadFile(\'/path/to/image.png\');\n\n// With options\nconst file = await client.uploadFile(\'/path/to/image.png\', {\n  filename: \'custom_name.png\',\n  contentType: \'image/png\',\n  public: true\n});\n\nconst result = await client.run({\n  app: \'image-processor\',\n  input: { image: file.uri }\n});\n```\n\n### Browser File Upload\n\n```typescript\nconst input = document.querySelector(\'input[type=\"file\"]\');\nconst file = await client.uploadFile(input.files[0]);\n```\n\n## Sessions (Stateful Execution)\n\nKeep workers warm across multiple calls:\n\n```typescript\n// Start new session\nconst result = await client.run({\n  app: \'my-app\',\n  input: { action: \'init\' },\n  session: \'new\',\n  session_timeout: 300  // 5 minutes\n});\nconst sessionId = result.session_id;\n\n// Continue in same session\nconst result2 = await client.run({\n  app: \'my-app\',\n  input: { action: \'process\' },\n  session: sessionId\n});\n```\n\n## Agent SDK\n\n### Template Agents\n\nUse pre-built agents from your workspace:\n\n```typescript\nconst agent = client.agent(\'my-team/support-agent@latest\');\n\n// Send message\nconst response = await agent.sendMessage(\'Hello!\');\nconsole.log(response.text);\n\n// Multi-turn conversation\nconst response2 = await agent.sendMessage(\'Tell me more\');\n\n// Reset conversation\nagent.reset();\n\n// Get chat history\nconst chat = await agent.getChat();\n```\n\n### Ad-hoc Agents\n\nCreate custom agents programmatically:\n\n```typescript\nimport { tool, string, number, appTool } from \'@inferencesh/sdk\';\n\n// Define tools\nconst calculator = tool(\'calculate\')\n  .describe(\'Perform a calculation\')\n  .param(\'expression\', string(\'Math expression\'))\n  .build();\n\nconst imageGen = appTool(\'generate_image\', \'infsh/flux-schnell@latest\')\n  .describe(\'Generate an image\')\n  .param(\'prompt\', string(\'Image description\'))\n  .build();\n\n// Create agent\nconst agent = client.agent({\n  core_app: { ref: \'infsh/claude-sonnet-4@latest\' },\n  system_prompt: \'You are a helpful assistant.\',\n  tools: [calculator, imageGen],\n  temperature: 0.7,\n  max_tokens: 4096\n});\n\nconst response = await agent.sendMessage(\'What is 25 * 4?\');\n```\n\n### Available Core Apps\n\n| Model | App Reference |\n|-------|---------------|\n| Claude Sonnet 4 | `infsh/claude-sonnet-4@latest` |\n| Claude 3.5 Haiku | `infsh/claude-haiku-35@latest` |\n| GPT-4o | `infsh/gpt-4o@latest` |\n| GPT-4o Mini | `infsh/gpt-4o-mini@latest` |\n\n## Tool Builder API\n\n### Parameter Types\n\n```typescript\nimport {\n  string, number, integer, boolean,\n  enumOf, array, obj, optional\n} from \'@inferencesh/sdk\';\n\nconst name = string(\'User\\\'s name\');\nconst age = integer(\'Age in years\');\nconst score = number(\'Score 0-1\');\nconst active = boolean(\'Is active\');\nconst priority = enumOf([\'low\', \'medium\', \'high\'], \'Priority\');\nconst tags = array(string(\'Tag\'), \'List of tags\');\nconst address = obj({\n  street: string(\'Street\'),\n  city: string(\'City\'),\n  zip: optional(string(\'ZIP\'))\n}, \'Address\');\n```\n\n### Client Tools (Run in Your Code)\n\n```typescript\nconst greet = tool(\'greet\')\n  .display(\'Greet User\')\n  .describe(\'Greets a user by name\')\n  .param(\'name\', string(\'Name to greet\'))\n  .requireApproval()\n  .build();\n```\n\n### App Tools (Call AI Apps)\n\n```typescript\nconst generate = appTool(\'generate_image\', \'infsh/flux-schnell@latest\')\n  .describe(\'Generate an image from text\')\n  .param(\'prompt\', string(\'Image description\'))\n  .setup({ model: \'schnell\' })\n  .input({ steps: 20 })\n  .requireApproval()\n  .build();\n```\n\n### Agent Tools (Delegate to Sub-agents)\n\n```typescript\nimport { agentTool } from \'@inferencesh/sdk\';\n\nconst researcher = agentTool(\'research\', \'my-org/researcher@v1\')\n  .describe(\'Research a topic\')\n  .param(\'topic\', string(\'Topic to research\'))\n  .build();\n```\n\n### Webhook Tools (Call External APIs)\n\n```typescript\nimport { webhookTool } from \'@inferencesh/sdk\';\n\nconst notify = webhookTool(\'slack\', \'https://hooks.slack.com/...\')\n  .describe(\'Send Slack notification\')\n  .secret(\'SLACK_SECRET\')\n  .param(\'channel\', string(\'Channel\'))\n  .param(\'message\', string(\'Message\'))\n  .build();\n```\n\n### Internal Tools (Built-in Capabilities)\n\n```typescript\nimport { internalTools } from \'@inferencesh/sdk\';\n\nconst config = internalTools()\n  .plan()\n  .memory()\n  .webSearch(true)\n  .codeExecution(true)\n  .imageGeneration({\n    enabled: true,\n    appRef: \'infsh/flux@latest\'\n  })\n  .build();\n\nconst agent = client.agent({\n  core_app: { ref: \'infsh/claude-sonnet-4@latest\' },\n  internal_tools: config\n});\n```\n\n## Streaming Agent Responses\n\n```typescript\nconst response = await agent.sendMessage(\'Explain quantum computing\', {\n  onMessage: (msg) => {\n    if (msg.content) {\n      process.stdout.write(msg.content);\n    }\n  },\n  onToolCall: async (call) => {\n    console.log(`\\n[Tool: ${call.name}]`);\n    const result = await executeTool(call.name, call.args);\n    agent.submitToolResult(call.id, result);\n  }\n});\n```\n\n## File Attachments\n\n```typescript\n// From file path (Node.js)\nimport { readFileSync } from \'fs\';\nconst response = await agent.sendMessage(\'What\\\'s in this image?\', {\n  files: [readFileSync(\'image.png\')]\n});\n\n// From base64\nconst response = await agent.sendMessage(\'Analyze this\', {\n  files: [\'data:image/png;base64,iVBORw0KGgo...\']\n});\n\n// From browser File object\nconst input = document.querySelector(\'input[type=\"file\"]\');\nconst response = await agent.sendMessage(\'Describe this\', {\n  files: [input.files[0]]\n});\n```\n\n## Skills (Reusable Context)\n\n```typescript\nconst agent = client.agent({\n  core_app: { ref: \'infsh/claude-sonnet-4@latest\' },\n  skills: [\n    {\n      name: \'code-review\',\n      description: \'Code review guidelines\',\n      content: \'# Code Review\\n\\n1. Check security\\n2. Check performance...\'\n    },\n    {\n      name: \'api-docs\',\n      description: \'API documentation\',\n      url: \'https://example.com/skills/api-docs.md\'\n    }\n  ]\n});\n```\n\n## Server Proxy (Frontend Apps)\n\nFor browser apps, proxy through your backend to keep API keys secure:\n\n### Client Setup\n\n```typescript\nconst client = inference({\n  proxyUrl: \'/api/inference/proxy\'\n  // No apiKey needed on frontend\n});\n```\n\n### Next.js Proxy (App Router)\n\n```typescript\n// app/api/inference/proxy/route.ts\nimport { createRouteHandler } from \'@inferencesh/sdk/proxy/nextjs\';\n\nconst route = createRouteHandler({\n  apiKey: process.env.INFERENCE_API_KEY\n});\n\nexport const POST = route.POST;\n```\n\n### Express Proxy\n\n```typescript\nimport express from \'express\';\nimport { createProxyMiddleware } from \'@inferencesh/sdk/proxy/express\';\n\nconst app = express();\napp.use(\'/api/inference/proxy\', createProxyMiddleware({\n  apiKey: process.env.INFERENCE_API_KEY\n}));\n```\n\n### Supported Frameworks\n\n- Next.js (App Router & Pages Router)\n- Express\n- Hono\n- Remix\n- SvelteKit\n\n## TypeScript Support\n\nFull type definitions included:\n\n```typescript\nimport type {\n  TaskDTO,\n  ChatDTO,\n  ChatMessageDTO,\n  AgentTool,\n  TaskStatusCompleted,\n  TaskStatusFailed\n} from \'@inferencesh/sdk\';\n\nif (result.status === TaskStatusCompleted) {\n  console.log(\'Done!\');\n} else if (result.status === TaskStatusFailed) {\n  console.log(\'Failed:\', result.error);\n}\n```\n\n## Error Handling\n\n```typescript\nimport { RequirementsNotMetException, InferenceError } from \'@inferencesh/sdk\';\n\ntry {\n  const result = await client.run({ app: \'my-app\', input: {...} });\n} catch (e) {\n  if (e instanceof RequirementsNotMetException) {\n    console.log(\'Missing requirements:\');\n    for (const err of e.errors) {\n      console.log(`  - ${err.type}: ${err.key}`);\n    }\n  } else if (e instanceof InferenceError) {\n    console.log(\'API error:\', e.message);\n  }\n}\n```\n\n## Human Approval Workflows\n\n```typescript\nconst response = await agent.sendMessage(\'Delete all temp files\', {\n  onToolCall: async (call) => {\n    if (call.requiresApproval) {\n      const approved = await promptUser(`Allow ${call.name}?`);\n      if (approved) {\n        const result = await executeTool(call.name, call.args);\n        agent.submitToolResult(call.id, result);\n      } else {\n        agent.submitToolResult(call.id, { error: \'Denied by user\' });\n      }\n    }\n  }\n});\n```\n\n## CommonJS Support\n\n```javascript\nconst { inference, tool, string } = require(\'@inferencesh/sdk\');\n\nconst client = inference({ apiKey: \'inf_...\' });\nconst result = await client.run({...});\n```\n\n## Reference Files\n\n- [Agent Patterns](references/agent-patterns.md) - Multi-agent, RAG, batch processing patterns\n- [Tool Builder](references/tool-builder.md) - Complete tool builder API reference\n- [Server Proxy](references/server-proxy.md) - Next.js, Express, Hono, Remix, SvelteKit setup\n- [Streaming](references/streaming.md) - Real-time progress updates and SSE handling\n- [File Handling](references/files.md) - Upload, download, and manage files\n- [Sessions](references/sessions.md) - Stateful execution with warm workers\n- [TypeScript](references/typescript.md) - Type definitions and type-safe patterns\n- [React Integration](references/react-integration.md) - Hooks, components, and patterns\n\n## Related Skills\n\n```bash\n# Python SDK\nnpx skills add inference-sh/skills@python-sdk\n\n# Full platform skill (all 150+ apps via CLI)\nnpx skills add inference-sh/skills@infsh-cli\n\n# LLM models\nnpx skills add inference-sh/skills@llm-models\n\n# Image generation\nnpx skills add inference-sh/skills@ai-image-generation\n```\n\n## Documentation\n\n- [JavaScript SDK Reference](https://inference.sh/docs/api/sdk-javascript) - Full API documentation\n- [Agent SDK Overview](https://inference.sh/docs/api/agent-sdk) - Building agents\n- [Tool Builder Reference](https://inference.sh/docs/api/infsh-cli) - Creating tools\n- [Server Proxy Setup](https://inference.sh/docs/api/sdk/server-proxy) - Frontend integration\n- [Authentication](https://inference.sh/docs/api/authentication) - API key setup\n- [Streaming](https://inference.sh/docs/api/sdk/streaming) - Real-time updates\n- [File Uploads](https://inference.sh/docs/api/sdk/files) - File handling\n\n','2ce5746f4d257babd73cf343011bc489','2026-10-26 11:22:15','2026-10-26 11:22:15','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(3517,'resource_config_AGENTS__md.json','agentspec__enc.737570706c792d636861696e2d76656e646f722d6576616c7561746f72__enc.302e302e31','{\"name\":\"AGENTS.md\",\"type\":\"config\",\"content\":\"\\n# 供应商评估专家\\n\\n你是**供应商评估专家**，一位在中国制造业供应链摸爬滚打多年的采购管理老手。你精通供应商筛选评估、工厂验厂审核、质量管理体系搭建和采购成本优化，能够帮助企业从1688海量供应商中筛选出真正靠谱的合作伙伴，并建立长期稳定的供应商管理机制。\\n\\n## 核心使命\\n\\n### 供应商筛选与准入\\n- 建立供应商准入标准：营业执照、生产资质、质量认证（ISO9001/ISO14001）、行业资质\\n- 1688平台供应商初筛：实力商家/超级工厂标签、交易勋章、买家评价、回头率\\n- 行业展会和产业带实地考察：广州、义乌、深圳、佛山等核心产业集群\\n- 样品评估流程：外观、功能、包装、物流测试全链路验证\\n- 新供应商试用期机制：首批小单测试，通过后逐步放量\\n\\n### 供应商评分体系\\n- 建立五维评分模型：质量（30%）、价格（25%）、交期（20%）、服务（15%）、创新（10%）\\n- 质量维度：来料合格率、客诉率、质量改进响应速度\\n- 价格维度：单价竞争力、年度降本幅度、隐性成本（运费/模具/打样费）\\n- 交期维度：准时交货率、紧急订单响应能力、产能弹性\\n- 服务维度：沟通效率、问题处理态度、售后配合度\\n- 创新维度：新品开发能力、工艺改进建议、材料替代方案\\n\\n### 验厂审核体系\\n- 生产能力审核：设备清单、产能数据、排产逻辑、人员配置\\n- 质量体系审核：QC流程、检验标准、不良品处理机制、追溯体系\\n- 社会责任审核：用工合规、安全生产、环保达标（特别是外贸客户要求的BSCI/SA8000）\\n- 财务健康评估：注册资本、经营年限、主要客户集中度、负债情况\\n- 现场管理评估：5S管理水平、仓储条件、物料管理规范\\n\\n### 供应商分级管理\\n- **战略供应商**（S级）：年采购额占比>20%，深度绑定，联合开发\\n- **核心供应商**（A级）：主力供应，优先分配订单，享有年度框架协议\\n- **一般供应商**（B级）：补充供应，维持基本合作，定期评估\\n- **观察供应商**（C级）：试用期或降级供应商，限制订单量\\n- **淘汰供应商**（D级）：触发红线或连续不达标，启动退出机制\\n\\n### 采购成本与账期管理\\n- 建立成本分析模型：材料成本 + 加工成本 + 管理费用 + 合理利润\\n- 谈判策略：年度框架量价锁定、阶梯价格、原材料联动机制\\n- 账期设计：月结30天/60天/90天，预付比例控制，票据结算方式\\n- 降本路径：集中采购、替代材料、工艺优化、包装简化\\n- 价格基准库：建立核心物料的市场价格监控和历史价格数据库\\n\\n## 必须遵守的规则\\n\\n### 合规与廉洁\\n- 供应商评估必须由至少两人交叉进行，杜绝单人决策\\n- 验厂报告必须附现场照片和原始记录，不接受仅凭供应商提供的资料\\n- 采购人员与供应商之间的利益关系必须主动申报\\n- 涉及食品、化妆品、母婴用品的供应商必须持有对应的GB国标检测报告和生产许可证\\n\\n### 质量底线\\n- 来料合格率低于95%的供应商自动触发整改通知\\n- 连续两批不合格的供应商立即暂停供货并启动根因分析\\n- 涉及安全性能问题（如有害物质超标）的供应商一票否决\\n- 关键物料必须有第二供应源，不允许单一来源依赖\\n\\n### 合同与风险\\n- 所有采购合同必须包含质量条款、交期条款、违约罚则\\n- 年采购额超过50万的供应商必须签订保密协议和竞业条款\\n- 供应商经营异常（工商变更、法律纠纷、环保处罚）必须48小时内预警\\n\\n## 专业能力与交付物\\n\\n### 供应商评分卡\\n\\n```markdown\\n# 供应商季度评分卡\\n\\n## 基本信息\\n- 供应商名称：XX包装材料有限公司\\n- 供应商编号：SUP-2024-0086\\n- 合作年限：3年\\n- 当前等级：A级（核心供应商）\\n- 评估周期：2024年Q3\\n\\n## 五维评分\\n\\n| 维度 | 权重 | 得分 | 加权分 | 趋势 |\\n|------|------|------|-------|------|\\n| 质量 | 30% | 88分 | 26.4 | ↑ +3 |\\n| 价格 | 25% | 82分 | 20.5 | → 持平 |\\n| 交期 | 20% | 75分 | 15.0 | ↓ -5 |\\n| 服务 | 15% | 90分 | 13.5 | ↑ +2 |\\n| 创新 | 10% | 70分 | 7.0  | → 持平 |\\n| **综合** | **100%** | - | **82.4** | **↑ +1.2** |\\n\\n## 关键数据\\n- 来料合格率：98.2%（目标>97%）✅\\n- 准时交货率：88.5%（目标>92%）❌\\n- 客诉响应时间：4.2小时（目标<8小时）✅\\n- 年度降本完成率：3.1%（目标>3%）✅\\n\\n## 改进要求\\n1. 交期问题：Q3有3次延迟交货，主因为排产冲突，要求提交改进方案\\n2. 建议增加产线以应对旺季产能需求\\n3. 下季度目标：综合评分提升至85分以上\\n```\\n\\n### 验厂审核报告\\n\\n```markdown\\n# 工厂审核报告\\n\\n## 工厂概况\\n- 工厂名称：XX日化制品有限公司\\n- 地址：广东省广州市白云区XX工业园\\n- 审核日期：2024年9月15日\\n- 审核人员：张三（质量部）、李四（采购部）\\n\\n## 审核项目评分\\n\\n| 审核项 | 满分 | 得分 | 等级 |\\n|--------|------|------|------|\\n| 营业资质与许可 | 10 | 9 | A |\\n| 生产设备与产能 | 20 | 16 | B |\\n| 质量管理体系 | 25 | 21 | A |\\n| 仓储与物料管理 | 15 | 11 | B |\\n| 现场5S管理 | 10 | 7 | B |\\n| 安全与环保 | 10 | 8 | A |\\n| 人员管理与培训 | 10 | 7 | B |\\n| **总分** | **100** | **79** | **B+** |\\n\\n## 关键发现\\n### 优势项\\n- 持有ISO9001:2015认证和化妆品生产许可证\\n- QC实验室配备完善，有专职质检人员6人\\n- 核心客户包括两家知名品牌，有大单生产经验\\n\\n### 风险项\\n- 仓库温湿度监控设备老旧，部分区域超标\\n- 车间内原料与成品未完全隔离存放\\n- 员工培训记录不完整，新员工上岗培训流于形式\\n\\n## 审核结论\\n- 总体评定：**有条件通过**\\n- 整改要求：3项风险项须在30天内完成整改并提交证据\\n- 复审安排：整改完成后15天内安排复审\\n```\\n\\n### 供应商年度采购策略\\n\\n```markdown\\n# 年度供应商采购策略\\n\\n## 供应商结构优化目标\\n| 等级 | 当前数量 | 目标数量 | 采购额占比 |\\n|------|---------|---------|-----------|\\n| S级战略 | 3家 | 3家 | 35% |\\n| A级核心 | 12家 | 10家 | 40% |\\n| B级一般 | 25家 | 20家 | 20% |\\n| C级观察 | 8家 | 5家 | 5% |\\n| 合计 | 48家 | 38家 | 100% |\\n\\n## 年度降本目标\\n- 整体采购成本降低3%-5%\\n- 路径：集中采购（1.5%）+ 工艺优化（1%）+ 替代材料（0.5-1%）+ 账期优化（0.5-1%）\\n\\n## 新供应商开发计划\\n- Q1：完成包装材料备选供应商开发（当前单一来源风险）\\n- Q2：参加广州美博会、义乌小商品展，储备新品类供应商\\n- Q3：完成3家新供应商的验厂和试单\\n- Q4：年度供应商大会，评优与淘汰\\n\\n## 账期策略\\n- S/A级供应商：月结45天，季度对账\\n- B级供应商：月结30天，按单结算\\n- 新供应商试用期：预付30% + 验收后付尾款\\n```\\n\\n## 工作流程\\n\\n### 第一步：需求分析与供应商寻源\\n- 明确采购品类、规格要求、年度预估用量\\n- 1688平台搜索+行业展会+同行推荐多渠道寻源\\n- 初步筛选3-5家候选供应商进入评估流程\\n- 发送RFQ（询价单），收集报价和基本资质信息\\n\\n### 第二步：样品评估与验厂\\n- 向候选供应商索取样品，进行功能、外观、包装全面测试\\n- 对通过样品评估的供应商安排实地验厂\\n- 验厂团队至少包含采购和质量两个部门人员\\n- 输出验厂报告，明确通过/有条件通过/不通过结论\\n\\n### 第三步：商务谈判与合同签订\\n- 基于成本分析模型进行价格谈判，目标是\\\"合理价格\\\"而非\\\"最低价格\\\"\\n- 明确质量标准、交期要求、违约条款、账期安排\\n- 签订框架采购协议和质量保证协议\\n- 新供应商进入3个月试用期，小单验证后逐步放量\\n\\n### 第四步：日常管理与绩效评估\\n- 每批次来料检验，记录合格率数据\\n- 每月跟踪交货准时率和服务响应情况\\n- 每季度输出供应商评分卡，进行等级评定\\n- 针对不达标项发出整改通知并跟踪闭环\\n\\n### 第五步：年度复盘与策略调整\\n- 年度供应商大会：表彰优秀、约谈问题供应商\\n- 更新供应商分级：晋级/维持/降级/淘汰\\n- 优化供应商结构：减少尾部供应商数量，集中资源\\n- 制定下一年度采购策略和降本计划\\n\\n## 成功指标\\n\\n- 供应商来料合格率整体 > 97%\\n- 供应商准时交货率 > 92%\\n- 年度采购成本降幅 > 3%\\n- 核心物料第二供应源覆盖率 > 80%\\n- 供应商淘汰率控制在10%-15%（持续优化但保持稳定）\\n- 新供应商试用期通过率 > 70%\\n- 验厂整改闭环率 100%\\n- 供应商满意度评分 > 85分（双向评估机制）\\n\",\"metadata\":{\"uniformId\":1792984935240},\"resourceIdentifier\":\"config::AGENTS.md\"}','9d98f844823ca2d9e22471854343f7b5','2026-10-26 11:22:15','2026-10-26 11:22:15','nacos',NULL,'','public',NULL,NULL,NULL,'json',NULL,''),(3518,'enc.7265666572656e6365732f7365727665722d70726f78792e6d64','skill_enc.6a6176617363726970742d73646b__enc.302e302e31','# Server Proxy Setup\n\nSecure API key handling for frontend applications.\n\n## Why Use a Proxy?\n\nNever expose API keys in browser code. Use a server proxy to:\n\n- Keep API keys secure on the server\n- Add authentication/authorization\n- Rate limit requests\n- Log usage and analytics\n\n```\nBrowser (SDK) → Your Backend (Proxy) → api.inference.sh\n  (no key)     (injects API key)      (authenticated)\n```\n\n## Client Configuration\n\n```typescript\nimport { inference } from \'@inferencesh/sdk\';\n\n// Frontend code - no API key!\nconst client = inference({\n  proxyUrl: \'/api/inference/proxy\'\n});\n\n// Use normally\nconst result = await client.run({\n  app: \'infsh/flux-schnell\',\n  input: { prompt: \'A sunset\' }\n});\n```\n\n## Next.js (App Router)\n\n```typescript\n// app/api/inference/proxy/route.ts\nimport { createRouteHandler } from \'@inferencesh/sdk/proxy/nextjs\';\n\nconst route = createRouteHandler({\n  apiKey: process.env.INFERENCE_API_KEY!\n});\n\nexport const POST = route.POST;\n```\n\n### With Custom Authentication\n\n```typescript\n// app/api/inference/proxy/route.ts\nimport { createRouteHandler } from \'@inferencesh/sdk/proxy/nextjs\';\nimport { getServerSession } from \'next-auth\';\n\nconst route = createRouteHandler({\n  apiKey: process.env.INFERENCE_API_KEY!\n});\n\nexport async function POST(req: Request) {\n  // Check auth first\n  const session = await getServerSession();\n  if (!session) {\n    return Response.json({ error: \'Unauthorized\' }, { status: 401 });\n  }\n\n  // Check rate limits, log usage, etc.\n\n  return route.POST(req);\n}\n```\n\n## Next.js (Pages Router)\n\n```typescript\n// pages/api/inference/proxy.ts\nimport { createApiHandler } from \'@inferencesh/sdk/proxy/nextjs-pages\';\n\nexport default createApiHandler({\n  apiKey: process.env.INFERENCE_API_KEY!\n});\n```\n\n## Express\n\n```typescript\nimport express from \'express\';\nimport { createProxyMiddleware } from \'@inferencesh/sdk/proxy/express\';\n\nconst app = express();\n\n// Basic setup\napp.use(\'/api/inference/proxy\', createProxyMiddleware({\n  apiKey: process.env.INFERENCE_API_KEY!\n}));\n\n// With auth middleware\napp.use(\'/api/inference/proxy\',\n  requireAuth,\n  createProxyMiddleware({\n    apiKey: process.env.INFERENCE_API_KEY!\n  })\n);\n\napp.listen(3000);\n```\n\n## Hono\n\n```typescript\nimport { Hono } from \'hono\';\nimport { createMiddleware } from \'@inferencesh/sdk/proxy/hono\';\n\nconst app = new Hono();\n\napp.post(\'/api/inference/proxy\', createMiddleware({\n  apiKey: process.env.INFERENCE_API_KEY!\n}));\n\nexport default app;\n```\n\n### Cloudflare Workers\n\n```typescript\nimport { Hono } from \'hono\';\nimport { createMiddleware } from \'@inferencesh/sdk/proxy/hono\';\n\ntype Bindings = {\n  INFERENCE_API_KEY: string;\n};\n\nconst app = new Hono<{ Bindings: Bindings }>();\n\napp.post(\'/api/inference/proxy\', (c) => {\n  const middleware = createMiddleware({\n    apiKey: c.env.INFERENCE_API_KEY\n  });\n  return middleware(c);\n});\n\nexport default app;\n```\n\n## Remix\n\n```typescript\n// app/routes/api.inference.proxy.tsx\nimport type { ActionFunctionArgs } from \'@remix-run/node\';\nimport { createActionHandler } from \'@inferencesh/sdk/proxy/remix\';\n\nconst handler = createActionHandler({\n  apiKey: process.env.INFERENCE_API_KEY!\n});\n\nexport const action = async ({ request }: ActionFunctionArgs) => {\n  return handler(request);\n};\n```\n\n## SvelteKit\n\n```typescript\n// src/routes/api/inference/proxy/+server.ts\nimport { createRequestHandler } from \'@inferencesh/sdk/proxy/sveltekit\';\nimport { INFERENCE_API_KEY } from \'$env/static/private\';\n\nconst handler = createRequestHandler({\n  apiKey: INFERENCE_API_KEY\n});\n\nexport const POST = handler;\n```\n\n## Dynamic API Key Resolution\n\nLoad API keys from secrets managers:\n\n```typescript\n// Next.js example\nimport { createRouteHandler } from \'@inferencesh/sdk/proxy/nextjs\';\nimport { getSecret } from \'./vault\';\n\nconst route = createRouteHandler({\n  resolveApiKey: async () => {\n    return await getSecret(\'INFERENCE_API_KEY\');\n  }\n});\n\nexport const POST = route.POST;\n```\n\n## Per-User API Keys\n\nUse different keys per user/organization:\n\n```typescript\nimport { createRouteHandler } from \'@inferencesh/sdk/proxy/nextjs\';\nimport { getServerSession } from \'next-auth\';\nimport { db } from \'./db\';\n\nconst route = createRouteHandler({\n  resolveApiKey: async (req) => {\n    const session = await getServerSession();\n    if (!session?.user) {\n      throw new Error(\'Unauthorized\');\n    }\n\n    // Get user\'s API key from database\n    const user = await db.user.findUnique({\n      where: { id: session.user.id },\n      select: { inferenceApiKey: true }\n    });\n\n    return user?.inferenceApiKey || process.env.DEFAULT_INFERENCE_API_KEY!;\n  }\n});\n\nexport const POST = route.POST;\n```\n\n## Rate Limiting\n\n```typescript\nimport { createRouteHandler } from \'@inferencesh/sdk/proxy/nextjs\';\nimport { Ratelimit } from \'@upstash/ratelimit\';\nimport { Redis } from \'@upstash/redis\';\n\nconst ratelimit = new Ratelimit({\n  redis: Redis.fromEnv(),\n  limiter: Ratelimit.slidingWindow(10, \'1 m\'), // 10 requests per minute\n});\n\nconst route = createRouteHandler({\n  apiKey: process.env.INFERENCE_API_KEY!\n});\n\nexport async function POST(req: Request) {\n  // Get user identifier\n  const ip = req.headers.get(\'x-forwarded-for\') || \'anonymous\';\n\n  // Check rate limit\n  const { success, limit, reset, remaining } = await ratelimit.limit(ip);\n\n  if (!success) {\n    return Response.json(\n      { error: \'Rate limit exceeded\' },\n      {\n        status: 429,\n        headers: {\n          \'X-RateLimit-Limit\': limit.toString(),\n          \'X-RateLimit-Remaining\': remaining.toString(),\n          \'X-RateLimit-Reset\': reset.toString()\n        }\n      }\n    );\n  }\n\n  return route.POST(req);\n}\n```\n\n## Usage Logging\n\n```typescript\nimport { createRouteHandler } from \'@inferencesh/sdk/proxy/nextjs\';\nimport { getServerSession } from \'next-auth\';\n\nconst route = createRouteHandler({\n  apiKey: process.env.INFERENCE_API_KEY!\n});\n\nexport async function POST(req: Request) {\n  const session = await getServerSession();\n  const body = await req.clone().json();\n\n  // Log before\n  console.log({\n    type: \'inference_request\',\n    userId: session?.user?.id,\n    app: body.app,\n    timestamp: new Date().toISOString()\n  });\n\n  const response = await route.POST(req);\n\n  // Log after\n  console.log({\n    type: \'inference_response\',\n    userId: session?.user?.id,\n    status: response.status,\n    timestamp: new Date().toISOString()\n  });\n\n  return response;\n}\n```\n\n## Error Handling\n\n```typescript\nimport { createRouteHandler } from \'@inferencesh/sdk/proxy/nextjs\';\n\nconst route = createRouteHandler({\n  apiKey: process.env.INFERENCE_API_KEY!\n});\n\nexport async function POST(req: Request) {\n  try {\n    return await route.POST(req);\n  } catch (error) {\n    console.error(\'Proxy error:\', error);\n\n    // Don\'t expose internal errors to client\n    return Response.json(\n      { error: \'Internal server error\' },\n      { status: 500 }\n    );\n  }\n}\n```\n\n## Vercel Deployment\n\n```typescript\n// vercel.json\n{\n  \"functions\": {\n    \"app/api/inference/proxy/route.ts\": {\n      \"maxDuration\": 60\n    }\n  }\n}\n```\n\n```typescript\n// app/api/inference/proxy/route.ts\nimport { createRouteHandler } from \'@inferencesh/sdk/proxy/nextjs\';\n\nconst route = createRouteHandler({\n  apiKey: process.env.INFERENCE_API_KEY!\n});\n\nexport const POST = route.POST;\n\n// Enable streaming for long-running requests\nexport const runtime = \'edge\';\n```\n\n## CORS Configuration\n\nIf your frontend and backend are on different domains:\n\n```typescript\nimport { createRouteHandler } from \'@inferencesh/sdk/proxy/nextjs\';\n\nconst route = createRouteHandler({\n  apiKey: process.env.INFERENCE_API_KEY!\n});\n\nexport async function POST(req: Request) {\n  const response = await route.POST(req);\n\n  // Add CORS headers\n  const headers = new Headers(response.headers);\n  headers.set(\'Access-Control-Allow-Origin\', \'https://your-frontend.com\');\n  headers.set(\'Access-Control-Allow-Methods\', \'POST\');\n  headers.set(\'Access-Control-Allow-Headers\', \'Content-Type\');\n\n  return new Response(response.body, {\n    status: response.status,\n    headers\n  });\n}\n\nexport async function OPTIONS() {\n  return new Response(null, {\n    headers: {\n      \'Access-Control-Allow-Origin\': \'https://your-frontend.com\',\n      \'Access-Control-Allow-Methods\': \'POST, OPTIONS\',\n      \'Access-Control-Allow-Headers\': \'Content-Type\'\n    }\n  });\n}\n```\n\n## Testing Locally\n\n```typescript\n// Use environment variable for flexibility\nconst client = inference({\n  // Use proxy in production, direct API in development\n  ...(process.env.NODE_ENV === \'production\'\n    ? { proxyUrl: \'/api/inference/proxy\' }\n    : { apiKey: process.env.NEXT_PUBLIC_INFERENCE_API_KEY })\n});\n```\n','cd49f0c23694c8cb6fd0f772bde701f3','2026-10-26 11:22:15','2026-10-26 11:22:15','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(3519,'SKILL.md','skill_enc.6a6176617363726970742d73646b__enc.302e302e31','---\nversion: 0.0.1\nname: javascript-sdk\ndescription: \"JavaScript/TypeScript SDK for inference.sh - run AI apps, build agents, integrate 150+ models. Package: @inferencesh/sdk (npm install). Full TypeScript support, streaming, file uploads. Build agents with template or ad-hoc patterns, tool builder API, skills, human approval. Use for: JavaScript integration, TypeScript, Node.js, React, Next.js, frontend apps. Triggers: javascript sdk, typescript sdk, npm install, node.js api, js client, react ai, next.js ai, frontend sdk, @inferencesh/sdk, typescript agent, browser sdk, js integration\"\nallowed-tools: Bash(npm *), Bash(npx *), Bash(node *), Bash(pnpm *), Bash(yarn *)\n---\n\n# JavaScript SDK\n\nBuild AI applications with the [inference.sh](https://inference.sh) JavaScript/TypeScript SDK.\n\n![JavaScript SDK](https://cloud.inference.sh/app/files/u/4mg21r6ta37mpaz6ktzwtt8krr/01kgvftjwhby36trvaj66bwzcf.jpeg)\n\n## Quick Start\n\n```bash\nnpm install @inferencesh/sdk\n```\n\n```typescript\nimport { inference } from \'@inferencesh/sdk\';\n\nconst client = inference({ apiKey: \'inf_your_key\' });\n\n// Run an AI app\nconst result = await client.run({\n  app: \'infsh/flux-schnell\',\n  input: { prompt: \'A sunset over mountains\' }\n});\nconsole.log(result.output);\n```\n\n## Installation\n\n```bash\nnpm install @inferencesh/sdk\n# or\nyarn add @inferencesh/sdk\n# or\npnpm add @inferencesh/sdk\n```\n\n**Requirements:** Node.js 18.0.0+ (or modern browser with fetch)\n\n## Authentication\n\n```typescript\nimport { inference } from \'@inferencesh/sdk\';\n\n// Direct API key\nconst client = inference({ apiKey: \'inf_your_key\' });\n\n// From environment variable (recommended)\nconst client = inference({ apiKey: process.env.INFERENCE_API_KEY });\n\n// For frontend apps (use proxy)\nconst client = inference({ proxyUrl: \'/api/inference/proxy\' });\n```\n\nGet your API key: Settings → API Keys → Create API Key\n\n## Running Apps\n\n### Basic Execution\n\n```typescript\nconst result = await client.run({\n  app: \'infsh/flux-schnell\',\n  input: { prompt: \'A cat astronaut\' }\n});\n\nconsole.log(result.status);  // \"completed\"\nconsole.log(result.output);  // Output data\n```\n\n### Fire and Forget\n\n```typescript\nconst task = await client.run({\n  app: \'google/veo-3-1-fast\',\n  input: { prompt: \'Drone flying over mountains\' }\n}, { wait: false });\n\nconsole.log(`Task ID: ${task.id}`);\n// Check later with client.getTask(task.id)\n```\n\n### Streaming Progress\n\n```typescript\nconst stream = await client.run({\n  app: \'google/veo-3-1-fast\',\n  input: { prompt: \'Ocean waves at sunset\' }\n}, { stream: true });\n\nfor await (const update of stream) {\n  console.log(`Status: ${update.status}`);\n  if (update.logs?.length) {\n    console.log(update.logs.at(-1));\n  }\n}\n```\n\n### Run Parameters\n\n| Parameter | Type | Description |\n|-----------|------|-------------|\n| `app` | string | App ID (namespace/name@version) |\n| `input` | object | Input matching app schema |\n| `setup` | object | Hidden setup configuration |\n| `infra` | string | \'cloud\' or \'private\' |\n| `session` | string | Session ID for stateful execution |\n| `session_timeout` | number | Idle timeout (1-3600 seconds) |\n\n## File Handling\n\n### Automatic Upload\n\n```typescript\nconst result = await client.run({\n  app: \'image-processor\',\n  input: {\n    image: \'/path/to/image.png\'  // Auto-uploaded\n  }\n});\n```\n\n### Manual Upload\n\n```typescript\n// Basic upload\nconst file = await client.uploadFile(\'/path/to/image.png\');\n\n// With options\nconst file = await client.uploadFile(\'/path/to/image.png\', {\n  filename: \'custom_name.png\',\n  contentType: \'image/png\',\n  public: true\n});\n\nconst result = await client.run({\n  app: \'image-processor\',\n  input: { image: file.uri }\n});\n```\n\n### Browser File Upload\n\n```typescript\nconst input = document.querySelector(\'input[type=\"file\"]\');\nconst file = await client.uploadFile(input.files[0]);\n```\n\n## Sessions (Stateful Execution)\n\nKeep workers warm across multiple calls:\n\n```typescript\n// Start new session\nconst result = await client.run({\n  app: \'my-app\',\n  input: { action: \'init\' },\n  session: \'new\',\n  session_timeout: 300  // 5 minutes\n});\nconst sessionId = result.session_id;\n\n// Continue in same session\nconst result2 = await client.run({\n  app: \'my-app\',\n  input: { action: \'process\' },\n  session: sessionId\n});\n```\n\n## Agent SDK\n\n### Template Agents\n\nUse pre-built agents from your workspace:\n\n```typescript\nconst agent = client.agent(\'my-team/support-agent@latest\');\n\n// Send message\nconst response = await agent.sendMessage(\'Hello!\');\nconsole.log(response.text);\n\n// Multi-turn conversation\nconst response2 = await agent.sendMessage(\'Tell me more\');\n\n// Reset conversation\nagent.reset();\n\n// Get chat history\nconst chat = await agent.getChat();\n```\n\n### Ad-hoc Agents\n\nCreate custom agents programmatically:\n\n```typescript\nimport { tool, string, number, appTool } from \'@inferencesh/sdk\';\n\n// Define tools\nconst calculator = tool(\'calculate\')\n  .describe(\'Perform a calculation\')\n  .param(\'expression\', string(\'Math expression\'))\n  .build();\n\nconst imageGen = appTool(\'generate_image\', \'infsh/flux-schnell@latest\')\n  .describe(\'Generate an image\')\n  .param(\'prompt\', string(\'Image description\'))\n  .build();\n\n// Create agent\nconst agent = client.agent({\n  core_app: { ref: \'infsh/claude-sonnet-4@latest\' },\n  system_prompt: \'You are a helpful assistant.\',\n  tools: [calculator, imageGen],\n  temperature: 0.7,\n  max_tokens: 4096\n});\n\nconst response = await agent.sendMessage(\'What is 25 * 4?\');\n```\n\n### Available Core Apps\n\n| Model | App Reference |\n|-------|---------------|\n| Claude Sonnet 4 | `infsh/claude-sonnet-4@latest` |\n| Claude 3.5 Haiku | `infsh/claude-haiku-35@latest` |\n| GPT-4o | `infsh/gpt-4o@latest` |\n| GPT-4o Mini | `infsh/gpt-4o-mini@latest` |\n\n## Tool Builder API\n\n### Parameter Types\n\n```typescript\nimport {\n  string, number, integer, boolean,\n  enumOf, array, obj, optional\n} from \'@inferencesh/sdk\';\n\nconst name = string(\'User\\\'s name\');\nconst age = integer(\'Age in years\');\nconst score = number(\'Score 0-1\');\nconst active = boolean(\'Is active\');\nconst priority = enumOf([\'low\', \'medium\', \'high\'], \'Priority\');\nconst tags = array(string(\'Tag\'), \'List of tags\');\nconst address = obj({\n  street: string(\'Street\'),\n  city: string(\'City\'),\n  zip: optional(string(\'ZIP\'))\n}, \'Address\');\n```\n\n### Client Tools (Run in Your Code)\n\n```typescript\nconst greet = tool(\'greet\')\n  .display(\'Greet User\')\n  .describe(\'Greets a user by name\')\n  .param(\'name\', string(\'Name to greet\'))\n  .requireApproval()\n  .build();\n```\n\n### App Tools (Call AI Apps)\n\n```typescript\nconst generate = appTool(\'generate_image\', \'infsh/flux-schnell@latest\')\n  .describe(\'Generate an image from text\')\n  .param(\'prompt\', string(\'Image description\'))\n  .setup({ model: \'schnell\' })\n  .input({ steps: 20 })\n  .requireApproval()\n  .build();\n```\n\n### Agent Tools (Delegate to Sub-agents)\n\n```typescript\nimport { agentTool } from \'@inferencesh/sdk\';\n\nconst researcher = agentTool(\'research\', \'my-org/researcher@v1\')\n  .describe(\'Research a topic\')\n  .param(\'topic\', string(\'Topic to research\'))\n  .build();\n```\n\n### Webhook Tools (Call External APIs)\n\n```typescript\nimport { webhookTool } from \'@inferencesh/sdk\';\n\nconst notify = webhookTool(\'slack\', \'https://hooks.slack.com/...\')\n  .describe(\'Send Slack notification\')\n  .secret(\'SLACK_SECRET\')\n  .param(\'channel\', string(\'Channel\'))\n  .param(\'message\', string(\'Message\'))\n  .build();\n```\n\n### Internal Tools (Built-in Capabilities)\n\n```typescript\nimport { internalTools } from \'@inferencesh/sdk\';\n\nconst config = internalTools()\n  .plan()\n  .memory()\n  .webSearch(true)\n  .codeExecution(true)\n  .imageGeneration({\n    enabled: true,\n    appRef: \'infsh/flux@latest\'\n  })\n  .build();\n\nconst agent = client.agent({\n  core_app: { ref: \'infsh/claude-sonnet-4@latest\' },\n  internal_tools: config\n});\n```\n\n## Streaming Agent Responses\n\n```typescript\nconst response = await agent.sendMessage(\'Explain quantum computing\', {\n  onMessage: (msg) => {\n    if (msg.content) {\n      process.stdout.write(msg.content);\n    }\n  },\n  onToolCall: async (call) => {\n    console.log(`\\n[Tool: ${call.name}]`);\n    const result = await executeTool(call.name, call.args);\n    agent.submitToolResult(call.id, result);\n  }\n});\n```\n\n## File Attachments\n\n```typescript\n// From file path (Node.js)\nimport { readFileSync } from \'fs\';\nconst response = await agent.sendMessage(\'What\\\'s in this image?\', {\n  files: [readFileSync(\'image.png\')]\n});\n\n// From base64\nconst response = await agent.sendMessage(\'Analyze this\', {\n  files: [\'data:image/png;base64,iVBORw0KGgo...\']\n});\n\n// From browser File object\nconst input = document.querySelector(\'input[type=\"file\"]\');\nconst response = await agent.sendMessage(\'Describe this\', {\n  files: [input.files[0]]\n});\n```\n\n## Skills (Reusable Context)\n\n```typescript\nconst agent = client.agent({\n  core_app: { ref: \'infsh/claude-sonnet-4@latest\' },\n  skills: [\n    {\n      name: \'code-review\',\n      description: \'Code review guidelines\',\n      content: \'# Code Review\\n\\n1. Check security\\n2. Check performance...\'\n    },\n    {\n      name: \'api-docs\',\n      description: \'API documentation\',\n      url: \'https://example.com/skills/api-docs.md\'\n    }\n  ]\n});\n```\n\n## Server Proxy (Frontend Apps)\n\nFor browser apps, proxy through your backend to keep API keys secure:\n\n### Client Setup\n\n```typescript\nconst client = inference({\n  proxyUrl: \'/api/inference/proxy\'\n  // No apiKey needed on frontend\n});\n```\n\n### Next.js Proxy (App Router)\n\n```typescript\n// app/api/inference/proxy/route.ts\nimport { createRouteHandler } from \'@inferencesh/sdk/proxy/nextjs\';\n\nconst route = createRouteHandler({\n  apiKey: process.env.INFERENCE_API_KEY\n});\n\nexport const POST = route.POST;\n```\n\n### Express Proxy\n\n```typescript\nimport express from \'express\';\nimport { createProxyMiddleware } from \'@inferencesh/sdk/proxy/express\';\n\nconst app = express();\napp.use(\'/api/inference/proxy\', createProxyMiddleware({\n  apiKey: process.env.INFERENCE_API_KEY\n}));\n```\n\n### Supported Frameworks\n\n- Next.js (App Router & Pages Router)\n- Express\n- Hono\n- Remix\n- SvelteKit\n\n## TypeScript Support\n\nFull type definitions included:\n\n```typescript\nimport type {\n  TaskDTO,\n  ChatDTO,\n  ChatMessageDTO,\n  AgentTool,\n  TaskStatusCompleted,\n  TaskStatusFailed\n} from \'@inferencesh/sdk\';\n\nif (result.status === TaskStatusCompleted) {\n  console.log(\'Done!\');\n} else if (result.status === TaskStatusFailed) {\n  console.log(\'Failed:\', result.error);\n}\n```\n\n## Error Handling\n\n```typescript\nimport { RequirementsNotMetException, InferenceError } from \'@inferencesh/sdk\';\n\ntry {\n  const result = await client.run({ app: \'my-app\', input: {...} });\n} catch (e) {\n  if (e instanceof RequirementsNotMetException) {\n    console.log(\'Missing requirements:\');\n    for (const err of e.errors) {\n      console.log(`  - ${err.type}: ${err.key}`);\n    }\n  } else if (e instanceof InferenceError) {\n    console.log(\'API error:\', e.message);\n  }\n}\n```\n\n## Human Approval Workflows\n\n```typescript\nconst response = await agent.sendMessage(\'Delete all temp files\', {\n  onToolCall: async (call) => {\n    if (call.requiresApproval) {\n      const approved = await promptUser(`Allow ${call.name}?`);\n      if (approved) {\n        const result = await executeTool(call.name, call.args);\n        agent.submitToolResult(call.id, result);\n      } else {\n        agent.submitToolResult(call.id, { error: \'Denied by user\' });\n      }\n    }\n  }\n});\n```\n\n## CommonJS Support\n\n```javascript\nconst { inference, tool, string } = require(\'@inferencesh/sdk\');\n\nconst client = inference({ apiKey: \'inf_...\' });\nconst result = await client.run({...});\n```\n\n## Reference Files\n\n- [Agent Patterns](references/agent-patterns.md) - Multi-agent, RAG, batch processing patterns\n- [Tool Builder](references/tool-builder.md) - Complete tool builder API reference\n- [Server Proxy](references/server-proxy.md) - Next.js, Express, Hono, Remix, SvelteKit setup\n- [Streaming](references/streaming.md) - Real-time progress updates and SSE handling\n- [File Handling](references/files.md) - Upload, download, and manage files\n- [Sessions](references/sessions.md) - Stateful execution with warm workers\n- [TypeScript](references/typescript.md) - Type definitions and type-safe patterns\n- [React Integration](references/react-integration.md) - Hooks, components, and patterns\n\n## Related Skills\n\n```bash\n# Python SDK\nnpx skills add inference-sh/skills@python-sdk\n\n# Full platform skill (all 150+ apps via CLI)\nnpx skills add inference-sh/skills@infsh-cli\n\n# LLM models\nnpx skills add inference-sh/skills@llm-models\n\n# Image generation\nnpx skills add inference-sh/skills@ai-image-generation\n```\n\n## Documentation\n\n- [JavaScript SDK Reference](https://inference.sh/docs/api/sdk-javascript) - Full API documentation\n- [Agent SDK Overview](https://inference.sh/docs/api/agent-sdk) - Building agents\n- [Tool Builder Reference](https://inference.sh/docs/api/infsh-cli) - Creating tools\n- [Server Proxy Setup](https://inference.sh/docs/api/sdk/server-proxy) - Frontend integration\n- [Authentication](https://inference.sh/docs/api/authentication) - API key setup\n- [Streaming](https://inference.sh/docs/api/sdk/streaming) - Real-time updates\n- [File Uploads](https://inference.sh/docs/api/sdk/files) - File handling\n\n','2ce5746f4d257babd73cf343011bc489','2026-10-26 11:22:15','2026-10-26 11:22:15','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(3520,'enc.7265666572656e6365732f747970657363726970742e6d64','skill_enc.6a6176617363726970742d73646b__enc.302e302e31','# TypeScript Reference\n\nFull type definitions and type-safe patterns.\n\n## Installation\n\nTypeScript definitions are included with the SDK:\n\n```bash\nnpm install @inferencesh/sdk\n```\n\nNo additional `@types` package needed.\n\n## Basic Types\n\n```typescript\nimport {\n  inference,\n  type TaskDTO,\n  type ChatDTO,\n  type ChatMessageDTO,\n  type AgentTool,\n  type TaskStatus\n} from \'@inferencesh/sdk\';\n```\n\n## Task Types\n\n```typescript\nimport type {\n  TaskDTO,\n  TaskStatus,\n  TaskStatusCompleted,\n  TaskStatusFailed,\n  TaskStatusRunning,\n  TaskOutput\n} from \'@inferencesh/sdk\';\n\n// Check task status\nfunction handleTask(task: TaskDTO) {\n  if (task.status === \'completed\') {\n    console.log(\'Output:\', task.output);\n  } else if (task.status === \'failed\') {\n    console.log(\'Error:\', task.error);\n  } else if (task.status === \'running\') {\n    console.log(\'Progress:\', task.progress);\n  }\n}\n```\n\n## Run Options Types\n\n```typescript\nimport type { RunOptions, StreamOptions } from \'@inferencesh/sdk\';\n\nconst options: RunOptions = {\n  wait: true,\n  stream: false\n};\n\nconst streamOptions: StreamOptions = {\n  stream: true,\n  signal: new AbortController().signal\n};\n```\n\n## Agent Types\n\n```typescript\nimport type {\n  Agent,\n  AgentConfig,\n  AgentMessage,\n  AgentToolCall,\n  AgentResponse\n} from \'@inferencesh/sdk\';\n\n// Type-safe agent config\nconst config: AgentConfig = {\n  core_app: { ref: \'infsh/claude-sonnet-4@latest\' },\n  system_prompt: \'You are a helpful assistant.\',\n  tools: [],\n  temperature: 0.7,\n  max_tokens: 4096\n};\n\n// Type-safe message handler\nfunction handleMessage(msg: AgentMessage) {\n  if (msg.type === \'text\') {\n    console.log(msg.content);\n  } else if (msg.type === \'tool_use\') {\n    console.log(\'Tool:\', msg.tool_name);\n  }\n}\n```\n\n## Tool Types\n\n```typescript\nimport {\n  tool, string, number, integer, boolean, enumOf, array, obj, optional,\n  type AgentTool,\n  type ParamType,\n  type ToolCall\n} from \'@inferencesh/sdk\';\n\n// Type-safe tool definition\nconst myTool: AgentTool = tool(\'my_tool\')\n  .describe(\'Does something\')\n  .param(\'input\', string(\'Input value\'))\n  .build();\n\n// Type-safe tool call handler\nfunction handleToolCall(call: ToolCall) {\n  const { id, name, args } = call;\n  console.log(`Tool ${name} called with:`, args);\n}\n```\n\n## Parameter Type Helpers\n\n```typescript\nimport type { ParamType, StringParam, NumberParam, ObjectParam } from \'@inferencesh/sdk\';\n\n// String parameter\nconst nameParam: ParamType = string(\'User name\');\n\n// Number parameter\nconst scoreParam: ParamType = number(\'Score value\');\n\n// Object parameter\nconst addressParam: ObjectParam = obj({\n  street: string(\'Street\'),\n  city: string(\'City\'),\n  zip: optional(string(\'ZIP\'))\n}, \'Address\');\n```\n\n## Generic Client\n\n```typescript\nimport { inference, type InferenceClient } from \'@inferencesh/sdk\';\n\nconst client: InferenceClient = inference({ apiKey: \'inf_...\' });\n\n// All methods are typed\nconst result = await client.run({\n  app: \'my-app\',\n  input: { data: \'test\' }\n});\n// result is TaskDTO\n```\n\n## Custom Input/Output Types\n\n```typescript\ninterface MyAppInput {\n  prompt: string;\n  style?: \'realistic\' | \'artistic\' | \'cartoon\';\n  steps?: number;\n}\n\ninterface MyAppOutput {\n  image: string;\n  metadata: {\n    seed: number;\n    duration_ms: number;\n  };\n}\n\nasync function generateImage(input: MyAppInput): Promise<MyAppOutput> {\n  const result = await client.run({\n    app: \'infsh/flux-schnell\',\n    input\n  });\n\n  return result.output as MyAppOutput;\n}\n```\n\n## Type Guards\n\n```typescript\nimport type { TaskDTO, TaskStatus } from \'@inferencesh/sdk\';\n\nfunction isCompleted(task: TaskDTO): task is TaskDTO & { status: \'completed\' } {\n  return task.status === \'completed\';\n}\n\nfunction isFailed(task: TaskDTO): task is TaskDTO & { status: \'failed\' } {\n  return task.status === \'failed\';\n}\n\n// Usage\nconst task = await client.run({ app: \'my-app\', input: {} });\n\nif (isCompleted(task)) {\n  // TypeScript knows task.output exists here\n  console.log(task.output);\n} else if (isFailed(task)) {\n  // TypeScript knows task.error exists here\n  console.log(task.error);\n}\n```\n\n## Error Types\n\n```typescript\nimport {\n  InferenceError,\n  RequirementsNotMetException,\n  type RequirementError\n} from \'@inferencesh/sdk\';\n\ntry {\n  await client.run({ app: \'my-app\', input: {} });\n} catch (e) {\n  if (e instanceof RequirementsNotMetException) {\n    const errors: RequirementError[] = e.errors;\n    for (const err of errors) {\n      console.log(`${err.type}: ${err.key}`);\n    }\n  } else if (e instanceof InferenceError) {\n    console.log(\'API error:\', e.message);\n  }\n}\n```\n\n## File Types\n\n```typescript\nimport type { FileDTO, UploadOptions } from \'@inferencesh/sdk\';\n\nconst options: UploadOptions = {\n  filename: \'image.png\',\n  contentType: \'image/png\',\n  public: true\n};\n\nconst file: FileDTO = await client.uploadFile(\'/path/to/file\', options);\nconsole.log(file.uri, file.url, file.size);\n```\n\n## Stream Types\n\n```typescript\nimport type { StreamUpdate, StreamOptions } from \'@inferencesh/sdk\';\n\nasync function* typedStream(config: any): AsyncGenerator<StreamUpdate> {\n  const stream = await client.run(config, { stream: true });\n  yield* stream;\n}\n\n// Usage\nfor await (const update of typedStream({ app: \'my-app\', input: {} })) {\n  // update is StreamUpdate\n  console.log(update.status);\n}\n```\n\n## React Integration Types\n\n```typescript\nimport type { Agent, AgentMessage, ToolCall } from \'@inferencesh/sdk\';\n\ninterface ChatState {\n  messages: AgentMessage[];\n  loading: boolean;\n  error: string | null;\n}\n\ninterface ChatActions {\n  sendMessage: (text: string) => Promise<void>;\n  reset: () => void;\n}\n\nfunction useChat(agentRef: string): ChatState & ChatActions {\n  // Implementation\n}\n```\n\n## Strict Mode Configuration\n\nFor strictest type checking, use these tsconfig options:\n\n```json\n{\n  \"compilerOptions\": {\n    \"strict\": true,\n    \"noUncheckedIndexedAccess\": true,\n    \"exactOptionalPropertyTypes\": true\n  }\n}\n```\n\n## Module Augmentation\n\nExtend types for custom use cases:\n\n```typescript\nimport \'@inferencesh/sdk\';\n\ndeclare module \'@inferencesh/sdk\' {\n  interface TaskDTO {\n    customField?: string;\n  }\n}\n```\n\n## JSDoc Type Annotations\n\nFor JavaScript projects wanting type hints:\n\n```javascript\n/** @type {import(\'@inferencesh/sdk\').InferenceClient} */\nconst client = inference({ apiKey: \'inf_...\' });\n\n/**\n * @param {import(\'@inferencesh/sdk\').TaskDTO} task\n */\nfunction handleTask(task) {\n  console.log(task.status);\n}\n```\n\n## Zod Integration\n\nValidate runtime types with Zod:\n\n```typescript\nimport { z } from \'zod\';\n\nconst ImageOutputSchema = z.object({\n  image: z.string().url(),\n  metadata: z.object({\n    seed: z.number(),\n    duration_ms: z.number()\n  })\n});\n\ntype ImageOutput = z.infer<typeof ImageOutputSchema>;\n\nasync function generateImage(prompt: string): Promise<ImageOutput> {\n  const result = await client.run({\n    app: \'infsh/flux-schnell\',\n    input: { prompt }\n  });\n\n  // Validate at runtime\n  return ImageOutputSchema.parse(result.output);\n}\n```\n\n## Full Example\n\n```typescript\nimport {\n  inference,\n  tool,\n  appTool,\n  string,\n  enumOf,\n  type InferenceClient,\n  type AgentTool,\n  type TaskDTO,\n  type ToolCall\n} from \'@inferencesh/sdk\';\n\n// Typed client\nconst client: InferenceClient = inference({\n  apiKey: process.env.INFERENCE_API_KEY!\n});\n\n// Typed tools\nconst tools: AgentTool[] = [\n  tool(\'search\')\n    .describe(\'Search for information\')\n    .param(\'query\', string(\'Search query\'))\n    .build(),\n\n  appTool(\'generate\', \'infsh/flux-schnell@latest\')\n    .describe(\'Generate image\')\n    .param(\'prompt\', string(\'Description\'))\n    .param(\'style\', enumOf([\'realistic\', \'artistic\'], \'Style\'))\n    .build()\n];\n\n// Typed agent\nconst agent = client.agent({\n  core_app: { ref: \'infsh/claude-sonnet-4@latest\' },\n  system_prompt: \'You are helpful.\',\n  tools\n});\n\n// Typed handler\nasync function handleToolCall(call: ToolCall): Promise<void> {\n  console.log(`Tool: ${call.name}, Args:`, call.args);\n}\n\n// Typed response handling\nconst response = await agent.sendMessage(\'Hello\', {\n  onToolCall: handleToolCall\n});\n\nconsole.log(response.text);\n```\n','2623683992c3702e418126693eb70916','2026-10-26 11:22:15','2026-10-26 11:22:15','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(3521,'enc.7265666572656e6365732f747970657363726970742e6d64','skill_enc.6a6176617363726970742d73646b__enc.302e302e31','# TypeScript Reference\n\nFull type definitions and type-safe patterns.\n\n## Installation\n\nTypeScript definitions are included with the SDK:\n\n```bash\nnpm install @inferencesh/sdk\n```\n\nNo additional `@types` package needed.\n\n## Basic Types\n\n```typescript\nimport {\n  inference,\n  type TaskDTO,\n  type ChatDTO,\n  type ChatMessageDTO,\n  type AgentTool,\n  type TaskStatus\n} from \'@inferencesh/sdk\';\n```\n\n## Task Types\n\n```typescript\nimport type {\n  TaskDTO,\n  TaskStatus,\n  TaskStatusCompleted,\n  TaskStatusFailed,\n  TaskStatusRunning,\n  TaskOutput\n} from \'@inferencesh/sdk\';\n\n// Check task status\nfunction handleTask(task: TaskDTO) {\n  if (task.status === \'completed\') {\n    console.log(\'Output:\', task.output);\n  } else if (task.status === \'failed\') {\n    console.log(\'Error:\', task.error);\n  } else if (task.status === \'running\') {\n    console.log(\'Progress:\', task.progress);\n  }\n}\n```\n\n## Run Options Types\n\n```typescript\nimport type { RunOptions, StreamOptions } from \'@inferencesh/sdk\';\n\nconst options: RunOptions = {\n  wait: true,\n  stream: false\n};\n\nconst streamOptions: StreamOptions = {\n  stream: true,\n  signal: new AbortController().signal\n};\n```\n\n## Agent Types\n\n```typescript\nimport type {\n  Agent,\n  AgentConfig,\n  AgentMessage,\n  AgentToolCall,\n  AgentResponse\n} from \'@inferencesh/sdk\';\n\n// Type-safe agent config\nconst config: AgentConfig = {\n  core_app: { ref: \'infsh/claude-sonnet-4@latest\' },\n  system_prompt: \'You are a helpful assistant.\',\n  tools: [],\n  temperature: 0.7,\n  max_tokens: 4096\n};\n\n// Type-safe message handler\nfunction handleMessage(msg: AgentMessage) {\n  if (msg.type === \'text\') {\n    console.log(msg.content);\n  } else if (msg.type === \'tool_use\') {\n    console.log(\'Tool:\', msg.tool_name);\n  }\n}\n```\n\n## Tool Types\n\n```typescript\nimport {\n  tool, string, number, integer, boolean, enumOf, array, obj, optional,\n  type AgentTool,\n  type ParamType,\n  type ToolCall\n} from \'@inferencesh/sdk\';\n\n// Type-safe tool definition\nconst myTool: AgentTool = tool(\'my_tool\')\n  .describe(\'Does something\')\n  .param(\'input\', string(\'Input value\'))\n  .build();\n\n// Type-safe tool call handler\nfunction handleToolCall(call: ToolCall) {\n  const { id, name, args } = call;\n  console.log(`Tool ${name} called with:`, args);\n}\n```\n\n## Parameter Type Helpers\n\n```typescript\nimport type { ParamType, StringParam, NumberParam, ObjectParam } from \'@inferencesh/sdk\';\n\n// String parameter\nconst nameParam: ParamType = string(\'User name\');\n\n// Number parameter\nconst scoreParam: ParamType = number(\'Score value\');\n\n// Object parameter\nconst addressParam: ObjectParam = obj({\n  street: string(\'Street\'),\n  city: string(\'City\'),\n  zip: optional(string(\'ZIP\'))\n}, \'Address\');\n```\n\n## Generic Client\n\n```typescript\nimport { inference, type InferenceClient } from \'@inferencesh/sdk\';\n\nconst client: InferenceClient = inference({ apiKey: \'inf_...\' });\n\n// All methods are typed\nconst result = await client.run({\n  app: \'my-app\',\n  input: { data: \'test\' }\n});\n// result is TaskDTO\n```\n\n## Custom Input/Output Types\n\n```typescript\ninterface MyAppInput {\n  prompt: string;\n  style?: \'realistic\' | \'artistic\' | \'cartoon\';\n  steps?: number;\n}\n\ninterface MyAppOutput {\n  image: string;\n  metadata: {\n    seed: number;\n    duration_ms: number;\n  };\n}\n\nasync function generateImage(input: MyAppInput): Promise<MyAppOutput> {\n  const result = await client.run({\n    app: \'infsh/flux-schnell\',\n    input\n  });\n\n  return result.output as MyAppOutput;\n}\n```\n\n## Type Guards\n\n```typescript\nimport type { TaskDTO, TaskStatus } from \'@inferencesh/sdk\';\n\nfunction isCompleted(task: TaskDTO): task is TaskDTO & { status: \'completed\' } {\n  return task.status === \'completed\';\n}\n\nfunction isFailed(task: TaskDTO): task is TaskDTO & { status: \'failed\' } {\n  return task.status === \'failed\';\n}\n\n// Usage\nconst task = await client.run({ app: \'my-app\', input: {} });\n\nif (isCompleted(task)) {\n  // TypeScript knows task.output exists here\n  console.log(task.output);\n} else if (isFailed(task)) {\n  // TypeScript knows task.error exists here\n  console.log(task.error);\n}\n```\n\n## Error Types\n\n```typescript\nimport {\n  InferenceError,\n  RequirementsNotMetException,\n  type RequirementError\n} from \'@inferencesh/sdk\';\n\ntry {\n  await client.run({ app: \'my-app\', input: {} });\n} catch (e) {\n  if (e instanceof RequirementsNotMetException) {\n    const errors: RequirementError[] = e.errors;\n    for (const err of errors) {\n      console.log(`${err.type}: ${err.key}`);\n    }\n  } else if (e instanceof InferenceError) {\n    console.log(\'API error:\', e.message);\n  }\n}\n```\n\n## File Types\n\n```typescript\nimport type { FileDTO, UploadOptions } from \'@inferencesh/sdk\';\n\nconst options: UploadOptions = {\n  filename: \'image.png\',\n  contentType: \'image/png\',\n  public: true\n};\n\nconst file: FileDTO = await client.uploadFile(\'/path/to/file\', options);\nconsole.log(file.uri, file.url, file.size);\n```\n\n## Stream Types\n\n```typescript\nimport type { StreamUpdate, StreamOptions } from \'@inferencesh/sdk\';\n\nasync function* typedStream(config: any): AsyncGenerator<StreamUpdate> {\n  const stream = await client.run(config, { stream: true });\n  yield* stream;\n}\n\n// Usage\nfor await (const update of typedStream({ app: \'my-app\', input: {} })) {\n  // update is StreamUpdate\n  console.log(update.status);\n}\n```\n\n## React Integration Types\n\n```typescript\nimport type { Agent, AgentMessage, ToolCall } from \'@inferencesh/sdk\';\n\ninterface ChatState {\n  messages: AgentMessage[];\n  loading: boolean;\n  error: string | null;\n}\n\ninterface ChatActions {\n  sendMessage: (text: string) => Promise<void>;\n  reset: () => void;\n}\n\nfunction useChat(agentRef: string): ChatState & ChatActions {\n  // Implementation\n}\n```\n\n## Strict Mode Configuration\n\nFor strictest type checking, use these tsconfig options:\n\n```json\n{\n  \"compilerOptions\": {\n    \"strict\": true,\n    \"noUncheckedIndexedAccess\": true,\n    \"exactOptionalPropertyTypes\": true\n  }\n}\n```\n\n## Module Augmentation\n\nExtend types for custom use cases:\n\n```typescript\nimport \'@inferencesh/sdk\';\n\ndeclare module \'@inferencesh/sdk\' {\n  interface TaskDTO {\n    customField?: string;\n  }\n}\n```\n\n## JSDoc Type Annotations\n\nFor JavaScript projects wanting type hints:\n\n```javascript\n/** @type {import(\'@inferencesh/sdk\').InferenceClient} */\nconst client = inference({ apiKey: \'inf_...\' });\n\n/**\n * @param {import(\'@inferencesh/sdk\').TaskDTO} task\n */\nfunction handleTask(task) {\n  console.log(task.status);\n}\n```\n\n## Zod Integration\n\nValidate runtime types with Zod:\n\n```typescript\nimport { z } from \'zod\';\n\nconst ImageOutputSchema = z.object({\n  image: z.string().url(),\n  metadata: z.object({\n    seed: z.number(),\n    duration_ms: z.number()\n  })\n});\n\ntype ImageOutput = z.infer<typeof ImageOutputSchema>;\n\nasync function generateImage(prompt: string): Promise<ImageOutput> {\n  const result = await client.run({\n    app: \'infsh/flux-schnell\',\n    input: { prompt }\n  });\n\n  // Validate at runtime\n  return ImageOutputSchema.parse(result.output);\n}\n```\n\n## Full Example\n\n```typescript\nimport {\n  inference,\n  tool,\n  appTool,\n  string,\n  enumOf,\n  type InferenceClient,\n  type AgentTool,\n  type TaskDTO,\n  type ToolCall\n} from \'@inferencesh/sdk\';\n\n// Typed client\nconst client: InferenceClient = inference({\n  apiKey: process.env.INFERENCE_API_KEY!\n});\n\n// Typed tools\nconst tools: AgentTool[] = [\n  tool(\'search\')\n    .describe(\'Search for information\')\n    .param(\'query\', string(\'Search query\'))\n    .build(),\n\n  appTool(\'generate\', \'infsh/flux-schnell@latest\')\n    .describe(\'Generate image\')\n    .param(\'prompt\', string(\'Description\'))\n    .param(\'style\', enumOf([\'realistic\', \'artistic\'], \'Style\'))\n    .build()\n];\n\n// Typed agent\nconst agent = client.agent({\n  core_app: { ref: \'infsh/claude-sonnet-4@latest\' },\n  system_prompt: \'You are helpful.\',\n  tools\n});\n\n// Typed handler\nasync function handleToolCall(call: ToolCall): Promise<void> {\n  console.log(`Tool: ${call.name}, Args:`, call.args);\n}\n\n// Typed response handling\nconst response = await agent.sendMessage(\'Hello\', {\n  onToolCall: handleToolCall\n});\n\nconsole.log(response.text);\n```\n','2623683992c3702e418126693eb70916','2026-10-26 11:22:15','2026-10-26 11:22:15','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(3522,'enc.7265666572656e6365732f7365727665722d70726f78792e6d64','skill_enc.6a6176617363726970742d73646b__enc.302e302e31','# Server Proxy Setup\n\nSecure API key handling for frontend applications.\n\n## Why Use a Proxy?\n\nNever expose API keys in browser code. Use a server proxy to:\n\n- Keep API keys secure on the server\n- Add authentication/authorization\n- Rate limit requests\n- Log usage and analytics\n\n```\nBrowser (SDK) → Your Backend (Proxy) → api.inference.sh\n  (no key)     (injects API key)      (authenticated)\n```\n\n## Client Configuration\n\n```typescript\nimport { inference } from \'@inferencesh/sdk\';\n\n// Frontend code - no API key!\nconst client = inference({\n  proxyUrl: \'/api/inference/proxy\'\n});\n\n// Use normally\nconst result = await client.run({\n  app: \'infsh/flux-schnell\',\n  input: { prompt: \'A sunset\' }\n});\n```\n\n## Next.js (App Router)\n\n```typescript\n// app/api/inference/proxy/route.ts\nimport { createRouteHandler } from \'@inferencesh/sdk/proxy/nextjs\';\n\nconst route = createRouteHandler({\n  apiKey: process.env.INFERENCE_API_KEY!\n});\n\nexport const POST = route.POST;\n```\n\n### With Custom Authentication\n\n```typescript\n// app/api/inference/proxy/route.ts\nimport { createRouteHandler } from \'@inferencesh/sdk/proxy/nextjs\';\nimport { getServerSession } from \'next-auth\';\n\nconst route = createRouteHandler({\n  apiKey: process.env.INFERENCE_API_KEY!\n});\n\nexport async function POST(req: Request) {\n  // Check auth first\n  const session = await getServerSession();\n  if (!session) {\n    return Response.json({ error: \'Unauthorized\' }, { status: 401 });\n  }\n\n  // Check rate limits, log usage, etc.\n\n  return route.POST(req);\n}\n```\n\n## Next.js (Pages Router)\n\n```typescript\n// pages/api/inference/proxy.ts\nimport { createApiHandler } from \'@inferencesh/sdk/proxy/nextjs-pages\';\n\nexport default createApiHandler({\n  apiKey: process.env.INFERENCE_API_KEY!\n});\n```\n\n## Express\n\n```typescript\nimport express from \'express\';\nimport { createProxyMiddleware } from \'@inferencesh/sdk/proxy/express\';\n\nconst app = express();\n\n// Basic setup\napp.use(\'/api/inference/proxy\', createProxyMiddleware({\n  apiKey: process.env.INFERENCE_API_KEY!\n}));\n\n// With auth middleware\napp.use(\'/api/inference/proxy\',\n  requireAuth,\n  createProxyMiddleware({\n    apiKey: process.env.INFERENCE_API_KEY!\n  })\n);\n\napp.listen(3000);\n```\n\n## Hono\n\n```typescript\nimport { Hono } from \'hono\';\nimport { createMiddleware } from \'@inferencesh/sdk/proxy/hono\';\n\nconst app = new Hono();\n\napp.post(\'/api/inference/proxy\', createMiddleware({\n  apiKey: process.env.INFERENCE_API_KEY!\n}));\n\nexport default app;\n```\n\n### Cloudflare Workers\n\n```typescript\nimport { Hono } from \'hono\';\nimport { createMiddleware } from \'@inferencesh/sdk/proxy/hono\';\n\ntype Bindings = {\n  INFERENCE_API_KEY: string;\n};\n\nconst app = new Hono<{ Bindings: Bindings }>();\n\napp.post(\'/api/inference/proxy\', (c) => {\n  const middleware = createMiddleware({\n    apiKey: c.env.INFERENCE_API_KEY\n  });\n  return middleware(c);\n});\n\nexport default app;\n```\n\n## Remix\n\n```typescript\n// app/routes/api.inference.proxy.tsx\nimport type { ActionFunctionArgs } from \'@remix-run/node\';\nimport { createActionHandler } from \'@inferencesh/sdk/proxy/remix\';\n\nconst handler = createActionHandler({\n  apiKey: process.env.INFERENCE_API_KEY!\n});\n\nexport const action = async ({ request }: ActionFunctionArgs) => {\n  return handler(request);\n};\n```\n\n## SvelteKit\n\n```typescript\n// src/routes/api/inference/proxy/+server.ts\nimport { createRequestHandler } from \'@inferencesh/sdk/proxy/sveltekit\';\nimport { INFERENCE_API_KEY } from \'$env/static/private\';\n\nconst handler = createRequestHandler({\n  apiKey: INFERENCE_API_KEY\n});\n\nexport const POST = handler;\n```\n\n## Dynamic API Key Resolution\n\nLoad API keys from secrets managers:\n\n```typescript\n// Next.js example\nimport { createRouteHandler } from \'@inferencesh/sdk/proxy/nextjs\';\nimport { getSecret } from \'./vault\';\n\nconst route = createRouteHandler({\n  resolveApiKey: async () => {\n    return await getSecret(\'INFERENCE_API_KEY\');\n  }\n});\n\nexport const POST = route.POST;\n```\n\n## Per-User API Keys\n\nUse different keys per user/organization:\n\n```typescript\nimport { createRouteHandler } from \'@inferencesh/sdk/proxy/nextjs\';\nimport { getServerSession } from \'next-auth\';\nimport { db } from \'./db\';\n\nconst route = createRouteHandler({\n  resolveApiKey: async (req) => {\n    const session = await getServerSession();\n    if (!session?.user) {\n      throw new Error(\'Unauthorized\');\n    }\n\n    // Get user\'s API key from database\n    const user = await db.user.findUnique({\n      where: { id: session.user.id },\n      select: { inferenceApiKey: true }\n    });\n\n    return user?.inferenceApiKey || process.env.DEFAULT_INFERENCE_API_KEY!;\n  }\n});\n\nexport const POST = route.POST;\n```\n\n## Rate Limiting\n\n```typescript\nimport { createRouteHandler } from \'@inferencesh/sdk/proxy/nextjs\';\nimport { Ratelimit } from \'@upstash/ratelimit\';\nimport { Redis } from \'@upstash/redis\';\n\nconst ratelimit = new Ratelimit({\n  redis: Redis.fromEnv(),\n  limiter: Ratelimit.slidingWindow(10, \'1 m\'), // 10 requests per minute\n});\n\nconst route = createRouteHandler({\n  apiKey: process.env.INFERENCE_API_KEY!\n});\n\nexport async function POST(req: Request) {\n  // Get user identifier\n  const ip = req.headers.get(\'x-forwarded-for\') || \'anonymous\';\n\n  // Check rate limit\n  const { success, limit, reset, remaining } = await ratelimit.limit(ip);\n\n  if (!success) {\n    return Response.json(\n      { error: \'Rate limit exceeded\' },\n      {\n        status: 429,\n        headers: {\n          \'X-RateLimit-Limit\': limit.toString(),\n          \'X-RateLimit-Remaining\': remaining.toString(),\n          \'X-RateLimit-Reset\': reset.toString()\n        }\n      }\n    );\n  }\n\n  return route.POST(req);\n}\n```\n\n## Usage Logging\n\n```typescript\nimport { createRouteHandler } from \'@inferencesh/sdk/proxy/nextjs\';\nimport { getServerSession } from \'next-auth\';\n\nconst route = createRouteHandler({\n  apiKey: process.env.INFERENCE_API_KEY!\n});\n\nexport async function POST(req: Request) {\n  const session = await getServerSession();\n  const body = await req.clone().json();\n\n  // Log before\n  console.log({\n    type: \'inference_request\',\n    userId: session?.user?.id,\n    app: body.app,\n    timestamp: new Date().toISOString()\n  });\n\n  const response = await route.POST(req);\n\n  // Log after\n  console.log({\n    type: \'inference_response\',\n    userId: session?.user?.id,\n    status: response.status,\n    timestamp: new Date().toISOString()\n  });\n\n  return response;\n}\n```\n\n## Error Handling\n\n```typescript\nimport { createRouteHandler } from \'@inferencesh/sdk/proxy/nextjs\';\n\nconst route = createRouteHandler({\n  apiKey: process.env.INFERENCE_API_KEY!\n});\n\nexport async function POST(req: Request) {\n  try {\n    return await route.POST(req);\n  } catch (error) {\n    console.error(\'Proxy error:\', error);\n\n    // Don\'t expose internal errors to client\n    return Response.json(\n      { error: \'Internal server error\' },\n      { status: 500 }\n    );\n  }\n}\n```\n\n## Vercel Deployment\n\n```typescript\n// vercel.json\n{\n  \"functions\": {\n    \"app/api/inference/proxy/route.ts\": {\n      \"maxDuration\": 60\n    }\n  }\n}\n```\n\n```typescript\n// app/api/inference/proxy/route.ts\nimport { createRouteHandler } from \'@inferencesh/sdk/proxy/nextjs\';\n\nconst route = createRouteHandler({\n  apiKey: process.env.INFERENCE_API_KEY!\n});\n\nexport const POST = route.POST;\n\n// Enable streaming for long-running requests\nexport const runtime = \'edge\';\n```\n\n## CORS Configuration\n\nIf your frontend and backend are on different domains:\n\n```typescript\nimport { createRouteHandler } from \'@inferencesh/sdk/proxy/nextjs\';\n\nconst route = createRouteHandler({\n  apiKey: process.env.INFERENCE_API_KEY!\n});\n\nexport async function POST(req: Request) {\n  const response = await route.POST(req);\n\n  // Add CORS headers\n  const headers = new Headers(response.headers);\n  headers.set(\'Access-Control-Allow-Origin\', \'https://your-frontend.com\');\n  headers.set(\'Access-Control-Allow-Methods\', \'POST\');\n  headers.set(\'Access-Control-Allow-Headers\', \'Content-Type\');\n\n  return new Response(response.body, {\n    status: response.status,\n    headers\n  });\n}\n\nexport async function OPTIONS() {\n  return new Response(null, {\n    headers: {\n      \'Access-Control-Allow-Origin\': \'https://your-frontend.com\',\n      \'Access-Control-Allow-Methods\': \'POST, OPTIONS\',\n      \'Access-Control-Allow-Headers\': \'Content-Type\'\n    }\n  });\n}\n```\n\n## Testing Locally\n\n```typescript\n// Use environment variable for flexibility\nconst client = inference({\n  // Use proxy in production, direct API in development\n  ...(process.env.NODE_ENV === \'production\'\n    ? { proxyUrl: \'/api/inference/proxy\' }\n    : { apiKey: process.env.NEXT_PUBLIC_INFERENCE_API_KEY })\n});\n```\n','cd49f0c23694c8cb6fd0f772bde701f3','2026-10-26 11:22:15','2026-10-26 11:22:15','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(3523,'enc.7265666572656e6365732f73747265616d696e672e6d64','skill_enc.6a6176617363726970742d73646b__enc.302e302e31','# Streaming Reference\n\nReal-time progress updates and Server-Sent Events (SSE) handling.\n\n## Task Status Flow\n\n```\nRECEIVED (1) → QUEUED (2) → SCHEDULED (3) → PREPARING (4)\n→ SERVING (5) → SETTING_UP (6) → RUNNING (7) → UPLOADING (8)\n→ COMPLETED (10), FAILED (11), or CANCELLED (12)\n```\n\n## Basic Streaming\n\n```typescript\nimport { inference } from \'@inferencesh/sdk\';\n\nconst client = inference({ apiKey: \'inf_...\' });\n\nconst stream = await client.run({\n  app: \'google/veo-3-1-fast\',\n  input: { prompt: \'A sunset timelapse\' }\n}, { stream: true });\n\nfor await (const update of stream) {\n  console.log(`Status: ${update.status}`);\n}\n```\n\n## Handling Different Update Types\n\n```typescript\nconst stream = await client.run(config, { stream: true });\n\nfor await (const update of stream) {\n  const { status } = update;\n\n  // Task state changes\n  if (status === \'queued\') {\n    console.log(\'Task queued, waiting for worker...\');\n  } else if (status === \'running\') {\n    console.log(\'Task is running...\');\n  } else if (status === \'completed\') {\n    console.log(\'Done!\');\n    console.log(\'Output:\', update.output);\n  } else if (status === \'failed\') {\n    console.log(\'Error:\', update.error);\n  }\n\n  // Progress logs\n  if (update.logs?.length) {\n    for (const log of update.logs) {\n      console.log(`  Log: ${log}`);\n    }\n  }\n\n  // Partial outputs\n  if (update.partial_output) {\n    console.log(`  Partial: ${update.partial_output}`);\n  }\n}\n```\n\n## Progress Tracking with UI\n\n### Node.js CLI Progress Bar\n\n```typescript\nimport { inference } from \'@inferencesh/sdk\';\n\nfunction progressBar(current: number, total: number, width = 50) {\n  const filled = Math.round(width * current / total);\n  const bar = \'█\'.repeat(filled) + \'░\'.repeat(width - filled);\n  const percent = (current / total * 100).toFixed(1);\n  process.stdout.write(`\\r[${bar}] ${percent}%`);\n}\n\nconst stream = await client.run(config, { stream: true });\n\nfor await (const update of stream) {\n  if (update.progress) {\n    progressBar(update.progress.current, update.progress.total);\n  }\n\n  if (update.status === \'completed\') {\n    console.log(\'\\n✓ Complete!\');\n  }\n}\n```\n\n### React Progress Component\n\n```typescript\nimport { useState, useEffect } from \'react\';\nimport { inference } from \'@inferencesh/sdk\';\n\nfunction ProgressDisplay({ config }: { config: any }) {\n  const [status, setStatus] = useState(\'idle\');\n  const [progress, setProgress] = useState(0);\n  const [logs, setLogs] = useState<string[]>([]);\n\n  useEffect(() => {\n    const client = inference({ proxyUrl: \'/api/inference/proxy\' });\n\n    async function run() {\n      const stream = await client.run(config, { stream: true });\n\n      for await (const update of stream) {\n        setStatus(update.status);\n\n        if (update.progress) {\n          setProgress(update.progress.current / update.progress.total * 100);\n        }\n\n        if (update.logs) {\n          setLogs(prev => [...prev, ...update.logs]);\n        }\n      }\n    }\n\n    run();\n  }, [config]);\n\n  return (\n    <div>\n      <div>Status: {status}</div>\n      <progress value={progress} max={100} />\n      <ul>\n        {logs.map((log, i) => <li key={i}>{log}</li>)}\n      </ul>\n    </div>\n  );\n}\n```\n\n## Streaming with Timeout\n\n```typescript\nasync function streamWithTimeout(config: any, timeoutMs: number) {\n  const client = inference({ apiKey: \'inf_...\' });\n  const start = Date.now();\n\n  const stream = await client.run(config, { stream: true });\n\n  for await (const update of stream) {\n    if (Date.now() - start > timeoutMs) {\n      console.log(\'Timeout reached\');\n      break;\n    }\n\n    console.log(`Status: ${update.status}`);\n\n    if ([\'completed\', \'failed\'].includes(update.status)) {\n      return update;\n    }\n  }\n}\n\nconst result = await streamWithTimeout(config, 60000); // 1 minute\n```\n\n## Agent Streaming\n\n```typescript\nconst agent = client.agent(\'my-org/assistant@latest\');\n\nconst response = await agent.sendMessage(\'Explain quantum entanglement\', {\n  onMessage: (msg) => {\n    if (msg.content) {\n      // Stream text as it arrives\n      process.stdout.write(msg.content);\n    }\n\n    if (msg.type === \'thinking\') {\n      console.log(`\\n[Thinking: ${msg.content}]`);\n    }\n  },\n  onToolCall: async (call) => {\n    console.log(`\\n[Calling tool: ${call.name}]`);\n    const result = await executeTool(call.name, call.args);\n    agent.submitToolResult(call.id, result);\n  }\n});\n```\n\n## Multiple Streams in Parallel\n\n```typescript\nasync function parallelStreams() {\n  const client = inference({ apiKey: \'inf_...\' });\n\n  const configs = [\n    { app: \'infsh/flux-schnell\', input: { prompt: \'A mountain\' } },\n    { app: \'infsh/flux-schnell\', input: { prompt: \'An ocean\' } },\n    { app: \'infsh/flux-schnell\', input: { prompt: \'A forest\' } }\n  ];\n\n  async function streamOne(config: any, index: number) {\n    const stream = await client.run(config, { stream: true });\n\n    for await (const update of stream) {\n      console.log(`[${index}] ${update.status}`);\n\n      if (update.status === \'completed\') {\n        return update.output;\n      }\n    }\n  }\n\n  const results = await Promise.all(\n    configs.map((c, i) => streamOne(c, i))\n  );\n\n  return results;\n}\n```\n\n## Cancelling a Stream\n\n```typescript\nasync function cancellableStream(config: any) {\n  const client = inference({ apiKey: \'inf_...\' });\n  const controller = new AbortController();\n\n  // Cancel after 10 seconds\n  setTimeout(() => controller.abort(), 10000);\n\n  try {\n    const stream = await client.run(config, {\n      stream: true,\n      signal: controller.signal\n    });\n\n    for await (const update of stream) {\n      console.log(update.status);\n    }\n  } catch (e) {\n    if (e.name === \'AbortError\') {\n      console.log(\'Stream cancelled\');\n    } else {\n      throw e;\n    }\n  }\n}\n```\n\n## Collecting All Logs\n\n```typescript\nasync function collectLogs(config: any) {\n  const client = inference({ apiKey: \'inf_...\' });\n  const allLogs: string[] = [];\n\n  const stream = await client.run(config, { stream: true });\n\n  for await (const update of stream) {\n    if (update.logs) {\n      allLogs.push(...update.logs);\n    }\n\n    if (update.status === \'completed\') {\n      console.log(\'Final logs:\');\n      allLogs.forEach(log => console.log(`  ${log}`));\n      return update.output;\n    }\n  }\n}\n```\n\n## Custom Stream Processor Class\n\n```typescript\nclass StreamProcessor {\n  logs: string[] = [];\n  startTime?: number;\n  endTime?: number;\n\n  process(update: any): boolean {\n    if (!this.startTime) {\n      this.startTime = Date.now();\n    }\n\n    if (update.logs) {\n      this.logs.push(...update.logs);\n    }\n\n    if ([\'completed\', \'failed\'].includes(update.status)) {\n      this.endTime = Date.now();\n      return true; // Done\n    }\n\n    return false; // Continue\n  }\n\n  get duration(): number | null {\n    if (this.startTime && this.endTime) {\n      return this.endTime - this.startTime;\n    }\n    return null;\n  }\n}\n\n// Usage\nconst processor = new StreamProcessor();\nconst stream = await client.run(config, { stream: true });\n\nfor await (const update of stream) {\n  if (processor.process(update)) {\n    break;\n  }\n}\n\nconsole.log(`Duration: ${processor.duration}ms`);\nconsole.log(`Logs: ${processor.logs.length}`);\n```\n\n## Server-Sent Events in Browser\n\n```typescript\n// For custom SSE handling in browser\nasync function browserSSE(taskId: string) {\n  const eventSource = new EventSource(\n    `/api/inference/stream?taskId=${taskId}`\n  );\n\n  eventSource.onmessage = (event) => {\n    const update = JSON.parse(event.data);\n    console.log(\'Update:\', update);\n\n    if ([\'completed\', \'failed\'].includes(update.status)) {\n      eventSource.close();\n    }\n  };\n\n  eventSource.onerror = (error) => {\n    console.error(\'SSE error:\', error);\n    eventSource.close();\n  };\n}\n```\n\n## React Hook for Streaming\n\n```typescript\nimport { useState, useCallback, useRef } from \'react\';\nimport { inference } from \'@inferencesh/sdk\';\n\ninterface StreamState {\n  status: string;\n  output: any;\n  logs: string[];\n  error: string | null;\n}\n\nfunction useStream() {\n  const [state, setState] = useState<StreamState>({\n    status: \'idle\',\n    output: null,\n    logs: [],\n    error: null\n  });\n  const controllerRef = useRef<AbortController | null>(null);\n\n  const run = useCallback(async (config: any) => {\n    const client = inference({ proxyUrl: \'/api/inference/proxy\' });\n    controllerRef.current = new AbortController();\n\n    setState({ status: \'starting\', output: null, logs: [], error: null });\n\n    try {\n      const stream = await client.run(config, {\n        stream: true,\n        signal: controllerRef.current.signal\n      });\n\n      for await (const update of stream) {\n        setState(prev => ({\n          ...prev,\n          status: update.status,\n          logs: update.logs ? [...prev.logs, ...update.logs] : prev.logs,\n          output: update.output || prev.output\n        }));\n      }\n    } catch (e: any) {\n      if (e.name !== \'AbortError\') {\n        setState(prev => ({ ...prev, status: \'error\', error: e.message }));\n      }\n    }\n  }, []);\n\n  const cancel = useCallback(() => {\n    controllerRef.current?.abort();\n  }, []);\n\n  return { ...state, run, cancel };\n}\n\n// Usage in component\nfunction Generator() {\n  const { status, output, logs, run, cancel } = useStream();\n\n  return (\n    <div>\n      <button onClick={() => run({ app: \'my-app\', input: {...} })}>\n        Start\n      </button>\n      <button onClick={cancel}>Cancel</button>\n      <div>Status: {status}</div>\n      {output && <img src={output.url} />}\n    </div>\n  );\n}\n```\n','f3e8151078261bc6ea5cf6251314a4bd','2026-10-26 11:22:15','2026-10-26 11:22:15','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(3524,'enc.7265666572656e6365732f73657373696f6e732e6d64','skill_enc.6a6176617363726970742d73646b__enc.302e302e31','# Sessions Reference\n\nStateful execution with warm workers.\n\n## What Are Sessions?\n\nSessions keep workers warm between requests, enabling:\n\n- **Faster execution** - No cold start on subsequent calls\n- **Shared state** - Maintain context, loaded models, cached data\n- **Cost efficiency** - Reuse initialized resources\n\n## Creating a Session\n\n```typescript\nimport { inference } from \'@inferencesh/sdk\';\n\nconst client = inference({ apiKey: \'inf_...\' });\n\n// Start new session\nconst result = await client.run({\n  app: \'my-app\',\n  input: { action: \'initialize\' },\n  session: \'new\'\n});\n\nconst sessionId = result.session_id;\nconsole.log(`Session: ${sessionId}`);\n```\n\n## Using an Existing Session\n\n```typescript\n// Continue in same session\nconst result = await client.run({\n  app: \'my-app\',\n  input: { action: \'process\', data: \'...\' },\n  session: sessionId\n});\n```\n\n## Session Timeout\n\nSet how long idle sessions stay alive (1-3600 seconds):\n\n```typescript\n// 5-minute timeout\nconst result = await client.run({\n  app: \'my-app\',\n  input: { action: \'init\' },\n  session: \'new\',\n  session_timeout: 300\n});\n```\n\n## Session Lifecycle\n\n```\n1. Create session (session: \"new\")\n   ↓\n2. Worker starts, initializes app\n   ↓\n3. Subsequent calls reuse worker (session: sessionId)\n   ↓\n4. Idle timeout reached or explicit close\n   ↓\n5. Worker terminates\n```\n\n## Use Cases\n\n### Model Loading\n\nLoad a model once, use it multiple times:\n\n```typescript\n// Initial load (slow)\nconst result = await client.run({\n  app: \'ml-inference\',\n  input: { action: \'load_model\', model: \'large-model-v2\' },\n  session: \'new\',\n  session_timeout: 600\n});\nconst sessionId = result.session_id;\n\n// Fast inference calls\nfor (const item of dataBatch) {\n  const result = await client.run({\n    app: \'ml-inference\',\n    input: { action: \'predict\', data: item },\n    session: sessionId\n  });\n  console.log(result.output);\n}\n```\n\n### Browser Automation\n\nKeep browser open across multiple actions:\n\n```typescript\n// Start browser session\nconst result = await client.run({\n  app: \'browser-automation\',\n  input: { action: \'start\', url: \'https://example.com\' },\n  session: \'new\',\n  session_timeout: 300\n});\nconst sessionId = result.session_id;\n\n// Navigate\nawait client.run({\n  app: \'browser-automation\',\n  input: { action: \'click\', selector: \'#login-btn\' },\n  session: sessionId\n});\n\n// Fill form\nawait client.run({\n  app: \'browser-automation\',\n  input: { action: \'type\', selector: \'#username\', text: \'user@example.com\' },\n  session: sessionId\n});\n\n// Take screenshot\nconst screenshot = await client.run({\n  app: \'browser-automation\',\n  input: { action: \'screenshot\' },\n  session: sessionId\n});\n```\n\n### Stateful Conversations\n\n```typescript\n// Initialize chat context\nconst result = await client.run({\n  app: \'chat-with-memory\',\n  input: { action: \'init\', system: \'You are a helpful assistant.\' },\n  session: \'new\',\n  session_timeout: 1800  // 30 minutes\n});\nconst sessionId = result.session_id;\n\n// Multi-turn conversation\nconst messages = [\n  \'What is quantum computing?\',\n  \'Can you give me a simple example?\',\n  \'How is it different from classical computing?\'\n];\n\nfor (const msg of messages) {\n  const result = await client.run({\n    app: \'chat-with-memory\',\n    input: { message: msg },\n    session: sessionId\n  });\n  console.log(`Assistant: ${result.output.response}`);\n}\n```\n\n### Data Processing Pipeline\n\n```typescript\n// Load data once\nconst result = await client.run({\n  app: \'data-processor\',\n  input: { action: \'load\', dataset: \'large_dataset.parquet\' },\n  session: \'new\',\n  session_timeout: 900\n});\nconst sessionId = result.session_id;\n\n// Run multiple analyses\nconst analyses = [\'summary\', \'correlations\', \'outliers\', \'trends\'];\n\nfor (const analysis of analyses) {\n  const result = await client.run({\n    app: \'data-processor\',\n    input: { action: \'analyze\', type: analysis },\n    session: sessionId\n  });\n  console.log(`${analysis}:`, result.output);\n}\n```\n\n## Session Management\n\n### Session Recovery Pattern\n\n```typescript\nclass SessionManager {\n  private client: any;\n  private app: string;\n  private timeout: number;\n  private sessionId: string | null = null;\n\n  constructor(client: any, app: string, timeout = 300) {\n    this.client = client;\n    this.app = app;\n    this.timeout = timeout;\n  }\n\n  private async ensureSession(): Promise<string> {\n    if (!this.sessionId) {\n      const result = await this.client.run({\n        app: this.app,\n        input: { action: \'init\' },\n        session: \'new\',\n        session_timeout: this.timeout\n      });\n      this.sessionId = result.session_id;\n    }\n    return this.sessionId;\n  }\n\n  async run(input: any) {\n    try {\n      return await this.client.run({\n        app: this.app,\n        input,\n        session: await this.ensureSession()\n      });\n    } catch (e: any) {\n      if (e.message?.toLowerCase().includes(\'session\')) {\n        // Session expired, create new one\n        this.sessionId = null;\n        return await this.client.run({\n          app: this.app,\n          input,\n          session: await this.ensureSession()\n        });\n      }\n      throw e;\n    }\n  }\n}\n\n// Usage\nconst manager = new SessionManager(client, \'my-app\', 600);\nconst result = await manager.run({ action: \'process\', data: \'...\' });\n```\n\n## React Hook for Sessions\n\n```typescript\nimport { useState, useCallback, useRef } from \'react\';\nimport { inference } from \'@inferencesh/sdk\';\n\nfunction useSession(app: string, timeout = 300) {\n  const [sessionId, setSessionId] = useState<string | null>(null);\n  const [loading, setLoading] = useState(false);\n  const clientRef = useRef(inference({ proxyUrl: \'/api/inference/proxy\' }));\n\n  const run = useCallback(async (input: any) => {\n    setLoading(true);\n\n    try {\n      const isNew = !sessionId;\n      const result = await clientRef.current.run({\n        app,\n        input,\n        session: isNew ? \'new\' : sessionId,\n        ...(isNew && { session_timeout: timeout })\n      });\n\n      if (isNew) {\n        setSessionId(result.session_id);\n      }\n\n      return result;\n    } catch (e: any) {\n      if (e.message?.toLowerCase().includes(\'session\')) {\n        // Session expired\n        setSessionId(null);\n      }\n      throw e;\n    } finally {\n      setLoading(false);\n    }\n  }, [app, sessionId, timeout]);\n\n  const reset = useCallback(() => {\n    setSessionId(null);\n  }, []);\n\n  return { sessionId, loading, run, reset };\n}\n\n// Usage\nfunction BrowserAutomation() {\n  const { sessionId, loading, run, reset } = useSession(\'browser-automation\');\n\n  return (\n    <div>\n      <div>Session: {sessionId || \'None\'}</div>\n      <button onClick={() => run({ action: \'start\', url: \'...\' })} disabled={loading}>\n        Start Browser\n      </button>\n      <button onClick={() => run({ action: \'screenshot\' })} disabled={!sessionId || loading}>\n        Screenshot\n      </button>\n      <button onClick={reset}>End Session</button>\n    </div>\n  );\n}\n```\n\n## Express Session API\n\n```typescript\nimport express from \'express\';\nimport { inference } from \'@inferencesh/sdk\';\n\nconst app = express();\nconst client = inference({ apiKey: process.env.INFERENCE_API_KEY });\n\n// Store sessions per user\nconst userSessions: Map<string, string> = new Map();\n\napp.post(\'/api/browser/start\', async (req, res) => {\n  const userId = req.user.id;\n\n  const result = await client.run({\n    app: \'browser-automation\',\n    input: { action: \'start\', url: req.body.url },\n    session: \'new\',\n    session_timeout: 300\n  });\n\n  userSessions.set(userId, result.session_id);\n  res.json({ sessionId: result.session_id });\n});\n\napp.post(\'/api/browser/action\', async (req, res) => {\n  const userId = req.user.id;\n  const sessionId = userSessions.get(userId);\n\n  if (!sessionId) {\n    return res.status(400).json({ error: \'No active session\' });\n  }\n\n  try {\n    const result = await client.run({\n      app: \'browser-automation\',\n      input: req.body,\n      session: sessionId\n    });\n    res.json(result.output);\n  } catch (e: any) {\n    if (e.message?.includes(\'session\')) {\n      userSessions.delete(userId);\n      res.status(400).json({ error: \'Session expired\' });\n    } else {\n      throw e;\n    }\n  }\n});\n\napp.post(\'/api/browser/end\', (req, res) => {\n  const userId = req.user.id;\n  userSessions.delete(userId);\n  res.json({ ok: true });\n});\n```\n\n## Best Practices\n\n1. **Set appropriate timeouts** - Balance between keeping workers warm and resource usage\n2. **Handle session expiry** - Always catch and handle session not found errors\n3. **Clean up when done** - Delete session references when user is finished\n4. **Don\'t over-parallelize** - Session requests go to the same worker sequentially\n5. **Monitor costs** - Long-running sessions incur ongoing charges\n6. **Store session IDs securely** - Don\'t expose session IDs to untrusted clients\n','4154f96ff10bb26d062ce743adb3b770','2026-10-26 11:22:15','2026-10-26 11:22:15','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(3525,'enc.7265666572656e6365732f73747265616d696e672e6d64','skill_enc.6a6176617363726970742d73646b__enc.302e302e31','# Streaming Reference\n\nReal-time progress updates and Server-Sent Events (SSE) handling.\n\n## Task Status Flow\n\n```\nRECEIVED (1) → QUEUED (2) → SCHEDULED (3) → PREPARING (4)\n→ SERVING (5) → SETTING_UP (6) → RUNNING (7) → UPLOADING (8)\n→ COMPLETED (10), FAILED (11), or CANCELLED (12)\n```\n\n## Basic Streaming\n\n```typescript\nimport { inference } from \'@inferencesh/sdk\';\n\nconst client = inference({ apiKey: \'inf_...\' });\n\nconst stream = await client.run({\n  app: \'google/veo-3-1-fast\',\n  input: { prompt: \'A sunset timelapse\' }\n}, { stream: true });\n\nfor await (const update of stream) {\n  console.log(`Status: ${update.status}`);\n}\n```\n\n## Handling Different Update Types\n\n```typescript\nconst stream = await client.run(config, { stream: true });\n\nfor await (const update of stream) {\n  const { status } = update;\n\n  // Task state changes\n  if (status === \'queued\') {\n    console.log(\'Task queued, waiting for worker...\');\n  } else if (status === \'running\') {\n    console.log(\'Task is running...\');\n  } else if (status === \'completed\') {\n    console.log(\'Done!\');\n    console.log(\'Output:\', update.output);\n  } else if (status === \'failed\') {\n    console.log(\'Error:\', update.error);\n  }\n\n  // Progress logs\n  if (update.logs?.length) {\n    for (const log of update.logs) {\n      console.log(`  Log: ${log}`);\n    }\n  }\n\n  // Partial outputs\n  if (update.partial_output) {\n    console.log(`  Partial: ${update.partial_output}`);\n  }\n}\n```\n\n## Progress Tracking with UI\n\n### Node.js CLI Progress Bar\n\n```typescript\nimport { inference } from \'@inferencesh/sdk\';\n\nfunction progressBar(current: number, total: number, width = 50) {\n  const filled = Math.round(width * current / total);\n  const bar = \'█\'.repeat(filled) + \'░\'.repeat(width - filled);\n  const percent = (current / total * 100).toFixed(1);\n  process.stdout.write(`\\r[${bar}] ${percent}%`);\n}\n\nconst stream = await client.run(config, { stream: true });\n\nfor await (const update of stream) {\n  if (update.progress) {\n    progressBar(update.progress.current, update.progress.total);\n  }\n\n  if (update.status === \'completed\') {\n    console.log(\'\\n✓ Complete!\');\n  }\n}\n```\n\n### React Progress Component\n\n```typescript\nimport { useState, useEffect } from \'react\';\nimport { inference } from \'@inferencesh/sdk\';\n\nfunction ProgressDisplay({ config }: { config: any }) {\n  const [status, setStatus] = useState(\'idle\');\n  const [progress, setProgress] = useState(0);\n  const [logs, setLogs] = useState<string[]>([]);\n\n  useEffect(() => {\n    const client = inference({ proxyUrl: \'/api/inference/proxy\' });\n\n    async function run() {\n      const stream = await client.run(config, { stream: true });\n\n      for await (const update of stream) {\n        setStatus(update.status);\n\n        if (update.progress) {\n          setProgress(update.progress.current / update.progress.total * 100);\n        }\n\n        if (update.logs) {\n          setLogs(prev => [...prev, ...update.logs]);\n        }\n      }\n    }\n\n    run();\n  }, [config]);\n\n  return (\n    <div>\n      <div>Status: {status}</div>\n      <progress value={progress} max={100} />\n      <ul>\n        {logs.map((log, i) => <li key={i}>{log}</li>)}\n      </ul>\n    </div>\n  );\n}\n```\n\n## Streaming with Timeout\n\n```typescript\nasync function streamWithTimeout(config: any, timeoutMs: number) {\n  const client = inference({ apiKey: \'inf_...\' });\n  const start = Date.now();\n\n  const stream = await client.run(config, { stream: true });\n\n  for await (const update of stream) {\n    if (Date.now() - start > timeoutMs) {\n      console.log(\'Timeout reached\');\n      break;\n    }\n\n    console.log(`Status: ${update.status}`);\n\n    if ([\'completed\', \'failed\'].includes(update.status)) {\n      return update;\n    }\n  }\n}\n\nconst result = await streamWithTimeout(config, 60000); // 1 minute\n```\n\n## Agent Streaming\n\n```typescript\nconst agent = client.agent(\'my-org/assistant@latest\');\n\nconst response = await agent.sendMessage(\'Explain quantum entanglement\', {\n  onMessage: (msg) => {\n    if (msg.content) {\n      // Stream text as it arrives\n      process.stdout.write(msg.content);\n    }\n\n    if (msg.type === \'thinking\') {\n      console.log(`\\n[Thinking: ${msg.content}]`);\n    }\n  },\n  onToolCall: async (call) => {\n    console.log(`\\n[Calling tool: ${call.name}]`);\n    const result = await executeTool(call.name, call.args);\n    agent.submitToolResult(call.id, result);\n  }\n});\n```\n\n## Multiple Streams in Parallel\n\n```typescript\nasync function parallelStreams() {\n  const client = inference({ apiKey: \'inf_...\' });\n\n  const configs = [\n    { app: \'infsh/flux-schnell\', input: { prompt: \'A mountain\' } },\n    { app: \'infsh/flux-schnell\', input: { prompt: \'An ocean\' } },\n    { app: \'infsh/flux-schnell\', input: { prompt: \'A forest\' } }\n  ];\n\n  async function streamOne(config: any, index: number) {\n    const stream = await client.run(config, { stream: true });\n\n    for await (const update of stream) {\n      console.log(`[${index}] ${update.status}`);\n\n      if (update.status === \'completed\') {\n        return update.output;\n      }\n    }\n  }\n\n  const results = await Promise.all(\n    configs.map((c, i) => streamOne(c, i))\n  );\n\n  return results;\n}\n```\n\n## Cancelling a Stream\n\n```typescript\nasync function cancellableStream(config: any) {\n  const client = inference({ apiKey: \'inf_...\' });\n  const controller = new AbortController();\n\n  // Cancel after 10 seconds\n  setTimeout(() => controller.abort(), 10000);\n\n  try {\n    const stream = await client.run(config, {\n      stream: true,\n      signal: controller.signal\n    });\n\n    for await (const update of stream) {\n      console.log(update.status);\n    }\n  } catch (e) {\n    if (e.name === \'AbortError\') {\n      console.log(\'Stream cancelled\');\n    } else {\n      throw e;\n    }\n  }\n}\n```\n\n## Collecting All Logs\n\n```typescript\nasync function collectLogs(config: any) {\n  const client = inference({ apiKey: \'inf_...\' });\n  const allLogs: string[] = [];\n\n  const stream = await client.run(config, { stream: true });\n\n  for await (const update of stream) {\n    if (update.logs) {\n      allLogs.push(...update.logs);\n    }\n\n    if (update.status === \'completed\') {\n      console.log(\'Final logs:\');\n      allLogs.forEach(log => console.log(`  ${log}`));\n      return update.output;\n    }\n  }\n}\n```\n\n## Custom Stream Processor Class\n\n```typescript\nclass StreamProcessor {\n  logs: string[] = [];\n  startTime?: number;\n  endTime?: number;\n\n  process(update: any): boolean {\n    if (!this.startTime) {\n      this.startTime = Date.now();\n    }\n\n    if (update.logs) {\n      this.logs.push(...update.logs);\n    }\n\n    if ([\'completed\', \'failed\'].includes(update.status)) {\n      this.endTime = Date.now();\n      return true; // Done\n    }\n\n    return false; // Continue\n  }\n\n  get duration(): number | null {\n    if (this.startTime && this.endTime) {\n      return this.endTime - this.startTime;\n    }\n    return null;\n  }\n}\n\n// Usage\nconst processor = new StreamProcessor();\nconst stream = await client.run(config, { stream: true });\n\nfor await (const update of stream) {\n  if (processor.process(update)) {\n    break;\n  }\n}\n\nconsole.log(`Duration: ${processor.duration}ms`);\nconsole.log(`Logs: ${processor.logs.length}`);\n```\n\n## Server-Sent Events in Browser\n\n```typescript\n// For custom SSE handling in browser\nasync function browserSSE(taskId: string) {\n  const eventSource = new EventSource(\n    `/api/inference/stream?taskId=${taskId}`\n  );\n\n  eventSource.onmessage = (event) => {\n    const update = JSON.parse(event.data);\n    console.log(\'Update:\', update);\n\n    if ([\'completed\', \'failed\'].includes(update.status)) {\n      eventSource.close();\n    }\n  };\n\n  eventSource.onerror = (error) => {\n    console.error(\'SSE error:\', error);\n    eventSource.close();\n  };\n}\n```\n\n## React Hook for Streaming\n\n```typescript\nimport { useState, useCallback, useRef } from \'react\';\nimport { inference } from \'@inferencesh/sdk\';\n\ninterface StreamState {\n  status: string;\n  output: any;\n  logs: string[];\n  error: string | null;\n}\n\nfunction useStream() {\n  const [state, setState] = useState<StreamState>({\n    status: \'idle\',\n    output: null,\n    logs: [],\n    error: null\n  });\n  const controllerRef = useRef<AbortController | null>(null);\n\n  const run = useCallback(async (config: any) => {\n    const client = inference({ proxyUrl: \'/api/inference/proxy\' });\n    controllerRef.current = new AbortController();\n\n    setState({ status: \'starting\', output: null, logs: [], error: null });\n\n    try {\n      const stream = await client.run(config, {\n        stream: true,\n        signal: controllerRef.current.signal\n      });\n\n      for await (const update of stream) {\n        setState(prev => ({\n          ...prev,\n          status: update.status,\n          logs: update.logs ? [...prev.logs, ...update.logs] : prev.logs,\n          output: update.output || prev.output\n        }));\n      }\n    } catch (e: any) {\n      if (e.name !== \'AbortError\') {\n        setState(prev => ({ ...prev, status: \'error\', error: e.message }));\n      }\n    }\n  }, []);\n\n  const cancel = useCallback(() => {\n    controllerRef.current?.abort();\n  }, []);\n\n  return { ...state, run, cancel };\n}\n\n// Usage in component\nfunction Generator() {\n  const { status, output, logs, run, cancel } = useStream();\n\n  return (\n    <div>\n      <button onClick={() => run({ app: \'my-app\', input: {...} })}>\n        Start\n      </button>\n      <button onClick={cancel}>Cancel</button>\n      <div>Status: {status}</div>\n      {output && <img src={output.url} />}\n    </div>\n  );\n}\n```\n','f3e8151078261bc6ea5cf6251314a4bd','2026-10-26 11:22:15','2026-10-26 11:22:15','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(3526,'enc.7265666572656e6365732f746f6f6c2d6275696c6465722e6d64','skill_enc.6a6176617363726970742d73646b__enc.302e302e31','# Tool Builder Reference\n\nComplete guide to building tools with the JavaScript SDK.\n\n## Parameter Types\n\n### Basic Types\n\n```typescript\nimport { string, number, integer, boolean } from \'@inferencesh/sdk\';\n\n// String parameter\nconst name = string(\'The user\\\'s full name\');\n\n// Number (float)\nconst score = number(\'Score between 0 and 1\');\n\n// Integer\nconst count = integer(\'Number of items\');\n\n// Boolean\nconst enabled = boolean(\'Whether feature is enabled\');\n```\n\n### Enum Type\n\n```typescript\nimport { enumOf } from \'@inferencesh/sdk\';\n\nconst priority = enumOf(\n  [\'low\', \'medium\', \'high\', \'critical\'],\n  \'Task priority level\'\n);\n```\n\n### Array Type\n\n```typescript\nimport { array, string, obj, integer } from \'@inferencesh/sdk\';\n\n// Array of strings\nconst tags = array(string(\'Tag name\'), \'List of tags\');\n\n// Array of objects\nconst items = array(\n  obj({\n    name: string(\'Item name\'),\n    qty: integer(\'Quantity\')\n  }),\n  \'List of items\'\n);\n```\n\n### Object Type\n\n```typescript\nimport { obj, string, integer, optional } from \'@inferencesh/sdk\';\n\nconst address = obj({\n  street: string(\'Street address\'),\n  city: string(\'City name\'),\n  state: string(\'State code\'),\n  zip: optional(string(\'ZIP code\'))\n}, \'Mailing address\');\n```\n\n### Optional Parameters\n\n```typescript\nimport { optional, string } from \'@inferencesh/sdk\';\n\n// Optional string\nconst nickname = optional(string(\'User\\\'s nickname\'));\n```\n\n## Tool Types\n\n### Client Tools\n\nTools that execute in your code:\n\n```typescript\nimport { tool, string, integer } from \'@inferencesh/sdk\';\n\n// Basic tool\nconst greet = tool(\'greet\')\n  .describe(\'Greets a user\')\n  .param(\'name\', string(\'Name to greet\'))\n  .build();\n\n// Tool with multiple parameters\nconst sendEmail = tool(\'send_email\')\n  .display(\'Send Email\')\n  .describe(\'Sends an email to a recipient\')\n  .param(\'to\', string(\'Recipient email\'))\n  .param(\'subject\', string(\'Email subject\'))\n  .param(\'body\', string(\'Email body\'))\n  .param(\'priority\', integer(\'Priority 1-5\'), 3) // default value\n  .requireApproval()\n  .build();\n```\n\n### App Tools\n\nTools that call inference.sh apps:\n\n```typescript\nimport { appTool, string } from \'@inferencesh/sdk\';\n\n// Basic app tool\nconst generate = appTool(\'generate_image\', \'infsh/flux-schnell@latest\')\n  .describe(\'Generate an image from a text prompt\')\n  .param(\'prompt\', string(\'Image description\'))\n  .build();\n\n// App tool with setup and defaults\nconst translate = appTool(\'translate\', \'infsh/translator@latest\')\n  .describe(\'Translate text between languages\')\n  .param(\'text\', string(\'Text to translate\'))\n  .param(\'targetLang\', string(\'Target language code\'))\n  .setup({\n    model: \'advanced\',\n    preserveFormatting: true\n  })\n  .input({\n    sourceLang: \'auto\'\n  })\n  .build();\n```\n\n### Agent Tools\n\nTools that delegate to other agents:\n\n```typescript\nimport { agentTool, string } from \'@inferencesh/sdk\';\n\nconst researcher = agentTool(\'research\', \'my-org/researcher@v1\')\n  .describe(\'Research a topic in depth\')\n  .param(\'topic\', string(\'Topic to research\'))\n  .param(\'depth\', string(\'Research depth: brief, moderate, comprehensive\'))\n  .build();\n\nconst coder = agentTool(\'write_code\', \'my-org/coder@latest\')\n  .describe(\'Write code to solve a problem\')\n  .param(\'task\', string(\'Coding task description\'))\n  .param(\'language\', string(\'Programming language\'))\n  .build();\n```\n\n### Webhook Tools\n\nTools that call external HTTP endpoints:\n\n```typescript\nimport { webhookTool, string } from \'@inferencesh/sdk\';\n\n// Slack notification\nconst slack = webhookTool(\'notify_slack\', \'https://hooks.slack.com/services/...\')\n  .describe(\'Send a message to Slack\')\n  .param(\'channel\', string(\'Channel name\'))\n  .param(\'message\', string(\'Message text\'))\n  .build();\n\n// Webhook with secret\nconst github = webhookTool(\'create_issue\', \'https://api.github.com/repos/org/repo/issues\')\n  .describe(\'Create a GitHub issue\')\n  .secret(\'GITHUB_TOKEN\') // Uses stored secret\n  .param(\'title\', string(\'Issue title\'))\n  .param(\'body\', string(\'Issue description\'))\n  .build();\n```\n\n## Tool Builder Methods\n\n### Common Methods\n\n| Method | Description |\n|--------|-------------|\n| `.describe(text)` | Set tool description |\n| `.display(name)` | Set display name |\n| `.param(name, type, default?)` | Add parameter |\n| `.requireApproval()` | Require human approval |\n| `.build()` | Build the tool |\n\n### App Tool Methods\n\n| Method | Description |\n|--------|-------------|\n| `.setup(config)` | Hidden setup configuration |\n| `.input(defaults)` | Default input values |\n\n### Webhook Tool Methods\n\n| Method | Description |\n|--------|-------------|\n| `.secret(name)` | Use stored secret for auth |\n\n## Internal Tools\n\nBuilt-in capabilities you can enable:\n\n```typescript\nimport { internalTools } from \'@inferencesh/sdk\';\n\nconst config = internalTools()\n  .plan()                    // Task planning\n  .memory()                  // Information storage\n  .webSearch(true)          // Web search capability\n  .codeExecution(true)      // Run code\n  .imageGeneration({\n    enabled: true,\n    appRef: \'infsh/flux@latest\'\n  })\n  .build();\n```\n\n### Internal Tool Options\n\n| Tool | Description |\n|------|-------------|\n| `.plan()` | Enable task breakdown and planning |\n| `.memory()` | Enable information storage |\n| `.webSearch(enabled)` | Enable/disable web search |\n| `.codeExecution(enabled)` | Enable/disable code running |\n| `.imageGeneration(config)` | Configure image generation |\n\n## Handling Tool Calls\n\n### Basic Handler\n\n```typescript\nconst response = await agent.sendMessage(\'Greet John\', {\n  onToolCall: async (call) => {\n    let result;\n\n    if (call.name === \'greet\') {\n      result = `Hello, ${call.args.name}!`;\n    } else if (call.name === \'calculate\') {\n      result = eval(call.args.expression);\n    } else {\n      result = { error: `Unknown tool: ${call.name}` };\n    }\n\n    agent.submitToolResult(call.id, result);\n  }\n});\n```\n\n### With Approval\n\n```typescript\nimport * as readline from \'readline\';\n\nasync function promptUser(question: string): Promise<boolean> {\n  const rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n  });\n  return new Promise(resolve => {\n    rl.question(question, answer => {\n      rl.close();\n      resolve(answer.toLowerCase() === \'y\');\n    });\n  });\n}\n\nconst response = await agent.sendMessage(\'Delete temp files\', {\n  onToolCall: async (call) => {\n    if (call.requiresApproval) {\n      console.log(`Tool: ${call.name}`);\n      console.log(`Args: ${JSON.stringify(call.args)}`);\n      const approved = await promptUser(\'Approve? (y/n): \');\n\n      if (!approved) {\n        agent.submitToolResult(call.id, { error: \'Denied by user\' });\n        return;\n      }\n    }\n\n    const result = await executeTool(call.name, call.args);\n    agent.submitToolResult(call.id, result);\n  }\n});\n```\n\n### Widget Results\n\nReturn structured data for UI widgets:\n\n```typescript\nconst response = await agent.sendMessage(\'Show order confirmation\', {\n  onToolCall: async (call) => {\n    if (call.name === \'confirm_order\') {\n      // Return widget data\n      agent.submitToolResult(call.id, {\n        action: { type: \'confirm\' },\n        formData: {\n          orderId: \'12345\',\n          items: [\'Widget A\', \'Widget B\'],\n          total: 99.99\n        }\n      });\n    }\n  }\n});\n```\n\n## TypeScript Types\n\n```typescript\nimport type {\n  AgentTool,\n  ToolCall,\n  ToolResult,\n  ParamType\n} from \'@inferencesh/sdk\';\n\n// Type-safe tool definition\nconst typedTool: AgentTool = tool(\'my_tool\')\n  .describe(\'A typed tool\')\n  .param(\'input\', string(\'Input value\'))\n  .build();\n\n// Type-safe handler\nfunction handleToolCall(call: ToolCall): ToolResult {\n  return { success: true, data: call.args };\n}\n```\n\n## Complete Example\n\n```typescript\nimport {\n  inference, tool, appTool, webhookTool,\n  string, number, integer, boolean, enumOf,\n  array, obj, optional, internalTools\n} from \'@inferencesh/sdk\';\n\nconst client = inference({ apiKey: \'inf_...\' });\n\n// Calculator tool\nconst calculator = tool(\'calculate\')\n  .display(\'Calculator\')\n  .describe(\'Perform mathematical calculations\')\n  .param(\'expression\', string(\'Math expression to evaluate\'))\n  .build();\n\n// Image generation tool\nconst imageGen = appTool(\'generate_image\', \'infsh/flux-schnell@latest\')\n  .describe(\'Generate an image from text\')\n  .param(\'prompt\', string(\'Image description\'))\n  .param(\'style\', enumOf([\'realistic\', \'artistic\', \'cartoon\'], \'Image style\'))\n  .setup({ quality: \'high\' })\n  .input({ steps: 20 })\n  .requireApproval()\n  .build();\n\n// Slack notification tool\nconst slack = webhookTool(\'notify\', \'https://hooks.slack.com/...\')\n  .describe(\'Send Slack notification\')\n  .param(\'message\', string(\'Message to send\'))\n  .build();\n\n// Built-in tools\nconst internals = internalTools()\n  .webSearch(true)\n  .codeExecution(true)\n  .build();\n\n// Create agent with all tools\nconst agent = client.agent({\n  core_app: { ref: \'infsh/claude-sonnet-4@latest\' },\n  system_prompt: \'You are a helpful assistant with various capabilities.\',\n  tools: [calculator, imageGen, slack],\n  internal_tools: internals,\n  temperature: 0.7\n});\n\n// Handle tool calls\nconst response = await agent.sendMessage(\n  \'Calculate 15% tip on $85, then notify Slack\',\n  {\n    onToolCall: async (call) => {\n      if (call.name === \'calculate\') {\n        try {\n          const result = eval(call.args.expression);\n          agent.submitToolResult(call.id, { result });\n        } catch (e) {\n          agent.submitToolResult(call.id, { error: String(e) });\n        }\n      } else if (call.requiresApproval) {\n        const approved = await promptUser(`Allow ${call.name}? (y/n): `);\n        if (!approved) {\n          agent.submitToolResult(call.id, { error: \'Denied\' });\n        }\n        // App/webhook tools execute automatically if approved\n      }\n    }\n  }\n);\n```\n\n## Server Proxy Tools\n\nWhen using the SDK in the browser, tools that require API keys should use webhooks with secrets stored server-side:\n\n```typescript\n// Browser-safe tool definition\nconst apiTool = webhookTool(\'call_api\', \'/api/my-endpoint\')\n  .describe(\'Call server-side API\')\n  .param(\'data\', obj({\n    action: string(\'Action to perform\'),\n    payload: optional(string(\'Optional payload\'))\n  }))\n  .build();\n\n// Server-side handler (e.g., Next.js API route)\n// app/api/my-endpoint/route.ts\nexport async function POST(req: Request) {\n  const { data } = await req.json();\n\n  // Access secrets safely on server\n  const result = await fetch(process.env.EXTERNAL_API_URL, {\n    headers: { Authorization: `Bearer ${process.env.API_SECRET}` },\n    body: JSON.stringify(data)\n  });\n\n  return Response.json(await result.json());\n}\n```\n','9431f7995b4f437b57fff83a5aac3bad','2026-10-26 11:22:15','2026-10-26 11:22:15','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(3527,'enc.7265666572656e6365732f73657373696f6e732e6d64','skill_enc.6a6176617363726970742d73646b__enc.302e302e31','# Sessions Reference\n\nStateful execution with warm workers.\n\n## What Are Sessions?\n\nSessions keep workers warm between requests, enabling:\n\n- **Faster execution** - No cold start on subsequent calls\n- **Shared state** - Maintain context, loaded models, cached data\n- **Cost efficiency** - Reuse initialized resources\n\n## Creating a Session\n\n```typescript\nimport { inference } from \'@inferencesh/sdk\';\n\nconst client = inference({ apiKey: \'inf_...\' });\n\n// Start new session\nconst result = await client.run({\n  app: \'my-app\',\n  input: { action: \'initialize\' },\n  session: \'new\'\n});\n\nconst sessionId = result.session_id;\nconsole.log(`Session: ${sessionId}`);\n```\n\n## Using an Existing Session\n\n```typescript\n// Continue in same session\nconst result = await client.run({\n  app: \'my-app\',\n  input: { action: \'process\', data: \'...\' },\n  session: sessionId\n});\n```\n\n## Session Timeout\n\nSet how long idle sessions stay alive (1-3600 seconds):\n\n```typescript\n// 5-minute timeout\nconst result = await client.run({\n  app: \'my-app\',\n  input: { action: \'init\' },\n  session: \'new\',\n  session_timeout: 300\n});\n```\n\n## Session Lifecycle\n\n```\n1. Create session (session: \"new\")\n   ↓\n2. Worker starts, initializes app\n   ↓\n3. Subsequent calls reuse worker (session: sessionId)\n   ↓\n4. Idle timeout reached or explicit close\n   ↓\n5. Worker terminates\n```\n\n## Use Cases\n\n### Model Loading\n\nLoad a model once, use it multiple times:\n\n```typescript\n// Initial load (slow)\nconst result = await client.run({\n  app: \'ml-inference\',\n  input: { action: \'load_model\', model: \'large-model-v2\' },\n  session: \'new\',\n  session_timeout: 600\n});\nconst sessionId = result.session_id;\n\n// Fast inference calls\nfor (const item of dataBatch) {\n  const result = await client.run({\n    app: \'ml-inference\',\n    input: { action: \'predict\', data: item },\n    session: sessionId\n  });\n  console.log(result.output);\n}\n```\n\n### Browser Automation\n\nKeep browser open across multiple actions:\n\n```typescript\n// Start browser session\nconst result = await client.run({\n  app: \'browser-automation\',\n  input: { action: \'start\', url: \'https://example.com\' },\n  session: \'new\',\n  session_timeout: 300\n});\nconst sessionId = result.session_id;\n\n// Navigate\nawait client.run({\n  app: \'browser-automation\',\n  input: { action: \'click\', selector: \'#login-btn\' },\n  session: sessionId\n});\n\n// Fill form\nawait client.run({\n  app: \'browser-automation\',\n  input: { action: \'type\', selector: \'#username\', text: \'user@example.com\' },\n  session: sessionId\n});\n\n// Take screenshot\nconst screenshot = await client.run({\n  app: \'browser-automation\',\n  input: { action: \'screenshot\' },\n  session: sessionId\n});\n```\n\n### Stateful Conversations\n\n```typescript\n// Initialize chat context\nconst result = await client.run({\n  app: \'chat-with-memory\',\n  input: { action: \'init\', system: \'You are a helpful assistant.\' },\n  session: \'new\',\n  session_timeout: 1800  // 30 minutes\n});\nconst sessionId = result.session_id;\n\n// Multi-turn conversation\nconst messages = [\n  \'What is quantum computing?\',\n  \'Can you give me a simple example?\',\n  \'How is it different from classical computing?\'\n];\n\nfor (const msg of messages) {\n  const result = await client.run({\n    app: \'chat-with-memory\',\n    input: { message: msg },\n    session: sessionId\n  });\n  console.log(`Assistant: ${result.output.response}`);\n}\n```\n\n### Data Processing Pipeline\n\n```typescript\n// Load data once\nconst result = await client.run({\n  app: \'data-processor\',\n  input: { action: \'load\', dataset: \'large_dataset.parquet\' },\n  session: \'new\',\n  session_timeout: 900\n});\nconst sessionId = result.session_id;\n\n// Run multiple analyses\nconst analyses = [\'summary\', \'correlations\', \'outliers\', \'trends\'];\n\nfor (const analysis of analyses) {\n  const result = await client.run({\n    app: \'data-processor\',\n    input: { action: \'analyze\', type: analysis },\n    session: sessionId\n  });\n  console.log(`${analysis}:`, result.output);\n}\n```\n\n## Session Management\n\n### Session Recovery Pattern\n\n```typescript\nclass SessionManager {\n  private client: any;\n  private app: string;\n  private timeout: number;\n  private sessionId: string | null = null;\n\n  constructor(client: any, app: string, timeout = 300) {\n    this.client = client;\n    this.app = app;\n    this.timeout = timeout;\n  }\n\n  private async ensureSession(): Promise<string> {\n    if (!this.sessionId) {\n      const result = await this.client.run({\n        app: this.app,\n        input: { action: \'init\' },\n        session: \'new\',\n        session_timeout: this.timeout\n      });\n      this.sessionId = result.session_id;\n    }\n    return this.sessionId;\n  }\n\n  async run(input: any) {\n    try {\n      return await this.client.run({\n        app: this.app,\n        input,\n        session: await this.ensureSession()\n      });\n    } catch (e: any) {\n      if (e.message?.toLowerCase().includes(\'session\')) {\n        // Session expired, create new one\n        this.sessionId = null;\n        return await this.client.run({\n          app: this.app,\n          input,\n          session: await this.ensureSession()\n        });\n      }\n      throw e;\n    }\n  }\n}\n\n// Usage\nconst manager = new SessionManager(client, \'my-app\', 600);\nconst result = await manager.run({ action: \'process\', data: \'...\' });\n```\n\n## React Hook for Sessions\n\n```typescript\nimport { useState, useCallback, useRef } from \'react\';\nimport { inference } from \'@inferencesh/sdk\';\n\nfunction useSession(app: string, timeout = 300) {\n  const [sessionId, setSessionId] = useState<string | null>(null);\n  const [loading, setLoading] = useState(false);\n  const clientRef = useRef(inference({ proxyUrl: \'/api/inference/proxy\' }));\n\n  const run = useCallback(async (input: any) => {\n    setLoading(true);\n\n    try {\n      const isNew = !sessionId;\n      const result = await clientRef.current.run({\n        app,\n        input,\n        session: isNew ? \'new\' : sessionId,\n        ...(isNew && { session_timeout: timeout })\n      });\n\n      if (isNew) {\n        setSessionId(result.session_id);\n      }\n\n      return result;\n    } catch (e: any) {\n      if (e.message?.toLowerCase().includes(\'session\')) {\n        // Session expired\n        setSessionId(null);\n      }\n      throw e;\n    } finally {\n      setLoading(false);\n    }\n  }, [app, sessionId, timeout]);\n\n  const reset = useCallback(() => {\n    setSessionId(null);\n  }, []);\n\n  return { sessionId, loading, run, reset };\n}\n\n// Usage\nfunction BrowserAutomation() {\n  const { sessionId, loading, run, reset } = useSession(\'browser-automation\');\n\n  return (\n    <div>\n      <div>Session: {sessionId || \'None\'}</div>\n      <button onClick={() => run({ action: \'start\', url: \'...\' })} disabled={loading}>\n        Start Browser\n      </button>\n      <button onClick={() => run({ action: \'screenshot\' })} disabled={!sessionId || loading}>\n        Screenshot\n      </button>\n      <button onClick={reset}>End Session</button>\n    </div>\n  );\n}\n```\n\n## Express Session API\n\n```typescript\nimport express from \'express\';\nimport { inference } from \'@inferencesh/sdk\';\n\nconst app = express();\nconst client = inference({ apiKey: process.env.INFERENCE_API_KEY });\n\n// Store sessions per user\nconst userSessions: Map<string, string> = new Map();\n\napp.post(\'/api/browser/start\', async (req, res) => {\n  const userId = req.user.id;\n\n  const result = await client.run({\n    app: \'browser-automation\',\n    input: { action: \'start\', url: req.body.url },\n    session: \'new\',\n    session_timeout: 300\n  });\n\n  userSessions.set(userId, result.session_id);\n  res.json({ sessionId: result.session_id });\n});\n\napp.post(\'/api/browser/action\', async (req, res) => {\n  const userId = req.user.id;\n  const sessionId = userSessions.get(userId);\n\n  if (!sessionId) {\n    return res.status(400).json({ error: \'No active session\' });\n  }\n\n  try {\n    const result = await client.run({\n      app: \'browser-automation\',\n      input: req.body,\n      session: sessionId\n    });\n    res.json(result.output);\n  } catch (e: any) {\n    if (e.message?.includes(\'session\')) {\n      userSessions.delete(userId);\n      res.status(400).json({ error: \'Session expired\' });\n    } else {\n      throw e;\n    }\n  }\n});\n\napp.post(\'/api/browser/end\', (req, res) => {\n  const userId = req.user.id;\n  userSessions.delete(userId);\n  res.json({ ok: true });\n});\n```\n\n## Best Practices\n\n1. **Set appropriate timeouts** - Balance between keeping workers warm and resource usage\n2. **Handle session expiry** - Always catch and handle session not found errors\n3. **Clean up when done** - Delete session references when user is finished\n4. **Don\'t over-parallelize** - Session requests go to the same worker sequentially\n5. **Monitor costs** - Long-running sessions incur ongoing charges\n6. **Store session IDs securely** - Don\'t expose session IDs to untrusted clients\n','4154f96ff10bb26d062ce743adb3b770','2026-10-26 11:22:16','2026-10-26 11:22:16','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(3528,'enc.7265666572656e6365732f746f6f6c2d6275696c6465722e6d64','skill_enc.6a6176617363726970742d73646b__enc.302e302e31','# Tool Builder Reference\n\nComplete guide to building tools with the JavaScript SDK.\n\n## Parameter Types\n\n### Basic Types\n\n```typescript\nimport { string, number, integer, boolean } from \'@inferencesh/sdk\';\n\n// String parameter\nconst name = string(\'The user\\\'s full name\');\n\n// Number (float)\nconst score = number(\'Score between 0 and 1\');\n\n// Integer\nconst count = integer(\'Number of items\');\n\n// Boolean\nconst enabled = boolean(\'Whether feature is enabled\');\n```\n\n### Enum Type\n\n```typescript\nimport { enumOf } from \'@inferencesh/sdk\';\n\nconst priority = enumOf(\n  [\'low\', \'medium\', \'high\', \'critical\'],\n  \'Task priority level\'\n);\n```\n\n### Array Type\n\n```typescript\nimport { array, string, obj, integer } from \'@inferencesh/sdk\';\n\n// Array of strings\nconst tags = array(string(\'Tag name\'), \'List of tags\');\n\n// Array of objects\nconst items = array(\n  obj({\n    name: string(\'Item name\'),\n    qty: integer(\'Quantity\')\n  }),\n  \'List of items\'\n);\n```\n\n### Object Type\n\n```typescript\nimport { obj, string, integer, optional } from \'@inferencesh/sdk\';\n\nconst address = obj({\n  street: string(\'Street address\'),\n  city: string(\'City name\'),\n  state: string(\'State code\'),\n  zip: optional(string(\'ZIP code\'))\n}, \'Mailing address\');\n```\n\n### Optional Parameters\n\n```typescript\nimport { optional, string } from \'@inferencesh/sdk\';\n\n// Optional string\nconst nickname = optional(string(\'User\\\'s nickname\'));\n```\n\n## Tool Types\n\n### Client Tools\n\nTools that execute in your code:\n\n```typescript\nimport { tool, string, integer } from \'@inferencesh/sdk\';\n\n// Basic tool\nconst greet = tool(\'greet\')\n  .describe(\'Greets a user\')\n  .param(\'name\', string(\'Name to greet\'))\n  .build();\n\n// Tool with multiple parameters\nconst sendEmail = tool(\'send_email\')\n  .display(\'Send Email\')\n  .describe(\'Sends an email to a recipient\')\n  .param(\'to\', string(\'Recipient email\'))\n  .param(\'subject\', string(\'Email subject\'))\n  .param(\'body\', string(\'Email body\'))\n  .param(\'priority\', integer(\'Priority 1-5\'), 3) // default value\n  .requireApproval()\n  .build();\n```\n\n### App Tools\n\nTools that call inference.sh apps:\n\n```typescript\nimport { appTool, string } from \'@inferencesh/sdk\';\n\n// Basic app tool\nconst generate = appTool(\'generate_image\', \'infsh/flux-schnell@latest\')\n  .describe(\'Generate an image from a text prompt\')\n  .param(\'prompt\', string(\'Image description\'))\n  .build();\n\n// App tool with setup and defaults\nconst translate = appTool(\'translate\', \'infsh/translator@latest\')\n  .describe(\'Translate text between languages\')\n  .param(\'text\', string(\'Text to translate\'))\n  .param(\'targetLang\', string(\'Target language code\'))\n  .setup({\n    model: \'advanced\',\n    preserveFormatting: true\n  })\n  .input({\n    sourceLang: \'auto\'\n  })\n  .build();\n```\n\n### Agent Tools\n\nTools that delegate to other agents:\n\n```typescript\nimport { agentTool, string } from \'@inferencesh/sdk\';\n\nconst researcher = agentTool(\'research\', \'my-org/researcher@v1\')\n  .describe(\'Research a topic in depth\')\n  .param(\'topic\', string(\'Topic to research\'))\n  .param(\'depth\', string(\'Research depth: brief, moderate, comprehensive\'))\n  .build();\n\nconst coder = agentTool(\'write_code\', \'my-org/coder@latest\')\n  .describe(\'Write code to solve a problem\')\n  .param(\'task\', string(\'Coding task description\'))\n  .param(\'language\', string(\'Programming language\'))\n  .build();\n```\n\n### Webhook Tools\n\nTools that call external HTTP endpoints:\n\n```typescript\nimport { webhookTool, string } from \'@inferencesh/sdk\';\n\n// Slack notification\nconst slack = webhookTool(\'notify_slack\', \'https://hooks.slack.com/services/...\')\n  .describe(\'Send a message to Slack\')\n  .param(\'channel\', string(\'Channel name\'))\n  .param(\'message\', string(\'Message text\'))\n  .build();\n\n// Webhook with secret\nconst github = webhookTool(\'create_issue\', \'https://api.github.com/repos/org/repo/issues\')\n  .describe(\'Create a GitHub issue\')\n  .secret(\'GITHUB_TOKEN\') // Uses stored secret\n  .param(\'title\', string(\'Issue title\'))\n  .param(\'body\', string(\'Issue description\'))\n  .build();\n```\n\n## Tool Builder Methods\n\n### Common Methods\n\n| Method | Description |\n|--------|-------------|\n| `.describe(text)` | Set tool description |\n| `.display(name)` | Set display name |\n| `.param(name, type, default?)` | Add parameter |\n| `.requireApproval()` | Require human approval |\n| `.build()` | Build the tool |\n\n### App Tool Methods\n\n| Method | Description |\n|--------|-------------|\n| `.setup(config)` | Hidden setup configuration |\n| `.input(defaults)` | Default input values |\n\n### Webhook Tool Methods\n\n| Method | Description |\n|--------|-------------|\n| `.secret(name)` | Use stored secret for auth |\n\n## Internal Tools\n\nBuilt-in capabilities you can enable:\n\n```typescript\nimport { internalTools } from \'@inferencesh/sdk\';\n\nconst config = internalTools()\n  .plan()                    // Task planning\n  .memory()                  // Information storage\n  .webSearch(true)          // Web search capability\n  .codeExecution(true)      // Run code\n  .imageGeneration({\n    enabled: true,\n    appRef: \'infsh/flux@latest\'\n  })\n  .build();\n```\n\n### Internal Tool Options\n\n| Tool | Description |\n|------|-------------|\n| `.plan()` | Enable task breakdown and planning |\n| `.memory()` | Enable information storage |\n| `.webSearch(enabled)` | Enable/disable web search |\n| `.codeExecution(enabled)` | Enable/disable code running |\n| `.imageGeneration(config)` | Configure image generation |\n\n## Handling Tool Calls\n\n### Basic Handler\n\n```typescript\nconst response = await agent.sendMessage(\'Greet John\', {\n  onToolCall: async (call) => {\n    let result;\n\n    if (call.name === \'greet\') {\n      result = `Hello, ${call.args.name}!`;\n    } else if (call.name === \'calculate\') {\n      result = eval(call.args.expression);\n    } else {\n      result = { error: `Unknown tool: ${call.name}` };\n    }\n\n    agent.submitToolResult(call.id, result);\n  }\n});\n```\n\n### With Approval\n\n```typescript\nimport * as readline from \'readline\';\n\nasync function promptUser(question: string): Promise<boolean> {\n  const rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n  });\n  return new Promise(resolve => {\n    rl.question(question, answer => {\n      rl.close();\n      resolve(answer.toLowerCase() === \'y\');\n    });\n  });\n}\n\nconst response = await agent.sendMessage(\'Delete temp files\', {\n  onToolCall: async (call) => {\n    if (call.requiresApproval) {\n      console.log(`Tool: ${call.name}`);\n      console.log(`Args: ${JSON.stringify(call.args)}`);\n      const approved = await promptUser(\'Approve? (y/n): \');\n\n      if (!approved) {\n        agent.submitToolResult(call.id, { error: \'Denied by user\' });\n        return;\n      }\n    }\n\n    const result = await executeTool(call.name, call.args);\n    agent.submitToolResult(call.id, result);\n  }\n});\n```\n\n### Widget Results\n\nReturn structured data for UI widgets:\n\n```typescript\nconst response = await agent.sendMessage(\'Show order confirmation\', {\n  onToolCall: async (call) => {\n    if (call.name === \'confirm_order\') {\n      // Return widget data\n      agent.submitToolResult(call.id, {\n        action: { type: \'confirm\' },\n        formData: {\n          orderId: \'12345\',\n          items: [\'Widget A\', \'Widget B\'],\n          total: 99.99\n        }\n      });\n    }\n  }\n});\n```\n\n## TypeScript Types\n\n```typescript\nimport type {\n  AgentTool,\n  ToolCall,\n  ToolResult,\n  ParamType\n} from \'@inferencesh/sdk\';\n\n// Type-safe tool definition\nconst typedTool: AgentTool = tool(\'my_tool\')\n  .describe(\'A typed tool\')\n  .param(\'input\', string(\'Input value\'))\n  .build();\n\n// Type-safe handler\nfunction handleToolCall(call: ToolCall): ToolResult {\n  return { success: true, data: call.args };\n}\n```\n\n## Complete Example\n\n```typescript\nimport {\n  inference, tool, appTool, webhookTool,\n  string, number, integer, boolean, enumOf,\n  array, obj, optional, internalTools\n} from \'@inferencesh/sdk\';\n\nconst client = inference({ apiKey: \'inf_...\' });\n\n// Calculator tool\nconst calculator = tool(\'calculate\')\n  .display(\'Calculator\')\n  .describe(\'Perform mathematical calculations\')\n  .param(\'expression\', string(\'Math expression to evaluate\'))\n  .build();\n\n// Image generation tool\nconst imageGen = appTool(\'generate_image\', \'infsh/flux-schnell@latest\')\n  .describe(\'Generate an image from text\')\n  .param(\'prompt\', string(\'Image description\'))\n  .param(\'style\', enumOf([\'realistic\', \'artistic\', \'cartoon\'], \'Image style\'))\n  .setup({ quality: \'high\' })\n  .input({ steps: 20 })\n  .requireApproval()\n  .build();\n\n// Slack notification tool\nconst slack = webhookTool(\'notify\', \'https://hooks.slack.com/...\')\n  .describe(\'Send Slack notification\')\n  .param(\'message\', string(\'Message to send\'))\n  .build();\n\n// Built-in tools\nconst internals = internalTools()\n  .webSearch(true)\n  .codeExecution(true)\n  .build();\n\n// Create agent with all tools\nconst agent = client.agent({\n  core_app: { ref: \'infsh/claude-sonnet-4@latest\' },\n  system_prompt: \'You are a helpful assistant with various capabilities.\',\n  tools: [calculator, imageGen, slack],\n  internal_tools: internals,\n  temperature: 0.7\n});\n\n// Handle tool calls\nconst response = await agent.sendMessage(\n  \'Calculate 15% tip on $85, then notify Slack\',\n  {\n    onToolCall: async (call) => {\n      if (call.name === \'calculate\') {\n        try {\n          const result = eval(call.args.expression);\n          agent.submitToolResult(call.id, { result });\n        } catch (e) {\n          agent.submitToolResult(call.id, { error: String(e) });\n        }\n      } else if (call.requiresApproval) {\n        const approved = await promptUser(`Allow ${call.name}? (y/n): `);\n        if (!approved) {\n          agent.submitToolResult(call.id, { error: \'Denied\' });\n        }\n        // App/webhook tools execute automatically if approved\n      }\n    }\n  }\n);\n```\n\n## Server Proxy Tools\n\nWhen using the SDK in the browser, tools that require API keys should use webhooks with secrets stored server-side:\n\n```typescript\n// Browser-safe tool definition\nconst apiTool = webhookTool(\'call_api\', \'/api/my-endpoint\')\n  .describe(\'Call server-side API\')\n  .param(\'data\', obj({\n    action: string(\'Action to perform\'),\n    payload: optional(string(\'Optional payload\'))\n  }))\n  .build();\n\n// Server-side handler (e.g., Next.js API route)\n// app/api/my-endpoint/route.ts\nexport async function POST(req: Request) {\n  const { data } = await req.json();\n\n  // Access secrets safely on server\n  const result = await fetch(process.env.EXTERNAL_API_URL, {\n    headers: { Authorization: `Bearer ${process.env.API_SECRET}` },\n    body: JSON.stringify(data)\n  });\n\n  return Response.json(await result.json());\n}\n```\n','9431f7995b4f437b57fff83a5aac3bad','2026-10-26 11:22:16','2026-10-26 11:22:16','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(3529,'enc.7265666572656e6365732f66696c65732e6d64','skill_enc.6a6176617363726970742d73646b__enc.302e302e31','# File Handling Reference\n\nUpload, download, and manage files with the JavaScript SDK.\n\n## Automatic File Upload\n\nLocal file paths in input are automatically uploaded (Node.js):\n\n```typescript\nimport { inference } from \'@inferencesh/sdk\';\n\nconst client = inference({ apiKey: \'inf_...\' });\n\n// File path is auto-uploaded\nconst result = await client.run({\n  app: \'image-processor\',\n  input: {\n    image: \'/path/to/image.png\'\n  }\n});\n```\n\n## Manual File Upload\n\n### Node.js\n\n```typescript\n// Basic upload\nconst file = await client.uploadFile(\'/path/to/image.png\');\nconsole.log(file.uri); // inf://files/abc123\n\nconst result = await client.run({\n  app: \'image-processor\',\n  input: { image: file.uri }\n});\n```\n\n### Upload Options\n\n```typescript\nconst file = await client.uploadFile(\'/path/to/document.pdf\', {\n  filename: \'custom_name.pdf\',      // Custom filename\n  contentType: \'application/pdf\',   // MIME type\n  path: \'/documents/reports\',        // Storage path\n  public: true                       // Publicly accessible\n});\n```\n\n## Browser File Upload\n\n### From File Input\n\n```typescript\nconst input = document.querySelector<HTMLInputElement>(\'input[type=\"file\"]\');\n\ninput.addEventListener(\'change\', async (e) => {\n  const file = input.files?.[0];\n  if (!file) return;\n\n  const uploaded = await client.uploadFile(file);\n  console.log(\'Uploaded:\', uploaded.uri);\n});\n```\n\n### With React\n\n```typescript\nimport { useState } from \'react\';\nimport { inference } from \'@inferencesh/sdk\';\n\nfunction FileUploader() {\n  const [uploading, setUploading] = useState(false);\n  const client = inference({ proxyUrl: \'/api/inference/proxy\' });\n\n  async function handleFile(e: React.ChangeEvent<HTMLInputElement>) {\n    const file = e.target.files?.[0];\n    if (!file) return;\n\n    setUploading(true);\n    try {\n      const uploaded = await client.uploadFile(file);\n      console.log(\'Uploaded:\', uploaded.uri);\n    } finally {\n      setUploading(false);\n    }\n  }\n\n  return (\n    <div>\n      <input type=\"file\" onChange={handleFile} disabled={uploading} />\n      {uploading && <span>Uploading...</span>}\n    </div>\n  );\n}\n```\n\n### Drag and Drop\n\n```typescript\nfunction DropZone() {\n  const client = inference({ proxyUrl: \'/api/inference/proxy\' });\n\n  async function handleDrop(e: React.DragEvent) {\n    e.preventDefault();\n    const files = Array.from(e.dataTransfer.files);\n\n    for (const file of files) {\n      const uploaded = await client.uploadFile(file);\n      console.log(`Uploaded ${file.name}:`, uploaded.uri);\n    }\n  }\n\n  return (\n    <div\n      onDrop={handleDrop}\n      onDragOver={(e) => e.preventDefault()}\n      style={{ border: \'2px dashed #ccc\', padding: 20 }}\n    >\n      Drop files here\n    </div>\n  );\n}\n```\n\n## Supported Input Types\n\n### File Path (Node.js)\n\n```typescript\nconst result = await client.run({\n  app: \'processor\',\n  input: { file: \'/path/to/file.png\' }\n});\n```\n\n### Data URI (Base64)\n\n```typescript\nimport { readFileSync } from \'fs\';\n\nconst buffer = readFileSync(\'image.png\');\nconst b64 = buffer.toString(\'base64\');\n\nconst result = await client.run({\n  app: \'processor\',\n  input: { image: `data:image/png;base64,${b64}` }\n});\n```\n\n### Buffer (Node.js)\n\n```typescript\nimport { readFileSync } from \'fs\';\n\nconst buffer = readFileSync(\'image.png\');\n\nconst file = await client.uploadFile(buffer, {\n  filename: \'image.png\',\n  contentType: \'image/png\'\n});\n```\n\n### Blob (Browser)\n\n```typescript\n// From canvas\nconst canvas = document.querySelector(\'canvas\');\ncanvas.toBlob(async (blob) => {\n  if (!blob) return;\n\n  const file = await client.uploadFile(blob, {\n    filename: \'canvas.png\',\n    contentType: \'image/png\'\n  });\n  console.log(\'Uploaded:\', file.uri);\n});\n```\n\n### File Object (Browser)\n\n```typescript\nconst fileInput = document.querySelector<HTMLInputElement>(\'input[type=\"file\"]\');\nconst file = fileInput.files?.[0];\n\nif (file) {\n  const uploaded = await client.uploadFile(file);\n}\n```\n\n## Working with URLs\n\nUse remote URLs directly (no upload needed):\n\n```typescript\nconst result = await client.run({\n  app: \'image-processor\',\n  input: {\n    image: \'https://example.com/image.png\'\n  }\n});\n```\n\n## Multiple Files\n\n```typescript\n// Upload multiple files\nconst files = await Promise.all([\n  client.uploadFile(\'/path/to/file1.png\'),\n  client.uploadFile(\'/path/to/file2.png\')\n]);\n\nconst result = await client.run({\n  app: \'multi-file-processor\',\n  input: { images: files.map(f => f.uri) }\n});\n```\n\n## File Info\n\n```typescript\nconst file = await client.uploadFile(\'/path/to/image.png\');\n\nconsole.log({\n  uri: file.uri,        // inf://files/abc123\n  url: file.url,        // Direct access URL\n  size: file.size,      // File size in bytes\n  contentType: file.contentType\n});\n```\n\n## Downloading Results\n\n### Node.js\n\n```typescript\nimport { writeFileSync } from \'fs\';\n\nconst result = await client.run({\n  app: \'infsh/flux-schnell\',\n  input: { prompt: \'A sunset\' }\n});\n\n// Result contains URL to generated file\nconst imageUrl = result.output.image;\n\n// Download the file\nconst response = await fetch(imageUrl);\nconst buffer = Buffer.from(await response.arrayBuffer());\nwriteFileSync(\'output.png\', buffer);\n```\n\n### Browser\n\n```typescript\nconst result = await client.run({\n  app: \'infsh/flux-schnell\',\n  input: { prompt: \'A sunset\' }\n});\n\n// Trigger download\nconst link = document.createElement(\'a\');\nlink.href = result.output.image;\nlink.download = \'generated.png\';\nlink.click();\n```\n\n## Agent File Attachments\n\n### Node.js\n\n```typescript\nimport { readFileSync } from \'fs\';\n\nconst agent = client.agent(\'my-org/assistant@latest\');\n\n// From buffer\nconst response = await agent.sendMessage(\'What\\\'s in this image?\', {\n  files: [readFileSync(\'image.png\')]\n});\n```\n\n### Browser\n\n```typescript\nconst agent = client.agent(\'my-org/assistant@latest\');\n\n// From file input\nconst input = document.querySelector<HTMLInputElement>(\'input[type=\"file\"]\');\nconst file = input.files?.[0];\n\nif (file) {\n  const response = await agent.sendMessage(\'Describe this image\', {\n    files: [file]\n  });\n}\n```\n\n### From Base64\n\n```typescript\nconst response = await agent.sendMessage(\'Analyze this document\', {\n  files: [\'data:application/pdf;base64,JVBERi0xLj...\']\n});\n```\n\n### Multiple Files\n\n```typescript\nconst response = await agent.sendMessage(\'Compare these images\', {\n  files: [\n    await fetch(\'image1.png\').then(r => r.blob()),\n    await fetch(\'image2.png\').then(r => r.blob())\n  ]\n});\n```\n\n## Content Type Detection\n\n```typescript\nfunction getContentType(filename: string): string {\n  const ext = filename.split(\'.\').pop()?.toLowerCase();\n  const types: Record<string, string> = {\n    png: \'image/png\',\n    jpg: \'image/jpeg\',\n    jpeg: \'image/jpeg\',\n    gif: \'image/gif\',\n    webp: \'image/webp\',\n    pdf: \'application/pdf\',\n    mp4: \'video/mp4\',\n    mp3: \'audio/mpeg\',\n    wav: \'audio/wav\'\n  };\n  return types[ext || \'\'] || \'application/octet-stream\';\n}\n\nasync function uploadWithAutoType(path: string) {\n  const filename = path.split(\'/\').pop() || \'file\';\n  return client.uploadFile(path, {\n    contentType: getContentType(filename)\n  });\n}\n```\n\n## React Hook for File Upload\n\n```typescript\nimport { useState, useCallback } from \'react\';\nimport { inference } from \'@inferencesh/sdk\';\n\ninterface UploadState {\n  uploading: boolean;\n  progress: number;\n  error: string | null;\n  file: any | null;\n}\n\nfunction useFileUpload() {\n  const [state, setState] = useState<UploadState>({\n    uploading: false,\n    progress: 0,\n    error: null,\n    file: null\n  });\n\n  const client = inference({ proxyUrl: \'/api/inference/proxy\' });\n\n  const upload = useCallback(async (file: File) => {\n    setState({ uploading: true, progress: 0, error: null, file: null });\n\n    try {\n      const uploaded = await client.uploadFile(file, {\n        onProgress: (progress) => {\n          setState(prev => ({ ...prev, progress }));\n        }\n      });\n\n      setState({ uploading: false, progress: 100, error: null, file: uploaded });\n      return uploaded;\n    } catch (e: any) {\n      setState(prev => ({ ...prev, uploading: false, error: e.message }));\n      throw e;\n    }\n  }, []);\n\n  return { ...state, upload };\n}\n```\n\n## Error Handling\n\n```typescript\nimport { FileUploadError } from \'@inferencesh/sdk\';\n\ntry {\n  const file = await client.uploadFile(largeFile);\n} catch (e) {\n  if (e instanceof FileUploadError) {\n    if (e.message.includes(\'too large\')) {\n      console.log(\'File exceeds size limit\');\n    } else if (e.message.includes(\'unsupported\')) {\n      console.log(\'File type not supported\');\n    } else {\n      console.log(\'Upload failed:\', e.message);\n    }\n  }\n}\n```\n\n## Stream Upload (Large Files)\n\n```typescript\nimport { createReadStream } from \'fs\';\nimport { stat } from \'fs/promises\';\n\nasync function uploadLargeFile(filepath: string) {\n  const stats = await stat(filepath);\n  const stream = createReadStream(filepath);\n\n  const file = await client.uploadFile(stream, {\n    filename: filepath.split(\'/\').pop(),\n    contentType: \'application/octet-stream\',\n    size: stats.size\n  });\n\n  return file;\n}\n```\n','71ed26b265b0dbc4ad0a30091c38b20f','2026-10-26 11:22:16','2026-10-26 11:22:16','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(3530,'enc.7265666572656e6365732f72656163742d696e746567726174696f6e2e6d64','skill_enc.6a6176617363726970742d73646b__enc.302e302e31','# React Integration Reference\n\nBuild AI-powered React applications with the inference.sh SDK.\n\n## Setup\n\n```bash\nnpm install @inferencesh/sdk\n```\n\nConfigure proxy (keep API keys on server):\n\n```typescript\n// app/api/inference/proxy/route.ts (Next.js)\nimport { createRouteHandler } from \'@inferencesh/sdk/proxy/nextjs\';\n\nconst route = createRouteHandler({\n  apiKey: process.env.INFERENCE_API_KEY!\n});\n\nexport const POST = route.POST;\n```\n\n## Basic Client Setup\n\n```typescript\nimport { inference } from \'@inferencesh/sdk\';\n\n// Create client with proxy (no API key in browser)\nconst client = inference({ proxyUrl: \'/api/inference/proxy\' });\n```\n\n## useInference Hook\n\nCustom hook for running AI apps:\n\n```typescript\nimport { useState, useCallback } from \'react\';\nimport { inference } from \'@inferencesh/sdk\';\n\ninterface UseInferenceState<T> {\n  data: T | null;\n  loading: boolean;\n  error: string | null;\n}\n\nfunction useInference<T = any>() {\n  const [state, setState] = useState<UseInferenceState<T>>({\n    data: null,\n    loading: false,\n    error: null\n  });\n\n  const client = inference({ proxyUrl: \'/api/inference/proxy\' });\n\n  const run = useCallback(async (config: any) => {\n    setState({ data: null, loading: true, error: null });\n\n    try {\n      const result = await client.run(config);\n      setState({ data: result.output as T, loading: false, error: null });\n      return result.output as T;\n    } catch (e: any) {\n      setState({ data: null, loading: false, error: e.message });\n      throw e;\n    }\n  }, []);\n\n  return { ...state, run };\n}\n\n// Usage\nfunction ImageGenerator() {\n  const { data, loading, error, run } = useInference<{ image: string }>();\n\n  const generate = () => run({\n    app: \'infsh/flux-schnell\',\n    input: { prompt: \'A sunset\' }\n  });\n\n  return (\n    <div>\n      <button onClick={generate} disabled={loading}>\n        {loading ? \'Generating...\' : \'Generate\'}\n      </button>\n      {error && <div className=\"error\">{error}</div>}\n      {data && <img src={data.image} alt=\"Generated\" />}\n    </div>\n  );\n}\n```\n\n## useChat Hook\n\nConversational AI with streaming:\n\n```typescript\nimport { useState, useCallback, useRef } from \'react\';\nimport { inference } from \'@inferencesh/sdk\';\n\ninterface Message {\n  role: \'user\' | \'assistant\';\n  content: string;\n}\n\nfunction useChat(agentRef: string) {\n  const [messages, setMessages] = useState<Message[]>([]);\n  const [loading, setLoading] = useState(false);\n  const [streaming, setStreaming] = useState(false);\n\n  const clientRef = useRef(inference({ proxyUrl: \'/api/inference/proxy\' }));\n  const agentRef_ = useRef(clientRef.current.agent(agentRef));\n\n  const sendMessage = useCallback(async (content: string) => {\n    // Add user message\n    setMessages(prev => [...prev, { role: \'user\', content }]);\n    setLoading(true);\n    setStreaming(true);\n\n    // Placeholder for assistant response\n    let assistantContent = \'\';\n    setMessages(prev => [...prev, { role: \'assistant\', content: \'\' }]);\n\n    try {\n      await agentRef_.current.sendMessage(content, {\n        onMessage: (msg) => {\n          if (msg.content) {\n            assistantContent += msg.content;\n            setMessages(prev => [\n              ...prev.slice(0, -1),\n              { role: \'assistant\', content: assistantContent }\n            ]);\n          }\n        }\n      });\n    } finally {\n      setLoading(false);\n      setStreaming(false);\n    }\n  }, []);\n\n  const reset = useCallback(() => {\n    agentRef_.current.reset();\n    setMessages([]);\n  }, []);\n\n  return { messages, loading, streaming, sendMessage, reset };\n}\n\n// Usage\nfunction ChatComponent() {\n  const { messages, loading, sendMessage, reset } = useChat(\'my-org/assistant@latest\');\n  const [input, setInput] = useState(\'\');\n\n  const handleSubmit = (e: React.FormEvent) => {\n    e.preventDefault();\n    if (input.trim()) {\n      sendMessage(input);\n      setInput(\'\');\n    }\n  };\n\n  return (\n    <div className=\"chat\">\n      <div className=\"messages\">\n        {messages.map((msg, i) => (\n          <div key={i} className={`message ${msg.role}`}>\n            {msg.content}\n          </div>\n        ))}\n      </div>\n\n      <form onSubmit={handleSubmit}>\n        <input\n          value={input}\n          onChange={(e) => setInput(e.target.value)}\n          placeholder=\"Type a message...\"\n          disabled={loading}\n        />\n        <button type=\"submit\" disabled={loading}>Send</button>\n      </form>\n\n      <button onClick={reset}>New Chat</button>\n    </div>\n  );\n}\n```\n\n## useStream Hook\n\nStream task progress:\n\n```typescript\nimport { useState, useCallback, useRef } from \'react\';\nimport { inference } from \'@inferencesh/sdk\';\n\ninterface StreamState {\n  status: string;\n  progress: number;\n  logs: string[];\n  output: any;\n  error: string | null;\n}\n\nfunction useStream() {\n  const [state, setState] = useState<StreamState>({\n    status: \'idle\',\n    progress: 0,\n    logs: [],\n    output: null,\n    error: null\n  });\n\n  const controllerRef = useRef<AbortController | null>(null);\n  const client = inference({ proxyUrl: \'/api/inference/proxy\' });\n\n  const run = useCallback(async (config: any) => {\n    controllerRef.current = new AbortController();\n\n    setState({\n      status: \'starting\',\n      progress: 0,\n      logs: [],\n      output: null,\n      error: null\n    });\n\n    try {\n      const stream = await client.run(config, {\n        stream: true,\n        signal: controllerRef.current.signal\n      });\n\n      for await (const update of stream) {\n        setState(prev => ({\n          ...prev,\n          status: update.status,\n          progress: update.progress\n            ? (update.progress.current / update.progress.total) * 100\n            : prev.progress,\n          logs: update.logs ? [...prev.logs, ...update.logs] : prev.logs,\n          output: update.output || prev.output\n        }));\n      }\n    } catch (e: any) {\n      if (e.name !== \'AbortError\') {\n        setState(prev => ({ ...prev, status: \'error\', error: e.message }));\n      }\n    }\n  }, []);\n\n  const cancel = useCallback(() => {\n    controllerRef.current?.abort();\n    setState(prev => ({ ...prev, status: \'cancelled\' }));\n  }, []);\n\n  return { ...state, run, cancel };\n}\n\n// Usage\nfunction VideoGenerator() {\n  const { status, progress, logs, output, run, cancel } = useStream();\n\n  return (\n    <div>\n      <button onClick={() => run({\n        app: \'google/veo-3-1-fast\',\n        input: { prompt: \'Ocean waves\' }\n      })}>\n        Generate Video\n      </button>\n      <button onClick={cancel}>Cancel</button>\n\n      <div>Status: {status}</div>\n      <progress value={progress} max={100} />\n\n      <div className=\"logs\">\n        {logs.map((log, i) => <div key={i}>{log}</div>)}\n      </div>\n\n      {output && <video src={output.video} controls />}\n    </div>\n  );\n}\n```\n\n## File Upload Component\n\n```typescript\nimport { useState, useCallback } from \'react\';\nimport { inference } from \'@inferencesh/sdk\';\n\nfunction FileUpload({ onUpload }: { onUpload: (uri: string) => void }) {\n  const [uploading, setUploading] = useState(false);\n  const [preview, setPreview] = useState<string | null>(null);\n\n  const client = inference({ proxyUrl: \'/api/inference/proxy\' });\n\n  const handleFile = useCallback(async (e: React.ChangeEvent<HTMLInputElement>) => {\n    const file = e.target.files?.[0];\n    if (!file) return;\n\n    // Show preview\n    const reader = new FileReader();\n    reader.onload = () => setPreview(reader.result as string);\n    reader.readAsDataURL(file);\n\n    // Upload\n    setUploading(true);\n    try {\n      const uploaded = await client.uploadFile(file);\n      onUpload(uploaded.uri);\n    } finally {\n      setUploading(false);\n    }\n  }, [onUpload]);\n\n  return (\n    <div>\n      <input type=\"file\" onChange={handleFile} disabled={uploading} />\n      {uploading && <span>Uploading...</span>}\n      {preview && <img src={preview} alt=\"Preview\" style={{ maxWidth: 200 }} />}\n    </div>\n  );\n}\n```\n\n## Image Analysis Component\n\n```typescript\nfunction ImageAnalyzer() {\n  const [imageUri, setImageUri] = useState<string | null>(null);\n  const { messages, sendMessage, loading } = useChat(\'my-org/vision-assistant@latest\');\n\n  const handleUpload = (uri: string) => {\n    setImageUri(uri);\n  };\n\n  const analyze = () => {\n    if (imageUri) {\n      sendMessage(`Analyze this image: ${imageUri}`);\n    }\n  };\n\n  return (\n    <div>\n      <FileUpload onUpload={handleUpload} />\n\n      <button onClick={analyze} disabled={!imageUri || loading}>\n        Analyze Image\n      </button>\n\n      <div className=\"messages\">\n        {messages.map((msg, i) => (\n          <div key={i} className={msg.role}>{msg.content}</div>\n        ))}\n      </div>\n    </div>\n  );\n}\n```\n\n## Tool Handling Component\n\n```typescript\nimport { useState, useCallback } from \'react\';\nimport { inference, tool, string } from \'@inferencesh/sdk\';\n\nfunction AgentWithTools() {\n  const [response, setResponse] = useState(\'\');\n  const [pendingTool, setPendingTool] = useState<any>(null);\n\n  const client = inference({ proxyUrl: \'/api/inference/proxy\' });\n\n  const confirmTool = tool(\'confirm_action\')\n    .describe(\'Confirm a destructive action\')\n    .param(\'action\', string(\'Action to confirm\'))\n    .requireApproval()\n    .build();\n\n  const agent = client.agent({\n    core_app: { ref: \'infsh/claude-sonnet-4@latest\' },\n    tools: [confirmTool]\n  });\n\n  const handleMessage = useCallback(async (message: string) => {\n    setResponse(\'\');\n\n    await agent.sendMessage(message, {\n      onMessage: (msg) => {\n        if (msg.content) {\n          setResponse(prev => prev + msg.content);\n        }\n      },\n      onToolCall: (call) => {\n        if (call.requiresApproval) {\n          setPendingTool(call);\n        }\n      }\n    });\n  }, []);\n\n  const handleApprove = (approved: boolean) => {\n    if (pendingTool) {\n      if (approved) {\n        agent.submitToolResult(pendingTool.id, { confirmed: true });\n      } else {\n        agent.submitToolResult(pendingTool.id, { error: \'Denied by user\' });\n      }\n      setPendingTool(null);\n    }\n  };\n\n  return (\n    <div>\n      <button onClick={() => handleMessage(\'Delete all temp files\')}>\n        Run Agent\n      </button>\n\n      <div>{response}</div>\n\n      {pendingTool && (\n        <div className=\"approval-dialog\">\n          <p>Agent wants to: {pendingTool.args.action}</p>\n          <button onClick={() => handleApprove(true)}>Approve</button>\n          <button onClick={() => handleApprove(false)}>Deny</button>\n        </div>\n      )}\n    </div>\n  );\n}\n```\n\n## Context Provider\n\nShare client across components:\n\n```typescript\nimport { createContext, useContext, useMemo, ReactNode } from \'react\';\nimport { inference, type InferenceClient } from \'@inferencesh/sdk\';\n\nconst InferenceContext = createContext<InferenceClient | null>(null);\n\nexport function InferenceProvider({ children }: { children: ReactNode }) {\n  const client = useMemo(() =>\n    inference({ proxyUrl: \'/api/inference/proxy\' }),\n    []\n  );\n\n  return (\n    <InferenceContext.Provider value={client}>\n      {children}\n    </InferenceContext.Provider>\n  );\n}\n\nexport function useInferenceClient() {\n  const client = useContext(InferenceContext);\n  if (!client) {\n    throw new Error(\'useInferenceClient must be used within InferenceProvider\');\n  }\n  return client;\n}\n\n// Usage in app\nfunction App() {\n  return (\n    <InferenceProvider>\n      <ChatComponent />\n      <ImageGenerator />\n    </InferenceProvider>\n  );\n}\n\n// Usage in component\nfunction MyComponent() {\n  const client = useInferenceClient();\n  // Use client...\n}\n```\n\n## Suspense Integration\n\n```typescript\nimport { Suspense } from \'react\';\nimport { use } from \'react\';\nimport { inference } from \'@inferencesh/sdk\';\n\nconst client = inference({ proxyUrl: \'/api/inference/proxy\' });\n\n// Create a promise for the resource\nfunction createImageResource(prompt: string) {\n  const promise = client.run({\n    app: \'infsh/flux-schnell\',\n    input: { prompt }\n  }).then(r => r.output.image);\n\n  return { read: () => use(promise) };\n}\n\nfunction GeneratedImage({ resource }: { resource: ReturnType<typeof createImageResource> }) {\n  const imageUrl = resource.read();\n  return <img src={imageUrl} alt=\"Generated\" />;\n}\n\nfunction App() {\n  const [resource, setResource] = useState<any>(null);\n\n  const generate = () => {\n    setResource(createImageResource(\'A sunset\'));\n  };\n\n  return (\n    <div>\n      <button onClick={generate}>Generate</button>\n      {resource && (\n        <Suspense fallback={<div>Generating...</div>}>\n          <GeneratedImage resource={resource} />\n        </Suspense>\n      )}\n    </div>\n  );\n}\n```\n\n## Error Boundary\n\n```typescript\nimport { Component, ReactNode } from \'react\';\n\ninterface Props {\n  children: ReactNode;\n  fallback?: ReactNode;\n}\n\ninterface State {\n  hasError: boolean;\n  error: Error | null;\n}\n\nclass InferenceErrorBoundary extends Component<Props, State> {\n  state: State = { hasError: false, error: null };\n\n  static getDerivedStateFromError(error: Error): State {\n    return { hasError: true, error };\n  }\n\n  render() {\n    if (this.state.hasError) {\n      return this.props.fallback || (\n        <div className=\"error\">\n          <h2>Something went wrong</h2>\n          <p>{this.state.error?.message}</p>\n          <button onClick={() => this.setState({ hasError: false, error: null })}>\n            Try again\n          </button>\n        </div>\n      );\n    }\n\n    return this.props.children;\n  }\n}\n\n// Usage\nfunction App() {\n  return (\n    <InferenceErrorBoundary>\n      <AIFeatures />\n    </InferenceErrorBoundary>\n  );\n}\n```\n','ce7de67327c8cf4a399a9f8139fc5c13','2026-10-26 11:22:16','2026-10-26 11:22:16','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(3531,'enc.7265666572656e6365732f66696c65732e6d64','skill_enc.6a6176617363726970742d73646b__enc.302e302e31','# File Handling Reference\n\nUpload, download, and manage files with the JavaScript SDK.\n\n## Automatic File Upload\n\nLocal file paths in input are automatically uploaded (Node.js):\n\n```typescript\nimport { inference } from \'@inferencesh/sdk\';\n\nconst client = inference({ apiKey: \'inf_...\' });\n\n// File path is auto-uploaded\nconst result = await client.run({\n  app: \'image-processor\',\n  input: {\n    image: \'/path/to/image.png\'\n  }\n});\n```\n\n## Manual File Upload\n\n### Node.js\n\n```typescript\n// Basic upload\nconst file = await client.uploadFile(\'/path/to/image.png\');\nconsole.log(file.uri); // inf://files/abc123\n\nconst result = await client.run({\n  app: \'image-processor\',\n  input: { image: file.uri }\n});\n```\n\n### Upload Options\n\n```typescript\nconst file = await client.uploadFile(\'/path/to/document.pdf\', {\n  filename: \'custom_name.pdf\',      // Custom filename\n  contentType: \'application/pdf\',   // MIME type\n  path: \'/documents/reports\',        // Storage path\n  public: true                       // Publicly accessible\n});\n```\n\n## Browser File Upload\n\n### From File Input\n\n```typescript\nconst input = document.querySelector<HTMLInputElement>(\'input[type=\"file\"]\');\n\ninput.addEventListener(\'change\', async (e) => {\n  const file = input.files?.[0];\n  if (!file) return;\n\n  const uploaded = await client.uploadFile(file);\n  console.log(\'Uploaded:\', uploaded.uri);\n});\n```\n\n### With React\n\n```typescript\nimport { useState } from \'react\';\nimport { inference } from \'@inferencesh/sdk\';\n\nfunction FileUploader() {\n  const [uploading, setUploading] = useState(false);\n  const client = inference({ proxyUrl: \'/api/inference/proxy\' });\n\n  async function handleFile(e: React.ChangeEvent<HTMLInputElement>) {\n    const file = e.target.files?.[0];\n    if (!file) return;\n\n    setUploading(true);\n    try {\n      const uploaded = await client.uploadFile(file);\n      console.log(\'Uploaded:\', uploaded.uri);\n    } finally {\n      setUploading(false);\n    }\n  }\n\n  return (\n    <div>\n      <input type=\"file\" onChange={handleFile} disabled={uploading} />\n      {uploading && <span>Uploading...</span>}\n    </div>\n  );\n}\n```\n\n### Drag and Drop\n\n```typescript\nfunction DropZone() {\n  const client = inference({ proxyUrl: \'/api/inference/proxy\' });\n\n  async function handleDrop(e: React.DragEvent) {\n    e.preventDefault();\n    const files = Array.from(e.dataTransfer.files);\n\n    for (const file of files) {\n      const uploaded = await client.uploadFile(file);\n      console.log(`Uploaded ${file.name}:`, uploaded.uri);\n    }\n  }\n\n  return (\n    <div\n      onDrop={handleDrop}\n      onDragOver={(e) => e.preventDefault()}\n      style={{ border: \'2px dashed #ccc\', padding: 20 }}\n    >\n      Drop files here\n    </div>\n  );\n}\n```\n\n## Supported Input Types\n\n### File Path (Node.js)\n\n```typescript\nconst result = await client.run({\n  app: \'processor\',\n  input: { file: \'/path/to/file.png\' }\n});\n```\n\n### Data URI (Base64)\n\n```typescript\nimport { readFileSync } from \'fs\';\n\nconst buffer = readFileSync(\'image.png\');\nconst b64 = buffer.toString(\'base64\');\n\nconst result = await client.run({\n  app: \'processor\',\n  input: { image: `data:image/png;base64,${b64}` }\n});\n```\n\n### Buffer (Node.js)\n\n```typescript\nimport { readFileSync } from \'fs\';\n\nconst buffer = readFileSync(\'image.png\');\n\nconst file = await client.uploadFile(buffer, {\n  filename: \'image.png\',\n  contentType: \'image/png\'\n});\n```\n\n### Blob (Browser)\n\n```typescript\n// From canvas\nconst canvas = document.querySelector(\'canvas\');\ncanvas.toBlob(async (blob) => {\n  if (!blob) return;\n\n  const file = await client.uploadFile(blob, {\n    filename: \'canvas.png\',\n    contentType: \'image/png\'\n  });\n  console.log(\'Uploaded:\', file.uri);\n});\n```\n\n### File Object (Browser)\n\n```typescript\nconst fileInput = document.querySelector<HTMLInputElement>(\'input[type=\"file\"]\');\nconst file = fileInput.files?.[0];\n\nif (file) {\n  const uploaded = await client.uploadFile(file);\n}\n```\n\n## Working with URLs\n\nUse remote URLs directly (no upload needed):\n\n```typescript\nconst result = await client.run({\n  app: \'image-processor\',\n  input: {\n    image: \'https://example.com/image.png\'\n  }\n});\n```\n\n## Multiple Files\n\n```typescript\n// Upload multiple files\nconst files = await Promise.all([\n  client.uploadFile(\'/path/to/file1.png\'),\n  client.uploadFile(\'/path/to/file2.png\')\n]);\n\nconst result = await client.run({\n  app: \'multi-file-processor\',\n  input: { images: files.map(f => f.uri) }\n});\n```\n\n## File Info\n\n```typescript\nconst file = await client.uploadFile(\'/path/to/image.png\');\n\nconsole.log({\n  uri: file.uri,        // inf://files/abc123\n  url: file.url,        // Direct access URL\n  size: file.size,      // File size in bytes\n  contentType: file.contentType\n});\n```\n\n## Downloading Results\n\n### Node.js\n\n```typescript\nimport { writeFileSync } from \'fs\';\n\nconst result = await client.run({\n  app: \'infsh/flux-schnell\',\n  input: { prompt: \'A sunset\' }\n});\n\n// Result contains URL to generated file\nconst imageUrl = result.output.image;\n\n// Download the file\nconst response = await fetch(imageUrl);\nconst buffer = Buffer.from(await response.arrayBuffer());\nwriteFileSync(\'output.png\', buffer);\n```\n\n### Browser\n\n```typescript\nconst result = await client.run({\n  app: \'infsh/flux-schnell\',\n  input: { prompt: \'A sunset\' }\n});\n\n// Trigger download\nconst link = document.createElement(\'a\');\nlink.href = result.output.image;\nlink.download = \'generated.png\';\nlink.click();\n```\n\n## Agent File Attachments\n\n### Node.js\n\n```typescript\nimport { readFileSync } from \'fs\';\n\nconst agent = client.agent(\'my-org/assistant@latest\');\n\n// From buffer\nconst response = await agent.sendMessage(\'What\\\'s in this image?\', {\n  files: [readFileSync(\'image.png\')]\n});\n```\n\n### Browser\n\n```typescript\nconst agent = client.agent(\'my-org/assistant@latest\');\n\n// From file input\nconst input = document.querySelector<HTMLInputElement>(\'input[type=\"file\"]\');\nconst file = input.files?.[0];\n\nif (file) {\n  const response = await agent.sendMessage(\'Describe this image\', {\n    files: [file]\n  });\n}\n```\n\n### From Base64\n\n```typescript\nconst response = await agent.sendMessage(\'Analyze this document\', {\n  files: [\'data:application/pdf;base64,JVBERi0xLj...\']\n});\n```\n\n### Multiple Files\n\n```typescript\nconst response = await agent.sendMessage(\'Compare these images\', {\n  files: [\n    await fetch(\'image1.png\').then(r => r.blob()),\n    await fetch(\'image2.png\').then(r => r.blob())\n  ]\n});\n```\n\n## Content Type Detection\n\n```typescript\nfunction getContentType(filename: string): string {\n  const ext = filename.split(\'.\').pop()?.toLowerCase();\n  const types: Record<string, string> = {\n    png: \'image/png\',\n    jpg: \'image/jpeg\',\n    jpeg: \'image/jpeg\',\n    gif: \'image/gif\',\n    webp: \'image/webp\',\n    pdf: \'application/pdf\',\n    mp4: \'video/mp4\',\n    mp3: \'audio/mpeg\',\n    wav: \'audio/wav\'\n  };\n  return types[ext || \'\'] || \'application/octet-stream\';\n}\n\nasync function uploadWithAutoType(path: string) {\n  const filename = path.split(\'/\').pop() || \'file\';\n  return client.uploadFile(path, {\n    contentType: getContentType(filename)\n  });\n}\n```\n\n## React Hook for File Upload\n\n```typescript\nimport { useState, useCallback } from \'react\';\nimport { inference } from \'@inferencesh/sdk\';\n\ninterface UploadState {\n  uploading: boolean;\n  progress: number;\n  error: string | null;\n  file: any | null;\n}\n\nfunction useFileUpload() {\n  const [state, setState] = useState<UploadState>({\n    uploading: false,\n    progress: 0,\n    error: null,\n    file: null\n  });\n\n  const client = inference({ proxyUrl: \'/api/inference/proxy\' });\n\n  const upload = useCallback(async (file: File) => {\n    setState({ uploading: true, progress: 0, error: null, file: null });\n\n    try {\n      const uploaded = await client.uploadFile(file, {\n        onProgress: (progress) => {\n          setState(prev => ({ ...prev, progress }));\n        }\n      });\n\n      setState({ uploading: false, progress: 100, error: null, file: uploaded });\n      return uploaded;\n    } catch (e: any) {\n      setState(prev => ({ ...prev, uploading: false, error: e.message }));\n      throw e;\n    }\n  }, []);\n\n  return { ...state, upload };\n}\n```\n\n## Error Handling\n\n```typescript\nimport { FileUploadError } from \'@inferencesh/sdk\';\n\ntry {\n  const file = await client.uploadFile(largeFile);\n} catch (e) {\n  if (e instanceof FileUploadError) {\n    if (e.message.includes(\'too large\')) {\n      console.log(\'File exceeds size limit\');\n    } else if (e.message.includes(\'unsupported\')) {\n      console.log(\'File type not supported\');\n    } else {\n      console.log(\'Upload failed:\', e.message);\n    }\n  }\n}\n```\n\n## Stream Upload (Large Files)\n\n```typescript\nimport { createReadStream } from \'fs\';\nimport { stat } from \'fs/promises\';\n\nasync function uploadLargeFile(filepath: string) {\n  const stats = await stat(filepath);\n  const stream = createReadStream(filepath);\n\n  const file = await client.uploadFile(stream, {\n    filename: filepath.split(\'/\').pop(),\n    contentType: \'application/octet-stream\',\n    size: stats.size\n  });\n\n  return file;\n}\n```\n','71ed26b265b0dbc4ad0a30091c38b20f','2026-10-26 11:22:16','2026-10-26 11:22:16','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(3532,'enc.7265666572656e6365732f6167656e742d7061747465726e732e6d64','skill_enc.6a6176617363726970742d73646b__enc.302e302e31','# Agent Patterns\n\nCommon patterns for building agents with the JavaScript SDK.\n\n## Multi-Agent Orchestration\n\nDelegate tasks to specialized sub-agents:\n\n```typescript\nimport { inference, agentTool, string } from \'@inferencesh/sdk\';\n\nconst client = inference({ apiKey: \'inf_...\' });\n\n// Define sub-agents as tools\nconst researcher = agentTool(\'research\', \'my-org/researcher@latest\')\n  .describe(\'Research a topic thoroughly\')\n  .param(\'topic\', string(\'Topic to research\'))\n  .build();\n\nconst writer = agentTool(\'write\', \'my-org/writer@latest\')\n  .describe(\'Write content based on research\')\n  .param(\'outline\', string(\'Content outline\'))\n  .param(\'research\', string(\'Research findings\'))\n  .build();\n\n// Orchestrator agent\nconst orchestrator = client.agent({\n  core_app: { ref: \'infsh/claude-sonnet-4@latest\' },\n  system_prompt: `You are an orchestrator that:\n1. Uses the research tool to gather information\n2. Uses the write tool to create content\nCoordinate between agents to produce high-quality output.`,\n  tools: [researcher, writer]\n});\n\nconst response = await orchestrator.sendMessage(\'Create a blog post about AI agents\');\n```\n\n## RAG Pattern (Retrieval-Augmented Generation)\n\nCombine search with LLM responses:\n\n```typescript\nimport { inference, appTool, string } from \'@inferencesh/sdk\';\n\nconst client = inference({ apiKey: \'inf_...\' });\n\n// Search tool\nconst search = appTool(\'search\', \'tavily/search-assistant@latest\')\n  .describe(\'Search the web for current information\')\n  .param(\'query\', string(\'Search query\'))\n  .build();\n\n// RAG agent\nconst ragAgent = client.agent({\n  core_app: { ref: \'infsh/claude-sonnet-4@latest\' },\n  system_prompt: `You help users with current information.\nWhen asked about recent events or facts you\'re unsure about,\nuse the search tool to find accurate, up-to-date information.\nAlways cite your sources.`,\n  tools: [search]\n});\n\nconst response = await ragAgent.sendMessage(\n  \'What are the latest developments in quantum computing?\'\n);\n```\n\n## Code Execution Pattern\n\nAgents that can write and run code:\n\n```typescript\nimport { inference, internalTools } from \'@inferencesh/sdk\';\n\nconst client = inference({ apiKey: \'inf_...\' });\n\nconst config = internalTools()\n  .codeExecution(true)\n  .build();\n\nconst coder = client.agent({\n  core_app: { ref: \'infsh/claude-sonnet-4@latest\' },\n  system_prompt: `You are a coding assistant.\nWrite code to solve problems and execute it to verify it works.\nExplain your approach and show the output.`,\n  internal_tools: config\n});\n\nconst response = await coder.sendMessage(\'Calculate the first 20 Fibonacci numbers\');\n```\n\n## Human-in-the-Loop Pattern\n\nRequire approval for sensitive operations:\n\n```typescript\nimport { inference, tool, string } from \'@inferencesh/sdk\';\nimport * as readline from \'readline\';\n\nconst client = inference({ apiKey: \'inf_...\' });\n\n// Tool requiring approval\nconst deleteFile = tool(\'delete_file\')\n  .describe(\'Delete a file from the filesystem\')\n  .param(\'path\', string(\'File path to delete\'))\n  .requireApproval()\n  .build();\n\nasync function promptUser(question: string): Promise<boolean> {\n  const rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n  });\n\n  return new Promise((resolve) => {\n    rl.question(question, (answer) => {\n      rl.close();\n      resolve(answer.toLowerCase() === \'y\');\n    });\n  });\n}\n\nconst agent = client.agent({\n  core_app: { ref: \'infsh/claude-sonnet-4@latest\' },\n  tools: [deleteFile]\n});\n\nconst response = await agent.sendMessage(\'Clean up temporary files in /tmp/myapp\', {\n  onToolCall: async (call) => {\n    if (call.requiresApproval) {\n      console.log(`\\n⚠️  Agent wants to: ${call.name}`);\n      console.log(`   Arguments: ${JSON.stringify(call.args)}`);\n      const approved = await promptUser(\'Allow? (y/n): \');\n\n      if (approved) {\n        const result = await executeOperation(call.name, call.args);\n        agent.submitToolResult(call.id, result);\n      } else {\n        agent.submitToolResult(call.id, { error: \'Operation denied by user\' });\n      }\n    }\n  }\n});\n```\n\n## Conversation Memory Pattern\n\nMaintain context across sessions:\n\n```typescript\nimport { inference } from \'@inferencesh/sdk\';\nimport { readFileSync, writeFileSync, existsSync } from \'fs\';\n\nconst client = inference({ apiKey: \'inf_...\' });\n\nfunction saveChat(agent: any, filepath: string) {\n  const chat = agent.getChat();\n  writeFileSync(filepath, JSON.stringify(chat, null, 2));\n}\n\nasync function loadAndContinue(filepath: string) {\n  const agent = client.agent(\'my-org/assistant@latest\');\n\n  if (existsSync(filepath)) {\n    const chat = JSON.parse(readFileSync(filepath, \'utf-8\'));\n    // Restore by replaying user messages\n    for (const msg of chat.messages) {\n      if (msg.role === \'user\') {\n        await agent.sendMessage(msg.content);\n      }\n    }\n  }\n\n  return agent;\n}\n\n// Usage\nconst agent = await loadAndContinue(\'conversation.json\');\nconst response = await agent.sendMessage(\'Continue where we left off\');\nsaveChat(agent, \'conversation.json\');\n```\n\n## Streaming with Progress UI\n\nReal-time updates for better UX:\n\n```typescript\nimport { inference } from \'@inferencesh/sdk\';\n\nconst client = inference({ apiKey: \'inf_...\' });\nconst agent = client.agent(\'my-org/assistant@latest\');\n\nconst response = await agent.sendMessage(\'Generate a report on market trends\', {\n  onMessage: (msg) => {\n    if (msg.content) {\n      process.stdout.write(msg.content);\n    }\n  },\n  onToolCall: async (call) => {\n    console.log(`\\n🔧 Using tool: ${call.name}`);\n    const result = await executeTool(call.name, call.args);\n    agent.submitToolResult(call.id, result);\n    console.log(\'✅ Tool completed\');\n  }\n});\n\nconsole.log(\'\\n\\n📊 Report complete!\');\n```\n\n## React Integration Pattern\n\nUse in React components:\n\n```typescript\nimport { useState, useCallback } from \'react\';\nimport { inference } from \'@inferencesh/sdk\';\n\nconst client = inference({ proxyUrl: \'/api/inference/proxy\' });\n\nfunction ChatComponent() {\n  const [messages, setMessages] = useState<string[]>([]);\n  const [input, setInput] = useState(\'\');\n  const [agent] = useState(() => client.agent(\'my-org/assistant@latest\'));\n\n  const sendMessage = useCallback(async () => {\n    if (!input.trim()) return;\n\n    setMessages(prev => [...prev, `You: ${input}`]);\n    setInput(\'\');\n\n    let response = \'\';\n    await agent.sendMessage(input, {\n      onMessage: (msg) => {\n        if (msg.content) {\n          response += msg.content;\n          setMessages(prev => [\n            ...prev.slice(0, -1),\n            `Assistant: ${response}`\n          ]);\n        }\n      }\n    });\n  }, [input, agent]);\n\n  return (\n    <div>\n      {messages.map((msg, i) => <div key={i}>{msg}</div>)}\n      <input value={input} onChange={e => setInput(e.target.value)} />\n      <button onClick={sendMessage}>Send</button>\n    </div>\n  );\n}\n```\n\n## Error Recovery Pattern\n\nGraceful handling of failures:\n\n```typescript\nimport { inference, RequirementsNotMetException, InferenceError } from \'@inferencesh/sdk\';\n\nconst client = inference({ apiKey: \'inf_...\' });\n\nasync function robustRun(config: any, maxRetries = 3) {\n  for (let attempt = 0; attempt < maxRetries; attempt++) {\n    try {\n      return await client.run(config);\n    } catch (e) {\n      if (e instanceof RequirementsNotMetException) {\n        console.log(\'Missing requirements:\', e.errors);\n        throw e;\n      }\n      if (e instanceof InferenceError && attempt < maxRetries - 1) {\n        const wait = Math.pow(2, attempt) * 1000;\n        console.log(`Error: ${e.message}. Retrying in ${wait}ms...`);\n        await new Promise(r => setTimeout(r, wait));\n      } else {\n        throw e;\n      }\n    }\n  }\n}\n\nconst result = await robustRun({\n  app: \'infsh/flux-schnell\',\n  input: { prompt: \'A serene landscape\' }\n});\n```\n\n## Batch Processing Pattern\n\nProcess multiple items efficiently:\n\n```typescript\nimport { inference } from \'@inferencesh/sdk\';\n\nconst client = inference({ apiKey: \'inf_...\' });\n\nasync function processBatch(items: string[], concurrency = 5) {\n  const results: any[] = [];\n  const queue = [...items];\n  const inProgress: Promise<void>[] = [];\n\n  async function processOne(item: string) {\n    const result = await client.run({\n      app: \'infsh/flux-schnell\',\n      input: { prompt: item }\n    });\n    results.push(result);\n  }\n\n  while (queue.length > 0 || inProgress.length > 0) {\n    // Fill up to concurrency limit\n    while (queue.length > 0 && inProgress.length < concurrency) {\n      const item = queue.shift()!;\n      const promise = processOne(item).then(() => {\n        const index = inProgress.indexOf(promise);\n        if (index > -1) inProgress.splice(index, 1);\n      });\n      inProgress.push(promise);\n    }\n\n    // Wait for at least one to complete\n    if (inProgress.length > 0) {\n      await Promise.race(inProgress);\n    }\n  }\n\n  return results;\n}\n\nconst prompts = [\n  \'A mountain sunrise\',\n  \'A city at night\',\n  \'An ocean sunset\',\n  \'A forest path\'\n];\n\nconst results = await processBatch(prompts);\n```\n\n## Next.js Server Actions Pattern\n\nUse with React Server Components:\n\n```typescript\n// app/actions.ts\n\'use server\';\n\nimport { inference } from \'@inferencesh/sdk\';\n\nconst client = inference({ apiKey: process.env.INFERENCE_API_KEY });\n\nexport async function generateImage(prompt: string) {\n  const result = await client.run({\n    app: \'infsh/flux-schnell\',\n    input: { prompt }\n  });\n  return result.output;\n}\n\nexport async function chat(message: string, sessionId?: string) {\n  const agent = client.agent(\'my-org/assistant@latest\');\n  const response = await agent.sendMessage(message);\n  return {\n    text: response.text,\n    sessionId: response.sessionId\n  };\n}\n```\n\n```typescript\n// app/page.tsx\nimport { generateImage, chat } from \'./actions\';\n\nexport default function Page() {\n  async function handleSubmit(formData: FormData) {\n    \'use server\';\n    const prompt = formData.get(\'prompt\') as string;\n    const image = await generateImage(prompt);\n    // Handle result\n  }\n\n  return (\n    <form action={handleSubmit}>\n      <input name=\"prompt\" placeholder=\"Describe an image...\" />\n      <button type=\"submit\">Generate</button>\n    </form>\n  );\n}\n```\n','9571831c0eac806c720437d0c51a062c','2026-10-26 11:22:16','2026-10-26 11:22:16','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'text',NULL,''),(3533,'enc.7265666572656e6365732f72656163742d696e746567726174696f6e2e6d64','skill_enc.6a6176617363726970742d73646b__enc.302e302e31','# React Integration Reference\n\nBuild AI-powered React applications with the inference.sh SDK.\n\n## Setup\n\n```bash\nnpm install @inferencesh/sdk\n```\n\nConfigure proxy (keep API keys on server):\n\n```typescript\n// app/api/inference/proxy/route.ts (Next.js)\nimport { createRouteHandler } from \'@inferencesh/sdk/proxy/nextjs\';\n\nconst route = createRouteHandler({\n  apiKey: process.env.INFERENCE_API_KEY!\n});\n\nexport const POST = route.POST;\n```\n\n## Basic Client Setup\n\n```typescript\nimport { inference } from \'@inferencesh/sdk\';\n\n// Create client with proxy (no API key in browser)\nconst client = inference({ proxyUrl: \'/api/inference/proxy\' });\n```\n\n## useInference Hook\n\nCustom hook for running AI apps:\n\n```typescript\nimport { useState, useCallback } from \'react\';\nimport { inference } from \'@inferencesh/sdk\';\n\ninterface UseInferenceState<T> {\n  data: T | null;\n  loading: boolean;\n  error: string | null;\n}\n\nfunction useInference<T = any>() {\n  const [state, setState] = useState<UseInferenceState<T>>({\n    data: null,\n    loading: false,\n    error: null\n  });\n\n  const client = inference({ proxyUrl: \'/api/inference/proxy\' });\n\n  const run = useCallback(async (config: any) => {\n    setState({ data: null, loading: true, error: null });\n\n    try {\n      const result = await client.run(config);\n      setState({ data: result.output as T, loading: false, error: null });\n      return result.output as T;\n    } catch (e: any) {\n      setState({ data: null, loading: false, error: e.message });\n      throw e;\n    }\n  }, []);\n\n  return { ...state, run };\n}\n\n// Usage\nfunction ImageGenerator() {\n  const { data, loading, error, run } = useInference<{ image: string }>();\n\n  const generate = () => run({\n    app: \'infsh/flux-schnell\',\n    input: { prompt: \'A sunset\' }\n  });\n\n  return (\n    <div>\n      <button onClick={generate} disabled={loading}>\n        {loading ? \'Generating...\' : \'Generate\'}\n      </button>\n      {error && <div className=\"error\">{error}</div>}\n      {data && <img src={data.image} alt=\"Generated\" />}\n    </div>\n  );\n}\n```\n\n## useChat Hook\n\nConversational AI with streaming:\n\n```typescript\nimport { useState, useCallback, useRef } from \'react\';\nimport { inference } from \'@inferencesh/sdk\';\n\ninterface Message {\n  role: \'user\' | \'assistant\';\n  content: string;\n}\n\nfunction useChat(agentRef: string) {\n  const [messages, setMessages] = useState<Message[]>([]);\n  const [loading, setLoading] = useState(false);\n  const [streaming, setStreaming] = useState(false);\n\n  const clientRef = useRef(inference({ proxyUrl: \'/api/inference/proxy\' }));\n  const agentRef_ = useRef(clientRef.current.agent(agentRef));\n\n  const sendMessage = useCallback(async (content: string) => {\n    // Add user message\n    setMessages(prev => [...prev, { role: \'user\', content }]);\n    setLoading(true);\n    setStreaming(true);\n\n    // Placeholder for assistant response\n    let assistantContent = \'\';\n    setMessages(prev => [...prev, { role: \'assistant\', content: \'\' }]);\n\n    try {\n      await agentRef_.current.sendMessage(content, {\n        onMessage: (msg) => {\n          if (msg.content) {\n            assistantContent += msg.content;\n            setMessages(prev => [\n              ...prev.slice(0, -1),\n              { role: \'assistant\', content: assistantContent }\n            ]);\n          }\n        }\n      });\n    } finally {\n      setLoading(false);\n      setStreaming(false);\n    }\n  }, []);\n\n  const reset = useCallback(() => {\n    agentRef_.current.reset();\n    setMessages([]);\n  }, []);\n\n  return { messages, loading, streaming, sendMessage, reset };\n}\n\n// Usage\nfunction ChatComponent() {\n  const { messages, loading, sendMessage, reset } = useChat(\'my-org/assistant@latest\');\n  const [input, setInput] = useState(\'\');\n\n  const handleSubmit = (e: React.FormEvent) => {\n    e.preventDefault();\n    if (input.trim()) {\n      sendMessage(input);\n      setInput(\'\');\n    }\n  };\n\n  return (\n    <div className=\"chat\">\n      <div className=\"messages\">\n        {messages.map((msg, i) => (\n          <div key={i} className={`message ${msg.role}`}>\n            {msg.content}\n          </div>\n        ))}\n      </div>\n\n      <form onSubmit={handleSubmit}>\n        <input\n          value={input}\n          onChange={(e) => setInput(e.target.value)}\n          placeholder=\"Type a message...\"\n          disabled={loading}\n        />\n        <button type=\"submit\" disabled={loading}>Send</button>\n      </form>\n\n      <button onClick={reset}>New Chat</button>\n    </div>\n  );\n}\n```\n\n## useStream Hook\n\nStream task progress:\n\n```typescript\nimport { useState, useCallback, useRef } from \'react\';\nimport { inference } from \'@inferencesh/sdk\';\n\ninterface StreamState {\n  status: string;\n  progress: number;\n  logs: string[];\n  output: any;\n  error: string | null;\n}\n\nfunction useStream() {\n  const [state, setState] = useState<StreamState>({\n    status: \'idle\',\n    progress: 0,\n    logs: [],\n    output: null,\n    error: null\n  });\n\n  const controllerRef = useRef<AbortController | null>(null);\n  const client = inference({ proxyUrl: \'/api/inference/proxy\' });\n\n  const run = useCallback(async (config: any) => {\n    controllerRef.current = new AbortController();\n\n    setState({\n      status: \'starting\',\n      progress: 0,\n      logs: [],\n      output: null,\n      error: null\n    });\n\n    try {\n      const stream = await client.run(config, {\n        stream: true,\n        signal: controllerRef.current.signal\n      });\n\n      for await (const update of stream) {\n        setState(prev => ({\n          ...prev,\n          status: update.status,\n          progress: update.progress\n            ? (update.progress.current / update.progress.total) * 100\n            : prev.progress,\n          logs: update.logs ? [...prev.logs, ...update.logs] : prev.logs,\n          output: update.output || prev.output\n        }));\n      }\n    } catch (e: any) {\n      if (e.name !== \'AbortError\') {\n        setState(prev => ({ ...prev, status: \'error\', error: e.message }));\n      }\n    }\n  }, []);\n\n  const cancel = useCallback(() => {\n    controllerRef.current?.abort();\n    setState(prev => ({ ...prev, status: \'cancelled\' }));\n  }, []);\n\n  return { ...state, run, cancel };\n}\n\n// Usage\nfunction VideoGenerator() {\n  const { status, progress, logs, output, run, cancel } = useStream();\n\n  return (\n    <div>\n      <button onClick={() => run({\n        app: \'google/veo-3-1-fast\',\n        input: { prompt: \'Ocean waves\' }\n      })}>\n        Generate Video\n      </button>\n      <button onClick={cancel}>Cancel</button>\n\n      <div>Status: {status}</div>\n      <progress value={progress} max={100} />\n\n      <div className=\"logs\">\n        {logs.map((log, i) => <div key={i}>{log}</div>)}\n      </div>\n\n      {output && <video src={output.video} controls />}\n    </div>\n  );\n}\n```\n\n## File Upload Component\n\n```typescript\nimport { useState, useCallback } from \'react\';\nimport { inference } from \'@inferencesh/sdk\';\n\nfunction FileUpload({ onUpload }: { onUpload: (uri: string) => void }) {\n  const [uploading, setUploading] = useState(false);\n  const [preview, setPreview] = useState<string | null>(null);\n\n  const client = inference({ proxyUrl: \'/api/inference/proxy\' });\n\n  const handleFile = useCallback(async (e: React.ChangeEvent<HTMLInputElement>) => {\n    const file = e.target.files?.[0];\n    if (!file) return;\n\n    // Show preview\n    const reader = new FileReader();\n    reader.onload = () => setPreview(reader.result as string);\n    reader.readAsDataURL(file);\n\n    // Upload\n    setUploading(true);\n    try {\n      const uploaded = await client.uploadFile(file);\n      onUpload(uploaded.uri);\n    } finally {\n      setUploading(false);\n    }\n  }, [onUpload]);\n\n  return (\n    <div>\n      <input type=\"file\" onChange={handleFile} disabled={uploading} />\n      {uploading && <span>Uploading...</span>}\n      {preview && <img src={preview} alt=\"Preview\" style={{ maxWidth: 200 }} />}\n    </div>\n  );\n}\n```\n\n## Image Analysis Component\n\n```typescript\nfunction ImageAnalyzer() {\n  const [imageUri, setImageUri] = useState<string | null>(null);\n  const { messages, sendMessage, loading } = useChat(\'my-org/vision-assistant@latest\');\n\n  const handleUpload = (uri: string) => {\n    setImageUri(uri);\n  };\n\n  const analyze = () => {\n    if (imageUri) {\n      sendMessage(`Analyze this image: ${imageUri}`);\n    }\n  };\n\n  return (\n    <div>\n      <FileUpload onUpload={handleUpload} />\n\n      <button onClick={analyze} disabled={!imageUri || loading}>\n        Analyze Image\n      </button>\n\n      <div className=\"messages\">\n        {messages.map((msg, i) => (\n          <div key={i} className={msg.role}>{msg.content}</div>\n        ))}\n      </div>\n    </div>\n  );\n}\n```\n\n## Tool Handling Component\n\n```typescript\nimport { useState, useCallback } from \'react\';\nimport { inference, tool, string } from \'@inferencesh/sdk\';\n\nfunction AgentWithTools() {\n  const [response, setResponse] = useState(\'\');\n  const [pendingTool, setPendingTool] = useState<any>(null);\n\n  const client = inference({ proxyUrl: \'/api/inference/proxy\' });\n\n  const confirmTool = tool(\'confirm_action\')\n    .describe(\'Confirm a destructive action\')\n    .param(\'action\', string(\'Action to confirm\'))\n    .requireApproval()\n    .build();\n\n  const agent = client.agent({\n    core_app: { ref: \'infsh/claude-sonnet-4@latest\' },\n    tools: [confirmTool]\n  });\n\n  const handleMessage = useCallback(async (message: string) => {\n    setResponse(\'\');\n\n    await agent.sendMessage(message, {\n      onMessage: (msg) => {\n        if (msg.content) {\n          setResponse(prev => prev + msg.content);\n        }\n      },\n      onToolCall: (call) => {\n        if (call.requiresApproval) {\n          setPendingTool(call);\n        }\n      }\n    });\n  }, []);\n\n  const handleApprove = (approved: boolean) => {\n    if (pendingTool) {\n      if (approved) {\n        agent.submitToolResult(pendingTool.id, { confirmed: true });\n      } else {\n        agent.submitToolResult(pendingTool.id, { error: \'Denied by user\' });\n      }\n      setPendingTool(null);\n    }\n  };\n\n  return (\n    <div>\n      <button onClick={() => handleMessage(\'Delete all temp files\')}>\n        Run Agent\n      </button>\n\n      <div>{response}</div>\n\n      {pendingTool && (\n        <div className=\"approval-dialog\">\n          <p>Agent wants to: {pendingTool.args.action}</p>\n          <button onClick={() => handleApprove(true)}>Approve</button>\n          <button onClick={() => handleApprove(false)}>Deny</button>\n        </div>\n      )}\n    </div>\n  );\n}\n```\n\n## Context Provider\n\nShare client across components:\n\n```typescript\nimport { createContext, useContext, useMemo, ReactNode } from \'react\';\nimport { inference, type InferenceClient } from \'@inferencesh/sdk\';\n\nconst InferenceContext = createContext<InferenceClient | null>(null);\n\nexport function InferenceProvider({ children }: { children: ReactNode }) {\n  const client = useMemo(() =>\n    inference({ proxyUrl: \'/api/inference/proxy\' }),\n    []\n  );\n\n  return (\n    <InferenceContext.Provider value={client}>\n      {children}\n    </InferenceContext.Provider>\n  );\n}\n\nexport function useInferenceClient() {\n  const client = useContext(InferenceContext);\n  if (!client) {\n    throw new Error(\'useInferenceClient must be used within InferenceProvider\');\n  }\n  return client;\n}\n\n// Usage in app\nfunction App() {\n  return (\n    <InferenceProvider>\n      <ChatComponent />\n      <ImageGenerator />\n    </InferenceProvider>\n  );\n}\n\n// Usage in component\nfunction MyComponent() {\n  const client = useInferenceClient();\n  // Use client...\n}\n```\n\n## Suspense Integration\n\n```typescript\nimport { Suspense } from \'react\';\nimport { use } from \'react\';\nimport { inference } from \'@inferencesh/sdk\';\n\nconst client = inference({ proxyUrl: \'/api/inference/proxy\' });\n\n// Create a promise for the resource\nfunction createImageResource(prompt: string) {\n  const promise = client.run({\n    app: \'infsh/flux-schnell\',\n    input: { prompt }\n  }).then(r => r.output.image);\n\n  return { read: () => use(promise) };\n}\n\nfunction GeneratedImage({ resource }: { resource: ReturnType<typeof createImageResource> }) {\n  const imageUrl = resource.read();\n  return <img src={imageUrl} alt=\"Generated\" />;\n}\n\nfunction App() {\n  const [resource, setResource] = useState<any>(null);\n\n  const generate = () => {\n    setResource(createImageResource(\'A sunset\'));\n  };\n\n  return (\n    <div>\n      <button onClick={generate}>Generate</button>\n      {resource && (\n        <Suspense fallback={<div>Generating...</div>}>\n          <GeneratedImage resource={resource} />\n        </Suspense>\n      )}\n    </div>\n  );\n}\n```\n\n## Error Boundary\n\n```typescript\nimport { Component, ReactNode } from \'react\';\n\ninterface Props {\n  children: ReactNode;\n  fallback?: ReactNode;\n}\n\ninterface State {\n  hasError: boolean;\n  error: Error | null;\n}\n\nclass InferenceErrorBoundary extends Component<Props, State> {\n  state: State = { hasError: false, error: null };\n\n  static getDerivedStateFromError(error: Error): State {\n    return { hasError: true, error };\n  }\n\n  render() {\n    if (this.state.hasError) {\n      return this.props.fallback || (\n        <div className=\"error\">\n          <h2>Something went wrong</h2>\n          <p>{this.state.error?.message}</p>\n          <button onClick={() => this.setState({ hasError: false, error: null })}>\n            Try again\n          </button>\n        </div>\n      );\n    }\n\n    return this.props.children;\n  }\n}\n\n// Usage\nfunction App() {\n  return (\n    <InferenceErrorBoundary>\n      <AIFeatures />\n    </InferenceErrorBoundary>\n  );\n}\n```\n','ce7de67327c8cf4a399a9f8139fc5c13','2026-10-26 11:22:16','2026-10-26 11:22:16','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(3534,'enc.7265666572656e6365732f6167656e742d7061747465726e732e6d64','skill_enc.6a6176617363726970742d73646b__enc.302e302e31','# Agent Patterns\n\nCommon patterns for building agents with the JavaScript SDK.\n\n## Multi-Agent Orchestration\n\nDelegate tasks to specialized sub-agents:\n\n```typescript\nimport { inference, agentTool, string } from \'@inferencesh/sdk\';\n\nconst client = inference({ apiKey: \'inf_...\' });\n\n// Define sub-agents as tools\nconst researcher = agentTool(\'research\', \'my-org/researcher@latest\')\n  .describe(\'Research a topic thoroughly\')\n  .param(\'topic\', string(\'Topic to research\'))\n  .build();\n\nconst writer = agentTool(\'write\', \'my-org/writer@latest\')\n  .describe(\'Write content based on research\')\n  .param(\'outline\', string(\'Content outline\'))\n  .param(\'research\', string(\'Research findings\'))\n  .build();\n\n// Orchestrator agent\nconst orchestrator = client.agent({\n  core_app: { ref: \'infsh/claude-sonnet-4@latest\' },\n  system_prompt: `You are an orchestrator that:\n1. Uses the research tool to gather information\n2. Uses the write tool to create content\nCoordinate between agents to produce high-quality output.`,\n  tools: [researcher, writer]\n});\n\nconst response = await orchestrator.sendMessage(\'Create a blog post about AI agents\');\n```\n\n## RAG Pattern (Retrieval-Augmented Generation)\n\nCombine search with LLM responses:\n\n```typescript\nimport { inference, appTool, string } from \'@inferencesh/sdk\';\n\nconst client = inference({ apiKey: \'inf_...\' });\n\n// Search tool\nconst search = appTool(\'search\', \'tavily/search-assistant@latest\')\n  .describe(\'Search the web for current information\')\n  .param(\'query\', string(\'Search query\'))\n  .build();\n\n// RAG agent\nconst ragAgent = client.agent({\n  core_app: { ref: \'infsh/claude-sonnet-4@latest\' },\n  system_prompt: `You help users with current information.\nWhen asked about recent events or facts you\'re unsure about,\nuse the search tool to find accurate, up-to-date information.\nAlways cite your sources.`,\n  tools: [search]\n});\n\nconst response = await ragAgent.sendMessage(\n  \'What are the latest developments in quantum computing?\'\n);\n```\n\n## Code Execution Pattern\n\nAgents that can write and run code:\n\n```typescript\nimport { inference, internalTools } from \'@inferencesh/sdk\';\n\nconst client = inference({ apiKey: \'inf_...\' });\n\nconst config = internalTools()\n  .codeExecution(true)\n  .build();\n\nconst coder = client.agent({\n  core_app: { ref: \'infsh/claude-sonnet-4@latest\' },\n  system_prompt: `You are a coding assistant.\nWrite code to solve problems and execute it to verify it works.\nExplain your approach and show the output.`,\n  internal_tools: config\n});\n\nconst response = await coder.sendMessage(\'Calculate the first 20 Fibonacci numbers\');\n```\n\n## Human-in-the-Loop Pattern\n\nRequire approval for sensitive operations:\n\n```typescript\nimport { inference, tool, string } from \'@inferencesh/sdk\';\nimport * as readline from \'readline\';\n\nconst client = inference({ apiKey: \'inf_...\' });\n\n// Tool requiring approval\nconst deleteFile = tool(\'delete_file\')\n  .describe(\'Delete a file from the filesystem\')\n  .param(\'path\', string(\'File path to delete\'))\n  .requireApproval()\n  .build();\n\nasync function promptUser(question: string): Promise<boolean> {\n  const rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n  });\n\n  return new Promise((resolve) => {\n    rl.question(question, (answer) => {\n      rl.close();\n      resolve(answer.toLowerCase() === \'y\');\n    });\n  });\n}\n\nconst agent = client.agent({\n  core_app: { ref: \'infsh/claude-sonnet-4@latest\' },\n  tools: [deleteFile]\n});\n\nconst response = await agent.sendMessage(\'Clean up temporary files in /tmp/myapp\', {\n  onToolCall: async (call) => {\n    if (call.requiresApproval) {\n      console.log(`\\n⚠️  Agent wants to: ${call.name}`);\n      console.log(`   Arguments: ${JSON.stringify(call.args)}`);\n      const approved = await promptUser(\'Allow? (y/n): \');\n\n      if (approved) {\n        const result = await executeOperation(call.name, call.args);\n        agent.submitToolResult(call.id, result);\n      } else {\n        agent.submitToolResult(call.id, { error: \'Operation denied by user\' });\n      }\n    }\n  }\n});\n```\n\n## Conversation Memory Pattern\n\nMaintain context across sessions:\n\n```typescript\nimport { inference } from \'@inferencesh/sdk\';\nimport { readFileSync, writeFileSync, existsSync } from \'fs\';\n\nconst client = inference({ apiKey: \'inf_...\' });\n\nfunction saveChat(agent: any, filepath: string) {\n  const chat = agent.getChat();\n  writeFileSync(filepath, JSON.stringify(chat, null, 2));\n}\n\nasync function loadAndContinue(filepath: string) {\n  const agent = client.agent(\'my-org/assistant@latest\');\n\n  if (existsSync(filepath)) {\n    const chat = JSON.parse(readFileSync(filepath, \'utf-8\'));\n    // Restore by replaying user messages\n    for (const msg of chat.messages) {\n      if (msg.role === \'user\') {\n        await agent.sendMessage(msg.content);\n      }\n    }\n  }\n\n  return agent;\n}\n\n// Usage\nconst agent = await loadAndContinue(\'conversation.json\');\nconst response = await agent.sendMessage(\'Continue where we left off\');\nsaveChat(agent, \'conversation.json\');\n```\n\n## Streaming with Progress UI\n\nReal-time updates for better UX:\n\n```typescript\nimport { inference } from \'@inferencesh/sdk\';\n\nconst client = inference({ apiKey: \'inf_...\' });\nconst agent = client.agent(\'my-org/assistant@latest\');\n\nconst response = await agent.sendMessage(\'Generate a report on market trends\', {\n  onMessage: (msg) => {\n    if (msg.content) {\n      process.stdout.write(msg.content);\n    }\n  },\n  onToolCall: async (call) => {\n    console.log(`\\n🔧 Using tool: ${call.name}`);\n    const result = await executeTool(call.name, call.args);\n    agent.submitToolResult(call.id, result);\n    console.log(\'✅ Tool completed\');\n  }\n});\n\nconsole.log(\'\\n\\n📊 Report complete!\');\n```\n\n## React Integration Pattern\n\nUse in React components:\n\n```typescript\nimport { useState, useCallback } from \'react\';\nimport { inference } from \'@inferencesh/sdk\';\n\nconst client = inference({ proxyUrl: \'/api/inference/proxy\' });\n\nfunction ChatComponent() {\n  const [messages, setMessages] = useState<string[]>([]);\n  const [input, setInput] = useState(\'\');\n  const [agent] = useState(() => client.agent(\'my-org/assistant@latest\'));\n\n  const sendMessage = useCallback(async () => {\n    if (!input.trim()) return;\n\n    setMessages(prev => [...prev, `You: ${input}`]);\n    setInput(\'\');\n\n    let response = \'\';\n    await agent.sendMessage(input, {\n      onMessage: (msg) => {\n        if (msg.content) {\n          response += msg.content;\n          setMessages(prev => [\n            ...prev.slice(0, -1),\n            `Assistant: ${response}`\n          ]);\n        }\n      }\n    });\n  }, [input, agent]);\n\n  return (\n    <div>\n      {messages.map((msg, i) => <div key={i}>{msg}</div>)}\n      <input value={input} onChange={e => setInput(e.target.value)} />\n      <button onClick={sendMessage}>Send</button>\n    </div>\n  );\n}\n```\n\n## Error Recovery Pattern\n\nGraceful handling of failures:\n\n```typescript\nimport { inference, RequirementsNotMetException, InferenceError } from \'@inferencesh/sdk\';\n\nconst client = inference({ apiKey: \'inf_...\' });\n\nasync function robustRun(config: any, maxRetries = 3) {\n  for (let attempt = 0; attempt < maxRetries; attempt++) {\n    try {\n      return await client.run(config);\n    } catch (e) {\n      if (e instanceof RequirementsNotMetException) {\n        console.log(\'Missing requirements:\', e.errors);\n        throw e;\n      }\n      if (e instanceof InferenceError && attempt < maxRetries - 1) {\n        const wait = Math.pow(2, attempt) * 1000;\n        console.log(`Error: ${e.message}. Retrying in ${wait}ms...`);\n        await new Promise(r => setTimeout(r, wait));\n      } else {\n        throw e;\n      }\n    }\n  }\n}\n\nconst result = await robustRun({\n  app: \'infsh/flux-schnell\',\n  input: { prompt: \'A serene landscape\' }\n});\n```\n\n## Batch Processing Pattern\n\nProcess multiple items efficiently:\n\n```typescript\nimport { inference } from \'@inferencesh/sdk\';\n\nconst client = inference({ apiKey: \'inf_...\' });\n\nasync function processBatch(items: string[], concurrency = 5) {\n  const results: any[] = [];\n  const queue = [...items];\n  const inProgress: Promise<void>[] = [];\n\n  async function processOne(item: string) {\n    const result = await client.run({\n      app: \'infsh/flux-schnell\',\n      input: { prompt: item }\n    });\n    results.push(result);\n  }\n\n  while (queue.length > 0 || inProgress.length > 0) {\n    // Fill up to concurrency limit\n    while (queue.length > 0 && inProgress.length < concurrency) {\n      const item = queue.shift()!;\n      const promise = processOne(item).then(() => {\n        const index = inProgress.indexOf(promise);\n        if (index > -1) inProgress.splice(index, 1);\n      });\n      inProgress.push(promise);\n    }\n\n    // Wait for at least one to complete\n    if (inProgress.length > 0) {\n      await Promise.race(inProgress);\n    }\n  }\n\n  return results;\n}\n\nconst prompts = [\n  \'A mountain sunrise\',\n  \'A city at night\',\n  \'An ocean sunset\',\n  \'A forest path\'\n];\n\nconst results = await processBatch(prompts);\n```\n\n## Next.js Server Actions Pattern\n\nUse with React Server Components:\n\n```typescript\n// app/actions.ts\n\'use server\';\n\nimport { inference } from \'@inferencesh/sdk\';\n\nconst client = inference({ apiKey: process.env.INFERENCE_API_KEY });\n\nexport async function generateImage(prompt: string) {\n  const result = await client.run({\n    app: \'infsh/flux-schnell\',\n    input: { prompt }\n  });\n  return result.output;\n}\n\nexport async function chat(message: string, sessionId?: string) {\n  const agent = client.agent(\'my-org/assistant@latest\');\n  const response = await agent.sendMessage(message);\n  return {\n    text: response.text,\n    sessionId: response.sessionId\n  };\n}\n```\n\n```typescript\n// app/page.tsx\nimport { generateImage, chat } from \'./actions\';\n\nexport default function Page() {\n  async function handleSubmit(formData: FormData) {\n    \'use server\';\n    const prompt = formData.get(\'prompt\') as string;\n    const image = await generateImage(prompt);\n    // Handle result\n  }\n\n  return (\n    <form action={handleSubmit}>\n      <input name=\"prompt\" placeholder=\"Describe an image...\" />\n      <button type=\"submit\">Generate</button>\n    </form>\n  );\n}\n```\n','9571831c0eac806c720437d0c51a062c','2026-10-26 11:22:16','2026-10-26 11:22:16','nacos',NULL,'','public',NULL,NULL,NULL,'text',NULL,''),(3535,'resource_config_SOUL__md.json','agentspec__enc.737570706c792d636861696e2d76656e646f722d6576616c7561746f72__enc.302e302e31','{\"name\":\"SOUL.md\",\"type\":\"config\",\"content\":\"## 身份与角色\\n\\n- **角色**：供应商评估与采购决策策略专家\\n- **个性**：严谨细致、原则性强、注重长期关系、善于在成本与质量之间找平衡\\n- **记忆**：你记住每一次因供应商跑路导致的断供危机，每一个验厂时发现的致命隐患，每一次通过谈判省下的真金白银\\n- **经验**：你见过太多企业因为\\\"图便宜\\\"选了不靠谱的供应商，结果批次质量波动、交期延误、售后扯皮。你深知好的供应商不是找来的，而是评出来、管出来、养出来的\\n\\n## 沟通风格\\n\\n- **数据说话**：\\\"这家供应商的准时交货率只有85%，低于我们92%的基线要求。过去三个月延迟了5次，其中3次影响了我们的发货时效，必须发整改函\\\"\\n- **原则坚定**：\\\"价格可以谈，但质量标准不能降。如果用回收料替代新料降成本，来料合格率风险太大，我们不接受\\\"\\n- **长期视角**：\\\"这家工厂虽然现在产能不大，但设备新、管理规范、老板有投入意愿。建议先给B级，用小单培养，明年有机会升A级\\\"\\n- **风险预警**：\\\"这个供应商最近工商信息变更了法人，而且有一条环保处罚记录。建议暂停新订单，先去实地核实情况\\\"\\n\\n\",\"metadata\":{\"uniformId\":1792984935240},\"resourceIdentifier\":\"config::SOUL.md\"}','65c9d6b4e6929a82ab5cf5cd6447d083','2026-10-26 11:22:16','2026-10-26 11:22:16','nacos_namespace_migrate',NULL,'','',NULL,NULL,NULL,'json',NULL,''),(3536,'resource_config_SOUL__md.json','agentspec__enc.737570706c792d636861696e2d76656e646f722d6576616c7561746f72__enc.302e302e31','{\"name\":\"SOUL.md\",\"type\":\"config\",\"content\":\"## 身份与角色\\n\\n- **角色**：供应商评估与采购决策策略专家\\n- **个性**：严谨细致、原则性强、注重长期关系、善于在成本与质量之间找平衡\\n- **记忆**：你记住每一次因供应商跑路导致的断供危机，每一个验厂时发现的致命隐患，每一次通过谈判省下的真金白银\\n- **经验**：你见过太多企业因为\\\"图便宜\\\"选了不靠谱的供应商，结果批次质量波动、交期延误、售后扯皮。你深知好的供应商不是找来的，而是评出来、管出来、养出来的\\n\\n## 沟通风格\\n\\n- **数据说话**：\\\"这家供应商的准时交货率只有85%，低于我们92%的基线要求。过去三个月延迟了5次，其中3次影响了我们的发货时效，必须发整改函\\\"\\n- **原则坚定**：\\\"价格